    public MainWindow()
    {
        RunStartupPhase("MainWindow.InitializeComponent", InitializeComponent);
        ApplyRuntimeProfile();
        RunStartupPhase("Workspace tab ordering", ApplyWorkspaceTabPriorityOrder);
        RunStartupPhase("Website template manager", RefreshWebsiteTemplateManager);
        _nativeMaterialSearchDebounceTimer.Tick += NativeMaterialSearchDebounceTimer_Tick;
        _nativeMaterialEditDebounceTimer.Tick += NativeMaterialEditDebounceTimer_Tick;
        _workflowLayoutSaveDebounceTimer.Tick += WorkflowLayoutSaveDebounceTimer_Tick;
        _transientStatusTimer.Tick += (_, _) =>
        {
            _transientStatusTimer.Stop();
            StatusText.Text = "Ready.";
        };
        Loaded += MainWindow_Loaded;
        Closing += MainWindow_Closing;
        RunStartupPhase("Analytics controls", InitializeAnalyticsControls);
        RunStartupPhase("Saved video ideas", LoadSavedVideoIdeas);
        RunStartupPhase("AI Assistant workspace", InitializeAiAssistantWorkspace);
        RunStartupPhase("AI provider foundation", InitializeAiProviderFoundation);
        RunStartupPhase("Native settings initialization", InitializeNativeSettingsManager);
        RunStartupPhase("Printer workspace initialization", InitializePrinterManager);
        RunStartupPhase("Native Materials initialization", InitializeNativeMaterialManager);
        RunStartupPhase("Print Job Quote workspace initialization", InitializePrintJobQuoteWorkspace);
        RunStartupPhase("Fast Materials default view", ActivateDefaultFastMaterialsView);
        RunStartupPhase("Manufacturer workspace initialization", InitializeManufacturerManager);
        RunStartupPhase("Inventory workspace initialization", InitializeInventorySpoolManager);
        RunStartupPhase("Usage workspace initialization", InitializeUsageWorkspace);
        RunStartupPhase("Experimental workspace initialization", InitializeExperimentalMaterialManager);
        RunStartupPhase("Purchasing workspace initialization", InitializePurchaseOrderManager);
        RunStartupPhase("Tensile workspace initialization", InitializeNativeTensileMeasurements);
        RunStartupPhase("Fast Tensile candidate view", ActivateDefaultFastTensileView);
        RunStartupPhase("Impact workspace initialization", InitializeNativeImpactMeasurements);
        RunStartupPhase("Fast Impact candidate view", ActivateDefaultFastImpactView);
        RunStartupPhase("Stiffness workspace initialization", InitializeNativeStiffnessMeasurements);
        RunStartupPhase("Fast Stiffness candidate view", ActivateDefaultFastStiffnessView);
        UpdateNativeWorkflowStatus("Auto-save ready");
        RunStartupPhase("Application statistics refresh", RefreshApplicationStatistics);
        App.StartupPerformance.Mark("MainWindow constructor completed");
    }

    private void ApplyRuntimeProfile()
    {
        var runtimeProfile = RuntimeProfileContext.Current;
        RuntimeProfileIdentityText.Text = runtimeProfile.VisibleIdentity;
        RuntimeProfileIdentityText.Foreground = runtimeProfile.Kind switch
        {
            RuntimeProfileKind.CleanReadiness => new SolidColorBrush(Color.FromRgb(125, 211, 252)),
            RuntimeProfileKind.DisposableVerification => new SolidColorBrush(Color.FromRgb(251, 191, 36)),
            _ => new SolidColorBrush(Color.FromRgb(134, 239, 172))
        };
        AutomationProperties.SetHelpText(RuntimeProfileIdentityText, runtimeProfile.CapabilitySummary);
        if (!AutomationRuntimeProfile.IsActive) return;
        Title += " — " + runtimeProfile.VisibleIdentity;
        ReportOutputFolderBox.Text = AutomationRuntimeProfile.Current!.OutputFolder;
        ReportOutputFolderBox.IsReadOnly = true;
        AutomationCrudPanel.Visibility = AutomationRuntimeProfile.Current.MaterialCrudAuthorized
            ? Visibility.Visible
            : Visibility.Collapsed;
        AutomationRecoveryPanel.Visibility = AutomationRuntimeProfile.Current.RecoveryAuthorized
            ? Visibility.Visible
            : Visibility.Collapsed;
        AutomationLandedCostPanel.Visibility = AutomationRuntimeProfile.Current.LandedCostWorkflowAuthorized
            ? Visibility.Visible
            : Visibility.Collapsed;
    }

    private bool IsAutomationActionBlocked(string action)
    {
        if (!AutomationRuntimeProfile.IsActive) return false;
        StatusText.Text = $"{action} — BLOCKED BY AUTOMATION SAFETY POLICY";
        return true;
    }

    private NativeMaterialRow? GetAuthorizedAutomationMaterial()
    {
        var materialId = AutomationRuntimeProfile.Current?.MaterialCrudId ?? string.Empty;
        AutomationRuntimeProfile.DemandMaterialCrudAuthorized(materialId);
        return _nativeMaterialRows.FirstOrDefault(row =>
            string.Equals(row.MaterialID, materialId, StringComparison.Ordinal));
    }

    private void SetAutomationCrudStatus(string status)
    {
        AutomationCrudStatusText.Text = status;
        AutomationProperties.SetName(AutomationCrudStatusText, status);
    }

    private void AutomationCrudCreate_Click(object sender, RoutedEventArgs e)
    {
        var materialId = AutomationRuntimeProfile.Current?.MaterialCrudId ?? string.Empty;
        AutomationRuntimeProfile.DemandMaterialCrudAuthorized(materialId);
        if (GetAuthorizedAutomationMaterial() is not null)
            throw new InvalidOperationException($"Authorized disposable MaterialID already exists: {materialId}");

        var row = new NativeMaterialRow
        {
            MaterialID = materialId,
            Manufacturer = "3DPIceland Automation Legacy",
            ProductLine = "Disposable CRUD",
            MarketingName = "Created",
            BaseMaterial = "Automation Base " + materialId,
            MaterialCategory = "Automation",
            DiameterMm = "1.75",
            SpoolWeightG = "1000",
            MsrpCurrency = "ISK",
            LandedCostCurrency = "ISK",
            Video = "No",
            TestedStatus = "Not tested",
            InTensile = "No",
            InImpact = "No",
            InStiffness = "No",
            SourcePriority = "Automation disposable",
            Notes = "AUTOMATION-CRUD-CREATED"
        };
        ApplyNativeMaterialComputedFields(row, _nativeMaterialRows.Count);
        _nativeMaterialRows.Add(row);
        var automationBaseMaterialName = "Automation Base " + materialId;
        if (_nativeBaseMaterialRows.Any(item =>
                string.Equals(item.BaseMaterial, automationBaseMaterialName, StringComparison.Ordinal)))
            throw new InvalidOperationException("Authorized disposable Base Material already exists.");
        _nativeBaseMaterialRows.Add(new NativeBaseMaterialRow
        {
            BaseMaterial = automationBaseMaterialName,
            Category = "Automation",
            SortOrder = "9998",
            NozzleTemperatureRecommendedC = "205",
            ProfileId = "AUTOMATION-BASE-CREATED"
        });
        SaveBaseMaterialCatalogToDatabase();
        var automationPrinterId = "AUT-PRN-" + materialId;
        if (_printerRows.Any(item => item.PrinterId == automationPrinterId))
            throw new InvalidOperationException("Authorized disposable PrinterID already exists.");
        _printerRows.Add(new PrinterProfileRecord
        {
            PrinterId = automationPrinterId,
            Name = "Automation Printer " + materialId,
            Manufacturer = "3DPIceland Automation",
            Model = "Created",
            CostCurrency = "ISK",
            PurchaseCostAmount = "300000",
            AnnualMaintenanceAmount = "10000",
            EstimatedLifeYears = "2",
            UptimePercent = "50",
            AveragePowerWatts = "150",
            Notes = "AUTOMATION-PRINTER-CREATED"
        });
        SavePrinters();
        RequireAutomationCrudSave("CREATED");
        _database.InsertPrintJobQuote(new PrintJobQuoteRecord
        {
            QuoteId = "AUT-Q-" + materialId,
            QuoteNumber = "AUT-" + materialId,
            CreatedAtUtc = DateTimeOffset.UtcNow.ToString(
                "O", CultureInfo.InvariantCulture),
            PreparedBy = "Automation",
            CustomerName = "Disposable",
            Description = "AUTOMATION-QUOTE-CREATED",
            MaterialId = materialId,
            MaterialLabelSnapshot = materialId + " Created",
            MaterialCostProvenance =
                "Canonical MaterialID LandedCostUsdPerKg",
            PrinterId = automationPrinterId,
            PrinterLabelSnapshot = "Automation Printer " + materialId,
            QuoteCurrency = "ISK",
            FinalPriceQuoteCurrency = "1000.00",
            FinalPriceIsk = "1000.00",
            CalculationVersion = "v1",
            SnapshotJson =
                "{\"schema\":\"3dpiceland-print-job-quote-v1\",\"automation\":\"created\"}"
        });
        CreateAuthorizedAutomationUsageEvent(row.MaterialID);
    }

    private void AutomationCrudEdit_Click(object sender, RoutedEventArgs e)
    {
        var row = GetAuthorizedAutomationMaterial()
                  ?? throw new InvalidOperationException("Authorized disposable MaterialID was not persisted after create.");
        if (!string.Equals(row.Notes, "AUTOMATION-CRUD-CREATED", StringComparison.Ordinal))
            throw new InvalidOperationException("Authorized disposable MaterialID has unexpected pre-edit content.");
        if (!string.Equals(row.Manufacturer, "3DPIceland Automation Legacy", StringComparison.Ordinal))
            throw new InvalidOperationException("Unmapped Manufacturer text was not preserved through create/restart.");
        if (!_fastManufacturerChoices.Contains(row.Manufacturer, StringComparer.Ordinal))
            throw new InvalidOperationException("Current unmapped Manufacturer is missing from the dropdown choices.");
        var automationBaseMaterialName = "Automation Base " + row.MaterialID;
        var automationBaseMaterial = _nativeBaseMaterialRows.SingleOrDefault(item =>
            string.Equals(item.BaseMaterial, automationBaseMaterialName, StringComparison.Ordinal))
            ?? throw new InvalidOperationException("Disposable Base Material was not persisted through restart.");
        var automationBaseMaterialCopyName = automationBaseMaterialName + " Copy";
        var automationPrinterId = "AUT-PRN-" + row.MaterialID;
        var automationPrinter = _printerRows.SingleOrDefault(item =>
            item.PrinterId == automationPrinterId)
            ?? throw new InvalidOperationException(
                "Disposable Printer profile was not persisted through restart.");
        if (!string.Equals(automationPrinter.Notes, "AUTOMATION-PRINTER-CREATED",
                StringComparison.Ordinal))
            throw new InvalidOperationException(
                "Disposable Printer profile has unexpected pre-edit content.");
        automationPrinter.Model = "Edited";
        automationPrinter.UptimePercent = "60";
        automationPrinter.Notes = "AUTOMATION-PRINTER-EDITED";
        SavePrinters();
        var automationQuoteId = "AUT-Q-" + row.MaterialID;
        var automationQuote = _database.LoadPrintJobQuotes().SingleOrDefault(item =>
            item.QuoteId == automationQuoteId)
            ?? throw new InvalidOperationException(
                "Disposable immutable Quote was not persisted through restart.");
        if (!automationQuote.SnapshotJson.Contains(
                "\"automation\":\"created\"", StringComparison.Ordinal))
            throw new InvalidOperationException(
                "Disposable immutable Quote snapshot changed after restart.");
        var duplicateQuoteBlocked = false;
        try
        {
            _database.InsertPrintJobQuote(automationQuote);
        }
        catch (Microsoft.Data.Sqlite.SqliteException)
        {
            duplicateQuoteBlocked = true;
        }
        if (!duplicateQuoteBlocked)
            throw new InvalidOperationException(
                "Immutable Quote identity unexpectedly allowed replacement.");
        _nativeBaseMaterialRows.Add(new NativeBaseMaterialRow
        {
            BaseMaterial = automationBaseMaterialCopyName,
            Category = automationBaseMaterial.Category,
            SortOrder = "9999",
            NozzleTemperatureRecommendedC = "210",
            ProfileId = "AUTOMATION-BASE-DUPLICATED"
        });
        automationBaseMaterial.Category = "Automation edited";
        automationBaseMaterial.ProfileId = "AUTOMATION-BASE-EDITED";
        SaveBaseMaterialCatalogToDatabase();
        row.BaseMaterialId = automationBaseMaterial.BaseMaterialId;
        row.BaseMaterial = automationBaseMaterial.BaseMaterial;
        var originalManufacturerSequence = _database.LoadManufacturerSequenceForAuthorizedAutomation();
        var canonicalManufacturer = new ManufacturerRecord
        {
            Name = "3DPIceland Automation Manufacturer " + row.MaterialID,
            DisplayName = "3DPIceland Automation Manufacturer",
            Notes = "AUTOMATION-ORIGINAL-SEQUENCE:" +
                    (originalManufacturerSequence?.ToString(CultureInfo.InvariantCulture) ?? "NULL"),
            SortOrder = int.MaxValue
        };
        _database.SaveManufacturer(canonicalManufacturer);
        AttachManufacturerAutoSave(canonicalManufacturer);
        _manufacturerRows.Add(canonicalManufacturer);
        _persistedManufacturerNames[canonicalManufacturer.ManufacturerId] = canonicalManufacturer.Name;
        row.Manufacturer = canonicalManufacturer.Name;
        row.ManufacturerId = canonicalManufacturer.ManufacturerId;
        row.MarketingName = "Edited";
        row.Notes = "AUTOMATION-CRUD-EDITED";
        ApplyNativeMaterialComputedFields(row, _nativeMaterialRows.IndexOf(row));
        RequireAutomationCrudSave("EDITED");
        CorrectAuthorizedAutomationUsageEvent(row.MaterialID);
    }

    private void AutomationCrudDelete_Click(object sender, RoutedEventArgs e)
    {
        var row = GetAuthorizedAutomationMaterial()
                  ?? throw new InvalidOperationException("Authorized disposable MaterialID was not persisted after edit.");
        if (!string.Equals(row.Notes, "AUTOMATION-CRUD-EDITED", StringComparison.Ordinal))
            throw new InvalidOperationException("Authorized disposable MaterialID edit was not persisted.");
        if (!_database.LoadManufacturers().Any(item =>
                item.IsActive &&
                item.ManufacturerId == row.ManufacturerId &&
                string.Equals(item.Name, row.Manufacturer, StringComparison.OrdinalIgnoreCase)))
            throw new InvalidOperationException("Canonical Manufacturer selection was not persisted through edit/restart.");
        var automationBaseMaterialName = "Automation Base " + row.MaterialID;
        var automationBaseMaterialCopyName = automationBaseMaterialName + " Copy";
        var automationPrinterId = "AUT-PRN-" + row.MaterialID;
        var automationPrinter = _printerRows.SingleOrDefault(item =>
            item.PrinterId == automationPrinterId)
            ?? throw new InvalidOperationException(
                "Disposable Printer profile was not persisted after edit.");
        if (!string.Equals(automationPrinter.Model, "Edited", StringComparison.Ordinal) ||
            !string.Equals(automationPrinter.UptimePercent, "60", StringComparison.Ordinal) ||
            !string.Equals(automationPrinter.Notes, "AUTOMATION-PRINTER-EDITED",
                StringComparison.Ordinal))
            throw new InvalidOperationException(
                "Disposable Printer edit did not persist through restart.");
        if (!_nativeBaseMaterialRows.Any(item =>
                string.Equals(item.BaseMaterial, automationBaseMaterialName, StringComparison.Ordinal) &&
                string.Equals(item.ProfileId, "AUTOMATION-BASE-EDITED", StringComparison.Ordinal)) ||
            !_nativeBaseMaterialRows.Any(item =>
                string.Equals(item.BaseMaterial, automationBaseMaterialCopyName, StringComparison.Ordinal) &&
                string.Equals(item.ProfileId, "AUTOMATION-BASE-DUPLICATED", StringComparison.Ordinal)))
            throw new InvalidOperationException("Disposable Base Material edit/duplicate did not persist through restart.");
        var canonicalBaseMaterial = _nativeBaseMaterialRows.Single(item =>
            string.Equals(item.BaseMaterial, automationBaseMaterialName, StringComparison.Ordinal));
        if (row.BaseMaterialId != canonicalBaseMaterial.BaseMaterialId)
            throw new InvalidOperationException("Canonical Base Material selection was not persisted through edit/restart.");
        if (_fastManufacturerChoices.Contains("3DPIceland Automation Legacy", StringComparer.Ordinal))
            throw new InvalidOperationException("Removed unmapped Manufacturer remains stale in the dropdown choices.");
        var canonicalManufacturer = _manufacturerRows.Single(item =>
            item.ManufacturerId == row.ManufacturerId);
        var referencedDeleteBlocked = false;
        try
        {
            _database.DeleteManufacturer(canonicalManufacturer.ManufacturerId);
        }
        catch (Microsoft.Data.Sqlite.SqliteException)
        {
            referencedDeleteBlocked = true;
        }
        if (!referencedDeleteBlocked)
            throw new InvalidOperationException("Referenced canonical Manufacturer deletion was not blocked.");
        var originalManufacturerName = canonicalManufacturer.Name;
        var renamedManufacturerName = originalManufacturerName + " Automation Rename";
        RenameManufacturerForAuthorizedAutomation(canonicalManufacturer, renamedManufacturerName);
        if (!string.Equals(row.Manufacturer, renamedManufacturerName, StringComparison.Ordinal) ||
            !_database.LoadNativeMaterialManagerRows().Any(item =>
                item.MaterialID == row.MaterialID &&
                item.ManufacturerId == canonicalManufacturer.ManufacturerId &&
                string.Equals(item.Manufacturer, renamedManufacturerName, StringComparison.Ordinal)))
            throw new InvalidOperationException("Canonical Manufacturer rename did not propagate to the linked Material.");
        RenameManufacturerForAuthorizedAutomation(canonicalManufacturer, originalManufacturerName);
        if (!string.Equals(row.Manufacturer, originalManufacturerName, StringComparison.Ordinal))
            throw new InvalidOperationException("Canonical Manufacturer rename restore did not propagate.");
        var referencedBaseMaterialDeleteBlocked = false;
        try
        {
            _nativeBaseMaterialRows.Remove(canonicalBaseMaterial);
            SaveBaseMaterialCatalogToDatabase();
        }
        catch (Microsoft.Data.Sqlite.SqliteException)
        {
            referencedBaseMaterialDeleteBlocked = true;
            _nativeBaseMaterialRows.Add(canonicalBaseMaterial);
        }
        if (!referencedBaseMaterialDeleteBlocked)
            throw new InvalidOperationException("Referenced canonical Base Material deletion was not blocked.");
        var renamedBaseMaterialName = automationBaseMaterialName + " Automation Rename";
        RenameBaseMaterialForAuthorizedAutomation(canonicalBaseMaterial, renamedBaseMaterialName);
        if (!_database.LoadNativeMaterialManagerRows().Any(item =>
                item.MaterialID == row.MaterialID &&
                item.BaseMaterialId == canonicalBaseMaterial.BaseMaterialId &&
                string.Equals(item.BaseMaterial, renamedBaseMaterialName, StringComparison.Ordinal)) ||
            !_fastBaseMaterialChoices.Contains(renamedBaseMaterialName, StringComparer.Ordinal) ||
            _fastBaseMaterialChoices.Contains(automationBaseMaterialName, StringComparer.Ordinal))
            throw new InvalidOperationException("Canonical Base Material rename did not propagate to the linked Material.");
        RenameBaseMaterialForAuthorizedAutomation(canonicalBaseMaterial, automationBaseMaterialName);
        DeleteAuthorizedAutomationUsageEvents(row.MaterialID);
        _database.DeletePrintJobQuoteForAuthorizedAutomation(
            "AUT-Q-" + row.MaterialID);
        _nativeMaterialRows.Remove(row);
        RequireAutomationCrudSave("DELETED");
        foreach (var baseMaterial in _nativeBaseMaterialRows.Where(item =>
                     string.Equals(item.BaseMaterial, automationBaseMaterialName, StringComparison.Ordinal) ||
                     string.Equals(item.BaseMaterial, automationBaseMaterialCopyName, StringComparison.Ordinal)).ToList())
        {
            if (!_database.DeleteUnreferencedBaseMaterial(baseMaterial.BaseMaterialId))
                throw new InvalidOperationException(
                    $"Authorized bounded Base Material delete failed for {baseMaterial.BaseMaterialId}.");
            if (_database.DeleteUnreferencedBaseMaterial(baseMaterial.BaseMaterialId))
                throw new InvalidOperationException(
                    $"Authorized missing Base Material delete was not a no-op for {baseMaterial.BaseMaterialId}.");
            _nativeBaseMaterialRows.Remove(baseMaterial);
        }
        _printerRows.Remove(automationPrinter);
        SavePrinters();
        var sequenceText = canonicalManufacturer.Notes["AUTOMATION-ORIGINAL-SEQUENCE:".Length..];
        long? originalManufacturerSequence = string.Equals(sequenceText, "NULL", StringComparison.Ordinal)
            ? null
            : long.Parse(sequenceText, CultureInfo.InvariantCulture);
        _database.DeleteManufacturer(canonicalManufacturer.ManufacturerId);
        _database.RestoreManufacturerSequenceForAuthorizedAutomation(originalManufacturerSequence);
        _manufacturerRows.Remove(canonicalManufacturer);
        _persistedManufacturerNames.Remove(canonicalManufacturer.ManufacturerId);
        _manufacturerRenameDraftIds.Remove(canonicalManufacturer.ManufacturerId);
        RefreshFastManufacturerChoices();
        _database.RestoreInventoryOptionalProvenanceForAuthorizedCrudAutomation(
            row.MaterialID);
    }

    private void RenameBaseMaterialForAuthorizedAutomation(
        NativeBaseMaterialRow baseMaterial,
        string newName)
    {
        AutomationRuntimeProfile.DemandMaterialCrudAuthorized(
            AutomationRuntimeProfile.Current?.MaterialCrudId ?? string.Empty);
        var columns = BuildFastBaseMaterialColumns();
        var column = columns.Single(item =>
            string.Equals(
                item.PropertyName,
                nameof(NativeBaseMaterialRow.BaseMaterial),
                StringComparison.Ordinal));
        var row = BuildFastBaseMaterialRows(columns).Single(item =>
            ReferenceEquals(item.Source, baseMaterial));
        var columnIndex = columns.IndexOf(column);
        var oldName = baseMaterial.BaseMaterial;
        if (!ApplyFastBaseMaterialChanges(
                [new MaterialsPrototypeChange(row, column, columnIndex, oldName, newName)]))
            throw new InvalidOperationException("Authorized Base Material rename failed.");
    }

