    private void ApplyWorkspaceTabPriorityOrder()
    {
        MoveWorkspaceTabAfter("Material Detail", "Materials");

        var anchorHeader = "Website Export";
        foreach (var header in new[] { "Manufacturers", "Purchase Orders", "Inventory", "Experimental Testing" })
        {
            MoveWorkspaceTabAfter(header, anchorHeader);
            anchorHeader = header;
        }
    }

    private void MoveWorkspaceTabAfter(string header, string anchorHeader)
    {
        var tab = WorkspaceTabs.Items.OfType<TabItem>()
            .FirstOrDefault(item => string.Equals(item.Header?.ToString(), header, StringComparison.Ordinal));
        var anchor = WorkspaceTabs.Items.OfType<TabItem>()
            .FirstOrDefault(item => string.Equals(item.Header?.ToString(), anchorHeader, StringComparison.Ordinal));
        if (tab is null || anchor is null || ReferenceEquals(tab, anchor)) return;

        WorkspaceTabs.Items.Remove(tab);
        var anchorIndex = WorkspaceTabs.Items.IndexOf(anchor);
        WorkspaceTabs.Items.Insert(anchorIndex + 1, tab);
    }


    private static readonly string[] WorkflowGridNames =
    {
        "ManufacturersGrid",
        "ExperimentalTensileGrid",
        "ExperimentalImpactGrid",
        "ExperimentalStiffnessGrid"
    };

    private void MainWindow_Loaded(object sender, RoutedEventArgs e)
    {
        using var startupPhase = App.StartupPerformance.Measure("MainWindow Loaded workflow");
        _workflowPreferencesService.RestoreWindow(this);
        RestoreWebsiteExportFolderPreference();
        UpdateDashboardInsights();

        foreach (var gridName in WorkflowGridNames)
        {
            if (FindName(gridName) is not DataGrid grid) continue;
            _defaultWorkflowGridLayouts[gridName] = WorkflowPreferencesService.CaptureGridLayout(grid);
            if (_workflowPreferencesService.HasSavedGridWidths(grid))
            {
                _workflowPreferencesService.RestoreGrid(grid);
            }
            else
            {
                ApplySmartWorkflowColumnWidths(grid);
            }

            grid.ClipboardCopyMode = DataGridClipboardCopyMode.ExcludeHeader;

            // Register keyboard handling with handledEventsToo=true. Editing controls such as
            // TextBox and ComboBox can consume Ctrl+C/Ctrl+V before the DataGrid's normal
            // PreviewKeyDown event reaches the workflow handler. A routed handler registered
            // this way consistently receives the shortcuts from both display and edit mode.
            grid.RemoveHandler(Keyboard.PreviewKeyDownEvent, new KeyEventHandler(InputDataGrid_PreviewKeyDown));
            grid.AddHandler(Keyboard.PreviewKeyDownEvent, new KeyEventHandler(InputDataGrid_PreviewKeyDown), true);

            // Restore the proven v37.0.7 first-click workflow. The handler owns a plain
            // left click on an editable cell, closes/commits the previous editor, and
            // activates the requested TextBox or ComboBox at Dispatcher Input priority.
            // Selection remains single-cell; no custom multi-selection path is involved.
            grid.PreviewMouseLeftButtonDown -= WorkflowGrid_PreviewMouseLeftButtonDown;
            grid.PreviewMouseLeftButtonDown += WorkflowGrid_PreviewMouseLeftButtonDown;
            grid.PreviewMouseDoubleClick -= WorkflowGrid_PreviewMouseDoubleClick;
            grid.PreviewMouseDoubleClick += WorkflowGrid_PreviewMouseDoubleClick;
            grid.ContextMenu = CreateWorkflowCellContextMenu(grid);
            grid.ColumnReordered -= WorkflowGrid_ColumnReordered;
            grid.ColumnReordered += WorkflowGrid_ColumnReordered;
            grid.RemoveHandler(Thumb.DragCompletedEvent, new DragCompletedEventHandler(WorkflowGrid_ColumnResizeCompleted));
            grid.AddHandler(Thumb.DragCompletedEvent, new DragCompletedEventHandler(WorkflowGrid_ColumnResizeCompleted), true);

            // Bind clipboard commands directly on the DataGrid as well as handling
            // PreviewKeyDown. WPF editing controls can otherwise consume Ctrl+C/Ctrl+V
            // before a key handler sees a usable cell selection.
            grid.CommandBindings.Add(new CommandBinding(ApplicationCommands.Copy, WorkflowGrid_CopyExecuted, WorkflowGrid_CopyCanExecute));
            grid.CommandBindings.Add(new CommandBinding(ApplicationCommands.Paste, WorkflowGrid_PasteExecuted, WorkflowGrid_PasteCanExecute));
        }

        if (_nativeMaterialIntelligenceRefreshPending || _nativeMaterialRows.Count > 0)
        {
            _nativeMaterialIntelligenceRefreshPending = false;
            QueueNativeMaterialDependentIntelligenceRefresh();
        }

        App.StartupPerformance.Mark("MainWindow Loaded workflow completed");
    }

    private void WorkflowGrid_PreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
    {
        if (sender is not DataGrid grid) return;
        if (e.ChangedButton != MouseButton.Left) return;
        if (e.ClickCount > 1) return; // preserve the dedicated double-click copy command
        if (Keyboard.Modifiers != ModifierKeys.None) return;

        var clickedCell = FindVisualParent<DataGridCell>(e.OriginalSource as DependencyObject);
        if (clickedCell is null) return;

        var targetItem = clickedCell.DataContext;
        var targetColumn = clickedCell.Column;
        var clickPositionInCell = e.GetPosition(clickedCell);
        if (targetItem is null || targetColumn is null) return;

        grid.CurrentCell = new DataGridCellInfo(targetItem, targetColumn);
        if (clickedCell.IsReadOnly || targetColumn.IsReadOnly) return;

        // Own the click so WPF does not spend the first click selecting the cell and the
        // second click entering edit mode. Activation is deferred just enough for the
        // previous ComboBox/TextBox edit to close and commit cleanly.
        e.Handled = true;

        Dispatcher.BeginInvoke(new Action(() =>
        {
            if (!grid.IsLoaded || !grid.IsVisible) return;
            if (!grid.Items.Contains(targetItem) || !grid.Columns.Contains(targetColumn)) return;

            CloseOpenWorkflowComboBoxes(grid);
            grid.CommitEdit(DataGridEditingUnit.Cell, true);
            grid.CommitEdit(DataGridEditingUnit.Row, true);
            TryActivateWorkflowGridCell(grid, targetItem, targetColumn, selectAllText: false, clickPositionInCell: clickPositionInCell);
        }), System.Windows.Threading.DispatcherPriority.Input);
    }

    private void WorkflowGrid_PreviewMouseDoubleClick(object sender, MouseButtonEventArgs e)
    {
        if (sender is not DataGrid grid) return;
        var cell = FindVisualParent<DataGridCell>(e.OriginalSource as DependencyObject);
        if (cell is null) return;

        grid.CurrentCell = new DataGridCellInfo(cell.DataContext, cell.Column);
        if (CopyCurrentWorkflowCell(grid))
        {
            StatusText.Text = $"Copied {cell.Column.Header}.";
            e.Handled = true;
        }
    }

    private ContextMenu CreateWorkflowCellContextMenu(DataGrid grid)
    {
        var menu = new ContextMenu();

        var copy = new MenuItem { Header = "Copy Value" };
        copy.Click += (_, _) =>
        {
            if (CopyCurrentWorkflowCell(grid)) StatusText.Text = "Copied cell.";
        };

        var paste = new MenuItem { Header = "Paste Special → Value Only" };
        paste.Click += (_, _) => PasteCurrentWorkflowCell(grid);

        var bulkUpdate = new MenuItem { Header = "Bulk Update…" };
        bulkUpdate.Click += (_, _) => RunWorkflowBulkUpdate(grid);

        menu.Items.Add(copy);
        menu.Items.Add(paste);
        menu.Items.Add(new Separator());
        menu.Items.Add(bulkUpdate);
        menu.Opened += (_, _) =>
        {
            copy.IsEnabled = grid.CurrentCell.IsValid;
            paste.IsEnabled = grid.CurrentCell.IsValid && !grid.CurrentCell.Column.IsReadOnly;
            bulkUpdate.IsEnabled = grid.CurrentCell.IsValid && !grid.CurrentCell.Column.IsReadOnly;
        };
        return menu;
    }

    private enum WorkflowBulkUpdateScope
    {
        RemainingVisibleRows,
        CurrentFilteredRows
    }

    private bool RunWorkflowBulkUpdate(DataGrid grid)
    {
        if (!grid.CurrentCell.IsValid || grid.CurrentCell.Column.IsReadOnly) return false;

        grid.CommitEdit(DataGridEditingUnit.Cell, true);
        grid.CommitEdit(DataGridEditingUnit.Row, true);

        var sourceItem = grid.CurrentCell.Item;
        var column = grid.CurrentCell.Column;
        if (sourceItem is null || column is null) return false;

        var sourceValue = GetWorkflowCellValue(sourceItem, column);
        var visibleRows = grid.Items.Cast<object>()
            .Where(item => item != CollectionView.NewItemPlaceholder)
            .ToList();
        var sourceIndex = visibleRows.IndexOf(sourceItem);
        var remainingRows = sourceIndex >= 0
            ? visibleRows.Skip(sourceIndex + 1).ToList()
            : new List<object>();

        var candidatesByScope = new Dictionary<WorkflowBulkUpdateScope, List<object>>
        {
            [WorkflowBulkUpdateScope.RemainingVisibleRows] = remainingRows,
            [WorkflowBulkUpdateScope.CurrentFilteredRows] = visibleRows.Where(item => !ReferenceEquals(item, sourceItem)).ToList()
        };

        var dialog = new WorkflowBulkUpdateDialog(
            Convert.ToString(column.Header, CultureInfo.CurrentCulture) ?? "Current column",
            FormatClipboardValue(sourceValue),
            candidatesByScope,
            item => FormatClipboardValue(GetWorkflowCellValue(item, column)))
        {
            Owner = this
        };

        if (dialog.ShowDialog() != true) return false;
        var targetRows = candidatesByScope[dialog.SelectedScope];
        var sourceText = FormatClipboardValue(sourceValue);
        var changed = 0;

        foreach (var row in targetRows)
        {
            if (string.Equals(FormatClipboardValue(GetWorkflowCellValue(row, column)), sourceText, StringComparison.CurrentCulture))
            {
                continue;
            }

            if (TrySetWorkflowCellValue(row, column, sourceValue)) changed++;
        }

        if (changed == 0)
        {
            StatusText.Text = "Bulk Update complete — no changes were needed.";
            return false;
        }

        RefreshAfterWorkflowBulkEdit(grid);
        grid.CurrentCell = new DataGridCellInfo(sourceItem, column);
        grid.ScrollIntoView(sourceItem, column);
        StatusText.Text = $"Bulk Update complete — {changed} row{(changed == 1 ? string.Empty : "s")} changed.";
        return true;
    }

    private sealed class WorkflowBulkUpdateDialog : Window
    {
        private readonly Dictionary<WorkflowBulkUpdateScope, List<object>> _candidatesByScope;
        private readonly Func<object, string> _valueReader;
        private readonly string _sourceValue;
        private readonly TextBlock _summaryText;
        private readonly Button _updateButton;

        public WorkflowBulkUpdateScope SelectedScope { get; private set; } = WorkflowBulkUpdateScope.RemainingVisibleRows;

        public WorkflowBulkUpdateDialog(
            string columnName,
            string sourceValue,
            Dictionary<WorkflowBulkUpdateScope, List<object>> candidatesByScope,
            Func<object, string> valueReader)
        {
            _sourceValue = sourceValue;
            _candidatesByScope = candidatesByScope;
            _valueReader = valueReader;

            Title = "Bulk Update";
            Width = 500;
            Height = 420;
            WindowStartupLocation = WindowStartupLocation.CenterOwner;
            ResizeMode = ResizeMode.NoResize;
            ShowInTaskbar = false;

            var root = new Grid { Margin = new Thickness(22) };
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var heading = new TextBlock
            {
                Text = "Bulk Update",
                FontSize = 22,
                FontWeight = FontWeights.SemiBold,
                Margin = new Thickness(0, 0, 0, 14)
            };
            Grid.SetRow(heading, 0);
            root.Children.Add(heading);

            var details = new TextBlock
            {
                Text = $"Column: {columnName}\nValue: {sourceValue}",
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 0, 0, 16)
            };
            Grid.SetRow(details, 1);
            root.Children.Add(details);

            var choices = new StackPanel { Margin = new Thickness(0, 0, 0, 14) };
            choices.Children.Add(new TextBlock { Text = "Apply to:", FontWeight = FontWeights.SemiBold, Margin = new Thickness(0, 0, 0, 6) });
            choices.Children.Add(CreateScopeRadio("Remaining visible rows below", WorkflowBulkUpdateScope.RemainingVisibleRows, true));
            choices.Children.Add(CreateScopeRadio("Current filtered rows", WorkflowBulkUpdateScope.CurrentFilteredRows, false));
            Grid.SetRow(choices, 2);
            root.Children.Add(choices);

            _summaryText = new TextBlock
            {
                TextWrapping = TextWrapping.Wrap,
                Padding = new Thickness(12),
                Background = new SolidColorBrush(Color.FromRgb(242, 244, 247)),
                Margin = new Thickness(0, 0, 0, 18)
            };
            Grid.SetRow(_summaryText, 3);
            root.Children.Add(_summaryText);

            var buttons = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
            var cancel = new Button { Content = "Cancel", MinWidth = 90, Margin = new Thickness(0, 0, 10, 0), IsCancel = true };
            _updateButton = new Button { Content = "Update", MinWidth = 90, IsDefault = true };
            _updateButton.Click += (_, _) => { DialogResult = true; Close(); };
            buttons.Children.Add(cancel);
            buttons.Children.Add(_updateButton);
            Grid.SetRow(buttons, 4);
            root.Children.Add(buttons);

            Content = root;
            UpdateSummary();
        }

        private RadioButton CreateScopeRadio(string label, WorkflowBulkUpdateScope scope, bool isChecked)
        {
            var radio = new RadioButton
            {
                Content = label,
                IsChecked = isChecked,
                Margin = new Thickness(0, 3, 0, 3),
                Tag = scope
            };
            radio.Checked += (_, _) =>
            {
                SelectedScope = scope;
                if (_summaryText is not null) UpdateSummary();
            };
            return radio;
        }

        private void UpdateSummary()
        {
            var rows = _candidatesByScope[SelectedScope];
            var values = rows.Select(_valueReader).ToList();
            var alreadySame = values.Count(value => string.Equals(value, _sourceValue, StringComparison.CurrentCulture));
            var emptyValues = values.Count(string.IsNullOrWhiteSpace);
            var differentValues = values.Count(value => !string.IsNullOrWhiteSpace(value) && !string.Equals(value, _sourceValue, StringComparison.CurrentCulture));
            var rowsToChange = emptyValues + differentValues;

            _summaryText.Text =
                $"Rows in scope: {rows.Count}\n" +
                $"Already '{_sourceValue}': {alreadySame}\n" +
                $"Empty rows to fill: {emptyValues}\n" +
                $"Existing different values: {differentValues}\n" +
                $"Rows to change: {rowsToChange}\n\n" +
                (differentValues > 0
                    ? $"Warning: {differentValues} existing value{(differentValues == 1 ? string.Empty : "s")} will be overwritten."
                    : "No existing values will be overwritten.");
            _updateButton.IsEnabled = rowsToChange > 0;
        }
    }

    private void TryActivateWorkflowGridCell(
        DataGrid grid,
        object targetItem,
        DataGridColumn targetColumn,
        bool selectAllText = true,
        Point? clickPositionInCell = null)
    {
        // A click can arrive while WPF is still completing the previous cell/row edit.
        // In that transient state SelectedItem/CurrentCell/BeginEdit may throw
        // InvalidOperationException. Treat it as a navigation retry, never as an app crash.
        if (!grid.IsLoaded || !grid.IsVisible) return;
        if (!grid.Items.Contains(targetItem) || !grid.Columns.Contains(targetColumn)) return;
        if (targetColumn.IsReadOnly || targetColumn.Visibility != Visibility.Visible) return;

        try
        {
            ActivateWorkflowGridCell(grid, targetItem, targetColumn, selectAllText, clickPositionInCell);
        }
        catch (InvalidOperationException)
        {
            grid.CancelEdit(DataGridEditingUnit.Cell);
            grid.CancelEdit(DataGridEditingUnit.Row);

            Dispatcher.BeginInvoke(new Action(() =>
            {
                if (!grid.IsLoaded || !grid.IsVisible) return;
                if (!grid.Items.Contains(targetItem) || !grid.Columns.Contains(targetColumn)) return;

                try
                {
                    ActivateWorkflowGridCell(grid, targetItem, targetColumn, selectAllText, clickPositionInCell);
                }
                catch (InvalidOperationException)
                {
                    // The target changed or the collection refreshed during the click.
                    // Leave the grid stable and let the next user action continue normally.
                }
            }), System.Windows.Threading.DispatcherPriority.ApplicationIdle);
        }
    }

    private void ActivateWorkflowGridCell(
        DataGrid grid,
        object targetItem,
        DataGridColumn targetColumn,
        bool selectAllText,
        Point? clickPositionInCell)
    {
        if (!grid.Items.Contains(targetItem) || !grid.Columns.Contains(targetColumn)) return;

        grid.SelectedItem = targetItem;
        grid.ScrollIntoView(targetItem, targetColumn);
        grid.UpdateLayout();

        var targetCell = GetWorkflowGridCell(grid, targetItem, targetColumn);
        if (targetCell is null || targetCell.IsReadOnly) return;

        var targetInfo = new DataGridCellInfo(targetItem, targetColumn);
        grid.SelectedCells.Clear();
        grid.CurrentCell = targetInfo;
        if (!grid.SelectedCells.Contains(targetInfo))
        {
            grid.SelectedCells.Add(targetInfo);
        }
        targetCell.Focus();

        if (!targetCell.IsEditing)
        {
            if (!grid.BeginEdit()) return;
            grid.UpdateLayout();
        }

        var comboBox = FindVisualChild<ComboBox>(targetCell);
        if (comboBox is not null)
        {
            comboBox.DropDownOpened -= WorkflowComboBox_DropDownOpened;
            comboBox.DropDownOpened += WorkflowComboBox_DropDownOpened;
            comboBox.DropDownClosed -= WorkflowComboBox_DropDownClosed;
            comboBox.DropDownClosed += WorkflowComboBox_DropDownClosed;
            Mouse.RemovePreviewMouseDownOutsideCapturedElementHandler(comboBox, WorkflowComboBox_PreviewMouseDownOutsideCapturedElement);
            Mouse.AddPreviewMouseDownOutsideCapturedElementHandler(comboBox, WorkflowComboBox_PreviewMouseDownOutsideCapturedElement);
            comboBox.Focus();
            comboBox.IsDropDownOpen = true;
            return;
        }

        var textBox = FindVisualChild<TextBox>(targetCell);
        if (textBox is not null)
        {
            if (!selectAllText)
            {
                // The grid owns the first mouse click to enter edit mode. Suppress the
                // global keyboard-focus Select All behavior for this one editor so the
                // original click can be restored as a precise caret position.
                _suppressSelectAllForTextBox = textBox;
            }

            textBox.Focus();

            if (selectAllText)
            {
                textBox.SelectAll();
            }
            else
            {
                var point = clickPositionInCell.HasValue
                    ? targetCell.TranslatePoint(clickPositionInCell.Value, textBox)
                    : Mouse.GetPosition(textBox);
                var caretIndex = ResolveMouseCaretIndex(textBox, point);
                textBox.SelectionLength = 0;
                textBox.CaretIndex = caretIndex;
            }
        }
    }


    private static int ResolveMouseCaretIndex(TextBox textBox, Point point)
    {
        var textLength = textBox.Text?.Length ?? 0;
        if (textLength == 0) return 0;

        // GetCharacterIndexFromPoint(..., true) snaps clicks in the blank area after
        // the text to the final character, which places the caret before that character.
        // Detect the visual end of the text first so a click to its right behaves like a
        // normal Windows text editor and places the caret after the last character.
        var endRect = textBox.GetRectFromCharacterIndex(textLength, trailingEdge: true);
        if (!endRect.IsEmpty && point.X >= endRect.Left)
        {
            return textLength;
        }

        var index = textBox.GetCharacterIndexFromPoint(point, snapToText: true);
        return Math.Clamp(index >= 0 ? index : textLength, 0, textLength);
    }

    private void WorkflowComboBox_DropDownOpened(object? sender, EventArgs e)
    {
        if (sender is not ComboBox comboBox) return;
        _openWorkflowComboBox = comboBox;
        _openWorkflowComboBoxSelection = comboBox.SelectedItem;
    }

    private void WorkflowComboBox_DropDownClosed(object? sender, EventArgs e)
    {
        if (sender is not ComboBox comboBox) return;

        Mouse.RemovePreviewMouseDownOutsideCapturedElementHandler(comboBox, WorkflowComboBox_PreviewMouseDownOutsideCapturedElement);
        _openWorkflowComboBoxSelection = null;
        if (ReferenceEquals(_openWorkflowComboBox, comboBox))
        {
            _openWorkflowComboBox = null;
        }
    }

    private void WorkflowComboBox_PreviewMouseDownOutsideCapturedElement(object sender, MouseButtonEventArgs e)
    {
        if (sender is not ComboBox comboBox || !comboBox.IsDropDownOpen) return;

        // This WPF event is raised specifically when a mouse-captured popup receives
        // a click outside its captured area. Close the dropdown and release capture,
        // but leave the event unhandled so the same physical click continues to the
        // filter, button, tab, grid cell or window chrome underneath it.
        comboBox.IsDropDownOpen = false;
        comboBox.ReleaseMouseCapture();
        if (Mouse.Captured is not null)
        {
            Mouse.Capture(null);
        }

        e.Handled = false;
    }

    private static DataGridCell? GetWorkflowGridCell(DataGrid grid, object item, DataGridColumn column)
    {
        var row = grid.ItemContainerGenerator.ContainerFromItem(item) as DataGridRow;
        if (row is null)
        {
            grid.ScrollIntoView(item);
            grid.UpdateLayout();
            row = grid.ItemContainerGenerator.ContainerFromItem(item) as DataGridRow;
        }

        if (row is null) return null;

        var presenter = FindVisualChild<DataGridCellsPresenter>(row);
        if (presenter is null)
        {
            row.ApplyTemplate();
            presenter = FindVisualChild<DataGridCellsPresenter>(row);
        }

        // DataGridCellsPresenter generates containers in the grid's logical Columns
        // collection order. DisplayIndex is only the visual position and changes when
        // the user drags a column. Using it here can activate a different (often
        // read-only) cell after reordering even though the requested cell is highlighted.
        var columnIndex = grid.Columns.IndexOf(column);
        if (columnIndex < 0) return null;

        var cell = presenter?.ItemContainerGenerator.ContainerFromIndex(columnIndex) as DataGridCell;
        if (cell is null)
        {
            grid.ScrollIntoView(item, column);
            grid.UpdateLayout();
            cell = presenter?.ItemContainerGenerator.ContainerFromIndex(columnIndex) as DataGridCell;
        }

        return cell;
    }

    private static void CloseOpenWorkflowComboBoxes(DependencyObject parent)
    {
        var childCount = VisualTreeHelper.GetChildrenCount(parent);
        for (var index = 0; index < childCount; index++)
        {
            var child = VisualTreeHelper.GetChild(parent, index);
            if (child is ComboBox { IsDropDownOpen: true } comboBox)
            {
                comboBox.IsDropDownOpen = false;
            }

            CloseOpenWorkflowComboBoxes(child);
        }
    }

    private static T? FindVisualParent<T>(DependencyObject? child) where T : DependencyObject
    {
        while (child is not null)
        {
            if (child is T match) return match;
            child = child is FrameworkContentElement contentElement
                ? contentElement.Parent
                : VisualTreeHelper.GetParent(child);
        }
        return null;
    }

    private static T? FindVisualChild<T>(DependencyObject parent) where T : DependencyObject
    {
        for (var i = 0; i < VisualTreeHelper.GetChildrenCount(parent); i++)
        {
            var child = VisualTreeHelper.GetChild(parent, i);
            if (child is T match) return match;
            var nested = FindVisualChild<T>(child);
            if (nested is not null) return nested;
        }
        return null;
    }

    private void UpdateNativeWorkflowStatus(string message, bool saved = false)
    {
        if (FindName("AutoSaveStatusText") is TextBlock autoSaveText)
        {
            autoSaveText.Text = message;
        }

        if (saved && FindName("LastSavedText") is TextBlock lastSavedText)
        {
            lastSavedText.Text = $"Last saved: {DateTime.Now:HH:mm:ss}";
        }

        if (FindName("NativeCountStatusText") is TextBlock countText)
        {
            countText.Text = $"Materials: {_nativeMaterialRows.Count} | Tensile: {_nativeTensileRows.Count} | Impact: {_nativeImpactRows.Count} | Stiffness: {_nativeStiffnessRows.Count}";
        }
    }

    private void ShowNativeSavingStatus(string moduleName)
    {
        UpdateNativeWorkflowStatus($"Saving {moduleName}...");
    }

    private void ShowNativeSavedStatus(string moduleName)
    {
        UpdateNativeWorkflowStatus($"Auto-saved {moduleName} ✓", saved: true);
    }

    private void ShowNativeSaveBlockedStatus(string moduleName, string reason)
    {
        UpdateNativeWorkflowStatus($"Auto-save paused for {moduleName}: {reason}");
    }

    private void ShowTransientStatus(string message)
    {
        StatusText.Text = message;
        _transientStatusTimer.Stop();
        _transientStatusTimer.Start();
    }


    private void InputDataGrid_BeginningEdit(object sender, DataGridBeginningEditEventArgs e)
    {
        if (sender is not DataGrid grid) return;
        var propertyName = GetBoundPropertyName(e.Column);
        if (string.IsNullOrWhiteSpace(propertyName) || e.Row?.Item is null)
        {
            return;
        }

        // When a DataGrid cell is selected and the user starts typing, WPF can use the
        // first typed character to create the editing TextBox before PreviewTextInput is
        // attached in PreparingCellForEdit. Reject invalid first characters here so
        // measurement cells cannot receive a one-letter value from direct typing.
        if (IsNativeMeasurementNumericInputColumn(grid.Name, propertyName)
            && e.EditingEventArgs is TextCompositionEventArgs textArgs
            && !IsValidPartialDecimalText(textArgs.Text))
        {
            e.Cancel = true;
            return;
        }
    }

    private void RefreshWorkflowGrid(string gridName)
    {
        if (FindName(gridName) is DataGrid grid)
        {
            try { grid.Items.Refresh(); } catch (InvalidOperationException) { }
        }
    }

    private static string? GetBoundPropertyName(DataGridColumn column)
    {
        return column switch
        {
            DataGridBoundColumn boundColumn when boundColumn.Binding is Binding binding => binding.Path?.Path,
            DataGridComboBoxColumn comboColumn when comboColumn.SelectedItemBinding is Binding selectedItemBinding => selectedItemBinding.Path?.Path,
            DataGridComboBoxColumn comboColumn when comboColumn.SelectedValueBinding is Binding selectedValueBinding => selectedValueBinding.Path?.Path,
            DataGridCheckBoxColumn checkBoxColumn when checkBoxColumn.Binding is Binding binding => binding.Path?.Path,
            _ => null
        };
    }

    private static object? GetPropertyValue(object target, string propertyName)
    {
        return target.GetType().GetProperty(propertyName)?.GetValue(target);
    }

    private static void SetPropertyValue(object target, string propertyName, object? value)
    {
        var property = target.GetType().GetProperty(propertyName);
        if (property is null || !property.CanWrite) return;

        if (value is null || property.PropertyType.IsInstanceOfType(value))
        {
            property.SetValue(target, value);
            return;
        }

        if (property.PropertyType == typeof(string))
        {
            property.SetValue(target, Convert.ToString(value, CultureInfo.CurrentCulture) ?? "");
            return;
        }

        var underlyingType = Nullable.GetUnderlyingType(property.PropertyType) ?? property.PropertyType;
        property.SetValue(target, Convert.ChangeType(value, underlyingType, CultureInfo.CurrentCulture));
    }

    private void MeasurementGrid_PreparingCellForEdit(object sender, DataGridPreparingCellForEditEventArgs e)
    {
        if (sender is not DataGrid grid || e.EditingElement is not TextBox textBox) return;
        var propertyName = GetBoundPropertyName(e.Column);
        if (!IsNativeMeasurementNumericInputColumn(grid.Name, propertyName)) return;

        textBox.PreviewTextInput -= MeasurementNumericTextBox_PreviewTextInput;
        textBox.PreviewTextInput += MeasurementNumericTextBox_PreviewTextInput;
        DataObject.RemovePastingHandler(textBox, MeasurementNumericTextBox_Pasting);
        DataObject.AddPastingHandler(textBox, MeasurementNumericTextBox_Pasting);

        // Defensive cleanup for any invalid text that may already have been injected by
        // the DataGrid edit-start gesture before the input filter was attached.
        if (!IsValidPartialDecimalText(textBox.Text))
        {
            textBox.Text = string.Empty;
            textBox.SelectionStart = 0;
        }
    }

    private static bool IsNativeMeasurementNumericInputColumn(string gridName, string? propertyName)
    {
        if (string.IsNullOrWhiteSpace(propertyName)) return false;

        if (gridName is "ExperimentalTensileGrid" or "ExperimentalImpactGrid")
        {
            return Regex.IsMatch(propertyName, "^Sample(10|[1-9])$", RegexOptions.CultureInvariant);
        }

        if (gridName == "ExperimentalStiffnessGrid")
        {
            return propertyName is "Sample1" or "Sample2";
        }

        return false;
    }

    private void MeasurementNumericTextBox_PreviewTextInput(object sender, TextCompositionEventArgs e)
    {
        if (sender is not TextBox textBox) return;
        var proposed = BuildProposedText(textBox, e.Text);
        e.Handled = !IsValidMeasurementCellText(textBox, proposed);
    }

    private void MeasurementNumericTextBox_Pasting(object sender, DataObjectPastingEventArgs e)
    {
        if (sender is not TextBox textBox) return;
        if (!e.DataObject.GetDataPresent(DataFormats.Text))
        {
            e.CancelCommand();
            return;
        }

        var pastedText = Convert.ToString(e.DataObject.GetData(DataFormats.Text), CultureInfo.CurrentCulture) ?? string.Empty;
        var proposed = BuildProposedText(textBox, pastedText);
        if (!IsValidMeasurementCellText(textBox, proposed))
        {
            e.CancelCommand();
        }
    }

    private static bool IsValidMeasurementCellText(TextBox textBox, string proposed)
    {
        if (!IsValidPartialDecimalText(proposed)) return false;
        if (string.IsNullOrWhiteSpace(proposed)) return true;
        if (!TryParseMeasurement(proposed, out var number)) return true; // allow a trailing decimal separator while typing

        var cell = FindVisualParent<DataGridCell>(textBox);
        var visualSource = (DependencyObject?)cell ?? textBox;
        var grid = FindVisualParent<DataGrid>(visualSource);
        if (cell is null || grid is null) return true;
        var propertyName = GetBoundPropertyName(cell.Column);

        return grid.Name switch
        {
            "ExperimentalTensileGrid" => number <= 505,
            "ExperimentalImpactGrid" => number <= 100,
            "ExperimentalStiffnessGrid" when propertyName == "Sample1" => number <= 10,
            "ExperimentalStiffnessGrid" when propertyName == "Sample2" => number <= 359,
            _ => true
        };
    }

    private static string BuildProposedText(TextBox textBox, string input)
    {
        var text = textBox.Text ?? string.Empty;
        var start = Math.Max(0, textBox.SelectionStart);
        var length = Math.Max(0, textBox.SelectionLength);
        if (start > text.Length) start = text.Length;
        if (start + length > text.Length) length = text.Length - start;
        return text.Remove(start, length).Insert(start, input ?? string.Empty);
    }

    private static bool IsValidPartialDecimalText(string text)
    {
        if (string.IsNullOrWhiteSpace(text)) return true;
        text = text.Trim();

        // Measurement input cells accept only positive decimal numbers.
        // Both Icelandic/European decimal comma and dot are allowed, but only one decimal separator.
        return Regex.IsMatch(text, @"^\d+([\.,]\d*)?$", RegexOptions.CultureInvariant);
    }

    private void InputDataGrid_PreviewKeyDown(object sender, KeyEventArgs e)
    {
        if (sender is not DataGrid grid) return;

        var modifiers = Keyboard.Modifiers;
        if ((modifiers & ModifierKeys.Control) != 0)
        {
            if (e.Key == Key.C)
            {
                e.Handled = true;
                CopyCurrentWorkflowCell(grid);
                return;
            }

            if (e.Key == Key.V)
            {
                e.Handled = true;
                PasteCurrentWorkflowCell(grid);
                return;
            }

        }

        if (e.Key == Key.Enter)
        {
            e.Handled = true;
            CommitAndMoveWorkflowCell(grid, Key.Right);
            return;
        }

        if (e.Key == Key.Tab)
        {
            e.Handled = true;
            CommitAndMoveWorkflowCell(grid, (modifiers & ModifierKeys.Shift) != 0 ? Key.Left : Key.Right);
            return;
        }

        if (e.Key is not (Key.Left or Key.Right or Key.Up or Key.Down)) return;
        if ((modifiers & (ModifierKeys.Control | ModifierKeys.Alt)) != 0) return;

        e.Handled = true;
        CommitAndMoveWorkflowCell(grid, e.Key);
    }

    private void CommitAndMoveWorkflowCell(DataGrid grid, Key direction)
    {
        CloseOpenWorkflowComboBoxes(grid);
        grid.CommitEdit(DataGridEditingUnit.Cell, true);
        grid.CommitEdit(DataGridEditingUnit.Row, true);
        Dispatcher.BeginInvoke(new Action(() => MoveDataGridSelection(grid, direction)),
            System.Windows.Threading.DispatcherPriority.Background);
    }

    private static void MoveDataGridSelection(DataGrid grid, Key direction)
    {
        if (grid.Items.Count == 0) return;
        var columns = GetEditableWorkflowColumns(grid);
        if (columns.Count == 0) return;

        var rowIndex = grid.Items.IndexOf(grid.CurrentItem);
        if (rowIndex < 0) rowIndex = 0;
        var columnIndex = grid.CurrentColumn is null ? -1 : columns.IndexOf(grid.CurrentColumn);
        if (columnIndex < 0) columnIndex = direction == Key.Left ? columns.Count - 1 : 0;

        switch (direction)
        {
            case Key.Right:
                if (++columnIndex >= columns.Count) { columnIndex = 0; rowIndex++; }
                break;
            case Key.Left:
                if (--columnIndex < 0) { columnIndex = columns.Count - 1; rowIndex--; }
                break;
            case Key.Down: rowIndex++; break;
            case Key.Up: rowIndex--; break;
        }

        rowIndex = Math.Clamp(rowIndex, 0, grid.Items.Count - 1);
        columnIndex = Math.Clamp(columnIndex, 0, columns.Count - 1);
        var item = grid.Items[rowIndex];
        var column = columns[columnIndex];
        // CurrentCell can automatically enter SelectedCells. Do not also select the
        // whole row or blindly add the same cell again: both can duplicate the
        // DataGridCellInfo and make WPF throw "collection already contains item".
        grid.SelectedCells.Clear();
        var targetCell = new DataGridCellInfo(item, column);
        grid.CurrentCell = targetCell;
        if (!grid.SelectedCells.Contains(targetCell))
        {
            grid.SelectedCells.Add(targetCell);
        }
        grid.ScrollIntoView(item, column);
        grid.Focus();

        grid.Dispatcher.BeginInvoke(new Action(() =>
        {
            grid.BeginEdit();
            grid.UpdateLayout();
            var cell = GetWorkflowGridCell(grid, item, column);
            var combo = cell is null ? null : FindVisualChild<ComboBox>(cell);
            if (combo is not null)
            {
                combo.Focus();
                combo.IsDropDownOpen = true;
            }
            else
            {
                var textBox = cell is null ? null : FindVisualChild<TextBox>(cell);
                textBox?.Focus();
                textBox?.SelectAll();
            }
        }), System.Windows.Threading.DispatcherPriority.Background);
    }

    private static List<DataGridColumn> GetEditableWorkflowColumns(DataGrid grid) => grid.Columns
        .Where(c => c.Visibility == Visibility.Visible && !c.IsReadOnly && GetBoundPropertyName(c) is not null)
        .OrderBy(c => c.DisplayIndex)
        .ToList();

    private void WorkflowGrid_CopyCanExecute(object sender, CanExecuteRoutedEventArgs e)
    {
        e.CanExecute = sender is DataGrid grid && (grid.CurrentCell.IsValid || grid.SelectedCells.Count > 0);
        e.Handled = true;
    }

    private void WorkflowGrid_CopyExecuted(object sender, ExecutedRoutedEventArgs e)
    {
        if (sender is DataGrid grid) CopyCurrentWorkflowCell(grid);
        e.Handled = true;
    }

    private void WorkflowGrid_PasteCanExecute(object sender, CanExecuteRoutedEventArgs e)
    {
        var hasText = false;
        try { hasText = Clipboard.ContainsText(); } catch (ExternalException) { }
        e.CanExecute = sender is DataGrid grid && grid.CurrentCell.IsValid && hasText;
        e.Handled = true;
    }

    private void WorkflowGrid_PasteExecuted(object sender, ExecutedRoutedEventArgs e)
    {
        if (sender is DataGrid grid) PasteCurrentWorkflowCell(grid);
        e.Handled = true;
    }

    private static bool CopyCurrentWorkflowCell(DataGrid grid)
    {
        // Single-cell copy deliberately uses CurrentCell rather than SelectedCells.
        // This keeps Ctrl+C dependable even while multi-cell selection work is paused.
        if (!grid.CurrentCell.IsValid) return false;

        grid.CommitEdit(DataGridEditingUnit.Cell, true);
        var item = grid.CurrentCell.Item;
        var column = grid.CurrentCell.Column;
        if (item is null || column is null) return false;

        var text = FormatClipboardValue(GetWorkflowCellValue(item, column));
        for (var attempt = 0; attempt < 4; attempt++)
        {
            try
            {
                Clipboard.SetText(text ?? string.Empty, TextDataFormat.UnicodeText);
                return true;
            }
            catch (ExternalException)
            {
                Thread.Sleep(25);
            }
        }
        return false;
    }

    private bool PasteCurrentWorkflowCell(DataGrid grid)
    {
        // Single-cell paste takes only the first clipboard cell. Multi-cell paste remains
        // available in the codebase but is intentionally not part of this focused fix.
        if (!grid.CurrentCell.IsValid || grid.CurrentCell.Column.IsReadOnly) return false;

        string text;
        try
        {
            if (!Clipboard.ContainsText()) return false;
            text = Clipboard.GetText(TextDataFormat.UnicodeText);
        }
        catch (ExternalException)
        {
            return false;
        }

        text = text.Replace("\r\n", "\n");
        var firstCell = text.Split('\n')[0].Split('\t')[0].TrimEnd('\r');
        var item = grid.CurrentCell.Item;
        var column = grid.CurrentCell.Column;
        if (item is null || column is null) return false;

        grid.CancelEdit(DataGridEditingUnit.Cell);
        if (!TrySetWorkflowCellValue(item, column, firstCell)) return false;

        RefreshAfterWorkflowBulkEdit(grid);
        grid.CurrentCell = new DataGridCellInfo(item, column);
        grid.ScrollIntoView(item, column);
        StatusText.Text = "Pasted cell.";
        return true;
    }

    private void RefreshAfterWorkflowBulkEdit(DataGrid grid)
    {
        grid.CommitEdit(DataGridEditingUnit.Cell, true);
        grid.CommitEdit(DataGridEditingUnit.Row, true);
        RefreshWorkflowGrid(grid.Name);
        try { grid.Items.Refresh(); } catch (InvalidOperationException) { }
    }

    private static object? GetWorkflowCellValue(object item, DataGridColumn column)
    {
        var propertyName = GetBoundPropertyName(column);
        if (propertyName is null) return null;
        if (item is DataRowView rowView) return rowView.Row.Table.Columns.Contains(propertyName) ? rowView[propertyName] : null;
        return TypeDescriptor.GetProperties(item)[propertyName]?.GetValue(item);
    }

    private static bool TrySetWorkflowCellValue(object item, DataGridColumn column, object? input)
    {
        var propertyName = GetBoundPropertyName(column);
        if (propertyName is null || column.IsReadOnly) return false;
        try
        {
            if (item is DataRowView rowView)
            {
                if (!rowView.Row.Table.Columns.Contains(propertyName)) return false;
                var dataColumn = rowView.Row.Table.Columns[propertyName]!;
                rowView[propertyName] = ConvertWorkflowValue(input, dataColumn.DataType) ?? DBNull.Value;
                return true;
            }
            var property = TypeDescriptor.GetProperties(item)[propertyName];
            if (property is null || property.IsReadOnly) return false;
            property.SetValue(item, ConvertWorkflowValue(input, property.PropertyType));
            return true;
        }
        catch (Exception ex) when (ex is FormatException or InvalidCastException or ArgumentException)
        {
            return false;
        }
    }

    private static object? ConvertWorkflowValue(object? input, Type targetType)
    {
        var nullableType = Nullable.GetUnderlyingType(targetType);
        var effectiveType = nullableType ?? targetType;
        var text = Convert.ToString(input, CultureInfo.CurrentCulture) ?? string.Empty;
        if (string.IsNullOrWhiteSpace(text)) return effectiveType == typeof(string) ? string.Empty : nullableType is not null ? null : Activator.CreateInstance(effectiveType);
        if (effectiveType == typeof(string)) return text;
        if (effectiveType == typeof(bool)) return text.Equals("true", StringComparison.OrdinalIgnoreCase) || text.Equals("yes", StringComparison.OrdinalIgnoreCase) || text == "1";
        if (effectiveType.IsEnum) return Enum.Parse(effectiveType, text, true);
        if (effectiveType == typeof(double) && double.TryParse(text.Replace(',', '.'), NumberStyles.Float, CultureInfo.InvariantCulture, out var d)) return d;
        if (effectiveType == typeof(decimal) && decimal.TryParse(text.Replace(',', '.'), NumberStyles.Float, CultureInfo.InvariantCulture, out var m)) return m;
        return Convert.ChangeType(text, effectiveType, CultureInfo.CurrentCulture);
    }

    private static string FormatClipboardValue(object? value) => value is null or DBNull ? string.Empty : value switch
    {
        IFormattable formattable => formattable.ToString(null, CultureInfo.CurrentCulture) ?? string.Empty,
        _ => value.ToString() ?? string.Empty
    };

    private static void ApplySmartWorkflowColumnWidths(DataGrid grid)
    {
        foreach (var column in grid.Columns)
        {
            var header = Convert.ToString(column.Header, CultureInfo.CurrentCulture) ?? string.Empty;
            var property = GetBoundPropertyName(column) ?? string.Empty;
            var key = (header + " " + property).ToLowerInvariant();
            var width = key switch
            {
                var x when x.Contains("notes") || x.Contains("website") || x.Contains("url") || x.Contains("material key") => 220,
                var x when x.Contains("manufacturer") || x.Contains("marketing") || x.Contains("display name") || x.Contains("product") => 170,
                var x when x.Contains("currency") || x.Contains("color") || x.Contains("status") || x.Contains("video") => 95,
                var x when x.Contains("date") || x.Contains("category") || x.Contains("reinforcement") || x.Contains("base material") => 125,
                _ => Math.Clamp(24 + Math.Max(header.Length, property.Length) * 7, 75, 150)
            };
            column.MinWidth = 55;
            column.MaxWidth = 280;
            column.Width = new DataGridLength(width);
        }
    }

    private void RestoreSqliteBackup_Click(object sender, RoutedEventArgs e)
    {
        if (IsAutomationActionBlocked("SQLite restore")) return;
        var dialog = new OpenFileDialog
        {
            Title = "Select SQLite Backup to Restore",
            Filter = SqliteBackupFileDialogFilter,
            InitialDirectory = Directory.Exists(_database.BackupFolder) ? _database.BackupFolder : _database.DatabaseFolder
        };
        if (dialog.ShowDialog(this) != true) return;

        try
        {
            var backup = _database.VerifyBackupCompatibility(dialog.FileName, runMigrationDryRun: true);
            if (!backup.CanRestore)
                throw new InvalidOperationException("Restore blocked: " + backup.CompatibilityStatus + ". " + backup.CompatibilityDetail);

            var confirmation = MessageBox.Show(this,
                "Restore this local SQLite backup?\n\n" +
                $"File: {System.IO.Path.GetFileName(backup.FilePath)}\n" +
                $"Schema: v{backup.SchemaVersion}\n" +
                $"Compatibility: {backup.CompatibilityStatus}\n" +
                $"Size: {FormatByteSize(backup.FileSizeBytes)}\n" +
                $"Materials: {backup.Materials:N0}\n" +
                $"Tensile samples: {backup.TensileSamples:N0}\n" +
                $"Impact samples: {backup.ImpactSamples:N0}\n" +
                $"Stiffness rows: {backup.StiffnessRows:N0}\n" +
                $"Integrity: {backup.IntegrityResult}\n\n" +
                "A verified recovery backup of the current database will be created first. The application will restart after a successful restore.",
                "Confirm Local Database Restore", MessageBoxButton.YesNo, MessageBoxImage.Warning, MessageBoxResult.No);
            if (confirmation != MessageBoxResult.Yes) return;

            if (_nativeMaterialDirty)
            {
                ApplyNativeMaterialComputedFieldsToAllRows();
                SaveNativeMaterialsSilent();
                if (_nativeMaterialDirty) throw new InvalidOperationException("Restore blocked because current Material changes could not be saved before the recovery snapshot.");
            }

            var result = _database.RestoreDatabaseBackup(dialog.FileName);
            MessageBox.Show(this,
                "SQLite restore completed and passed integrity verification.\n\n" +
                $"Restored: {result.SourceBackupPath}\n" +
                $"Pre-restore recovery backup: {result.RecoveryBackupPath}\n" +
                $"Post-restore evidence backup: {result.PostRestoreBackupPath}\n" +
                $"Materials: {result.RestoredDatabase.Materials:N0}\n\n" +
                "The application will now restart and run normal schema compatibility checks.",
                "SQLite Backup Restored", MessageBoxButton.OK, MessageBoxImage.Information);

            _databaseRestoreShutdown = true;
            var executable = Environment.ProcessPath;
            if (string.IsNullOrWhiteSpace(executable)) throw new InvalidOperationException("Restore succeeded, but the application executable path is unavailable. Close and reopen the application manually.");
            Process.Start(new ProcessStartInfo(executable) { UseShellExecute = true, WorkingDirectory = AppContext.BaseDirectory });
            Application.Current.Shutdown();
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "SQLite Restore Failed", MessageBoxButton.OK, MessageBoxImage.Error);
        }
    }

    private async void ShowRecoveryCenter_Click(object sender, RoutedEventArgs e)
    {
        var window = new Window
        {
            Title = "3DPIceland Backup and Recovery Center",
            Owner = this,
            Width = 1450,
            Height = 760,
            MinWidth = 1050,
            MinHeight = 560,
            WindowStartupLocation = WindowStartupLocation.CenterOwner
        };
        AutomationProperties.SetAutomationId(window, "RecoveryCenterWindow");
        var root = new DockPanel { Margin = new Thickness(10) };
        var toolbar = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 8) };
        var status = new TextBlock { Text = "Loading local SQLite backups…", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(8, 0, 0, 0) };
        var details = new TextBox { IsReadOnly = true, TextWrapping = TextWrapping.Wrap, Height = 90, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Margin = new Thickness(0, 8, 0, 0) };
        var glossary = new TextBlock
        {
            Text = BuildRecoveryCenterCompatibilitySummary(),
            TextWrapping = TextWrapping.Wrap,
            Foreground = new SolidColorBrush(Color.FromRgb(51, 65, 85)),
            Background = new SolidColorBrush(Color.FromRgb(248, 250, 252)),
            Padding = new Thickness(10, 8, 10, 8),
            Margin = new Thickness(0, 0, 0, 8)
        };
        var rows = new ObservableCollection<DatabaseBackupInfo>();
        var grid = new DataGrid
        {
            ItemsSource = rows, AutoGenerateColumns = false, IsReadOnly = true, SelectionMode = DataGridSelectionMode.Single,
            CanUserAddRows = false, CanUserDeleteRows = false, HeadersVisibility = DataGridHeadersVisibility.Column,
            GridLinesVisibility = DataGridGridLinesVisibility.Horizontal
        };
        AutomationProperties.SetAutomationId(grid, "RecoveryBackupCatalog");
        AutomationProperties.SetAutomationId(status, "RecoveryStatus");
        AutomationProperties.SetAutomationId(details, "RecoverySelectedDetails");
        AutomationProperties.SetAutomationId(glossary, "RecoveryCompatibilitySummary");
        void Column(string header, string property, double width) => grid.Columns.Add(new DataGridTextColumn { Header = header, Binding = new Binding(property), Width = width });
        Column("File", nameof(DatabaseBackupInfo.FileName), 260);
        Column("Type", nameof(DatabaseBackupInfo.BackupKind), 185);
        Column("Modified", nameof(DatabaseBackupInfo.ModifiedAt), 150);
        Column("Schema", nameof(DatabaseBackupInfo.SchemaVersion), 70);
        Column("Integrity", nameof(DatabaseBackupInfo.IntegrityResult), 80);
        Column("Materials", nameof(DatabaseBackupInfo.Materials), 85);
        Column("Tensile", nameof(DatabaseBackupInfo.TensileSamples), 85);
        Column("Impact", nameof(DatabaseBackupInfo.ImpactSamples), 85);
        Column("Stiffness", nameof(DatabaseBackupInfo.StiffnessRows), 85);
        Column("Settings", nameof(DatabaseBackupInfo.SettingsRows), 75);
        Column("Compatibility", nameof(DatabaseBackupInfo.CompatibilityStatus), 170);

        Button ActionButton(string text, string automationId)
        {
            var button = new Button { Content = text, Padding = new Thickness(10, 5, 10, 5), Margin = new Thickness(0, 0, 8, 0) };
            AutomationProperties.SetAutomationId(button, automationId);
            toolbar.Children.Add(button);
            return button;
        }
        var refreshButton = ActionButton(BackupAndRecoveryCenterActions[0], "RefreshRecoveryCatalog");
        var verifyButton = ActionButton(BackupAndRecoveryCenterActions[1], "VerifySelectedRecoveryBackup");
        var restoreButton = ActionButton(BackupAndRecoveryCenterActions[2], "RestoreSelectedRecoveryBackup");
        var manualBackupButton = ActionButton(BackupAndRecoveryCenterActions[3], "CreateRecoverySqliteBackup");
        var restoreFileButton = ActionButton(BackupAndRecoveryCenterActions[4], "RestoreRecoverySqliteFile");
        var exportExcelButton = ActionButton(BackupAndRecoveryCenterActions[5], "CreateRecoveryExcelBackup");
        var restoreExcelButton = ActionButton(BackupAndRecoveryCenterActions[6], "RestoreRecoveryExcelBackup");
        var openButton = ActionButton(BackupAndRecoveryCenterActions[7], "OpenRecoveryStorageFolder");
        toolbar.Children.Add(status);

        async Task RefreshAsync()
        {
            refreshButton.IsEnabled = verifyButton.IsEnabled = restoreButton.IsEnabled = false;
            status.Text = "Inspecting SQLite backups…";
            try
            {
                var catalog = await Task.Run(() => _database.GetLocalBackupCatalog());
                rows.Clear(); foreach (var item in catalog) rows.Add(item);
                var emptyReady = rows.Count(item => string.Equals(item.CompatibilityStatus, "Ready — empty profile", StringComparison.Ordinal));
                status.Text = $"{rows.Count:N0} local SQLite backup(s); {emptyReady:N0} healthy empty-profile backup(s); select one for exact details.";
            }
            catch (Exception ex) { status.Text = "Recovery catalog failed: " + ex.Message; }
            finally { refreshButton.IsEnabled = verifyButton.IsEnabled = restoreButton.IsEnabled = true; }
        }
        grid.SelectionChanged += (_, _) =>
        {
            if (grid.SelectedItem is not DatabaseBackupInfo item) { details.Text = string.Empty; return; }
            details.Text = $"{item.FilePath}\n\n{item.CompatibilityStatus}: {item.CompatibilityDetail}";
        };
        refreshButton.Click += async (_, _) => await RefreshAsync();
        verifyButton.Click += async (_, _) =>
        {
            if (grid.SelectedItem is not DatabaseBackupInfo selected) { MessageBox.Show(window, "Select a SQLite backup first.", "Recovery Center", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            refreshButton.IsEnabled = verifyButton.IsEnabled = restoreButton.IsEnabled = false;
            status.Text = "Running isolated migration compatibility verification…";
            try
            {
                var verified = await Task.Run(() => _database.VerifyBackupCompatibility(selected.FilePath, runMigrationDryRun: true));
                var index = rows.IndexOf(selected); if (index >= 0) rows[index] = verified;
                grid.SelectedItem = verified;
                status.Text = verified.CanRestore ? "Verification passed; backup is eligible for guarded restore." : "Verification completed; restore remains blocked.";
            }
            catch (Exception ex) { status.Text = "Verification failed: " + ex.Message; }
            finally { refreshButton.IsEnabled = verifyButton.IsEnabled = restoreButton.IsEnabled = true; }
        };
        restoreButton.Click += async (_, _) =>
        {
            if (grid.SelectedItem is not DatabaseBackupInfo selected) { MessageBox.Show(window, "Select a SQLite backup first.", "Recovery Center", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            refreshButton.IsEnabled = verifyButton.IsEnabled = restoreButton.IsEnabled = false;
            try
            {
                var verified = await Task.Run(() => _database.VerifyBackupCompatibility(selected.FilePath, runMigrationDryRun: true));
                if (!verified.CanRestore) throw new InvalidOperationException(verified.CompatibilityStatus + ": " + verified.CompatibilityDetail);
                var confirmation = MessageBox.Show(window,
                    "Restore the selected local SQLite backup?\n\n" +
                    $"File: {verified.FileName}\nType: {verified.BackupKind}\nSchema: v{verified.SchemaVersion}\nStatus: {verified.CompatibilityStatus}\n" +
                    $"Materials: {verified.Materials:N0}\nTensile: {verified.TensileSamples:N0}\nImpact: {verified.ImpactSamples:N0}\nStiffness: {verified.StiffnessRows:N0}\n\n" +
                    (verified.Materials == 0
                        ? "EMPTY PROFILE WARNING: This is a healthy zero-data backup. Restore will explicitly replace the current database with an empty profile.\n\n"
                        : string.Empty) +
                    "A verified pre-restore recovery backup will be created. The application will restart after successful restore.",
                    "Confirm Recovery Center Restore", MessageBoxButton.YesNo, MessageBoxImage.Warning, MessageBoxResult.No);
                if (confirmation != MessageBoxResult.Yes) return;
                var result = await Task.Run(() => _database.RestoreDatabaseBackup(verified.FilePath));
                MessageBox.Show(window,
                    "Restore completed and passed integrity verification.\n\n" +
                    "Pre-restore recovery backup: " + result.RecoveryBackupPath + "\n" +
                    "Post-restore evidence backup: " + result.PostRestoreBackupPath,
                    "Recovery Center Restore Completed", MessageBoxButton.OK, MessageBoxImage.Information);
                window.Close();
                RestartAfterDatabaseRestore();
            }
            catch (Exception ex) { MessageBox.Show(window, ex.Message, "Recovery Center Restore Failed", MessageBoxButton.OK, MessageBoxImage.Error); }
            finally { refreshButton.IsEnabled = verifyButton.IsEnabled = restoreButton.IsEnabled = true; }
        };
        manualBackupButton.Click += async (_, _) =>
        {
            try
            {
                var backup = _database.CreateManualBackupNow();
                status.Text = "Manual SQLite backup created and verified: " + backup.Name;
                await RefreshAsync();
            }
            catch (Exception ex) { MessageBox.Show(window, ex.Message, "Manual Backup Failed", MessageBoxButton.OK, MessageBoxImage.Error); }
        };
        restoreFileButton.Click += (_, _) => { window.Close(); RestoreSqliteBackup_Click(this, new RoutedEventArgs()); };
        exportExcelButton.Click += (_, _) => { window.Close(); ExportNativeExcel_Click(this, new RoutedEventArgs()); };
        restoreExcelButton.Click += (_, _) => { window.Close(); RestoreExcelDisasterRecovery_Click(this, new RoutedEventArgs()); };
        openButton.Click += (_, _) => OpenBackupFolderFromDiagnostics();
        DockPanel.SetDock(toolbar, Dock.Top); root.Children.Add(toolbar);
        DockPanel.SetDock(glossary, Dock.Top); root.Children.Add(glossary);
        DockPanel.SetDock(details, Dock.Bottom); root.Children.Add(details);
        root.Children.Add(grid); window.Content = root;
        window.Show();
        await RefreshAsync();
    }

    private static string BuildRecoveryCenterCompatibilitySummary() =>
        "Ready backups can be restored. Older backups require verification; incompatible or damaged backups remain blocked.";

    private static string BuildRecoveryCompatibilityGlossary() =>
        "Compatibility: Ready = integrity/schema accepted with canonical Materials. " +
        "Ready — empty profile = healthy schema-current clean-profile backup with zero Materials; restorable explicitly, but not full-data release evidence. " +
        "Migration required = supported older schema needs isolated dry-run. " +
        "Legacy / incomplete = missing supported canonical structure/evidence. " +
        "Newer / incompatible = created by a newer schema and blocked. " +
        "Corrupt / unreadable = integrity/read failure and blocked.";

    private static string BuildLatestApplicationUpdateEvidenceSummary()
    {
        var diagnostics = GetApplicationUpdateDiagnostics();
        var latest = diagnostics.FirstOrDefault();
        var sb = new StringBuilder();
        sb.AppendLine("Latest application update evidence (read-only)");
        if (latest is null)
        {
            foreach (var label in UpdateEvidenceBoundaryLabels)
                sb.AppendLine(label + ": None recorded");
        }
        else
        {
            sb.AppendLine($"Transaction state: {latest.Phase}; {latest.TransactionId}; v{latest.PreviousVersion} -> v{latest.NewVersion}; updated {latest.UpdatedAtUtc}");

            ApplicationUpdateTransactionRequest? request = null;
            if (latest.RequestReadable && IOFile.Exists(latest.RequestPath))
            {
                try
                {
                    request = JsonSerializer.Deserialize<ApplicationUpdateTransactionRequest>(IOFile.ReadAllText(latest.RequestPath));
                }
                catch
                {
                    request = null;
                }
            }

            var acknowledgementPath = request?.HealthAcknowledgementPath ?? string.Empty;
            sb.AppendLine("Health acknowledgement: " + DescribeUpdateHealthAcknowledgement(acknowledgementPath, latest));

            var rollbackPath = request?.RollbackDirectory ?? string.Empty;
            sb.AppendLine("Application rollback snapshot: " +
                (string.IsNullOrWhiteSpace(rollbackPath) ? "None recorded" :
                    (IODirectory.Exists(rollbackPath) ? "Present; " : "Missing; ") + rollbackPath));

            sb.AppendLine("SQLite backup evidence: " +
                (string.IsNullOrWhiteSpace(latest.DatabaseBackupPath) ? "None recorded" :
                    (IOFile.Exists(latest.DatabaseBackupPath) ? "Present; " : "Missing; ") + latest.DatabaseBackupPath));
        }
        sb.Append("Application rollback never restores SQLite automatically. SQLite recovery remains a separate explicit/default-No operation; evidence and backups are not deleted here.");
        return sb.ToString();
    }

    private static string DescribeUpdateHealthAcknowledgement(
        string acknowledgementPath,
        ApplicationUpdateTransactionDiagnostic transaction)
    {
        if (string.IsNullOrWhiteSpace(acknowledgementPath)) return "None recorded";
        if (!IOFile.Exists(acknowledgementPath)) return "Missing; " + acknowledgementPath;
        try
        {
            var acknowledgement = JsonSerializer.Deserialize<ApplicationUpdateHealthAcknowledgement>(
                IOFile.ReadAllText(acknowledgementPath));
            var valid = acknowledgement is not null &&
                        acknowledgement.HealthSchema == ApplicationUpdateHealthAcknowledgement.Schema &&
                        acknowledgement.TransactionId == transaction.TransactionId &&
                        acknowledgement.ReleaseVersion == transaction.NewVersion;
            return valid
                ? $"Valid; release v{acknowledgement!.ReleaseVersion}; SQLite schema v{acknowledgement.DatabaseSchema}; acknowledged {acknowledgement.AcknowledgedAtUtc}; {acknowledgementPath}"
                : "Present but identity/schema does not match the latest transaction; " + acknowledgementPath;
        }
        catch (Exception ex)
        {
            return "Unreadable; " + acknowledgementPath + "; " + ex.Message;
        }
    }

    private void RestoreExcelDisasterRecovery_Click(object sender, RoutedEventArgs e)
    {
        if (IsAutomationActionBlocked("Excel restore")) return;
        var dialog = new OpenFileDialog
        {
            Title = "Select Governed Excel Disaster-Recovery Package",
            Filter = "Excel recovery workbook (*.xlsx)|*.xlsx|All files (*.*)|*.*"
        };
        if (dialog.ShowDialog(this) != true) return;

        try
        {
            var service = new ExcelDisasterRecoveryService();
            var snapshot = service.LoadAndVerify(dialog.FileName);
            var materials = snapshot.Tables.Single(table => string.Equals(table.TableName, "NativeMaterialManagerRows", StringComparison.OrdinalIgnoreCase)).Rows.Count;
            var totalRows = snapshot.Tables.Sum(table => table.Rows.Count);
            var confirmation = MessageBox.Show(this,
                "Restore canonical application data from this governed Excel package?\n\n" +
                $"File: {System.IO.Path.GetFileName(dialog.FileName)}\n" +
                $"Format: v{snapshot.FormatVersion}\n" +
                $"Source schema: v{snapshot.SourceSchemaVersion}\n" +
                $"Exported UTC: {snapshot.ExportedAtUtc}\n" +
                $"Governed tables: {snapshot.Tables.Count:N0}\n" +
                $"Rows: {totalRows:N0}\n" +
                $"Materials: {materials:N0}\n\n" +
                "Every table hash has passed. A verified SQLite recovery backup of the current database will be created first. The governed tables will be replaced in one transaction and the application will restart.",
                "Confirm Excel Disaster Recovery", MessageBoxButton.YesNo, MessageBoxImage.Warning, MessageBoxResult.No);
            if (confirmation != MessageBoxResult.Yes) return;

            var result = _database.RestoreExcelRecoverySnapshot(snapshot);
            MessageBox.Show(this,
                "Excel disaster recovery completed successfully.\n\n" +
                $"Tables restored: {result.TablesRestored:N0}\n" +
                $"Rows restored: {result.RowsRestored:N0}\n" +
                $"Materials restored: {result.MaterialsRestored:N0}\n" +
                $"Pre-restore SQLite recovery backup: {result.RecoveryBackupPath}\n\n" +
                "SQLite foreign keys, integrity and Materials counts passed. The application will now restart.",
                "Excel Disaster Recovery Completed", MessageBoxButton.OK, MessageBoxImage.Information);
            RestartAfterDatabaseRestore();
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Excel Disaster Recovery Failed", MessageBoxButton.OK, MessageBoxImage.Error);
        }
    }

    private void RestartAfterDatabaseRestore()
    {
        _databaseRestoreShutdown = true;
        var executable = Environment.ProcessPath;
        if (string.IsNullOrWhiteSpace(executable)) throw new InvalidOperationException("Restore succeeded, but the application executable path is unavailable. Close and reopen the application manually.");
        Process.Start(new ProcessStartInfo(executable) { UseShellExecute = true, WorkingDirectory = AppContext.BaseDirectory });
        Application.Current.Shutdown();
    }

    private void ShowMaterialDetails(DataRow row)
    {
        _currentMaterialDetailRow = row;
        var title = _detailService.BuildTitle(row);
        var subtitle = _detailService.BuildSubtitle(row);
        var materialId = GetCell(row, "Material ID", "MaterialID").Trim();

        DetailTitleText.Text = string.IsNullOrWhiteSpace(title) ? "Selected material" : title;
        DetailMaterialIdText.Text = string.IsNullOrWhiteSpace(materialId) ? "MaterialID: none" : $"MaterialID: {materialId}";
        DetailSubtitleText.Text = string.IsNullOrWhiteSpace(subtitle) ? "All imported Excel fields are shown below." : subtitle;

        RenderGroupedDetails(row);
        RenderPrintingProfile(row);
        RenderMechanicalTab(row);
        UpdateSelectedMaterialIntelligence(row);
        UpdateReportSelectedMaterial(row);
        SynchronizeRecommendationScopeToSelectedMaterial(row);
    }

    private void SynchronizeRecommendationScopeToSelectedMaterial(DataRow row)
    {
        if (RecommendationBaseMaterialFilter is null) return;

        var selectedBaseMaterial = DataTableHelpers.FirstValue(
            row,
            "Base Material",
            "Type",
            "Material Type")?.Trim() ?? string.Empty;
        var recommendationScope = ResolveRecommendationBaseMaterialScope(
            selectedBaseMaterial,
            RecommendationBaseMaterialFilter.Items.Cast<object?>().Select(item =>
                item is ComboBoxItem comboItem
                    ? comboItem.Content?.ToString()
                    : item?.ToString()));
        if (string.IsNullOrWhiteSpace(recommendationScope)) return;
        if (string.Equals(
                SelectedComboText(RecommendationBaseMaterialFilter),
                recommendationScope,
                StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        _isUpdatingRecommendationFilters = true;
        try
        {
            SelectComboValue(RecommendationBaseMaterialFilter, recommendationScope);
        }
        finally
        {
            _isUpdatingRecommendationFilters = false;
        }

        UpdateRecommendations();
    }

    private static string ResolveRecommendationBaseMaterialScope(
        string? selectedBaseMaterial,
        IEnumerable<string?> availableScopes)
    {
        if (string.IsNullOrWhiteSpace(selectedBaseMaterial)) return string.Empty;
        var normalized = selectedBaseMaterial.Trim();
        return availableScopes
            .FirstOrDefault(scope => string.Equals(
                scope?.Trim(),
                normalized,
                StringComparison.OrdinalIgnoreCase))
            ?.Trim() ?? string.Empty;
    }

    private void RenderPrintingProfile(DataRow row)
    {
        var baseMaterial = row.Table.Columns.Contains("Base Material") ? row["Base Material"]?.ToString()?.Trim() ?? string.Empty : string.Empty;
        var materialId = GetCell(row, "Material ID", "MaterialID").Trim();
        var nativeMaterial = _nativeMaterialRows.FirstOrDefault(item =>
            string.Equals(item.MaterialID?.Trim(), materialId, StringComparison.OrdinalIgnoreCase));
        var profile = nativeMaterial is null
            ? ResolveBaseMaterialCatalogRow(null, baseMaterial)
            : ResolveBaseMaterialCatalogRow(nativeMaterial);
        string Value(string value) => string.IsNullOrWhiteSpace(value) ? "Not recorded" : value.Trim();
        var fields = profile is null ? new List<MaterialDetailField>() : new()
        {
            new("Nozzle Temperature Min °C", Value(profile.NozzleTemperatureMinC)), new("Nozzle Temperature Recommended °C", Value(profile.NozzleTemperatureRecommendedC)), new("Nozzle Temperature Max °C", Value(profile.NozzleTemperatureMaxC)),
            new("Bed Temperature Min °C", Value(profile.BedTemperatureMinC)), new("Bed Temperature Recommended °C", Value(profile.BedTemperatureRecommendedC)), new("Bed Temperature Max °C", Value(profile.BedTemperatureMaxC)),
            new("Print Speed Min mm/s", Value(profile.PrintSpeedMinMmPerS)), new("Print Speed Recommended mm/s", Value(profile.PrintSpeedRecommendedMmPerS)), new("Print Speed Max mm/s", Value(profile.PrintSpeedMaxMmPerS)),
            new("Cooling Min %", Value(profile.CoolingMinPercent)), new("Cooling Recommended %", Value(profile.CoolingRecommendedPercent)), new("Cooling Max %", Value(profile.CoolingMaxPercent)), new("Cooling Guidance", Value(profile.CoolingGuidance)),
            new("Drying Temperature °C", Value(profile.DryingTemperatureC)), new("Drying Time hours", Value(profile.DryingTimeHours)), new("Enclosure Requirement", Value(profile.EnclosureRequirement)),
            new("Printer / G-code Profile Reference", Value(profile.PrinterProfileReference)), new("Slicer Profile Reference", Value(profile.SlicerProfileReference)),
            new("Profile ID", Value(profile.ProfileId)), new("Profile Kind", Value(profile.ProfileKind))
        };
        PrintingProfileFieldsList.ItemsSource = fields;
        var recorded = fields.Count(field => !string.Equals(field.Value, "Not recorded", StringComparison.Ordinal));
        PrintingProfileStatusText.Text = profile is null
            ? $"No Base Material Catalog profile matches '{baseMaterial}'."
            : $"{recorded} / {fields.Count} fields recorded • SQLite Base Material baseline: {profile.BaseMaterial}";
    }


    private string CurrentSelectedMaterialId()
    {
        if (_currentMaterialDetailRow is DataRow displayedRow && displayedRow.Table.Columns.Contains("Material ID"))
        {
            return displayedRow["Material ID"]?.ToString()?.Trim() ?? string.Empty;
        }

        if (_lastSelectedNativeMaterial is { } nativeRow &&
            _nativeMaterialRows.Contains(nativeRow))
        {
            return nativeRow.MaterialID.Trim();
        }

        return string.Empty;
    }

    private DataRow? CurrentSelectedMaterialRow()
    {
        if (_currentMaterialDetailRow is not null) return _currentMaterialDetailRow;

        if (_lastSelectedNativeMaterial is { } nativeRow &&
            _nativeMaterialRows.Contains(nativeRow))
        {
            return BuildNativeMaterialDataRow(nativeRow);
        }

        return null;
    }

    private void RenderMechanicalTab(DataRow row)
    {
        var materialId = row.Table.Columns.Contains("Material ID")
            ? row["Material ID"]?.ToString()?.Trim() ?? string.Empty
            : string.Empty;

        if (string.IsNullOrWhiteSpace(materialId))
        {
            ResetEngineeringDashboard();
            TensileSummaryList.ItemsSource = null;
            MechanicalMetricsList.ItemsSource = null;
            return;
        }

        var tensile = _database.GetTensileTestResult(materialId);
        var summaryMetrics = GetCanonicalTestSummaryMetrics(materialId)
            .Where(m => m.TestType is "Tensile" or "Impact" or "Stiffness" or "Rating")
            .ToList();

        RenderEngineeringDashboard(row, tensile, summaryMetrics);
        RenderChartScores(tensile, summaryMetrics);
        TensileSummaryList.ItemsSource = BuildTensileSummaryFields(tensile);

        var metrics = summaryMetrics
            .Select(m => new
            {
                m.TestType,
                m.MetricName,
                DisplayValue = FormatSummaryMetric(m),
                m.SourceSheet
            })
            .ToList();

        MechanicalMetricsList.ItemsSource = metrics;
    }

    private void RenderEngineeringDashboard(DataRow row, TensileTestResult? tensile, IReadOnlyList<TestSummaryMetric> metrics)
    {
        DashboardMaterialText.Text = DetailTitleText.Text;
        DashboardMaterialSubtitleText.Text = DetailSubtitleText.Text;

        DashboardManufacturerText.Text = DisplayOrDash(DataTableHelpers.FirstValue(row, "Manufacturer", "Brand"));
        DashboardProductLineText.Text = DisplayOrDash(DataTableHelpers.FirstValue(row, "Product Line", "Marketing Name"));

        var materialType = JoinNonEmpty(" / ",
            DataTableHelpers.FirstValue(row, "Base Material", "Type", "Material Type"),
            DataTableHelpers.FirstValue(row, "Category"));
        DashboardMaterialTypeText.Text = DisplayOrDash(materialType);

        var variantColor = JoinNonEmpty(" / ",
            DataTableHelpers.FirstValue(row, "Variant / Finish", "Variant", "Finish"),
            DataTableHelpers.FirstValue(row, "Color", "Colour"));
        DashboardVariantColorText.Text = DisplayOrDash(variantColor);

        DashboardTensileFlatText.Text = tensile?.FlatDisplay ?? "—";
        DashboardTensileUprightText.Text = tensile?.UprightDisplay ?? "—";
        DashboardTensileConsistencyText.Text = tensile is null || !tensile.HasAnyValue
            ? "—"
            : $"Flat CV {tensile.FlatCvDisplay} • Upright CV {tensile.UprightCvDisplay}";
        DashboardTensileSamplesText.Text = tensile is null || !tensile.HasAnyValue
            ? "—"
            : $"Flat {tensile.FlatSamplesDisplay} • Upright {tensile.UprightSamplesDisplay}";
        var tensileReliability = BuildReliabilityRating(
            ParseCvPercent(tensile?.CvFlat),
            ParseCvPercent(tensile?.CvUpright),
            ParseSampleCount(tensile?.SamplesFlat),
            ParseSampleCount(tensile?.SamplesUpright));
        DashboardTensileReliabilityText.Text = tensileReliability.Summary;
        DashboardTensileReliabilityInterpretationText.Text = tensileReliability.Interpretation;

        DashboardImpactFlatText.Text = FormatSummaryMetric(FindMetric(metrics, "Impact", "Flat", "kJ"));
        DashboardImpactUprightText.Text = FormatSummaryMetric(FindMetric(metrics, "Impact", "Upright", "kJ"));
        DashboardImpactConsistencyText.Text = FormatPair(
            "Flat CV", FormatSummaryMetric(FindMetric(metrics, "Impact", "Flat", "CV")),
            "Upright CV", FormatSummaryMetric(FindMetric(metrics, "Impact", "Upright", "CV")));
        var impactFlatCv = FindMetric(metrics, "Impact", "Flat", "CV");
        var impactUprightCv = FindMetric(metrics, "Impact", "Upright", "CV");
        var impactFlatSamples = FindMetric(metrics, "Impact", "Flat", "Samples");
        var impactUprightSamples = FindMetric(metrics, "Impact", "Upright", "Samples");
        DashboardImpactSamplesText.Text = FormatPair(
            "Flat", FormatSummaryMetric(impactFlatSamples),
            "Upright", FormatSummaryMetric(impactUprightSamples));
        var impactReliability = BuildReliabilityRating(
            ParseCvPercent(impactFlatCv?.MetricValue),
            ParseCvPercent(impactUprightCv?.MetricValue),
            ParseSampleCount(impactFlatSamples?.MetricValue),
            ParseSampleCount(impactUprightSamples?.MetricValue));
        DashboardImpactReliabilityText.Text = impactReliability.Summary;
        DashboardImpactReliabilityInterpretationText.Text = impactReliability.Interpretation;

        DashboardStiffnessText.Text = FormatSummaryMetric(FindMetric(metrics, "Stiffness", "Modulus"));


        var nativeTestedStatus = DataTableHelpers.FirstValue(row, "Tested Status", "Test Status", "Tested", "Is Tested");
        var hasNativeTensile = IsTruthy(DataTableHelpers.FirstValue(row, "In Tensile"));
        var hasNativeImpact = IsTruthy(DataTableHelpers.FirstValue(row, "In Impact"));
        var hasNativeStiffness = IsTruthy(DataTableHelpers.FirstValue(row, "In Stiffness"));
        var hasDashboardData = tensile?.HasAnyValue == true || metrics.Count > 0 || hasNativeTensile || hasNativeImpact || hasNativeStiffness;
        var isTested = !string.IsNullOrWhiteSpace(nativeTestedStatus)
            ? !string.Equals(nativeTestedStatus.Trim(), "Not tested", StringComparison.OrdinalIgnoreCase)
            : hasDashboardData;
        DashboardTestedStatusText.Text = BuildStatusLine("Tested", isTested);
        DashboardMechanicalStatusText.Text = BuildStatusLine("Mechanical Data", hasDashboardData);
        DashboardWebsiteStatusText.Text = BuildStatusLine("Website Profile", HasAnyValue(row, "Website Display Name", "Material Key", "Slug", "Product Page"));
        DashboardVideoStatusText.Text = BuildStatusLine("YouTube Review", IsTruthy(DataTableHelpers.FirstValue(row, "YouTube Available", "Video Available")) || HasAnyValue(row, "YouTube Review URL", "YouTube URL"));

        DashboardStatusText.Text = hasDashboardData
            ? "Engineering values come from canonical SQLite measurement rows linked by MaterialID. Canonical metric details remain available below."
            : "No mechanical results are currently linked to this material.";
    }


    private void RenderChartScores(TensileTestResult? tensile, IReadOnlyList<TestSummaryMetric> metrics)
    {
        var profile = _scoringService.BuildProfile(tensile, metrics);

        ChartTensileScoreText.Text = FormatScore(profile.TensileScore);
        ChartImpactScoreText.Text = FormatScore(profile.ImpactScore);
        ChartStiffnessScoreText.Text = FormatScore(profile.StiffnessScore);
        ChartLayerAdhesionScoreText.Text = FormatScore(profile.LayerAdhesionScore);
        ChartConsistencyScoreText.Text = FormatScore(profile.ConsistencyScore);
        ChartOverallScoreText.Text = FormatScore(profile.OverallScore);

        ChartTensileSourceText.Text = profile.TensileSource;
        ChartImpactSourceText.Text = profile.ImpactSource;
        ChartStiffnessSourceText.Text = profile.StiffnessSource;
        ChartLayerAdhesionSourceText.Text = profile.LayerAdhesionSource;
        ChartConsistencySourceText.Text = profile.ConsistencySource;

        ChartScoreNoteText.Text = profile.OverallScore.HasValue
            ? "These are first-pass normalized 0–100 website-radar inputs. They are intended to feed the future radar chart and material comparison tools, not replace the raw measured values."
            : "No score profile is available for this material yet. Import the workbook and select a material with mechanical summary values.";
    }

    private static string FormatScore(double? score)
    {
        return score.HasValue ? $"{score.Value:0}/100" : "—";
    }

    private static string DisplayOrDash(string value) => string.IsNullOrWhiteSpace(value) ? "—" : value.Trim();

    private static string JoinNonEmpty(string separator, params string[] values)
    {
        var nonEmpty = values
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .Select(value => value.Trim())
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();

        return nonEmpty.Count == 0 ? string.Empty : string.Join(separator, nonEmpty);
    }

    private static bool HasAnyValue(DataRow row, params string[] columnNames)
    {
        return columnNames.Any(name => !string.IsNullOrWhiteSpace(DataTableHelpers.FirstValue(row, name)));
    }

    private static bool IsTruthy(string value)
    {
        if (string.IsNullOrWhiteSpace(value)) return false;

        var normalized = value.Trim().ToLowerInvariant();
        return normalized is "1" or "yes" or "true" or "tested" or "available" or "x" or "y";
    }

    private static string BuildStatusLine(string label, bool isAvailable)
    {
        return isAvailable ? $"✓ {label}: Available" : $"• {label}: Not available";
    }


    private sealed record ReliabilityRating(int Stars, string Label, string Interpretation)
    {
        public string Summary => Stars <= 0 ? "—" : $"{new string('★', Stars)}{new string('☆', 5 - Stars)} {Label}";
    }

    private static ReliabilityRating BuildReliabilityRating(double? flatCvPercent, double? uprightCvPercent, double? flatSamples, double? uprightSamples)
    {
        var cvValues = new[] { flatCvPercent, uprightCvPercent }
            .Where(value => value.HasValue)
            .Select(value => value!.Value)
            .ToList();
        var sampleValues = new[] { flatSamples, uprightSamples }
            .Where(value => value.HasValue)
            .Select(value => value!.Value)
            .ToList();

        if (cvValues.Count == 0 && sampleValues.Count == 0)
        {
            return new ReliabilityRating(0, string.Empty, "No canonical reliability data is available for this test yet.");
        }

        var score = ConsistencyCalibrationService.CalculateScore(
            cvValues.Select(value => (double?)value),
            sampleValues.Select(value => (double?)value));
        var rating = ConsistencyCalibrationService.InterpretScore(score);
        return new ReliabilityRating(rating.Stars, rating.Label, rating.Interpretation);
    }

    private static double? ParseCvPercent(string? value)
    {
        if (string.IsNullOrWhiteSpace(value)) return null;
        if (!TryParseDecimalAware(value, out var number)) return null;

        // Workbook CV values are stored as fractions such as 0,065, but some text fields may already be 6,5%.
        return Math.Abs(number) <= 1.0 && !value.Contains('%') ? number * 100.0 : number;
    }

    private static double? ParseSampleCount(string? value)
    {
        if (string.IsNullOrWhiteSpace(value)) return null;
        return TryParseDecimalAware(value, out var number) ? number : null;
    }


    private static string FormatPair(string firstLabel, string firstValue, string secondLabel, string secondValue)
    {
        var first = string.IsNullOrWhiteSpace(firstValue) || firstValue == "—" ? string.Empty : $"{firstLabel} {firstValue}";
        var second = string.IsNullOrWhiteSpace(secondValue) || secondValue == "—" ? string.Empty : $"{secondLabel} {secondValue}";

        var parts = new[] { first, second }
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .ToList();

        return parts.Count == 0 ? "—" : string.Join(" • ", parts);
    }

    private IReadOnlyList<TestSummaryMetric> GetCanonicalTestSummaryMetrics(string materialId)
    {
        var metrics = new List<TestSummaryMetric>();
        void Add(string testType, string name, string? value, string unit)
        {
            if (string.IsNullOrWhiteSpace(value)) return;
            metrics.Add(new TestSummaryMetric
            {
                TestType = testType,
                MetricName = name,
                MetricValue = value,
                Unit = unit,
                SourceSheet = "Canonical SQLite",
                SourceColumn = name
            });
        }

        var tensile = _nativeTensileRows.FirstOrDefault(row => string.Equals(row.MaterialID, materialId, StringComparison.OrdinalIgnoreCase));
        if (tensile is not null)
        {
            ApplyNativeTensileComputedFields(new[] { tensile });
            Add("Tensile", "Upright MPa", tensile.MpaUpright, "MPa");
            Add("Tensile", "Flat MPa", tensile.MpaFlat, "MPa");
            Add("Tensile", "Upright CV", tensile.CvUpright, "%");
            Add("Tensile", "Flat CV", tensile.CvFlat, "%");
            Add("Tensile", "Upright Samples", tensile.SamplesUpright, "");
            Add("Tensile", "Flat Samples", tensile.SamplesFlat, "");
        }

        var impact = _nativeImpactRows.FirstOrDefault(row =>
            string.Equals(row.MaterialID, materialId, StringComparison.OrdinalIgnoreCase) &&
            NativeImpactRowHasMeasurementData(row));
        if (impact is null)
        {
            var canonicalSamples = _database.GetImpactSamples()
                .Where(sample => string.Equals(sample.MaterialId, materialId, StringComparison.OrdinalIgnoreCase))
                .ToList();
            if (canonicalSamples.Count > 0)
            {
                impact = new NativeImpactMeasurementRow { MaterialID = materialId };
                foreach (var sample in canonicalSamples)
                {
                    impact.SetSample(
                        string.Equals(sample.Orientation, "Upright", StringComparison.OrdinalIgnoreCase),
                        sample.SampleNumber,
                        sample.RawValue);
                }
            }
        }
        if (impact is not null)
        {
            ApplyNativeImpactComputedFields(new[] { impact });
            Add("Impact", "Upright kJ", impact.KjUpright, "kJ/m²");
            Add("Impact", "Flat kJ", impact.KjFlat, "kJ/m²");
            Add("Impact", "Upright CV", impact.CvUpright, "%");
            Add("Impact", "Flat CV", impact.CvFlat, "%");
            Add("Impact", "Upright Samples", impact.SamplesUpright, "");
            Add("Impact", "Flat Samples", impact.SamplesFlat, "");
        }

        var stiffness = _nativeStiffnessRows.FirstOrDefault(row =>
            string.Equals(row.MaterialID, materialId, StringComparison.OrdinalIgnoreCase) &&
            NativeStiffnessRowHasMeasurementData(row));
        if (stiffness is null)
        {
            var canonicalInput = _database.GetStiffnessMeasurements()
                .FirstOrDefault(input => string.Equals(input.MaterialId, materialId, StringComparison.OrdinalIgnoreCase));
            if (!string.IsNullOrWhiteSpace(canonicalInput.MaterialId))
            {
                stiffness = new NativeStiffnessMeasurementRow
                {
                    MaterialID = materialId,
                    Revolutions = canonicalInput.Revolutions,
                    Degrees = canonicalInput.Degrees,
                    TestNotes = canonicalInput.TestNotes ?? ""
                };
            }
        }
        if (stiffness is not null)
        {
            ApplyNativeStiffnessComputedFields(new[] { stiffness });
            Add("Stiffness", "Modulus MPa", stiffness.ModulusMpa, "MPa");
            Add("Stiffness", "Deflection mm", stiffness.DeflectionMm, "mm");
        }

        return metrics;
    }

    private void WorkspaceTabs_SelectionChanged(object sender, SelectionChangedEventArgs e)
    {
        if (!ReferenceEquals(e.Source, WorkspaceTabs) ||
            WorkspaceTabs.SelectedItem is not TabItem selectedTab ||
            selectedTab.Header?.ToString() is not { } header)
        {
            return;
        }

        if (string.Equals(header, "AI Assistant", StringComparison.Ordinal))
        {
            RefreshAiAssistantScopePreview();
            return;
        }

        if (string.Equals(header, "Usage", StringComparison.Ordinal))
        {
            RefreshUsageWorkspace();
            return;
        }

        if ((!string.Equals(header, "Settings Manager", StringComparison.Ordinal) &&
             !string.Equals(header, "Base Materials", StringComparison.Ordinal)) ||
            (_embeddedFastNativeSettingsView is not null &&
             _embeddedFastBaseMaterialsView is not null))
        {
            return;
        }

        // The selected tab must never appear ready with an empty Fast host.
        // Native settings/catalog rows are loaded synchronously in the constructor,
        // so the lightweight view creation is safe to complete before selection returns.
        ActivateDefaultFastSettingsViews();
    }

    private static TestSummaryMetric? FindMetric(IEnumerable<TestSummaryMetric> metrics, params string[] terms)
    {
        return metrics.FirstOrDefault(metric =>
        {
            var haystack = $"{metric.TestType} {metric.MetricName} {metric.SourceColumn}";
            return terms.All(term => haystack.Contains(term, StringComparison.OrdinalIgnoreCase));
        });
    }

    private static string FormatSummaryMetric(TestSummaryMetric? metric)
    {
        if (metric is null || string.IsNullOrWhiteSpace(metric.MetricValue)) return "—";

        var unit = metric.Unit ?? string.Empty;
        var raw = metric.MetricValue.Trim();

        if (!IsUsefulNumericMetric(raw)) return raw;

        if (TryParseDecimalAware(raw, out var number))
        {
            var metricName = metric.MetricName ?? string.Empty;
            var isPercent = unit.Contains('%') || metricName.Contains("CV", StringComparison.OrdinalIgnoreCase);
            var value = isPercent && Math.Abs(number) <= 1.0
                ? (number * 100.0).ToString("0.0", CultureInfo.CurrentCulture)
                : number.ToString("0.##", CultureInfo.CurrentCulture);

            if (isPercent && string.IsNullOrWhiteSpace(unit)) unit = "%";
            return string.IsNullOrWhiteSpace(unit) ? value : $"{value} {unit}";
        }

        return string.IsNullOrWhiteSpace(unit) ? raw : $"{raw} {unit}";
    }

    private static bool IsUsefulNumericMetric(string? value)
    {
        if (string.IsNullOrWhiteSpace(value)) return false;
        var text = value.Trim();
        return !text.Equals("Yes", StringComparison.OrdinalIgnoreCase)
            && !text.Equals("No", StringComparison.OrdinalIgnoreCase)
            && !text.Equals("TRUE", StringComparison.OrdinalIgnoreCase)
            && !text.Equals("FALSE", StringComparison.OrdinalIgnoreCase);
    }

    private static bool TryParseDecimalAware(string value, out double number)
    {
        number = 0;
        var cleaned = value
            .Trim()
            .Replace("MPa", string.Empty, StringComparison.OrdinalIgnoreCase)
            .Replace("kJ/m²", string.Empty, StringComparison.OrdinalIgnoreCase)
            .Replace("kJ/m2", string.Empty, StringComparison.OrdinalIgnoreCase)
            .Replace("%", string.Empty, StringComparison.OrdinalIgnoreCase)
            .Trim();

        var cultures = new[]
        {
            CultureInfo.CurrentCulture,
            CultureInfo.GetCultureInfo("is-IS"),
            CultureInfo.GetCultureInfo("da-DK"),
            CultureInfo.GetCultureInfo("en-US")
        };

        foreach (var culture in cultures)
        {
            if (double.TryParse(cleaned, NumberStyles.Float, culture, out number)) return true;
        }

        if (cleaned.Contains(',') && !cleaned.Contains('.'))
        {
            var normalized = cleaned.Replace(',', '.');
            if (double.TryParse(normalized, NumberStyles.Float, CultureInfo.InvariantCulture, out number)) return true;
        }

        return double.TryParse(cleaned, NumberStyles.Float, CultureInfo.InvariantCulture, out number);
    }

    private static IReadOnlyList<MaterialDetailField> BuildTensileSummaryFields(TensileTestResult? tensile)
    {
        if (tensile is null || !tensile.HasAnyValue)
        {
            return new[]
            {
                new MaterialDetailField("Status", "No tensile result imported for this material yet.")
            };
        }

        var fields = new List<MaterialDetailField>
        {
            new("MPa - Upright", tensile.UprightDisplay),
            new("MPa - Flat", tensile.FlatDisplay),
            new("Samples - Upright", tensile.UprightSamplesDisplay),
            new("Samples - Flat", tensile.FlatSamplesDisplay),
            new("Std Dev - Upright", tensile.UprightStdDevDisplay),
            new("Std Dev - Flat", tensile.FlatStdDevDisplay),
            new("CV - Upright", tensile.UprightCvDisplay),
            new("CV - Flat", tensile.FlatCvDisplay),
            new("Confidence - Upright", tensile.UprightConfidenceDisplay),
            new("Confidence - Flat", tensile.FlatConfidenceDisplay)
        };

        if (!string.IsNullOrWhiteSpace(tensile.TestNotes))
        {
            fields.Add(new MaterialDetailField("Test Notes", tensile.TestNotes));
        }

        return fields;
    }


    private void RenderGroupedDetails(DataRow row)
    {
        GroupedDetailsPanel.Children.Clear();
        var materialId = GetCell(row, "Material ID", "MaterialID").Trim();
        var groups = _detailService.BuildGroupedFields(row).ToList();
        var measurementDateFields = BuildMeasurementDateDetailFields(materialId);
        var testInformationIndex = groups.FindIndex(group => string.Equals(group.Name, "Test Information", StringComparison.Ordinal));
        if (testInformationIndex >= 0)
        {
            var testInformation = groups[testInformationIndex];
            groups[testInformationIndex] = new MaterialDetailGroup(
                testInformation.Name,
                testInformation.Fields.Concat(measurementDateFields).ToList());
        }
        else
        {
            groups.Add(new MaterialDetailGroup("Test Information", measurementDateFields));
        }

        foreach (var group in groups)
        {
            var groupBorder = new Border
            {
                Padding = new Thickness(12),
                Margin = new Thickness(0, 0, 0, 12),
                CornerRadius = new CornerRadius(6),
                Background = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(248, 250, 252)),
                BorderBrush = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(226, 232, 240)),
                BorderThickness = new Thickness(1)
            };

            var groupPanel = new StackPanel();
            groupPanel.Children.Add(new TextBlock
            {
                Text = group.Name,
                FontSize = 15,
                FontWeight = FontWeights.SemiBold,
                Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(30, 41, 59)),
                Margin = new Thickness(0, 0, 0, 8)
            });

            var fieldsPanel = new WrapPanel
            {
                Orientation = Orientation.Horizontal
            };

            var useFullWidthRows = string.Equals(group.Name, "Notes", StringComparison.Ordinal) ||
                                   string.Equals(group.Name, "Other", StringComparison.Ordinal);

            foreach (var field in group.Fields)
            {
                var fieldGrid = new Grid
                {
                    Margin = new Thickness(0, 0, 16, 7),
                    Width = useFullWidthRows ? double.NaN : 430,
                    MinWidth = useFullWidthRows ? 0 : 430
                };
                fieldGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(165) });
                fieldGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

                var label = new TextBlock
                {
                    Text = field.Key,
                    FontWeight = FontWeights.SemiBold,
                    Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(71, 85, 105)),
                    TextWrapping = TextWrapping.Wrap,
                    Margin = new Thickness(0, 0, 10, 0)
                };
                var value = new TextBlock
                {
                    Text = field.Value,
                    Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(15, 23, 42)),
                    TextWrapping = TextWrapping.Wrap
                };
                Grid.SetColumn(value, 1);
                fieldGrid.Children.Add(label);
                fieldGrid.Children.Add(value);

                if (useFullWidthRows)
                {
                    fieldGrid.HorizontalAlignment = HorizontalAlignment.Stretch;
                    groupPanel.Children.Add(fieldGrid);
                }
                else
                {
                    fieldsPanel.Children.Add(fieldGrid);
                }
            }

            if (!useFullWidthRows)
            {
                groupPanel.Children.Add(fieldsPanel);
            }

            if (string.Equals(group.Name, "Website", StringComparison.Ordinal))
            {
                foreach (var link in _detailService.BuildLinks(row))
                {
                    var button = new Button
                    {
                        Content = link.Label,
                        HorizontalAlignment = HorizontalAlignment.Left,
                        Margin = new Thickness(0, 3, 0, 4),
                        Padding = new Thickness(10, 5, 10, 5),
                        ToolTip = link.Url,
                        Tag = link.Url
                    };
                    button.Click += OpenUrlButton_Click;
                    groupPanel.Children.Add(button);
                }
            }

            groupBorder.Child = groupPanel;
            GroupedDetailsPanel.Children.Add(groupBorder);
        }

        if (GroupedDetailsPanel.Children.Count == 0)
        {
            GroupedDetailsPanel.Children.Add(new TextBlock
            {
                Text = "No material details are available for this row.",
                Foreground = System.Windows.Media.Brushes.DimGray
            });
        }
    }

    private void WorkflowGrid_ColumnReordered(object? sender, DataGridColumnEventArgs e)
    {
        if (sender is DataGrid grid) QueueWorkflowLayoutSave(grid);
    }

    private void WorkflowGrid_ColumnResizeCompleted(object sender, DragCompletedEventArgs e)
    {
        if (sender is not DataGrid grid ||
            FindVisualParent<DataGridColumnHeader>(e.OriginalSource as DependencyObject) is null)
        {
            return;
        }

        QueueWorkflowLayoutSave(grid);
    }

    private void QueueWorkflowLayoutSave(DataGrid grid)
    {
        _pendingWorkflowLayoutGrid = grid;
        _workflowLayoutSaveDebounceTimer.Stop();
        _workflowLayoutSaveDebounceTimer.Start();
    }

    private void WorkflowLayoutSaveDebounceTimer_Tick(object? sender, EventArgs e)
    {
        _workflowLayoutSaveDebounceTimer.Stop();
        var grid = _pendingWorkflowLayoutGrid;
        _pendingWorkflowLayoutGrid = null;
        if (grid is null || string.IsNullOrWhiteSpace(grid.Name)) return;

        _workflowPreferencesService.CaptureGrid(grid);
        _workflowPreferencesService.Save();
        ShowTransientStatus($"{grid.Name} column layout saved.");
    }

    private static readonly string[] MeasurementDateDetailLabels =
    {
        "Tensile measured",
        "Impact measured",
        "Stiffness measured"
    };

    private IReadOnlyList<MaterialDetailField> BuildMeasurementDateDetailFields(string materialId)
    {
        string Display(string testType)
        {
            if (string.IsNullOrWhiteSpace(materialId)) return "Not recorded";
            var date = ParseIsoMeasuredDate(_database.GetNativeMeasurementDate(materialId, testType));
            return date.HasValue ? FormatDisplayedMeasuredDate(date) : "Not recorded";
        }

        return new[]
        {
            new MaterialDetailField(MeasurementDateDetailLabels[0], Display("Tensile")),
            new MaterialDetailField(MeasurementDateDetailLabels[1], Display("Impact")),
            new MaterialDetailField(MeasurementDateDetailLabels[2], Display("Stiffness"))
        };
    }

    private static void PopulateFilterBox(ComboBox comboBox, DataTable table, string[] possibleColumnNames)
    {
        var oldValue = comboBox.SelectedItem as string;
        var column = DataTableHelpers.FindFirstExistingColumn(table, possibleColumnNames);
        var values = new List<string> { "All" };

        if (column is not null)
        {
            values.AddRange(table.Rows.Cast<DataRow>()
                .Select(r => r[column]?.ToString()?.Trim() ?? string.Empty)
                .Where(v => !string.IsNullOrWhiteSpace(v))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(v => v));
        }

        comboBox.ItemsSource = values;
        comboBox.SelectedItem = values.Contains(oldValue ?? string.Empty) ? oldValue : "All";
    }

    private static void PopulateReinforcementFilterBox(ComboBox comboBox, DataTable table)
    {
        var oldValue = comboBox.SelectedItem as string;
        var column = DataTableHelpers.FindFirstExistingColumn(table, new[] { "Reinforcement", "Reinforment" });
        var values = new List<string> { "All" };
        var hasUnreinforced = false;

        if (column is not null)
        {
            foreach (var value in table.Rows.Cast<DataRow>().Select(r => r[column]?.ToString()?.Trim() ?? string.Empty))
            {
                if (IsUnreinforcedValue(value))
                {
                    hasUnreinforced = true;
                    continue;
                }

                if (!values.Contains(value, StringComparer.OrdinalIgnoreCase))
                {
                    values.Add(value);
                }
            }
        }

        if (hasUnreinforced)
        {
            values.Insert(1, "Unreinforced");
        }

        var sorted = values.Take(1)
            .Concat(values.Skip(1).OrderBy(v => v == "Unreinforced" ? string.Empty : v, StringComparer.CurrentCultureIgnoreCase))
            .ToList();

        comboBox.ItemsSource = sorted;
        comboBox.SelectedItem = sorted.Contains(oldValue ?? string.Empty) ? oldValue : "All";
    }


    private static bool IsUnreinforcedValue(string? value)
    {
        if (string.IsNullOrWhiteSpace(value) || value.Trim() == "—") return true;

        var normalized = value.Trim();
        return normalized.Equals("none", StringComparison.OrdinalIgnoreCase)
            || normalized.Equals("no", StringComparison.OrdinalIgnoreCase)
            || normalized.Equals("pure", StringComparison.OrdinalIgnoreCase)
            || normalized.Equals("unreinforced", StringComparison.OrdinalIgnoreCase)
            || normalized.Equals("__none__", StringComparison.OrdinalIgnoreCase);
    }

    private static bool ReinforcementFilterMatches(string? rowValue, string? filterValue)
    {
        if (string.IsNullOrWhiteSpace(filterValue) || filterValue == "All") return true;
        if (filterValue.Equals("Unreinforced", StringComparison.OrdinalIgnoreCase)) return IsUnreinforcedValue(rowValue);
        return string.Equals((rowValue ?? string.Empty).Trim(), filterValue.Trim(), StringComparison.OrdinalIgnoreCase);
    }

