    private void InitializeAnalyticsControls()
    {
        AnalyticsChartMode.ItemsSource = new[]
        {
            new AnalyticsChartModeOption { Key = "samples", Label = "All filament samples" },
            new AnalyticsChartModeOption { Key = "materialType", Label = "Average by material type" },
            new AnalyticsChartModeOption { Key = "manufacturer", Label = "Average by manufacturer" },
            new AnalyticsChartModeOption { Key = "productLine", Label = "Average by product line" },
            new AnalyticsChartModeOption { Key = "variant", Label = "Average by variant / finish" },
            new AnalyticsChartModeOption { Key = "reinforcement", Label = "Average by reinforcement" }
        };
        AnalyticsChartMode.SelectedIndex = 0;
    }

    private void AnalyticsChartMode_SelectionChanged(object sender, SelectionChangedEventArgs e)
    {
        if (!IsLoaded) return;
        UpdateAnalyticsFramework();
    }

    private void UpdateAnalyticsFramework()
    {
        if (AnalyticsResultsList is null) return;

        var visibleRows = GetCanonicalVisibleMaterialRows();
        var mode = (AnalyticsChartMode.SelectedItem as AnalyticsChartModeOption)?.Key ?? "samples";
        var scores = visibleRows
            .Select(BuildAnalyticsMaterialScore)
            .Where(score => score.Profile.OverallScore.HasValue)
            .ToList();

        IReadOnlyList<AnalyticsDisplayRow> rows = mode == "samples"
            ? scores.Select(score => new AnalyticsDisplayRow
            {
                Label = score.Label,
                Count = 1,
                Tensile = score.Profile.TensileScore,
                Impact = score.Profile.ImpactScore,
                Stiffness = score.Profile.StiffnessScore,
                Consistency = score.Profile.ConsistencyScore,
                LayerAdhesion = score.Profile.LayerAdhesionScore,
                Overall = score.Profile.OverallScore,
                TensileDisplay = FormatScore(score.Profile.TensileScore),
                ImpactDisplay = FormatScore(score.Profile.ImpactScore),
                StiffnessDisplay = FormatScore(score.Profile.StiffnessScore),
                ConsistencyDisplay = FormatScore(score.Profile.ConsistencyScore),
                LayerAdhesionDisplay = FormatScore(score.Profile.LayerAdhesionScore),
                OverallDisplay = FormatScore(score.Profile.OverallScore)
            })
            .OrderByDescending(row => ParseScoreForSorting(row.OverallDisplay))
            .ThenBy(row => row.Label, StringComparer.CurrentCultureIgnoreCase)
            .ToList()
            : BuildGroupedAnalyticsRows(scores, mode);

        var modeLabel = (AnalyticsChartMode.SelectedItem as AnalyticsChartModeOption)?.Label ?? "All filament samples";
        _currentAnalyticsRows = rows;
        _currentAnalyticsModeLabel = modeLabel;

        _isUpdatingAnalyticsGrid = true;
        AnalyticsResultsList.ItemsSource = rows;
        AnalyticsResultsList.SelectedItems.Clear();
        _isUpdatingAnalyticsGrid = false;

        AnalyticsStatusText.Text = $"{modeLabel}: {rows.Count} row{(rows.Count == 1 ? string.Empty : "s")} from {visibleRows.Count} visible material{(visibleRows.Count == 1 ? string.Empty : "s")}. Select one or more rows to control the radar overlay.";
        RenderAnalyticsRadar(rows, modeLabel);
    }

    private void AnalyticsResultsList_SelectionChanged(object sender, SelectionChangedEventArgs e)
    {
        if (_isUpdatingAnalyticsGrid) return;
        RenderAnalyticsRadar(_currentAnalyticsRows, _currentAnalyticsModeLabel);
    }

    private void ClearAnalyticsSelection_Click(object sender, RoutedEventArgs e)
    {
        AnalyticsResultsList.SelectedItems.Clear();
        RenderAnalyticsRadar(_currentAnalyticsRows, _currentAnalyticsModeLabel);
    }


    private sealed class RadarLegendItem
    {
        public string Text { get; init; } = string.Empty;
        public Brush Brush { get; init; } = Brushes.Transparent;
        public override string ToString() => Text;
    }

    private void RenderAnalyticsRadar(IReadOnlyList<AnalyticsDisplayRow> rows, string modeLabel)
    {
        if (AnalyticsRadarCanvas is null) return;

        AnalyticsRadarCanvas.Children.Clear();
        AnalyticsRadarLegend.ItemsSource = null;

        const double size = 430;
        const double center = size / 2.0;
        const double radius = 150.0;
        var axes = new[] { "Tensile", "Impact", "Stiffness", "Layer Adhesion", "Consistency" };
        var selectedRows = AnalyticsResultsList?.SelectedItems
            .OfType<AnalyticsDisplayRow>()
            .Where(row => row.Overall.HasValue)
            .ToList() ?? new List<AnalyticsDisplayRow>();

        var visibleRows = selectedRows.Count > 0
            ? selectedRows.Take(6).ToList()
            : rows
                .Where(row => row.Overall.HasValue)
                .OrderByDescending(row => row.Overall)
                .Take(6)
                .ToList();

        DrawRadarGrid(center, radius, axes);

        if (visibleRows.Count == 0)
        {
            AddCanvasText("No radar data available for the current filters.", center - 120, center - 10, 14, Brushes.White);
            AnalyticsRadarSubtitle.Text = "No radar data available";
            return;
        }

        var brushes = new[]
        {
            Color.FromRgb(37, 99, 235),
            Color.FromRgb(22, 163, 74),
            Color.FromRgb(234, 88, 12),
            Color.FromRgb(147, 51, 234),
            Color.FromRgb(14, 165, 233),
            Color.FromRgb(220, 38, 38)
        };

        foreach (var row in rows)
        {
            row.RadarBrush = Brushes.Transparent;
            row.RadarRowBackground = Brushes.Transparent;
        }

        var legendItems = new List<RadarLegendItem>();

        for (var i = 0; i < visibleRows.Count; i++)
        {
            var color = brushes[i % brushes.Length];
            var brush = new SolidColorBrush(color);
            var row = visibleRows[i];

            row.RadarBrush = brush;
            row.RadarRowBackground = new SolidColorBrush(Color.FromArgb(30, color.R, color.G, color.B));

            DrawRadarProfile(row, center, radius, color);
            legendItems.Add(new RadarLegendItem
            {
                Brush = brush,
                Text = $"{row.Label} — {row.OverallDisplay}"
            });
        }

        AnalyticsResultsList?.Items.Refresh();

        if (selectedRows.Count > 0)
        {
            AnalyticsRadarSubtitle.Text = selectedRows.Count > 6
                ? $"{modeLabel}: showing first 6 of {selectedRows.Count} selected profiles"
                : $"{modeLabel}: showing {visibleRows.Count} selected profile{(visibleRows.Count == 1 ? string.Empty : "s")}";
        }
        else
        {
            AnalyticsRadarSubtitle.Text = $"{modeLabel}: showing top {visibleRows.Count} profile{(visibleRows.Count == 1 ? string.Empty : "s")} by overall score";
        }

        AnalyticsRadarLegend.ItemsSource = legendItems;
    }

    private void DrawRadarGrid(double center, double radius, string[] axes)
    {
        for (var ring = 1; ring <= 5; ring++)
        {
            var ringRadius = radius * ring / 5.0;
            var polygon = new Polygon
            {
                Stroke = new SolidColorBrush(Color.FromRgb(51, 65, 85)),
                StrokeThickness = 1,
                Fill = Brushes.Transparent
            };

            foreach (var point in RadarPoints(Enumerable.Repeat(ring * 20.0, axes.Length).Select(v => (double?)v).ToArray(), center, radius))
            {
                polygon.Points.Add(point);
            }

            AnalyticsRadarCanvas.Children.Add(polygon);
            AddCanvasText((ring * 20).ToString(CultureInfo.CurrentCulture), center + 4, center - ringRadius - 8, 11, new SolidColorBrush(Color.FromRgb(148, 163, 184)));
        }

        for (var i = 0; i < axes.Length; i++)
        {
            var end = RadarPoint(i, axes.Length, 100, center, radius);
            AnalyticsRadarCanvas.Children.Add(new Line
            {
                X1 = center,
                Y1 = center,
                X2 = end.X,
                Y2 = end.Y,
                Stroke = new SolidColorBrush(Color.FromRgb(71, 85, 105)),
                StrokeThickness = 1
            });

            var label = RadarPoint(i, axes.Length, 118, center, radius);
            AddCanvasText(axes[i], label.X - 42, label.Y - 10, 13, new SolidColorBrush(Color.FromRgb(226, 232, 240)));
        }
    }

    private void DrawRadarProfile(AnalyticsDisplayRow row, double center, double radius, Color color)
    {
        var values = new[] { row.Tensile, row.Impact, row.Stiffness, row.LayerAdhesion, row.Consistency };
        var points = RadarPoints(values, center, radius).ToList();
        var stroke = new SolidColorBrush(color);
        var fill = new SolidColorBrush(Color.FromArgb(48, color.R, color.G, color.B));

        var polygon = new Polygon
        {
            Stroke = stroke,
            StrokeThickness = 2,
            Fill = fill
        };

        foreach (var point in points)
        {
            polygon.Points.Add(point);
        }

        AnalyticsRadarCanvas.Children.Add(polygon);

        foreach (var point in points)
        {
            var marker = new Ellipse
            {
                Width = 6,
                Height = 6,
                Fill = stroke,
                Stroke = Brushes.White,
                StrokeThickness = 1
            };
            Canvas.SetLeft(marker, point.X - 3);
            Canvas.SetTop(marker, point.Y - 3);
            AnalyticsRadarCanvas.Children.Add(marker);
        }
    }

    private static IEnumerable<Point> RadarPoints(IReadOnlyList<double?> values, double center, double radius)
    {
        for (var i = 0; i < values.Count; i++)
        {
            yield return RadarPoint(i, values.Count, Math.Clamp(values[i] ?? 0, 0, 100), center, radius);
        }
    }

    private static Point RadarPoint(int index, int count, double value, double center, double radius)
    {
        var angle = -Math.PI / 2.0 + index * 2.0 * Math.PI / count;
        var scaled = radius * value / 100.0;
        return new Point(center + Math.Cos(angle) * scaled, center + Math.Sin(angle) * scaled);
    }

    private void AddCanvasText(string text, double x, double y, double fontSize, Brush brush)
    {
        var block = new TextBlock
        {
            Text = text,
            FontSize = fontSize,
            Foreground = brush,
            TextWrapping = TextWrapping.NoWrap
        };
        Canvas.SetLeft(block, x);
        Canvas.SetTop(block, y);
        AnalyticsRadarCanvas.Children.Add(block);
    }

    private AnalyticsMaterialScore BuildAnalyticsMaterialScore(DataRow row)
    {
        var materialId = row.Table.Columns.Contains("Material ID")
            ? row["Material ID"]?.ToString()?.Trim() ?? string.Empty
            : string.Empty;
        var tensile = _database.GetTensileTestResult(materialId);
        var metrics = GetCanonicalTestSummaryMetrics(materialId)
            .Where(m => m.TestType is "Tensile" or "Impact" or "Stiffness" or "Rating")
            .ToList();

        return new AnalyticsMaterialScore
        {
            Label = _detailService.BuildTitle(row),
            Manufacturer = DataTableHelpers.FirstValue(row, "Manufacturer", "Brand") ?? "",
            ProductLine = DataTableHelpers.FirstValue(row, "Product Line", "ProductLine") ?? "",
            BaseMaterial = DataTableHelpers.FirstValue(row, "Base Material", "Type", "Material Type") ?? "",
            Variant = DataTableHelpers.FirstValue(row, "Variant / Finish", "Variant", "Finish") ?? "",
            Reinforcement = DataTableHelpers.FirstValue(row, "Reinforcement", "Reinforment") ?? "",
            Profile = _scoringService.BuildProfile(tensile, metrics)
        };
    }

    private static IReadOnlyList<AnalyticsDisplayRow> BuildGroupedAnalyticsRows(IReadOnlyList<AnalyticsMaterialScore> scores, string mode)
    {
        return scores
            .GroupBy(score => GroupKeyForMode(score, mode), StringComparer.OrdinalIgnoreCase)
            .Where(group => !string.IsNullOrWhiteSpace(group.Key))
            .Select(group =>
            {
                var items = group.ToList();
                var profile = AverageProfile(items.Select(item => item.Profile));
                return new AnalyticsDisplayRow
                {
                    Label = group.Key,
                    Count = items.Count,
                    Tensile = profile.TensileScore,
                    Impact = profile.ImpactScore,
                    Stiffness = profile.StiffnessScore,
                    Consistency = profile.ConsistencyScore,
                    LayerAdhesion = profile.LayerAdhesionScore,
                    Overall = profile.OverallScore,
                    TensileDisplay = FormatScore(profile.TensileScore),
                    ImpactDisplay = FormatScore(profile.ImpactScore),
                    StiffnessDisplay = FormatScore(profile.StiffnessScore),
                    ConsistencyDisplay = FormatScore(profile.ConsistencyScore),
                    LayerAdhesionDisplay = FormatScore(profile.LayerAdhesionScore),
                    OverallDisplay = FormatScore(profile.OverallScore)
                };
            })
            .OrderByDescending(row => ParseScoreForSorting(row.OverallDisplay))
            .ThenBy(row => row.Label, StringComparer.CurrentCultureIgnoreCase)
            .ToList();
    }

    private static string GroupKeyForMode(AnalyticsMaterialScore score, string mode)
    {
        var value = mode switch
        {
            "materialType" => score.BaseMaterial,
            "manufacturer" => score.Manufacturer,
            "productLine" => score.ProductLine,
            "variant" => score.Variant,
            "reinforcement" => string.IsNullOrWhiteSpace(score.Reinforcement) ? "Unreinforced" : score.Reinforcement,
            _ => score.Label
        };

        return string.IsNullOrWhiteSpace(value) ? "(blank)" : value.Trim();
    }

    private static EngineeringScoreProfile AverageProfile(IEnumerable<EngineeringScoreProfile> profiles)
    {
        var list = profiles.ToList();
        return new EngineeringScoreProfile
        {
            TensileScore = AverageNullable(list.Select(p => p.TensileScore)),
            ImpactScore = AverageNullable(list.Select(p => p.ImpactScore)),
            StiffnessScore = AverageNullable(list.Select(p => p.StiffnessScore)),
            ConsistencyScore = AverageNullable(list.Select(p => p.ConsistencyScore)),
            LayerAdhesionScore = AverageNullable(list.Select(p => p.LayerAdhesionScore)),
            OverallScore = AverageNullable(list.Select(p => p.OverallScore))
        };
    }

    private static double? AverageNullable(IEnumerable<double?> values)
    {
        var available = values.Where(v => v.HasValue).Select(v => v!.Value).ToList();
        return available.Count == 0 ? null : available.Average();
    }

    private static double ParseScoreForSorting(string display)
    {
        var cleaned = display.Replace("/100", string.Empty, StringComparison.OrdinalIgnoreCase).Trim();
        return double.TryParse(cleaned, NumberStyles.Float, CultureInfo.CurrentCulture, out var value) ? value : double.MinValue;
    }


