    private void PopulateComparisonSelectors(DataTable table)
    {
        _isUpdatingComparisonSelectors = true;
        var options = new List<ComparisonMaterialOption>
        {
            new() { MaterialId = string.Empty, Label = "— Not selected —", Row = null }
        };

        options.AddRange(table.Rows.Cast<DataRow>()
            .Select(row => new ComparisonMaterialOption
            {
                MaterialId = row.Table.Columns.Contains("Material ID") ? row["Material ID"]?.ToString()?.Trim() ?? string.Empty : string.Empty,
                Label = _detailService.BuildTitle(row),
                Row = row
            })
            .Where(option => !string.IsNullOrWhiteSpace(option.MaterialId))
            .OrderBy(option => option.Label, StringComparer.CurrentCultureIgnoreCase));

        SetComparisonItems(CompareMaterialA, options, 1);
        SetComparisonItems(CompareMaterialB, options, 2);
        SetComparisonItems(CompareMaterialC, options, 0);
        SetComparisonItems(CompareMaterialD, options, 0);
        _isUpdatingComparisonSelectors = false;
        UpdateComparisonWorkbench();
    }

    private static void SetComparisonItems(ComboBox comboBox, IReadOnlyList<ComparisonMaterialOption> options, int preferredIndex)
    {
        var previousId = (comboBox.SelectedItem as ComparisonMaterialOption)?.MaterialId;
        comboBox.ItemsSource = options;

        var selected = !string.IsNullOrWhiteSpace(previousId)
            ? options.FirstOrDefault(option => option.MaterialId == previousId)
            : null;

        comboBox.SelectedItem = selected ?? options[Math.Min(preferredIndex, options.Count - 1)];
    }

