    private void UseSelectedForComparison_Click(object sender, RoutedEventArgs e)
    {
        var selectedId = CurrentSelectedMaterialId();
        if (string.IsNullOrWhiteSpace(selectedId)) return;

        var options = CompareMaterialA.ItemsSource?.Cast<ComparisonMaterialOption>().ToList() ?? new List<ComparisonMaterialOption>();
        var match = options.FirstOrDefault(option => option.MaterialId == selectedId);
        if (match is not null)
        {
            CompareMaterialA.SelectedItem = match;
            UpdateComparisonWorkbench();
