    private void UpdateComparisonWorkbench()
    {
        if (ComparisonMetricsList is null || ComparisonScoresList is null) return;

        var selections = new[]
        {
            CompareMaterialA.SelectedItem as ComparisonMaterialOption,
            CompareMaterialB.SelectedItem as ComparisonMaterialOption,
            CompareMaterialC.SelectedItem as ComparisonMaterialOption,
            CompareMaterialD.SelectedItem as ComparisonMaterialOption
        };

        var snapshots = selections
            .Select(option => option?.Row is null ? null : BuildComparisonSnapshot(option.Row))
            .ToArray();

        UpdateComparisonColumnHeaders(snapshots);
        ComparisonMetricsList.ItemsSource = BuildComparisonMetricRows(snapshots);
        ComparisonScoresList.ItemsSource = BuildComparisonScoreRows(snapshots);

        var selectedCount = snapshots.Count(snapshot => snapshot is not null);
        ComparisonStatusText.Text = selectedCount == 0
            ? "Select two or more materials to compare."
            : $"Comparing {selectedCount} material{(selectedCount == 1 ? string.Empty : "s")}. Winning cells are highlighted; non-winning values show their delta versus the best value.";
    }

    private ComparisonSnapshot BuildComparisonSnapshot(DataRow row)
    {
        var materialId = row.Table.Columns.Contains("Material ID")
            ? row["Material ID"]?.ToString()?.Trim() ?? string.Empty
            : string.Empty;

        var tensile = _database.GetTensileTestResult(materialId);
        var metrics = GetCanonicalTestSummaryMetrics(materialId)
            .Where(m => m.TestType is "Tensile" or "Impact" or "Stiffness" or "Rating")
            .ToList();
        var profile = _scoringService.BuildProfile(tensile, metrics);

        var impactFlat = FindMetric(metrics, "Impact", "Flat", "kJ");
        var impactUpright = FindMetric(metrics, "Impact", "Upright", "kJ");
        var stiffness = FindMetric(metrics, "Stiffness", "Modulus");

        return new ComparisonSnapshot
        {
            MaterialId = materialId,
            Label = _detailService.BuildTitle(row),
            TensileFlat = ParseSampleCount(tensile?.FlatMpa),
            TensileFlatDisplay = tensile?.FlatDisplay ?? "—",
            TensileUpright = ParseSampleCount(tensile?.UprightMpa),
            TensileUprightDisplay = tensile?.UprightDisplay ?? "—",
            ImpactFlat = ParseSampleCount(impactFlat?.MetricValue),
            ImpactFlatDisplay = FormatSummaryMetric(impactFlat),
            ImpactUpright = ParseSampleCount(impactUpright?.MetricValue),
            ImpactUprightDisplay = FormatSummaryMetric(impactUpright),
            Stiffness = ParseSampleCount(stiffness?.MetricValue),
            StiffnessDisplay = FormatSummaryMetric(stiffness),
            Profile = profile
        };
    }

    private static IReadOnlyList<ComparisonDisplayRow> BuildComparisonMetricRows(IReadOnlyList<ComparisonSnapshot?> snapshots)
    {
        return new[]
        {
            BuildComparisonRow("Tensile Flat", snapshots, s => s?.TensileFlatDisplay, s => s?.TensileFlat),
            BuildComparisonRow("Tensile Upright", snapshots, s => s?.TensileUprightDisplay, s => s?.TensileUpright),
            BuildComparisonRow("Impact Flat", snapshots, s => s?.ImpactFlatDisplay, s => s?.ImpactFlat),
            BuildComparisonRow("Impact Upright", snapshots, s => s?.ImpactUprightDisplay, s => s?.ImpactUpright),
            BuildComparisonRow("Stiffness", snapshots, s => s?.StiffnessDisplay, s => s?.Stiffness)
        };
    }

    private static IReadOnlyList<ComparisonDisplayRow> BuildComparisonScoreRows(IReadOnlyList<ComparisonSnapshot?> snapshots)
    {
        return new[]
        {
            BuildComparisonRow("Tensile Score", snapshots, s => FormatScore(s?.Profile.TensileScore), s => s?.Profile.TensileScore),
            BuildComparisonRow("Impact Score", snapshots, s => FormatScore(s?.Profile.ImpactScore), s => s?.Profile.ImpactScore),
            BuildComparisonRow("Stiffness Score", snapshots, s => FormatScore(s?.Profile.StiffnessScore), s => s?.Profile.StiffnessScore),
            BuildComparisonRow("Consistency Score", snapshots, s => FormatScore(s?.Profile.ConsistencyScore), s => s?.Profile.ConsistencyScore),
            BuildComparisonRow("Layer Adhesion Score", snapshots, s => FormatScore(s?.Profile.LayerAdhesionScore), s => s?.Profile.LayerAdhesionScore),
            BuildComparisonRow("Overall Profile", snapshots, s => FormatScore(s?.Profile.OverallScore), s => s?.Profile.OverallScore)
        };
    }

    private static ComparisonDisplayRow BuildComparisonRow(
        string metric,
        IReadOnlyList<ComparisonSnapshot?> snapshots,
        Func<ComparisonSnapshot?, string?> displaySelector,
        Func<ComparisonSnapshot?, double?> numericSelector)
    {
        var displays = snapshots.Select(snapshot => displaySelector(snapshot) ?? "—").ToArray();
        var values = snapshots.Select(snapshot => numericSelector(snapshot)).ToArray();
        var bestIndexes = FindBestIndexes(values);
        var best = BuildBestText(snapshots, values, bestIndexes);

        return new ComparisonDisplayRow
        {
            Metric = metric,
            A = BuildComparisonCell(displays.ElementAtOrDefault(0) ?? "—", values.ElementAtOrDefault(0), values, bestIndexes, 0),
            B = BuildComparisonCell(displays.ElementAtOrDefault(1) ?? "—", values.ElementAtOrDefault(1), values, bestIndexes, 1),
            C = BuildComparisonCell(displays.ElementAtOrDefault(2) ?? "—", values.ElementAtOrDefault(2), values, bestIndexes, 2),
            D = BuildComparisonCell(displays.ElementAtOrDefault(3) ?? "—", values.ElementAtOrDefault(3), values, bestIndexes, 3),
            Best = best
        };
    }

    private static ComparisonCell BuildComparisonCell(
        string display,
        double? value,
        IReadOnlyList<double?> values,
        IReadOnlyList<int> bestIndexes,
        int index)
    {
        if (!value.HasValue || string.IsNullOrWhiteSpace(display) || display == "—")
        {
            return ComparisonCell.Empty;
        }

        var isWinner = bestIndexes.Contains(index);
        return new ComparisonCell
        {
            Display = isWinner ? display : AppendDelta(display, value.Value, values, bestIndexes),
            IsWinner = isWinner
        };
    }

    private static string AppendDelta(string display, double value, IReadOnlyList<double?> values, IReadOnlyList<int> bestIndexes)
    {
        if (bestIndexes.Count == 0) return display;

        var bestValue = bestIndexes
            .Select(index => values.ElementAtOrDefault(index))
            .Where(v => v.HasValue)
            .Select(v => v!.Value)
            .DefaultIfEmpty(double.NaN)
            .First();

        if (double.IsNaN(bestValue) || Math.Abs(bestValue) < 0.000001) return display;

        var deltaPercent = (value / bestValue - 1.0) * 100.0;
        if (Math.Abs(deltaPercent) < 0.05) return display;

        var deltaText = deltaPercent > 0
            ? $"+{deltaPercent:0.#}%"
            : $"{deltaPercent:0.#}%";

        return $"{display} ({deltaText})";
    }

    private static IReadOnlyList<int> FindBestIndexes(IReadOnlyList<double?> values)
    {
        var available = values
            .Select((value, index) => new { Value = value, Index = index })
            .Where(item => item.Value.HasValue)
            .ToList();

        if (available.Count == 0) return Array.Empty<int>();

        var bestValue = available.Max(item => item.Value!.Value);
        return available
            .Where(item => Math.Abs(item.Value!.Value - bestValue) < 0.000001)
            .Select(item => item.Index)
            .ToList();
    }

    private static string BuildBestText(
        IReadOnlyList<ComparisonSnapshot?> snapshots,
        IReadOnlyList<double?> values,
        IReadOnlyList<int> bestIndexes)
    {
        if (bestIndexes.Count == 0) return "—";

        var labels = bestIndexes
            .Select(index => snapshots[index]?.Label)
            .Where(label => !string.IsNullOrWhiteSpace(label))
            .ToList();

        return labels.Count == 0 ? "—" : string.Join(" / ", labels);
    }

    private static void SetComparisonHeader(DataGridTemplateColumn column, ComparisonSnapshot? snapshot, string fallback)
    {
        column.Header = snapshot is null || string.IsNullOrWhiteSpace(snapshot.Label)
            ? fallback
            : ShortenComparisonHeader(snapshot.Label);
    }

    private static string ShortenComparisonHeader(string label)
    {
        const int maxLength = 34;
        return label.Length <= maxLength ? label : label[..(maxLength - 1)] + "…";
    }

    private void UpdateComparisonColumnHeaders(IReadOnlyList<ComparisonSnapshot?> snapshots)
    {
        SetComparisonHeader(ComparisonMetricColumnA, snapshots.ElementAtOrDefault(0), "Material A");
        SetComparisonHeader(ComparisonMetricColumnB, snapshots.ElementAtOrDefault(1), "Material B");
        SetComparisonHeader(ComparisonMetricColumnC, snapshots.ElementAtOrDefault(2), "Material C");
        SetComparisonHeader(ComparisonMetricColumnD, snapshots.ElementAtOrDefault(3), "Material D");

        SetComparisonHeader(ComparisonScoreColumnA, snapshots.ElementAtOrDefault(0), "Material A");
        SetComparisonHeader(ComparisonScoreColumnB, snapshots.ElementAtOrDefault(1), "Material B");
        SetComparisonHeader(ComparisonScoreColumnC, snapshots.ElementAtOrDefault(2), "Material C");
        SetComparisonHeader(ComparisonScoreColumnD, snapshots.ElementAtOrDefault(3), "Material D");
    }



