        SelectComboValue(RankingReinforcementFilter, "All");
        SelectComboValue(RankingLimitFilter, "Top 25");
        UpdateRankings();
    }

    private void UpdateRankings()
    {
        if (RankingsGrid is null) return;

        var visibleRows = GetCanonicalVisibleMaterialRows();
        if (visibleRows.Count == 0)
        {
            RankingsGrid.ItemsSource = null;
            RankingStatusText.Text = "Load Materials data to build rankings.";
            RankingSummaryText.Text = "No rankings yet";
            return;
        }

        var metric = SelectedComboText(RankingMetricFilter);
        if (string.IsNullOrWhiteSpace(metric)) metric = "Overall";

        var rows = BuildCanonicalVisiblePlannerRows()
            .Select(row => BuildRankingRow(row, metric))
            .Where(row => row.RankScore.HasValue)
            .ToList();

        var baseMaterial = SelectedComboText(RankingBaseMaterialFilter);
        if (!string.IsNullOrWhiteSpace(baseMaterial) && baseMaterial != "All")
        {
            rows = rows.Where(row => row.BaseMaterial.Equals(baseMaterial, StringComparison.OrdinalIgnoreCase)).ToList();
        }

        var manufacturer = SelectedComboText(RankingManufacturerFilter);
        if (!string.IsNullOrWhiteSpace(manufacturer) && manufacturer != "All")
        {
            rows = rows.Where(row => row.Manufacturer.Equals(manufacturer, StringComparison.OrdinalIgnoreCase)).ToList();
        }

        var reinforcement = SelectedComboText(RankingReinforcementFilter);
        if (!string.IsNullOrWhiteSpace(reinforcement) && reinforcement != "All")
        {
            rows = rows.Where(row => ReinforcementFilterMatches(row.Reinforcement, reinforcement)).ToList();
        }

        rows = rows
            .OrderByDescending(row => row.RankScore ?? double.MinValue)
            .ThenByDescending(row => row.Overall ?? double.MinValue)
            .ThenBy(row => row.Label, StringComparer.CurrentCultureIgnoreCase)
            .ToList();

        var rankedTotal = rows.Count;
        var limit = RankingLimit();
        if (limit.HasValue) rows = rows.Take(limit.Value).ToList();

        for (var i = 0; i < rows.Count; i++) rows[i].Rank = i + 1;

        RankingsGrid.ItemsSource = rows;
        if (rankedTotal == 0)
        {
            RankingSummaryText.Text = "No ranked rows";
            RankingStatusText.Text = $"No ranking results for {metric}. Try Reset Filters, another metric, or clearing the Materials tab search/filter.";
            return;
        }

        RankingSummaryText.Text = $"{rankedTotal} ranked material{(rankedTotal == 1 ? string.Empty : "s")}";
        RankingStatusText.Text = $"Ranking by {metric}. Showing {rows.Count} of {rankedTotal} ranked material{(rankedTotal == 1 ? string.Empty : "s")} from {visibleRows.Count} visible material{(visibleRows.Count == 1 ? string.Empty : "s")}. Filters/search from the Materials tab are included.";
    }

    private RankingRow BuildRankingRow(VideoPlannerRow row, string metric)
    {
        var rankScore = metric switch
        {
            "Tensile" => row.TensileScore,
            "Impact" => row.ImpactScore,
            "Stiffness" => row.StiffnessScore,
            "Consistency" => row.ConsistencyScore,
            "Layer Adhesion" => row.LayerAdhesionScore,
            _ => row.OverallScore
        };

        return new RankingRow
        {
            MaterialId = row.MaterialId,
            Label = row.Label,
            Manufacturer = row.Manufacturer,
            BaseMaterial = row.BaseMaterial,
            Reinforcement = string.IsNullOrWhiteSpace(row.Reinforcement) ? "—" : row.Reinforcement,
            Status = row.Status,
            RankScore = rankScore,
            Overall = row.OverallScore,
            Tensile = row.TensileScore,
            Impact = row.ImpactScore,
            Stiffness = row.StiffnessScore,
            Consistency = row.ConsistencyScore,
            LayerAdhesion = row.LayerAdhesionScore,
            PricePerKg = row.PricePerKg,
            BestAxis = BestProfileDimension(new EngineeringScoreProfile
            {
                OverallScore = row.OverallScore,
                TensileScore = row.TensileScore,
                ImpactScore = row.ImpactScore,
                StiffnessScore = row.StiffnessScore,
                ConsistencyScore = row.ConsistencyScore,
                LayerAdhesionScore = row.LayerAdhesionScore
            })
        };
    }

    private int? RankingLimit()
    {
        var selected = SelectedComboText(RankingLimitFilter);
        return selected switch
        {
            "Top 10" => 10,
            "Top 25" => 25,
            "Top 50" => 50,
            "Top 100" => 100,
            _ => null
        };
    }

    private void ExportRankingsCsv_Click(object sender, RoutedEventArgs e)
    {
        var rows = RankingsGrid?.ItemsSource is IEnumerable<RankingRow> rankingRows
            ? rankingRows.ToList()
            : new List<RankingRow>();

        if (rows.Count == 0)
        {
            MessageBox.Show(this, "There are no ranking rows to export yet.", "Export Rankings", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }

        var dialog = new SaveFileDialog
        {
            Title = "Export Rankings CSV",
            Filter = "CSV file (*.csv)|*.csv|All files (*.*)|*.*",
            FileName = "3dp-iceland-rankings-v20-5.csv"
        };

        if (dialog.ShowDialog(this) != true) return;

        var lines = new List<string>
        {
            CsvLine("Rank", "Material", "Manufacturer", "Base Material", "Reinforcement", "Rank Score", "Overall", "Tensile", "Impact", "Stiffness", "Consistency", "Layer Adhesion", "Best Axis", "Status")
        };

        lines.AddRange(rows.Select(row => CsvLine(
            row.Rank.ToString(CultureInfo.InvariantCulture),
            row.Label,
            row.Manufacturer,
            row.BaseMaterial,
            row.Reinforcement,
            row.RankScoreText,
            row.OverallText,
            row.TensileText,
            row.ImpactText,
            row.StiffnessText,
            row.ConsistencyText,
            row.LayerAdhesionText,
            row.BestAxis,
            row.Status)));

        File.WriteAllLines(dialog.FileName, lines);
        RankingStatusText.Text = $"Exported {rows.Count} ranking rows to {System.IO.Path.GetFileName(dialog.FileName)}.";
    }

    private static string CsvLine(params string?[] values) => string.Join(",", values.Select(CsvValue));

    private static string CsvValue(string? value)
    {
        var text = value ?? string.Empty;
        return $"\"{text.Replace("\"", "\"\"")}" + "\"";
    }



