    private void UpdateCategoryRankings()
    {
        if (CategoryRankingsGrid is null) return;

        var visibleRows = GetCanonicalVisibleMaterialRows();
        if (visibleRows.Count == 0)
        {
            CategoryRankingsGrid.ItemsSource = null;
            CategoryRankingStatusText.Text = "Load Materials data to build category rankings.";
            CategoryRankingSummaryText.Text = "No category rankings yet";
            return;
        }

        var rankingRows = BuildCanonicalVisiblePlannerRows()
            .Select(row => BuildRankingRow(row, "Overall"))
            .ToList();

        var baseMaterial = SelectedComboText(CategoryRankingBaseMaterialFilter);
        if (!string.IsNullOrWhiteSpace(baseMaterial) && baseMaterial != "All")
        {
            rankingRows = rankingRows.Where(row => row.BaseMaterial.Equals(baseMaterial, StringComparison.OrdinalIgnoreCase)).ToList();
        }

        var manufacturer = SelectedComboText(CategoryRankingManufacturerFilter);
        if (!string.IsNullOrWhiteSpace(manufacturer) && manufacturer != "All")
        {
            rankingRows = rankingRows.Where(row => row.Manufacturer.Equals(manufacturer, StringComparison.OrdinalIgnoreCase)).ToList();
        }

        var reinforcement = SelectedComboText(CategoryRankingReinforcementFilter);
        if (!string.IsNullOrWhiteSpace(reinforcement) && reinforcement != "All")
        {
            rankingRows = rankingRows.Where(row => ReinforcementFilterMatches(row.Reinforcement, reinforcement)).ToList();
        }

        var selectedCategory = SelectedComboText(CategoryRankingMetricFilter);
        var metricDefinitions = CategoryMetricDefinitions()
            .Where(metric => string.IsNullOrWhiteSpace(selectedCategory) || selectedCategory == "All categories" || metric.Name == selectedCategory)
            .ToList();

        var groupMode = SelectedComboText(CategoryRankingGroupFilter);
        if (string.IsNullOrWhiteSpace(groupMode)) groupMode = "Overall top lists";

        var limit = CategoryRankingLimit(SelectedComboText(CategoryRankingLimitFilter));
        var categoryRows = new List<CategoryRankingRow>();

        foreach (var metric in metricDefinitions)
        {
            var scoredRows = rankingRows
                .Select(row => (Row: row, Score: metric.ScoreSelector(row)))
                .Where(item => item.Score.HasValue)
                .ToList();

            IEnumerable<IGrouping<string, (RankingRow Row, double? Score)>> groups;
            if (groupMode == "Winners by base material")
            {
                groups = scoredRows
                    .Where(item => !string.IsNullOrWhiteSpace(item.Row.BaseMaterial) && item.Row.BaseMaterial != "—")
                    .GroupBy(item => item.Row.BaseMaterial);
            }
            else if (groupMode == "Winners by manufacturer")
            {
                groups = scoredRows
                    .Where(item => !string.IsNullOrWhiteSpace(item.Row.Manufacturer) && item.Row.Manufacturer != "—")
                    .GroupBy(item => item.Row.Manufacturer);
            }
            else
            {
                groups = scoredRows.GroupBy(_ => "All visible materials");
            }

            foreach (var group in groups.OrderBy(g => g.Key, StringComparer.CurrentCultureIgnoreCase))
            {
                var orderedWinners = group
                    .OrderByDescending(item => item.Score ?? double.MinValue)
                    .ThenByDescending(item => item.Row.Overall ?? double.MinValue)
                    .ThenBy(item => item.Row.Label, StringComparer.CurrentCultureIgnoreCase);
                var winners = limit.HasValue
                    ? orderedWinners.Take(limit.Value).ToList()
                    : orderedWinners.ToList();

                for (var i = 0; i < winners.Count; i++)
                {
                    var row = winners[i].Row;
                    categoryRows.Add(new CategoryRankingRow
                    {
                        Category = metric.Name,
                        Group = group.Key,
                        Rank = i + 1,
                        Label = row.Label,
                        Manufacturer = row.Manufacturer,
                        BaseMaterial = row.BaseMaterial,
                        Reinforcement = row.Reinforcement,
                        Status = row.Status,
                        CategoryScore = winners[i].Score,
                        Overall = row.Overall,
                        BestAxis = row.BestAxis
                    });
                }
            }
        }

        CategoryRankingsGrid.ItemsSource = categoryRows;
        if (categoryRows.Count == 0)
        {
            CategoryRankingSummaryText.Text = "No category winners";
            CategoryRankingStatusText.Text = $"No category ranking rows match the current category/view/filter combination. Try Reset Filters or clearing the Materials tab search/filter.";
            return;
        }

        CategoryRankingSummaryText.Text = $"{categoryRows.Count} category ranking row{(categoryRows.Count == 1 ? string.Empty : "s")}";
        var limitText = limit.HasValue ? $"up to {limit.Value} rows per group" : "all ranked rows per group";
        CategoryRankingStatusText.Text = $"Showing {categoryRows.Count} row{(categoryRows.Count == 1 ? string.Empty : "s")} across {metricDefinitions.Count} categor{(metricDefinitions.Count == 1 ? "y" : "ies")}; {limitText}. View: {groupMode}. Filters/search from the Materials tab are included.";
    }

    private static int? CategoryRankingLimit(string selected)
    {
        return selected switch
        {
            "5" => 5,
            "10" => 10,
            "50" => 50,
            "100" => 100,
            "All" => null,
            _ => 10
        };
    }

