            return;
        }

        var dialog = new SaveFileDialog
        {
            Title = "Export Category Rankings CSV",
            Filter = "CSV file (*.csv)|*.csv|All files (*.*)|*.*",
            FileName = "3dp-iceland-category-rankings-v20-5.csv"
