        if (dialog.ShowDialog(this) != true) return;

        var lines = new List<string>
        {
            CsvLine("Category", "Group", "Rank", "Material", "Manufacturer", "Base Material", "Reinforcement", "Category Score", "Overall", "Best Axis", "Status")
