        new AwardDefinition { Name = "Strongest Material", Set = "Performance awards", UseCase = "Strength-focused videos", ScoreSelector = row => row.Tensile },
        new AwardDefinition { Name = "Toughest Material", Set = "Performance awards", UseCase = "Impact/toughness stories", ScoreSelector = row => row.Impact },
        new AwardDefinition { Name = "Stiffest Material", Set = "Performance awards", UseCase = "Rigidity comparisons", ScoreSelector = row => row.Stiffness },
        new AwardDefinition { Name = "Most Consistent Material", Set = "Performance awards", UseCase = "Reliability stories", ScoreSelector = row => row.Consistency },
        new AwardDefinition { Name = "Best Layer Adhesion", Set = "Performance awards", UseCase = "Layer strength stories", ScoreSelector = row => row.LayerAdhesion },

        new AwardDefinition { Name = "Best PLA", Set = "Material family awards", UseCase = "PLA roundups", AppliesTo = row => IsBaseMaterial(row, "PLA"), ScoreSelector = row => row.Overall },
        new AwardDefinition { Name = "Best PETG", Set = "Material family awards", UseCase = "PETG roundups", AppliesTo = row => IsBaseMaterial(row, "PETG"), ScoreSelector = row => row.Overall },
        new AwardDefinition { Name = "Best ASA", Set = "Material family awards", UseCase = "ASA roundups", AppliesTo = row => IsBaseMaterial(row, "ASA"), ScoreSelector = row => row.Overall },
        new AwardDefinition { Name = "Best ABS", Set = "Material family awards", UseCase = "ABS roundups", AppliesTo = row => IsBaseMaterial(row, "ABS"), ScoreSelector = row => row.Overall },
        new AwardDefinition { Name = "Best Nylon", Set = "Material family awards", UseCase = "Nylon/PA videos", AppliesTo = row => IsBaseMaterial(row, "PA") || IsBaseMaterial(row, "NYLON"), ScoreSelector = row => row.Overall },
        new AwardDefinition { Name = "Best PC", Set = "Material family awards", UseCase = "Engineering material videos", AppliesTo = row => IsBaseMaterial(row, "PC"), ScoreSelector = row => row.Overall },

        new AwardDefinition { Name = "Best Carbon Fiber Material", Set = "Reinforcement awards", UseCase = "CF comparison videos", AppliesTo = row => HasReinforcement(row, "CF") || HasReinforcement(row, "Carbon"), ScoreSelector = row => row.Overall },
        new AwardDefinition { Name = "Best Glass Fiber Material", Set = "Reinforcement awards", UseCase = "GF comparison videos", AppliesTo = row => HasReinforcement(row, "GF") || HasReinforcement(row, "Glass"), ScoreSelector = row => row.Overall },
        new AwardDefinition { Name = "Best Unreinforced Material", Set = "Reinforcement awards", UseCase = "Pure material comparisons", AppliesTo = IsUnreinforced, ScoreSelector = row => row.Overall }
    };

    private static bool IsBaseMaterial(RankingRow row, string expected)
    {
        if (string.IsNullOrWhiteSpace(row.BaseMaterial) || row.BaseMaterial == "—") return false;
        return row.BaseMaterial.Contains(expected, StringComparison.OrdinalIgnoreCase);
    }

    private static bool HasReinforcement(RankingRow row, string expected)
    {
        if (string.IsNullOrWhiteSpace(row.Reinforcement) || row.Reinforcement == "—") return false;
        return row.Reinforcement.Contains(expected, StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsUnreinforced(RankingRow row)
    {
        if (string.IsNullOrWhiteSpace(row.Reinforcement) || row.Reinforcement == "—") return true;
        var reinforcement = row.Reinforcement.Trim();
        return reinforcement.Equals("None", StringComparison.OrdinalIgnoreCase)
            || reinforcement.Equals("No", StringComparison.OrdinalIgnoreCase)
            || reinforcement.Equals("Pure", StringComparison.OrdinalIgnoreCase)
            || reinforcement.Equals("__none__", StringComparison.OrdinalIgnoreCase);
    }

