    private void UpdateAwards()
    {
        if (AwardsGrid is null) return;

        var visibleRows = GetCanonicalVisibleMaterialRows();
        if (visibleRows.Count == 0)
        {
            AwardsGrid.ItemsSource = null;
            AwardsStatusText.Text = "Load Materials data to build awards.";
            AwardsSummaryText.Text = "No awards yet";
            return;
        }

        var rankingRows = BuildCanonicalVisiblePlannerRows()
            .Select(row => BuildRankingRow(row, "Overall"))
            .ToList();

        var baseMaterial = SelectedComboText(AwardsBaseMaterialFilter);
        if (!string.IsNullOrWhiteSpace(baseMaterial) && baseMaterial != "All")
        {
            rankingRows = rankingRows.Where(row => row.BaseMaterial.Equals(baseMaterial, StringComparison.OrdinalIgnoreCase)).ToList();
        }

        var manufacturer = SelectedComboText(AwardsManufacturerFilter);
        if (!string.IsNullOrWhiteSpace(manufacturer) && manufacturer != "All")
        {
            rankingRows = rankingRows.Where(row => row.Manufacturer.Equals(manufacturer, StringComparison.OrdinalIgnoreCase)).ToList();
        }

        var reinforcement = SelectedComboText(AwardsReinforcementFilter);
        if (!string.IsNullOrWhiteSpace(reinforcement) && reinforcement != "All")
        {
            rankingRows = rankingRows.Where(row => ReinforcementFilterMatches(row.Reinforcement, reinforcement)).ToList();
        }

        var selectedSet = SelectedComboText(AwardsSetFilter);
        var definitions = AwardDefinitions()
            .Where(definition => string.IsNullOrWhiteSpace(selectedSet) || selectedSet == "All awards" || definition.Set == selectedSet)
            .ToList();

        var awardRows = new List<AwardRow>();
        foreach (var definition in definitions)
        {
            var candidates = rankingRows
                .Where(definition.AppliesTo)
                .Select(row => (Row: row, Score: definition.ScoreSelector(row)))
                .Where(item => item.Score.HasValue)
                .OrderByDescending(item => item.Score ?? double.MinValue)
                .ThenByDescending(item => item.Row.Overall ?? double.MinValue)
                .ThenBy(item => item.Row.Label, StringComparer.CurrentCultureIgnoreCase)
                .ToList();

            if (candidates.Count == 0) continue;

            var winner = candidates[0];
            var runnerUpItem = candidates.Count > 1 ? candidates[1] : candidates[0];
            var hasRunnerUp = candidates.Count > 1;
            awardRows.Add(new AwardRow
            {
                Award = definition.Name,
                Winner = winner.Row.Label,
                Manufacturer = winner.Row.Manufacturer,
                BaseMaterial = winner.Row.BaseMaterial,
                Reinforcement = winner.Row.Reinforcement,
                Score = winner.Score,
                RunnerUp = hasRunnerUp ? runnerUpItem.Row.Label : "—",
                RunnerUpManufacturer = hasRunnerUp ? runnerUpItem.Row.Manufacturer : string.Empty,
                RunnerUpBaseMaterial = hasRunnerUp ? runnerUpItem.Row.BaseMaterial : string.Empty,
                RunnerUpReinforcement = hasRunnerUp ? runnerUpItem.Row.Reinforcement : string.Empty,
                RunnerUpScore = hasRunnerUp ? runnerUpItem.Score : null,
                UseCase = definition.UseCase,
                Why = BuildAwardReason(definition, winner.Row, winner.Score),
                Status = winner.Row.Status
            });
        }

        AwardsGrid.ItemsSource = awardRows;
        if (awardRows.Count == 0)
        {
            AwardsSummaryText.Text = "No award winners";
            AwardsStatusText.Text = "No award winners match the current award set and filters. Try Reset Filters or clearing the Materials tab search/filter.";
            return;
        }

        AwardsSummaryText.Text = $"{awardRows.Count} award winner{(awardRows.Count == 1 ? string.Empty : "s")}";
        AwardsStatusText.Text = $"Showing {awardRows.Count} award winner{(awardRows.Count == 1 ? string.Empty : "s")} from {rankingRows.Count} visible material{(rankingRows.Count == 1 ? string.Empty : "s")}. Filters/search from the Materials tab are included.";
    }

    private static string BuildAwardReason(AwardDefinition definition, RankingRow row, double? score)
    {
        var scoreText = FormatScore(score);
        if (definition.Name.Contains("Strongest", StringComparison.OrdinalIgnoreCase)) return $"Highest tensile score in this award set ({scoreText}).";
        if (definition.Name.Contains("Toughest", StringComparison.OrdinalIgnoreCase)) return $"Highest impact score in this award set ({scoreText}).";
        if (definition.Name.Contains("Stiffest", StringComparison.OrdinalIgnoreCase)) return $"Highest stiffness score in this award set ({scoreText}).";
        if (definition.Name.Contains("Consistent", StringComparison.OrdinalIgnoreCase)) return $"Best consistency score in this award set ({scoreText}).";
        if (definition.Name.Contains("Layer", StringComparison.OrdinalIgnoreCase)) return $"Best layer adhesion score in this award set ({scoreText}).";
        return $"Best overall score in this award set ({scoreText}). Best axis: {row.BestAxis}.";
    }

