    private void RefreshVideoPlanner_Click(object sender, RoutedEventArgs e) => UpdateVideoPlanner();

    private void UpdateVideoPlanner()
    {
        if (VideoPlannerList is null) return;

        var visibleRows = GetCanonicalVisibleMaterialRows();
        if (visibleRows.Count == 0)
        {
            VideoPlannerList.ItemsSource = null;
            VideoPlannerStatusText.Text = "Load Materials data to build the video planner.";
            return;
        }

        var allRows = BuildCanonicalVisiblePlannerRows();

        ApplyDataAwareVideoSuggestions(allRows);
        ApplyVideoTitleSuggestions(allRows);

        var rows = allRows
            .Where(row => RowMatchesVideoPlannerFilters(row))
            .OrderByDescending(row => row.Priority)
            .ThenByDescending(row => row.SortScore)
            .ThenBy(row => row.Label, StringComparer.CurrentCultureIgnoreCase)
            .Take(80)
            .ToList();

        VideoPlannerList.ItemsSource = rows;
        var comparisonIdeas = BuildAutomaticComparisonSuggestions(allRows)
            .Take(25)
            .ToList();
        VideoComparisonIdeasList.ItemsSource = comparisonIdeas;

        var noVideo = rows.Count(r => r.Status.Contains("No video", StringComparison.OrdinalIgnoreCase));
        var dataAware = rows.Count(r => !string.IsNullOrWhiteSpace(r.SuggestionCategory) && r.SuggestionCategory != "General candidate");
        VideoPlannerStatusText.Text = $"Showing {rows.Count} video candidate{(rows.Count == 1 ? string.Empty : "s")} from {visibleRows.Count} visible material{(visibleRows.Count == 1 ? string.Empty : "s")}. {noVideo} currently have no YouTube review link. {dataAware} have data-aware suggestion flags. {comparisonIdeas.Count} comparison idea{(comparisonIdeas.Count == 1 ? string.Empty : "s")} discovered.";
    }

    private bool RowMatchesVideoPlannerFilters(VideoPlannerRow row)
    {
        if (VideoNoYoutubeOnlyCheck?.IsChecked == true && !row.Status.Contains("No video", StringComparison.OrdinalIgnoreCase)) return false;
        if (VideoReadyOnlyCheck?.IsChecked == true && !row.Status.Contains("Mechanical ready", StringComparison.OrdinalIgnoreCase)) return false;

        var category = VideoCategoryFilter?.SelectedItem as string;
        if (!string.IsNullOrWhiteSpace(category) && category != "All" && !row.MaterialType.Contains(category, StringComparison.OrdinalIgnoreCase)) return false;

        var manufacturer = VideoManufacturerFilter?.SelectedItem as string;
        if (!string.IsNullOrWhiteSpace(manufacturer) && manufacturer != "All" && !row.Label.StartsWith(manufacturer, StringComparison.OrdinalIgnoreCase)) return false;

        var baseMaterial = VideoBaseMaterialFilter?.SelectedItem as string;
        if (!string.IsNullOrWhiteSpace(baseMaterial) && baseMaterial != "All" && !row.MaterialType.Contains(baseMaterial, StringComparison.OrdinalIgnoreCase)) return false;

        return true;
    }

    private VideoPlannerRow BuildVideoPlannerRow(
        DataRow row,
        IReadOnlyDictionary<string, MaterialResults>? verifiedSummaries = null)
    {
        var materialId = row.Table.Columns.Contains("Material ID")
            ? row["Material ID"]?.ToString()?.Trim() ?? string.Empty
            : string.Empty;

        var label = _detailService.BuildTitle(row);
        var manufacturer = DataTableHelpers.FirstValue(row, "Manufacturer", "Brand");
        var baseMaterial = DataTableHelpers.FirstValue(row, "Base Material", "Type", "Material Type");
        var category = DataTableHelpers.FirstValue(row, "Material Category", "Category");
        var productLine = DataTableHelpers.FirstValue(row, "Product Line", "ProductLine");
        var reinforcement = DataTableHelpers.FirstValue(row, "Reinforcement", "Reinforment");
        var variant = DataTableHelpers.FirstValue(row, "Variant / Finish", "Variant", "Finish");
        var hasVideo = IsTruthy(DataTableHelpers.FirstValue(row, "YouTube Available", "Video Available")) || HasAnyValue(row, "YouTube Review URL", "YouTube URL");
        var hasWebsite = HasAnyValue(row, "Website Display Name", "Material Key", "Slug", "Product Page");

        MaterialResults? verifiedSummary = null;
        verifiedSummaries?.TryGetValue(materialId, out verifiedSummary);

        // Verified Material Summary is the canonical downstream source. Avoid legacy
        // per-material database reads when that governed summary is already available.
        var tensile = verifiedSummary is null ? _database.GetTensileTestResult(materialId) : null;
        var metrics = verifiedSummary is null
            ? GetCanonicalTestSummaryMetrics(materialId)
                .Where(m => m.TestType is "Tensile" or "Impact" or "Stiffness" or "Rating")
                .ToList()
            : new List<TestSummaryMetric>();
        var profile = verifiedSummary is not null
            ? _scoringService.BuildProfile(verifiedSummary)
            : _scoringService.BuildProfile(tensile, metrics);
        var hasMechanical = verifiedSummary?.HasAnyResults == true || profile.OverallScore.HasValue || tensile?.HasAnyValue == true || metrics.Count > 0;
        var nativePricingRow = _nativeMaterialRows.FirstOrDefault(item =>
            item.MaterialID.Equals(materialId, StringComparison.OrdinalIgnoreCase));
        var pricePerKg = ResolveCanonicalMsrpUsdPerKg(nativePricingRow, row);
        var strongest = BestProfileDimension(profile);
        var comparisonIdea = BuildComparisonIdea(baseMaterial, reinforcement, variant, manufacturer, productLine);
        var statusParts = new List<string>
        {
            hasMechanical ? "Mechanical ready" : "Missing mechanical data",
            hasVideo ? "Has video" : "No video",
            hasWebsite ? "Website profile" : "No website profile"
        };

        var priority = 0;
        if (hasMechanical) priority += 40;
        if (!hasVideo) priority += 30;
        if (hasWebsite) priority += 10;
        if (profile.OverallScore >= 70) priority += 10;
        if (profile.ConsistencyScore >= 80) priority += 5;
        if (!string.IsNullOrWhiteSpace(reinforcement)) priority += 5;

        return new VideoPlannerRow
        {
            Priority = priority,
            MaterialId = materialId,
            Label = label,
            MaterialType = JoinNonEmpty(" / ", baseMaterial, category, reinforcement, variant),
            BaseMaterial = baseMaterial ?? string.Empty,
            Category = category ?? string.Empty,
            Manufacturer = manufacturer ?? string.Empty,
            Reinforcement = reinforcement ?? string.Empty,
            Variant = variant ?? string.Empty,
            ProductLine = productLine ?? string.Empty,
            HasVideo = hasVideo,
            HasMechanical = hasMechanical,
            OverallScore = profile.OverallScore,
            TensileScore = profile.TensileScore,
            ImpactScore = profile.ImpactScore,
            StiffnessScore = profile.StiffnessScore,
            ConsistencyScore = profile.ConsistencyScore,
            LayerAdhesionScore = profile.LayerAdhesionScore,
            PricePerKg = pricePerKg,
            VerifiedSummary = verifiedSummary,
            Status = string.Join(" • ", statusParts),
            Standout = BuildStandoutText(profile, strongest),
            SuggestedAngle = BuildSuggestedVideoAngle(row, profile, strongest, hasVideo),
            SuggestedTitle = BuildSuggestedMaterialTitle(label, manufacturer, baseMaterial, reinforcement, variant, profile, strongest),
            TalkingPoints = BuildMaterialTalkingPoints(profile, strongest),
            ComparisonIdea = comparisonIdea,
            SortScore = profile.OverallScore ?? 0
        };
    }

    private static double? ResolveCanonicalMsrpUsdPerKg(NativeMaterialRow? nativeMaterial, DataRow? legacyProjection)
    {
        return new PricingProvenanceService().ResolveCanonicalMsrpUsdPerKg(
            nativeMaterial is not null,
            nativeMaterial?.MsrpUsdPerKg,
            legacyProjection is null
                ? null
                : DataTableHelpers.FirstValue(legacyProjection, "MSRP USD/kg", "MsrpUsdPerKg"));
    }


    private static void ApplyDataAwareVideoSuggestions(List<VideoPlannerRow> rows)
    {
        foreach (var row in rows)
        {
            row.SuggestionCategory = row.HasMechanical ? "General candidate" : "Needs data";
            row.DataReason = row.HasMechanical
                ? "Mechanical profile imported; no major outlier flag yet."
                : "Missing mechanical profile, so it is not ready for a data-driven video angle.";
        }

        var mechanicalRows = rows.Where(r => r.HasMechanical && r.OverallScore.HasValue).ToList();
        if (mechanicalRows.Count == 0) return;

        foreach (var row in mechanicalRows)
        {
            var peerGroup = mechanicalRows
                .Where(r => !string.IsNullOrWhiteSpace(row.BaseMaterial) && string.Equals(r.BaseMaterial, row.BaseMaterial, StringComparison.OrdinalIgnoreCase))
                .ToList();

            if (peerGroup.Count < 3)
            {
                peerGroup = mechanicalRows
                    .Where(r => !string.IsNullOrWhiteSpace(row.Category) && string.Equals(r.Category, row.Category, StringComparison.OrdinalIgnoreCase))
                    .ToList();
            }

            if (peerGroup.Count < 3) peerGroup = mechanicalRows;

            var standout = FindStrongestOutlier(row, peerGroup);
            var topOverall = IsTopPercent(row.OverallScore, peerGroup.Select(r => r.OverallScore), 0.15);
            var highConsistency = IsTopPercent(row.ConsistencyScore, peerGroup.Select(r => r.ConsistencyScore), 0.15);
            var highLayerAdhesion = IsTopPercent(row.LayerAdhesionScore, peerGroup.Select(r => r.LayerAdhesionScore), 0.15);

            if (standout.PercentAboveAverage >= 20)
            {
                row.SuggestionCategory = $"{TitleCase(standout.Axis)} outlier";
                row.DataReason = $"{TitleCase(standout.Axis)} score is {standout.PercentAboveAverage:0}% above the {PeerGroupLabel(row, peerGroup)} average.";
                row.Priority += row.HasVideo ? 8 : 18;
                row.SuggestedAngle = $"Why does this {row.BaseMaterial} stand out in {standout.Axis}?";
            }
            else if (topOverall)
            {
                row.SuggestionCategory = "Top performer";
                row.DataReason = $"Overall profile is in the top tier among {PeerGroupLabel(row, peerGroup)} materials.";
                row.Priority += row.HasVideo ? 6 : 15;
            }
            else if (highLayerAdhesion)
            {
                row.SuggestionCategory = "Layer adhesion story";
                row.DataReason = $"Layer adhesion score is among the best in its peer group.";
                row.Priority += row.HasVideo ? 5 : 12;
            }
            else if (highConsistency)
            {
                row.SuggestionCategory = "Reliability story";
                row.DataReason = $"Consistency score is among the best in its peer group.";
                row.Priority += row.HasVideo ? 4 : 10;
            }
        }
    }

    private static void ApplyVideoTitleSuggestions(List<VideoPlannerRow> rows)
    {
        foreach (var row in rows.Where(r => r.HasMechanical))
        {
            var strongest = HighestAxisLabel(row);
            row.SuggestedTitle = BuildSuggestedMaterialTitle(row.Label, row.Manufacturer, row.BaseMaterial, row.Reinforcement, row.Variant, row, strongest);
            row.TalkingPoints = BuildMaterialTalkingPoints(row, strongest);

            if (row.SuggestionCategory.Contains("outlier", StringComparison.OrdinalIgnoreCase))
            {
                row.SuggestedAngle = $"Lead with the data surprise: this {SafeLower(row.BaseMaterial, "material")} stands out on {strongest}.";
            }
            else if (row.SuggestionCategory.Contains("Layer", StringComparison.OrdinalIgnoreCase))
            {
                row.SuggestedAngle = "Frame it around layer adhesion and structural-printing reliability.";
            }
            else if (row.SuggestionCategory.Contains("Reliability", StringComparison.OrdinalIgnoreCase))
            {
                row.SuggestedAngle = "Frame it around repeatability: strong data confidence, not just peak strength.";
            }
        }
    }

    private static (string Axis, double PercentAboveAverage) FindStrongestOutlier(VideoPlannerRow row, List<VideoPlannerRow> peers)
    {
        var axes = new[]
        {
            (Axis: "tensile", Value: row.TensileScore, PeerValues: peers.Select(p => p.TensileScore)),
            (Axis: "impact", Value: row.ImpactScore, PeerValues: peers.Select(p => p.ImpactScore)),
            (Axis: "stiffness", Value: row.StiffnessScore, PeerValues: peers.Select(p => p.StiffnessScore)),
            (Axis: "consistency", Value: row.ConsistencyScore, PeerValues: peers.Select(p => p.ConsistencyScore)),
            (Axis: "layer adhesion", Value: row.LayerAdhesionScore, PeerValues: peers.Select(p => p.LayerAdhesionScore))
        };

        var bestAxis = "overall";
        var bestPct = 0d;
        foreach (var axis in axes)
        {
            if (!axis.Value.HasValue) continue;
            var avg = axis.PeerValues.Where(v => v.HasValue).Select(v => v!.Value).DefaultIfEmpty(0).Average();
            if (avg <= 0) continue;
            var pct = ((axis.Value.Value - avg) / avg) * 100d;
            if (pct > bestPct)
            {
                bestPct = pct;
                bestAxis = axis.Axis;
            }
        }

        return (bestAxis, bestPct);
    }

    private static bool IsTopPercent(double? value, IEnumerable<double?> values, double topFraction)
    {
        if (!value.HasValue) return false;
        var list = values.Where(v => v.HasValue).Select(v => v!.Value).OrderByDescending(v => v).ToList();
        if (list.Count < 3) return false;
        var cutoffIndex = Math.Max(0, (int)Math.Ceiling(list.Count * topFraction) - 1);
        return value.Value >= list[Math.Min(cutoffIndex, list.Count - 1)];
    }

    private static string PeerGroupLabel(VideoPlannerRow row, List<VideoPlannerRow> peers)
    {
        if (!string.IsNullOrWhiteSpace(row.BaseMaterial) && peers.All(p => string.Equals(p.BaseMaterial, row.BaseMaterial, StringComparison.OrdinalIgnoreCase)))
            return row.BaseMaterial;
        if (!string.IsNullOrWhiteSpace(row.Category) && peers.All(p => string.Equals(p.Category, row.Category, StringComparison.OrdinalIgnoreCase)))
            return row.Category;
        return "visible dataset";
    }

    private static string TitleCase(string value)
    {
        if (string.IsNullOrWhiteSpace(value)) return value;
        return char.ToUpper(value[0], CultureInfo.CurrentCulture) + value[1..];
    }

    private static string BestProfileDimension(EngineeringScoreProfile profile)
    {
        var candidates = new[]
        {
            (Name: "tensile strength", Score: profile.TensileScore),
            (Name: "impact resistance", Score: profile.ImpactScore),
            (Name: "stiffness", Score: profile.StiffnessScore),
            (Name: "consistency", Score: profile.ConsistencyScore),
            (Name: "layer adhesion", Score: profile.LayerAdhesionScore)
        }
        .Where(item => item.Score.HasValue)
        .OrderByDescending(item => item.Score)
        .ToList();

        return candidates.Count == 0 ? "mechanical profile" : candidates[0].Name;
    }

    private static string BuildStandoutText(EngineeringScoreProfile profile, string strongest)
    {
        if (!profile.OverallScore.HasValue) return "No score profile yet";
        return $"Overall {FormatScore(profile.OverallScore)} • best axis: {strongest}";
    }

    private static string BuildSuggestedMaterialTitle(string label, string? manufacturer, string? baseMaterial, string? reinforcement, string? variant, EngineeringScoreProfile profile, string strongest)
    {
        return BuildSuggestedMaterialTitleFromScores(label, manufacturer, baseMaterial, reinforcement, variant,
            profile.TensileScore, profile.ImpactScore, profile.StiffnessScore, profile.ConsistencyScore, profile.LayerAdhesionScore, profile.OverallScore, strongest);
    }

    private static string BuildSuggestedMaterialTitle(string label, string? manufacturer, string? baseMaterial, string? reinforcement, string? variant, VideoPlannerRow row, string strongest)
    {
        return BuildSuggestedMaterialTitleFromScores(label, manufacturer, baseMaterial, reinforcement, variant,
            row.TensileScore, row.ImpactScore, row.StiffnessScore, row.ConsistencyScore, row.LayerAdhesionScore, row.OverallScore, strongest);
    }

    private static string BuildSuggestedMaterialTitleFromScores(
        string label,
        string? manufacturer,
        string? baseMaterial,
        string? reinforcement,
        string? variant,
        double? tensile,
        double? impact,
        double? stiffness,
        double? consistency,
        double? layerAdhesion,
        double? overall,
        string strongest)
    {
        var brand = ShortBrand(manufacturer);
        var material = string.IsNullOrWhiteSpace(baseMaterial) ? "filament" : baseMaterial.Trim();
        var reinforced = string.IsNullOrWhiteSpace(reinforcement) ? string.Empty : $" {reinforcement.Trim()}";
        var variantText = string.IsNullOrWhiteSpace(variant) ? string.Empty : $" {variant.Trim()}";

        if (impact >= 75) return $"The Toughest {material}{reinforced} I’ve Tested | {brand}";
        if (stiffness >= 85) return $"This {material}{reinforced} Is Seriously Stiff | {brand}";
        if (tensile >= 75) return $"This {material}{reinforced} Is Stronger Than Expected | {brand}";
        if (layerAdhesion >= 75) return $"This {material}{variantText} Has Shockingly Good Layer Adhesion | {brand}";
        if (consistency >= 88) return $"The Most Repeatable {material}{variantText} Results So Far | {brand}";
        if (!string.IsNullOrWhiteSpace(reinforcement)) return $"Is {reinforcement.Trim()} Worth It? | {brand} {material}";
        if (!string.IsNullOrWhiteSpace(variant)) return $"Is {variant.Trim()} {material} Actually Better? | {brand}";
        if (overall >= 65) return $"This {material} Surprised Me in the Lab | {brand}";
        return $"What Is {ShortenPlannerText(label, 46)} Actually Good For?";
    }

    private static string BuildMaterialTalkingPoints(EngineeringScoreProfile profile, string strongest)
    {
        return BuildTalkingPointsFromScores(profile.TensileScore, profile.ImpactScore, profile.StiffnessScore, profile.ConsistencyScore, profile.LayerAdhesionScore, profile.OverallScore, strongest);
    }

    private static string BuildMaterialTalkingPoints(VideoPlannerRow row, string strongest)
    {
        return BuildTalkingPointsFromScores(row.TensileScore, row.ImpactScore, row.StiffnessScore, row.ConsistencyScore, row.LayerAdhesionScore, row.OverallScore, strongest);
    }

    private static string BuildTalkingPointsFromScores(double? tensile, double? impact, double? stiffness, double? consistency, double? layerAdhesion, double? overall, string strongest)
    {
        var points = new List<string>();
        if (overall.HasValue) points.Add($"overall {overall.Value:0}/100");
        if (!string.IsNullOrWhiteSpace(strongest)) points.Add($"best axis: {strongest}");
        if (tensile >= 70) points.Add($"high tensile {tensile.Value:0}/100");
        if (impact >= 70) points.Add($"high impact {impact.Value:0}/100");
        if (stiffness >= 80) points.Add($"very stiff {stiffness.Value:0}/100");
        if (consistency >= 85) points.Add($"repeatable {consistency.Value:0}/100");
        if (layerAdhesion >= 65) points.Add($"layer adhesion {layerAdhesion.Value:0}/100");
        return points.Count == 0 ? "Mechanical data imported, but no strong story axis yet." : string.Join(" • ", points);
    }

    private static string HighestAxisLabel(VideoPlannerRow row)
    {
        var candidates = new[]
        {
            (Name: "tensile strength", Score: row.TensileScore),
            (Name: "impact resistance", Score: row.ImpactScore),
            (Name: "stiffness", Score: row.StiffnessScore),
            (Name: "consistency", Score: row.ConsistencyScore),
            (Name: "layer adhesion", Score: row.LayerAdhesionScore)
        }
        .Where(item => item.Score.HasValue)
        .OrderByDescending(item => item.Score)
        .ToList();

        return candidates.Count == 0 ? "mechanical profile" : candidates[0].Name;
    }

    private static string ShortBrand(string? manufacturer)
    {
        if (string.IsNullOrWhiteSpace(manufacturer)) return "3DPIceland Labs";
        return manufacturer.Trim()
            .Replace("Prima Creator", "3DPrima", StringComparison.OrdinalIgnoreCase)
            .Replace("3D Prima", "3DPrima", StringComparison.OrdinalIgnoreCase)
            .Replace("Prusa3D", "Prusa", StringComparison.OrdinalIgnoreCase)
            .Replace("BambuLab", "Bambu Lab", StringComparison.OrdinalIgnoreCase);
    }

    private static string SafeLower(string? value, string fallback)
    {
        return string.IsNullOrWhiteSpace(value) ? fallback : value.Trim().ToLower(CultureInfo.CurrentCulture);
    }

    private static string BuildSuggestedVideoAngle(DataRow row, EngineeringScoreProfile profile, string strongest, bool hasVideo)
    {
        var baseMaterial = DataTableHelpers.FirstValue(row, "Base Material", "Type", "Material Type");
        var reinforcement = DataTableHelpers.FirstValue(row, "Reinforcement", "Reinforment");
        var variant = DataTableHelpers.FirstValue(row, "Variant / Finish", "Variant", "Finish");
        var titleBase = DataTableHelpers.FirstValue(row, "Website Display Name", "Marketing Name") ?? string.Empty;

        if (!profile.OverallScore.HasValue) return hasVideo ? "Existing review; data incomplete for new angle." : "Test data first, then review.";
        if (!string.IsNullOrWhiteSpace(reinforcement)) return $"Does {baseMaterial} {reinforcement} actually improve {strongest}?";
        if (!string.IsNullOrWhiteSpace(variant)) return $"Is {variant} {baseMaterial} worth choosing over standard {baseMaterial}?";
        if (profile.ConsistencyScore >= 85) return $"Very repeatable results: good candidate for a reliability-focused review.";
        if (profile.LayerAdhesionScore >= 65) return $"Layer adhesion stands out: useful structural-printing angle.";
        return string.IsNullOrWhiteSpace(titleBase)
            ? $"Review angle: strongest result is {strongest}."
            : $"What is {titleBase} actually good for?";
    }

    private static string BuildComparisonIdea(string baseMaterial, string reinforcement, string variant, string manufacturer, string productLine)
    {
        if (!string.IsNullOrWhiteSpace(reinforcement)) return $"Compare {baseMaterial} {reinforcement} against unfilled {baseMaterial} and other reinforced variants.";
        if (!string.IsNullOrWhiteSpace(variant)) return $"Compare {baseMaterial} {variant} against standard {baseMaterial}.";
        if (!string.IsNullOrWhiteSpace(productLine)) return $"Compare {productLine} against other {baseMaterial} product lines.";
        if (!string.IsNullOrWhiteSpace(manufacturer)) return $"Compare {manufacturer} against other {baseMaterial} manufacturers.";
        return "Compare against similar base materials in the same category.";
    }


    private static List<VideoComparisonSuggestion> BuildAutomaticComparisonSuggestions(List<VideoPlannerRow> allRows)
    {
        var candidates = allRows
            .Where(r => r.HasMechanical && r.OverallScore.HasValue && !string.IsNullOrWhiteSpace(r.BaseMaterial))
            .ToList();

        var suggestions = new List<VideoComparisonSuggestion>();

        foreach (var baseGroup in candidates.GroupBy(r => NormalizeGroupKey(r.BaseMaterial)))
        {
            var baseRows = baseGroup.ToList();
            if (baseRows.Count < 3) continue;

            var baseLabel = FirstNonEmpty(baseRows.Select(r => r.BaseMaterial));
            AddGroupBattle(suggestions, baseRows, baseLabel, "Reinforcement", r => NormalizeNullableGroup(r.Reinforcement, "Pure"), $"{baseLabel}: CF vs GF vs Pure");
            AddGroupBattle(suggestions, baseRows, baseLabel, "Manufacturer", r => NormalizeNullableGroup(r.Manufacturer, "Unknown manufacturer"), $"{baseLabel}: manufacturer battle");
            AddGroupBattle(suggestions, baseRows, baseLabel, "Product line", r => NormalizeNullableGroup(r.ProductLine, "Unknown product line"), $"{baseLabel}: product-line comparison");
            AddGroupBattle(suggestions, baseRows, baseLabel, "Variant / Finish", r => NormalizeNullableGroup(r.Variant, "Standard"), $"{baseLabel}: variant / finish comparison");
        }

        return suggestions
            .GroupBy(s => $"{s.Title}|{s.Group}")
            .Select(g => g.OrderByDescending(s => s.Priority).First())
            .OrderByDescending(s => s.Priority)
            .ThenBy(s => s.Title, StringComparer.CurrentCultureIgnoreCase)
            .ToList();
    }

    private static void AddGroupBattle(
        List<VideoComparisonSuggestion> suggestions,
        List<VideoPlannerRow> rows,
        string baseLabel,
        string groupingName,
        Func<VideoPlannerRow, string> groupSelector,
        string title)
    {
        var groups = rows
            .GroupBy(groupSelector)
            .Where(g => !string.IsNullOrWhiteSpace(g.Key) && g.Count(r => r.OverallScore.HasValue) > 0)
            .Select(g => new
            {
                Name = g.Key,
                Rows = g.OrderByDescending(r => r.OverallScore ?? 0).ToList(),
                Overall = g.Where(r => r.OverallScore.HasValue).Average(r => r.OverallScore!.Value),
                Tensile = AverageNullable(g.Select(r => r.TensileScore)),
                Impact = AverageNullable(g.Select(r => r.ImpactScore)),
                Stiffness = AverageNullable(g.Select(r => r.StiffnessScore)),
                Consistency = AverageNullable(g.Select(r => r.ConsistencyScore)),
                LayerAdhesion = AverageNullable(g.Select(r => r.LayerAdhesionScore))
            })
            .Where(g => g.Rows.Count > 0)
            .OrderByDescending(g => g.Overall)
            .ToList();

        if (groups.Count < 2) return;

        var best = groups[0];
        var lowest = groups[^1];
        var spread = best.Overall - lowest.Overall;
        if (spread < 8 && groups.Count < 3) return;

        var axisWinner = FindMostDifferentAxis(groups.Select(g => (
            g.Name,
            g.Tensile,
            g.Impact,
            g.Stiffness,
            g.Consistency,
            g.LayerAdhesion)).ToList());

        var materialNames = string.Join(" | ", groups
            .Take(4)
            .Select(g => $"{g.Name}: {ShortenPlannerText(g.Rows[0].Label, 54)}"));

        var noVideoBonus = groups.SelectMany(g => g.Rows).Any(r => !r.HasVideo) ? 8 : 0;
        var priority = (int)Math.Round(spread) + groups.Count * 3 + noVideoBonus;

        suggestions.Add(new VideoComparisonSuggestion
        {
            Priority = priority,
            Title = title,
            Group = groupingName,
            Winner = $"{best.Name} ({best.Overall:0} overall)",
            Reason = $"{groupingName} averages differ by {spread:0} points. Biggest story axis: {axisWinner}.",
            SuggestedTitleAngle = BuildComparisonTitleAngle(baseLabel, groupingName, best.Name, axisWinner),
            SuggestedTitle = BuildComparisonSuggestedTitle(baseLabel, groupingName, best.Name, axisWinner),
            TalkingPoints = BuildComparisonTalkingPoints(groups.Select(g => (g.Name, g.Overall)).ToList(), axisWinner, spread),
            Materials = materialNames
        });
    }

    private static string BuildComparisonSuggestedTitle(string baseLabel, string groupingName, string winner, string axis)
    {
        if (groupingName.Equals("Reinforcement", StringComparison.OrdinalIgnoreCase))
            return $"CF vs GF vs Pure {baseLabel} – The Results Surprised Me";
        if (groupingName.Equals("Manufacturer", StringComparison.OrdinalIgnoreCase))
            return $"Which {baseLabel} Brand Actually Wins? | Lab Tested";
        if (groupingName.Equals("Product line", StringComparison.OrdinalIgnoreCase))
            return $"Is {winner} the Best {baseLabel} Line? | Lab Results";
        if (groupingName.Equals("Variant / Finish", StringComparison.OrdinalIgnoreCase))
            return $"Which {baseLabel} Variant Is Actually Better?";
        return $"{baseLabel} Comparison – {winner} Wins on {TitleCase(axis)}";
    }

    private static string BuildComparisonTalkingPoints(List<(string Name, double Overall)> groups, string axis, double spread)
    {
        var ordered = groups.OrderByDescending(g => g.Overall).Take(4).ToList();
        if (ordered.Count == 0) return "No comparison talking points yet.";
        var winner = ordered[0];
        var runnerUp = ordered.Count > 1 ? ordered[1] : ordered[0];
        return $"Winner: {winner.Name} ({winner.Overall:0}/100) • runner-up: {runnerUp.Name} ({runnerUp.Overall:0}/100) • spread: {spread:0} points • story axis: {axis}";
    }

    private static string BuildComparisonTitleAngle(string baseLabel, string groupingName, string winner, string axis)
    {
        if (groupingName.Equals("Reinforcement", StringComparison.OrdinalIgnoreCase))
            return $"{baseLabel}: does reinforcement actually improve {axis}?";
        if (groupingName.Equals("Manufacturer", StringComparison.OrdinalIgnoreCase))
            return $"Which {baseLabel} brand wins on {axis}?";
        if (groupingName.Equals("Product line", StringComparison.OrdinalIgnoreCase))
            return $"Is {winner} the best {baseLabel} product line?";
        if (groupingName.Equals("Variant / Finish", StringComparison.OrdinalIgnoreCase))
            return $"Which {baseLabel} variant is actually strongest?";
        return $"{baseLabel} comparison: {winner} wins on {axis}.";
    }

    private static string FindMostDifferentAxis(List<(string Name, double? Tensile, double? Impact, double? Stiffness, double? Consistency, double? LayerAdhesion)> groups)
    {
        var axes = new[]
        {
            (Name: "tensile", Values: groups.Select(g => g.Tensile)),
            (Name: "impact", Values: groups.Select(g => g.Impact)),
            (Name: "stiffness", Values: groups.Select(g => g.Stiffness)),
            (Name: "consistency", Values: groups.Select(g => g.Consistency)),
            (Name: "layer adhesion", Values: groups.Select(g => g.LayerAdhesion))
        };

        return axes
            .Select(axis => new
            {
                axis.Name,
                Spread = NullableSpread(axis.Values)
            })
            .OrderByDescending(axis => axis.Spread)
            .FirstOrDefault()?.Name ?? "overall profile";
    }


    private static double NullableSpread(IEnumerable<double?> values)
    {
        var list = values.Where(v => v.HasValue).Select(v => v!.Value).ToList();
        return list.Count < 2 ? 0 : list.Max() - list.Min();
    }

    private static string NormalizeGroupKey(string? value) => string.IsNullOrWhiteSpace(value) ? string.Empty : value.Trim();

    private static string NormalizeNullableGroup(string? value, string fallback) => string.IsNullOrWhiteSpace(value) || value == "0" ? fallback : value.Trim();

    private static string FirstNonEmpty(IEnumerable<string> values) => values.FirstOrDefault(v => !string.IsNullOrWhiteSpace(v)) ?? "Material";

    private static string ShortenPlannerText(string value, int maxLength)
    {
        if (string.IsNullOrWhiteSpace(value) || value.Length <= maxLength) return value;
        return value[..(maxLength - 1)] + "…";
    }




    private void RecommendationSelection_Changed(object sender, SelectionChangedEventArgs e)
    {
        if (_isUpdatingRecommendationSelection) return;

        try
        {
            _isUpdatingRecommendationSelection = true;

            if (sender == PerformanceRecommendationList && PerformanceRecommendationList.SelectedItem is RecommendationRow performanceRow)
            {
                if (ApplicationRecommendationList is not null) ApplicationRecommendationList.SelectedItem = null;
                UpdateRecommendationDetailPanel(performanceRow);
                return;
            }

            if (sender == ApplicationRecommendationList && ApplicationRecommendationList.SelectedItem is RecommendationRow applicationRow)
            {
                if (PerformanceRecommendationList is not null) PerformanceRecommendationList.SelectedItem = null;
                UpdateRecommendationDetailPanel(applicationRow);
                return;
            }

            if ((PerformanceRecommendationList?.SelectedItem is not RecommendationRow) &&
                (ApplicationRecommendationList?.SelectedItem is not RecommendationRow))
            {
                ResetRecommendationDetailPanel();
            }
        }
        finally
        {
            _isUpdatingRecommendationSelection = false;
        }
    }

    private void UpdateRecommendationDetailPanel(RecommendationRow row)
    {
        if (RecommendationDetailType is null) return;

        _selectedRecommendationForVideoPlanner = row;
