        RecommendationDetailScore.Text = $"Score: {row.ScoreText} · {row.MaterialType}";
        RecommendationDetailTitle.Text = BlankDash(row.SuggestedTitle);
        RecommendationDetailHook.Text = BlankDash(row.ThumbnailHook);
        RecommendationDetailTalkingPoints.Text = BlankDash(row.TalkingPoints);
        RecommendationDetailReason.Text = BlankDash(row.Reason);
        RecommendationDetailConfidence.Text = BlankDash(row.AdvisorInsight?.ConfidenceLabel);
        RecommendationDetailConfidenceSummary.Text = BlankDash(row.AdvisorInsight?.ConfidenceSummary);
        RecommendationDetailEvidence.Text = BlankDash(row.AdvisorInsight?.EvidenceSummary);
        RecommendationDetailComparison.Text = BlankDash(row.AdvisorInsight?.ComparisonSummary);
        RecommendationDetailConsistencyStatus.Text = BlankDash(row.ConsistencyInsight?.StatusLabel);
        RecommendationDetailConsistencySummary.Text = BlankDash(row.ConsistencyInsight?.RepeatabilitySummary);
        RecommendationDetailOutlierReview.Text = BlankDash(row.ConsistencyInsight?.OutlierReviewSummary);
        RecommendationDetailPriceContext.Text = BuildRecommendationPriceContext(row);
        RecommendationDetailValueIndex.Text = row.ValueIndex?.Summary ??
            "3DPIceland value index: Not recorded. Overall engineering score or canonical MSRP USD/kg is unavailable.";
        RecommendationDetailInventoryStatus.Text = BlankDash(row.ContextInsight?.InventoryStatus);
        RecommendationDetailInventoryContext.Text = BlankDash(row.ContextInsight?.InventorySummary);
        RecommendationDetailManufacturerContext.Text = BlankDash(row.ContextInsight?.ManufacturerSummary);
        RecommendationDetailManufacturerPosition.Text = BlankDash(row.PeerInsight?.ManufacturerPositionSummary);
        RecommendationDetailCategoryPosition.Text = BlankDash(row.PeerInsight?.CategoryPositionSummary);
        RecommendationAlternativeList.ItemsSource = row.Alternatives;
        RecommendationAlternativeStatus.Text = row.Alternatives.Count == 0
            ? "No comparable alternatives are available in the current filtered recommendation group."
            : $"{row.Alternatives.Count} data-driven alternative{(row.Alternatives.Count == 1 ? string.Empty : "s")} from the current filtered group.";
        RecommendationDetailBestUse.Text = BlankDash(row.BestUse);
        RecommendationDetailCaution.Text = BlankDash(JoinNonEmpty(" ", row.Caution, row.AdvisorInsight?.TradeOffSummary ?? string.Empty));
        RecommendationChatGptPrompt.Text = BuildRecommendationChatGptPrompt(row);
        if (SendRecommendationToVideoPlannerButton is not null) SendRecommendationToVideoPlannerButton.IsEnabled = true;
        if (RecommendationVideoPlannerStatus is not null) RecommendationVideoPlannerStatus.Text = "Ready to send this recommendation to the Video Planner.";
