    private void SendRecommendationToVideoPlanner_Click(object sender, RoutedEventArgs e)
    {
        if (_selectedRecommendationForVideoPlanner is not RecommendationRow row)
        {
            MessageBox.Show(this, "Select a recommendation first.", "No recommendation selected", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }

        var plannerRow = BuildRecommendationVideoPlannerRow(row);

        _recommendationVideoIdeas.RemoveAll(existing =>
            existing.Label.Equals(plannerRow.Label, StringComparison.OrdinalIgnoreCase) &&
            existing.SuggestionCategory.Equals(plannerRow.SuggestionCategory, StringComparison.OrdinalIgnoreCase) &&
            existing.SuggestedTitle.Equals(plannerRow.SuggestedTitle, StringComparison.OrdinalIgnoreCase));

        _recommendationVideoIdeas.Insert(0, plannerRow);
        if (RecommendationVideoIdeaList is not null) RecommendationVideoIdeaList.ItemsSource = _recommendationVideoIdeas.ToList();
        SaveVideoIdeaQueue();
        UpdateProductionDashboard();

        var existingRows = VideoPlannerList?.ItemsSource is IEnumerable<VideoPlannerRow> rows
            ? rows.ToList()
            : new List<VideoPlannerRow>();

        existingRows.RemoveAll(existing =>
            existing.Label.Equals(plannerRow.Label, StringComparison.OrdinalIgnoreCase) &&
            existing.SuggestionCategory.Equals(plannerRow.SuggestionCategory, StringComparison.OrdinalIgnoreCase) &&
            existing.SuggestedTitle.Equals(plannerRow.SuggestedTitle, StringComparison.OrdinalIgnoreCase));

        existingRows.Insert(0, plannerRow);
        if (VideoPlannerList is not null) VideoPlannerList.ItemsSource = existingRows.Take(100).ToList();

        if (VideoNoYoutubeOnlyCheck is not null) VideoNoYoutubeOnlyCheck.IsChecked = false;
        if (VideoReadyOnlyCheck is not null) VideoReadyOnlyCheck.IsChecked = false;

        if (VideoPlannerStatusText is not null)
        {
            VideoPlannerStatusText.Text = $"Added recommendation idea: {row.SuggestedTitle}. Open the Video Planner tab to review it at the top of the candidate list.";
        }

        if (RecommendationVideoPlannerStatus is not null)
        {
            RecommendationVideoPlannerStatus.Text = "Sent to Video Planner candidate list.";
        }
    }

    private VideoPlannerRow BuildRecommendationVideoPlannerRow(RecommendationRow row)
    {
        var handoff = row.IntelligenceHandoff ?? _engineeringIntelligenceHandoffService.Build(
            row.AdvisorInsight,
            row.ConsistencyInsight,
            row.ContextInsight,
            row.PeerInsight,
            row.Alternatives);

        return new VideoPlannerRow
        {
            MaterialId = row.MaterialId,
            Priority = 999,
            Label = row.Label,
            MaterialType = row.MaterialType,
            Status = "Recommendation idea",
            Standout = $"{row.TierText} · {row.ScoreText}",
            SuggestionCategory = row.RecommendationType,
            DataReason = row.Reason,
            SuggestedAngle = row.ThumbnailHook,
            SuggestedTitle = row.SuggestedTitle,
            TalkingPoints = row.TalkingPoints,
            ComparisonIdea = row.VideoAngle,
            SortScore = row.Score,
            BaseMaterial = row.BaseMaterial,
            Category = row.Category,
            Manufacturer = row.Manufacturer,
            HasVideo = false,
            HasMechanical = true,
            OverallScore = row.Profile.OverallScore,
            TensileScore = row.Profile.TensileScore,
            ImpactScore = row.Profile.ImpactScore,
            StiffnessScore = row.Profile.StiffnessScore,
            ConsistencyScore = row.Profile.ConsistencyScore,
            LayerAdhesionScore = row.Profile.LayerAdhesionScore,
            PricePerKg = row.PricePerKg,
            ProductionStatus = "Idea",
            ProductionPriority = row.TierText == "Winner" ? "High" : "Medium",
            Notes = "Created from Recommendation Engine." + Environment.NewLine + handoff.VideoPlannerSummary,
            Series = GuessVideoSeries(row),
            Effort = "Medium"
        };
    }




