    private void UpdateProductionDashboard()
    {
        var ideas = _recommendationVideoIdeas;

        SetProductionCount(ProductionIdeasCountText, ideas.Count(row => string.Equals(row.ProductionStatus, "Idea", StringComparison.OrdinalIgnoreCase)));
        SetProductionCount(ProductionResearchingCountText, ideas.Count(row => string.Equals(row.ProductionStatus, "Researching", StringComparison.OrdinalIgnoreCase)));
        SetProductionCount(ProductionFilmingCountText, ideas.Count(row => string.Equals(row.ProductionStatus, "Filming", StringComparison.OrdinalIgnoreCase)));
        SetProductionCount(ProductionEditingCountText, ideas.Count(row => string.Equals(row.ProductionStatus, "Editing", StringComparison.OrdinalIgnoreCase)));
        SetProductionCount(ProductionScheduledCountText, ideas.Count(row => string.Equals(row.ProductionStatus, "Scheduled", StringComparison.OrdinalIgnoreCase)));
        SetProductionCount(ProductionPublishedCountText, ideas.Count(row => string.Equals(row.ProductionStatus, "Published", StringComparison.OrdinalIgnoreCase)));
