    private static void SetProductionCount(TextBlock? target, int count)
    {
        if (target is not null) target.Text = count.ToString(CultureInfo.InvariantCulture);
    }


    private void LoadSavedVideoIdeas()
    {
        try
        {
            _recommendationVideoIdeas.Clear();

            foreach (var record in _database.LoadVideoIdeas())
            {
                _recommendationVideoIdeas.Add(VideoPlannerRowFromRecord(record));
            }

            if (RecommendationVideoIdeaList is not null)
            {
                RecommendationVideoIdeaList.ItemsSource = _recommendationVideoIdeas.ToList();
            }

            UpdateProductionDashboard();
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Could not load saved video ideas", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

    private void SaveVideoIdeaQueue()
    {
        try
        {
            _database.SaveVideoIdeas(_recommendationVideoIdeas.Select(VideoPlannerRowToRecord));
        }
        catch (Exception ex)
        {
            if (VideoPlannerStatusText is not null)
            {
                VideoPlannerStatusText.Text = $"Could not save video idea queue: {ex.Message}";
            }
        }
    }


    private static string GuessVideoSeries(RecommendationRow row)
    {
        var materialText = $"{row.Label} {row.MaterialType}".ToLowerInvariant();

        if (materialText.Contains("yasin")) return "Yasin";
        if (materialText.Contains("3dprima") || materialText.Contains("prima creator") || materialText.Contains("primaselect") || materialText.Contains("primavalue")) return "3DPrima";
        if (materialText.Contains("extrudr")) return "Extrudr";
        if (materialText.Contains("thorwell")) return "Thorwell";
        if (materialText.Contains("experiment")) return "Experiments";

        return "General";
    }

