            Notes = row.Notes,
            PublishDate = row.PublishDate,
            TargetWeek = row.TargetWeek,
            Series = row.Series,
            EpisodeOrder = row.EpisodeOrder,
            Effort = row.Effort,
            Label = row.Label,
            MaterialType = row.MaterialType,
            SuggestionCategory = row.SuggestionCategory,
            SuggestedTitle = row.SuggestedTitle,
            SuggestedAngle = row.SuggestedAngle,
            TalkingPoints = row.TalkingPoints,
            DataReason = row.DataReason,
            Standout = row.Standout,
            ComparisonIdea = row.ComparisonIdea,
            BaseMaterial = row.BaseMaterial,
            Category = row.Category,
            Manufacturer = row.Manufacturer,
            Reinforcement = row.Reinforcement,
            Variant = row.Variant,
            ProductLine = row.ProductLine,
            OverallScore = ScoreToText(row.OverallScore),
            TensileScore = ScoreToText(row.TensileScore),
            ImpactScore = ScoreToText(row.ImpactScore),
            StiffnessScore = ScoreToText(row.StiffnessScore),
            ConsistencyScore = ScoreToText(row.ConsistencyScore),
