    private static VideoPlannerRow VideoPlannerRowFromRecord(VideoIdeaRecord record)
    {
        return new VideoPlannerRow
        {
            MaterialId = record.MaterialId,
            Priority = string.Equals(record.ProductionPriority, "High", StringComparison.OrdinalIgnoreCase) ? 1 : 999,
            Label = record.Label,
            MaterialType = record.MaterialType,
            Status = "Saved video idea",
            Standout = record.Standout,
            SuggestionCategory = record.SuggestionCategory,
            DataReason = record.DataReason,
            SuggestedAngle = record.SuggestedAngle,
            SuggestedTitle = record.SuggestedTitle,
            TalkingPoints = record.TalkingPoints,
            ComparisonIdea = record.ComparisonIdea,
            SortScore = ParseSavedScore(record.OverallScore) ?? 0,
            BaseMaterial = record.BaseMaterial,
            Category = record.Category,
            Manufacturer = record.Manufacturer,
            Reinforcement = record.Reinforcement,
            Variant = record.Variant,
            ProductLine = record.ProductLine,
            HasVideo = false,
            HasMechanical = true,
            OverallScore = ParseSavedScore(record.OverallScore),
            TensileScore = ParseSavedScore(record.TensileScore),
            ImpactScore = ParseSavedScore(record.ImpactScore),
            StiffnessScore = ParseSavedScore(record.StiffnessScore),
            ConsistencyScore = ParseSavedScore(record.ConsistencyScore),
            LayerAdhesionScore = ParseSavedScore(record.LayerAdhesionScore),
            ProductionStatus = string.IsNullOrWhiteSpace(record.ProductionStatus) ? "Idea" : record.ProductionStatus,
            ProductionPriority = string.IsNullOrWhiteSpace(record.ProductionPriority) ? "Medium" : record.ProductionPriority,
            Notes = record.Notes,
            PublishDate = record.PublishDate,
            TargetWeek = record.TargetWeek,
            Series = record.Series,
            EpisodeOrder = record.EpisodeOrder,
            Effort = string.IsNullOrWhiteSpace(record.Effort) ? "Medium" : record.Effort
        };
    }

    private static string ScoreToText(double? value)
    {
        return value.HasValue ? value.Value.ToString("0.###", CultureInfo.InvariantCulture) : string.Empty;
    }

    private static double? ParseSavedScore(string value)
    {
        return TryParseDecimalAware(value, out var number) ? number : null;
    }

