    private void UpdateSelectedMaterialIntelligence(DataRow row, IReadOnlyList<VideoPlannerRow>? activePlannerRows = null)
    {
        if (SelectedMaterialIntelligenceTitle is null) return;

        var materialId = row.Table.Columns.Contains("Material ID")
            ? row["Material ID"]?.ToString()?.Trim() ?? string.Empty
            : string.Empty;
        if (string.IsNullOrWhiteSpace(materialId))
        {
            ResetSelectedMaterialIntelligence();
            return;
        }

        var nativeMaterial = _nativeMaterialRows.FirstOrDefault(item =>
            !item.IsArchived && item.MaterialID.Equals(materialId, StringComparison.OrdinalIgnoreCase));
        IReadOnlyDictionary<string, MaterialResults> summaries = nativeMaterial is null
            ? new Dictionary<string, MaterialResults>(StringComparer.OrdinalIgnoreCase)
            : BuildVerifiedMaterialSummaryMap(new[] { nativeMaterial });
        var material = BuildVideoPlannerRow(row, summaries);
        var profile = new EngineeringScoreProfile
        {
            TensileScore = material.TensileScore,
            ImpactScore = material.ImpactScore,
            StiffnessScore = material.StiffnessScore,
            ConsistencyScore = material.ConsistencyScore,
            LayerAdhesionScore = material.LayerAdhesionScore,
            OverallScore = material.OverallScore
        };
        var consistency = _engineeringConsistencyService.Analyze(material.VerifiedSummary, profile.ConsistencyScore);
        var peerCandidates = (activePlannerRows ?? BuildFilteredRecommendationPlannerRows())
            .Select(candidate => new EngineeringPeerCandidate
            {
                MaterialId = candidate.MaterialId,
                Label = candidate.Label,
                Manufacturer = candidate.Manufacturer,
                Category = candidate.Category,
                OverallScore = candidate.OverallScore
            })
            .ToList();
        var peerPosition = _engineeringPeerPositionService.Analyze(materialId, peerCandidates);

        SelectedMaterialIntelligenceTitle.Text = material.Label;
        SelectedMaterialIntelligenceScore.Text = $"Overall engineering profile: {FormatScoreValue(profile.OverallScore)}/100 · Verified summary: {material.VerifiedSummary?.SummaryStatus ?? "unavailable"}";
        SelectedMaterialIntelligenceEvidence.Text = BuildSelectedMaterialEvidence(profile);
        SelectedMaterialIntelligenceConsistencyStatus.Text = consistency.StatusLabel;
        SelectedMaterialIntelligenceConsistencySummary.Text = consistency.RepeatabilitySummary;
        SelectedMaterialIntelligenceOutlierReview.Text = consistency.OutlierReviewSummary;
        SelectedMaterialIntelligenceManufacturerPosition.Text = peerPosition.ManufacturerPositionSummary;
        SelectedMaterialIntelligenceCategoryPosition.Text = peerPosition.CategoryPositionSummary;
    }

    private static string BuildSelectedMaterialEvidence(EngineeringScoreProfile profile)
    {
        var axes = new (string Name, double? Score)[]
        {
            ("Tensile", profile.TensileScore),
            ("Impact", profile.ImpactScore),
            ("Stiffness", profile.StiffnessScore),
            ("Consistency", profile.ConsistencyScore),
            ("Layer adhesion", profile.LayerAdhesionScore)
        };
        var available = axes.Where(axis => axis.Score.HasValue).ToList();
        var missing = axes.Where(axis => !axis.Score.HasValue).Select(axis => axis.Name).ToList();
        if (available.Count == 0)
        {
            return "No verified engineering score axes are available for this material yet.";
        }

        var strongest = available.OrderByDescending(axis => axis.Score).First();
        var missingText = missing.Count == 0
            ? "All five engineering axes are represented."
            : $"Missing evidence: {string.Join(", ", missing)}.";
        return $"{available.Count}/5 engineering axes available. Strongest available axis: {strongest.Name} {strongest.Score:0}/100. {missingText}";
    }

    private void ResetSelectedMaterialIntelligence()
    {
        if (SelectedMaterialIntelligenceTitle is null) return;
        SelectedMaterialIntelligenceTitle.Text = "Select a material in Materials.";
        SelectedMaterialIntelligenceScore.Text = "—";
        SelectedMaterialIntelligenceEvidence.Text = "—";
        SelectedMaterialIntelligenceConsistencyStatus.Text = "Repeatability unavailable";
        SelectedMaterialIntelligenceConsistencySummary.Text = "Select a material to load its verified repeatability context.";
        SelectedMaterialIntelligenceOutlierReview.Text = "—";
        SelectedMaterialIntelligenceManufacturerPosition.Text = "—";
        SelectedMaterialIntelligenceCategoryPosition.Text = "—";
    }

    private static DataRow? ResolveMaterialDetailIntelligenceRow(DataRow? displayedMaterialDetailRow, DataRow? gridSelectionFallback) =>
        displayedMaterialDetailRow ?? gridSelectionFallback;

    private List<VideoPlannerRow> BuildFilteredRecommendationPlannerRows()
    {
        var plannerRows = BuildCanonicalVisiblePlannerRows()
            .Where(row => row.HasMechanical && row.OverallScore.HasValue)
            .ToList();

        var categoryFilter = SelectedComboText(RecommendationCategoryFilter);
        if (!string.IsNullOrWhiteSpace(categoryFilter) && categoryFilter != "All")
        {
            plannerRows = plannerRows
                .Where(row => row.Category.Equals(categoryFilter, StringComparison.OrdinalIgnoreCase) || row.MaterialType.Contains(categoryFilter, StringComparison.OrdinalIgnoreCase))
                .ToList();
        }

        var baseMaterialFilter = SelectedComboText(RecommendationBaseMaterialFilter);
        if (!string.IsNullOrWhiteSpace(baseMaterialFilter) && baseMaterialFilter != "All")
        {
            plannerRows = plannerRows
                .Where(row => row.BaseMaterial.Equals(baseMaterialFilter, StringComparison.OrdinalIgnoreCase) || row.MaterialType.Contains(baseMaterialFilter, StringComparison.OrdinalIgnoreCase))
                .ToList();
        }

        return plannerRows;
    }

    private void UpdateRecommendations()
    {
        if (PerformanceRecommendationList is null || ApplicationRecommendationList is null) return;

        if (GetCanonicalVisibleMaterialRows().Count == 0)
        {
            PerformanceRecommendationList.ItemsSource = null;
            ApplicationRecommendationList.ItemsSource = null;
            RecommendationStatusText.Text = "Load Materials data to build recommendations.";
            ResetRecommendationDetailPanel();
            return;
        }

        var selectedMaterialRow = ResolveMaterialDetailIntelligenceRow(_currentMaterialDetailRow, CurrentSelectedMaterialRow());
        var plannerRows = BuildFilteredRecommendationPlannerRows();
        if (selectedMaterialRow is not null)
        {
            UpdateSelectedMaterialIntelligence(selectedMaterialRow, plannerRows);
        }

        var recommendations = BuildRecommendationRows(plannerRows);
        ApplyEngineeringAdvisor(recommendations, plannerRows);
        var useCase = SelectedComboText(RecommendationUseCaseFilter);
        if (!string.IsNullOrWhiteSpace(useCase) && useCase != "All recommendations")
        {
            recommendations = recommendations
                .Where(row => row.RecommendationType.Equals(useCase, StringComparison.OrdinalIgnoreCase))
                .ToList();
        }

        recommendations = recommendations
            .GroupBy(row => row.RecommendationType)
            .SelectMany(group => group
                .OrderBy(row => row.Rank)
                .ThenByDescending(row => row.Score)
                .Take(3))
            .OrderBy(row => RecommendationSortGroup(row.RecommendationType))
            .ThenBy(row => row.Rank)
            .ThenByDescending(row => row.Score)
            .ToList();

        var performanceRecommendations = recommendations
            .Where(row => IsPerformanceLeaderRecommendation(row.RecommendationType))
            .ToList();

        var applicationRecommendations = recommendations
            .Where(row => !IsPerformanceLeaderRecommendation(row.RecommendationType))
            .ToList();

        PerformanceRecommendationList.ItemsSource = performanceRecommendations;
        ApplicationRecommendationList.ItemsSource = applicationRecommendations;

        PerformanceRecommendationList.SelectedItem = performanceRecommendations.FirstOrDefault();
        ApplicationRecommendationList.SelectedItem = null;
        if (PerformanceRecommendationList.SelectedItem is RecommendationRow selectedPerformance)
        {
            UpdateRecommendationDetailPanel(selectedPerformance);
        }
        else if (applicationRecommendations.FirstOrDefault() is RecommendationRow selectedApplication)
        {
            ApplicationRecommendationList.SelectedItem = selectedApplication;
            UpdateRecommendationDetailPanel(selectedApplication);
        }
        else
        {
            ResetRecommendationDetailPanel();
        }

        RecommendationStatusText.Text = $"Showing winner / runner-up / third-place recommendations ({recommendations.Count} rows) from {plannerRows.Count} mechanically tested visible material{(plannerRows.Count == 1 ? string.Empty : "s")}. Performance leaders: {performanceRecommendations.Count}. Application recommendations: {applicationRecommendations.Count}.";
    }

    private static bool IsPerformanceLeaderRecommendation(string recommendationType) => recommendationType switch
    {
        "Best overall" => true,
        "Strongest" => true,
        "Highest impact" => true,
        "Stiffest" => true,
        "Most consistent" => true,
        "Best layer adhesion" => true,
        "Best by material family" => true,
        _ => false
    };

    private static string SelectedComboText(ComboBox? combo)
    {
        if (combo?.SelectedItem is ComboBoxItem item) return item.Content?.ToString() ?? string.Empty;
        return combo?.SelectedItem?.ToString() ?? string.Empty;
    }

    private static void SelectComboValue(ComboBox? combo, string value)
    {
        if (combo is null) return;

        foreach (var item in combo.Items)
        {
            var text = item is ComboBoxItem comboItem
                ? comboItem.Content?.ToString()
                : item?.ToString();

            if (string.Equals(text, value, StringComparison.OrdinalIgnoreCase))
            {
                combo.SelectedItem = item;
                return;
            }
        }

        if (combo.Items.Count > 0) combo.SelectedIndex = 0;
    }

    private static int RecommendationSortGroup(string recommendationType) => recommendationType switch
    {
        "Best overall" => 0,
        "Strongest" => 1,
        "Highest impact" => 2,
        "Stiffest" => 3,
        "Most consistent" => 4,
        "Best layer adhesion" => 5,
        "Best by material family" => 6,
        "Best outdoor material" => 7,
        "Best functional part material" => 8,
        "Best beginner engineering material" => 9,
        "Best impact resistant material" => 10,
        "Best layer adhesion material" => 11,
        "Best stiffness-focused material" => 12,
        "Best consistency-focused material" => 13,
        _ => 99
    };

    private static List<RecommendationRow> BuildRecommendationRows(List<VideoPlannerRow> rows)
    {
        var recommendations = new List<RecommendationRow>();
        AddTopRecommendationRows(recommendations, rows, "Best overall", r => r.OverallScore, "Best balanced profile across tensile, impact, stiffness, consistency, and layer adhesion.");
        AddTopRecommendationRows(recommendations, rows, "Strongest", r => r.TensileScore, "Best tensile-focused candidate from the current visible dataset.");
        AddTopRecommendationRows(recommendations, rows, "Highest impact", r => r.ImpactScore, "Best impact-resistance candidate from the current visible dataset.");
        AddTopRecommendationRows(recommendations, rows, "Stiffest", r => r.StiffnessScore, "Best stiffness-focused candidate from the current visible dataset.");
        AddTopRecommendationRows(recommendations, rows, "Most consistent", r => r.ConsistencyScore, "Most repeatable results based on the imported CV-based consistency score.");
        AddTopRecommendationRows(recommendations, rows, "Best layer adhesion", r => r.LayerAdhesionScore, "Best layer-adhesion profile based on upright-vs-flat tensile behavior.");
        AddBestByMaterialFamily(recommendations, rows);
        AddContextAwareRecommendationRows(recommendations, rows);
        return recommendations;
    }

    private void ApplyEngineeringAdvisor(List<RecommendationRow> recommendations, IReadOnlyList<VideoPlannerRow> plannerRows)
    {
        var inventory = BuildInventorySummary();
        var manufacturers = _database.LoadManufacturers();
        var peerCandidates = plannerRows.Select(row => new EngineeringPeerCandidate
        {
            MaterialId = row.MaterialId,
            Label = row.Label,
            Manufacturer = row.Manufacturer,
            Category = row.Category,
            OverallScore = row.OverallScore
        }).ToList();
        var peerInsights = peerCandidates
            .Where(candidate => !string.IsNullOrWhiteSpace(candidate.MaterialId))
            .GroupBy(candidate => candidate.MaterialId, StringComparer.OrdinalIgnoreCase)
            .ToDictionary(
                group => group.Key,
                group => _engineeringPeerPositionService.Analyze(group.Key, peerCandidates),
                StringComparer.OrdinalIgnoreCase);
        foreach (var group in recommendations.GroupBy(row => row.RecommendationType))
        {
            var ranked = group.OrderBy(row => row.Rank).ThenByDescending(row => row.Score).ToList();
            for (var index = 0; index < ranked.Count; index++)
            {
                var row = ranked[index];
                var comparison = index == 0
                    ? ranked.ElementAtOrDefault(1)
                    : ranked[index - 1];

                row.AdvisorInsight = _engineeringAdvisorService.Explain(
                    ToAdvisorCandidate(row),
                    comparison is null ? null : ToAdvisorCandidate(comparison));
                row.ConsistencyInsight = _engineeringConsistencyService.Analyze(row.VerifiedSummary, row.Profile.ConsistencyScore);
                row.ContextInsight = _engineeringContextService.Analyze(
                    row.MaterialId,
                    row.Manufacturer,
                    row.PricePerKg,
                    inventory,
                    manufacturers);
                row.ValueIndex = _engineeringValueIndexService.Calculate(
                    row.Profile.OverallScore,
                    row.PricePerKg,
                    !string.IsNullOrWhiteSpace(row.BaseMaterial)
                        ? $"current filtered {row.BaseMaterial.Trim()} group"
                        : "current filtered material dataset");
                if (peerInsights.TryGetValue(row.MaterialId, out var peerInsight)) row.PeerInsight = peerInsight;
                row.Alternatives = _engineeringAdvisorService.FindAlternatives(
                    ToAdvisorCandidate(row),
                    ranked.Select(ToAdvisorCandidate));
                row.IntelligenceHandoff = _engineeringIntelligenceHandoffService.Build(
                    row.AdvisorInsight,
                    row.ConsistencyInsight,
                    row.ContextInsight,
                    row.PeerInsight,
                    row.Alternatives);
            }
        }
    }

    private static EngineeringAdvisorCandidate ToAdvisorCandidate(RecommendationRow row) => new()
    {
        Label = row.Label,
        MaterialId = row.MaterialId,
        RecommendationType = row.RecommendationType,
        Category = row.Category,
        BaseMaterial = row.BaseMaterial,
        RecommendationScore = row.Score,
        PricePerKg = row.PricePerKg,
        Profile = row.Profile
    };

    private static void AddTopRecommendationRows(List<RecommendationRow> target, List<VideoPlannerRow> rows, string type, Func<VideoPlannerRow, double?> selector, string reasonPrefix)
    {
        var topRows = rows
            .Where(row => selector(row).HasValue)
            .OrderByDescending(row => selector(row)!.Value)
            .Take(8)
            .ToList();

        var rank = 1;
        foreach (var row in topRows)
        {
            var score = selector(row)!.Value;
            target.Add(CreateRecommendationRow(rank++, type, row, score, BuildRecommendationReason(reasonPrefix, row, score), BuildRecommendationBestUse(type, row), BuildRecommendationCaution(type, row), BuildRecommendationVideoAngle(type, row, score)));
        }
    }

    private static void AddBestByMaterialFamily(List<RecommendationRow> target, List<VideoPlannerRow> rows)
    {
        var familyWinners = rows
            .Where(row => !string.IsNullOrWhiteSpace(row.BaseMaterial) && row.OverallScore.HasValue)
            .GroupBy(row => row.BaseMaterial.Trim(), StringComparer.OrdinalIgnoreCase)
            .Select(group => group.OrderByDescending(row => row.OverallScore ?? 0).First())
            .OrderBy(row => row.BaseMaterial, StringComparer.CurrentCultureIgnoreCase)
            .ToList();

        var rank = 1;
        foreach (var row in familyWinners)
        {
            var score = row.OverallScore ?? 0;
            target.Add(CreateRecommendationRow(rank++, "Best by material family", row, score, $"Best {row.BaseMaterial} candidate in the currently visible dataset.", $"Start here when choosing a {row.BaseMaterial} material.", BuildRecommendationCaution("Best overall", row), $"Best {row.BaseMaterial}: why {ShortenPlannerText(row.Label, 48)} stands out."));
        }
    }
    private static void AddContextAwareRecommendationRows(List<RecommendationRow> target, List<VideoPlannerRow> rows)
    {
        AddContextUseCaseRows(
            target,
            rows.Where(IsOutdoorCandidate),
            "Best outdoor material",
            r => WeightedScore(r, (r.LayerAdhesionScore, 0.28), (r.StiffnessScore, 0.24), (r.ConsistencyScore, 0.22), (r.ImpactScore, 0.16), (r.TensileScore, 0.10)),
            "Best balance of layer adhesion, stiffness, consistency, and impact for outdoor-style functional parts.");

        AddContextUseCaseRows(
            target,
            rows,
            "Best functional part material",
            r => WeightedScore(r, (r.OverallScore, 0.35), (r.TensileScore, 0.20), (r.ImpactScore, 0.20), (r.LayerAdhesionScore, 0.15), (r.ConsistencyScore, 0.10)),
            "Best balanced mechanical profile for real functional printed parts.");

        AddContextUseCaseRows(
            target,
            rows.Where(IsBeginnerEngineeringCandidate),
            "Best beginner engineering material",
            r => WeightedScore(r, (r.OverallScore, 0.35), (r.ConsistencyScore, 0.30), (r.LayerAdhesionScore, 0.20), (r.ImpactScore, 0.15)) - ReinforcementDifficultyPenalty(r),
            "Good engineering-category performance with a preference for repeatability and simpler unfilled materials.");

        AddContextUseCaseRows(
            target,
            rows,
            "Best impact resistant material",
            r => WeightedScore(r, (r.ImpactScore, 0.65), (r.ConsistencyScore, 0.20), (r.LayerAdhesionScore, 0.15)),
            "Impact-focused choice that still considers consistency and layer behavior.");

        AddContextUseCaseRows(
            target,
            rows,
            "Best layer adhesion material",
            r => WeightedScore(r, (r.LayerAdhesionScore, 0.70), (r.TensileScore, 0.15), (r.ConsistencyScore, 0.15)),
            "Best upright-vs-flat tensile behavior for layer-sensitive structural prints.");

        AddContextUseCaseRows(
            target,
            rows,
            "Best stiffness-focused material",
            r => WeightedScore(r, (r.StiffnessScore, 0.70), (r.TensileScore, 0.15), (r.ConsistencyScore, 0.15)),
            "Rigid material choice where stiffness and dimensional stability matter most.");

        AddContextUseCaseRows(
            target,
            rows,
            "Best consistency-focused material",
            r => WeightedScore(r, (r.ConsistencyScore, 0.75), (r.OverallScore, 0.25)),
            "Most repeatable material profile in the currently visible dataset.");
    }

    private static void AddContextUseCaseRows(List<RecommendationRow> target, IEnumerable<VideoPlannerRow> sourceRows, string type, Func<VideoPlannerRow, double> selector, string reasonPrefix)
    {
        var ranked = sourceRows
            .Where(row => row.HasMechanical)
            .Select(row => new { Row = row, Score = selector(row) })
            .Where(item => !double.IsNaN(item.Score) && item.Score > 0)
            .OrderByDescending(item => item.Score)
            .Take(8)
            .ToList();

        var rank = 1;
        foreach (var item in ranked)
        {
            target.Add(CreateRecommendationRow(
                rank++,
                type,
                item.Row,
                item.Score,
                BuildContextRecommendationReason(reasonPrefix, item.Row, item.Score),
                BuildRecommendationBestUse(type, item.Row),
                BuildRecommendationCaution(type, item.Row),
                BuildRecommendationVideoAngle(type, item.Row, item.Score)));
        }
    }

    private static double WeightedScore(VideoPlannerRow row, params (double? Value, double Weight)[] parts)
    {
        var totalWeight = 0.0;
        var total = 0.0;
        foreach (var part in parts)
        {
            if (!part.Value.HasValue) continue;
            total += ClampScore(part.Value.Value) * part.Weight;
            totalWeight += part.Weight;
        }

        return totalWeight <= 0 ? 0 : total / totalWeight;
    }

    private static double ClampScore(double value) => Math.Max(0, Math.Min(100, value));

    private static bool IsOutdoorCandidate(VideoPlannerRow row)
    {
        var material = row.BaseMaterial.ToUpperInvariant();
        return material.Contains("ASA") || material.Contains("ABS") || material.Contains("PETG") || material.Contains("PCTG") || material.Contains("PC") || material.Contains("PA") || material.Contains("PP");
    }

    private static bool IsBeginnerEngineeringCandidate(VideoPlannerRow row)
    {
        var category = row.Category.ToLowerInvariant();
        var material = row.BaseMaterial.ToUpperInvariant();
        if (!category.Contains("engineering") && !(material.Contains("ASA") || material.Contains("PETG") || material.Contains("PCTG") || material.Contains("PC"))) return false;
        return true;
    }

    private static double ReinforcementDifficultyPenalty(VideoPlannerRow row)
    {
        if (string.IsNullOrWhiteSpace(row.Reinforcement)) return 0;
        var reinforcement = row.Reinforcement.ToUpperInvariant();
        if (reinforcement.Contains("CF") || reinforcement.Contains("GF")) return 8;
        return 4;
    }

    private static string BuildContextRecommendationReason(string prefix, VideoPlannerRow row, double score)
    {
        var components = $"Tensile {FormatScoreValue(row.TensileScore)}, impact {FormatScoreValue(row.ImpactScore)}, stiffness {FormatScoreValue(row.StiffnessScore)}, consistency {FormatScoreValue(row.ConsistencyScore)}, layer adhesion {FormatScoreValue(row.LayerAdhesionScore)}.";
        var noVideo = row.HasVideo ? string.Empty : " No YouTube review yet.";
        return $"{prefix} Weighted score: {score:0}/100. {components}{noVideo}";
    }

    private static string FormatScoreValue(double? value) => value.HasValue ? $"{value.Value:0}" : "n/a";


    private static RecommendationRow CreateRecommendationRow(int rank, string type, VideoPlannerRow row, double score, string reason, string bestUse, string caution, string videoAngle)
    {
        var suggestedTitle = BuildRecommendationSuggestedTitle(type, row, score);
        return new RecommendationRow
        {
            Rank = rank,
            RecommendationType = type,
            Label = row.Label,
            MaterialType = row.MaterialType,
            Score = score,
            Reason = reason,
            BestUse = bestUse,
            Caution = caution,
            VideoAngle = videoAngle,
            SuggestedTitle = suggestedTitle,
            ThumbnailHook = BuildRecommendationThumbnailHook(type, row, score),
            TalkingPoints = BuildRecommendationTalkingPoints(type, row, score),
            Category = row.Category,
            BaseMaterial = row.BaseMaterial,
            Manufacturer = row.Manufacturer,
            MaterialId = row.MaterialId,
            PricePerKg = row.PricePerKg,
            VerifiedSummary = row.VerifiedSummary,
            Profile = new EngineeringScoreProfile
            {
                TensileScore = row.TensileScore,
                ImpactScore = row.ImpactScore,
                StiffnessScore = row.StiffnessScore,
                ConsistencyScore = row.ConsistencyScore,
                LayerAdhesionScore = row.LayerAdhesionScore,
                OverallScore = row.OverallScore
            }
        };
    }

    private static string BuildRecommendationReason(string prefix, VideoPlannerRow row, double score)
    {
        var noVideo = row.HasVideo ? string.Empty : " No YouTube review yet.";
        return $"{prefix} Score: {score:0}/100.{noVideo}";
    }

    private static string BuildRecommendationBestUse(string type, VideoPlannerRow row) => type switch
    {
        "Strongest" => "Functional parts where tensile strength matters most.",
        "Highest impact" => "Parts that need toughness or impact resistance.",
        "Stiffest" => "Rigid brackets, fixtures, and dimensional stability tests.",
        "Most consistent" => "Repeatable prints and reliable comparison benchmarks.",
        "Best layer adhesion" => "Structural prints where upright/layer direction matters.",
        "Best outdoor material" => "Outdoor-style brackets, fixtures and parts where heat/UV-tolerant material families and layer behavior matter.",
        "Best functional part material" => "General functional parts where the best balanced mechanical profile matters more than one peak metric.",
        "Best beginner engineering material" => "First engineering-grade material candidate to test before moving into more difficult reinforced or nylon-based options.",
        "Best impact resistant material" => "Parts that need toughness, drops, knocks or energy absorption.",
        "Best layer adhesion material" => "Structural prints where upright/layer direction matters.",
        "Best stiffness-focused material" => "Rigid brackets, fixtures, mounts and parts where deformation should be minimized.",
        "Best consistency-focused material" => "Repeatable testing, dependable prints and benchmarking where low variation matters.",
        "Best overall" => $"Balanced {SafeLower(row.BaseMaterial, "material")} recommendation.",
        _ => $"Best visible {SafeLower(row.BaseMaterial, "material")} candidate."
    };

    private static string BuildRecommendationCaution(string type, VideoPlannerRow row)
    {
        if (row.ConsistencyScore < 55) return "Consistency score is low, so verify sample spread before making a strong claim.";
        if (row.LayerAdhesionScore < 40 && type != "Best layer adhesion") return "Layer adhesion score is weaker than the rest of the profile.";
        if (row.ImpactScore < 40 && type == "Strongest") return "Strength is good, but impact resistance may not match it.";
        if (row.TensileScore < 40 && (type == "Highest impact" || type == "Best impact resistant material")) return "Impact is strong, but tensile strength may be the trade-off.";
        if (type == "Best outdoor material") return "Outdoor recommendation is based on material family and mechanical profile; verify UV/weather behavior and print settings before final use.";
        if (type == "Best beginner engineering material" && !string.IsNullOrWhiteSpace(row.Reinforcement)) return "Reinforcement may require abrasive-capable nozzles and more tuning than unfilled materials.";
        return "Check printability and price before turning this into a final recommendation.";
    }

    private static string BuildRecommendationSuggestedTitle(string type, VideoPlannerRow row, double score)
    {
        var material = CleanMaterialName(row.BaseMaterial);
        var shortName = ShortenPlannerText(row.Label, 52);
        var reinforcement = CleanMaterialName(row.Reinforcement);
        var reinforcedName = string.IsNullOrWhiteSpace(reinforcement) ? material : $"{material} {reinforcement}";

        return type switch
        {
            "Best overall" => $"Is This the Best All-Round {material}? | {shortName}",
            "Strongest" => $"The Strongest {reinforcedName} I've Tested | {shortName}",
            "Highest impact" => $"This {material} Takes a Hit Better Than Expected | {shortName}",
            "Stiffest" => $"The Stiffest {reinforcedName} I've Tested | {shortName}",
            "Most consistent" => $"The Most Repeatable {material} Result So Far | {shortName}",
            "Best layer adhesion" => $"This {material} Refuses To Delaminate | {shortName}",
            "Best by material family" => $"The Best {material} Candidate in My Test Database | {shortName}",
            "Best outdoor material" => $"The Best Outdoor-Style {material} I've Tested | {shortName}",
            "Best functional part material" => $"The Best Functional Filament in My Database? | {shortName}",
            "Best beginner engineering material" => $"The Beginner-Friendly Engineering Filament? | {shortName}",
            "Best impact resistant material" => $"The Toughest Filament I've Tested? | {shortName}",
            "Best layer adhesion material" => $"The Best Layer Bonding I've Tested | {shortName}",
            "Best stiffness-focused material" => $"No Flex: The Stiffest Filament I've Tested | {shortName}",
            "Best consistency-focused material" => $"The Most Reliable Filament in My Tests | {shortName}",
            _ => $"Why {shortName} Stands Out in the Data"
        };
    }

    private static string BuildRecommendationThumbnailHook(string type, VideoPlannerRow row, double score)
    {
        return type switch
        {
            "Best overall" => "BEST ALL-ROUNDER?",
            "Strongest" => "STRONGEST YET?",
            "Highest impact" => "TAKES A HIT?",
            "Stiffest" => "NO FLEX?",
            "Most consistent" => "MOST RELIABLE?",
            "Best layer adhesion" => "NO DELAMINATION?",
            "Best by material family" => $"BEST {SafeUpper(row.BaseMaterial, "MATERIAL")}?",
            "Best outdoor material" => "OUTDOOR KING?",
            "Best functional part material" => "FUNCTIONAL KING?",
            "Best beginner engineering material" => "EASY ENGINEERING?",
            "Best impact resistant material" => "TOUGHEST?",
            "Best layer adhesion material" => "BEST BONDING?",
            "Best stiffness-focused material" => "STIFFEST?",
            "Best consistency-focused material" => "REPEATABLE?",
            _ => "WORTH TESTING?"
        };
    }

    private static string BuildRecommendationTalkingPoints(string type, VideoPlannerRow row, double score)
    {
        var points = new List<string>
        {
            $"Score {score:0}/100",
            $"Best axis: {BestScoreAxis(row)}",
            $"Tensile {FormatScoreValue(row.TensileScore)}",
            $"Impact {FormatScoreValue(row.ImpactScore)}",
            $"Stiffness {FormatScoreValue(row.StiffnessScore)}",
            $"Consistency {FormatScoreValue(row.ConsistencyScore)}",
            $"Layer adhesion {FormatScoreValue(row.LayerAdhesionScore)}"
        };

        if (!row.HasVideo) points.Add("No YouTube review yet");
        if (!string.IsNullOrWhiteSpace(row.Reinforcement)) points.Add($"Reinforcement: {row.Reinforcement}");
        if (!string.IsNullOrWhiteSpace(row.Category)) points.Add($"Category: {row.Category}");

        var tradeOff = BiggestTradeoff(row);
        if (!string.IsNullOrWhiteSpace(tradeOff)) points.Add($"Watch: {tradeOff}");

        return string.Join(" • ", points);
    }

    private static string CleanMaterialName(string? value)
    {
        if (string.IsNullOrWhiteSpace(value)) return "filament";
        return value.Trim();
    }

    private static string BestScoreAxis(VideoPlannerRow row)
    {
        var scores = new List<(string Name, double? Value)>
        {
            ("tensile", row.TensileScore),
            ("impact", row.ImpactScore),
            ("stiffness", row.StiffnessScore),
            ("consistency", row.ConsistencyScore),
            ("layer adhesion", row.LayerAdhesionScore)
        };

        var best = scores
            .Where(s => s.Value.HasValue)
            .OrderByDescending(s => s.Value!.Value)
            .FirstOrDefault();

        return string.IsNullOrWhiteSpace(best.Name) ? "n/a" : $"{best.Name} ({best.Value:0}/100)";
    }

    private static string BiggestTradeoff(VideoPlannerRow row)
    {
        var scores = new List<(string Name, double? Value)>
        {
            ("tensile", row.TensileScore),
            ("impact", row.ImpactScore),
            ("stiffness", row.StiffnessScore),
            ("consistency", row.ConsistencyScore),
            ("layer adhesion", row.LayerAdhesionScore)
        }
        .Where(s => s.Value.HasValue)
        .ToList();

        if (scores.Count == 0) return string.Empty;

        var weakest = scores.OrderBy(s => s.Value!.Value).First();
        return weakest.Value < 45 ? $"{weakest.Name} is the weak point ({weakest.Value:0}/100)" : string.Empty;
    }

    private static string SafeUpper(string? value, string fallback)
    {
        if (string.IsNullOrWhiteSpace(value)) return fallback;
        return value.Trim().ToUpperInvariant();
    }

    private static string BuildRecommendationVideoAngle(string type, VideoPlannerRow row, double score)
    {
        var material = string.IsNullOrWhiteSpace(row.BaseMaterial) ? "filament" : row.BaseMaterial;
        var shortName = ShortenPlannerText(row.Label, 52);
        return type switch
        {
            "Best overall" => $"Is this the best balanced {material}? | {shortName}",
            "Strongest" => $"The strongest {material} in my database? | {shortName}",
            "Highest impact" => $"This {material} takes a hit better than expected | {shortName}",
            "Stiffest" => $"The stiffest {material} I tested | {shortName}",
            "Most consistent" => $"The most repeatable {material} result so far | {shortName}",
            "Best layer adhesion" => $"Layer adhesion matters — and this {material} stands out | {shortName}",
            "Best by material family" => $"Best {material} candidate from my test database | {shortName}",
            "Best outdoor material" => $"Best outdoor-style {material} from my tests? | {shortName}",
            "Best functional part material" => $"Best functional filament in my database? | {shortName}",
            "Best beginner engineering material" => $"The easiest engineering filament to recommend? | {shortName}",
            "Best impact resistant material" => $"The toughest filament I tested? | {shortName}",
            "Best layer adhesion material" => $"Layer adhesion matters — this filament stands out | {shortName}",
            "Best stiffness-focused material" => $"The stiffest filament I tested? | {shortName}",
            "Best consistency-focused material" => $"The most repeatable filament result so far | {shortName}",
            _ => $"Why {shortName} stands out in the data"
        };
    }


    private void RefreshWebsiteTemplateManager()
    {
        try
        {
            var templates = _database.GetWebsiteTemplates();
            if (FindName("WebsiteTemplateVersionCombo") is ComboBox combo)
            {
                combo.ItemsSource = templates;
                combo.DisplayMemberPath = nameof(WebsiteTemplateRecord.DisplayLabel);
                combo.SelectedItem = templates.FirstOrDefault(x => x.IsActive);
            }
            if (FindName("WebsiteTemplateDatabaseStatusText") is TextBlock status)
            {
                var active = templates.FirstOrDefault(x => x.IsActive);
                status.Text = active is null ? "No active database template" : $"Active: {active.TemplateVersion} • {templates.Count} stored version(s) • SHA-256 {active.ContentHash[..Math.Min(12, active.ContentHash.Length)]}…";
            }
        }
        catch (Exception ex)
        {
            if (FindName("WebsiteTemplateDatabaseStatusText") is TextBlock status) status.Text = "Template database unavailable: " + ex.Message;
        }
    }

    private void ImportWebsiteTemplateToDatabase_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            var dialog = new OpenFileDialog { Title = "Import website master template", Filter = "HTML files (*.html)|*.html|All files (*.*)|*.*" };
            if (dialog.ShowDialog(this) != true) return;
            var fileInfo = new FileInfo(dialog.FileName);
            if (fileInfo.Length > WebsiteHtmlRendererService.MaximumTemplateBytes)
                throw new InvalidOperationException("Website template exceeds the 5 MiB import limit.");

            var html = IOFile.ReadAllText(dialog.FileName, Encoding.UTF8);
            _websiteHtmlRendererService.ValidateTemplateForImport(html);

            var confirmed = MessageBox.Show(
                this,
                "This HTML file can contain executable JavaScript. Importing it stores and immediately activates it as the main website " +
                "template, so its content can run during Preview/Production generation and can be published through the existing FTPS workflow.\n\n" +
                "Only continue if you trust the file and its source. The application validates the required DATA boundary but cannot make " +
                "arbitrary HTML safe.\n\nImport and activate this template?",
                "Trust and Activate Website Template?",
                MessageBoxButton.YesNo,
                MessageBoxImage.Warning,
                MessageBoxResult.No);
            if (confirmed != MessageBoxResult.Yes) return;

            var imported = _database.ImportWebsiteTemplate(
                html,
                IOPath.GetFileName(dialog.FileName),
                "Imported through Website Export with the v44.7.13 explicit trust boundary.");
            RefreshWebsiteTemplateManager();
            WebsiteExportPreviewLog.Text = $"Website template imported into SQLite and activated.\n\nVersion: {imported.TemplateVersion}\nSource: {imported.SourceFileName}\nSHA-256: {imported.ContentHash}\n\nFuture main website exports will use this database version.";
            WebsiteExportSummaryText.Text = "Database template imported";
        }
        catch (Exception ex) { MessageBox.Show(this, ex.Message, "Template Import Failed", MessageBoxButton.OK, MessageBoxImage.Error); }
    }

