    private async Task<bool> RunFtpsConnectionTestAsync(bool showSuccess)
    {
        if (IsAutomationActionBlocked("FTPS connection")) return false;
        var deployment = _database.LoadDeploymentSettings();
        var password = FtpsPasswordBox.Password;
        if (string.IsNullOrWhiteSpace(password)) password = WindowsCredentialService.ReadPassword(deployment.FtpsHost, deployment.FtpsUserName);
        if (string.IsNullOrWhiteSpace(password))
        {
            MessageBox.Show(this, "Enter the FTPS password first. It will only be saved in Windows Credential Manager after a successful encrypted connection.", "FTPS Password Required", MessageBoxButton.OK, MessageBoxImage.Information);
            return false;
        }

        SetFtpsPublishingBusy(true, "Testing explicit FTPS connection…");
        try
        {
            var publisher = new FtpsWebsitePublisherService(deployment);
            var probe = await Task.Run(() => publisher.TestConnection(password));

            if (!probe.Connected)
            {
                MessageBox.Show(this, probe.Message, "FTPS Connection Failed", MessageBoxButton.OK, MessageBoxImage.Error);
                return false;
            }

            WindowsCredentialService.SavePassword(publisher.Host, publisher.UserName, password);
            FtpsPasswordBox.Clear();
            WebsiteExportSummaryText.Text = "FTPS connection ready";
            WebsiteExportPreviewLog.Text = $"Explicit FTPS connection successful.\n\nServer: {publisher.Host}:{publisher.Port}\nUser: {publisher.UserName}\nMode: Explicit TLS, passive data connections\nCertificate: {probe.CertificateSubject}\n\nThe password is stored in Windows Credential Manager under this host/user identity.";
            if (showSuccess) MessageBox.Show(this, "Encrypted FTPS connection succeeded and the server TLS certificate is valid.", "FTPS Ready", MessageBoxButton.OK, MessageBoxImage.Information);
            return true;
        }
        finally
        {
            SetFtpsPublishingBusy(false, "Ready.");
        }
    }

    private async void PublishWebsiteFtps_Click(object sender, RoutedEventArgs e)
    {
        if (IsAutomationActionBlocked("Production FTPS publishing")) return;
        var deployment = _database.LoadDeploymentSettings();
        if (!await GenerateWebsiteExportAsync(isProduction: true)) return;

        var folder = WebsiteExportFolderBox.Text?.Trim();
        if (string.IsNullOrWhiteSpace(folder)) folder = GetDefaultWebsiteExportFolder();
        var publishPlanPath = System.IO.Path.Combine(folder, WebsiteProductionPublishPlanService.FileName);
        WebsiteProductionPublishPlan publishPlan;
        try
        {
            publishPlan = _websiteProductionPublishPlanService.Load(publishPlanPath);
            if (!_websiteProductionPublishPlanService.VerifyLocalArtifacts(publishPlan, folder, out var failure))
                throw new InvalidOperationException(failure);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Production Publish Plan Rejected", MessageBoxButton.OK, MessageBoxImage.Error);
            return;
        }

        if (!await RunFtpsConnectionTestAsync(showSuccess: false)) return;
        var confirm = MessageBox.Show(
            this,
            $"Publish the newly generated Production website to {deployment.FtpsHost}:{deployment.FtpsPort}?\n\n" +
            $"Public MaterialIDs: {publishPlan.PublicMaterials}\n" +
            $"Catalog entries: {publishPlan.CatalogEntries}\n" +
            $"Exact allowlisted files: {publishPlan.Files.Count:N0}\n" +
            $"Complete package size before delta comparison: {publishPlan.TotalBytes:N0} bytes\n\n" +
            $"Every artifact is first checked by {FtpsWebsitePublisherService.LocalValidationWorkers} bounded parallel local workers. After confirmation, the completed Production deployment state is compared with this exact plan. Only changed, new or remotely missing targets are backed up and staged through one runtime-proven FTPS session. The first v42.12 Production publish may use a full fallback because Test and Production baselines are isolated. The root /index.html is activated last. If activation fails, changed files are rolled back and newly added files are removed.\n\nContinue with the live Production FTPS publish?",
            "Confirm Website Publish",
            MessageBoxButton.YesNo,
            MessageBoxImage.Warning,
            MessageBoxResult.No);
        if (confirm != MessageBoxResult.Yes) return;

        var password = WindowsCredentialService.ReadPassword(deployment.FtpsHost, deployment.FtpsUserName);
        SetFtpsPublishingBusy(true, "Publishing website over explicit FTPS…");
        try
        {
            var publisher = new FtpsWebsitePublisherService(deployment);
            var progress = new Progress<FtpsWebsitePublisherService.PublishProgress>(value =>
            {
                var item = string.IsNullOrWhiteSpace(value.RemotePath) ? string.Empty : " — " + value.RemotePath;
                WebsiteExportSummaryText.Text = $"{value.Phase}: {value.Completed:N0}/{value.Total:N0}";
                StatusText.Text = $"{value.Phase} {value.Completed:N0}/{value.Total:N0}{item}";
            });
            var result = await Task.Run(() => publisher.PublishPlan(password, publishPlan, progress));
            WebsiteExportSummaryText.Text = "Website published successfully";
            WebsiteExportPreviewLog.Text =
                "Guarded FTPS website publish completed successfully.\n\n" +
                $"Delta baseline: {(result.DeltaBaselineUsed ? result.BaselineFolder : "none; full publish fallback")}\n" +
                $"New remote backup: {(string.IsNullOrWhiteSpace(result.BackupFolder) ? "none; no changed artifacts" : result.BackupFolder)}\n" +
                $"Allowlisted files evaluated: {result.PlannedFiles:N0}\n" +
                $"Unchanged files skipped: {result.UnchangedFiles:N0}\n" +
                $"Files staged and size-verified: {result.StagedFiles:N0}\n" +
                $"Files activated and size-verified: {result.ActivatedFiles:N0}\n" +
                $"Published bytes: {result.TotalBytes:N0}\n" +
                $"Parallel local validation workers: {FtpsWebsitePublisherService.LocalValidationWorkers}\n" +
                $"Host-compatible FTPS transfer sessions: {result.TransferWorkers}\n" +
                $"Backup and staging: {result.StagingSeconds:0.0}s\n" +
                $"Sequential activation: {result.ActivationSeconds:0.0}s\n" +
                "Activation order: catalog allowlist; /index.html last\n" +
                $"\n\nCompleted: {DateTime.Now:yyyy-MM-dd HH:mm:ss}";
            var publishMessage = result.StagedFiles == 0
                ? "Website publishing completed successfully. All remote artifacts already matched the governed deployment state; nothing was transferred."
                : "Website publishing completed successfully. Changed remote files are backed up in " + result.BackupFolder;
            MessageBox.Show(this, publishMessage, "Website Published", MessageBoxButton.OK, MessageBoxImage.Information);
        }
        catch (Exception ex)
        {
            WebsiteExportSummaryText.Text = "Website publish failed";
            WebsiteExportPreviewLog.Text = "FTPS website publish failed.\n\n" + ex.Message;
            MessageBox.Show(this, ex.Message, "Website Publish Failed", MessageBoxButton.OK, MessageBoxImage.Error);
        }
        finally
        {
            SetFtpsPublishingBusy(false, "Ready.");
        }
    }

