    private void SetFtpsPublishingBusy(bool busy, string status)
    {
        TestFtpsConnectionButton.IsEnabled = !busy;
        PublishWebsiteTestFtpsButton.IsEnabled = !busy;
        PublishWebsiteFtpsButton.IsEnabled = !busy;
        RestoreWebsiteBackupButton.IsEnabled = !busy;
        StatusText.Text = status;
    }

    private async Task<bool> GenerateWebsiteExportAsync(bool isProduction)
    {
        if (isProduction)
            if (IsAutomationActionBlocked("Production website generation")) return false;
        try
        {
            if (GetNativeWebsiteExportCandidateRows().Count == 0)
            {
                WebsiteExportPreviewLog.Text = "No material data is loaded. Load canonical MaterialID rows before generating a website export.";
                WebsiteExportSummaryText.Text = "No data loaded";
                return false;
            }

            var folder = WebsiteExportFolderBox.Text?.Trim();
            if (string.IsNullOrWhiteSpace(folder))
            {
                folder = GetDefaultWebsiteExportFolder();
                WebsiteExportFolderBox.Text = folder;
            }

            Directory.CreateDirectory(folder);

            var visibleRows = GetCanonicalVisibleMaterialRows();
            var allRows = GetCanonicalActiveMaterialRows();
            // STABILITY-004B: resolve the exact native row set once and use it for both
            // the generated DATA block and every exported count/quality statistic.
            var exportRows = GetNativeWebsitePipelineRows(visibleRows);
            var generatedAt = DateTime.Now;
            var outputFileName = isProduction ? "index.html" : "index-test.html";
            var htmlPath = System.IO.Path.Combine(folder, outputFileName);
            var manifestPath = System.IO.Path.Combine(folder, isProduction ? "export-manifest-production.txt" : "export-manifest.txt");
            var manufacturersFolder = System.IO.Path.Combine(folder, "manufacturers");
            var manufacturerRedirectPath = System.IO.Path.Combine(manufacturersFolder, isProduction ? "index.html" : "index-test.html");

            var templatePath = ResolveAutomaticMainWebsiteTemplatePath(folder);
            var templateSource = GetWebsiteTemplateSourceLabel(templatePath);
            var modeLabel = isProduction ? "Production" : "Preview";

            var validation = BuildMainExportValidationReport(templatePath, folder, htmlPath, visibleRows, allRows, exportRows, validatePublicReportPackage: false);
            if (validation.HasErrors)
            {
                throw new InvalidOperationException(validation.ToPlainText());
            }

            var backupPath = string.Empty;
            var manufacturerRedirectBackupPath = string.Empty;

            if (isProduction)
            {
                var confirm = MessageBox.Show(
                    this,
                    $"You are about to generate the production website and its legacy manufacturers redirect.\n\nTemplate:\n{templateSource}\n\nMain output:\n{htmlPath}\n\nRedirect output:\n{manufacturerRedirectPath}\n\nMissing or presentation-stale public reports will be rebuilt automatically. Existing production files will be backed up first.\n\nValidation:\n{validation.ToCompactText()}\n\nContinue?",
                    "Confirm Production Website Export",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Warning,
                    MessageBoxResult.No);

                if (confirm != MessageBoxResult.Yes)
                {
                    WebsiteExportSummaryText.Text = "Production export cancelled";
                    WebsiteExportPreviewLog.Text = "Production website export was cancelled. No files were changed.";
                    return false;
                }

            }

            if (BuildPublicEngineeringReportPackageButton is not null) BuildPublicEngineeringReportPackageButton.IsEnabled = false;
            var reportPackageEnsure = await EnsurePublicReportPackageAsync(status =>
            {
                WebsiteExportSummaryText.Text = $"{modeLabel}: {status}";
                StatusText.Text = status;
            });

            validation = BuildMainExportValidationReport(templatePath, folder, htmlPath, visibleRows, allRows, exportRows, validatePublicReportPackage: true);
            if (validation.HasErrors)
            {
                throw new InvalidOperationException(validation.ToPlainText());
            }

            if (isProduction)
            {
                backupPath = BackupExistingProductionHtml(htmlPath, generatedAt);
                Directory.CreateDirectory(manufacturersFolder);
                manufacturerRedirectBackupPath = BackupExistingProductionHtml(manufacturerRedirectPath, generatedAt);
            }

            var reportStage = _publicReportWebsiteIntegrationService.Stage(GetPublicReportPackageRoot(), folder, isProduction);
            SafeFileOperations.WriteAllTextAtomic(htmlPath, BuildWebsitePreviewHtml(visibleRows, allRows, generatedAt, templatePath, isProduction), Encoding.UTF8);
            Directory.CreateDirectory(manufacturersFolder);
            SafeFileOperations.WriteAllTextAtomic(manufacturerRedirectPath, BuildManufacturerRedirectHtml(isProduction), Encoding.UTF8);
            var documentationEngine = new DocumentationEngineService();
            var whitepaperPath = System.IO.Path.Combine(folder, DocumentationEngineService.WhitepaperFileName);
            SafeFileOperations.WriteAllBytesAtomic(whitepaperPath, documentationEngine.RenderPdf(documentationEngine.BuildDocument(generatedAt)));
            SafeFileOperations.WriteAllTextAtomic(manifestPath, BuildWebsiteExportManifest(exportRows, allRows.Count, htmlPath, manufacturerRedirectPath, generatedAt, templateSource, isProduction, backupPath, manufacturerRedirectBackupPath, reportStage), Encoding.UTF8);

            WebsiteProductionPublishPlan? publishPlan = null;
            var publishPlanPath = string.Empty;
            if (isProduction)
            {
                publishPlan = _websiteProductionPublishPlanService.Build(folder, generatedAt);
                if (!_websiteProductionPublishPlanService.Verify(publishPlan))
                    throw new InvalidOperationException("The catalog-driven Production publish plan did not pass readiness verification.");
                publishPlanPath = System.IO.Path.Combine(folder, WebsiteProductionPublishPlanService.FileName);
                SafeFileOperations.WriteAllTextAtomic(publishPlanPath, _websiteProductionPublishPlanService.Serialize(publishPlan), Encoding.UTF8);
            }

            var summary = BuildWebsiteExportSummary(exportRows, allRows.Count, includeManufacturers: false);
            var logBody = BuildDetailedExportLog($"Website {modeLabel.ToLowerInvariant()}", generatedAt, validation, summary, htmlPath, manifestPath, templateSource, backupPath) +
                          $"\nPublic report package prerequisite: {reportPackageEnsure.PublicMaterials} MaterialIDs, {reportPackageEnsure.CatalogEntries} catalog entries, source data changed {(reportPackageEnsure.SourceDataChanged ? "yes" : "no")}, rebuilt types {reportPackageEnsure.RebuiltTypesLabel}, ensure time {reportPackageEnsure.BuildSeconds:0.0}s.\n" +
                          (publishPlan is null ? string.Empty : $"Production publish plan: {publishPlan.Files.Count} exact allowlisted files, {publishPlan.TotalBytes:N0} bytes, root index activated last.\n");
            var logPath = WriteWebsiteExportLog(folder, isProduction ? "website-production" : "website-preview", generatedAt, logBody);

            WebsiteExportSummaryText.Text = $"{modeLabel}: {exportRows.Count} materials exported";
            WebsiteExportPreviewLog.Text =
                $"Website {modeLabel.ToLowerInvariant()} export generated successfully.\n\n" +
                validation.ToPlainText() + "\n\n" +
                summary + "\n" +
                $"Created files:\n- {htmlPath}\n- {manufacturerRedirectPath}\n- {reportStage.PortalPath}\n- {whitepaperPath}\n- {manifestPath}\n- {logPath}\n" +
                (publishPlan is null ? string.Empty : $"- {publishPlanPath}\nProduction publish readiness: {publishPlan.Files.Count} exact catalog-derived files, {publishPlan.TotalBytes:N0} bytes, SHA-256 recorded; /index.html last.\n") +
                $"Public report package prerequisite: {reportPackageEnsure.PublicMaterials} MaterialIDs, {reportPackageEnsure.CatalogEntries} catalog entries; source data changed: {(reportPackageEnsure.SourceDataChanged ? "yes" : "no")}; rebuilt types: {reportPackageEnsure.RebuiltTypesLabel}.\n" +
                $"Public report website stage: {reportStage.PublicMaterials} MaterialIDs, {reportStage.CatalogEntries} catalog entries, {reportStage.CopiedFiles} files copied or refreshed.\n" +
                (string.IsNullOrWhiteSpace(backupPath) ? string.Empty : $"\nBackup created:\n- {backupPath}\n") +
                (string.IsNullOrWhiteSpace(manufacturerRedirectBackupPath) ? string.Empty : $"\nManufacturers redirect backup created:\n- {manufacturerRedirectBackupPath}\n") +
                $"\nGenerated: {generatedAt:yyyy-MM-dd HH:mm:ss}\n\n" +
                (isProduction
                    ? "Safety note: Production export requires confirmation, validation, detailed logging and local backup. FTPS publishing remains a separate guarded action."
                    : "Safety note: Preview created index-test.html and manufacturers\\index-test.html only. It did not overwrite either production file.");

            StatusText.Text = $"Website export complete — {System.IO.Path.GetFileName(htmlPath)}";
            return true;
        }
        catch (Exception ex)
        {
            WebsiteExportSummaryText.Text = isProduction ? "Production failed" : "Preview failed";
            WebsiteExportPreviewLog.Text = $"Website export failed.\n\n{ex.Message}";
            MessageBox.Show(this, ex.Message, "Website Export Failed", MessageBoxButton.OK, MessageBoxImage.Error);
            return false;
        }
        finally
        {
            if (BuildPublicEngineeringReportPackageButton is not null) BuildPublicEngineeringReportPackageButton.IsEnabled = true;
        }
    }

    private sealed class WebsiteExportValidationReport
    {
        public List<string> Checks { get; } = new();
        public List<string> Warnings { get; } = new();
        public List<string> Errors { get; } = new();
        public bool HasErrors => Errors.Count > 0;

        public void Check(bool condition, string success, string failure)
        {
            if (condition) Checks.Add("✓ " + success);
            else Errors.Add("✗ " + failure);
        }

        public void WarnIf(bool condition, string warning)
        {
            if (condition) Warnings.Add("⚠ " + warning);
        }

        public string ToPlainText()
        {
            var sb = new StringBuilder();
            sb.AppendLine("Export Validation");
            sb.AppendLine("-----------------");
            foreach (var check in Checks) sb.AppendLine(check);
            foreach (var warning in Warnings) sb.AppendLine(warning);
            foreach (var error in Errors) sb.AppendLine(error);
            return sb.ToString().TrimEnd();
        }

        public string ToCompactText()
        {
            var parts = Checks.Concat(Warnings).Concat(Errors).ToList();
            return parts.Count == 0 ? "No validation checks were reported." : string.Join("\n", parts);
        }
    }

    private WebsiteExportValidationReport BuildMainExportValidationReport(string? templatePath, string outputFolder, string htmlPath, IReadOnlyList<DataRow> visibleRows, IReadOnlyList<DataRow> allRows, IReadOnlyList<NativeMaterialRow> exportRows, bool validatePublicReportPackage = true)
    {
        var report = new WebsiteExportValidationReport();
        report.Check(!string.IsNullOrWhiteSpace(outputFolder), "Output folder selected", "Output folder is missing");
        report.Check(Directory.Exists(outputFolder), $"Output folder exists: {outputFolder}", $"Output folder does not exist: {outputFolder}");
        report.Check(CanWriteToFolder(outputFolder), "Output folder is writable", $"Output folder is not writable: {outputFolder}");
        report.Check(exportRows.Count > 0, $"Materials selected for DATA export: {exportRows.Count}", "No materials are available for export");
        report.Check(allRows.Count > 0 || exportRows.Count > 0,
            $"Source rows loaded: legacy projection {allRows.Count}, canonical export set {exportRows.Count}",
            "No legacy projection rows or canonical MaterialID rows are loaded");

        var summaryVerification = EvaluateNativeMaterialSummaryVerification();
        report.Check(summaryVerification.Available && summaryVerification.Passed,
            $"Verified Material Summary pipeline available: {summaryVerification.SummariesBuilt} summaries",
            "Verified Material Summary pipeline is not available or did not pass. Run Verification Center before website export.");
        report.Check(exportRows.Count > 0,
            $"Native website export candidates selected: {exportRows.Count}",
            "No active native MaterialID rows are available for website export");

        try
        {
            var template = LoadWebsiteExportTemplate(templatePath);
            var templateLabel = string.IsNullOrWhiteSpace(templatePath) ? "Bundled website template" : templatePath;
            report.Check(true, $"Template file loaded: {templateLabel}", "Template file could not be loaded");
            report.Check(_websiteHtmlRendererService.HasDataBlock(template), "Main website DATA block found", "Could not locate const DATA=... block in the main website template");
        }
        catch (Exception ex)
        {
            report.Errors.Add("✗ Template validation failed: " + ex.Message);
        }

        var previewRedirectHtml = BuildManufacturerRedirectHtml(isProduction: false);
        var productionRedirectHtml = BuildManufacturerRedirectHtml(isProduction: true);
        const string canonicalTarget = "https://iskort.is/3dp/index.html#manufacturers";
        report.Check(
            HasManufacturerRedirectTarget(previewRedirectHtml, "../index-test.html#manufacturers", canonicalTarget) &&
            HasManufacturerRedirectTarget(productionRedirectHtml, "../index.html#manufacturers", canonicalTarget),
            "Preview and Production manufacturers redirects target their matching main website files",
            "Legacy manufacturers redirect is incomplete or targets the wrong location");

        if (validatePublicReportPackage)
        {
            var reportPackage = _publicReportWebsiteIntegrationService.ValidatePackage(GetPublicReportPackageRoot());
            report.Check(reportPackage.Passed,
                $"Public report package ready for website staging: {reportPackage.PublicMaterials} MaterialIDs and {reportPackage.Reports.Count} catalog entries",
                reportPackage.Detail);
        }
        else
        {
            report.Checks.Add("✓ Public report package will be validated and rebuilt automatically when required");
        }

        report.WarnIf(File.Exists(htmlPath), $"Output file already exists and will be overwritten after backup/confirmation when using production: {htmlPath}");
        AppendDataQualityWarnings(report, exportRows);
        return report;
    }

    private static bool CanWriteToFolder(string folder)
    {
        try
        {
            if (string.IsNullOrWhiteSpace(folder)) return false;
            Directory.CreateDirectory(folder);
            var probe = System.IO.Path.Combine(folder, ".filamentdb_write_test_" + Guid.NewGuid().ToString("N") + ".tmp");
            File.WriteAllText(probe, "test", Encoding.UTF8);
            File.Delete(probe);
            return true;
        }
        catch
        {
            return false;
        }
    }

    private static void AppendDataQualityWarnings(WebsiteExportValidationReport report, IReadOnlyList<DataRow> rows)
    {
        var missingManufacturer = rows.Count(row => string.IsNullOrWhiteSpace(GetCell(row, "Manufacturer", "Brand")));
        var missingCategory = rows.Count(row => string.IsNullOrWhiteSpace(GetCell(row, "Category", "Material Category")));
        var missingBaseMaterial = rows.Count(row => string.IsNullOrWhiteSpace(GetCell(row, "Base Material", "Material Type", "Type")));
        var missingProductUrl = rows.Count(row => string.IsNullOrWhiteSpace(GetCell(row, "Product Page", "Product URL", "ProductUrl", "Manufacturer Website", "Website")));
        var missingYoutubeUrl = rows.Count(row => string.IsNullOrWhiteSpace(GetCell(row, "YouTube Review URL", "YouTube URL")));

        report.WarnIf(missingManufacturer > 0, $"Materials missing manufacturer: {missingManufacturer}");
        report.WarnIf(missingCategory > 0, $"Materials missing category: {missingCategory}");
        report.WarnIf(missingBaseMaterial > 0, $"Materials missing base material/type: {missingBaseMaterial}");
        report.WarnIf(missingProductUrl > 0, $"Materials missing product URL: {missingProductUrl}");
        report.WarnIf(missingYoutubeUrl > 0, $"Materials without YouTube review: {missingYoutubeUrl}");
    }

    private static void AppendDataQualityWarnings(WebsiteExportValidationReport report, IReadOnlyList<NativeMaterialRow> rows)
    {
        report.WarnIf(rows.Count(row => string.IsNullOrWhiteSpace(row.Manufacturer)) > 0,
            $"Materials missing manufacturer: {rows.Count(row => string.IsNullOrWhiteSpace(row.Manufacturer))}");
        report.WarnIf(rows.Count(row => string.IsNullOrWhiteSpace(row.MaterialCategory)) > 0,
            $"Materials missing category: {rows.Count(row => string.IsNullOrWhiteSpace(row.MaterialCategory))}");
        report.WarnIf(rows.Count(row => string.IsNullOrWhiteSpace(row.BaseMaterial)) > 0,
            $"Materials missing base material/type: {rows.Count(row => string.IsNullOrWhiteSpace(row.BaseMaterial))}");
        report.WarnIf(rows.Count(row => string.IsNullOrWhiteSpace(row.ManufacturerWebsite)) > 0,
            $"Materials missing product URL: {rows.Count(row => string.IsNullOrWhiteSpace(row.ManufacturerWebsite))}");
        report.WarnIf(rows.Count(row => string.IsNullOrWhiteSpace(row.YouTubeReviewUrl)) > 0,
            $"Materials without YouTube review: {rows.Count(row => string.IsNullOrWhiteSpace(row.YouTubeReviewUrl))}");
    }

    private string BuildWebsiteExportSummary(IReadOnlyList<NativeMaterialRow> exportRows, int legacyProjectionCount, bool includeManufacturers)
    {
        var activeRows = exportRows.Where(row => !row.IsArchived).ToList();
        var sb = new StringBuilder();
        sb.AppendLine("Export Summary");
        sb.AppendLine("--------------");
        sb.AppendLine($"Materials exported to DATA block: {activeRows.Count}");
        sb.AppendLine($"Legacy projection rows (informational): {legacyProjectionCount}");
        sb.AppendLine($"Manufacturers: {activeRows.Select(row => row.Manufacturer?.Trim()).Where(value => !string.IsNullOrWhiteSpace(value)).Distinct(StringComparer.OrdinalIgnoreCase).Count()}");
        sb.AppendLine($"Base materials: {activeRows.Select(row => row.BaseMaterial?.Trim()).Where(value => !string.IsNullOrWhiteSpace(value)).Distinct(StringComparer.OrdinalIgnoreCase).Count()}");
        sb.AppendLine($"Product lines: {activeRows.Select(row => row.ProductLine?.Trim()).Where(value => !string.IsNullOrWhiteSpace(value)).Distinct(StringComparer.OrdinalIgnoreCase).Count()}");
        sb.AppendLine($"Videos linked: {activeRows.Count(row => !string.IsNullOrWhiteSpace(row.YouTubeReviewUrl))}");
        sb.AppendLine($"Product URLs: {activeRows.Count(row => !string.IsNullOrWhiteSpace(row.ManufacturerWebsite))}");
        if (includeManufacturers) sb.AppendLine("Manufacturers page export: enabled");
        sb.AppendLine();
        sb.Append(BuildDataQualitySummary(activeRows));
        return sb.ToString().TrimEnd();
    }

    private static string BuildDataQualitySummary(IReadOnlyList<NativeMaterialRow> rows)
    {
        var sb = new StringBuilder();
        sb.AppendLine("Data Quality Warnings");
        sb.AppendLine("---------------------");
        AppendWarningLine(sb, "Missing manufacturer", rows.Count(row => string.IsNullOrWhiteSpace(row.Manufacturer)));
        AppendWarningLine(sb, "Missing category", rows.Count(row => string.IsNullOrWhiteSpace(row.MaterialCategory)));
        AppendWarningLine(sb, "Missing base material/type", rows.Count(row => string.IsNullOrWhiteSpace(row.BaseMaterial)));
        AppendWarningLine(sb, "Missing product URL", rows.Count(row => string.IsNullOrWhiteSpace(row.ManufacturerWebsite)));
        AppendWarningLine(sb, "Missing YouTube URL", rows.Count(row => string.IsNullOrWhiteSpace(row.YouTubeReviewUrl)));
        return sb.ToString().TrimEnd();
    }

    private string BuildWebsiteExportSummary(IReadOnlyList<DataRow> visibleRows, IReadOnlyList<DataRow> allRows, bool includeManufacturers)
    {
        var sb = new StringBuilder();
        sb.AppendLine("Export Summary");
        sb.AppendLine("--------------");
        sb.AppendLine($"Visible materials exported: {visibleRows.Count}");
        sb.AppendLine($"Legacy projection materials: {allRows.Count}");
        sb.AppendLine($"Manufacturers: {CountManufacturers(allRows)}");
        sb.AppendLine($"Base materials: {CountDistinctValues(allRows, "Base Material", "Material Type", "Type")}");
        sb.AppendLine($"Product lines: {CountDistinctValues(allRows, "Product Line", "ProductLine")}");
        sb.AppendLine($"Videos linked: {CountRowsWithAnyValue(allRows, "YouTube Review URL", "YouTube URL")}");
        sb.AppendLine($"Product URLs: {CountRowsWithAnyValue(allRows, "Product Page", "Product URL", "ProductUrl", "Manufacturer Website", "Website")}");
        if (includeManufacturers) sb.AppendLine("Manufacturers page export: enabled");
        sb.AppendLine();
        sb.Append(BuildDataQualitySummary(allRows));
        return sb.ToString().TrimEnd();
    }

    private static string BuildDataQualitySummary(IReadOnlyList<DataRow> rows)
    {
        var sb = new StringBuilder();
        sb.AppendLine("Data Quality Warnings");
        sb.AppendLine("---------------------");
        AppendWarningLine(sb, "Missing manufacturer", rows.Count(row => string.IsNullOrWhiteSpace(GetCell(row, "Manufacturer", "Brand"))));
        AppendWarningLine(sb, "Missing category", rows.Count(row => string.IsNullOrWhiteSpace(GetCell(row, "Category", "Material Category"))));
        AppendWarningLine(sb, "Missing base material/type", rows.Count(row => string.IsNullOrWhiteSpace(GetCell(row, "Base Material", "Material Type", "Type"))));
        AppendWarningLine(sb, "Missing product URL", rows.Count(row => string.IsNullOrWhiteSpace(GetCell(row, "Product Page", "Product URL", "ProductUrl", "Manufacturer Website", "Website"))));
        AppendWarningLine(sb, "Missing YouTube URL", rows.Count(row => string.IsNullOrWhiteSpace(GetCell(row, "YouTube Review URL", "YouTube URL"))));
        return sb.ToString().TrimEnd();
    }

    private static void AppendWarningLine(StringBuilder sb, string label, int count)
    {
        sb.AppendLine(count == 0 ? $"✓ {label}: 0" : $"⚠ {label}: {count}");
    }

    private static int CountDistinctValues(IReadOnlyList<DataRow> rows, params string[] columnNames)
    {
        return rows
            .Select(row => GetCell(row, columnNames)?.Trim())
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Count();
    }

    private static int CountRowsWithAnyValue(IReadOnlyList<DataRow> rows, params string[] columnNames)
    {
        return rows.Count(row => !string.IsNullOrWhiteSpace(GetCell(row, columnNames)));
    }

    private string BuildDetailedExportLog(string title, DateTime generatedAt, WebsiteExportValidationReport validation, string summary, string htmlPath, string manifestPath, string templateSource, string backupPath)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"{title} export log");
        sb.AppendLine("====================");
        sb.AppendLine($"Generated: {generatedAt:yyyy-MM-dd HH:mm:ss}");
        sb.AppendLine($"Template source: {templateSource}");
        sb.AppendLine($"Output HTML: {htmlPath}");
        sb.AppendLine($"Manifest: {manifestPath}");
        sb.AppendLine(string.IsNullOrWhiteSpace(backupPath) ? "Backup: not required" : $"Backup: {backupPath}");
        sb.AppendLine();
        sb.AppendLine(validation.ToPlainText());
        sb.AppendLine();
        sb.AppendLine(summary);
        sb.AppendLine();
        sb.AppendLine("Result: Success");
        return sb.ToString();
    }

    private string WriteWebsiteExportLog(string outputFolder, string prefix, DateTime generatedAt, string logBody)
    {
        var logFolder = System.IO.Path.Combine(outputFolder, "ExportLogs");
        Directory.CreateDirectory(logFolder);
        var safePrefix = Regex.Replace(prefix, @"[^A-Za-z0-9_-]+", "-").Trim('-');
        if (string.IsNullOrWhiteSpace(safePrefix)) safePrefix = "website-export";
        var logPath = System.IO.Path.Combine(logFolder, $"{generatedAt:yyyy-MM-dd_HHmmss}_{safePrefix}.log");
        SafeFileOperations.WriteAllTextAtomic(logPath, logBody, Encoding.UTF8);
        return logPath;
    }

    private string? ResolveAutomaticMainWebsiteTemplatePath(string websiteRootFolder)
    {
        // Main website templates are database-managed from v40.10.0 onward.
        return null;
    }

    private string BackupExistingProductionHtml(string htmlPath, DateTime generatedAt)
    {
        if (!File.Exists(htmlPath)) return string.Empty;

        var folder = System.IO.Path.GetDirectoryName(htmlPath);
        if (string.IsNullOrWhiteSpace(folder)) return string.Empty;

        var backupFolder = System.IO.Path.Combine(folder, "Backups");
        Directory.CreateDirectory(backupFolder);

        var backupName = $"index_{generatedAt:yyyy-MM-dd_HHmmss}.html";
        var backupPath = System.IO.Path.Combine(backupFolder, backupName);
        File.Copy(htmlPath, backupPath, overwrite: false);
        return backupPath;
    }

    private void OpenWebsiteExportFolder_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            var folder = WebsiteExportFolderBox.Text?.Trim();
            if (string.IsNullOrWhiteSpace(folder)) folder = GetDefaultWebsiteExportFolder();

            Directory.CreateDirectory(folder);
            UrlLauncher.Open(folder);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Could not open website export folder", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

    private string GetDefaultWebsiteExportFolder()
    {
        var currentExportFolder = WebsiteExportFolderBox?.Text?.Trim();
        if (!string.IsNullOrWhiteSpace(currentExportFolder) && Directory.Exists(currentExportFolder)) return currentExportFolder;

        var databaseFolder = System.IO.Path.GetDirectoryName(_database.DatabasePath);
        if (!string.IsNullOrWhiteSpace(databaseFolder)) return databaseFolder;

        return Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);
    }

    private void RestoreWebsiteExportFolderPreference()
    {
        var savedFolder = _workflowPreferencesService.GetWebsiteExportFolder();
        if (string.IsNullOrWhiteSpace(savedFolder) || !Directory.Exists(savedFolder)) return;

        WebsiteExportFolderBox.Text = savedFolder;
        WebsiteExportPreviewLog.Text = $"Restored website root folder from your previous session:\n{savedFolder}";
        WebsiteExportSummaryText.Text = "Saved folder restored";
    }

    private void SaveWebsiteExportFolderPreference(string folder)
    {
        if (string.IsNullOrWhiteSpace(folder) || !Directory.Exists(folder)) return;
        _workflowPreferencesService.SetWebsiteExportFolder(folder);
        _workflowPreferencesService.Save();
    }

    private string BuildWebsitePreviewHtml(IReadOnlyList<DataRow> visibleRows, IReadOnlyList<DataRow> allRows, DateTime generatedAt, string? templatePath, bool isProduction)
    {
        var template = LoadWebsiteExportTemplate(templatePath);
        var dataJson = BuildWebsiteTemplateDataJson(visibleRows);
        var rendered = _websiteHtmlRendererService.RenderMainWebsite(template, dataJson, generatedAt, isProduction, BuildInfo.ShortLabel + " - " + BuildInfo.ReleaseTitle);

        // The Manufacturers portal consumes the same canonical active material rows
        // supplied to the website DATA pipeline for this render.
        var canonical = ApplyWebsiteTerminologyCleanup(ApplyConsistencyCalibrationToWebsite(ApplyPublicReportLinksToWebsite(ApplyNativeWebsitePortalNavigation(InjectExperimentalWebsiteSection(rendered), allRows))));
        return _publicReportWebsiteIntegrationService.ApplyPortalNavigation(canonical, isProduction);
    }

    private string GetPublicReportPackageRoot()
    {
        var output = string.IsNullOrWhiteSpace(ReportOutputFolderBox?.Text) ? GetDefaultReportOutputFolder() : ReportOutputFolderBox.Text.Trim();
        return System.IO.Path.Combine(output, PublicReportPublishingService.PreviewRootFolderName);
    }

    private static string ApplyPublicReportLinksToWebsite(string html)
    {
        const string marker = "<!-- 3DP-PUBLIC-REPORT-LINKS-v42.10 -->";
        if (html.Contains(marker, StringComparison.Ordinal)) return html;

        html = html.Replace(
            "<section class=\"card\" id=\"videoReviewCard\"><h2>Links for visible materials</h2>",
            marker + "\n<section class=\"card\" id=\"videoReviewCard\"><h2>Links and public reports for visible materials</h2>",
            StringComparison.Ordinal);
        html = html.Replace(
            "while Product page buttons open the manufacturer or reseller page for the filament.",
            "while Product page buttons open the manufacturer or reseller page for the filament. Public report buttons appear only for MaterialIDs explicitly selected for public reporting in the Engineering Platform.",
            StringComparison.Ordinal);
        html = html.Replace(
            "youtubeUrl:r.youtubeUrl,productUrl:r.productUrl,materialId:r.materialId",
            "youtubeUrl:r.youtubeUrl,productUrl:r.productUrl,publicReportUrl:r.publicReportUrl,publicReportPdfUrl:r.publicReportPdfUrl,publicRecommendationUrl:r.publicRecommendationUrl,publicTestSessionUrl:r.publicTestSessionUrl,publicManufacturerReportUrl:r.publicManufacturerReportUrl,publicComparisonReportUrl:r.publicComparisonReportUrl,materialId:r.materialId",
            StringComparison.Ordinal);
        html = html.Replace(
            "'youtubeUrl','productUrl','materialId'",
            "'youtubeUrl','productUrl','publicReportUrl','publicReportPdfUrl','publicRecommendationUrl','publicTestSessionUrl','publicManufacturerReportUrl','publicComparisonReportUrl','materialId'",
            StringComparison.Ordinal);
        html = html.Replace(
            "(r.youtubeUrl||r.productUrl)",
            "(r.youtubeUrl||r.productUrl||r.publicReportUrl)",
            StringComparison.Ordinal);
        html = html.Replace(
            "const reviewCount=rows.filter(r=>r.youtubeUrl).length,productCount=rows.filter(r=>r.productUrl).length;",
            "const reviewCount=rows.filter(r=>r.youtubeUrl).length,productCount=rows.filter(r=>r.productUrl).length,reportCount=rows.filter(r=>r.publicReportUrl).length;",
            StringComparison.Ordinal);
        html = html.Replace(
            "countEl.textContent=rows.length?`${rows.length} visible material${rows.length===1?' has':'s have'} links · ${reviewCount} review link${reviewCount===1?'':'s'} · ${productCount} product page link${productCount===1?'':'s'}`:'No review or product links for the currently visible materials';",
            "countEl.textContent=rows.length?`${rows.length} visible material${rows.length===1?' has':'s have'} links · ${reviewCount} review link${reviewCount===1?'':'s'} · ${productCount} product page link${productCount===1?'':'s'} · ${reportCount} public report${reportCount===1?'':'s'}`:'No review, product or public report links for the currently visible materials';",
            StringComparison.Ordinal);
        html = html.Replace(
            "const product=r.productUrl?`<a class=\"product-link\" href=\"${esc(r.productUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\">Product page</a>`:'';",
            "const product=r.productUrl?`<a class=\"product-link\" href=\"${esc(r.productUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\">Product page</a>`:'';const report=r.publicReportUrl?`<a class=\"product-link\" href=\"${esc(r.publicReportUrl)}\">Engineering report</a><a class=\"product-link\" href=\"${esc(r.publicReportPdfUrl)}\">Report PDF</a><a class=\"product-link\" href=\"${esc(r.publicRecommendationUrl)}\">Printing guidance</a><a class=\"product-link\" href=\"${esc(r.publicTestSessionUrl)}\">Test evidence</a>${r.publicComparisonReportUrl?`<a class=\"product-link\" href=\"${esc(r.publicComparisonReportUrl)}\">Family comparison</a>`:''}${r.publicManufacturerReportUrl?`<a class=\"product-link\" href=\"${esc(r.publicManufacturerReportUrl)}\">Manufacturer report</a>`:''}`:'';",
            StringComparison.Ordinal);
        html = html.Replace("${review}${product}</div>", "${review}${product}${report}</div>", StringComparison.Ordinal);
        return html;
    }

    private static string ApplyConsistencyCalibrationToWebsite(string html)
    {
        const string marker = "<!-- 3DP-CONSISTENCY-CALIBRATION-v41.6 -->";
        if (html.Contains(marker, StringComparison.Ordinal)) return html;

        const string labelFunction = "function consistencyRatingLabel(score){if(score==null||!isFinite(score))return 'Unavailable';if(score>=90)return 'Excellent repeatability';if(score>=85)return 'Very good repeatability';if(score>=80)return 'Good repeatability';if(score>=70)return 'Moderate repeatability';if(score>=60)return 'Low repeatability';return 'Very low repeatability';}\n";
        html = html.Replace(
            "function consistencySourceRows(){",
            marker + "\n" + labelFunction + "function consistencySourceRows(){",
            StringComparison.Ordinal);
        html = html.Replace(
            "Consistency score: ${fmt(val)} / 100${marketing}",
            "Consistency score: ${fmt(val)} / 100<br>Internal rating: ${consistencyRatingLabel(val)}${marketing}",
            StringComparison.Ordinal);
        html = html.Replace(
            "A high score means the measured specimens behaved more repeatably, not necessarily that the filament is strongest.",
            "A high score means the measured specimens behaved more repeatably, not necessarily that the filament is strongest. Internal rating bands: 90 excellent, 85 very good, 80 good, 70 moderate, 60 low, and below 60 very low repeatability.",
            StringComparison.Ordinal);
        return html;
    }

    private string LoadWebsiteExportTemplate(string? templatePath)
    {
        // v40.10.0: SQLite is the canonical source of truth for the main website template.
        return _database.GetActiveWebsiteTemplate().HtmlContent;
    }

    private static int FindMatchingJsonObjectEnd(string text, int objectStart)
    {
        var depth = 0;
        var inString = false;
        var escape = false;

        for (var i = objectStart; i < text.Length; i++)
        {
            var ch = text[i];

            if (inString)
            {
                if (escape)
                {
                    escape = false;
                    continue;
                }

                if (ch == '\\')
                {
                    escape = true;
                    continue;
                }

                if (ch == '"')
                {
                    inString = false;
                }

                continue;
            }

            if (ch == '"')
            {
                inString = true;
                continue;
            }

            if (ch == '{')
            {
                depth++;
                continue;
            }

            if (ch == '}')
            {
                depth--;
                if (depth == 0)
                {
                    return i;
                }
            }
        }

        return -1;
    }


    private string BuildWebsiteTemplateDataJson(IReadOnlyList<DataRow> rows)
    {
        var candidateRows = GetNativeWebsitePipelineRows(rows);
        var summaries = BuildVerifiedMaterialSummaryMap(candidateRows);
        var chartInputs = new List<WebsiteChartMaterialInput>();

        foreach (var material in candidateRows)
        {
            var materialId = material.MaterialID?.Trim() ?? string.Empty;
            if (string.IsNullOrWhiteSpace(materialId)) continue;
            if (!summaries.TryGetValue(materialId, out var summary)) continue;

            chartInputs.Add(new WebsiteChartMaterialInput(BuildWebsiteTemplateCommonFields(material), summary));
        }

        return _websiteChartGeneratorService.BuildDataJson(chartInputs);
    }


