    private string ApplyNativeWebsitePortalNavigation(string html, IReadOnlyList<DataRow>? manufacturerRows = null)
    {
        const string markerStart = "<!-- 3DP-NATIVE-PORTAL-START -->";
        const string markerEnd = "<!-- 3DP-NATIVE-PORTAL-END -->";

        // Export is generated from a clean SQLite template, but keeping this transform
        // idempotent protects verification probes and future renderer reuse.
        if (html.Contains(markerStart, StringComparison.Ordinal)) return html;

        const string experimentalStart = "<!-- 3DP-EXPERIMENTAL-WEBSITE-START -->";
        const string experimentalEnd = "<!-- 3DP-EXPERIMENTAL-WEBSITE-END -->";
        var experimentalBlock = experimentalStart + Environment.NewLine + experimentalEnd;
        var experimentalIndex = html.IndexOf(experimentalStart, StringComparison.Ordinal);
        if (experimentalIndex >= 0)
        {
            var experimentalEndIndex = html.IndexOf(experimentalEnd, experimentalIndex, StringComparison.Ordinal);
            if (experimentalEndIndex >= 0)
            {
                var length = experimentalEndIndex + experimentalEnd.Length - experimentalIndex;
                experimentalBlock = html.Substring(experimentalIndex, length);
                html = html.Remove(experimentalIndex, length);
            }
        }

        var mainOpen = Regex.Match(html, @"<main\b[^>]*>", RegexOptions.IgnoreCase);
        if (!mainOpen.Success) return html;
        var mainClose = html.IndexOf("</main>", mainOpen.Index + mainOpen.Length, StringComparison.OrdinalIgnoreCase);
        if (mainClose < 0) return html;

        var databaseContent = html.Substring(mainOpen.Index + mainOpen.Length, mainClose - (mainOpen.Index + mainOpen.Length));
        const string conciseMultiSelectHint = "Click to select/deselect — multiple selections allowed.";
        foreach (var verboseHint in new[]
        {
            "Base material only. None selected = all. Options stay independent.",
            "Examples: Matte, Silk, Pro, Wood. None selected = all. Options stay independent.",
            "Examples: CF, GF, Wood. None selected = all. Options stay independent.",
            "Ctrl/Cmd-click to select multiple. None selected = all. Options stay independent."
        })
        {
            databaseContent = databaseContent.Replace(verboseHint, conciseMultiSelectHint, StringComparison.Ordinal);
        }
        databaseContent = Regex.Replace(
            databaseContent,
            @"(<select\b[^>]*\bid=[""'](?:variant|reinforcement|color|manufacturer|productLine)[""'][^>]*>.*?</select>)<span class=[""']filter-hint[""']>Click to select/deselect — multiple selections allowed\.</span>",
            "$1",
            RegexOptions.IgnoreCase | RegexOptions.Singleline);
        databaseContent = databaseContent
            .Replace("<span class=\"filter-hint\">Optional public MSRP price-per-kg filter.</span>", string.Empty, StringComparison.Ordinal)
            .Replace("<span class=\"filter-hint\">Pricing is shown as manually researched reference data.</span>", string.Empty, StringComparison.Ordinal);
        databaseContent = Regex.Replace(
            databaseContent,
            @"<div class=[""']search-reset[""']><div>\s*<label for=[""']sortMode[""']>Sort tensile / impact by</label>\s*(?<sortSelect><select id=[""']sortMode[""']>.*?</select>)\s*<label for=[""']search[""'][^>]*>Search</label><input id=[""']search[""'][^>]*?/?>\s*</div><div><button id=[""']reset[""']>Reset filters</button></div></div>",
            @"<div class=""search-reset compact-filter-row""><div class=""search-filter""><button id=""reset"">Reset filters</button><label for=""search"">Search</label><input id=""search"" placeholder=""Search label...""/></div><div class=""sort-filter""><label for=""sortMode"">Sort tensile / impact by</label>${sortSelect}</div></div>",
            RegexOptions.IgnoreCase | RegexOptions.Singleline);
        var pricingContent = new StringBuilder();
        foreach (var pricingSectionId in new[] { "pricingExplorerCard", "pricePerformanceCard", "valueRankingsCard" })
        {
            var sectionPattern = $@"<section\b(?=[^>]*\bid=[""']{Regex.Escape(pricingSectionId)}[""'])[^>]*>.*?</section>";
            var sectionMatch = Regex.Match(databaseContent, sectionPattern, RegexOptions.IgnoreCase | RegexOptions.Singleline);
            if (!sectionMatch.Success) continue;
            pricingContent.AppendLine(sectionMatch.Value);
            databaseContent = databaseContent.Remove(sectionMatch.Index, sectionMatch.Length);
        }
        // The full governed methodology now has its own portal page. Remove the old
        // template-era summary from Database without changing the approved SQLite template.
        databaseContent = Regex.Replace(
            databaseContent,
            @"<section\b(?=[^>]*\bclass=[""'][^""']*\bmethodology-box\b[^""']*[""'])[^>]*>.*?</section>",
            string.Empty,
            RegexOptions.IgnoreCase | RegexOptions.Singleline);
        var portalBody = new StringBuilder();
        portalBody.AppendLine();
        portalBody.AppendLine(markerStart);
        portalBody.AppendLine("<nav class=\"portal-navigation\" aria-label=\"3DPIceland Labs sections\">");
        portalBody.AppendLine("  <div class=\"portal-navigation-inner\">");
        portalBody.AppendLine("    <button type=\"button\" class=\"portal-tab is-active\" data-portal-target=\"database\" aria-controls=\"portalPageDatabase\" aria-selected=\"true\">Filament Database</button>");
        portalBody.AppendLine("    <button type=\"button\" class=\"portal-tab\" data-portal-target=\"pricing\" aria-controls=\"portalPagePricing\" aria-selected=\"false\">Pricing &amp; Value</button>");
        portalBody.AppendLine("    <button type=\"button\" class=\"portal-tab\" data-portal-target=\"experimental\" aria-controls=\"portalPageExperimental\" aria-selected=\"false\">Experimental Lab</button>");
        portalBody.AppendLine("    <button type=\"button\" class=\"portal-tab\" data-portal-target=\"manufacturers\" aria-controls=\"portalPageManufacturers\" aria-selected=\"false\">Manufacturers</button>");
        portalBody.AppendLine("    <button type=\"button\" class=\"portal-tab\" data-portal-target=\"methodology\" aria-controls=\"portalPageMethodology\" aria-selected=\"false\">Methodology</button>");
        portalBody.AppendLine("  </div>");
        portalBody.AppendLine("</nav>");
        portalBody.AppendLine("<section id=\"portalPageDatabase\" class=\"portal-page is-active\" data-portal-page=\"database\">");
        portalBody.AppendLine(databaseContent.Trim());
        portalBody.AppendLine("</section>");
        portalBody.AppendLine("<section id=\"portalPagePricing\" class=\"portal-page\" data-portal-page=\"pricing\" hidden>");
        portalBody.AppendLine("  <div class=\"portal-page-heading pricing-portal-heading\"><p class=\"portal-eyebrow\">Pricing intelligence</p><h1>Pricing &amp; Value</h1><p>Explore public MSRP, measured performance per dollar and comparable value rankings. Filters are synchronized with the Filament Database so both tabs always use the same visible material set.</p></div>");
        portalBody.AppendLine(BuildPricingPortalFilterHtml());
        portalBody.AppendLine("  <div class=\"pricing-portal-content\">");
        portalBody.AppendLine(pricingContent.ToString());
        portalBody.AppendLine("  </div>");
        portalBody.AppendLine("</section>");
        portalBody.AppendLine("<section id=\"portalPageExperimental\" class=\"portal-page\" data-portal-page=\"experimental\" hidden>");
        portalBody.AppendLine("  <div class=\"portal-page-heading\"><p class=\"portal-eyebrow\">3DPIceland Labs</p><h1>Experimental Lab</h1><p>Published parameter studies and verified native test runs. Full chart visualization arrives in the dedicated Experimental Lab dashboard milestone.</p></div>");
        portalBody.AppendLine(experimentalBlock);
        portalBody.AppendLine("</section>");
        portalBody.AppendLine("<section id=\"portalPageManufacturers\" class=\"portal-page\" data-portal-page=\"manufacturers\" hidden>");
        portalBody.AppendLine(BuildNativeManufacturerPortalHtml(manufacturerRows ?? Array.Empty<DataRow>()));
        portalBody.AppendLine("</section>");
        portalBody.AppendLine("<section id=\"portalPageMethodology\" class=\"portal-page\" data-portal-page=\"methodology\" hidden>");
        portalBody.AppendLine(BuildMethodologyPortalHtml());
        portalBody.AppendLine("</section>");
        portalBody.AppendLine(markerEnd);

        html = html.Substring(0, mainOpen.Index + mainOpen.Length) + portalBody + html.Substring(mainClose);

        const string portalCss = @"
