        const string portalScript = @"
<script id=""nativePortalNavigationScript"">
(function(){
  const valid=['database','pricing','experimental','manufacturers','methodology'];
  const tabs=Array.from(document.querySelectorAll('[data-portal-target]'));
  const pages=Array.from(document.querySelectorAll('[data-portal-page]'));
  function routeFromHash(){
    const raw=(location.hash||'#database').slice(1).split(/[?&]/)[0].toLowerCase();
    return valid.includes(raw)?raw:'database';
  }
  function activate(route,updateHash){
    if(!valid.includes(route)) route='database';
    tabs.forEach(tab=>{const active=tab.dataset.portalTarget===route;tab.classList.toggle('is-active',active);tab.setAttribute('aria-selected',active?'true':'false');});
    pages.forEach(page=>{const active=page.dataset.portalPage===route;page.hidden=!active;page.classList.toggle('is-active',active);});
    if(updateHash && location.hash!=='#'+route) history.pushState(null,'','#'+route);
    document.documentElement.dataset.portalRoute=route;
    if(route==='pricing'){
      syncPricingFilters();
      requestAnimationFrame(()=>{if(typeof renderPricePerformance==='function')renderPricePerformance();});
    }
    window.scrollTo({top:0,behavior:'auto'});
  }
  const pricingFilterPairs=[
    ['pricingFilterChartMode','chartMode'],['pricingFilterCategory','category'],['pricingFilterType','type'],['pricingFilterVariant','variant'],
    ['pricingFilterReinforcement','reinforcement'],['pricingFilterColor','color'],['pricingFilterManufacturer','manufacturer'],
    ['pricingFilterProductLine','productLine'],['pricingFilterPriceMin','priceMin'],['pricingFilterPriceMax','priceMax'],
    ['pricingFilterAvailability','priceAvailability'],['pricingFilterSortMode','sortMode'],['pricingFilterSearch','search']
  ];
  function copySelectState(source,target){
    target.replaceChildren(...Array.from(source.options).map(option=>{const clone=document.createElement('option');clone.value=option.value;clone.textContent=option.textContent;return clone;}));
    Array.from(target.options).forEach(option=>option.selected=Array.from(source.selectedOptions).some(selected=>selected.value===option.value));
  }
  function syncPricingFilters(){
    pricingFilterPairs.forEach(([mirrorId,sourceId])=>{const mirror=document.getElementById(mirrorId),source=document.getElementById(sourceId);if(!mirror||!source)return;if(source.tagName==='SELECT')copySelectState(source,mirror);else mirror.value=source.value;});
  }
  pricingFilterPairs.forEach(([mirrorId,sourceId])=>{
    const mirror=document.getElementById(mirrorId),source=document.getElementById(sourceId);if(!mirror||!source)return;
    mirror.addEventListener('input',()=>{if(source.tagName==='SELECT'){Array.from(source.options).forEach(option=>option.selected=Array.from(mirror.selectedOptions).some(selected=>selected.value===option.value));}else source.value=mirror.value;source.dispatchEvent(new Event('input',{bubbles:true}));requestAnimationFrame(syncPricingFilters);});
    source.addEventListener('input',()=>requestAnimationFrame(syncPricingFilters));
    if(mirror instanceof HTMLSelectElement&&mirror.multiple){
      mirror.addEventListener('mousedown',event=>{
        if(event.target instanceof HTMLOptionElement){
          event.preventDefault();
          event.target.selected=!event.target.selected;
          mirror.dispatchEvent(new Event('input',{bubbles:true}));
        }
      });
    }
  });
  document.getElementById('pricingFilterReset')?.addEventListener('click',()=>{document.getElementById('reset')?.click();requestAnimationFrame(syncPricingFilters);});
  tabs.forEach(tab=>tab.addEventListener('click',()=>activate(tab.dataset.portalTarget,true)));
  document.querySelectorAll('[data-methodology-scroll]').forEach(link=>link.addEventListener('click',event=>{
    event.preventDefault();
    activate('methodology',location.hash!=='#methodology');
    const target=document.getElementById(link.dataset.methodologyScroll);
    if(target) requestAnimationFrame(()=>target.scrollIntoView({behavior:'smooth',block:'start'}));
  }));
  const submissionForm=document.getElementById('manufacturerSubmissionForm');
  const submissionStatus=document.getElementById('manufacturerSubmissionStatus');
  const submissionReference=document.getElementById('manufacturerSubmissionReference');
  function createSubmissionReference(){
    const date=new Date().toISOString().slice(0,10).replace(/-/g,'');
    const bytes=new Uint8Array(4);
    if(window.crypto&&window.crypto.getRandomValues) window.crypto.getRandomValues(bytes);
    else bytes.forEach((_,index)=>bytes[index]=Math.floor(Math.random()*256));
    return '3DPI-'+date+'-'+Array.from(bytes,value=>value.toString(16).padStart(2,'0')).join('').toUpperCase();
  }
  function ensureSubmissionReference(){
    if(submissionReference&&!submissionReference.value) submissionReference.value=createSubmissionReference();
    return submissionReference?.value||createSubmissionReference();
  }
  function submissionDetails(){
    if(!submissionForm) return '';
    const data=new FormData(submissionForm);
    const value=name=>(data.get(name)||'').toString().trim()||'Not provided';
    return [
      '3DPIceland Manufacturer Material Submission',
      'Reference ID: '+ensureSubmissionReference(),
      '',
      'Company: '+value('company'),
      'Contact name: '+value('contactName'),
      'Contact email: '+value('contactEmail'),
      'Material name: '+value('materialName'),
      'Product line: '+value('productLine'),
      'Material type: '+value('materialType'),
      'Colour: '+value('colour'),
      'Spool size: '+value('spoolSize'),
      'Sample quantity: '+value('sampleQuantity'),
      'Product page: '+value('productUrl'),
      'Technical datasheet: '+value('datasheetUrl'),
      '',
      'Testing goals / notes:',
      value('notes'),
      '',
      'Acknowledgement: Independent, data-driven testing and publication accepted.'
    ].join('\n');
  }
  function setSubmissionStatus(message,type){
    if(!submissionStatus) return;
    submissionStatus.textContent=message;
    submissionStatus.classList.toggle('is-error',type==='error');
    submissionStatus.classList.toggle('is-success',type==='success');
  }
  document.querySelectorAll('[data-manufacturer-submission-open]').forEach(button=>button.addEventListener('click',()=>{
    const target=document.getElementById('manufacturerSubmissionSection');
    if(target) target.scrollIntoView({behavior:'smooth',block:'start'});
    requestAnimationFrame(()=>document.getElementById('manufacturerCompany')?.focus({preventScroll:true}));
  }));
  if(submissionForm){
    ensureSubmissionReference();
    submissionForm.addEventListener('submit',event=>{
      event.preventDefault();
      if(!submissionForm.reportValidity()){
        setSubmissionStatus('Please complete the required fields and accept the independent-testing acknowledgement.','error');
        return;
      }
      const reference=ensureSubmissionReference();
      const subject='Material testing submission - '+reference;
      const mailto='mailto:iskort@iskort.is?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(submissionDetails());
      setSubmissionStatus('Your email application is opening. Review the message and press Send to complete the enquiry.','success');
      window.location.href=mailto;
    });
    document.getElementById('manufacturerCopySubmission')?.addEventListener('click',async()=>{
      if(!submissionForm.reportValidity()){
        setSubmissionStatus('Please complete the required fields before copying the submission.','error');
        return;
      }
      const details=submissionDetails();
      try{
        await navigator.clipboard.writeText(details);
      }catch(error){
        const fallback=document.createElement('textarea');fallback.value=details;fallback.style.position='fixed';fallback.style.opacity='0';document.body.appendChild(fallback);fallback.select();document.execCommand('copy');fallback.remove();
      }
      setSubmissionStatus('Submission details copied. Paste them into an email to iskort@iskort.is.','success');
    });
  }
  window.addEventListener('hashchange',()=>activate(routeFromHash(),false));
  activate(routeFromHash(),false);
})();
</script>";
        var bodyClose = html.LastIndexOf("</body>", StringComparison.OrdinalIgnoreCase);
        return bodyClose >= 0 ? html.Insert(bodyClose, portalScript + Environment.NewLine) : html + portalScript;
    }


    private string BuildNativeManufacturerPortalHtml(IReadOnlyList<DataRow> rows)
    {
        const string submissionEmail = "iskort@iskort.is";
        var activeRows = rows.Where(row => !IsTruthy(DataTableHelpers.FirstValue(row, "Archived", "Is Archived"))).ToList();
        var profiles = LoadManufacturerKnowledgeByName();
        var verifiedSummaries = BuildVerifiedMaterialSummaryMap(GetNativeWebsiteExportCandidateRows());

        // Build the directory from the union of native material manufacturers and active
        // SQLite manufacturer profiles. This makes newly added profiles visible immediately,
        // even before a material has been linked to them.
        var materialGroups = activeRows
            .Select(row => new { Row = row, Name = (GetCell(row, "Manufacturer", "Brand") ?? string.Empty).Trim() })
            .Where(item => !string.IsNullOrWhiteSpace(item.Name))
            .GroupBy(item => item.Name, StringComparer.OrdinalIgnoreCase)
            .ToDictionary(group => group.Key, group => group.Select(item => item.Row).ToList(), StringComparer.OrdinalIgnoreCase);

        var manufacturerNames = materialGroups.Keys
            .Concat(profiles.Keys)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(name => profiles.TryGetValue(name, out var profile) ? profile.SortOrder : int.MaxValue)
            .ThenBy(name => name, StringComparer.OrdinalIgnoreCase)
            .ToList();

        var activeMaterialIds = activeRows
            .Select(row => (GetCell(row, "Material ID", "MaterialID") ?? string.Empty).Trim())
            .Where(id => !string.IsNullOrWhiteSpace(id))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();
        var testedCount = activeMaterialIds.Count(id => verifiedSummaries.TryGetValue(id, out var summary) && summary.HasAnyResults);
        var tensileCount = activeMaterialIds.Count(id => verifiedSummaries.TryGetValue(id, out var summary) && summary.HasTensileResults);
        var impactCount = activeMaterialIds.Count(id => verifiedSummaries.TryGetValue(id, out var summary) && summary.HasImpactResults);
        var stiffnessCount = activeMaterialIds.Count(id => verifiedSummaries.TryGetValue(id, out var summary) && summary.HasStiffnessResults);
        var layerAdhesionCount = activeMaterialIds.Count(id =>
            verifiedSummaries.TryGetValue(id, out var summary) &&
            summary.Tensile?.Upright.SampleCount > 0 &&
            summary.Tensile.Flat.SampleCount > 0);
        var completeSummaryCount = activeMaterialIds.Count(id => verifiedSummaries.TryGetValue(id, out var summary) && summary.IsCompleteEngineeringSummary);
        var productLinkCount = activeRows.Count(row => HasAnyValue(row, "Product Page", "Product URL", "ProductUrl", "Manufacturer Website", "Website"));
        var youtubeLinkCount = activeRows.Count(row => HasAnyValue(row, "YouTube Review URL", "YouTube URL"));
        var sb = new StringBuilder();
        sb.AppendLine("<div class=\"manufacturer-portal\">");
        sb.AppendLine("<div class=\"manufacturer-hero\"><p class=\"portal-eyebrow\">Independent filament testing and manufacturer intelligence</p><h1>Put your materials into comparable, real-world testing</h1><p>3DPIceland Labs measures tensile strength, impact resistance, stiffness and layer adhesion using one controlled, repeatable workflow. Manufacturers receive independent technical visibility, comparable engineering context and long-term discoverability across the database, rankings, reports and relevant video coverage.</p>");
        sb.AppendLine("<div class=\"manufacturer-summary-grid\">");
        sb.AppendLine($"<div class=\"manufacturer-summary\"><span>Manufacturers</span><strong>{manufacturerNames.Count}</strong></div>");
        sb.AppendLine($"<div class=\"manufacturer-summary\"><span>Materials in database</span><strong>{activeRows.Count}+</strong></div>");
        sb.AppendLine($"<div class=\"manufacturer-summary\"><span>Tested materials</span><strong>{testedCount}+</strong></div>");
        sb.AppendLine("<div class=\"manufacturer-summary\"><span>Verification checks</span><strong>150+</strong></div>");
        sb.AppendLine("</div></div>");
        sb.AppendLine("<section class=\"manufacturer-outreach\" aria-labelledby=\"manufacturerSubmissionHeading\">");
        sb.AppendLine("<div class=\"manufacturer-outreach-panel\"><p class=\"portal-eyebrow\">Manufacturer submission portal</p><h2 id=\"manufacturerSubmissionHeading\">Submit materials for independent testing</h2><p>Send production filament for inclusion in the 3DPIceland Engineering Platform. Materials enter the same documented print, measurement, calculation and verification pipeline as the rest of the database. Results are independent and data-driven; paid placement is not required and does not influence rankings.</p>");
        sb.AppendLine("<div class=\"manufacturer-process-grid\"><div class=\"manufacturer-process-step\"><strong>1. Contact us</strong><span>Tell us which materials, product lines and technical claims you want evaluated.</span></div><div class=\"manufacturer-process-step\"><strong>2. Send materials</strong><span>We confirm spool requirements, shipping details and the intended comparison scope.</span></div><div class=\"manufacturer-process-step\"><strong>3. Controlled testing</strong><span>Specimens are printed and measured through the documented tensile, impact, stiffness and layer-adhesion workflow.</span></div><div class=\"manufacturer-process-step\"><strong>4. Published context</strong><span>Eligible results enter the database, manufacturer comparisons, rankings, engineering reports and relevant review coverage.</span></div></div>");
        sb.AppendLine($"<div class=\"manufacturer-cta-row\"><button type=\"button\" class=\"manufacturer-cta-primary\" data-manufacturer-submission-open>Submit Materials for Testing</button><a class=\"manufacturer-cta-secondary\" href=\"#methodology\" data-methodology-scroll=\"methodology-overview\">Read the methodology</a><a class=\"manufacturer-cta-secondary\" href=\"3DPIceland_Labs_Mechanical_Testing_Methodology_v1.0.pdf\" target=\"_blank\" rel=\"noopener\">Engineering whitepaper</a></div><p class=\"manufacturer-contact\">Manufacturer enquiries: <a href=\"mailto:{submissionEmail}\">{submissionEmail}</a></p></div>");
        sb.AppendLine("<aside class=\"manufacturer-participation\"><h2>What participation delivers</h2><p>A durable technical presence built around measured results rather than promotional placement.</p><ul class=\"manufacturer-benefits\"><li>Independent technical exposure</li><li>Comparable results across brands</li><li>Long-term database discoverability</li><li>Product and review links</li><li>Rankings and manufacturer intelligence</li><li>Engineering PDF and whitepaper context</li><li>Website visibility</li><li>YouTube exposure when relevant</li><li>No requirement for paid placement</li></ul></aside>");
        sb.AppendLine("</section>");
        sb.AppendLine("<section id=\"manufacturerSubmissionSection\" class=\"manufacturer-submission\" aria-labelledby=\"manufacturerFormHeading\"><div class=\"manufacturer-submission-header\"><p class=\"portal-eyebrow\">Structured email submission</p><h2 id=\"manufacturerFormHeading\">Tell us which materials you want tested</h2><p>Complete the form and your email application will open with a structured enquiry addressed to 3DPIceland Labs. No information is uploaded or stored by this website.</p></div>");
        sb.AppendLine("<form id=\"manufacturerSubmissionForm\" class=\"manufacturer-submission-form\"><input id=\"manufacturerSubmissionReference\" name=\"referenceId\" type=\"hidden\"><div class=\"manufacturer-form-grid\">");
        sb.AppendLine("<div class=\"manufacturer-form-field\"><label for=\"manufacturerCompany\">Company <span>*</span></label><input id=\"manufacturerCompany\" name=\"company\" type=\"text\" maxlength=\"120\" autocomplete=\"organization\" required></div>");
        sb.AppendLine("<div class=\"manufacturer-form-field\"><label for=\"manufacturerContactName\">Contact name <span>*</span></label><input id=\"manufacturerContactName\" name=\"contactName\" type=\"text\" maxlength=\"120\" autocomplete=\"name\" required></div>");
        sb.AppendLine("<div class=\"manufacturer-form-field\"><label for=\"manufacturerContactEmail\">Contact email <span>*</span></label><input id=\"manufacturerContactEmail\" name=\"contactEmail\" type=\"email\" maxlength=\"160\" autocomplete=\"email\" required></div>");
        sb.AppendLine("<div class=\"manufacturer-form-field\"><label for=\"manufacturerMaterialName\">Material name <span>*</span></label><input id=\"manufacturerMaterialName\" name=\"materialName\" type=\"text\" maxlength=\"160\" required></div>");
        sb.AppendLine("<div class=\"manufacturer-form-field\"><label for=\"manufacturerProductLine\">Product line</label><input id=\"manufacturerProductLine\" name=\"productLine\" type=\"text\" maxlength=\"160\"></div>");
        sb.AppendLine("<div class=\"manufacturer-form-field\"><label for=\"manufacturerMaterialType\">Material type <span>*</span></label><input id=\"manufacturerMaterialType\" name=\"materialType\" type=\"text\" maxlength=\"80\" placeholder=\"PLA, PETG, ASA, PA, PC...\" required></div>");
        sb.AppendLine("<div class=\"manufacturer-form-field\"><label for=\"manufacturerColour\">Colour</label><input id=\"manufacturerColour\" name=\"colour\" type=\"text\" maxlength=\"80\"></div>");
        sb.AppendLine("<div class=\"manufacturer-form-field\"><label for=\"manufacturerSpoolSize\">Spool size</label><input id=\"manufacturerSpoolSize\" name=\"spoolSize\" type=\"text\" maxlength=\"60\" placeholder=\"For example 1 kg\"></div>");
        sb.AppendLine("<div class=\"manufacturer-form-field\"><label for=\"manufacturerSampleQuantity\">Sample quantity <span>*</span></label><input id=\"manufacturerSampleQuantity\" name=\"sampleQuantity\" type=\"number\" min=\"1\" max=\"100\" step=\"1\" required><span class=\"manufacturer-form-help\">Number of spools or material samples proposed.</span></div>");
        sb.AppendLine("<div class=\"manufacturer-form-field\"><label for=\"manufacturerProductUrl\">Product page</label><input id=\"manufacturerProductUrl\" name=\"productUrl\" type=\"url\" maxlength=\"500\" placeholder=\"https://\"></div>");
        sb.AppendLine("<div class=\"manufacturer-form-field wide\"><label for=\"manufacturerDatasheetUrl\">Technical datasheet</label><input id=\"manufacturerDatasheetUrl\" name=\"datasheetUrl\" type=\"url\" maxlength=\"500\" placeholder=\"https://\"></div>");
        sb.AppendLine("<div class=\"manufacturer-form-field wide\"><label for=\"manufacturerNotes\">Testing goals or additional notes</label><textarea id=\"manufacturerNotes\" name=\"notes\" maxlength=\"800\" placeholder=\"Tell us about the material, relevant claims, intended applications or comparison goals.\"></textarea></div></div>");
        sb.AppendLine("<label class=\"manufacturer-acknowledgement\"><input name=\"acknowledgement\" type=\"checkbox\" required><span>I understand that testing and publication are independent and data-driven. Submission does not guarantee publication, ranking position or favourable results.</span></label>");
        sb.AppendLine("<div class=\"manufacturer-form-actions\"><button type=\"submit\" class=\"manufacturer-cta-primary\">Prepare Email Submission</button><button type=\"button\" id=\"manufacturerCopySubmission\" class=\"manufacturer-copy-button\">Copy Submission Details</button></div><p id=\"manufacturerSubmissionStatus\" class=\"manufacturer-form-status\" role=\"status\" aria-live=\"polite\"></p>");
        sb.AppendLine($"<p class=\"manufacturer-mail-note\">This first-stage form does not send or store data on the server. Your email application must open and you must press Send. If that does not work, copy the submission details and email them to <a href=\"mailto:{submissionEmail}\">{submissionEmail}</a>.</p></form></section>");
        sb.AppendLine($"<div class=\"manufacturer-platform-grid\" aria-label=\"Verified platform coverage\"><div class=\"manufacturer-platform-item\"><span>Tensile</span><strong>{tensileCount}</strong><small>materials with verified tensile results</small></div><div class=\"manufacturer-platform-item\"><span>Impact</span><strong>{impactCount}</strong><small>materials with verified impact results</small></div><div class=\"manufacturer-platform-item\"><span>Stiffness</span><strong>{stiffnessCount}</strong><small>materials with verified stiffness results</small></div><div class=\"manufacturer-platform-item\"><span>Layer adhesion</span><strong>{layerAdhesionCount}</strong><small>materials with both tensile orientations</small></div><div class=\"manufacturer-platform-item\"><span>Manufacturer comparison</span><strong>{manufacturerNames.Count}</strong><small>manufacturers available for comparison</small></div><div class=\"manufacturer-platform-item\"><span>Engineering reports</span><strong>{completeSummaryCount}</strong><small>complete engineering summaries</small></div><div class=\"manufacturer-platform-item\"><span>Product visibility</span><strong>{productLinkCount}</strong><small>materials with product links</small></div><div class=\"manufacturer-platform-item\"><span>YouTube exposure</span><strong>{youtubeLinkCount}</strong><small>materials with linked reviews</small></div></div>");
        sb.AppendLine("<div class=\"portal-page-heading\"><p class=\"portal-eyebrow\">Measured manufacturer directory</p><h1>Explore participating manufacturers</h1><p>Profiles, material coverage and engineering highlights below are generated from the canonical SQLite database and verified result summaries during every website export.</p></div>");
        sb.AppendLine("<div class=\"manufacturer-directory\">");

        if (manufacturerNames.Count == 0)
        {
            sb.AppendLine("<div class=\"manufacturer-empty\">No active manufacturer data is available yet.</div>");
        }

        foreach (var manufacturerName in manufacturerNames)
        {
            profiles.TryGetValue(manufacturerName, out var profile);
            var groupRows = materialGroups.TryGetValue(manufacturerName, out var linkedRows) ? linkedRows : new List<DataRow>();
            var displayName = !string.IsNullOrWhiteSpace(profile?.DisplayName) ? profile.DisplayName : manufacturerName;
            var tested = groupRows
                .Select(row => (GetCell(row, "Material ID", "MaterialID") ?? string.Empty).Trim())
                .Where(id => !string.IsNullOrWhiteSpace(id))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Count(id => verifiedSummaries.TryGetValue(id, out var summary) && summary.HasAnyResults);
            var baseMaterials = groupRows.Select(row => (GetCell(row, "Base Material", "Material Type", "Type") ?? string.Empty).Trim())
                .Where(value => !string.IsNullOrWhiteSpace(value)).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(value => value).ToList();
            var productLines = groupRows.Select(row => (GetCell(row, "Product Line", "ProductLine") ?? string.Empty).Trim())
                .Where(value => !string.IsNullOrWhiteSpace(value)).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(value => value).ToList();
            var productUrl = groupRows.Select(row => EmptyToNull(GetCell(row, "Product Page", "Product URL", "ProductUrl", "Manufacturer Website", "Website")))
                .FirstOrDefault(value => !string.IsNullOrWhiteSpace(value));
            var youtubeUrl = groupRows.Select(row => EmptyToNull(GetCell(row, "YouTube Review URL", "YouTube URL")))
                .FirstOrDefault(value => !string.IsNullOrWhiteSpace(value));
            var website = !string.IsNullOrWhiteSpace(profile?.Website) ? profile.Website : productUrl;
            var intelligence = BuildManufacturerEngineeringIntelligence(groupRows, verifiedSummaries);
            var publicManufacturerReportUrl = _nativeMaterialRows.Any(item => !item.IsArchived && item.PublishPublicReports && string.Equals(item.Manufacturer?.Trim(), manufacturerName, StringComparison.CurrentCultureIgnoreCase))
                ? $"reports/manufacturers/{PublicComparisonReportPublishingService.SafeSlug(manufacturerName)}/index.html"
                : null;

            sb.AppendLine("<article class=\"manufacturer-card\">");
            sb.AppendLine("<div class=\"manufacturer-card-header\"><div>");
            sb.AppendLine($"<h2>{System.Net.WebUtility.HtmlEncode(displayName)}</h2>");
            var metaParts = new[] { profile?.Country, string.IsNullOrWhiteSpace(profile?.Founded) ? null : "Founded " + profile.Founded, profile?.Headquarters }.Where(value => !string.IsNullOrWhiteSpace(value));
            sb.AppendLine($"<div class=\"manufacturer-meta\">{System.Net.WebUtility.HtmlEncode(string.Join(" • ", metaParts))}</div></div>");
            if (!string.IsNullOrWhiteSpace(profile?.LogoUrl)) sb.AppendLine($"<img class=\"manufacturer-logo\" src=\"{System.Net.WebUtility.HtmlEncode(profile.LogoUrl)}\" alt=\"{System.Net.WebUtility.HtmlEncode(displayName)} logo\" loading=\"lazy\">");
            sb.AppendLine("</div>");
            if (!string.IsNullOrWhiteSpace(profile?.Description)) sb.AppendLine($"<div class=\"manufacturer-description\">{System.Net.WebUtility.HtmlEncode(profile.Description)}</div>");
            sb.AppendLine("<div class=\"manufacturer-stats\">");
            sb.AppendLine($"<div class=\"manufacturer-stat\"><strong>{groupRows.Count}</strong><span>Materials</span></div>");
            sb.AppendLine($"<div class=\"manufacturer-stat\"><strong>{tested}</strong><span>Tested</span></div>");
            sb.AppendLine($"<div class=\"manufacturer-stat\"><strong>{baseMaterials.Count}</strong><span>Families</span></div>");
            sb.AppendLine("</div>");
            AppendManufacturerPortalDetail(sb, "Engineering focus", profile?.EngineeringFocus);
            AppendManufacturerPortalDetail(sb, "Strengths", profile?.Strengths);
            AppendManufacturerPortalDetail(sb, "Typical applications", profile?.TypicalApplications);
            AppendManufacturerPortalDetail(sb, "Sustainability", profile?.Sustainability);
            AppendManufacturerEngineeringIntelligence(sb, intelligence);
            var tags = baseMaterials.Concat(productLines).Distinct(StringComparer.OrdinalIgnoreCase).Take(14).ToList();
            if (tags.Count > 0)
            {
                sb.AppendLine("<div class=\"manufacturer-tags\">");
                foreach (var tag in tags) sb.AppendLine($"<span class=\"manufacturer-tag\">{System.Net.WebUtility.HtmlEncode(tag)}</span>");
                sb.AppendLine("</div>");
            }
            sb.AppendLine("<div class=\"manufacturer-actions\">");
            if (!string.IsNullOrWhiteSpace(publicManufacturerReportUrl)) sb.AppendLine($"<a href=\"{System.Net.WebUtility.HtmlEncode(publicManufacturerReportUrl)}\">Engineering report</a>");
            if (!string.IsNullOrWhiteSpace(website)) sb.AppendLine($"<a href=\"{System.Net.WebUtility.HtmlEncode(website)}\" target=\"_blank\" rel=\"noopener noreferrer\">Manufacturer website</a>");
            if (!string.IsNullOrWhiteSpace(youtubeUrl)) sb.AppendLine($"<a class=\"secondary\" href=\"{System.Net.WebUtility.HtmlEncode(youtubeUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\">Watch review</a>");
            sb.AppendLine("</div></article>");
        }

        sb.AppendLine("</div></div>");
        return sb.ToString();
    }

    private ManufacturerEngineeringIntelligence BuildManufacturerEngineeringIntelligence(
        IReadOnlyList<DataRow> rows,
        IReadOnlyDictionary<string, MaterialResults> verifiedSummaries)
    {
        var materials = new List<ManufacturerMaterialInsight>();
        foreach (var row in rows)
        {
            var materialId = (GetCell(row, "Material ID", "MaterialID") ?? string.Empty).Trim();
            if (string.IsNullOrWhiteSpace(materialId)) continue;

            verifiedSummaries.TryGetValue(materialId, out var summary);
            var metrics = GetCanonicalTestSummaryMetrics(materialId)
                .Where(metric => metric.TestType is "Tensile" or "Impact" or "Stiffness" or "Rating")
                .ToList();
            var profile = _scoringService.BuildProfile(_database.GetTensileTestResult(materialId), metrics);
            var label = !string.IsNullOrWhiteSpace(GetCell(row, "Website Display Name"))
                ? GetCell(row, "Website Display Name")!.Trim()
                : _detailService.BuildTitle(row);
            var nativePricingRow = _nativeMaterialRows.FirstOrDefault(item =>
                string.Equals(item.MaterialID, materialId, StringComparison.OrdinalIgnoreCase));
            var pricePerKg = _pricingProvenanceService.ResolveCanonicalMsrpUsdPerKg(
                nativePricingRow is not null,
                nativePricingRow?.MsrpUsdPerKg,
                GetCell(row, "MSRP USD/kg", "MsrpUsdPerKg"));
            var valueIndex = _engineeringValueIndexService.Calculate(
                profile.OverallScore,
                pricePerKg,
                !string.IsNullOrWhiteSpace(GetCell(row, "Base Material", "Material Type", "Type"))
                    ? $"current filtered {GetCell(row, "Base Material", "Material Type", "Type")!.Trim()} group"
                    : "current manufacturer material dataset");

            materials.Add(new ManufacturerMaterialInsight(
                materialId,
                label,
                (GetCell(row, "Base Material", "Material Type", "Type") ?? string.Empty).Trim(),
                summary,
                profile,
                valueIndex.Value,
                pricePerKg));
        }

        var scored = materials.Where(item => item.Profile.OverallScore.HasValue).ToList();
        var averageOverall = scored.Count > 0 ? scored.Average(item => item.Profile.OverallScore!.Value) : (double?)null;
        return new ManufacturerEngineeringIntelligence(
            materials.Count(item => item.Summary?.IsCompleteEngineeringSummary == true),
            materials.Count(item => item.Summary?.HasAnyResults == true && item.Summary.IsCompleteEngineeringSummary == false),
            averageOverall,
            TopInsight(materials, item => item.Summary?.BestTensileMpa),
            TopInsight(materials, item => item.Summary?.BestImpactKjM2),
            TopInsight(materials, item => item.Summary?.StiffnessMpa),
            TopInsight(materials, item => item.Profile.LayerAdhesionScore),
            TopInsight(materials, item => item.Profile.OverallScore),
            TopValueInsight(materials),
            scored.OrderByDescending(item => item.Profile.OverallScore).Take(3).ToList(),
            materials.Where(item => !string.IsNullOrWhiteSpace(item.BaseMaterial))
                .GroupBy(item => item.BaseMaterial, StringComparer.OrdinalIgnoreCase)
                .OrderByDescending(group => group.Count())
                .ThenBy(group => group.Key, StringComparer.OrdinalIgnoreCase)
                .Take(6)
                .Select(group => $"{group.Key} ({group.Count()})")
                .ToList());
    }

    private static ManufacturerMetricLeader? TopInsight(
        IEnumerable<ManufacturerMaterialInsight> materials,
        Func<ManufacturerMaterialInsight, double?> selector)
    {
        return materials
            .Select(item => new { Item = item, Value = selector(item) })
            .Where(item => item.Value.HasValue && double.IsFinite(item.Value.Value))
            .OrderByDescending(item => item.Value!.Value)
            .Select(item => new ManufacturerMetricLeader(item.Item.Label, item.Value!.Value))
            .FirstOrDefault();
    }

    private static ManufacturerMetricLeader? TopValueInsight(IEnumerable<ManufacturerMaterialInsight> materials)
    {
        return materials
            .Where(item => item.ValueScore.HasValue && double.IsFinite(item.ValueScore.Value) &&
                           item.PricePerKg.HasValue && item.PricePerKg.Value > 0 &&
                           item.Profile.OverallScore.HasValue)
            .OrderByDescending(item => item.ValueScore!.Value)
            .Select(item => new ManufacturerMetricLeader(
                item.Label,
                item.ValueScore!.Value,
                item.PricePerKg,
                item.Profile.OverallScore))
            .FirstOrDefault();
    }

    private static void AppendManufacturerEngineeringIntelligence(StringBuilder sb, ManufacturerEngineeringIntelligence intelligence)
    {
        if (!intelligence.HasData) return;
        sb.AppendLine("<div class=\"manufacturer-intelligence\"><h3>Engineering intelligence</h3>");
        sb.AppendLine("<div class=\"manufacturer-leaders\">");
        AppendManufacturerLeader(sb, "Strongest tensile", intelligence.StrongestTensile, "MPa");
        AppendManufacturerLeader(sb, "Best impact", intelligence.BestImpact, "kJ/m²");
        AppendManufacturerLeader(sb, "Highest stiffness", intelligence.HighestStiffness, "MPa");
        AppendManufacturerLeader(sb, "Best layer adhesion", intelligence.BestLayerAdhesion, "/100");
        AppendManufacturerLeader(sb, "Best overall", intelligence.BestOverall, "/100");
        AppendManufacturerBestValueLeader(sb, intelligence.BestValue);
        sb.AppendLine("</div>");
        var coverage = $"{intelligence.CompleteCount} complete engineering profiles" +
                       (intelligence.PartialCount > 0 ? $" • {intelligence.PartialCount} partial" : string.Empty) +
                       (intelligence.AverageOverall.HasValue ? $" • average overall {intelligence.AverageOverall.Value:0.0}/100" : string.Empty);
        sb.AppendLine($"<div class=\"manufacturer-family-summary\">{System.Net.WebUtility.HtmlEncode(coverage)}</div>");
        if (intelligence.TopMaterials.Count > 0)
        {
            sb.AppendLine("<ol class=\"manufacturer-top-list\">");
            foreach (var item in intelligence.TopMaterials)
                sb.AppendLine($"<li><strong>{System.Net.WebUtility.HtmlEncode(item.Label)}</strong> — {item.Profile.OverallScore:0.0}/100</li>");
            sb.AppendLine("</ol>");
        }
        if (intelligence.FamilySummary.Count > 0)
            sb.AppendLine($"<div class=\"manufacturer-family-summary\"><strong>Coverage:</strong> {System.Net.WebUtility.HtmlEncode(string.Join(" • ", intelligence.FamilySummary))}</div>");
        sb.AppendLine("</div>");
    }

    private static void AppendManufacturerLeader(StringBuilder sb, string title, ManufacturerMetricLeader? leader, string unit)
    {
        if (leader is null) return;
        sb.AppendLine($"<div class=\"manufacturer-leader\"><span>{System.Net.WebUtility.HtmlEncode(title)}</span><strong>{System.Net.WebUtility.HtmlEncode(leader.Label)}</strong><small>{leader.Value:0.0} {System.Net.WebUtility.HtmlEncode(unit)}</small></div>");
    }

    private static void AppendManufacturerBestValueLeader(StringBuilder sb, ManufacturerMetricLeader? leader)
    {
        if (leader is null || !leader.PricePerKg.HasValue || !leader.OverallScore.HasValue) return;
        var price = leader.PricePerKg.Value.ToString("0.00", CultureInfo.InvariantCulture);
        var value = leader.Value.ToString("0.00", CultureInfo.InvariantCulture);
        var overall = leader.OverallScore.Value.ToString("0.0", CultureInfo.InvariantCulture);
        sb.AppendLine($"<div class=\"manufacturer-leader\"><span>Best value</span><strong>{System.Net.WebUtility.HtmlEncode(leader.Label)}</strong><small><b>MSRP:</b> ${price}/kg<br><b>Engineering score:</b> {overall}/100<br><b>Value score:</b> {value}</small></div>");
    }

    private static void AppendManufacturerPortalDetail(StringBuilder sb, string heading, string? value)
    {
        if (string.IsNullOrWhiteSpace(value)) return;
        sb.AppendLine($"<div class=\"manufacturer-detail\"><h3>{System.Net.WebUtility.HtmlEncode(heading)}</h3><p>{System.Net.WebUtility.HtmlEncode(value)}</p></div>");
    }

    private static string BuildMethodologyPortalHtml()
    {
        const string resourceName = "FilamentDbApp.Assets.Website.MethodologyPortal.html";
        using var stream = typeof(MainWindow).Assembly.GetManifestResourceStream(resourceName);
        if (stream is null)
        {
            return "<div class=\"portal-placeholder\"><p class=\"portal-eyebrow\">Methodology unavailable</p><h1>How the materials are tested</h1><p>The embedded methodology resource could not be loaded.</p></div>";
        }

        using var reader = new StreamReader(stream, Encoding.UTF8, true);
        return reader.ReadToEnd();
    }


    private static string ApplyWebsiteTerminologyCleanup(string html)
    {
        const string marker = "<!-- 3DP-WEBSITE-TERMINOLOGY-v40.12.2 -->";
        if (html.Contains(marker, StringComparison.Ordinal)) return html;

        // The legacy manufacturers CTA is redundant now that For Manufacturers is a portal tab.
        html = Regex.Replace(
            html,
            @"<div\s+class=[""']manufacturer-cta[""'][^>]*>.*?</div>",
            string.Empty,
            RegexOptions.IgnoreCase | RegexOptions.Singleline | RegexOptions.CultureInvariant);

        // Website-only display terminology. SQLite, calculation services and WPF labels remain unchanged.
        html = html.Replace(
            "<section class=\"card\"><h2>Tensile strength</h2>",
            "<section class=\"card\"><h2>Tensile Strength vs Layer Adhesion Strength</h2>",
            StringComparison.Ordinal);
        html = html.Replace(
            "<span><i class=\"key upright\"></i>Upright</span><span><i class=\"key flat\"></i>Flat</span><span>Error bars: standard deviation</span>",
            "<span><i class=\"key upright\"></i>Layer Adhesion Strength <small>(upright specimens)</small></span><span><i class=\"key flat\"></i>Tensile Strength <small>(flat specimens)</small></span><span>Error bars: standard deviation</span>",
            StringComparison.Ordinal);
        html = html.Replace(
            "Ranking by upright tensile strength relative to flat tensile strength",
            "Ranking by layer adhesion strength relative to tensile strength",
            StringComparison.Ordinal);
        html = html.Replace(
            "Ratio: Upright tensile / Flat tensile",
            "Ratio: Layer Adhesion Strength / Tensile Strength",
            StringComparison.Ordinal);
        html = html.Replace(
            "the upright specimen retains more of the flat tensile strength",
            "the upright specimen retains more of the flat-specimen tensile strength",
            StringComparison.Ordinal);
        html = html.Replace(
            "<br>Upright tensile: ${fmt(r.tensileUpright)} MPa<br>Flat tensile: ${fmt(r.tensileFlat)} MPa",
            "<br>Layer Adhesion Strength: ${fmt(r.tensileUpright)} MPa<br>Tensile Strength: ${fmt(r.tensileFlat)} MPa",
            StringComparison.Ordinal);

        // Apply the same public terminology to metric selectors and chart configuration used by
        // Performance vs Price, Value Rankings and the shared comparison surfaces.
        html = html.Replace("Tensile flat, MPa", "Tensile Strength, MPa", StringComparison.Ordinal);
        html = html.Replace("Tensile upright, MPa", "Layer Adhesion Strength, MPa", StringComparison.Ordinal);
        html = html.Replace("tensileFlat:'Tensile flat'", "tensileFlat:'Tensile Strength'", StringComparison.Ordinal);
        html = html.Replace("tensileUpright:'Tensile upright'", "tensileUpright:'Layer Adhesion Strength'", StringComparison.Ordinal);
        html = html.Replace("label:'Tensile flat'", "label:'Tensile Strength'", StringComparison.Ordinal);
        html = html.Replace("shortLabel:'Tensile flat'", "shortLabel:'Tensile Strength'", StringComparison.Ordinal);
        html = html.Replace("label:'Tensile upright'", "label:'Layer Adhesion Strength'", StringComparison.Ordinal);
        html = html.Replace("shortLabel:'Tensile upright'", "shortLabel:'Layer Adhesion Strength'", StringComparison.Ordinal);

        const string oldTooltipLabel = "${key==='flat'?'Flat':'Upright'}: ${fmt(val)} ${unit}";
        const string newTooltipLabel = "${target==='tensileChart'?(key==='flat'?'Tensile Strength':'Layer Adhesion Strength'):(key==='flat'?'Flat':'Upright')}: ${fmt(val)} ${unit}${target==='tensileChart'?(key==='flat'?'<br>Measured from flat printed specimens.':'<br>Measured from upright printed specimens.'):''}";
        html = html.Replace(oldTooltipLabel, newTooltipLabel, StringComparison.Ordinal);

        var headClose = html.IndexOf("</head>", StringComparison.OrdinalIgnoreCase);
        const string terminologyCss = "<style id=\"websiteTerminologyStyles\">.legend small{color:#94a3b8;font-size:12px;font-weight:500}</style>";
        html = headClose >= 0 ? html.Insert(headClose, terminologyCss + Environment.NewLine) : terminologyCss + html;
        return marker + Environment.NewLine + html;
    }


    private string InjectExperimentalWebsiteSection(string html)
    {
        const string markerStart = "<!-- 3DP-EXPERIMENTAL-WEBSITE-START -->";
        const string markerEnd = "<!-- 3DP-EXPERIMENTAL-WEBSITE-END -->";
        var existingStart = html.IndexOf(markerStart, StringComparison.Ordinal);
        if (existingStart >= 0)
        {
            var existingEnd = html.IndexOf(markerEnd, existingStart, StringComparison.Ordinal);
            if (existingEnd >= 0) html = html.Remove(existingStart, existingEnd + markerEnd.Length - existingStart);
        }

        var payload = _experimentalWebsiteService.BuildPayload(BuildExperimentalWebsiteInputs());
        var verification = _experimentalWebsiteService.Verify(payload);
        if (!verification.Passed)
            throw new InvalidOperationException("Experimental website payload failed verification: " + string.Join(" ", verification.Errors));
        var section = _experimentalWebsiteService.RenderSection(payload, markerStart, markerEnd);
        var insertion = html.LastIndexOf("</main>", StringComparison.OrdinalIgnoreCase);
        if (insertion < 0) insertion = html.LastIndexOf("</body>", StringComparison.OrdinalIgnoreCase);
        if (insertion < 0) return html + Environment.NewLine + section;
        return html.Insert(insertion, section + Environment.NewLine);
    }

    private IReadOnlyList<ExperimentalWebsiteSeriesInput> BuildExperimentalWebsiteInputs()
    {
        return _materialExperimentRows
            .Where(series => series.IsActive && series.PublishOnWebsite)
            .OrderBy(series => series.ExperimentName, StringComparer.CurrentCultureIgnoreCase)
            .ThenBy(series => series.MaterialDisplayName, StringComparer.CurrentCultureIgnoreCase)
            .Select(series => new ExperimentalWebsiteSeriesInput(
                series.MaterialExperimentId,
                series.MaterialID,
                series.MaterialDisplayName,
                series.ExperimentName,
                series.ParameterUnit,
                series.Notes,
                _experimentalRunRows
                    .Where(run => run.IsActive && string.Equals(run.MaterialExperimentId, series.MaterialExperimentId, StringComparison.OrdinalIgnoreCase))
                    .OrderBy(run => ParseExperimentalSortValue(run.ParameterValue))
                    .ThenBy(run => run.ParameterValue, StringComparer.CurrentCultureIgnoreCase)
                    .Select(run =>
                    {
                        var metrics = GetExperimentalRunMetrics(run.ExperimentalRunId);
                        // Native Experimental Results use Flat as tensile strength and Upright
                        // as layer-adhesion strength. The public payload uses engineering labels.
                        return new ExperimentalWebsiteRunInput(
                            run.ExperimentalRunId,
                            ExperimentalRunLabel(run),
                            run.Status,
                            run.IsBaseline,
                            ParseExperimentalResult(run.ParameterValue),
                            metrics.TensileFlat,
                            metrics.TensileFlatCv,
                            metrics.TensileUpright,
                            metrics.TensileUprightCv,
                            metrics.ImpactFlat,
                            metrics.ImpactFlatCv,
                            metrics.ImpactUpright,
                            metrics.ImpactUprightCv,
                            metrics.Stiffness);
                    })
                    .ToList()))
            .ToList();
    }

    private List<NativeMaterialRow> GetNativeWebsitePipelineRows(IReadOnlyList<DataRow> visibleRows)
    {
        var candidates = GetNativeWebsiteExportCandidateRows();
        if (visibleRows.Count == 0) return candidates;

        var visibleIds = visibleRows
            .Select(row => GetCell(row, "Material ID", "MaterialID")?.Trim())
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

        if (visibleIds.Count == 0) return candidates;

        // The website pipeline is always bounded by native export candidates. A filtered
        // canonical Materials projection may narrow that set, but can never introduce a
        // row that is not owned by the active native MaterialID universe.
        var candidateIds = candidates
            .Select(row => row.MaterialID?.Trim() ?? string.Empty)
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .ToList();

        var visibleViewIsStale = candidateIds.Count > visibleIds.Count ||
                                 candidateIds.Any(id => !visibleIds.Contains(id));

        if (visibleViewIsStale)
        {
            return candidates;
        }

        var filtered = candidates
            .Where(row => visibleIds.Contains(row.MaterialID?.Trim() ?? string.Empty))
            .ToList();

        return filtered.Count > 0 ? filtered : candidates;
    }

    private Dictionary<string, MaterialResults> BuildVerifiedMaterialSummaryMap(IReadOnlyList<NativeMaterialRow> materialRows)
    {
        var summaries = new Dictionary<string, MaterialResults>(StringComparer.OrdinalIgnoreCase);

        var tensileByMaterialId = _nativeTensileRows
            .Where(row => !string.IsNullOrWhiteSpace(row.MaterialID))
            .GroupBy(row => row.MaterialID.Trim(), StringComparer.OrdinalIgnoreCase)
            .ToDictionary(group => group.Key, group => group.First(), StringComparer.OrdinalIgnoreCase);
        var impactByMaterialId = _nativeImpactRows
            .Where(row => !string.IsNullOrWhiteSpace(row.MaterialID))
            .GroupBy(row => row.MaterialID.Trim(), StringComparer.OrdinalIgnoreCase)
            .ToDictionary(group => group.Key, group => group.First(), StringComparer.OrdinalIgnoreCase);
        var stiffnessByMaterialId = _nativeStiffnessRows
            .Where(row => !string.IsNullOrWhiteSpace(row.MaterialID))
            .GroupBy(row => row.MaterialID.Trim(), StringComparer.OrdinalIgnoreCase)
            .ToDictionary(group => group.Key, group => group.First(), StringComparer.OrdinalIgnoreCase);

        var tensileArea = GetNativeTensileCrossSectionArea();
        var impactAngle = GetNativeImpactNoSampleAngle();
        var impactArea = GetNativeImpactCrossSectionAreaM2();
        var maxImpact = GetNativeImpactMaxPossibleImpact();
        var stiffnessMmPerRevolution = GetNativeStiffnessMmPerRevolution();
        var stiffnessSpan = GetNativeStiffnessSpanLength();
        var stiffnessLoad = GetNativeStiffnessLoad();
        var stiffnessSecondMoment = GetNativeStiffnessSecondMomentOfArea();

        foreach (var material in materialRows)
        {
            var materialId = material.MaterialID?.Trim() ?? string.Empty;
            if (string.IsNullOrWhiteSpace(materialId)) continue;

            tensileByMaterialId.TryGetValue(materialId, out var tensileRow);
            impactByMaterialId.TryGetValue(materialId, out var impactRow);
            stiffnessByMaterialId.TryGetValue(materialId, out var stiffnessRow);

            var tensileResults = tensileRow is null
                ? null
                : _resultsService.CalculateTensile(tensileRow.SampleValues(true), tensileRow.SampleValues(false), tensileArea);
            var impactResults = impactRow is null
                ? null
                : _resultsService.CalculateImpact(impactRow.SampleValues(true), impactRow.SampleValues(false), impactAngle, impactArea, maxImpact);
            var stiffnessResults = stiffnessRow is null
                ? null
                : _resultsService.CalculateStiffness(stiffnessRow.Revolutions, stiffnessRow.Degrees, stiffnessMmPerRevolution, stiffnessSpan, stiffnessLoad, stiffnessSecondMoment);

            summaries[materialId] = _resultsService.CalculateMaterialResults(materialId, tensileResults, impactResults, stiffnessResults);
        }

        return summaries;
    }

    private Dictionary<string, object?> BuildWebsiteTemplateCommonFields(NativeMaterialRow row)
    {
        var materialId = row.MaterialID?.Trim() ?? string.Empty;
        var category = row.MaterialCategory?.Trim() ?? string.Empty;
        var baseMaterial = row.BaseMaterial?.Trim() ?? string.Empty;
        var variant = EmptyToNull(row.VariantFinish);
        var reinforcement = EmptyToNull(row.Reinforcement);
        var color = row.Color?.Trim() ?? string.Empty;
        var manufacturer = row.Manufacturer?.Trim() ?? string.Empty;
        var productLine = row.ProductLine?.Trim() ?? string.Empty;
        var marketingName = EmptyToNull(row.MarketingName);
        var brand = JoinNonEmpty(" ", manufacturer, productLine);
        var label = !string.IsNullOrWhiteSpace(row.WebsiteDisplayName) ? row.WebsiteDisplayName.Trim() : JoinNonEmpty(" ", manufacturer, productLine, baseMaterial, color);
        var youtubeUrl = EmptyToNull(row.YouTubeReviewUrl);
        var productUrl = EmptyToNull(row.ManufacturerWebsite);
        var publicSegment = PublicReportPublishingService.SafeMaterialIdSegment(materialId);
        var publicSelected = row.PublishPublicReports && !string.IsNullOrWhiteSpace(publicSegment);
        var publicFamilyCount = _nativeMaterialRows.Count(item => !item.IsArchived && item.PublishPublicReports && string.Equals(item.BaseMaterial?.Trim(), baseMaterial, StringComparison.CurrentCultureIgnoreCase));
        var publicComparisonSlug = publicFamilyCount >= 2 && !string.IsNullOrWhiteSpace(baseMaterial)
            ? "material-family-" + PublicComparisonReportPublishingService.SafeSlug(baseMaterial)
            : null;

        return new Dictionary<string, object?>
        {
            ["materialId"] = materialId,
            ["category"] = category,
            ["baseMaterial"] = baseMaterial,
            ["variant"] = variant,
            ["reinforcement"] = reinforcement,
            ["type"] = baseMaterial,
            ["color"] = color,
            ["manufacturer"] = manufacturer,
            ["productLine"] = productLine,
            ["marketingName"] = marketingName,
            ["brand"] = string.IsNullOrWhiteSpace(brand) ? manufacturer : brand,
            ["label"] = label,
            ["youtubeUrl"] = youtubeUrl,
            ["overall"] = label,
            ["productUrl"] = productUrl,
            ["publicReportUrl"] = publicSelected ? $"reports/materials/{publicSegment}/index.html" : null,
            ["publicReportPdfUrl"] = publicSelected ? $"reports/materials/{publicSegment}/report.pdf" : null,
            ["publicRecommendationUrl"] = publicSelected ? $"reports/printing-recommendations/{publicSegment}/index.html" : null,
            ["publicTestSessionUrl"] = publicSelected ? $"reports/test-sessions/{publicSegment}/index.html" : null,
            ["publicManufacturerReportUrl"] = publicSelected && !string.IsNullOrWhiteSpace(manufacturer) ? $"reports/manufacturers/{PublicComparisonReportPublishingService.SafeSlug(manufacturer)}/index.html" : null,
            ["publicComparisonReportUrl"] = publicSelected && publicComparisonSlug is not null ? $"reports/comparisons/{publicComparisonSlug}/index.html" : null,
            ["msrpUsd"] = NumberValue(row.MsrpUsd),
            ["landedCostUsd"] = NumberValue(row.LandedCostUsd),
            ["msrpUsdPerKg"] = NumberValue(row.MsrpUsdPerKg),
            ["landedCostUsdPerKg"] = NumberValue(row.LandedCostUsdPerKg),
            ["priceCheckedDate"] = EmptyToNull(row.PriceCheckedDate),
            ["pricingStatus"] = GetPricingStatus(row)
        };
    }

    private static string GetPricingStatus(NativeMaterialRow row)
    {
        var hasMsrp = NumberValue(row.MsrpUsd).HasValue;
        var hasLanded = NumberValue(row.LandedCostUsd).HasValue;
        var hasWeight = NumberValue(row.SpoolWeightG) is > 0;
        return hasMsrp && hasLanded && hasWeight ? "Complete" : "Incomplete";
    }

    private static double? NumberValue(double? value)
    {
        return value.HasValue && double.IsFinite(value.Value) ? value.Value : null;
    }

    private static double? NumberValue(int? value)
    {
        return value.HasValue ? value.Value : null;
    }

    private static string? EmptyToNull(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim();

    private static double? NumberValue(string? value)
    {
        if (string.IsNullOrWhiteSpace(value)) return null;
        return TryParseDecimalAware(value, out var number) && double.IsFinite(number) ? number : null;
    }

