    {
        var active = _database.GetActiveWebsiteTemplate();
        return $"SQLite active template: {active.TemplateVersion} | {active.SourceFileName} | SHA-256 {active.ContentHash[..Math.Min(12, active.ContentHash.Length)]}…";
    }

    private static bool HasManufacturerRedirectTarget(string html, string redirectTarget, string canonicalTarget)
    {
        return html.Contains($"http-equiv=\"refresh\" content=\"0; url={redirectTarget}\"", StringComparison.Ordinal) &&
               html.Contains($"window.location.replace(\"{redirectTarget}\")", StringComparison.Ordinal) &&
               html.Contains($"<a href=\"{redirectTarget}\"", StringComparison.Ordinal) &&
               html.Contains($"rel=\"canonical\" href=\"{canonicalTarget}\"", StringComparison.Ordinal);
    }

    private static string BuildManufacturerRedirectHtml(bool isProduction)
    {
        var target = isProduction ? "../index.html#manufacturers" : "../index-test.html#manufacturers";
        const string canonicalTarget = "https://iskort.is/3dp/index.html#manufacturers";
        return $$"""
            <!doctype html>
            <html lang="en">
            <head>
              <meta charset="utf-8">
              <meta name="viewport" content="width=device-width, initial-scale=1">
              <meta http-equiv="refresh" content="0; url={{target}}">
              <link rel="canonical" href="{{canonicalTarget}}">
              <title>Manufacturers | 3DPIceland Engineering Platform</title>
              <script>window.location.replace("{{target}}");</script>
            </head>
            <body>
              <p>The Manufacturers portal has moved to <a href="{{target}}">the 3DPIceland Engineering Platform</a>.</p>
            </body>
            </html>
            """;
    }

    private string BuildWebsiteExportManifest(IReadOnlyList<NativeMaterialRow> exportRows, int legacyProjectionCount, string htmlPath, string manufacturerRedirectPath, DateTime generatedAt, string templateSource, bool isProduction, string backupPath, string manufacturerRedirectBackupPath, PublicReportWebsiteStageResult? reportStage = null)
    {
        var sb = new StringBuilder();
        sb.AppendLine(isProduction ? "3DP Iceland Labs Website Export Production Manifest" : "3DP Iceland Labs Website Export Preview Manifest");
        sb.AppendLine("Version: " + BuildInfo.ShortLabel + " - " + BuildInfo.ReleaseTitle);
        sb.AppendLine($"Generated: {generatedAt:yyyy-MM-dd HH:mm:ss}");
        sb.AppendLine($"Template source: {templateSource}");
        sb.AppendLine($"Output HTML: {htmlPath}");
        sb.AppendLine($"Manufacturers redirect: {manufacturerRedirectPath} -> {(isProduction ? "../index.html#manufacturers" : "../index-test.html#manufacturers")}");
        sb.AppendLine($"Methodology whitepaper: {System.IO.Path.Combine(System.IO.Path.GetDirectoryName(htmlPath) ?? string.Empty, DocumentationEngineService.WhitepaperFileName)}");
        sb.AppendLine($"Materials exported to DATA block: {exportRows.Count}");
        sb.AppendLine($"Legacy projection rows (informational): {legacyProjectionCount}");
        if (reportStage is not null)
        {
            sb.AppendLine($"Public reports portal: {reportStage.PortalPath}");
            sb.AppendLine($"Public report catalog entries staged: {reportStage.CatalogEntries}");
            sb.AppendLine($"Public MaterialIDs staged: {reportStage.PublicMaterials}");
        }
        sb.AppendLine();
        sb.AppendLine("Safety:");
        if (isProduction)
        {
            sb.AppendLine("- Created production index.html after confirmation.");
            sb.AppendLine(string.IsNullOrWhiteSpace(backupPath) ? "- No previous index.html existed, so no backup was needed." : $"- Previous index.html backup: {backupPath}");
            sb.AppendLine(string.IsNullOrWhiteSpace(manufacturerRedirectBackupPath) ? "- No previous manufacturers/index.html existed, so no redirect backup was needed." : $"- Previous manufacturers/index.html backup: {manufacturerRedirectBackupPath}");
            sb.AppendLine($"- Catalog-driven FTPS handoff allowlist: {WebsiteProductionPublishPlanService.FileName}");
        }
        else
        {
            sb.AppendLine("- Created index-test.html only.");
            sb.AppendLine("- Created manufacturers/index-test.html redirect only.");
            sb.AppendLine("- Production index.html and manufacturers/index.html were not overwritten.");
        }
        sb.AppendLine("- Explicit FTPS publishing is available only through the separate guarded Website Test or Production actions.");
        sb.AppendLine("- Public report artifacts are staged locally; the current FTPS action remains unchanged until the Production publish plan receives runtime acceptance.");
        return sb.ToString();
    }

    private static string ReplaceManufacturerStatsBlock(
        string template,
        int materialCount,
        int manufacturerCount,
        int familyCount,
        int linkedVideoCount)
    {
        var statsStart = template.IndexOf("<div class=\"stats\">", StringComparison.OrdinalIgnoreCase);
        if (statsStart < 0)
        {
            return template;
        }

        var headerEnd = template.IndexOf("</header>", statsStart, StringComparison.OrdinalIgnoreCase);
        if (headerEnd < 0)
        {
            return template;
        }

        var statsEnd = template.LastIndexOf("</div>", headerEnd, StringComparison.OrdinalIgnoreCase);
        if (statsEnd <= statsStart)
        {
            return template;
        }

        var statsHtml = new StringBuilder();
        statsHtml.AppendLine("<div class=\"stats\">");
        statsHtml.AppendLine($"    <div class=\"stat\"><span>Materials in database</span><strong>{materialCount}</strong></div>");
        statsHtml.AppendLine($"    <div class=\"stat\"><span>Manufacturers represented</span><strong>{manufacturerCount}</strong></div>");
        statsHtml.AppendLine($"    <div class=\"stat\"><span>Material families</span><strong>{familyCount}</strong></div>");
        statsHtml.AppendLine($"    <div class=\"stat\"><span>Linked review videos</span><strong>{linkedVideoCount}</strong></div>");
        statsHtml.Append("  </div>");

        return template[..statsStart] + statsHtml + template[(statsEnd + 6)..];
    }

    private static bool IsWebsiteTestedMaterial(DataRow row)
    {
        if (IsTruthy(DataTableHelpers.FirstValue(row, "Tested", "Test Status", "Is Tested", "Available on Website"))) return true;
        return HasAnyValue(row, "Website Display Name", "Material Key", "Slug", "Product Page", "Product URL", "YouTube Review URL", "YouTube URL");
    }

    private static int CountManufacturers(IReadOnlyList<DataRow> rows)
    {
        return rows
            .Select(row => GetCell(row, "Manufacturer", "Brand")?.Trim())
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Count();
    }

    private static string MaterialDisplayName(DataRow row)
    {
        var direct = GetCell(row, "Display Name", "Material Name", "Name");
        if (!string.IsNullOrWhiteSpace(direct)) return direct;

        var manufacturer = GetCell(row, "Manufacturer", "Brand");
        var product = GetCell(row, "Product Line", "ProductLine", "Product");
        var type = GetCell(row, "Base Material", "Material Type", "Type");
        var color = GetCell(row, "Color", "Colour");
        var label = string.Join(" ", new[] { manufacturer, product, type, color }.Where(value => !string.IsNullOrWhiteSpace(value)));
        return string.IsNullOrWhiteSpace(label) ? GetCell(row, "Material ID") : label;
    }

    private static string GetCell(DataRow row, params string[] names)
    {
        foreach (var name in names)
        {
            if (row.Table.Columns.Contains(name)) return row[name]?.ToString()?.Trim() ?? string.Empty;
        }
        return string.Empty;
    }

    private static string Html(string? value)
    {
        if (string.IsNullOrWhiteSpace(value)) return string.Empty;
        return value
            .Replace("&", "&amp;")
            .Replace("<", "&lt;")
            .Replace(">", "&gt;")
            .Replace("\"", "&quot;")
            .Replace("'", "&#39;");
    }


