    private void RefreshReportPreview_Click(object sender, RoutedEventArgs e) => RefreshReportPreview();

    private async void ExportPdfReport_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            AutomationRuntimeProfile.DemandReportGenerationAuthorized();
            var selectedReportKey = (ReportTypeSelector?.SelectedItem as ComboBoxItem)?.Tag?.ToString() ?? string.Empty;
            if (!_purchasingReportService.IsPurchasingReport(selectedReportKey) && !HasCanonicalMaterialReportData())
            {
                ReportPreviewLog.Text = "No material data is loaded. Add or import materials before exporting engineering reports.";
                ReportExportSummaryText.Text = "No data loaded";
                return;
            }

            var folder = ReportOutputFolderBox.Text?.Trim();
            if (string.IsNullOrWhiteSpace(folder))
            {
                folder = GetDefaultReportOutputFolder();
                ReportOutputFolderBox.Text = folder;
            }
            Directory.CreateDirectory(folder);
            var generatedAt = DateTime.Now;
            var report = BuildReportFoundation(generatedAt);
            var packageFolder = CreateReportPackageFolder(folder, report, generatedAt);
            await WriteReportPackageArtifactsAsync(packageFolder, report, generatedAt);

            var htmlPath = System.IO.Path.Combine(packageFolder, "report.html");
            var pdfPath = System.IO.Path.Combine(packageFolder, "report.pdf");
            var txtPath = System.IO.Path.Combine(packageFolder, "report.txt");
            var manifestPath = System.IO.Path.Combine(packageFolder, "manifest.txt");
            var metadataPath = System.IO.Path.Combine(packageFolder, "report-metadata.json");
            var assetsFolder = System.IO.Path.Combine(packageFolder, "assets");

            ReportExportSummaryText.Text = $"Exported current report: {System.IO.Path.GetFileName(packageFolder)}";
            ReportPreviewLog.Text = report.Text + $"\n\nCurrent report exported:\n- Report folder: {packageFolder}\n- Canonical HTML: {htmlPath}\n- PDF printed from that HTML: {pdfPath}\n- Text summary: {txtPath}\n- Manifest: {manifestPath}\n- Metadata: {metadataPath}\n- Assets: {assetsFolder}";
        }
        catch (Exception ex)
        {
            ReportPreviewLog.Text += $"\n\nPDF export failed: {ex.Message}";
        }
    }

    private async Task WriteReportPackageArtifactsAsync(string packageFolder, ReportFoundationResult report, DateTime generatedAt)
    {
        Directory.CreateDirectory(packageFolder);
        var assetsFolder = System.IO.Path.Combine(packageFolder, "assets");
        Directory.CreateDirectory(assetsFolder);
        CopyReportPackageAssets(assetsFolder);

        var htmlPath = System.IO.Path.Combine(packageFolder, "report.html");
        var pdfPath = System.IO.Path.Combine(packageFolder, "report.pdf");
        var txtPath = System.IO.Path.Combine(packageFolder, "report.txt");
        var manifestPath = System.IO.Path.Combine(packageFolder, "manifest.txt");
        var metadataPath = System.IO.Path.Combine(packageFolder, "report-metadata.json");

        SafeFileOperations.WriteAllTextAtomic(htmlPath, report.Html, Encoding.UTF8);
        SafeFileOperations.WriteAllTextAtomic(txtPath, report.Text, Encoding.UTF8);
        await WriteReportPdfFromCanonicalHtmlAsync(pdfPath, htmlPath);
        SafeFileOperations.WriteAllTextAtomic(manifestPath, BuildReportManifest(report, pdfPath, htmlPath, generatedAt, packageFolder, assetsFolder, metadataPath), Encoding.UTF8);
        SafeFileOperations.WriteAllTextAtomic(metadataPath, BuildReportMetadataJson(report, generatedAt, packageFolder, htmlPath, txtPath, pdfPath), Encoding.UTF8);
    }

    private async void BuildPublicMaterialReportPreview_Click(object sender, RoutedEventArgs e)
    {
        await BuildPublicMaterialReportPreviewAsync();
    }

    private async Task BuildPublicMaterialReportPreviewAsync()
    {
        if (BuildPublicMaterialReportPreviewButton is not null) BuildPublicMaterialReportPreviewButton.IsEnabled = false;

        try
        {
            AutomationRuntimeProfile.DemandReportGenerationAuthorized();
            var selectedMaterials = _nativeMaterialRows
                .Where(row => !row.IsArchived && row.PublishPublicReports && !string.IsNullOrWhiteSpace(row.MaterialID))
                .OrderBy(row => row.WebsiteDisplayName, StringComparer.CurrentCultureIgnoreCase)
                .ThenBy(row => row.MaterialID, StringComparer.OrdinalIgnoreCase)
                .ToList();
            if (selectedMaterials.Count == 0)
            {
                ReportExportSummaryText.Text = "No public materials selected";
                ReportPreviewLog.Text = "Check Public reports for one or more active materials in Materials before building the local public report preview.";
                return;
            }

            var outputFolder = ReportOutputFolderBox.Text?.Trim();
            if (string.IsNullOrWhiteSpace(outputFolder))
            {
                outputFolder = GetDefaultReportOutputFolder();
                ReportOutputFolderBox.Text = outputFolder;
            }

            var generatedAt = DateTime.Now;
            var batch = selectedMaterials
                .Select(row =>
                {
                    var model = BuildPublicMaterialEngineeringReportModel(BuildNativeMaterialDataRow(row));
                    var publication = _publicReportPublishingService.Build(model, generatedAt, BuildInfo.ShortLabel, BuildInfo.ReleaseTitle);
                    var verification = _publicReportPublishingService.Verify(model, publication);
                    return (Model: model, Publication: publication, Verification: verification);
                })
                .ToList();
            var failedVerification = batch.FirstOrDefault(item => !item.Verification.Passed);
            if (failedVerification.Model is not null)
                throw new InvalidOperationException($"Public report safety verification failed for {failedVerification.Model.MaterialId}: {failedVerification.Verification.Detail}");

            var previewRoot = System.IO.Path.Combine(outputFolder, PublicReportPublishingService.PreviewRootFolderName);
            var previewIndexPath = System.IO.Path.Combine(previewRoot, "materials.html");
            var legacyPreviewIndexPath = System.IO.Path.Combine(previewRoot, "index.html");
            var createdPaths = new List<string>();

            foreach (var item in batch)
            {
                var relativeParts = item.Publication.RelativeDirectory.Split('/', StringSplitOptions.RemoveEmptyEntries);
                var materialFolder = relativeParts.Aggregate(previewRoot, System.IO.Path.Combine);
                var assetsFolder = System.IO.Path.Combine(materialFolder, "assets");
                Directory.CreateDirectory(assetsFolder);
                CopyReportPackageAssets(assetsFolder);

                var htmlPath = System.IO.Path.Combine(materialFolder, "index.html");
                var pdfPath = System.IO.Path.Combine(materialFolder, "report.pdf");
                var manifestPath = System.IO.Path.Combine(materialFolder, "manifest.txt");
                var metadataPath = System.IO.Path.Combine(materialFolder, "report-metadata.json");

                SafeFileOperations.WriteAllTextAtomic(htmlPath, item.Publication.Html, Encoding.UTF8);
                SafeFileOperations.WriteAllTextAtomic(manifestPath, item.Publication.Manifest, Encoding.UTF8);
                SafeFileOperations.WriteAllTextAtomic(metadataPath, item.Publication.MetadataJson, Encoding.UTF8);
                if (File.Exists(pdfPath)) File.Delete(pdfPath);
                await WriteReportPdfFromCanonicalHtmlAsync(pdfPath, htmlPath);
                createdPaths.Add($"- {item.Model.MaterialId}: {item.Publication.RelativeDirectory}/");
            }

            var previewIndexHtml = PublicReportPublishingService.BuildPreviewIndex(batch.Select(item => item.Model), generatedAt);
            SafeFileOperations.WriteAllTextAtomic(previewIndexPath, previewIndexHtml, Encoding.UTF8);
            if (!File.Exists(legacyPreviewIndexPath) || !File.ReadAllText(legacyPreviewIndexPath).Contains(PublicEngineeringReportPackageService.PortfolioMarker, StringComparison.Ordinal))
                SafeFileOperations.WriteAllTextAtomic(legacyPreviewIndexPath, previewIndexHtml, Encoding.UTF8);

            ReportExportSummaryText.Text = $"Public previews built: {batch.Count} materials";
            ReportPreviewLog.Text =
                $"Public Material Engineering Report previews built successfully for {batch.Count} selected materials.\n\n" +
                string.Join("\n", createdPaths) + "\n\n" +
                $"Combined preview index: {previewIndexPath}\n" +
                "Each material folder contains canonical index.html, report.pdf printed from that HTML, metadata, manifest and assets.\n\n" +
                "Safety contract: only allowlisted public fields were supplied to the renderer. Purchasing, operational stock data, credentials, device paths, raw specimen rows and internal notes were not supplied.\n\n" +
                "This is a local preview only. Nothing was uploaded to the production website.";
        }
        catch (Exception ex)
        {
            ReportExportSummaryText.Text = "Public preview failed";
            ReportPreviewLog.Text += "\n\nPublic report preview failed: " + ex.Message;
        }
        finally
        {
            if (BuildPublicMaterialReportPreviewButton is not null) BuildPublicMaterialReportPreviewButton.IsEnabled = true;
        }
    }

    private async void BuildPublicComparisonReportPreview_Click(object sender, RoutedEventArgs e)
    {
        await BuildPublicComparisonReportPreviewAsync();
    }

    private async Task BuildPublicComparisonReportPreviewAsync()
    {
        if (BuildPublicComparisonReportPreviewButton is not null) BuildPublicComparisonReportPreviewButton.IsEnabled = false;
        try
        {
            AutomationRuntimeProfile.DemandReportGenerationAuthorized();
            var publicRows = _nativeMaterialRows
                .Where(row => !row.IsArchived && row.PublishPublicReports && !string.IsNullOrWhiteSpace(row.MaterialID))
                .Select(BuildNativeMaterialDataRow)
                .ToList();
            var models = publicRows
                .Select(BuildPublicMaterialEngineeringReportModel)
                .Where(model => !string.IsNullOrWhiteSpace(model.BaseMaterial))
                .GroupBy(model => model.BaseMaterial.Trim(), StringComparer.CurrentCultureIgnoreCase)
                .Where(group => group.Count() >= 2)
                .Select(group => new PublicComparisonReportModel
                {
                    PresetSlug = "material-family-" + PublicComparisonReportPublishingService.SafeSlug(group.Key),
                    Title = group.Key + " Material Family Comparison",
                    BaseMaterial = group.Key,
                    ScopeDescription = $"Stable Material Family preset for {group.Key}. Every included MaterialID has explicit Public reports opt-in.",
                    Materials = group
                        .OrderByDescending(item => PublicComparisonScore(item.OverallScore) ?? double.MinValue)
                        .ThenBy(item => item.MaterialName, StringComparer.CurrentCultureIgnoreCase)
                        .Select(item => new PublicComparisonMaterialModel
                        {
                            MaterialId = item.MaterialId, MaterialName = item.MaterialName, Manufacturer = item.Manufacturer, ProductLine = item.ProductLine,
                            BaseMaterial = item.BaseMaterial, Reinforcement = item.Reinforcement, TestCoverage = item.TestCoverage,
                            VerifiedEngineeringAxes = item.VerifiedEngineeringAxes, OverallScore = item.OverallScore,
                            TensileScore = item.TensileScore, ImpactScore = item.ImpactScore, StiffnessScore = item.StiffnessScore,
                            ConsistencyScore = item.ConsistencyScore, LayerAdhesionScore = item.LayerAdhesionScore, MsrpUsdPerKg = item.MsrpUsdPerKg
                        }).ToList()
                })
                .OrderBy(model => model.Title, StringComparer.CurrentCultureIgnoreCase)
                .ToList();
            if (models.Count == 0)
            {
                ReportExportSummaryText.Text = "No public comparison presets available";
                ReportPreviewLog.Text = "A Material Family public comparison requires at least two active materials in the same base-material family with Public reports checked.";
                return;
            }

            var generatedAt = DateTime.Now;
            var outputFolder = string.IsNullOrWhiteSpace(ReportOutputFolderBox.Text) ? GetDefaultReportOutputFolder() : ReportOutputFolderBox.Text.Trim();
            ReportOutputFolderBox.Text = outputFolder;
            var previewRoot = System.IO.Path.Combine(outputFolder, PublicReportPublishingService.PreviewRootFolderName);
            var publications = models.Select(model =>
            {
                var publication = _publicComparisonReportPublishingService.Build(model, generatedAt, BuildInfo.ShortLabel, BuildInfo.ReleaseTitle);
                var verification = _publicComparisonReportPublishingService.Verify(model, publication);
                if (!verification.Passed) throw new InvalidOperationException($"Public comparison verification failed for {model.PresetSlug}: {verification.Detail}");
                return (Model: model, Publication: publication);
            }).ToList();

            foreach (var item in publications)
            {
                var folder = item.Publication.RelativeDirectory.Split('/', StringSplitOptions.RemoveEmptyEntries).Aggregate(previewRoot, System.IO.Path.Combine);
                var assets = System.IO.Path.Combine(folder, "assets");
                Directory.CreateDirectory(assets);
                CopyReportPackageAssets(assets);
                var htmlPath = System.IO.Path.Combine(folder, "index.html");
                SafeFileOperations.WriteAllTextAtomic(htmlPath, item.Publication.Html, Encoding.UTF8);
                SafeFileOperations.WriteAllTextAtomic(System.IO.Path.Combine(folder, "manifest.txt"), item.Publication.Manifest, Encoding.UTF8);
                SafeFileOperations.WriteAllTextAtomic(System.IO.Path.Combine(folder, "report-metadata.json"), item.Publication.MetadataJson, Encoding.UTF8);
                await WriteReportPdfFromCanonicalHtmlAsync(System.IO.Path.Combine(folder, "report.pdf"), htmlPath);
            }
            Directory.CreateDirectory(previewRoot);
            SafeFileOperations.WriteAllTextAtomic(System.IO.Path.Combine(previewRoot, "comparisons.html"), PublicComparisonReportPublishingService.BuildPreviewIndex(models, generatedAt), Encoding.UTF8);
            ReportExportSummaryText.Text = $"Public comparison previews built: {models.Count}";
            var generatedRoutes = string.Join("\n", publications.Select(item =>
                $"- {item.Model.BaseMaterial}: {item.Model.Materials.Count} materials -> {item.Publication.RelativeDirectory}/index.html"));
            ReportPreviewLog.Text = $"Built {models.Count} stable Material Family comparison presets from {publicRows.Count} explicitly allowlisted MaterialIDs.\n\nGenerated material types:\n{generatedRoutes}\n\nIndex: {System.IO.Path.Combine(previewRoot, "comparisons.html")}\n\nCanonical HTML, PDF, metadata, manifest and assets were created locally. Nothing was uploaded.";
        }
        catch (Exception ex)
        {
            ReportExportSummaryText.Text = "Public comparison preview failed";
            ReportPreviewLog.Text += "\n\nPublic comparison preview failed: " + ex.Message;
        }
        finally
        {
            if (BuildPublicComparisonReportPreviewButton is not null) BuildPublicComparisonReportPreviewButton.IsEnabled = true;
        }
    }

    private static double? PublicComparisonScore(string? value)
    {
        var match = Regex.Match(value ?? string.Empty, @"-?\d+(?:[.,]\d+)?", RegexOptions.CultureInvariant);
        return match.Success && double.TryParse(match.Value.Replace(',', '.'), NumberStyles.Float, CultureInfo.InvariantCulture, out var parsed) ? parsed : null;
    }

    private async void BuildPublicManufacturerReportPreview_Click(object sender, RoutedEventArgs e)
