    private async void BuildPublicMaterialSummaryPreview_Click(object sender, RoutedEventArgs e)
    {
        await BuildPublicMaterialSummaryPreviewAsync();
    }

    private async Task BuildPublicMaterialSummaryPreviewAsync()
    {
        if (BuildPublicMaterialSummaryPreviewButton is not null) BuildPublicMaterialSummaryPreviewButton.IsEnabled = false;
        try
        {
            AutomationRuntimeProfile.DemandReportGenerationAuthorized();
            var summaries = GetCanonicalVerifiedSummaryMap();
            var source = _nativeMaterialRows
                .Where(row => !row.IsArchived && row.PublishPublicReports && !string.IsNullOrWhiteSpace(row.MaterialID))
                .Select(row =>
                {
                    var dataRow = BuildNativeMaterialDataRow(row);
                    var material = BuildPublicMaterialEngineeringReportModel(dataRow);
                    summaries.TryGetValue(material.MaterialId, out var summary);
                    return (Material: material, Summary: summary);
                })
                .OrderBy(item => item.Material.BaseMaterial)
                .ThenBy(item => item.Material.MaterialName)
                .ToList();

            if (source.Count == 0)
            {
                ReportPreviewLog.Text = "Select one or more active MaterialIDs with Public reports before building the public Material Summary.";
                return;
            }

            string Coverage(int count) => source.Count == 0 ? "0%" : ((double)count / source.Count * 100).ToString("0.#", CultureInfo.CurrentCulture) + "%";
            var complete = source.Count(item => item.Summary?.IsCompleteEngineeringSummary == true);
            var tested = source.Count(item => item.Summary?.HasAnyResults == true);
            var model = new PublicMaterialSummaryReportModel
            {
                PublicMaterials = source.Count,
                FullyTested = complete,
                PartiallyTested = Math.Max(0, tested - complete),
                NoTestResults = Math.Max(0, source.Count - tested),
                Manufacturers = source.Select(item => item.Material.Manufacturer).Where(value => !string.IsNullOrWhiteSpace(value)).Distinct(StringComparer.CurrentCultureIgnoreCase).Count(),
                MaterialTypes = source.Select(item => item.Material.BaseMaterial).Where(value => !string.IsNullOrWhiteSpace(value)).Distinct(StringComparer.CurrentCultureIgnoreCase).Count(),
                MaterialsWithResults = tested,
                Coverage = new[]
                {
                    ("Tensile", source.Count(item => item.Summary?.HasTensileResults == true)),
                    ("Impact", source.Count(item => item.Summary?.HasImpactResults == true)),
                    ("Stiffness", source.Count(item => item.Summary?.HasStiffnessResults == true)),
                    ("Consistency score available", source.Count(item => PublicComparisonScore(item.Material.ConsistencyScore).HasValue)),
                    ("Layer adhesion score available", source.Count(item => PublicComparisonScore(item.Material.LayerAdhesionScore).HasValue))
                }.Select(item => new PublicSummaryCoverageModel { Module = item.Item1, Materials = item.Item2, Coverage = Coverage(item.Item2) }).ToList(),
                MaterialTypeDistribution = source.GroupBy(item => DisplayText(item.Material.BaseMaterial), StringComparer.CurrentCultureIgnoreCase).Select(group => new PublicSummaryDistributionModel { Label = group.Key, Materials = group.Count() }).OrderByDescending(item => item.Materials).ThenBy(item => item.Label).ToList(),
                ManufacturerDistribution = source.GroupBy(item => DisplayText(item.Material.Manufacturer), StringComparer.CurrentCultureIgnoreCase).Select(group => new PublicSummaryDistributionModel { Label = group.Key, Materials = group.Count() }).OrderByDescending(item => item.Materials).ThenBy(item => item.Label).ToList(),
                Materials = source.Select(item => new PublicMaterialSummaryRowModel
                {
                    MaterialId = item.Material.MaterialId,
                    MaterialName = item.Material.MaterialName,
                    Manufacturer = item.Material.Manufacturer,
                    BaseMaterial = item.Material.BaseMaterial,
                    TestCoverage = item.Summary?.SummaryStatus ?? "No native results",
                    EngineeringAxes = item.Material.VerifiedEngineeringAxes,
                    OverallScore = item.Material.OverallScore,
                    TensileScore = item.Material.TensileScore,
                    ImpactScore = item.Material.ImpactScore,
                    StiffnessScore = item.Material.StiffnessScore,
                    ConsistencyScore = item.Material.ConsistencyScore,
                    LayerAdhesionScore = item.Material.LayerAdhesionScore
                }).ToList()
            };

            var at = DateTime.Now;
            var output = string.IsNullOrWhiteSpace(ReportOutputFolderBox.Text) ? GetDefaultReportOutputFolder() : ReportOutputFolderBox.Text.Trim();
            var root = System.IO.Path.Combine(output, PublicReportPublishingService.PreviewRootFolderName);
            var result = _publicMaterialSummaryReportPublishingService.Build(model, at, BuildInfo.ShortLabel, BuildInfo.ReleaseTitle);
            var verification = _publicMaterialSummaryReportPublishingService.Verify(model, result);
            if (!verification.Passed) throw new InvalidOperationException(verification.Detail);
            var folder = result.RelativeDirectory.Split('/', StringSplitOptions.RemoveEmptyEntries).Aggregate(root, System.IO.Path.Combine);
            var assets = System.IO.Path.Combine(folder, "assets");
            Directory.CreateDirectory(assets);
            CopyReportPackageAssets(assets);
            var html = System.IO.Path.Combine(folder, "index.html");
            SafeFileOperations.WriteAllTextAtomic(html, result.Html, Encoding.UTF8);
            SafeFileOperations.WriteAllTextAtomic(System.IO.Path.Combine(folder, "manifest.txt"), result.Manifest, Encoding.UTF8);
            SafeFileOperations.WriteAllTextAtomic(System.IO.Path.Combine(folder, "report-metadata.json"), result.MetadataJson, Encoding.UTF8);
            await WriteReportPdfFromCanonicalHtmlAsync(System.IO.Path.Combine(folder, "report.pdf"), html);
            ReportExportSummaryText.Text = $"Public Material Summary built: {model.PublicMaterials} materials";
            ReportPreviewLog.Text = $"Built the full public Material Summary from {model.PublicMaterials} allowlisted MaterialIDs.\n\nHTML: {html}\n\nLocal preview only. Nothing was uploaded.";
        }
        catch (Exception ex)
        {
            ReportExportSummaryText.Text = "Public Material Summary failed";
            ReportPreviewLog.Text += "\n\n" + ex.Message;
        }
        finally
        {
            if (BuildPublicMaterialSummaryPreviewButton is not null) BuildPublicMaterialSummaryPreviewButton.IsEnabled = true;
        }
    }

    private async void BuildPublicEngineeringReportPackage_Click(object sender, RoutedEventArgs e)
    {
        if (BuildPublicEngineeringReportPackageButton is not null) BuildPublicEngineeringReportPackageButton.IsEnabled = false;
        try
        {
            AutomationRuntimeProfile.DemandReportGenerationAuthorized();
            if (AutomationRuntimeProfile.IsActive)
                ReportOutputFolderBox.Text = AutomationRuntimeProfile.Current!.OutputFolder;
            var result = await EnsurePublicReportPackageAsync(status => ReportExportSummaryText.Text = status);
            ReportExportSummaryText.Text = $"Public report package built: {result.CatalogEntries} catalog entries";
            ReportPreviewLog.Text = FormatPublicReportPackageResult(result);
        }
        catch (Exception ex)
        {
            ReportExportSummaryText.Text = "Public report package failed";
            ReportPreviewLog.Text = ex.Message;
        }
        finally
        {
            if (BuildPublicEngineeringReportPackageButton is not null) BuildPublicEngineeringReportPackageButton.IsEnabled = true;
        }
    }

    private sealed record PublicReportPackageEnsureResult(
        int PublicMaterials,
        int CatalogEntries,
        IReadOnlyList<string> RebuiltTypes,
        bool SourceDataChanged,
        double BuildSeconds,
        IReadOnlyList<string> BuildTimings,
        string IndexPath,
        string ManifestPath,
        string CatalogPath,
        string FingerprintPath)
    {
        public string RebuiltTypesLabel => RebuiltTypes.Count == 0
            ? "none; all artifacts already existed"
            : string.Join(", ", RebuiltTypes);
    }

    private async Task<PublicReportPackageEnsureResult> EnsurePublicReportPackageAsync(Action<string>? progress = null)
    {
        var packageTimer = Stopwatch.StartNew();
        var buildTimings = new List<string>();
        var rebuiltTypes = new List<string>();
        try
        {
            var publicRows = _nativeMaterialRows
                .Where(row => !row.IsArchived && row.PublishPublicReports && !string.IsNullOrWhiteSpace(row.MaterialID))
                .OrderBy(row => row.MaterialID, StringComparer.OrdinalIgnoreCase)
                .ToList();
            if (publicRows.Count == 0)
                throw new InvalidOperationException("Select one or more active MaterialIDs with Public reports before building a website or public report package.");

            PublicReportCatalogEntryModel Entry(string type, string title, string scopeType, string scopeId, string directory) => new()
            {
                ReportType = type,
                Title = title,
                ScopeType = scopeType,
                ScopeId = scopeId,
                Html = directory + "/index.html",
                Pdf = directory + "/report.pdf",
                Metadata = directory + "/report-metadata.json"
            };

            var entries = new List<PublicReportCatalogEntryModel>
            {
                Entry("material-summary", "Public Material Summary", "Dataset", "public-materials", PublicMaterialSummaryReportPublishingService.StableDirectory)
            };

            foreach (var row in publicRows)
            {
                var id = row.MaterialID.Trim();
                var segment = PublicReportPublishingService.SafeMaterialIdSegment(id);
                var title = string.IsNullOrWhiteSpace(row.WebsiteDisplayName) ? id : row.WebsiteDisplayName.Trim();
                entries.Add(Entry("material-engineering", title + " Material Engineering Report", "MaterialID", id, $"reports/materials/{segment}"));
                entries.Add(Entry("test-session", title + " Test Session Report", "MaterialID", id, $"reports/test-sessions/{segment}"));
                entries.Add(Entry("printing-recommendation", title + " Printing Recommendation", "MaterialID", id, $"reports/printing-recommendations/{segment}"));
            }

            var publicMaterialModels = publicRows.Select(row => BuildPublicMaterialEngineeringReportModel(BuildNativeMaterialDataRow(row))).ToList();
            foreach (var family in publicMaterialModels
                         .Select(model => model.BaseMaterial?.Trim() ?? string.Empty)
                         .Where(value => !string.IsNullOrWhiteSpace(value))
                         .GroupBy(value => value, StringComparer.CurrentCultureIgnoreCase)
                         .Where(group => group.Count() >= 2)
                         .Select(group => group.Key)
                         .OrderBy(value => value))
            {
                var slug = "material-family-" + PublicComparisonReportPublishingService.SafeSlug(family);
                entries.Add(Entry("comparison", family + " Material Family Comparison", "Material family", family, $"reports/comparisons/{slug}"));
            }

            foreach (var manufacturer in publicRows
                         .Select(row => row.Manufacturer?.Trim() ?? string.Empty)
                         .Where(value => !string.IsNullOrWhiteSpace(value))
                         .Distinct(StringComparer.CurrentCultureIgnoreCase)
                         .OrderBy(value => value))
            {
                var slug = PublicComparisonReportPublishingService.SafeSlug(manufacturer);
                entries.Add(Entry("manufacturer", manufacturer + " Manufacturer Report", "Manufacturer", manufacturer, $"reports/manufacturers/{slug}"));
            }

            var output = AutomationRuntimeProfile.Current?.OutputFolder ??
                         (string.IsNullOrWhiteSpace(ReportOutputFolderBox.Text)
                             ? GetDefaultReportOutputFolder()
                             : ReportOutputFolderBox.Text.Trim());
            var root = System.IO.Path.Combine(output, PublicReportPublishingService.PreviewRootFolderName);
            var fingerprintPath = System.IO.Path.Combine(root, PublicReportSourceFingerprintService.FileName);
            var canonicalReportProjection = JsonSerializer.Serialize(new
            {
                schema = "3dpiceland.public-report-current-projection.v1",
                materials = publicMaterialModels.OrderBy(model => model.MaterialId, StringComparer.OrdinalIgnoreCase),
                tensile = _nativeTensileRows.OrderBy(row => row.MaterialID, StringComparer.OrdinalIgnoreCase),
                impact = _nativeImpactRows.OrderBy(row => row.MaterialID, StringComparer.OrdinalIgnoreCase),
                stiffness = _nativeStiffnessRows.OrderBy(row => row.MaterialID, StringComparer.OrdinalIgnoreCase)
            });
            var sourceFingerprint = _publicReportSourceFingerprintService.Compute(_database.DatabasePath, publicRows.Select(row => row.MaterialID), canonicalReportProjection);
            var storedFingerprint = _publicReportSourceFingerprintService.ReadFingerprint(fingerprintPath);
            var sourceDataChanged = !PublicReportSourceFingerprintService.Matches(sourceFingerprint, storedFingerprint);
            var initialMissing = await FindMissingPublicReportArtifactsAsync(entries, root);
            var initialMissingSet = initialMissing.ToHashSet(StringComparer.OrdinalIgnoreCase);
            var missingTypes = entries
                .Where(entry => new[] { entry.Html, entry.Pdf, entry.Metadata }.Any(initialMissingSet.Contains))
                .Select(entry => entry.ReportType)
                .Distinct(StringComparer.Ordinal)
                .ToHashSet(StringComparer.Ordinal);
            if (sourceDataChanged)
            {
                missingTypes.UnionWith(entries.Select(entry => entry.ReportType));
                progress?.Invoke(string.IsNullOrWhiteSpace(storedFingerprint)
                    ? "Building public reports for the initial canonical source fingerprint"
                    : "Canonical public report source data changed; rebuilding all report types");
            }

            if (missingTypes.Count > 0)
            {
                progress?.Invoke($"Building {missingTypes.Count} missing or stale public report type(s)");
                var buildOrder = new[]
                {
                    (Type: "material-engineering", Build: (Func<Task>)BuildPublicMaterialReportPreviewAsync),
                    (Type: "comparison", Build: (Func<Task>)BuildPublicComparisonReportPreviewAsync),
                    (Type: "manufacturer", Build: (Func<Task>)BuildPublicManufacturerReportPreviewAsync),
                    (Type: "test-session", Build: (Func<Task>)BuildPublicTestSessionReportPreviewAsync),
                    (Type: "printing-recommendation", Build: (Func<Task>)BuildPublicPrintingRecommendationPreviewAsync),
                    (Type: "material-summary", Build: (Func<Task>)BuildPublicMaterialSummaryPreviewAsync)
                };
                await BeginPublicReportPdfBatchAsync();
                foreach (var item in buildOrder.Where(item => missingTypes.Contains(item.Type)))
                {
                    progress?.Invoke($"Building public {item.Type}");
                    var typeTimer = Stopwatch.StartNew();
                    await item.Build();
                    typeTimer.Stop();
                    buildTimings.Add($"{item.Type}: {typeTimer.Elapsed.TotalSeconds:0.0}s");
                    rebuiltTypes.Add(item.Type);
                }
            }
            else
            {
                progress?.Invoke("Validating existing public report package");
            }

            var missing = await FindMissingPublicReportArtifactsAsync(entries, root);
            if (missing.Count > 0)
                throw new InvalidOperationException($"Automatic report build completed but {missing.Count} artifact(s) are still missing or presentation-stale:\n" + string.Join("\n", missing.Take(20)) + (missing.Count > 20 ? $"\n... and {missing.Count - 20} more" : string.Empty));

            var model = new PublicEngineeringReportPackageModel { PublicMaterials = publicRows.Count, Reports = entries };
            var at = DateTime.Now;
            var package = _publicEngineeringReportPackageService.Build(model, at, BuildInfo.ShortLabel, BuildInfo.ReleaseTitle);
            var verification = _publicEngineeringReportPackageService.Verify(model, package);
            if (!verification.Passed) throw new InvalidOperationException(verification.Detail);

            Directory.CreateDirectory(root);
            var assets = System.IO.Path.Combine(root, "assets");
            Directory.CreateDirectory(assets);
            CopyReportPackageAssets(assets);
            var index = System.IO.Path.Combine(root, "index.html");
            var manifest = System.IO.Path.Combine(root, PublicEngineeringReportPackageService.ManifestFileName);
            var catalog = System.IO.Path.Combine(root, PublicEngineeringReportPackageService.CatalogFileName);
            SafeFileOperations.WriteAllTextAtomic(index, package.IndexHtml, Encoding.UTF8);
            SafeFileOperations.WriteAllTextAtomic(manifest, package.Manifest + $"Source fingerprint metadata: {PublicReportSourceFingerprintService.FileName}\n", Encoding.UTF8);
            SafeFileOperations.WriteAllTextAtomic(catalog, package.CatalogJson, Encoding.UTF8);
            SafeFileOperations.WriteAllTextAtomic(fingerprintPath, _publicReportSourceFingerprintService.BuildMetadataJson(sourceFingerprint, publicRows.Count, at), Encoding.UTF8);
            if (!PublicReportSourceFingerprintService.Matches(sourceFingerprint, _publicReportSourceFingerprintService.ReadFingerprint(fingerprintPath)))
                throw new InvalidOperationException("The canonical public report source fingerprint could not be persisted or verified.");
            packageTimer.Stop();
            return new PublicReportPackageEnsureResult(publicRows.Count, entries.Count, rebuiltTypes, sourceDataChanged, packageTimer.Elapsed.TotalSeconds, buildTimings, index, manifest, catalog, fingerprintPath);
        }
        finally
        {
            EndPublicReportPdfBatch();
        }
    }

    private static string FormatPublicReportPackageResult(PublicReportPackageEnsureResult result) =>
        $"Public Engineering Report Package built successfully.\n\nPublic MaterialIDs: {result.PublicMaterials}\nCatalog entries: {result.CatalogEntries}\nCanonical source data changed: {(result.SourceDataChanged ? "yes; report types were rebuilt" : "no; existing data revision remained current")}\nAutomatically rebuilt report types: {result.RebuiltTypesLabel}\nBatch print engine: {(result.RebuiltTypes.Count == 0 ? "not needed" : "one reusable WebView2 host")}\nArtifact validation: 4 bounded parallel workers\nBuild time: {result.BuildSeconds:0.0}s{(result.BuildTimings.Count == 0 ? string.Empty : "\n" + string.Join("\n", result.BuildTimings))}\nIndex: {result.IndexPath}\nManifest: {result.ManifestPath}\nCatalog: {result.CatalogPath}\nSource fingerprint: {result.FingerprintPath}\n\nAll linked HTML/PDF/metadata artifacts were verified on disk. Local preview only. Nothing was uploaded.";

    private static async Task<IReadOnlyList<string>> FindMissingPublicReportArtifactsAsync(
        IReadOnlyList<PublicReportCatalogEntryModel> entries,
        string root)
    {
        var missing = new ConcurrentBag<string>();
        var artifacts = entries
            .SelectMany(entry => new[] { entry.Html, entry.Pdf, entry.Metadata })
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();
        await Parallel.ForEachAsync(
            artifacts,
            new ParallelOptions { MaxDegreeOfParallelism = 4 },
            async (relative, cancellationToken) =>
            {
                var path = relative.Split('/', StringSplitOptions.RemoveEmptyEntries).Aggregate(root, System.IO.Path.Combine);
                try
                {
                    if (!File.Exists(path) || new FileInfo(path).Length == 0)
                    {
                        missing.Add(relative);
                    }
                    else if (relative.EndsWith(".html", StringComparison.OrdinalIgnoreCase))
                    {
                        var html = await File.ReadAllTextAsync(path, cancellationToken);
                        if (!html.Contains(PublicReportScreenThemeService.Marker, StringComparison.Ordinal)) missing.Add(relative);
                    }
                }
                catch (IOException)
                {
                    missing.Add(relative);
                }
                catch (UnauthorizedAccessException)
                {
                    missing.Add(relative);
                }
            });
        return missing.OrderBy(value => value, StringComparer.OrdinalIgnoreCase).ToList();
    }

    private PublicMaterialEngineeringReportModel BuildPublicMaterialEngineeringReportModel(DataRow row)
    {
        var verifiedSummaries = GetCanonicalVerifiedSummaryMap();
        var video = BuildVideoPlannerRow(row, verifiedSummaries);
        var ranking = BuildRankingRow(video, "Overall");
        var contextRankings = GetCanonicalActiveMaterialRows()
            .Select(source => BuildRankingRow(BuildVideoPlannerRow(source, verifiedSummaries), "Overall"))
            .Where(item => !string.IsNullOrWhiteSpace(item.Label))
            .ToList();
        if (contextRankings.All(item => !string.Equals(item.MaterialId, video.MaterialId, StringComparison.OrdinalIgnoreCase)))
            contextRankings.Add(ranking);
        var materialAverage = AverageRankingRow(
            "Material average - " + DisplayText(ranking.BaseMaterial),
            contextRankings.Where(item => SameText(item.BaseMaterial, ranking.BaseMaterial)));
        var manufacturerAverage = AverageRankingRow(
            "Manufacturer average - " + DisplayText(ranking.Manufacturer),
            contextRankings.Where(item => SameText(item.Manufacturer, ranking.Manufacturer)));
        var best = BestScoredMetric(ranking);
        var weakest = WeakestScoredMetric(ranking);
        var overallRank = BuildMetricRank(ranking.Overall ?? ranking.RankScore, contextRankings.Select(item => item.Overall ?? item.RankScore));
        var betterAlternatives = BuildBetterAlternativeRows(ranking, contextRankings);
        var metricPositions = new[]
        {
            ("Overall", ranking.OverallText, ranking.Overall ?? ranking.RankScore, contextRankings.Select(item => item.Overall ?? item.RankScore)),
            ("Tensile", ranking.TensileText, ranking.Tensile, contextRankings.Select(item => item.Tensile)),
            ("Impact", ranking.ImpactText, ranking.Impact, contextRankings.Select(item => item.Impact)),
            ("Stiffness", ranking.StiffnessText, ranking.Stiffness, contextRankings.Select(item => item.Stiffness)),
            ("Consistency", ranking.ConsistencyText, ranking.Consistency, contextRankings.Select(item => item.Consistency)),
            ("Layer adhesion", ranking.LayerAdhesionText, ranking.LayerAdhesion, contextRankings.Select(item => item.LayerAdhesion))
        }.Select(item =>
        {
            var position = BuildMetricRank(item.Item3, item.Item4);
            return new PublicMetricPositionModel { Metric = item.Item1, Score = item.Item2, Rank = position.RankText, Percentile = position.PercentileText };
        }).ToList();
        var axes = new[]
        {
            ranking.Tensile, ranking.Impact, ranking.Stiffness, ranking.Consistency, ranking.LayerAdhesion
        }.Count(value => value.HasValue);

        return new PublicMaterialEngineeringReportModel
        {
            MaterialId = video.MaterialId,
            MaterialName = video.Label,
            Manufacturer = video.Manufacturer,
            ProductLine = video.ProductLine,
            BaseMaterial = video.BaseMaterial,
            MaterialCategory = video.Category,
            VariantFinish = video.Variant,
            Reinforcement = video.Reinforcement,
            Color = GetCell(row, "Color"),
            TestCoverage = video.VerifiedSummary?.SummaryStatus ?? "No verified results",
            OverallScore = ranking.OverallText,
            TensileScore = ranking.TensileText,
            ImpactScore = ranking.ImpactText,
            StiffnessScore = ranking.StiffnessText,
            ConsistencyScore = ranking.ConsistencyText,
            LayerAdhesionScore = ranking.LayerAdhesionText,
            BestAxis = DisplayText(ranking.BestAxis),
            MsrpUsdPerKg = ranking.PricePerKg?.ToString("0.00", CultureInfo.InvariantCulture) ?? string.Empty,
            ManufacturerWebsite = GetCell(row, "Manufacturer Website", "Website", "Product URL"),
            VideoReviewUrl = GetCell(row, "YouTube Review URL", "Video URL", "YouTube URL"),
            VerifiedEngineeringAxes = axes,
            EngineeringSummary = BuildEngineeringSummaryText(ranking, materialAverage, manufacturerAverage, best.Label, weakest.Label),
            ExecutiveReview = BuildDeterministicEngineeringReviewText(ranking, contextRankings, materialAverage, manufacturerAverage, best.Label, weakest.Label, overallRank.PercentileText),
            BestFeature = best.Label,
            WeakestFeature = weakest.Label,
            OverallRank = overallRank.RankText,
            OverallPercentile = overallRank.PercentileText,
            RecommendedApplications = BuildRecommendedApplications(ranking),
            Strengths = BuildStrengthList(ranking, materialAverage, manufacturerAverage),
            Limitations = BuildWeaknessList(ranking, materialAverage, manufacturerAverage),
            Tradeoffs = BuildEngineeringTradeoffs(ranking, materialAverage, manufacturerAverage),
            MaterialAverage = PublicEngineeringScoreProfileFromRanking(materialAverage),
            ManufacturerAverage = PublicEngineeringScoreProfileFromRanking(manufacturerAverage),
            VerifiedMeasurements = PublicVerifiedMeasurementsFromSummary(video.VerifiedSummary),
            MeasurementDates = BuildPublicMeasurementDateProvenance(video.MaterialId),
            MetricPositions = metricPositions,
            DecisionGuidance = BuildDecisionGuidanceItems(ranking, betterAlternatives.Count),
            BetterAlternatives = betterAlternatives.Select(item => new PublicAlternativeModel
            {
                MaterialId = item.MaterialId,
                MaterialName = item.Label,
                Manufacturer = item.Manufacturer,
                OverallScore = item.OverallText,
                TensileScore = item.TensileText,
                ImpactScore = item.ImpactText
            }).ToList(),
            PeerContext = contextRankings
                .Where(item => !string.Equals(item.MaterialId, video.MaterialId, StringComparison.OrdinalIgnoreCase))
                .Where(item => SameText(item.BaseMaterial, video.BaseMaterial))
                .OrderByDescending(item => item.Overall ?? item.RankScore ?? double.MinValue)
                .ThenBy(item => item.Label, StringComparer.CurrentCultureIgnoreCase)
                .Take(8)
                .Select(item => new PublicMaterialPeerModel
                {
                    MaterialId = item.MaterialId,
                    MaterialName = item.Label,
                    Manufacturer = item.Manufacturer,
                    OverallScore = item.OverallText,
                    TensileScore = item.TensileText,
                    ImpactScore = item.ImpactText
                })
                .ToList()
        };
    }

