    private async void ExportEngineeringReportPackage_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            AutomationRuntimeProfile.DemandReportGenerationAuthorized();
            if (!HasCanonicalMaterialReportData())
            {
                ReportPreviewLog.Text = "No material data is loaded. Add or import materials before exporting the Engineering Report Package.";
                ReportExportSummaryText.Text = "No data loaded";
                return;
            }

            var outputFolder = ReportOutputFolderBox.Text?.Trim();
            if (string.IsNullOrWhiteSpace(outputFolder))
            {
                outputFolder = GetDefaultReportOutputFolder();
                ReportOutputFolderBox.Text = outputFolder;
            }
            Directory.CreateDirectory(outputFolder);

            var generatedAt = DateTime.Now;
            var packageFolder = CreateUniqueReportFolder(outputFolder, $"engineering-report-package-{generatedAt:yyyyMMdd-HHmmss}");
            var definitions = EngineeringReportPackageDefinitions();
            var generatedReports = new List<(string Key, string Title, string Folder, string Purpose, ReportFoundationResult Report)>();

            if (ExportEngineeringReportPackageButton is not null) ExportEngineeringReportPackageButton.IsEnabled = false;
            for (var index = 0; index < definitions.Count; index++)
            {
                var definition = definitions[index];
                ReportExportSummaryText.Text = $"Engineering package: exporting {index + 1} of {definitions.Count} - {definition.Title}";
                var report = BuildReportFoundation(generatedAt, definition.Key, definition.Title);
                var reportFolder = System.IO.Path.Combine(packageFolder, definition.Folder);
                await WriteReportPackageArtifactsAsync(reportFolder, report, generatedAt);
                generatedReports.Add((definition.Key, definition.Title, definition.Folder, definition.Purpose, report));
            }

            var indexPath = System.IO.Path.Combine(packageFolder, "index.html");
            var manifestPath = System.IO.Path.Combine(packageFolder, "manifest.txt");
            var metadataPath = System.IO.Path.Combine(packageFolder, "package-metadata.json");
            SafeFileOperations.WriteAllTextAtomic(indexPath, BuildEngineeringReportPackageIndexHtml(generatedReports, generatedAt), Encoding.UTF8);
            SafeFileOperations.WriteAllTextAtomic(manifestPath, BuildEngineeringReportPackageManifest(generatedReports, generatedAt, packageFolder), Encoding.UTF8);
            SafeFileOperations.WriteAllTextAtomic(metadataPath, BuildEngineeringReportPackageMetadataJson(generatedReports, generatedAt, packageFolder), Encoding.UTF8);

            ReportExportSummaryText.Text = $"Exported Engineering Report Package: {System.IO.Path.GetFileName(packageFolder)}";
            ReportPreviewLog.Text = $"Engineering Report Package exported successfully.\n\nScope: {BuildEngineeringReportPackageScopeLabel()}\nReports: {generatedReports.Count}\nPackage folder: {packageFolder}\nIndex: {indexPath}\nManifest: {manifestPath}\nMetadata: {metadataPath}\n\nEach report folder contains canonical HTML, PDF printed from that HTML, text, metadata, manifest and assets.";
        }
        catch (Exception ex)
        {
            ReportPreviewLog.Text += $"\n\nEngineering Report Package export failed: {ex.Message}";
        }
        finally
        {
            if (ExportEngineeringReportPackageButton is not null) ExportEngineeringReportPackageButton.IsEnabled = true;
        }
    }

    private static string CreateUniqueReportFolder(string outputFolder, string baseName)
    {
        var candidate = System.IO.Path.Combine(outputFolder, baseName);
        var suffix = 2;
        while (Directory.Exists(candidate))
        {
            candidate = System.IO.Path.Combine(outputFolder, $"{baseName}-{suffix++}");
        }
        Directory.CreateDirectory(candidate);
        return candidate;
    }

    private string BuildEngineeringReportPackageScopeLabel()
    {
        if (GetMaterialReportScope() == "visible") return BuildMaterialReportScopeDescription();
        var selected = CurrentSelectedMaterialRow();
        return selected is null
            ? "Selected material unavailable; report-specific visible-scope fallbacks apply."
            : $"Selected Material Only: {_detailService.BuildTitle(selected)} ({GetCell(selected, "Material ID", "MaterialID")}). Each report applies its accepted selected-scope contract.";
    }

    private string BuildEngineeringReportPackageIndexHtml(IReadOnlyList<(string Key, string Title, string Folder, string Purpose, ReportFoundationResult Report)> reports, DateTime generatedAt)
    {
        var rows = reports.Select(item =>
            $"<tr><td>{Html(item.Title)}</td><td>{Html(item.Purpose)}</td><td>{item.Report.VisibleMaterialCount}</td><td><a href=\"{Html(item.Folder)}/report.html\">HTML</a></td><td><a href=\"{Html(item.Folder)}/report.pdf\">PDF</a></td><td><a href=\"{Html(item.Folder)}/report-metadata.json\">Metadata</a></td></tr>");
        return "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><title>3DPIceland Engineering Report Package</title>" +
               "<style>body{font-family:Segoe UI,Arial,sans-serif;margin:32px;color:#0f172a;background:#f8fafc}.shell{max-width:1120px;margin:auto;background:#fff;border:1px solid #cbd5e1;border-radius:16px;padding:28px;box-shadow:0 12px 36px rgba(15,23,42,.08)}h1{margin:0 0 8px}.meta,.note{color:#475569;line-height:1.5}.note{background:#f1f5f9;border:1px solid #cbd5e1;border-radius:10px;padding:14px;margin:18px 0}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{text-align:left;padding:10px;border-bottom:1px solid #e2e8f0;vertical-align:top}th{background:#e2e8f0}a{color:#1d4ed8;font-weight:600}</style></head><body><div class=\"shell\">" +
               "<h1>3DPIceland Engineering Report Package</h1>" +
               $"<div class=\"meta\">Version {Html(BuildInfo.ShortLabel)} - {Html(BuildInfo.ReleaseTitle)}<br>Generated {generatedAt:yyyy-MM-dd HH:mm:ss}<br>Reports {reports.Count}</div>" +
               $"<div class=\"note\"><strong>Package scope:</strong> {Html(BuildEngineeringReportPackageScopeLabel())}</div>" +
               "<div class=\"note\">Every PDF in this package is printed from the canonical HTML beside it. Individual report contracts remain independent; the package index does not merge or recalculate their data.</div>" +
               "<table><thead><tr><th>Report</th><th>Purpose</th><th>Materials / records</th><th>Canonical</th><th>Print</th><th>Metadata</th></tr></thead><tbody>" + string.Join("", rows) + "</tbody></table>" +
               "</div></body></html>";
    }

    private string BuildEngineeringReportPackageManifest(IReadOnlyList<(string Key, string Title, string Folder, string Purpose, ReportFoundationResult Report)> reports, DateTime generatedAt, string packageFolder)
    {
        var sb = new StringBuilder();
        sb.AppendLine("3DP Iceland Labs - Engineering Report Package Manifest");
        sb.AppendLine("Version: " + BuildInfo.ShortLabel + " - " + BuildInfo.ReleaseTitle);
        sb.AppendLine($"Generated: {generatedAt:yyyy-MM-dd HH:mm:ss}");
        sb.AppendLine("Package folder: " + packageFolder);
        sb.AppendLine("Scope: " + BuildEngineeringReportPackageScopeLabel());
        sb.AppendLine($"Accepted engineering reports: {reports.Count}");
        sb.AppendLine("Canonical package index: index.html");
        sb.AppendLine("Package metadata: package-metadata.json");
        sb.AppendLine();
        foreach (var item in reports)
        {
            sb.AppendLine($"- {item.Key} | {item.Title} | {item.Folder}/report.html | {item.Folder}/report.pdf | scope {item.Report.VisibleMaterialCount} of {item.Report.TotalMaterialCount}");
        }
        sb.AppendLine();
        sb.AppendLine("Rendering contract: every PDF is printed from its adjacent canonical report.html using WebView2 PrintToPdf.");
        return sb.ToString();
    }

    private string BuildEngineeringReportPackageMetadataJson(IReadOnlyList<(string Key, string Title, string Folder, string Purpose, ReportFoundationResult Report)> reports, DateTime generatedAt, string packageFolder)
    {
        var payload = new
        {
            packageType = "3DPIceland Engineering Report Package",
            release = BuildInfo.ShortLabel,
            releaseTitle = BuildInfo.ReleaseTitle,
            generatedAt = generatedAt.ToString("O", CultureInfo.InvariantCulture),
            packageFolder,
            scope = BuildEngineeringReportPackageScopeLabel(),
            reportCount = reports.Count,
            reports = reports.Select(item => new
            {
                item.Key,
                item.Title,
                item.Purpose,
                folder = item.Folder,
                canonicalHtml = item.Folder + "/report.html",
                pdf = item.Folder + "/report.pdf",
                metadata = item.Folder + "/report-metadata.json",
                scopeCount = item.Report.VisibleMaterialCount,
                activeMaterialCount = item.Report.TotalMaterialCount
            }).ToList()
        };
        return JsonSerializer.Serialize(payload, new JsonSerializerOptions { WriteIndented = true });
    }


    private async Task WriteReportPdfFromCanonicalHtmlAsync(string pdfPath, string htmlPath)
    {
        if (_publicReportBatchWebView?.CoreWebView2 is not null)
        {
            await PrintCanonicalHtmlWithWebViewAsync(_publicReportBatchWebView, pdfPath, htmlPath);
            return;
        }

        var (webView, hostWindow) = CreateHiddenReportPrintHost();

        try
        {
            hostWindow.Show();
            await webView.EnsureCoreWebView2Async();
            ConfigureReportPrintWebView(webView);
            await PrintCanonicalHtmlWithWebViewAsync(webView, pdfPath, htmlPath);
        }
        finally
        {
            hostWindow.Close();
            webView.Dispose();
        }
    }

    private async Task BeginPublicReportPdfBatchAsync()
    {
        if (_publicReportBatchWebView is not null) return;
        var (webView, hostWindow) = CreateHiddenReportPrintHost();
        try
        {
            hostWindow.Show();
            await webView.EnsureCoreWebView2Async();
            ConfigureReportPrintWebView(webView);
            _publicReportBatchWebView = webView;
            _publicReportBatchHostWindow = hostWindow;
        }
        catch
        {
            hostWindow.Close();
            webView.Dispose();
            throw;
        }
    }

    private void EndPublicReportPdfBatch()
    {
        _publicReportBatchHostWindow?.Close();
        _publicReportBatchWebView?.Dispose();
        _publicReportBatchHostWindow = null;
        _publicReportBatchWebView = null;
    }

    private static (Microsoft.Web.WebView2.Wpf.WebView2 WebView, Window HostWindow) CreateHiddenReportPrintHost()
    {
        var webView = new Microsoft.Web.WebView2.Wpf.WebView2 { Width = 1120, Height = 1600 };
        var hostWindow = new Window
        {
            Title = "3DPIceland HTML Print Engine",
            Width = 1200,
            Height = 1600,
            Left = -32000,
            Top = -32000,
            ShowInTaskbar = false,
            WindowStyle = WindowStyle.None,
            ResizeMode = ResizeMode.NoResize,
            Opacity = 0,
            Content = webView
        };
        AutomationProperties.SetAutomationId(hostWindow, "ReportPrintHostWindow");
        return (webView, hostWindow);
    }

    private static void ConfigureReportPrintWebView(Microsoft.Web.WebView2.Wpf.WebView2 webView)
    {
        var core = webView.CoreWebView2;
        core.Settings.AreDevToolsEnabled = false;
        core.Settings.AreDefaultContextMenusEnabled = false;
        core.Settings.AreBrowserAcceleratorKeysEnabled = false;
        core.Settings.IsStatusBarEnabled = false;
        core.Settings.IsZoomControlEnabled = false;
        core.NewWindowRequested += (_, args) => args.Handled = true;
        core.PermissionRequested += (_, args) => args.State = Microsoft.Web.WebView2.Core.CoreWebView2PermissionState.Deny;
    }

    private static async Task PrintCanonicalHtmlWithWebViewAsync(Microsoft.Web.WebView2.Wpf.WebView2 webView, string pdfPath, string htmlPath)
    {
        var navigationReady = new TaskCompletionSource<object?>(TaskCreationOptions.RunContinuationsAsynchronously);
        var allowedDocumentUri = new Uri(htmlPath).AbsoluteUri;
        void NavigationStarting(object? sender, Microsoft.Web.WebView2.Core.CoreWebView2NavigationStartingEventArgs args)
        {
            if (!string.Equals(args.Uri, allowedDocumentUri, StringComparison.OrdinalIgnoreCase))
                args.Cancel = true;
        }

        void NavigationCompleted(object? sender, Microsoft.Web.WebView2.Core.CoreWebView2NavigationCompletedEventArgs args)
        {
            if (args.IsSuccess)
                navigationReady.TrySetResult(null);
            else
                navigationReady.TrySetException(new InvalidOperationException("HTML print engine navigation failed: " + args.WebErrorStatus));
        }

        try
        {
            webView.CoreWebView2.Settings.IsScriptEnabled = true;
            webView.CoreWebView2.NavigationStarting += NavigationStarting;
            webView.NavigationCompleted += NavigationCompleted;
            webView.CoreWebView2.Navigate(allowedDocumentUri);
            await navigationReady.Task.WaitAsync(TimeSpan.FromSeconds(30));

            await WaitForReportDocumentReadyAsync(webView);

            var settings = webView.CoreWebView2.Environment.CreatePrintSettings();
            settings.ShouldPrintBackgrounds = true;
            settings.ShouldPrintHeaderAndFooter = false;
            settings.Orientation = UsesLandscapePublicReportLayout(htmlPath)
                ? Microsoft.Web.WebView2.Core.CoreWebView2PrintOrientation.Landscape
                : Microsoft.Web.WebView2.Core.CoreWebView2PrintOrientation.Portrait;
            settings.PageWidth = 8.27;
            settings.PageHeight = 11.69;
            settings.MarginTop = 0.25;
            settings.MarginBottom = 0.25;
            settings.MarginLeft = 0.25;
            settings.MarginRight = 0.25;
            settings.ScaleFactor = 1.0;

            var printed = await webView.CoreWebView2.PrintToPdfAsync(pdfPath, settings);
            if (!printed || !IOFile.Exists(pdfPath) || new FileInfo(pdfPath).Length == 0)
                throw new InvalidOperationException("HTML print engine did not create a valid PDF file.");
        }
        finally
        {
            webView.CoreWebView2.Stop();
            webView.CoreWebView2.Settings.IsScriptEnabled = false;
            webView.CoreWebView2.NavigationStarting -= NavigationStarting;
            webView.NavigationCompleted -= NavigationCompleted;
        }
    }

    private static bool UsesLandscapePublicReportLayout(string htmlPath)
    {
        var normalized = htmlPath.Replace('\\', '/');
        return normalized.Contains("/reports/comparisons/", StringComparison.OrdinalIgnoreCase) ||
               normalized.Contains("/reports/manufacturers/", StringComparison.OrdinalIgnoreCase) ||
               normalized.Contains("/reports/material-summary/", StringComparison.OrdinalIgnoreCase);
    }

    private static async Task WaitForReportDocumentReadyAsync(Microsoft.Web.WebView2.Wpf.WebView2 webView)
    {
        const string readinessScript = "(() => document.readyState === 'complete' && (!document.fonts || document.fonts.status === 'loaded') && Array.from(document.images).every(image => image.complete) ? 'ready' : 'waiting')()";
        for (var attempt = 0; attempt < 20; attempt++)
        {
            var state = await webView.CoreWebView2.ExecuteScriptAsync(readinessScript);
            if (state.Contains("ready", StringComparison.OrdinalIgnoreCase))
            {
                await Task.Delay(50);
                return;
            }
            await Task.Delay(25);
        }
        await Task.Delay(100);
    }

