    private void RefreshReportPreview()
    {
        if (ReportPreviewLog is null) return;

        var selectedReportKey = (ReportTypeSelector?.SelectedItem as ComboBoxItem)?.Tag?.ToString() ?? string.Empty;
        if (!_purchasingReportService.IsPurchasingReport(selectedReportKey) && !HasCanonicalMaterialReportData())
        {
            ReportPreviewLog.Text = "No material data is loaded. Add or import materials before generating engineering report previews.";
            ReportExportSummaryText.Text = "No data loaded";
            return;
        }

        var folder = ReportOutputFolderBox.Text?.Trim();
        if (string.IsNullOrWhiteSpace(folder))
        {
            folder = GetDefaultReportOutputFolder();
            ReportOutputFolderBox.Text = folder;
        }

        var report = BuildReportFoundation(DateTime.Now);
        ReportPreviewLog.Text = report.Text;
        ReportExportSummaryText.Text = $"Preview: {report.Title}";
    }

    private sealed class ReportFoundationResult
    {
        public string Key { get; init; } = "report";
        public string Title { get; init; } = "Report";
        public string Text { get; init; } = string.Empty;
        public string Html { get; init; } = string.Empty;
        public int VisibleMaterialCount { get; init; }
        public int TotalMaterialCount { get; init; }
    }

    private string GetMaterialReportScope()
    {
        var selectedItem = ReportMaterialScopeSelector?.SelectedItem as ComboBoxItem;
        return selectedItem?.Tag?.ToString() == "visible" ? "visible" : "selected";
    }

    private bool HasCanonicalMaterialReportData()
    {
        return _nativeMaterialRows.Any(row => !row.IsArchived);
    }

    private List<DataRow> GetCanonicalVisibleMaterialRows()
    {
        var visibleMaterialIds = GetVisibleNativeMaterialIdsFromCurrentFilters();
        return _nativeMaterialRows
            .Where(row => !row.IsArchived && visibleMaterialIds.Contains(row.MaterialID))
            .Select(BuildNativeMaterialDataRow)
            .ToList();
    }

    private List<DataRow> GetCanonicalActiveMaterialRows() => BuildNativeMaterialDataRows(includeArchived: false);

    private DataTable BuildCanonicalActiveMaterialTable()
    {
        var rows = GetCanonicalActiveMaterialRows();
        if (rows.Count == 0) return new DataTable("CanonicalMaterials");

        var table = rows[0].Table.Clone();
        table.TableName = "CanonicalMaterials";
        foreach (var row in rows) table.ImportRow(row);
        return table;
    }

    private List<DataRow> GetCanonicalVisibleMaterialReportRows() => GetCanonicalVisibleMaterialRows();

    private List<DataRow> GetCanonicalMaterialReportContextRows() => GetCanonicalActiveMaterialRows();

    private Dictionary<string, MaterialResults> GetCanonicalVerifiedSummaryMap() =>
        BuildVerifiedMaterialSummaryMap(_nativeMaterialRows.Where(row => !row.IsArchived).ToList());

    private List<VideoPlannerRow> BuildCanonicalVisiblePlannerRows()
    {
        var verifiedSummaries = GetCanonicalVerifiedSummaryMap();
        return GetCanonicalVisibleMaterialRows()
            .Select(row => BuildVideoPlannerRow(row, verifiedSummaries))
            .ToList();
    }

    private string BuildMaterialReportScopeDescription()
    {
        if (GetMaterialReportScope() == "selected")
        {
            var selected = CurrentSelectedMaterialRow();
            return selected is null
                ? "Selected material unavailable; the current visible material set is used."
                : $"Selected material only: {_detailService.BuildTitle(selected)} ({GetCell(selected, "Material ID")}).";
        }

        var filterDescription = BuildCurrentMaterialFilterDescription();
        return string.Equals(
            filterDescription,
            "All active canonical Materials",
            StringComparison.Ordinal)
            ? "All visible active materials; no Materials-tab search or filters are applied."
            : "All visible active materials. Applied Materials-tab scope: " +
              filterDescription + ".";
    }

    private void UpdateReportSelectedMaterial(DataRow? row)
    {
        if (ReportSelectedMaterialText is null) return;

        var selectedLabel = row is null ? string.Empty : _detailService.BuildTitle(row);
        var selectedMaterialId = row is null ? string.Empty : GetCell(row, "Material ID", "MaterialID").Trim();
        ReportSelectedMaterialText.Text = string.IsNullOrWhiteSpace(selectedLabel)
            ? "Selected material: none"
            : $"Selected material: {selectedLabel} · MaterialID: {selectedMaterialId}";

        if (IsLoaded && row is not null && GetMaterialReportScope() == "selected" && ReportPreviewLog is not null)
        {
            RefreshReportPreview();
        }
    }

    private void ReportMaterialScopeSelector_SelectionChanged(object sender, SelectionChangedEventArgs e)
    {
        if (!IsLoaded) return;
        RefreshReportPreview();
    }

    private ReportFoundationResult BuildReportFoundation(DateTime generatedAt, string? reportKeyOverride = null, string? reportTitleOverride = null)
    {
        var selectedItem = ReportTypeSelector?.SelectedItem as ComboBoxItem;
        var key = reportKeyOverride ?? selectedItem?.Tag?.ToString() ?? "material";
        var title = reportTitleOverride ?? selectedItem?.Content?.ToString() ?? "Material Reports";
        if (_purchasingReportService.IsPurchasingReport(key))
        {
            CommitPurchaseOrderEdits(false);
            var purchasing = _purchasingReportService.Build(key, _inventorySpoolRows.ToList(), _purchaseOrders.ToList(), _purchaseOrderLines.ToList(), generatedAt);
            return new ReportFoundationResult
            {
                Key = purchasing.Key, Title = purchasing.Title, Text = purchasing.Text, Html = purchasing.Html,
                VisibleMaterialCount = purchasing.RecordCount, TotalMaterialCount = purchasing.RecordCount
            };
        }
        var visibleRows = GetCanonicalVisibleMaterialReportRows();
        var contextRows = GetCanonicalMaterialReportContextRows();
        var totalRows = contextRows.Count;
        var selectedMaterialRow = CurrentSelectedMaterialRow();
        var materialScope = GetMaterialReportScope();
        var useSelectedMaterialScope = materialScope == "selected" && selectedMaterialRow is not null;

        // v23.1.3: Report scope now applies to all report types.
        // Selected Material Only limits Material, Rankings, Awards, and YouTube reports
        // to the selected row. All Visible Materials restores the full filtered dataset.
        var reportRows = useSelectedMaterialScope && selectedMaterialRow is not null
            ? new List<DataRow> { selectedMaterialRow }
            : visibleRows;
        var effectiveReportCount = key == "comparison" && useSelectedMaterialScope && selectedMaterialRow is not null
            ? 1 + Math.Min(5, visibleRows.Count(row => !SameText(GetCell(row, "Material ID"), GetCell(selectedMaterialRow, "Material ID"))))
            : key == "manufacturer" && useSelectedMaterialScope && selectedMaterialRow is not null
                ? GetCanonicalActiveMaterialRows().Count(row => SameText(GetCell(row, "Manufacturer", "Brand"), GetCell(selectedMaterialRow, "Manufacturer", "Brand")))
            : reportRows.Count;

        if (useSelectedMaterialScope)
        {
            title = key switch
            {
                "rankings" => "Selected Material Ranking Context",
                "awards" => "Selected Material Award Eligibility",
                "youtube" => "Selected Material Video Notes",
                "engineering" => "Material Engineering Report",
                "material-summary" => "Material Summary Report",
                "comparison" => "Comparison Report",
                "manufacturer" => "Manufacturer Report",
                "test-session" => "Test Session Report",
                "printing-recommendation" => "Printing Recommendation Report",
                _ => "Material Detail Report"
            };
        }

        var sb = new StringBuilder();
        sb.AppendLine("3DP Iceland Labs - Report Export Preview");
        sb.AppendLine($"Report type: {title}");
        sb.AppendLine($"Generated: {generatedAt:yyyy-MM-dd HH:mm:ss}");
        var reportScopeLabel = key switch
        {
            "comparison" when useSelectedMaterialScope => "Selected material anchor + visible comparison peers",
            "manufacturer" when useSelectedMaterialScope => "Active portfolio of the selected material's manufacturer",
            "test-session" when useSelectedMaterialScope => "Detailed native test record for the selected material",
            "printing-recommendation" when useSelectedMaterialScope => "Printing-use guidance for the selected material",
            _ => materialScope == "visible" ? "All visible materials" : "Selected material only"
        };
        sb.AppendLine($"Report scope: {reportScopeLabel}");
        if (useSelectedMaterialScope)
        {
            sb.AppendLine($"Selected material: {_detailService.BuildTitle(selectedMaterialRow!)}");
        }
        else if (materialScope == "selected")
        {
            sb.AppendLine("Selected material: none selected, using all visible materials");
        }
        sb.AppendLine(key == "comparison"
            ? $"Materials in comparison: {effectiveReportCount} from {totalRows} active materials"
            : $"Materials in report scope: {reportRows.Count} of {totalRows} active materials");
        sb.AppendLine();

        switch (key)
        {
            case "rankings":
                AppendRankingsReportPreview(sb, reportRows);
                break;
            case "awards":
                AppendAwardsReportPreview(sb, reportRows);
                break;
            case "youtube":
                AppendYouTubeResearchReportPreview(sb, reportRows);
                break;
            case "engineering":
                AppendMaterialEngineeringReportPreview(sb, reportRows);
                break;
            case "material-summary":
                AppendMaterialSummaryReportPreview(sb, reportRows);
                break;
            case "comparison":
                AppendComparisonReportPreview(sb, reportRows, visibleRows, useSelectedMaterialScope);
                break;
            case "manufacturer":
                AppendManufacturerReportPreview(sb, reportRows, visibleRows, useSelectedMaterialScope);
                break;
            case "test-session":
                AppendTestSessionReportPreview(sb, reportRows, useSelectedMaterialScope);
                break;
            case "printing-recommendation":
                AppendPrintingRecommendationReportPreview(sb, reportRows, useSelectedMaterialScope);
                break;
            default:
                AppendMaterialReportPreview(sb, reportRows);
                break;
        }

        sb.AppendLine();
        sb.AppendLine("Foundation status:");
        sb.AppendLine("- Native report template selector: ready");
        sb.AppendLine("- Output folder workflow: ready");
        sb.AppendLine("- Preview/export workflow: ready");
        sb.AppendLine("- Unified report rendering engine: ready");
        sb.AppendLine("- HTML is canonical report layout");
        sb.AppendLine("- PDF export writes companion canonical HTML package");

        var text = sb.ToString();
        return new ReportFoundationResult
        {
            Key = key,
            Title = title,
            Text = text,
            Html = BuildReportFoundationHtml(title, key, generatedAt, reportRows, visibleRows, totalRows, useSelectedMaterialScope, text),
            VisibleMaterialCount = effectiveReportCount,
            TotalMaterialCount = totalRows
        };
    }

    
private void AppendMaterialReportPreview(StringBuilder sb, IReadOnlyList<DataRow> rows)
    {
        sb.AppendLine("Material Report Generator");
        sb.AppendLine("========================");
        sb.AppendLine();

        foreach (var row in rows.Take(10))
        {
            var label = _detailService.BuildTitle(row);
            var manufacturer = GetCell(row, "Manufacturer", "Brand");
            var baseMaterial = GetCell(row, "Base Material", "Material Type", "Type");
            var reinforcement = GetCell(row, "Reinforcement", "Reinforment");

            sb.AppendLine($"Material: {label}");
            sb.AppendLine($"Manufacturer: {manufacturer}");
            sb.AppendLine($"Material Type: {baseMaterial}");
            if (!string.IsNullOrWhiteSpace(reinforcement))
                sb.AppendLine($"Reinforcement: {reinforcement}");

            var tensile = FormatMetricCell(row, "Tensile", "Tensile Strength", "Tensile MPa", "MPa");
            var impact = FormatMetricCell(row, "Impact", "Impact Strength", "Impact kJ/m2", "kJ/m²");
            var score = FormatMetricCell(row, "Overall Score", "Engineering Score", "Score", "");

            if (!string.IsNullOrWhiteSpace(tensile)) sb.AppendLine($"Tensile: {tensile}");
            if (!string.IsNullOrWhiteSpace(impact)) sb.AppendLine($"Impact: {impact}");
            if (!string.IsNullOrWhiteSpace(score)) sb.AppendLine($"Overall Score: {score}");

            sb.AppendLine(new string('-',60));
        }

        if (rows.Count > 10)
            sb.AppendLine($"Showing first 10 of {rows.Count} visible materials.");
    }

    private void AppendMaterialSummaryReportPreview(StringBuilder sb, IReadOnlyList<DataRow> rows)
    {
        var verifiedSummaries = BuildVerifiedMaterialSummaryMap(GetNativeWebsiteExportCandidateRows());
        var summaries = rows.Select(row =>
        {
            var materialId = (GetCell(row, "Material ID", "MaterialID") ?? string.Empty).Trim();
            verifiedSummaries.TryGetValue(materialId, out var summary);
            return (Summary: summary, Ranking: BuildRankingRow(BuildVideoPlannerRow(row, verifiedSummaries), "Overall"));
        }).ToList();
        var tested = summaries.Count(row => row.Summary?.HasAnyResults == true);
        var completeProfiles = summaries.Count(row => row.Summary?.IsCompleteEngineeringSummary == true);

        sb.AppendLine("Material Summary Report - REPORT-110");
        sb.AppendLine("====================================");
        sb.AppendLine("Canonical identity, test coverage and high-level verified engineering results.");
        sb.AppendLine($"Materials in report scope: {rows.Count}");
        sb.AppendLine($"Scope definition: {BuildMaterialReportScopeDescription()}");
        sb.AppendLine($"Manufacturers represented: {summaries.Select(row => row.Ranking.Manufacturer).Where(value => !string.IsNullOrWhiteSpace(value)).Distinct(StringComparer.CurrentCultureIgnoreCase).Count()}");
        sb.AppendLine($"Materials with verified test results: {tested}");
        sb.AppendLine($"Fully tested materials (tensile + impact + stiffness): {completeProfiles}");
        sb.AppendLine();

        foreach (var item in summaries.Take(10))
        {
            var row = item.Ranking;
            sb.AppendLine($"- {row.Label} | {DisplayText(row.Manufacturer)} | {DisplayText(row.BaseMaterial)} | Status {DisplayText(row.Status)} | Overall {row.OverallText}");
        }

        if (rows.Count > 10)
        {
            sb.AppendLine();
            sb.AppendLine($"Preview showing first 10 of {rows.Count} materials. Export Current Report includes the full report scope.");
        }
    }

    private void AppendMaterialEngineeringReportPreview(StringBuilder sb, IReadOnlyList<DataRow> rows)
    {
        sb.AppendLine("Material Engineering Report");
        sb.AppendLine("===========================");
        sb.AppendLine("Production REPORT-100 output built from verified report models and Material Summary data.");
        sb.AppendLine("No raw tensile, impact or stiffness rows are consumed by this report layer.");
        sb.AppendLine();

        foreach (var row in rows.Take(5))
        {
            var video = BuildVideoPlannerRow(row);
            var ranking = BuildRankingRow(video, "Overall");
            sb.AppendLine($"Material: {video.Label}");
            sb.AppendLine($"Manufacturer: {video.Manufacturer}");
            sb.AppendLine($"Material Type: {video.BaseMaterial}");
            sb.AppendLine($"Reinforcement: {DisplayText(video.Reinforcement)}");
            sb.AppendLine($"Overall: {ranking.OverallText}");
            sb.AppendLine($"Tensile: {ranking.TensileText}");
            sb.AppendLine($"Impact: {ranking.ImpactText}");
            sb.AppendLine($"Stiffness: {ranking.StiffnessText}");
            sb.AppendLine($"Consistency: {ranking.ConsistencyText}");
            sb.AppendLine($"Layer Adhesion: {ranking.LayerAdhesionText}");
            sb.AppendLine($"Recommendation status: {video.Status}");
            sb.AppendLine(new string('-', 60));
        }

        if (rows.Count > 5)
            sb.AppendLine($"Showing first 5 of {rows.Count} materials. Use Selected Material Only for a focused production report.");
    }

    private void AppendRankingsReportPreview(StringBuilder sb, IReadOnlyList<DataRow> rows)
    {
        sb.AppendLine("Rankings report preview:");
        sb.AppendLine("- Intended output: top ranked materials with score breakdowns, ready for print/PDF review.");
        sb.AppendLine("- Ranking source: current visible dataset, sorted by overall engineering score.");
        sb.AppendLine();
        sb.AppendLine("Top candidates:");

        var rankedRows = rows
            .Select(row => BuildRankingRow(BuildVideoPlannerRow(row), "Overall"))
            .Where(row => row.RankScore.HasValue)
            .OrderByDescending(row => row.RankScore ?? double.MinValue)
            .ThenBy(row => row.Label, StringComparer.CurrentCultureIgnoreCase)
            .Take(12)
            .ToList();


        for (var i = 0; i < rankedRows.Count; i++)
        {
            var row = rankedRows[i];
            sb.AppendLine($"{i + 1}. {row.Label} | Overall {row.OverallText} | Tensile {row.TensileText} | Impact {row.ImpactText}");
        }

        if (rankedRows.Count == 0) sb.AppendLine("- No scored materials found in the current visible set.");
    }

    private void AppendAwardsReportPreview(StringBuilder sb, IReadOnlyList<DataRow> rows)
    {
        sb.AppendLine("Awards report preview:");
        sb.AppendLine("- Intended output: award categories and visible dataset context for later winner/runner-up exports.");
        sb.AppendLine("- Award source: current visible dataset and existing Awards & Winners scoring logic.");
        sb.AppendLine();
        sb.AppendLine("Award categories prepared:");
        sb.AppendLine("- Best overall engineering material");
        sb.AppendLine("- Best tensile performer");
        sb.AppendLine("- Best impact performer");
        sb.AppendLine("- Best stiffness performer");
        sb.AppendLine("- Most consistent filament");
        sb.AppendLine($"- Visible materials available for award calculation: {rows.Count}");
    }

    private void AppendYouTubeResearchReportPreview(StringBuilder sb, IReadOnlyList<DataRow> rows)
    {
        sb.AppendLine("YouTube research report preview:");
        sb.AppendLine("- Intended output: video planning notes, standout metrics, suggested angles, and title research for print/PDF review.");
        sb.AppendLine("- Source: current visible dataset and Video Planner candidate logic.");
        sb.AppendLine();
        sb.AppendLine("Research candidates:");

        var candidates = rows
            .Select(row => BuildVideoPlannerRow(row))
            .OrderByDescending(row => row.Priority)
            .ThenByDescending(row => row.OverallScore ?? double.MinValue)
            .Take(12)
            .ToList();

        foreach (var row in candidates)
        {
            sb.AppendLine($"- {row.Label} | Priority {row.Priority} | {row.Status} | Angle: {row.SuggestedAngle}");
        }

        if (candidates.Count == 0) sb.AppendLine("- No YouTube candidates found in the current visible set.");
    }

    private string BuildReportFoundationHtml(string title, string key, DateTime generatedAt, IReadOnlyList<DataRow> rows, IReadOnlyList<DataRow> contextRows, int totalRows, bool selectedScope, string text)
    {
        return key switch
        {
            "rankings" => selectedScope && rows.Count == 1
                ? BuildSelectedRankingContextHtml(title, key, generatedAt, rows[0], contextRows, totalRows)
                : BuildRankingsReportHtml(title, key, generatedAt, rows, totalRows),
            "awards" => selectedScope && rows.Count == 1
                ? BuildSelectedAwardEligibilityHtml(title, key, generatedAt, rows[0], contextRows, totalRows)
                : BuildAwardsReportHtml(title, key, generatedAt, rows, totalRows),
            "youtube" => selectedScope && rows.Count == 1
                ? BuildSelectedVideoNotesHtml(title, key, generatedAt, rows[0], totalRows)
                : BuildYouTubeReportHtml(title, key, generatedAt, rows, totalRows),
            "engineering" => rows.Count == 1
                ? BuildSelectedMaterialEngineeringReportHtml(title, key, generatedAt, rows[0], contextRows, totalRows)
                : BuildMaterialEngineeringReportHtml(title, key, generatedAt, rows, totalRows),
            "material-summary" => BuildMaterialSummaryReportHtml(title, key, generatedAt, rows, totalRows),
            "comparison" => BuildComparisonReportHtml(title, key, generatedAt, rows, contextRows, totalRows, selectedScope),
            "manufacturer" => BuildManufacturerReportHtml(title, key, generatedAt, rows, contextRows, totalRows, selectedScope),
            "test-session" => BuildTestSessionReportHtml(title, key, generatedAt, rows, totalRows, selectedScope),
            "printing-recommendation" => BuildPrintingRecommendationReportHtml(title, key, generatedAt, rows, contextRows, totalRows, selectedScope),
            _ => BuildMaterialReportHtml(title, key, generatedAt, rows, totalRows)
        };
    }

