    private static string BuildReportLogoDataUri()
    {
        var bytes = LoadReportLogoJpegBytes();
        return bytes.Length == 0 ? string.Empty : "data:image/jpeg;base64," + Convert.ToBase64String(bytes);
    }

    private static byte[] LoadReportLogoJpegBytes()
    {
        var candidatePaths = new[]
        {
            System.IO.Path.Combine(AppContext.BaseDirectory, "Assets", "3dp-iceland-labs-logo-pdf.jpg"),
            System.IO.Path.Combine(AppContext.BaseDirectory, "3dp-iceland-labs-logo-pdf.jpg"),
            System.IO.Path.Combine(Directory.GetCurrentDirectory(), "Assets", "3dp-iceland-labs-logo-pdf.jpg")
        };

        foreach (var path in candidatePaths)
        {
            if (File.Exists(path)) return File.ReadAllBytes(path);
        }

        return Array.Empty<byte>();
    }

    private string BuildScoreBarChartHtml(string title, IEnumerable<RankingRow> rankingRows, Func<RankingRow, double?> scoreSelector, string valueSuffix = "/100")
    {
        var items = rankingRows
            .Select(row => (Label: row.Label, Value: scoreSelector(row)))
            .Where(item => item.Value.HasValue)
            .Select(item => (item.Label, Value: item.Value!.Value))
            .OrderByDescending(item => item.Value)
            .Take(10)
            .ToList();

        return BuildBarChartHtml(title, items, valueSuffix);
    }

    private string BuildDistributionBarChartHtml(string title, IEnumerable<(string Label, int Count)> source)
    {
        var items = source
            .Where(item => !string.IsNullOrWhiteSpace(item.Label) && item.Count > 0)
            .Select(item => (Label: item.Label, Value: (double)item.Count))
            .OrderByDescending(item => item.Value)
            .ThenBy(item => item.Label, StringComparer.CurrentCultureIgnoreCase)
            .Take(10)
            .ToList();

        return BuildBarChartHtml(title, items, string.Empty);
    }

    private string BuildBarChartHtml(string title, IReadOnlyList<(string Label, double Value)> items, string valueSuffix)
    {
        if (items.Count == 0) return string.Empty;

        var max = Math.Max(1, items.Max(item => item.Value));
        var rowsHtml = items.Select(item =>
        {
            var width = Math.Max(2, Math.Min(100, item.Value / max * 100));
            var valueText = item.Value >= 100 ? item.Value.ToString("0", CultureInfo.CurrentCulture) : item.Value.ToString("0.#", CultureInfo.CurrentCulture);
            return $"<div class=\"bar-row\"><div class=\"bar-label\" title=\"{Html(item.Label)}\">{Html(item.Label)}</div><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:{width.ToString("0.#", CultureInfo.InvariantCulture)}%\"></div></div><div class=\"bar-value\">{Html(valueText + valueSuffix)}</div></div>";
        });

        return $"<div class=\"chart\"><div class=\"chart-title\">{Html(title)}</div>{string.Join("", rowsHtml)}</div>";
    }


    private string BuildEngineeringChartSuiteHtml(RankingRow selected, IEnumerable<RankingRow> contextRows)
    {
        var peers = contextRows
            .Where(row => !string.IsNullOrWhiteSpace(row.Label))
            .ToList();

        var materialAverage = AverageRankingRow(
            "Material average - " + DisplayText(selected.BaseMaterial),
            peers.Where(row => SameText(row.BaseMaterial, selected.BaseMaterial)));
        var manufacturerAverage = AverageRankingRow(
            "Manufacturer average - " + DisplayText(selected.Manufacturer),
            peers.Where(row => SameText(row.Manufacturer, selected.Manufacturer)));

        var radar = BuildRadarChartHtml("Engineering radar - selected vs material + manufacturer averages", selected, materialAverage, manufacturerAverage);
        var materialComparison = BuildMetricComparisonTableHtml("Material vs material average", selected, materialAverage);
        var manufacturerComparison = BuildMetricComparisonTableHtml("Material vs manufacturer average", selected, manufacturerAverage);

        return "<div class=\"chart-grid\">" + radar + materialComparison + manufacturerComparison + "</div>";
    }


    private string BuildEngineeringIntelligenceHtml(RankingRow selected, IEnumerable<RankingRow> contextRows)
    {
        var peers = contextRows
            .Where(row => !string.IsNullOrWhiteSpace(row.Label))
            .ToList();
        if (peers.Count == 0) peers.Add(selected);

        var materialAverage = AverageRankingRow(
            "Material average - " + DisplayText(selected.BaseMaterial),
            peers.Where(row => SameText(row.BaseMaterial, selected.BaseMaterial)));
        var manufacturerAverage = AverageRankingRow(
            "Manufacturer average - " + DisplayText(selected.Manufacturer),
            peers.Where(row => SameText(row.Manufacturer, selected.Manufacturer)));

        var best = BestScoredMetric(selected);
        var weakest = WeakestScoredMetric(selected);
        var overallRank = BuildMetricRank(selected.Overall ?? selected.RankScore, peers.Select(row => row.Overall ?? row.RankScore));
        var tensileRank = BuildMetricRank(selected.Tensile, peers.Select(row => row.Tensile));
        var impactRank = BuildMetricRank(selected.Impact, peers.Select(row => row.Impact));
        var stiffnessRank = BuildMetricRank(selected.Stiffness, peers.Select(row => row.Stiffness));
        var consistencyRank = BuildMetricRank(selected.Consistency, peers.Select(row => row.Consistency));
        var layerRank = BuildMetricRank(selected.LayerAdhesion, peers.Select(row => row.LayerAdhesion));

        var summary = BuildEngineeringSummaryText(selected, materialAverage, manufacturerAverage, best.Label, weakest.Label);
        var applications = BuildRecommendedApplications(selected);
        var highlight = BuildEngineeringHighlight(selected, best.Label, weakest.Label);
        var executiveReview = BuildDeterministicEngineeringReviewText(selected, peers, materialAverage, manufacturerAverage, best.Label, weakest.Label, overallRank.PercentileText);
        var strengths = BuildStrengthList(selected, materialAverage, manufacturerAverage).Select(item => $"<li>{Html(item)}</li>");
        var weaknesses = BuildWeaknessList(selected, materialAverage, manufacturerAverage).Select(item => $"<li>{Html(item)}</li>");
        var tradeoffs = BuildEngineeringTradeoffs(selected, materialAverage, manufacturerAverage).Select(item => $"<li>{Html(item)}</li>");
        var alternatives = BuildBetterAlternativeRows(selected, peers);
        var alternativesRows = alternatives.Count == 0
            ? "<tr><td colspan=\"4\">No stronger same-material alternatives were found in the current verified report context.</td></tr>"
            : string.Join("", alternatives.Select(item => $"<tr><td>{Html(item.Label)}</td><td>{Html(FormatScore(item.Overall ?? item.RankScore))}</td><td>{Html(FormatScore(item.Tensile))}</td><td>{Html(FormatScore(item.Impact))}</td></tr>"));

        var rankingRows = new[]
        {
            ("Overall", selected.Overall ?? selected.RankScore, overallRank),
            ("Tensile", selected.Tensile, tensileRank),
            ("Impact", selected.Impact, impactRank),
            ("Stiffness", selected.Stiffness, stiffnessRank),
            ("Consistency", selected.Consistency, consistencyRank),
            ("Layer Adhesion", selected.LayerAdhesion, layerRank)
        }.Select(item => $"<tr><td>{Html(item.Item1)}</td><td>{Html(FormatScore(item.Item2))}</td><td>{Html(item.Item3.RankText)}</td><td>{Html(item.Item3.PercentileText)}</td></tr>");

        var recommendationItems = applications.Select(item => $"<li>{Html(item)}</li>");
        var recommendedUse = applications.FirstOrDefault() ?? "Review manually";

        return "<h2>Engineering Intelligence</h2>" +
               $"<div class=\"note\"><strong>Engineering Summary:</strong> {Html(summary)}</div>" +
               "<div class=\"badge-row\">" +
               $"<span class=\"badge good\">Best feature: {Html(best.Label)}</span>" +
               $"<span class=\"badge warn\">Weakest feature: {Html(weakest.Label)}</span>" +
               $"<span class=\"badge info\">Highlight: {Html(highlight)}</span>" +
               "</div>" +
               "<div class=\"intelligence-grid\">" +
               $"<div class=\"intel-card\"><div class=\"intel-card-title\">Overall percentile</div><div class=\"intel-card-value\">{Html(overallRank.PercentileText)}</div></div>" +
               $"<div class=\"intel-card\"><div class=\"intel-card-title\">Overall rank</div><div class=\"intel-card-value\">{Html(overallRank.RankText)}</div></div>" +
               $"<div class=\"intel-card\"><div class=\"intel-card-title\">Recommended use</div><div class=\"intel-card-value\">{Html(recommendedUse)}</div></div>" +
               "</div>" +
               "<div class=\"ai-review\">" +
               "<h2>Data-driven Engineering Review</h2>" +
               "<div class=\"note\"><strong>Method:</strong> Generated locally from deterministic rules and verified engineering summaries. No external AI or LLM is used.</div>" +
               $"<div class=\"note\"><strong>Executive Summary:</strong> {Html(executiveReview)}</div>" +
               "<div class=\"review-section-grid\">" +
               "<div class=\"review-panel\"><div class=\"review-panel-title\">Strengths</div><ul class=\"review-list\">" + string.Join("", strengths) + "</ul></div>" +
               "<div class=\"review-panel\"><div class=\"review-panel-title\">Weaknesses</div><ul class=\"review-list\">" + string.Join("", weaknesses) + "</ul></div>" +
               "<div class=\"review-panel\"><div class=\"review-panel-title\">Engineering trade-offs</div><ul class=\"review-list\">" + string.Join("", tradeoffs) + "</ul></div>" +
               "<div class=\"review-panel\"><div class=\"review-panel-title\">Decision guidance</div><ul class=\"review-list\">" + BuildDecisionGuidanceHtml(selected, alternatives.Count) + "</ul></div>" +
               "</div>" +
               "<h2>Better alternatives in the current dataset</h2>" +
               "<table class=\"alternatives-table\"><thead><tr><th>Alternative</th><th>Overall</th><th>Tensile</th><th>Impact</th></tr></thead><tbody>" + alternativesRows + "</tbody></table>" +
               "</div>" +
               "<h2>Recommended applications</h2>" +
               "<ul class=\"recommendation-list\">" + string.Join("", recommendationItems) + "</ul>" +
               "<h2>Rankings and percentiles</h2>" +
               "<table><thead><tr><th>Metric</th><th>Score</th><th>Rank</th><th>Percentile</th></tr></thead><tbody>" +
               string.Join("", rankingRows) +
               "</tbody></table>";
    }

    private static string BuildDeterministicEngineeringReviewText(RankingRow selected, IReadOnlyList<RankingRow> peers, RankingRow? materialAverage, RankingRow? manufacturerAverage, string bestFeature, string weakestFeature, string percentileText)
    {
        var overall = selected.Overall ?? selected.RankScore;
        var materialDelta = Difference(overall, materialAverage?.Overall ?? materialAverage?.RankScore);
        var manufacturerDelta = Difference(overall, manufacturerAverage?.Overall ?? manufacturerAverage?.RankScore);
        var suitability = GetPrimarySuitability(selected);
        var materialComparison = DescribeDelta(materialDelta, "the material-family average");
        var manufacturerComparison = DescribeDelta(manufacturerDelta, "the manufacturer average");

        return $"{selected.Label} is best understood as {suitability}. Compared with the current verified dataset, it ranks {percentileText.ToLowerInvariant()} overall, is {materialComparison}, and is {manufacturerComparison}. Its strongest engineering signal is {bestFeature}, while {weakestFeature} is the main limitation to consider before using it for demanding applications.";
    }

    private static IReadOnlyList<string> BuildStrengthList(RankingRow selected, RankingRow? materialAverage, RankingRow? manufacturerAverage)
    {
        var strengths = new List<string>();
        AddStrengthIfAbove(strengths, "Layer adhesion", selected.LayerAdhesion, materialAverage?.LayerAdhesion, "Z-axis bonding is better than the material-family context.");
        AddStrengthIfAbove(strengths, "Consistency", selected.Consistency, materialAverage?.Consistency, "Repeatability is one of the stronger signals in this material profile.");
        AddStrengthIfAbove(strengths, "Impact", selected.Impact, materialAverage?.Impact, "Impact behavior is competitive against the material-family context.");
        AddStrengthIfAbove(strengths, "Tensile", selected.Tensile, materialAverage?.Tensile, "Tensile behavior is competitive against the material-family context.");
        AddStrengthIfAbove(strengths, "Stiffness", selected.Stiffness, materialAverage?.Stiffness, "Stiffness is a relative advantage in this comparison group.");

        if (strengths.Count == 0)
        {
            var best = BestScoredMetric(selected);
            strengths.Add($"Best available signal: {best.Label} at {best.Value:0}/100.");
        }
        return strengths.Take(4).ToList();
    }

    private static IReadOnlyList<string> BuildWeaknessList(RankingRow selected, RankingRow? materialAverage, RankingRow? manufacturerAverage)
    {
        var weaknesses = new List<string>();
        AddWeaknessIfBelow(weaknesses, "Tensile", selected.Tensile, materialAverage?.Tensile, "Avoid using this as the primary choice for tensile-loaded parts.");
        AddWeaknessIfBelow(weaknesses, "Impact", selected.Impact, materialAverage?.Impact, "Avoid high impact or shock-loaded components without additional validation.");
        AddWeaknessIfBelow(weaknesses, "Stiffness", selected.Stiffness, materialAverage?.Stiffness, "Expect less shape stability than the stronger materials in the same family.");
        AddWeaknessIfBelow(weaknesses, "Consistency", selected.Consistency, materialAverage?.Consistency, "Repeatability may not be the best reason to choose this filament.");
        AddWeaknessIfBelow(weaknesses, "Layer adhesion", selected.LayerAdhesion, materialAverage?.LayerAdhesion, "Z-axis performance should be treated with caution.");

        if (weaknesses.Count == 0)
        {
            var weakest = WeakestScoredMetric(selected);
            weaknesses.Add($"Main watch item: {weakest.Label} at {weakest.Value:0}/100.");
        }
        return weaknesses.Take(4).ToList();
    }

    private static IReadOnlyList<string> BuildEngineeringTradeoffs(RankingRow selected, RankingRow? materialAverage, RankingRow? manufacturerAverage)
    {
        var tradeoffs = new List<string>();
        if (selected.Consistency.GetValueOrDefault(0) >= 60 && selected.Tensile.GetValueOrDefault(0) < 40)
            tradeoffs.Add("Good repeatability does not compensate for low tensile capability in load-bearing designs.");
        if (selected.LayerAdhesion.GetValueOrDefault(0) >= 50 && selected.Stiffness.GetValueOrDefault(0) < 60)
            tradeoffs.Add("Layer bonding may be acceptable, but stiffness is still a limiting design factor.");
        if (selected.Stiffness.GetValueOrDefault(0) >= 70 && selected.Impact.GetValueOrDefault(0) < 45)
            tradeoffs.Add("Stiffness is useful for shape stability, but impact tolerance is a separate limitation.");
        if ((selected.Overall ?? selected.RankScore).GetValueOrDefault(0) < 50)
            tradeoffs.Add("The report should be read as a suitability warning rather than a general-purpose recommendation.");

        if (tradeoffs.Count == 0)
            tradeoffs.Add("The score profile is balanced enough that final material choice should depend on printability, finish, cost and environment.");

        return tradeoffs;
    }

    private static IReadOnlyList<RankingRow> BuildBetterAlternativeRows(RankingRow selected, IEnumerable<RankingRow> peers)
    {
        var selectedOverall = (selected.Overall ?? selected.RankScore).GetValueOrDefault(double.MinValue);
        var sameFamily = peers
            .Where(row => !ReferenceEquals(row, selected))
            .Where(row => !SameText(row.Label, selected.Label))
            .Where(row => SameText(row.BaseMaterial, selected.BaseMaterial))
            .Where(row => (row.Overall ?? row.RankScore).HasValue)
            .Where(row => (row.Overall ?? row.RankScore).GetValueOrDefault() > selectedOverall + 3)
            .OrderByDescending(row => (row.Overall ?? row.RankScore).GetValueOrDefault())
            .ThenBy(row => row.Label, StringComparer.CurrentCultureIgnoreCase)
            .Take(3)
            .ToList();

        return sameFamily;
    }

    private static string BuildDecisionGuidanceHtml(RankingRow selected, int alternativesCount)
    {
        return string.Join("", BuildDecisionGuidanceItems(selected, alternativesCount).Select(item => $"<li>{Html(item)}</li>"));
    }

    private static IReadOnlyList<string> BuildDecisionGuidanceItems(RankingRow selected, int alternativesCount)
    {
        var guidance = new List<string>();
        var overall = (selected.Overall ?? selected.RankScore).GetValueOrDefault(0);
        if (overall >= 70) guidance.Add("Use this material when its best feature aligns with the part requirement.");
        else if (overall >= 50) guidance.Add("Use this material for moderate requirements after checking the weakest axis.");
        else guidance.Add("Use this material mainly for low-load, visual or experimental parts.");

        if (alternativesCount > 0) guidance.Add("Review the listed alternatives if the application needs stronger overall performance.");
        if (selected.Tensile.GetValueOrDefault(0) < 35) guidance.Add("Do not choose it as a tensile-strength benchmark material.");
        if (selected.Impact.GetValueOrDefault(0) < 35) guidance.Add("Avoid selecting it for impact-focused testing or shock-loaded designs.");

        return guidance;
    }

    private static void AddStrengthIfAbove(List<string> output, string metric, double? selected, double? average, string note)
    {
        if (!selected.HasValue) return;
        if (selected.Value >= 70 || (average.HasValue && selected.Value >= average.Value + 5))
            output.Add($"{metric}: {selected.Value:0}/100. {note}");
    }

    private static void AddWeaknessIfBelow(List<string> output, string metric, double? selected, double? average, string note)
    {
        if (!selected.HasValue) return;
        if (selected.Value < 40 || (average.HasValue && selected.Value <= average.Value - 10))
            output.Add($"{metric}: {selected.Value:0}/100. {note}");
    }

    private static double? Difference(double? selected, double? average)
    {
        return selected.HasValue && average.HasValue ? selected.Value - average.Value : (double?)null;
    }

    private static string DescribeDelta(double? delta, string target)
    {
        if (!delta.HasValue) return "missing enough context for " + target;
        if (Math.Abs(delta.Value) < 3) return "roughly aligned with " + target;
        return delta.Value > 0
            ? $"above {target} by {delta.Value:0.#} points"
            : $"below {target} by {Math.Abs(delta.Value):0.#} points";
    }

    private static string GetPrimarySuitability(RankingRow selected)
    {
        var overall = (selected.Overall ?? selected.RankScore).GetValueOrDefault(0);
        if (overall >= 75) return "a strong candidate for engineering-oriented prints";
        if (overall >= 55) return "a balanced material for general functional prototypes";
        if (selected.Consistency.GetValueOrDefault(0) >= 65) return "a repeatable material for cosmetic, concept and low-load prototype work";
        return "a limited-use material that should be validated carefully before functional use";
    }

    private static (string Label, double Value) BestScoredMetric(RankingRow row)
    {
        var metrics = BuildMetricValueList(row).Where(item => item.Value.HasValue).Select(item => (item.Label, Value: item.Value!.Value)).ToList();
        return metrics.Count == 0 ? ("No scored metric", 0) : metrics.OrderByDescending(item => item.Value).First();
    }

    private static (string Label, double Value) WeakestScoredMetric(RankingRow row)
    {
        var metrics = BuildMetricValueList(row).Where(item => item.Value.HasValue).Select(item => (item.Label, Value: item.Value!.Value)).ToList();
        return metrics.Count == 0 ? ("No scored metric", 0) : metrics.OrderBy(item => item.Value).First();
    }

    private static IReadOnlyList<(string Label, double? Value)> BuildMetricValueList(RankingRow row)
    {
        return new[]
        {
            ("Overall", row.Overall ?? row.RankScore),
            ("Tensile", row.Tensile),
            ("Impact", row.Impact),
            ("Stiffness", row.Stiffness),
            ("Consistency", row.Consistency),
            ("Layer Adhesion", row.LayerAdhesion)
        };
    }

    private static (string RankText, string PercentileText) BuildMetricRank(double? selectedValue, IEnumerable<double?> values)
    {
        var present = values.Where(value => value.HasValue).Select(value => value!.Value).OrderByDescending(value => value).ToList();
        if (!selectedValue.HasValue || present.Count == 0) return ("—", "—");

        var rank = present.Count(value => value > selectedValue.Value) + 1;
        var lowerOrEqual = present.Count(value => value <= selectedValue.Value);
        var percentile = Math.Max(0, Math.Min(100, lowerOrEqual * 100.0 / present.Count));
        return ($"{rank} / {present.Count}", $"Better than {percentile:0}%");
    }

    private static string BuildEngineeringSummaryText(RankingRow selected, RankingRow? materialAverage, RankingRow? manufacturerAverage, string bestFeature, string weakestFeature)
    {
        var overall = selected.Overall ?? selected.RankScore;
        var materialDelta = overall.HasValue && (materialAverage?.Overall ?? materialAverage?.RankScore).HasValue
            ? overall.Value - (materialAverage!.Overall ?? materialAverage.RankScore)!.Value
            : (double?)null;
        var manufacturerDelta = overall.HasValue && (manufacturerAverage?.Overall ?? manufacturerAverage?.RankScore).HasValue
            ? overall.Value - (manufacturerAverage!.Overall ?? manufacturerAverage.RankScore)!.Value
            : (double?)null;

        var overallValue = overall.GetValueOrDefault(0);
        var level = overallValue >= 75
            ? "strong engineering profile"
            : overallValue >= 55
                ? "balanced mid-range engineering profile"
                : overallValue >= 35
                    ? "specialized or limited engineering profile"
                    : "low engineering profile";

        var materialText = materialDelta.HasValue
            ? (materialDelta.Value >= 0 ? $"above its material-family average by {materialDelta.Value:0.#} points" : $"below its material-family average by {Math.Abs(materialDelta.Value):0.#} points")
            : "without enough material-family average context";
        var manufacturerText = manufacturerDelta.HasValue
            ? (manufacturerDelta.Value >= 0 ? $"above its manufacturer average by {manufacturerDelta.Value:0.#} points" : $"below its manufacturer average by {Math.Abs(manufacturerDelta.Value):0.#} points")
            : "without enough manufacturer average context";

        return $"{selected.Label} has a {level}. It is {materialText} and {manufacturerText}. Its strongest measured axis is {bestFeature}, while the weakest axis is {weakestFeature}.";
    }

    private static string BuildEngineeringHighlight(RankingRow selected, string bestFeature, string weakestFeature)
    {
        if (selected.LayerAdhesion.GetValueOrDefault(0) >= 70) return "Strong layer adhesion";
        if (selected.Consistency.GetValueOrDefault(0) >= 80) return "High consistency";
        if (selected.Stiffness.GetValueOrDefault(0) >= 80) return "Very stiff profile";
        if (selected.Impact.GetValueOrDefault(0) >= 70) return "Impact capable";
        if (selected.Tensile.GetValueOrDefault(0) >= 70) return "Strong tensile profile";
        return bestFeature == weakestFeature ? "Review profile" : bestFeature;
    }

    private static IReadOnlyList<string> BuildRecommendedApplications(RankingRow selected)
    {
        var recommendations = new List<string>();
        var overall = selected.Overall ?? selected.RankScore;

        var overallValue = overall.GetValueOrDefault(0);
        var tensileValue = selected.Tensile.GetValueOrDefault(0);
        var impactValue = selected.Impact.GetValueOrDefault(0);
        var stiffnessValue = selected.Stiffness.GetValueOrDefault(0);
        var consistencyValue = selected.Consistency.GetValueOrDefault(0);
        var layerValue = selected.LayerAdhesion.GetValueOrDefault(0);

        if (overallValue >= 70 && tensileValue >= 55) recommendations.Add("Functional engineering parts");
        if (stiffnessValue >= 70) recommendations.Add("Rigid brackets, fixtures and shape-stable prototypes");
        if (impactValue >= 60) recommendations.Add("Impact-aware parts where toughness matters");
        if (layerValue >= 60) recommendations.Add("Parts where Z-axis bonding is important");
        if (consistencyValue >= 70) recommendations.Add("Repeatable print jobs and production-style batches");
        if (overallValue < 55 || tensileValue < 35 || impactValue < 35) recommendations.Add("Cosmetic parts, concept models or low-load prototypes");
        if (tensileValue < 35) recommendations.Add("Avoid high tensile load applications");
        if (impactValue < 35) recommendations.Add("Avoid high impact components");

        if (recommendations.Count == 0) recommendations.Add("General purpose use after application-specific validation");
        return recommendations.Distinct(StringComparer.CurrentCultureIgnoreCase).Take(6).ToList();
    }

    private static RankingRow? AverageRankingRow(string label, IEnumerable<RankingRow> source)
    {
        var rows = source.ToList();
        if (rows.Count == 0) return null;

        static double? AverageOrNull(IEnumerable<double?> values)
        {
            var present = values.Where(value => value.HasValue).Select(value => value!.Value).ToList();
            return present.Count == 0 ? null : present.Average();
        }

        return new RankingRow
        {
            Label = label,
            Manufacturer = "Average",
            BaseMaterial = rows.FirstOrDefault()?.BaseMaterial ?? string.Empty,
            Reinforcement = "Average",
            Overall = AverageOrNull(rows.Select(row => row.Overall ?? row.RankScore)),
            RankScore = AverageOrNull(rows.Select(row => row.RankScore ?? row.Overall)),
            Tensile = AverageOrNull(rows.Select(row => row.Tensile)),
            Impact = AverageOrNull(rows.Select(row => row.Impact)),
            Stiffness = AverageOrNull(rows.Select(row => row.Stiffness)),
            Consistency = AverageOrNull(rows.Select(row => row.Consistency)),
            LayerAdhesion = AverageOrNull(rows.Select(row => row.LayerAdhesion)),
            BestAxis = "average"
        };
    }

    private string BuildMetricComparisonTableHtml(string title, RankingRow selected, RankingRow? average)
    {
        if (average is null) return string.Empty;

        var rows = BuildMetricTriples(selected, average).Select(metric =>
        {
            var deltaText = metric.Delta.HasValue ? metric.Delta.Value.ToString("+0.#;-0.#;0", CultureInfo.CurrentCulture) + "/100" : "—";
            return $"<tr><td>{Html(metric.Label)}</td><td>{Html(FormatScore(metric.Selected))}</td><td>{Html(FormatScore(metric.Average))}</td><td>{Html(deltaText)}</td></tr>";
        });

        return $"<div class=\"radar-card\"><div class=\"chart-title\">{Html(title)}</div><table class=\"comparison-table\"><thead><tr><th>Metric</th><th>Selected</th><th>Average</th><th>Delta</th></tr></thead><tbody>{string.Join("", rows)}</tbody></table></div>";
    }

    private static IEnumerable<(string Label, double? Selected, double? Average, double? Delta)> BuildMetricTriples(RankingRow selected, RankingRow average)
    {
        var pairs = new (string Label, double? Selected, double? Average)[]
        {
            ("Overall", selected.Overall ?? selected.RankScore, average.Overall ?? average.RankScore),
            ("Tensile", selected.Tensile, average.Tensile),
            ("Impact", selected.Impact, average.Impact),
            ("Stiffness", selected.Stiffness, average.Stiffness),
            ("Consistency", selected.Consistency, average.Consistency),
            ("Layer Adhesion", selected.LayerAdhesion, average.LayerAdhesion)
        };

        foreach (var pair in pairs)
        {
            yield return (pair.Label, pair.Selected, pair.Average, pair.Selected.HasValue && pair.Average.HasValue ? pair.Selected.Value - pair.Average.Value : null);
        }
    }

    private string BuildRadarChartHtml(string title, RankingRow selected, RankingRow? materialAverage, RankingRow? manufacturerAverage)
    {
        var selectedPoints = BuildRadarPolygonPoints(selected);
        if (string.IsNullOrWhiteSpace(selectedPoints)) return string.Empty;

        var materialAveragePoints = materialAverage is null ? string.Empty : BuildRadarPolygonPoints(materialAverage);
        var manufacturerAveragePoints = manufacturerAverage is null ? string.Empty : BuildRadarPolygonPoints(manufacturerAverage);
        var labels = new[]
        {
            (Text: "Overall", X: 210, Y: 28),
            (Text: "Tensile", X: 350, Y: 112),
            (Text: "Impact", X: 350, Y: 286),
            (Text: "Stiffness", X: 210, Y: 370),
            (Text: "Consistency", X: 48, Y: 286),
            (Text: "Layer", X: 48, Y: 112)
        };

        var labelHtml = string.Join("", labels.Select(label => $"<text class=\"radar-label\" x=\"{label.X}\" y=\"{label.Y}\" text-anchor=\"middle\">{Html(label.Text)}</text>"));
        var materialPoly = string.IsNullOrWhiteSpace(materialAveragePoints) ? string.Empty : $"<polygon class=\"radar-poly-material-average\" points=\"{materialAveragePoints}\"/>";
        var manufacturerPoly = string.IsNullOrWhiteSpace(manufacturerAveragePoints) ? string.Empty : $"<polygon class=\"radar-poly-manufacturer-average\" points=\"{manufacturerAveragePoints}\"/>";
        var materialLegend = string.IsNullOrWhiteSpace(materialAveragePoints)
            ? string.Empty
            : $"<span><span class=\"legend-line material\"></span>{Html(materialAverage!.Label)}</span>";
        var manufacturerLegend = string.IsNullOrWhiteSpace(manufacturerAveragePoints)
            ? string.Empty
            : $"<span><span class=\"legend-line manufacturer\"></span>{Html(manufacturerAverage!.Label)}</span>";

        return $"<div class=\"radar-card\"><div class=\"chart-title\">{Html(title)}</div><svg class=\"radar-svg\" viewBox=\"0 0 420 400\" role=\"img\" aria-label=\"Engineering radar chart\">" +
               "<polygon class=\"radar-grid\" points=\"210,72 323,135 323,265 210,328 97,265 97,135\"/>" +
               "<polygon class=\"radar-grid\" points=\"210,124 278,162 278,238 210,276 142,238 142,162\"/>" +
               "<line class=\"radar-axis\" x1=\"210\" y1=\"200\" x2=\"210\" y2=\"54\"/><line class=\"radar-axis\" x1=\"210\" y1=\"200\" x2=\"336\" y2=\"127\"/><line class=\"radar-axis\" x1=\"210\" y1=\"200\" x2=\"336\" y2=\"273\"/><line class=\"radar-axis\" x1=\"210\" y1=\"200\" x2=\"210\" y2=\"346\"/><line class=\"radar-axis\" x1=\"210\" y1=\"200\" x2=\"84\" y2=\"273\"/><line class=\"radar-axis\" x1=\"210\" y1=\"200\" x2=\"84\" y2=\"127\"/>" +
               materialPoly + manufacturerPoly + $"<polygon class=\"radar-poly-selected\" points=\"{selectedPoints}\"/>" + labelHtml + "</svg>" +
               "<div class=\"legend\"><span><span class=\"legend-line\"></span>Selected material</span>" + materialLegend + manufacturerLegend + "</div></div>";
    }

    private string BuildRadarPolygonPoints(RankingRow row)
    {
        var values = new[]
        {
            row.Overall ?? row.RankScore,
            row.Tensile,
            row.Impact,
            row.Stiffness,
            row.Consistency,
            row.LayerAdhesion
        };

        if (!values.Any(value => value.HasValue)) return string.Empty;

        var points = new List<string>();
        for (var i = 0; i < values.Length; i++)
        {
            var score = Math.Max(0, Math.Min(100, values[i] ?? 0));
            var angle = (-90 + i * 60) * Math.PI / 180.0;
            var radius = 146 * (score / 100.0);
            var x = 210 + Math.Cos(angle) * radius;
            var y = 200 + Math.Sin(angle) * radius;
            points.Add(x.ToString("0.#", CultureInfo.InvariantCulture) + "," + y.ToString("0.#", CultureInfo.InvariantCulture));
        }

        return string.Join(" ", points);
    }

