    private EngineeringIntelligenceHandoff BuildEngineeringReportHandoff(VideoPlannerRow selected, IReadOnlyList<VideoPlannerRow> contextRows)
    {
        var candidates = contextRows
            .Where(row => !string.IsNullOrWhiteSpace(row.MaterialId))
            .GroupBy(row => row.MaterialId, StringComparer.OrdinalIgnoreCase)
            .Select(group => ToReportAdvisorCandidate(group.First()))
            .ToList();
        var selectedCandidate = ToReportAdvisorCandidate(selected);
        if (candidates.All(candidate => !candidate.MaterialId.Equals(selected.MaterialId, StringComparison.OrdinalIgnoreCase)))
            candidates.Add(selectedCandidate);

        var comparison = candidates
            .Where(candidate => !candidate.MaterialId.Equals(selected.MaterialId, StringComparison.OrdinalIgnoreCase))
            .Where(candidate => candidate.Profile.OverallScore.HasValue && selected.OverallScore.HasValue)
            .OrderBy(candidate => Math.Abs(candidate.Profile.OverallScore!.Value - selected.OverallScore!.Value))
            .FirstOrDefault();
        var advisor = _engineeringAdvisorService.Explain(selectedCandidate, comparison);
        var consistency = _engineeringConsistencyService.Analyze(selected.VerifiedSummary, selected.ConsistencyScore);
        var context = _engineeringContextService.Analyze(
            selected.MaterialId,
            selected.Manufacturer,
            selected.PricePerKg,
            BuildInventorySummary(),
            _database.LoadManufacturers());
        var peer = _engineeringPeerPositionService.Analyze(
            selected.MaterialId,
            contextRows.Select(row => new EngineeringPeerCandidate
            {
                MaterialId = row.MaterialId,
                Label = row.Label,
                Manufacturer = row.Manufacturer,
                Category = row.Category,
                OverallScore = row.OverallScore
            }).ToList());
        var alternatives = _engineeringAdvisorService.FindAlternatives(selectedCandidate, candidates);

        return _engineeringIntelligenceHandoffService.Build(advisor, consistency, context, peer, alternatives);
    }

    private static EngineeringAdvisorCandidate ToReportAdvisorCandidate(VideoPlannerRow row) => new()
    {
        MaterialId = row.MaterialId,
        Label = row.Label,
        RecommendationType = "Material engineering report",
        Category = row.Category,
        BaseMaterial = row.BaseMaterial,
        RecommendationScore = row.OverallScore ?? 0,
        PricePerKg = row.PricePerKg,
        Profile = new EngineeringScoreProfile
        {
            OverallScore = row.OverallScore,
            TensileScore = row.TensileScore,
            ImpactScore = row.ImpactScore,
            StiffnessScore = row.StiffnessScore,
            ConsistencyScore = row.ConsistencyScore,
            LayerAdhesionScore = row.LayerAdhesionScore
        }
    };

    private string BuildMaterialSummaryReportHtml(string title, string key, DateTime generatedAt, IReadOnlyList<DataRow> rows, int totalRows)
    {
        var verifiedSummaries = BuildVerifiedMaterialSummaryMap(GetNativeWebsiteExportCandidateRows());
        var summaries = rows
            .Select(row =>
            {
                var materialId = (GetCell(row, "Material ID", "MaterialID") ?? string.Empty).Trim();
                verifiedSummaries.TryGetValue(materialId, out var summary);
                var video = BuildVideoPlannerRow(row, verifiedSummaries);
                return (Source: row, Video: video, Summary: summary, Ranking: BuildRankingRow(video, "Overall"));
            })
            .ToList();
        var tested = summaries.Count(item => item.Summary?.HasAnyResults == true);
        var completeProfiles = summaries.Count(item => item.Summary?.IsCompleteEngineeringSummary == true);
        var partialProfiles = Math.Max(0, tested - completeProfiles);
        var noEvidence = Math.Max(0, rows.Count - tested);
        var manufacturers = summaries.Select(item => item.Ranking.Manufacturer).Where(value => !string.IsNullOrWhiteSpace(value)).Distinct(StringComparer.CurrentCultureIgnoreCase).Count();
        var materialTypes = summaries.Select(item => item.Ranking.BaseMaterial).Where(value => !string.IsNullOrWhiteSpace(value)).Distinct(StringComparer.CurrentCultureIgnoreCase).Count();

        var coverageRows = new[]
        {
            ("Tensile", summaries.Count(item => item.Summary?.HasTensileResults == true)),
            ("Impact", summaries.Count(item => item.Summary?.HasImpactResults == true)),
            ("Stiffness", summaries.Count(item => item.Summary?.HasStiffnessResults == true)),
            ("Consistency score available", summaries.Count(item => item.Ranking.Consistency.HasValue)),
            ("Layer adhesion score available", summaries.Count(item => item.Ranking.LayerAdhesion.HasValue))
        };
        var coverageTable = string.Join("", coverageRows.Select(item =>
            $"<tr><td>{Html(item.Item1)}</td><td>{item.Item2}</td><td>{FormatCoveragePercent(item.Item2, rows.Count)}</td></tr>"));
        var materialRows = string.Join("", summaries.Select(item =>
            $"<tr><td>{Html(item.Video.MaterialId)}</td><td>{Html(item.Ranking.Label)}</td><td>{Html(DisplayText(item.Ranking.Manufacturer))}</td><td>{Html(DisplayText(item.Ranking.BaseMaterial))}</td><td>{Html(item.Summary?.SummaryStatus ?? "No native results")}</td><td>{Html(DisplayText(item.Ranking.Status))}</td><td>{BuildExternalReportLinkHtml(GetCell(item.Source, "YouTube Review URL", "Video URL", "YouTube URL"), "Watch video")}</td><td>{Html(item.Ranking.OverallText)}</td><td>{Html(item.Ranking.TensileText)}</td><td>{Html(item.Ranking.ImpactText)}</td><td>{Html(item.Ranking.StiffnessText)}</td><td>{Html(item.Ranking.ConsistencyText)}</td><td>{Html(item.Ranking.LayerAdhesionText)}</td></tr>"));
        var selectedIdentity = rows.Count == 1
            ? BuildMaterialSummaryIdentityHtml(rows[0])
            : string.Empty;
        var scopeDescription = BuildMaterialReportScopeDescription();

        var body =
            "<div class=\"note\"><strong>REPORT-110 - Material Summary:</strong> canonical material identity, test coverage and high-level verified engineering results. A verified test result means that at least one accepted tensile, impact, stiffness, consistency or layer-adhesion result is available in the governed material summary. It does not refer to video, price or database identity. Missing results are shown as n/a and are never calculated by the report layer.</div>" +
            $"<div class=\"note\"><strong>Report scope:</strong> {Html(scopeDescription)}</div>" +
            selectedIdentity +
            "<div class=\"cards\">" +
            $"<div class=\"card\"><div class=\"card-label\">Fully tested (3 modules)</div><div class=\"card-value\">{completeProfiles}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">Partially tested</div><div class=\"card-value\">{partialProfiles}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">No test results</div><div class=\"card-value\">{noEvidence}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">Manufacturers</div><div class=\"card-value\">{manufacturers}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">Material types</div><div class=\"card-value\">{materialTypes}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">Materials with test results</div><div class=\"card-value\">{tested}</div></div>" +
            "</div>" +
            "<h2>Native test-result coverage</h2><table><thead><tr><th>Engineering module / score</th><th>Materials</th><th>Coverage</th></tr></thead><tbody>" + coverageTable + "</tbody></table>" +
            BuildDistributionBarChartHtml("Material type distribution", MaterialTypeDistribution(rows)) +
            BuildDistributionBarChartHtml("Manufacturer distribution", ManufacturerDistribution(rows)) +
            "<h2>Materials in report scope</h2><table><thead><tr><th>MaterialID</th><th>Material</th><th>Manufacturer</th><th>Type</th><th>Test coverage</th><th>Publishing status</th><th>Video</th><th>Overall</th><th>Tensile</th><th>Impact</th><th>Stiffness</th><th>Consistency</th><th>Layer adhesion</th></tr></thead><tbody>" + materialRows + "</tbody></table>" +
            BuildMaterialSummarySourceHtml();

        return BuildReportHtmlShell(title, key, generatedAt, rows, totalRows, body);
    }

    private static string FormatCoveragePercent(int count, int total)
    {
        return total <= 0 ? "0%" : $"{(double)count / total * 100:0.#}%";
    }

