    private static string BuildExternalReportLinkHtml(string? url, string label)
    {
        var value = url?.Trim() ?? string.Empty;
        if (!Uri.TryCreate(value, UriKind.Absolute, out var uri) ||
            (uri.Scheme != Uri.UriSchemeHttp && uri.Scheme != Uri.UriSchemeHttps))
        {
            return "&mdash;";
        }

        return $"<a href=\"{Html(uri.AbsoluteUri)}\" target=\"_blank\" rel=\"noopener noreferrer\">{Html(label)}</a>";
    }

