    private void AppendComparisonReportPreview(StringBuilder sb, IReadOnlyList<DataRow> rows, IReadOnlyList<DataRow> contextRows, bool selectedScope)
    {
        var comparisonRows = ResolveComparisonReportMaterials(rows, contextRows, selectedScope);
        sb.AppendLine("Comparison Report - REPORT-120");
        sb.AppendLine("==============================");
        sb.AppendLine(selectedScope
            ? "Selected material compared with up to five closest visible engineering peers; same-base-material peers are preferred."
            : "All currently visible materials compared across existing governed engineering score axes.");
        sb.AppendLine("Missing verified results remain n/a. The report layer does not calculate test values.");
        sb.AppendLine($"Materials compared: {comparisonRows.Count}");
        sb.AppendLine($"Scope definition: {BuildMaterialReportScopeDescription()}");
        sb.AppendLine();

        foreach (var item in comparisonRows.Take(10))
        {
            var reason = string.IsNullOrWhiteSpace(item.ContextReason) ? string.Empty : $" | {item.ContextReason}";
            sb.AppendLine($"- {item.Ranking.Label} | Overall {item.Ranking.OverallText} | Tensile {item.Ranking.TensileText} | Impact {item.Ranking.ImpactText} | Stiffness {item.Ranking.StiffnessText} | Evidence {item.EvidenceAxes}/5{reason}");
        }

        if (comparisonRows.Count > 10)
        {
            sb.AppendLine($"Preview showing first 10 of {comparisonRows.Count} compared materials. Export Current Report includes the full comparison scope.");
        }
    }

    private string BuildComparisonReportHtml(string title, string key, DateTime generatedAt, IReadOnlyList<DataRow> rows, IReadOnlyList<DataRow> contextRows, int totalRows, bool selectedScope)
    {
        var comparisonRows = ResolveComparisonReportMaterials(rows, contextRows, selectedScope);
        var rankings = comparisonRows.Select(item => item.Ranking).ToList();
        var selected = selectedScope && comparisonRows.Count > 0 ? comparisonRows[0] : null;
        var scored = comparisonRows.Count(item => item.Ranking.Overall.HasValue);
        var completeEvidence = comparisonRows.Count(item => item.EvidenceAxes == 5);
        var sameFamilyPeers = selected is null
            ? 0
            : comparisonRows.Skip(1).Count(item => SameText(item.Ranking.BaseMaterial, selected.Ranking.BaseMaterial));

        var scopeText = selected is null
            ? BuildMaterialReportScopeDescription()
            : $"Selected anchor: {selected.Ranking.Label} ({selected.MaterialId}). Compared with {Math.Max(0, comparisonRows.Count - 1)} visible peers; same-base-material peers are preferred before closest overall-score distance.";

        var axisDefinitions = new (string Name, Func<RankingRow, double?> Value)[]
        {
            ("Overall", row => row.Overall),
            ("Tensile", row => row.Tensile),
            ("Impact", row => row.Impact),
            ("Stiffness", row => row.Stiffness),
            ("Consistency", row => row.Consistency),
            ("Layer adhesion", row => row.LayerAdhesion)
        };
        var leaderRows = axisDefinitions.Select(axis =>
        {
            var leader = rankings.Where(row => axis.Value(row).HasValue)
                .OrderByDescending(row => axis.Value(row))
                .ThenBy(row => row.Label, StringComparer.CurrentCultureIgnoreCase)
                .FirstOrDefault();
            return leader is null
                ? $"<tr><td>{Html(axis.Name)}</td><td>&mdash;</td><td>n/a</td></tr>"
                : $"<tr><td>{Html(axis.Name)}</td><td>{Html(leader.Label)}</td><td>{Html(FormatScore(axis.Value(leader)))}</td></tr>";
        });

        var identityRows = comparisonRows.Select(item =>
        {
            var rowClass = ReferenceEquals(item, selected) ? " class=\"selected-comparison\"" : string.Empty;
            var reason = string.IsNullOrWhiteSpace(item.ContextReason) ? "—" : item.ContextReason;
            return $"<tr{rowClass}><td>{Html(item.MaterialId)}</td><td>{Html(item.Ranking.Label)}</td><td>{Html(DisplayText(item.Ranking.Manufacturer))}</td><td>{Html(DisplayText(item.Ranking.BaseMaterial))}</td><td>{Html(DisplayText(item.Ranking.Reinforcement))}</td><td>{Html(item.TestCoverage)}</td><td>{item.EvidenceAxes}/5</td><td>{Html(reason)}</td></tr>";
        });
        var scoreRows = comparisonRows.Select(item =>
        {
            var anchor = selected?.Ranking;
            var rowClass = ReferenceEquals(item, selected) ? " class=\"selected-comparison\"" : string.Empty;
            var delta = selected is null || ReferenceEquals(item, selected)
                ? "&mdash;"
                : Html(FormatComparisonDelta(item.Ranking.Overall, anchor?.Overall));
            var price = item.Video.PricePerKg.HasValue && item.Video.PricePerKg.Value > 0
                ? "$" + item.Video.PricePerKg.Value.ToString("0.00", CultureInfo.InvariantCulture) + "/kg"
                : "n/a";
            return $"<tr{rowClass}><td>{Html(item.Ranking.Label)}</td><td>{Html(item.Ranking.OverallText)}</td><td>{delta}</td><td>{Html(item.Ranking.TensileText)}</td><td>{Html(item.Ranking.ImpactText)}</td><td>{Html(item.Ranking.StiffnessText)}</td><td>{Html(item.Ranking.ConsistencyText)}</td><td>{Html(item.Ranking.LayerAdhesionText)}</td><td>{Html(price)}</td></tr>";
        });

        var selectedContext = selected is null
            ? string.Empty
            : "<div class=\"note\"><strong>Selected comparison anchor:</strong> The highlighted row is the selected material. Positive/negative overall deltas show each peer relative to that selected score. A score delta is comparative context, not a statistical confidence interval or proof of fitness for a specific application.</div>";

        var body =
            "<div class=\"note\"><strong>REPORT-120 - Engineering Comparison:</strong> side-by-side comparison of existing governed engineering scores and Verified Material Summary coverage. Missing results are shown as n/a. This report does not recalculate tensile, impact, stiffness, consistency or layer-adhesion results and does not replace manufacturer datasheets.</div>" +
            $"<div class=\"note\"><strong>Comparison scope:</strong> {Html(scopeText)}</div>" +
            selectedContext +
            "<div class=\"cards\">" +
            $"<div class=\"card\"><div class=\"card-label\">Materials compared</div><div class=\"card-value\">{comparisonRows.Count}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">Overall score available</div><div class=\"card-value\">{scored}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">All 5 axes available</div><div class=\"card-value\">{completeEvidence}</div></div>" +
            (selected is null ? string.Empty : $"<div class=\"card\"><div class=\"card-label\">Same material-family peers</div><div class=\"card-value\">{sameFamilyPeers}</div></div>") +
            "</div>" +
            "<h2>Engineering-axis leaders in this comparison</h2><table><thead><tr><th>Axis</th><th>Leading material</th><th>Score</th></tr></thead><tbody>" + string.Join("", leaderRows) + "</tbody></table>" +
            "<div class=\"chart-grid\">" +
            BuildScoreBarChartHtml("Overall comparison", rankings, row => row.Overall) +
            BuildScoreBarChartHtml("Tensile comparison", rankings, row => row.Tensile) +
            BuildScoreBarChartHtml("Impact comparison", rankings, row => row.Impact) +
            BuildScoreBarChartHtml("Stiffness comparison", rankings, row => row.Stiffness) +
            "</div>" +
            "<h2>Materials and evidence context</h2><table><thead><tr><th>MaterialID</th><th>Material</th><th>Manufacturer</th><th>Type</th><th>Reinforcement</th><th>Test coverage</th><th>Evidence</th><th>Comparison context</th></tr></thead><tbody>" + string.Join("", identityRows) + "</tbody></table>" +
            "<h2>Side-by-side engineering scores</h2><table class=\"comparison-table\"><thead><tr><th>Material</th><th>Overall</th><th>Δ vs selected</th><th>Tensile</th><th>Impact</th><th>Stiffness</th><th>Consistency</th><th>Layer adhesion</th><th>MSRP USD/kg</th></tr></thead><tbody>" + string.Join("", scoreRows) + "</tbody></table>" +
            BuildMaterialSummarySourceHtml();

        return BuildReportHtmlShell(title, key, generatedAt, comparisonRows.Select(item => item.Source).ToList(), totalRows, body);
    }

    private List<ComparisonReportMaterial> ResolveComparisonReportMaterials(IReadOnlyList<DataRow> rows, IReadOnlyList<DataRow> contextRows, bool selectedScope)
    {
        var verifiedSummaries = GetCanonicalVerifiedSummaryMap();
        var context = BuildComparisonReportMaterials(contextRows, verifiedSummaries);
        if (!selectedScope || rows.Count == 0)
        {
            return BuildComparisonReportMaterials(rows, verifiedSummaries)
                .OrderByDescending(item => item.Ranking.Overall ?? double.MinValue)
                .ThenBy(item => item.Ranking.Label, StringComparer.CurrentCultureIgnoreCase)
                .ToList();
        }

        var selected = BuildComparisonReportMaterials(new[] { rows[0] }, verifiedSummaries).FirstOrDefault();
        if (selected is null) return context;
        selected.ContextReason = "Selected material";

        var peers = context
            .Where(item => !SameText(item.MaterialId, selected.MaterialId))
            .OrderByDescending(item => SameText(item.Ranking.BaseMaterial, selected.Ranking.BaseMaterial))
            .ThenBy(item => ComparisonScoreDistance(selected.Ranking.Overall, item.Ranking.Overall))
            .ThenBy(item => item.Ranking.Label, StringComparer.CurrentCultureIgnoreCase)
            .Take(5)
            .ToList();
        foreach (var peer in peers)
        {
            peer.ContextReason = SameText(peer.Ranking.BaseMaterial, selected.Ranking.BaseMaterial)
                ? "Same base material; closest visible score context"
                : "Closest remaining visible score context";
        }

        return new[] { selected }.Concat(peers).ToList();
    }

    private List<ComparisonReportMaterial> BuildComparisonReportMaterials(IEnumerable<DataRow> rows, IReadOnlyDictionary<string, MaterialResults> verifiedSummaries)
    {
        return rows
            .Select(row =>
            {
                var materialId = GetCell(row, "Material ID", "MaterialID").Trim();
                verifiedSummaries.TryGetValue(materialId, out var summary);
                var video = BuildVideoPlannerRow(row, verifiedSummaries);
                var ranking = BuildRankingRow(video, "Overall");
                var evidenceAxes = new[] { ranking.Tensile, ranking.Impact, ranking.Stiffness, ranking.Consistency, ranking.LayerAdhesion }.Count(value => value.HasValue);
                return new ComparisonReportMaterial
                {
                    Source = row,
                    Video = video,
                    Ranking = ranking,
                    MaterialId = materialId,
                    TestCoverage = summary?.SummaryStatus ?? "No native results",
                    EvidenceAxes = evidenceAxes,
                    HasAnyResults = summary?.HasAnyResults == true,
                    IsCompleteEngineeringSummary = summary?.IsCompleteEngineeringSummary == true
                };
            })
            .Where(item => !string.IsNullOrWhiteSpace(item.MaterialId))
            .GroupBy(item => item.MaterialId, StringComparer.OrdinalIgnoreCase)
            .Select(group => group.First())
            .ToList();
    }

    private static double ComparisonScoreDistance(double? anchor, double? candidate) =>
        anchor.HasValue && candidate.HasValue ? Math.Abs(anchor.Value - candidate.Value) : double.MaxValue;

    private static string FormatComparisonDelta(double? value, double? anchor)
    {
        if (!value.HasValue || !anchor.HasValue) return "n/a";
        var delta = value.Value - anchor.Value;
        return delta > 0 ? $"+{delta:0.#}" : delta.ToString("0.#", CultureInfo.CurrentCulture);
    }

