    private void AppendManufacturerReportPreview(StringBuilder sb, IReadOnlyList<DataRow> rows, IReadOnlyList<DataRow> visibleRows, bool selectedScope)
    {
        var portfolios = ResolveManufacturerReportPortfolios(rows, visibleRows, selectedScope);
        sb.AppendLine("Manufacturer Report - REPORT-130");
        sb.AppendLine("================================");
        sb.AppendLine(selectedScope
            ? "The selected material identifies the manufacturer; the report expands to that manufacturer's complete active portfolio."
            : "Manufacturer portfolios are built from the exact current visible Materials search/filter scope.");
        sb.AppendLine("Scores and coverage come from existing Verified Material Summary outputs; missing values remain n/a.");
        sb.AppendLine($"Manufacturers in report: {portfolios.Count}");
        sb.AppendLine($"Materials in manufacturer scope: {portfolios.Sum(portfolio => portfolio.Materials.Count)}");
        sb.AppendLine();

        foreach (var portfolio in portfolios.Take(10))
        {
            sb.AppendLine($"- {portfolio.Manufacturer} | {portfolio.Materials.Count} materials | {portfolio.MaterialsWithResults} with results | {portfolio.CompleteProfiles} complete profiles | Average overall {FormatScore(portfolio.AverageOverall)} | Leader {DisplayText(portfolio.StrongestMaterial)}");
        }

        if (portfolios.Count > 10)
        {
            sb.AppendLine($"Preview showing first 10 of {portfolios.Count} manufacturers. Export Current Report includes the full scope.");
        }
    }

    private string BuildManufacturerReportHtml(string title, string key, DateTime generatedAt, IReadOnlyList<DataRow> rows, IReadOnlyList<DataRow> visibleRows, int totalRows, bool selectedScope)
    {
        var portfolios = ResolveManufacturerReportPortfolios(rows, visibleRows, selectedScope);
        var selectedMaterialId = selectedScope && rows.Count > 0 ? GetCell(rows[0], "Material ID", "MaterialID") : string.Empty;
        var selectedMaterialLabel = selectedScope && rows.Count > 0 ? _detailService.BuildTitle(rows[0]) : string.Empty;
        var allActiveMaterials = BuildComparisonReportMaterials(GetCanonicalActiveMaterialRows(), GetCanonicalVerifiedSummaryMap());
        var globalPortfolios = BuildManufacturerReportPortfolios(allActiveMaterials);
        var rankedManufacturers = globalPortfolios
            .Where(portfolio => portfolio.AverageOverall.HasValue)
            .OrderByDescending(portfolio => portfolio.AverageOverall)
            .ThenBy(portfolio => portfolio.Manufacturer, StringComparer.CurrentCultureIgnoreCase)
            .ToList();
        var materialsInScope = portfolios.Sum(portfolio => portfolio.Materials.Count);
        var testedInScope = portfolios.Sum(portfolio => portfolio.MaterialsWithResults);
        var completeInScope = portfolios.Sum(portfolio => portfolio.CompleteProfiles);
        var typesInScope = portfolios.SelectMany(portfolio => portfolio.Materials.Select(item => item.Ranking.BaseMaterial))
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .Distinct(StringComparer.CurrentCultureIgnoreCase)
            .Count();

        var scopeText = selectedScope && rows.Count > 0
            ? $"The selected material identifies {DisplayText(GetCell(rows[0], "Manufacturer", "Brand"))}. This report includes that manufacturer's complete active portfolio from canonical MaterialID records, regardless of the current Materials filter."
            : BuildMaterialReportScopeDescription() + " Manufacturer portfolios and counts use only that visible set.";
        var selectionSourceHtml = selectedScope && rows.Count > 0
            ? $"<div class=\"note\"><strong>Selected source material:</strong> {Html(DisplayText(selectedMaterialLabel))} ({Html(DisplayText(selectedMaterialId))}). This material chooses the manufacturer; the report then expands to the full active manufacturer portfolio. The selected source row is highlighted in the product table.</div>"
            : string.Empty;

        var overviewRows = portfolios.Select(portfolio =>
        {
            var globalRankIndex = rankedManufacturers.FindIndex(item => SameText(item.Manufacturer, portfolio.Manufacturer));
            var globalRank = globalRankIndex >= 0 ? $"{globalRankIndex + 1} of {rankedManufacturers.Count}" : "n/a";
            return $"<tr><td>{Html(portfolio.Manufacturer)}</td><td>{portfolio.Materials.Count}</td><td>{portfolio.ProductLines}</td><td>{portfolio.MaterialTypes}</td><td>{portfolio.MaterialsWithResults}</td><td>{portfolio.CompleteProfiles}</td><td>{Html(FormatScore(portfolio.AverageOverall))}</td><td>{Html(globalRank)}</td><td>{Html(DisplayText(portfolio.StrongestMaterial))}</td><td>{Html(DisplayText(portfolio.StrongestAxis))}</td><td>{portfolio.MaterialsWithMsrp}</td><td>{portfolio.MaterialsWithVideo}</td></tr>";
        });

        var detailSections = portfolios.Select(portfolio =>
        {
            var manufacturerUrl = portfolio.Materials
                .Select(item => GetCell(item.Source, "Manufacturer Website", "Product Page", "Supplier URL"))
                .FirstOrDefault(value => Uri.TryCreate(value, UriKind.Absolute, out var uri) && (uri.Scheme == Uri.UriSchemeHttp || uri.Scheme == Uri.UriSchemeHttps));
            var materialRows = portfolio.Materials
                .OrderBy(item => item.Ranking.BaseMaterial, StringComparer.CurrentCultureIgnoreCase)
                .ThenBy(item => item.Ranking.Label, StringComparer.CurrentCultureIgnoreCase)
                .Select(item =>
                {
                    var price = item.Video.PricePerKg.HasValue && item.Video.PricePerKg.Value > 0
                        ? "$" + item.Video.PricePerKg.Value.ToString("0.00", CultureInfo.InvariantCulture) + "/kg"
                        : "n/a";
                    var productLink = BuildExternalReportLinkHtml(GetCell(item.Source, "Manufacturer Website", "Product Page", "Supplier URL"), "Product page");
                    var videoLink = BuildExternalReportLinkHtml(GetCell(item.Source, "YouTube Review URL", "Video URL", "YouTube URL"), "Video review");
                    var selectedRowStyle = selectedScope && SameText(item.MaterialId, selectedMaterialId)
                        ? " style=\"background:#e8f0ff;font-weight:600\""
                        : string.Empty;
                    var selectedMarker = selectedScope && SameText(item.MaterialId, selectedMaterialId) ? " (selected source)" : string.Empty;
                    return $"<tr{selectedRowStyle}><td>{Html(item.MaterialId)}</td><td>{Html(item.Ranking.Label + selectedMarker)}</td><td>{Html(DisplayText(GetCell(item.Source, "Product Line")))}</td><td>{Html(DisplayText(item.Ranking.BaseMaterial))}</td><td>{Html(DisplayText(item.Ranking.Reinforcement))}</td><td>{Html(item.TestCoverage)}</td><td>{item.EvidenceAxes}/5</td><td>{Html(item.Ranking.OverallText)}</td><td>{Html(item.Ranking.BestAxis)}</td><td>{Html(price)}</td><td>{productLink}</td><td>{videoLink}</td></tr>";
                });
            var categoryPosition = BuildManufacturerCategoryPositionHtml(portfolio, allActiveMaterials);
            var scoreCharts = "<div class=\"chart-grid\">" +
                BuildScoreBarChartHtml(portfolio.Manufacturer + " - overall leaders", portfolio.Materials.Select(item => item.Ranking), row => row.Overall) +
                BuildScoreBarChartHtml(portfolio.Manufacturer + " - consistency leaders", portfolio.Materials.Select(item => item.Ranking), row => row.Consistency) +
                "</div>";

            return $"<h2>{Html(portfolio.Manufacturer)}</h2>" +
                   $"<div class=\"note\"><strong>Manufacturer portfolio:</strong> {portfolio.Materials.Count} active/scoped materials across {portfolio.ProductLines} product lines and {portfolio.MaterialTypes} material types. Manufacturer website: {BuildExternalReportLinkHtml(manufacturerUrl, "Open manufacturer/product site")}.</div>" +
                   categoryPosition + scoreCharts +
                   "<h3>Product-level engineering context</h3><table><thead><tr><th>MaterialID</th><th>Material</th><th>Product line</th><th>Type</th><th>Reinforcement</th><th>Test coverage</th><th>Engineering axes</th><th>Overall</th><th>Strongest axis</th><th>MSRP USD/kg</th><th>Product</th><th>Video</th></tr></thead><tbody>" + string.Join("", materialRows) + "</tbody></table>";
        });

        var body =
            "<div class=\"note\"><strong>REPORT-130 - Manufacturer Intelligence:</strong> portfolio coverage, product-level engineering context and comparative manufacturer positioning from canonical MaterialID records and existing Verified Material Summary scores. No test measurement or score is calculated by the report layer. Missing evidence and price remain n/a.</div>" +
            $"<div class=\"note\"><strong>Manufacturer report scope:</strong> {Html(scopeText)}</div>" +
            selectionSourceHtml +
            "<div class=\"cards\">" +
            $"<div class=\"card\"><div class=\"card-label\">Manufacturers</div><div class=\"card-value\">{portfolios.Count}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">Materials</div><div class=\"card-value\">{materialsInScope}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">With test results</div><div class=\"card-value\">{testedInScope}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">Complete profiles</div><div class=\"card-value\">{completeInScope}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">Material types</div><div class=\"card-value\">{typesInScope}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">Global benchmark manufacturers</div><div class=\"card-value\">{globalPortfolios.Count}</div></div>" +
            "</div>" +
            "<h2>Manufacturer overview and global position</h2><table><thead><tr><th>Manufacturer</th><th>Materials</th><th>Product lines</th><th>Types</th><th>With results</th><th>Complete</th><th>Average overall</th><th>Global rank</th><th>Portfolio leader</th><th>Strongest axis</th><th>With MSRP</th><th>With video</th></tr></thead><tbody>" + string.Join("", overviewRows) + "</tbody></table>" +
            string.Join("", detailSections) +
            BuildMaterialSummarySourceHtml();

        var shellRows = portfolios.SelectMany(portfolio => portfolio.Materials).Select(item => item.Source).ToList();
        return BuildReportHtmlShell(title, key, generatedAt, shellRows, totalRows, body);
    }

    private List<ManufacturerReportPortfolio> ResolveManufacturerReportPortfolios(IReadOnlyList<DataRow> rows, IReadOnlyList<DataRow> visibleRows, bool selectedScope)
    {
        IReadOnlyList<DataRow> sourceRows = rows;
        if (selectedScope && rows.Count > 0)
        {
            var manufacturer = GetCell(rows[0], "Manufacturer", "Brand");
            var activeManufacturerRows = GetCanonicalActiveMaterialRows()
                .Where(row => SameText(GetCell(row, "Manufacturer", "Brand"), manufacturer))
                .ToList();
            sourceRows = activeManufacturerRows.Count > 0
                ? activeManufacturerRows
                : visibleRows.Where(row => SameText(GetCell(row, "Manufacturer", "Brand"), manufacturer)).ToList();
        }
        else if (!selectedScope)
        {
            sourceRows = visibleRows;
        }

        var materials = BuildComparisonReportMaterials(sourceRows, GetCanonicalVerifiedSummaryMap());
        return BuildManufacturerReportPortfolios(materials);
    }

    private List<ManufacturerReportPortfolio> BuildManufacturerReportPortfolios(IEnumerable<ComparisonReportMaterial> materials)
    {
        return materials
            .GroupBy(item => string.IsNullOrWhiteSpace(item.Ranking.Manufacturer) ? "Unknown manufacturer" : item.Ranking.Manufacturer.Trim(), StringComparer.CurrentCultureIgnoreCase)
            .Select(group =>
            {
                var rows = group.ToList();
                var scored = rows.Where(item => item.Ranking.Overall.HasValue).ToList();
                var strongest = scored.OrderByDescending(item => item.Ranking.Overall).ThenBy(item => item.Ranking.Label, StringComparer.CurrentCultureIgnoreCase).FirstOrDefault();
                return new ManufacturerReportPortfolio
                {
                    Manufacturer = group.Key,
                    Materials = rows,
                    ProductLines = rows.Select(item => GetCell(item.Source, "Product Line")).Where(value => !string.IsNullOrWhiteSpace(value)).Distinct(StringComparer.CurrentCultureIgnoreCase).Count(),
                    MaterialTypes = rows.Select(item => item.Ranking.BaseMaterial).Where(value => !string.IsNullOrWhiteSpace(value)).Distinct(StringComparer.CurrentCultureIgnoreCase).Count(),
                    MaterialsWithResults = rows.Count(item => item.HasAnyResults),
                    CompleteProfiles = rows.Count(item => item.IsCompleteEngineeringSummary),
                    MaterialsWithMsrp = rows.Count(item => item.Video.PricePerKg is > 0),
                    MaterialsWithVideo = rows.Count(item => !string.IsNullOrWhiteSpace(GetCell(item.Source, "YouTube Review URL", "Video URL", "YouTube URL"))),
                    AverageOverall = scored.Count == 0 ? null : scored.Average(item => item.Ranking.Overall!.Value),
                    StrongestMaterial = strongest?.Ranking.Label ?? string.Empty,
                    StrongestAxis = strongest?.Ranking.BestAxis ?? string.Empty
                };
            })
            .OrderBy(portfolio => portfolio.Manufacturer, StringComparer.CurrentCultureIgnoreCase)
            .ToList();
    }

    private string BuildManufacturerCategoryPositionHtml(ManufacturerReportPortfolio portfolio, IReadOnlyList<ComparisonReportMaterial> globalMaterials)
    {
        var rows = portfolio.Materials
            .Select(item => item.Ranking.BaseMaterial)
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .Distinct(StringComparer.CurrentCultureIgnoreCase)
            .OrderBy(value => value, StringComparer.CurrentCultureIgnoreCase)
            .Select(baseMaterial =>
            {
                var manufacturerScores = globalMaterials
                    .Where(item => SameText(item.Ranking.BaseMaterial, baseMaterial) && item.Ranking.Overall.HasValue)
                    .GroupBy(item => item.Ranking.Manufacturer, StringComparer.CurrentCultureIgnoreCase)
                    .Select(group => (Manufacturer: group.Key, Average: group.Average(item => item.Ranking.Overall!.Value), Materials: group.Count()))
                    .OrderByDescending(item => item.Average)
                    .ThenBy(item => item.Manufacturer, StringComparer.CurrentCultureIgnoreCase)
                    .ToList();
                var index = manufacturerScores.FindIndex(item => SameText(item.Manufacturer, portfolio.Manufacturer));
                var own = index >= 0 ? manufacturerScores[index] : default;
                return $"<tr><td>{Html(baseMaterial)}</td><td>{(index >= 0 ? $"{index + 1} of {manufacturerScores.Count}" : "n/a")}</td><td>{(index >= 0 ? Html(FormatScore(own.Average)) : "n/a")}</td><td>{(index >= 0 ? own.Materials.ToString(CultureInfo.InvariantCulture) : "0")}</td></tr>";
            });

        return "<h3>Category position by base material</h3><table><thead><tr><th>Base material</th><th>Manufacturer position</th><th>Average overall</th><th>Scored products</th></tr></thead><tbody>" + string.Join("", rows) + "</tbody></table>";
    }

    private sealed class TestSessionReportRecord
    {
        public DataRow Source { get; init; } = null!;
        public string MaterialId { get; init; } = string.Empty;
        public string Label { get; init; } = string.Empty;
        public string Manufacturer { get; init; } = string.Empty;
        public string BatchNumber { get; init; } = string.Empty;
        public MaterialResults? Summary { get; init; }
        public NativeTensileMeasurementRow? Tensile { get; init; }
        public NativeImpactMeasurementRow? Impact { get; init; }
        public NativeStiffnessMeasurementRow? Stiffness { get; init; }

        public int ModuleCount => Summary?.ResultModuleCount ?? 0;
        public int SpecimenCount =>
            (Summary?.Tensile?.Upright.SampleCount ?? 0) +
            (Summary?.Tensile?.Flat.SampleCount ?? 0) +
            (Summary?.Impact?.Upright.SampleCount ?? 0) +
            (Summary?.Impact?.Flat.SampleCount ?? 0) +
            (Summary?.HasStiffnessResults == true ? 1 : 0);
        public bool HasNotes => !string.IsNullOrWhiteSpace(Tensile?.TestNotes) ||
                                !string.IsNullOrWhiteSpace(Impact?.TestNotes) ||
                                !string.IsNullOrWhiteSpace(Stiffness?.TestNotes);
    }

