        var records = BuildTestSessionReportRecords(rows);
        var complete = records.Count(record => record.Summary?.IsCompleteEngineeringSummary == true);
        var modules = records.Sum(record => record.ModuleCount);
        var specimens = records.Sum(record => record.SpecimenCount);
