        });

        var selectedDetail = selectedScope && records.Count == 1
            ? BuildSelectedTestSessionDetailHtml(records[0])
            : string.Empty;
        var ledgerTitle = selectedScope ? "Selected material test-record summary" : "Test record ledger";
        var body =
            "<div class=\"note\"><strong>REPORT-140 - Test Session Traceability:</strong> native MaterialID-linked tensile, impact and stiffness inputs plus existing Verified Material Summary results. The report does not recalculate measurements and does not invent missing session metadata.</div>" +
            $"<div class=\"note\"><strong>Test Session report scope:</strong> {Html(scopeText)}</div>" +
            "<div class=\"note\"><strong>Traceability boundary:</strong> the current canonical test tables are material-linked records, not a dedicated session ledger. Session identifier, test timestamp, operator, printer/slicer profile and environmental conditions are therefore shown as Not recorded until those fields exist in SQLite.</div>" +
            "<div class=\"cards\">" +
