            $"<div class=\"card\"><div class=\"card-label\">Complete test records</div><div class=\"card-value\">{complete}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">Native result modules</div><div class=\"card-value\">{modules}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">Specimen/result records</div><div class=\"card-value\">{specimens}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">Records with notes</div><div class=\"card-value\">{withNotes}</div></div>" +
            "</div>" +
            selectedDetail + methodContext +
            $"<h2>{ledgerTitle}</h2><table><thead><tr><th>MaterialID</th><th>Material</th><th>Manufacturer</th><th>Batch</th><th>Status</th><th>Modules</th><th>Specimen/result records</th><th>Best tensile</th><th>Best impact</th><th>Stiffness</th><th>Notes</th></tr></thead><tbody>{string.Join("", ledgerRows)}</tbody></table>" +
            BuildMaterialSummarySourceHtml();

        return BuildReportHtmlShell(title, key, generatedAt, rows, totalRows, body);
    }

    private string BuildSelectedTestSessionDetailHtml(TestSessionReportRecord record)
    {
        var summary = record.Summary;
        var resultRows = new List<string>();
        AddSessionMeasurementRow(resultRows, "Tensile", "Upright", summary?.Tensile?.Upright, "MPa", record.Tensile?.ValidationSummary);
        AddSessionMeasurementRow(resultRows, "Tensile", "Flat", summary?.Tensile?.Flat, "MPa", record.Tensile?.ValidationSummary);
        AddSessionMeasurementRow(resultRows, "Impact", "Upright", summary?.Impact?.Upright, "kJ/m²", record.Impact?.ValidationSummary);
        AddSessionMeasurementRow(resultRows, "Impact", "Flat", summary?.Impact?.Flat, "kJ/m²", record.Impact?.ValidationSummary);
        resultRows.Add($"<tr><td>Stiffness</td><td>Three-point bend</td><td>{Html(FormatSessionMetric(summary?.Stiffness?.ModulusMpa, " MPa"))}</td><td>n/a</td><td>n/a</td><td>{(summary?.HasStiffnessResults == true ? "1" : "0")}</td><td>{Html(summary?.Stiffness?.CompletenessRating.Label ?? "n/a")}</td><td>{Html(record.Stiffness?.ValidationSummary ?? "No native record")}</td></tr>");

        var rawRows = new[]
        {
            BuildRawSessionRow("Tensile", "Upright force inputs (N)", record.Tensile?.SampleValues(true)),
            BuildRawSessionRow("Tensile", "Flat force inputs (N)", record.Tensile?.SampleValues(false)),
            BuildRawSessionRow("Impact", "Upright needle inputs (%)", record.Impact?.SampleValues(true)),
            BuildRawSessionRow("Impact", "Flat needle inputs (%)", record.Impact?.SampleValues(false)),
            $"<tr><td>Stiffness</td><td>Revolutions / degrees</td><td>{Html(DisplayText(record.Stiffness is null ? string.Empty : JoinNonEmpty(" / ", record.Stiffness.Revolutions, record.Stiffness.Degrees)))}</td></tr>"
        };
        var notes = new[]
        {
            (Module: "Tensile", Notes: record.Tensile?.TestNotes),
            (Module: "Impact", Notes: record.Impact?.TestNotes),
            (Module: "Stiffness", Notes: record.Stiffness?.TestNotes)
        }.Select(item => $"<tr><td>{item.Module}</td><td>{Html(DisplayText(item.Notes))}</td></tr>");

        return $"<h2>Selected material and traceability</h2><table><tbody>" +
               $"<tr><td>Material</td><td>{Html(record.Label)}</td></tr><tr><td>MaterialID</td><td>{Html(record.MaterialId)}</td></tr><tr><td>Manufacturer</td><td>{Html(record.Manufacturer)}</td></tr><tr><td>Batch / lot</td><td>{Html(DisplayText(record.BatchNumber))}</td></tr>" +
               "<tr><td>Session identifier</td><td>Not recorded</td></tr><tr><td>Test timestamp</td><td>Not recorded</td></tr><tr><td>Operator</td><td>Not recorded</td></tr><tr><td>Printer / slicer profile</td><td>Not recorded in the canonical test record</td></tr><tr><td>Environmental conditions</td><td>Not recorded</td></tr>" +
               "</tbody></table>" +
               "<h2>Specimen and result quality</h2><table><thead><tr><th>Module</th><th>Orientation</th><th>Average</th><th>Std. dev.</th><th>CV</th><th>Specimens</th><th>Confidence / completeness</th><th>Validation</th></tr></thead><tbody>" + string.Join("", resultRows) + "</tbody></table>" +
               "<h2>Recorded native inputs</h2><table><thead><tr><th>Module</th><th>Input set</th><th>Recorded values</th></tr></thead><tbody>" + string.Join("", rawRows) + "</tbody></table>" +
               "<h2>Test notes</h2><table><thead><tr><th>Module</th><th>Notes</th></tr></thead><tbody>" + string.Join("", notes) + "</tbody></table>";
    }

    private List<TestSessionReportRecord> BuildTestSessionReportRecords(IReadOnlyList<DataRow> rows)
    {
        var summaries = GetCanonicalVerifiedSummaryMap();
        var tensile = _nativeTensileRows.Where(row => !string.IsNullOrWhiteSpace(row.MaterialID)).GroupBy(row => row.MaterialID.Trim(), StringComparer.OrdinalIgnoreCase).ToDictionary(group => group.Key, group => group.First(), StringComparer.OrdinalIgnoreCase);
        var impact = _nativeImpactRows.Where(row => !string.IsNullOrWhiteSpace(row.MaterialID)).GroupBy(row => row.MaterialID.Trim(), StringComparer.OrdinalIgnoreCase).ToDictionary(group => group.Key, group => group.First(), StringComparer.OrdinalIgnoreCase);
        var stiffness = _nativeStiffnessRows.Where(row => !string.IsNullOrWhiteSpace(row.MaterialID)).GroupBy(row => row.MaterialID.Trim(), StringComparer.OrdinalIgnoreCase).ToDictionary(group => group.Key, group => group.First(), StringComparer.OrdinalIgnoreCase);

        return rows.Select(row =>
        {
            var materialId = GetCell(row, "Material ID", "MaterialID").Trim();
            summaries.TryGetValue(materialId, out var summary);
            tensile.TryGetValue(materialId, out var tensileRow);
            impact.TryGetValue(materialId, out var impactRow);
            stiffness.TryGetValue(materialId, out var stiffnessRow);
            return new TestSessionReportRecord
            {
                Source = row,
                MaterialId = materialId,
                Label = _detailService.BuildTitle(row),
                Manufacturer = GetCell(row, "Manufacturer", "Brand"),
                BatchNumber = GetCell(row, "Batch Number", "Batch", "Lot"),
                Summary = summary,
                Tensile = tensileRow,
                Impact = impactRow,
                Stiffness = stiffnessRow
            };
        }).ToList();
    }

    private static void AddSessionMeasurementRow(List<string> rows, string module, string orientation, MeasurementSetResult? result, string unit, string? validation)
    {
        rows.Add($"<tr><td>{Html(module)}</td><td>{Html(orientation)}</td><td>{Html(FormatSessionMetric(result?.Average, " " + unit))}</td><td>{Html(FormatSessionMetric(result?.StandardDeviation, " " + unit))}</td><td>{Html(FormatSessionMetric(result?.CoefficientOfVariation, "%"))}</td><td>{result?.SampleCount.ToString(CultureInfo.InvariantCulture) ?? "0"}</td><td>{Html(result?.Confidence.HasValue == true ? result.Confidence.Value.ToString(CultureInfo.InvariantCulture) + "/10" : "n/a")}</td><td>{Html(validation ?? "No native record")}</td></tr>");
    }

    private static string BuildRawSessionRow(string module, string inputSet, IEnumerable<string>? values)
    {
        var recorded = values?.Where(value => !string.IsNullOrWhiteSpace(value)).ToList() ?? new List<string>();
        return $"<tr><td>{Html(module)}</td><td>{Html(inputSet)}</td><td>{Html(recorded.Count == 0 ? "n/a" : string.Join(", ", recorded))}</td></tr>";
    }

    private static string FormatSessionMetric(double? value, string suffix) =>
        value.HasValue ? value.Value.ToString("0.###", CultureInfo.CurrentCulture) + suffix : "n/a";

    private void AppendPrintingRecommendationReportPreview(StringBuilder sb, IReadOnlyList<DataRow> rows, bool selectedScope)
    {
        var summaries = GetCanonicalVerifiedSummaryMap();
        var recommendations = rows
            .Select(row => BuildRankingRow(BuildVideoPlannerRow(row, summaries), "Overall"))
            .ToList();
        sb.AppendLine("Printing Recommendation Report - REPORT-150");
        sb.AppendLine("============================================");
        sb.AppendLine(selectedScope
            ? "Detailed printing-use guidance for the selected material."
            : "Recommendation ledger for the exact current visible Materials search/filter scope.");
        sb.AppendLine("Guidance is generated locally from governed engineering profiles; exact printer settings are not invented.");
        sb.AppendLine($"Materials in report: {recommendations.Count}");
        sb.AppendLine();

        foreach (var recommendation in recommendations.Take(10))
        {
            var application = BuildRecommendedApplications(recommendation).FirstOrDefault() ?? "Application-specific validation required";
            sb.AppendLine($"- {recommendation.Label} | Overall {FormatScore(recommendation.Overall ?? recommendation.RankScore)} | {application}");
        }

        if (recommendations.Count > 10)
        {
            sb.AppendLine($"Preview showing first 10 of {recommendations.Count} materials. Export Current Report includes the full recommendation ledger.");
        }
    }

    private string BuildPrintingRecommendationReportHtml(string title, string key, DateTime generatedAt, IReadOnlyList<DataRow> rows, IReadOnlyList<DataRow> contextRows, int totalRows, bool selectedScope)
    {
        var summaries = GetCanonicalVerifiedSummaryMap();
        var recommendationRows = rows
            .Select(row => (Source: row, Ranking: BuildRankingRow(BuildVideoPlannerRow(row, summaries), "Overall")))
            .ToList();
        var peerRows = contextRows
            .Select(row => BuildRankingRow(BuildVideoPlannerRow(row, summaries), "Overall"))
            .ToList();
        if (selectedScope && recommendationRows.Count == 1 && !peerRows.Any(row => SameText(row.MaterialId, recommendationRows[0].Ranking.MaterialId)))
        {
            peerRows.Add(recommendationRows[0].Ranking);
        }

        var withProfiles = recommendationRows.Count(item => (item.Ranking.Overall ?? item.Ranking.RankScore).HasValue);
        var completeAxes = recommendationRows.Count(item => BuildMetricValueList(item.Ranking).Skip(1).All(metric => metric.Value.HasValue));
        var withMsrp = recommendationRows.Count(item => item.Ranking.PricePerKg is > 0);
        var scopeText = selectedScope
            ? $"Selected material only: {DisplayText(recommendationRows.FirstOrDefault().Ranking?.Label)}. Peer comparisons use the current visible Materials context."
            : BuildMaterialReportScopeDescription() + " Recommendations and counts use only that visible set.";

        var ledgerRows = recommendationRows
            .OrderByDescending(item => item.Ranking.Overall ?? item.Ranking.RankScore ?? double.MinValue)
            .ThenBy(item => item.Ranking.Label, StringComparer.CurrentCultureIgnoreCase)
            .Select(item =>
            {
                var ranking = item.Ranking;
                var applications = BuildRecommendedApplications(ranking);
                var best = BestScoredMetric(ranking);
                var weakest = WeakestScoredMetric(ranking);
                var evidenceAxes = BuildMetricValueList(ranking).Skip(1).Count(metric => metric.Value.HasValue);
                var guidance = BuildPrintingDecisionSummary(ranking);
                return $"<tr><td>{Html(ranking.MaterialId)}</td><td>{Html(ranking.Label)}</td><td>{Html(DisplayText(ranking.BaseMaterial))}</td><td>{Html(FormatScore(ranking.Overall ?? ranking.RankScore))}</td><td>{evidenceAxes}/5</td><td>{Html(applications.FirstOrDefault() ?? "Application-specific validation required")}</td><td>{Html(best.Label)}</td><td>{Html(weakest.Label)}</td><td>{Html(ranking.PricePerKg.HasValue ? "$" + ranking.PricePerKg.Value.ToString("0.00", CultureInfo.InvariantCulture) + "/kg" : "n/a")}</td><td>{Html(guidance)}</td></tr>";
            });

        var selectedDetail = selectedScope && recommendationRows.Count == 1
            ? BuildSelectedPrintingRecommendationHtml(recommendationRows[0].Source, recommendationRows[0].Ranking, peerRows)
            : string.Empty;
        var body =
            "<div class=\"note\"><strong>REPORT-150 - Governed Printing Recommendation:</strong> application guidance, strengths, limitations and print-workflow checks composed from existing engineering score profiles and Verified Material Summary coverage. No measurement or score is recalculated here. No external AI or LLM is used.</div>" +
            $"<div class=\"note\"><strong>Printing Recommendation report scope:</strong> {Html(scopeText)}</div>" +
            "<div class=\"note\"><strong>Settings boundary:</strong> this report does not invent nozzle temperature, bed temperature, speed, cooling, drying or enclosure values. Confirm exact settings against the manufacturer profile, spool label and the actual printer/material combination before printing.</div>" +
            "<div class=\"cards\">" +
            $"<div class=\"card\"><div class=\"card-label\">Materials</div><div class=\"card-value\">{recommendationRows.Count}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">With engineering profile</div><div class=\"card-value\">{withProfiles}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">All five axes</div><div class=\"card-value\">{completeAxes}</div></div>" +
            $"<div class=\"card\"><div class=\"card-label\">With MSRP</div><div class=\"card-value\">{withMsrp}</div></div>" +
            "</div>" +
            selectedDetail +
            "<h2>Printing recommendation ledger</h2><table><thead><tr><th>MaterialID</th><th>Material</th><th>Type</th><th>Overall</th><th>Engineering axes</th><th>Primary application</th><th>Strongest axis</th><th>Main limitation</th><th>MSRP USD/kg</th><th>Decision guidance</th></tr></thead><tbody>" + string.Join("", ledgerRows) + "</tbody></table>" +
            BuildMaterialSummarySourceHtml();

        return BuildReportHtmlShell(title, key, generatedAt, rows, totalRows, body);
    }

    private string BuildSelectedPrintingRecommendationHtml(DataRow source, RankingRow selected, IReadOnlyList<RankingRow> peerRows)
    {
        var peers = peerRows.Count > 0 ? peerRows.ToList() : new List<RankingRow> { selected };
        var materialAverage = AverageRankingRow(
            "Material average - " + DisplayText(selected.BaseMaterial),
            peers.Where(row => SameText(row.BaseMaterial, selected.BaseMaterial)));
        var manufacturerAverage = AverageRankingRow(
            "Manufacturer average - " + DisplayText(selected.Manufacturer),
            peers.Where(row => SameText(row.Manufacturer, selected.Manufacturer)));
        var applications = BuildRecommendedApplications(selected);
        var strengths = BuildStrengthList(selected, materialAverage, manufacturerAverage);
        var weaknesses = BuildWeaknessList(selected, materialAverage, manufacturerAverage);
        var tradeoffs = BuildEngineeringTradeoffs(selected, materialAverage, manufacturerAverage);
        var alternatives = BuildBetterAlternativeRows(selected, peers);
        var evidenceAxes = BuildMetricValueList(selected).Skip(1).Count(metric => metric.Value.HasValue);
        var overallRank = BuildMetricRank(selected.Overall ?? selected.RankScore, peers.Select(row => row.Overall ?? row.RankScore));
        var price = selected.PricePerKg.HasValue
            ? "$" + selected.PricePerKg.Value.ToString("0.00", CultureInfo.InvariantCulture) + "/kg"
            : "n/a";
        var applicationItems = applications.Select(item => $"<li>{Html(item)}</li>");
        var strengthItems = strengths.Select(item => $"<li>{Html(item)}</li>");
        var weaknessItems = weaknesses.Select(item => $"<li>{Html(item)}</li>");
        var tradeoffItems = tradeoffs.Select(item => $"<li>{Html(item)}</li>");
        var workflowItems = BuildPrintingWorkflowChecks(source, selected).Select(item => $"<li>{Html(item)}</li>");
        var alternativeRows = alternatives.Count == 0
            ? "<tr><td colspan=\"7\">No stronger same-material alternatives were found in the current visible comparison context.</td></tr>"
            : string.Join("", alternatives.Select(row => $"<tr><td>{Html(row.MaterialId)}</td><td>{Html(row.Label)}</td><td>{Html(FormatScore(row.Overall ?? row.RankScore))}</td><td>{Html(FormatScore(row.Tensile))}</td><td>{Html(FormatScore(row.Impact))}</td><td>{Html(FormatScore(row.Stiffness))}</td><td>{Html(row.PricePerKg.HasValue ? "$" + row.PricePerKg.Value.ToString("0.00", CultureInfo.InvariantCulture) + "/kg" : "n/a")}</td></tr>"));

        return $"<h2>Selected printing recommendation</h2>" +
               "<div class=\"cards\">" +
               $"<div class=\"card\"><div class=\"card-label\">Material</div><div class=\"card-value\">{Html(selected.Label)}</div></div>" +
               $"<div class=\"card\"><div class=\"card-label\">Overall profile</div><div class=\"card-value\">{Html(FormatScore(selected.Overall ?? selected.RankScore))}</div></div>" +
               $"<div class=\"card\"><div class=\"card-label\">Engineering axes</div><div class=\"card-value\">{evidenceAxes}/5</div></div>" +
               $"<div class=\"card\"><div class=\"card-label\">Visible-context rank</div><div class=\"card-value\">{Html(overallRank.RankText)}</div></div>" +
               $"<div class=\"card\"><div class=\"card-label\">MSRP</div><div class=\"card-value\">{Html(price)}</div></div>" +
               "</div>" +
               BuildBarChartHtml("Selected engineering profile", BuildSelectedMaterialScoreItems(selected), "/100") +
               "<div class=\"review-section-grid\">" +
               "<div class=\"review-panel\"><div class=\"review-panel-title\">Recommended applications</div><ul class=\"review-list\">" + string.Join("", applicationItems) + "</ul></div>" +
               "<div class=\"review-panel\"><div class=\"review-panel-title\">Measured strengths</div><ul class=\"review-list\">" + string.Join("", strengthItems) + "</ul></div>" +
               "<div class=\"review-panel\"><div class=\"review-panel-title\">Limitations</div><ul class=\"review-list\">" + string.Join("", weaknessItems) + "</ul></div>" +
               "<div class=\"review-panel\"><div class=\"review-panel-title\">Engineering trade-offs</div><ul class=\"review-list\">" + string.Join("", tradeoffItems) + "</ul></div>" +
               "</div>" +
               "<h2>Print workflow checks</h2><div class=\"note\"><ul class=\"review-list\">" + string.Join("", workflowItems) + "</ul></div>" +
               "<h2>Decision guidance</h2><div class=\"note\"><ul class=\"review-list\">" + BuildDecisionGuidanceHtml(selected, alternatives.Count) + "</ul></div>" +
               "<h2>Stronger same-family alternatives</h2><table><thead><tr><th>MaterialID</th><th>Material</th><th>Overall</th><th>Tensile</th><th>Impact</th><th>Stiffness</th><th>MSRP USD/kg</th></tr></thead><tbody>" + alternativeRows + "</tbody></table>";
    }

    private static IReadOnlyList<string> BuildPrintingWorkflowChecks(DataRow source, RankingRow selected)
    {
        var checks = new List<string>
        {
            "Confirm nozzle temperature, bed temperature, speed, cooling and drying requirements from the manufacturer profile or spool label.",
            "Print a small validation part before committing to a long, costly or safety-relevant print.",
            "Orient the part so the governing load does not rely on an unverified or weak engineering axis."
        };
        var family = selected.BaseMaterial.ToUpperInvariant();
        var reinforcement = GetCell(source, "Reinforcement").ToUpperInvariant();
        if (reinforcement.Contains("CF") || reinforcement.Contains("GF"))
            checks.Add("Reinforced filament: confirm an abrasion-resistant nozzle and manufacturer drying/storage requirements.");
        if (family.Contains("ABS") || family.Contains("ASA") || family.Contains("PC") || family.StartsWith("PA", StringComparison.Ordinal))
            checks.Add("Engineering/high-temperature family: confirm enclosure, ventilation, warping control and material-specific drying requirements.");
        if (family.Contains("TPU") || family.Contains("TPE"))
            checks.Add("Flexible family: validate extrusion path, retraction and speed conservatively on the actual printer.");
        if (selected.LayerAdhesion.GetValueOrDefault(0) < 40)
            checks.Add("Layer-adhesion evidence is weak; avoid critical Z-axis loading without additional validation.");
        if (selected.Consistency.GetValueOrDefault(0) < 60)
            checks.Add("Repeatability is low on the internal scale; run extra validation specimens before relying on the profile.");
        return checks;
    }

    private static string BuildPrintingDecisionSummary(RankingRow ranking)
    {
        var overall = (ranking.Overall ?? ranking.RankScore).GetValueOrDefault(0);
        if (overall >= 70) return "Strong candidate when the leading axis matches the part requirement.";
        if (overall >= 50) return "Moderate candidate; review the weakest axis before functional use.";
        return "Use mainly for low-load or exploratory work unless further validation supports the application.";
    }

    private string BuildMaterialReportHtml(string title, string key, DateTime generatedAt, IReadOnlyList<DataRow> rows, int totalRows)
    {
        if (title == "Material Detail Report" && rows.Count == 1)
        {
            return BuildSelectedMaterialReportHtml(title, key, generatedAt, rows[0], totalRows);
        }

        var sampleRows = rows.Take(80).Select(row =>
        {
            var titleText = _detailService.BuildTitle(row);
            var manufacturer = GetCell(row, "Manufacturer", "Brand");
            var baseMaterial = GetCell(row, "Base Material", "Material Type", "Type");
            var reinforcement = GetCell(row, "Reinforcement", "Reinforment");
            var tensile = FormatMetricCell(row, "Tensile", "Tensile Strength", "Tensile MPa", "MPa");
            var impact = FormatMetricCell(row, "Impact", "Impact Strength", "Impact kJ/m2", "kJ/m²");
            var score = FormatMetricCell(row, "Overall Score", "Engineering Score", "Score", "");
            return $"<tr><td>{Html(titleText)}</td><td>{Html(manufacturer)}</td><td>{Html(baseMaterial)}</td><td>{Html(reinforcement)}</td><td>{Html(tensile)}</td><td>{Html(impact)}</td><td>{Html(score)}</td></tr>";
        });

        var body = "<div class=\"note\"><strong>Material report:</strong> summary of the currently visible material dataset. This report respects the Materials tab search/filter state.</div>" +
                   BuildDistributionBarChartHtml("Material type distribution", MaterialTypeDistribution(rows)) +
                   BuildDistributionBarChartHtml("Manufacturer distribution", ManufacturerDistribution(rows)) +
                   "<h2>Visible material sample</h2>\n<table><thead><tr><th>Material</th><th>Manufacturer</th><th>Type</th><th>Reinforcement</th><th>Tensile</th><th>Impact</th><th>Score</th></tr></thead><tbody>\n" +
                   string.Join("\n", sampleRows) +
                   "\n</tbody></table>\n";
        return BuildReportHtmlShell(title, key, generatedAt, rows, totalRows, body);
    }

