        }.Select(item => $"<tr><td>{Html(item.Item1)}</td><td>{Html(item.Item2)}</td></tr>");

        var body = $"<div class=\"note\"><strong>Selected material detail:</strong> {Html(video.Label)}. This report uses the selected row from the Materials grid instead of the full visible dataset.</div>" +
                   "<div class=\"cards\">" +
                   $"<div class=\"card\"><div class=\"card-label\">Material</div><div class=\"card-value\">{Html(video.Label)}</div></div>" +
                   $"<div class=\"card\"><div class=\"card-label\">Manufacturer</div><div class=\"card-value\">{Html(video.Manufacturer)}</div></div>" +
                   $"<div class=\"card\"><div class=\"card-label\">Type</div><div class=\"card-value\">{Html(video.BaseMaterial)}</div></div>" +
