                   "<h2>YouTube research notes</h2>\n<table><tbody>\n" +
                   $"<tr><td>Suggested title</td><td>{Html(video.SuggestedTitle)}</td></tr>" +
                   $"<tr><td>Angle</td><td>{Html(video.SuggestedAngle)}</td></tr>" +
                   $"<tr><td>Comparison idea</td><td>{Html(video.ComparisonIdea)}</td></tr>" +
