    private IReadOnlyList<(string Label, double Value)> BuildSelectedMaterialScoreItems(RankingRow ranking)
    {
        var items = new List<(string Label, double Value)>();
        if (ranking.Overall.HasValue) items.Add(("Overall", ranking.Overall.Value));
        if (ranking.Tensile.HasValue) items.Add(("Tensile", ranking.Tensile.Value));
        if (ranking.Impact.HasValue) items.Add(("Impact", ranking.Impact.Value));
        if (ranking.Stiffness.HasValue) items.Add(("Stiffness", ranking.Stiffness.Value));
        if (ranking.Consistency.HasValue) items.Add(("Consistency", ranking.Consistency.Value));
        if (ranking.LayerAdhesion.HasValue) items.Add(("Layer Adhesion", ranking.LayerAdhesion.Value));
        return items;
    }


    private string BuildSelectedRankingContextHtml(string title, string key, DateTime generatedAt, DataRow selectedRow, IReadOnlyList<DataRow> contextRows, int totalRows)
    {
        var selected = BuildRankingRow(BuildVideoPlannerRow(selectedRow), "Overall");
        var allRanked = contextRows
            .Select(row => BuildRankingRow(BuildVideoPlannerRow(row), "Overall"))
            .Where(row => row.RankScore.HasValue || row.Overall.HasValue || row.Tensile.HasValue || row.Impact.HasValue || row.Stiffness.HasValue)
            .ToList();

        var overall = BuildSelectedRankContext("Overall", allRanked, selected, row => true, row => row.Overall ?? row.RankScore);
        var type = BuildSelectedRankContext($"{DisplayText(selected.BaseMaterial)} rank", allRanked, selected, row => SameText(row.BaseMaterial, selected.BaseMaterial), row => row.Overall ?? row.RankScore);
        var manufacturer = BuildSelectedRankContext($"{DisplayText(selected.Manufacturer)} rank", allRanked, selected, row => SameText(row.Manufacturer, selected.Manufacturer), row => row.Overall ?? row.RankScore);
        var reinforcement = string.IsNullOrWhiteSpace(selected.Reinforcement) || selected.Reinforcement == "—"
            ? BuildSelectedRankContext("Unreinforced rank", allRanked, selected, row => string.IsNullOrWhiteSpace(row.Reinforcement) || row.Reinforcement == "—", row => row.Overall ?? row.RankScore)
            : BuildSelectedRankContext($"{selected.Reinforcement} rank", allRanked, selected, row => SameText(row.Reinforcement, selected.Reinforcement), row => row.Overall ?? row.RankScore);

        var rankRows = new[] { overall, type, manufacturer, reinforcement }
            .Where(item => item.Total > 0)
            .Select(item => $"<tr><td>{Html(item.Scope)}</td><td>{Html(FormatRank(item.Rank, item.Total))}</td><td>{Html(FormatScore(item.Score))}</td><td>{Html(item.Leader)}</td><td>{Html(item.Note)}</td></tr>");

        var body = $"<div class=\"note\"><strong>Selected material ranking context:</strong> {Html(selected.Label)} is compared against the full current visible/filter dataset. This is not a one-row Top 10 list.</div>" +
                   "<div class=\"cards\">" +
                   $"<div class=\"card\"><div class=\"card-label\">Material</div><div class=\"card-value\">{Html(selected.Label)}</div></div>" +
                   $"<div class=\"card\"><div class=\"card-label\">Overall rank</div><div class=\"card-value\">{Html(FormatRank(overall.Rank, overall.Total))}</div></div>" +
                   $"<div class=\"card\"><div class=\"card-label\">Type rank</div><div class=\"card-value\">{Html(FormatRank(type.Rank, type.Total))}</div></div>" +
                   "</div>" +
                   BuildBarChartHtml("Selected material score profile", BuildSelectedMaterialScoreItems(selected), "/100") +
                   "<h2>Ranking context</h2>\n<table><thead><tr><th>Scope</th><th>Standing</th><th>Score</th><th>Current leader</th><th>Interpretation</th></tr></thead><tbody>\n" +
                   string.Join("\n", rankRows) +
                   "\n</tbody></table>\n" +
                   "<h2>Metric summary</h2>\n<table><tbody>" +
                   $"<tr><td>Overall</td><td>{Html(selected.OverallText)}</td></tr>" +
                   $"<tr><td>Tensile</td><td>{Html(selected.TensileText)}</td></tr>" +
                   $"<tr><td>Impact</td><td>{Html(selected.ImpactText)}</td></tr>" +
                   $"<tr><td>Stiffness</td><td>{Html(selected.StiffnessText)}</td></tr>" +
                   $"<tr><td>Consistency</td><td>{Html(selected.ConsistencyText)}</td></tr>" +
                   $"<tr><td>Layer Adhesion</td><td>{Html(selected.LayerAdhesionText)}</td></tr>" +
                   "</tbody></table>";
        return BuildReportHtmlShell(title, key, generatedAt, new[] { selectedRow }, totalRows, body);
    }

    private string BuildSelectedAwardEligibilityHtml(string title, string key, DateTime generatedAt, DataRow selectedRow, IReadOnlyList<DataRow> contextRows, int totalRows)
    {
        var selected = BuildRankingRow(BuildVideoPlannerRow(selectedRow), "Overall");
        var allRanked = contextRows.Select(row => BuildRankingRow(BuildVideoPlannerRow(row), "Overall")).ToList();
        var eligibilityRows = new List<(string Award, int Rank, int Total, double? Score, string Leader, string Status, string UseCase)>();

        foreach (var definition in AwardDefinitions())
        {
            if (!definition.AppliesTo(selected)) continue;
            var candidates = allRanked
                .Where(definition.AppliesTo)
                .Select(row => (Row: row, Score: definition.ScoreSelector(row)))
                .Where(item => item.Score.HasValue)
                .OrderByDescending(item => item.Score ?? double.MinValue)
                .ThenByDescending(item => item.Row.Overall ?? double.MinValue)
                .ThenBy(item => item.Row.Label, StringComparer.CurrentCultureIgnoreCase)
                .ToList();
            if (candidates.Count == 0) continue;
            var index = candidates.FindIndex(item => MatchesRankingRow(item.Row, selected));
            if (index < 0) continue;
            var leader = candidates[0].Row.Label;
            eligibilityRows.Add((definition.Name, index + 1, candidates.Count, candidates[index].Score, leader, BuildAwardStandingText(index + 1, candidates.Count), definition.UseCase));
        }

        var tableRows = eligibilityRows.Select(item =>
            $"<tr><td>{Html(item.Award)}</td><td>{Html(FormatRank(item.Rank, item.Total))}</td><td>{Html(FormatScore(item.Score))}</td><td>{Html(item.Leader)}</td><td>{Html(item.Status)}</td><td>{Html(item.UseCase)}</td></tr>");

        var body = $"<div class=\"note\"><strong>Selected material award eligibility:</strong> {Html(selected.Label)} is checked against award categories in the full current visible/filter dataset. This report does not declare the selected material as winner unless it actually ranks first in that category.</div>" +
                   "<div class=\"cards\">" +
                   $"<div class=\"card\"><div class=\"card-label\">Material</div><div class=\"card-value\">{Html(selected.Label)}</div></div>" +
                   $"<div class=\"card\"><div class=\"card-label\">Eligible awards</div><div class=\"card-value\">{eligibilityRows.Count}</div></div>" +
                   $"<div class=\"card\"><div class=\"card-label\">Best standing</div><div class=\"card-value\">{Html(eligibilityRows.Count == 0 ? "-" : FormatRank(eligibilityRows.Min(row => row.Rank), eligibilityRows.First(row => row.Rank == eligibilityRows.Min(r => r.Rank)).Total))}</div></div>" +
                   "</div>" +
                   BuildBarChartHtml("Selected material award category scores", eligibilityRows.Select(row => (Label: row.Award, Value: row.Score ?? 0)).ToList(), "/100") +
                   "<h2>Award eligibility</h2>\n<table><thead><tr><th>Award</th><th>Standing</th><th>Score</th><th>Current leader</th><th>Status</th><th>Use case</th></tr></thead><tbody>\n" +
                   string.Join("\n", tableRows) +
                   "\n</tbody></table>\n";
        return BuildReportHtmlShell(title, key, generatedAt, new[] { selectedRow }, totalRows, body);
    }

    private string BuildSelectedVideoNotesHtml(string title, string key, DateTime generatedAt, DataRow selectedRow, int totalRows)
    {
        var video = BuildVideoPlannerRow(selectedRow);
        var ranking = BuildRankingRow(video, "Overall");
        var talkingPoints = (video.TalkingPoints ?? string.Empty)
            .Split(new[] { ';', '\n' }, StringSplitOptions.RemoveEmptyEntries)
            .Select(point => $"<li>{Html(point.Trim())}</li>");

        var body = $"<div class=\"note\"><strong>Selected material video notes:</strong> title, angle, comparison idea, and talking points for {Html(video.Label)}.</div>" +
                   "<div class=\"cards\">" +
                   $"<div class=\"card\"><div class=\"card-label\">Priority</div><div class=\"card-value\">{Html(video.Priority.ToString(CultureInfo.CurrentCulture))}</div></div>" +
                   $"<div class=\"card\"><div class=\"card-label\">Overall</div><div class=\"card-value\">{Html(FormatScore(video.OverallScore))}</div></div>" +
                   $"<div class=\"card\"><div class=\"card-label\">Best axis</div><div class=\"card-value\">{Html(DisplayText(ranking.BestAxis))}</div></div>" +
                   "</div>" +
                   BuildBarChartHtml("Selected material score profile", BuildSelectedMaterialScoreItems(ranking), "/100") +
                   "<h2>Video planning notes</h2><table><tbody>" +
                   $"<tr><td>Suggested title</td><td>{Html(video.SuggestedTitle)}</td></tr>" +
                   $"<tr><td>Thumbnail angle</td><td>{Html(video.SuggestedAngle)}</td></tr>" +
                   $"<tr><td>Comparison idea</td><td>{Html(video.ComparisonIdea)}</td></tr>" +
                   $"<tr><td>Status</td><td>{Html(video.Status)}</td></tr>" +
                   "</tbody></table>" +
                   "<h2>Talking points</h2><ul>" + string.Join("", talkingPoints) + "</ul>";
        return BuildReportHtmlShell(title, key, generatedAt, new[] { selectedRow }, totalRows, body);
    }

    private sealed class SelectedRankContext
    {
        public string Scope { get; init; } = string.Empty;
        public int Rank { get; init; }
        public int Total { get; init; }
        public double? Score { get; init; }
        public string Leader { get; init; } = string.Empty;
        public string Note { get; init; } = string.Empty;
    }

    private SelectedRankContext BuildSelectedRankContext(string scope, IReadOnlyList<RankingRow> rows, RankingRow selected, Func<RankingRow, bool> filter, Func<RankingRow, double?> scoreSelector)
    {
        var candidates = rows
            .Where(filter)
            .Select(row => (Row: row, Score: scoreSelector(row)))
            .Where(item => item.Score.HasValue)
            .OrderByDescending(item => item.Score ?? double.MinValue)
            .ThenByDescending(item => item.Row.Overall ?? double.MinValue)
            .ThenBy(item => item.Row.Label, StringComparer.CurrentCultureIgnoreCase)
            .ToList();
        var index = candidates.FindIndex(item => MatchesRankingRow(item.Row, selected));
        return new SelectedRankContext
        {
            Scope = scope,
            Rank = index >= 0 ? index + 1 : 0,
            Total = candidates.Count,
            Score = index >= 0 ? candidates[index].Score : null,
            Leader = candidates.Count > 0 ? candidates[0].Row.Label : "-",
            Note = index >= 0 ? BuildRankStandingText(index + 1, candidates.Count) : "No matching scored material found in this scope"
        };
    }

    private static bool MatchesRankingRow(RankingRow left, RankingRow right)
    {
        return SameText(left.Label, right.Label)
            && SameText(left.Manufacturer, right.Manufacturer)
            && SameText(left.BaseMaterial, right.BaseMaterial)
            && SameText(left.Reinforcement, right.Reinforcement);
    }

    private static bool SameText(string? left, string? right)
    {
        return string.Equals((left ?? string.Empty).Trim(), (right ?? string.Empty).Trim(), StringComparison.CurrentCultureIgnoreCase);
    }

    private static string FormatRank(int rank, int total)
    {
        if (rank <= 0 || total <= 0) return "-";
        return $"#{rank} / {total}";
    }

    private static string BuildRankStandingText(int rank, int total)
    {
        if (rank <= 0 || total <= 0) return "No score available";
        if (rank == 1) return "Current leader in this scope";
        var percentile = (double)rank / Math.Max(1, total);
        if (percentile <= 0.1) return "Top 10% contender";
        if (percentile <= 0.25) return "Strong upper-quartile contender";
        if (percentile <= 0.5) return "Middle of the pack";
        return "Lower half in this scope";
    }

    private static string BuildAwardStandingText(int rank, int total)
    {
        if (rank == 1) return "Currently winning this award category";
        var percentile = (double)rank / Math.Max(1, total);
        if (percentile <= 0.1) return "Strong award contender";
        if (percentile <= 0.25) return "Possible award shortlist candidate";
        return "Eligible, but not currently near the top";
    }

    private string BuildRankingAnalyticsHtml(IReadOnlyList<RankingRow> rankedRows)
    {
        var manufacturerLeaders = BuildGroupAnalytics(rankedRows, row => row.Manufacturer, row => row.RankScore, 10);
        var materialTypeLeaders = BuildGroupAnalytics(rankedRows, row => row.BaseMaterial, row => row.RankScore, 10);
        var reinforcementLeaders = BuildGroupAnalytics(rankedRows, row => string.IsNullOrWhiteSpace(row.Reinforcement) || row.Reinforcement == "—" ? "Unreinforced" : row.Reinforcement, row => row.RankScore, 10);

        var sb = new StringBuilder();
        sb.AppendLine("<h2>Rankings analytics</h2>");
        sb.AppendLine("<div class=\"note\"><strong>Analytics view:</strong> group leaderboards use the average overall score of currently visible materials. Groups with more tested materials are usually more reliable than groups with only one material.</div>");
        sb.AppendLine(BuildBarChartHtml("Manufacturer leaderboard - average overall score", manufacturerLeaders.Select(row => (row.Label, row.Value)).ToList(), "/100"));
        sb.AppendLine(BuildGroupAnalyticsTableHtml("Manufacturer leaderboard", manufacturerLeaders));
        sb.AppendLine(BuildBarChartHtml("Material type leaderboard - average overall score", materialTypeLeaders.Select(row => (row.Label, row.Value)).ToList(), "/100"));
        sb.AppendLine(BuildGroupAnalyticsTableHtml("Material type leaderboard", materialTypeLeaders));
        sb.AppendLine(BuildBarChartHtml("Reinforcement comparison - average overall score", reinforcementLeaders.Select(row => (row.Label, row.Value)).ToList(), "/100"));
        sb.AppendLine(BuildGroupAnalyticsTableHtml("Reinforcement comparison", reinforcementLeaders));
        sb.AppendLine(BuildMetricLeaderSummaryHtml(rankedRows));
        return sb.ToString();
    }

    private sealed class RankingGroupAnalyticsRow
    {
        public string Label { get; init; } = string.Empty;
        public double Value { get; init; }
        public int Count { get; init; }
        public string BestMaterial { get; init; } = string.Empty;
        public string BestScoreText { get; init; } = string.Empty;
    }

    private List<RankingGroupAnalyticsRow> BuildGroupAnalytics(IReadOnlyList<RankingRow> rows, Func<RankingRow, string> groupSelector, Func<RankingRow, double?> scoreSelector, int limit)
    {
        return rows
            .Select(row => (Row: row, Group: DisplayText(groupSelector(row)), Score: scoreSelector(row)))
            .Where(item => item.Score.HasValue && !string.IsNullOrWhiteSpace(item.Group) && item.Group != "-")
            .GroupBy(item => item.Group, StringComparer.CurrentCultureIgnoreCase)
            .Select(group =>
            {
                var best = group.OrderByDescending(item => item.Score ?? double.MinValue).ThenBy(item => item.Row.Label, StringComparer.CurrentCultureIgnoreCase).First();
                var avg = group.Average(item => item.Score ?? 0);
                return new RankingGroupAnalyticsRow
                {
                    Label = group.Key,
                    Value = avg,
                    Count = group.Count(),
                    BestMaterial = best.Row.Label,
                    BestScoreText = FormatScore(best.Score)
                };
            })
            .OrderByDescending(row => row.Value)
            .ThenByDescending(row => row.Count)
            .ThenBy(row => row.Label, StringComparer.CurrentCultureIgnoreCase)
            .Take(limit)
            .ToList();
    }

    private string BuildGroupAnalyticsTableHtml(string title, IReadOnlyList<RankingGroupAnalyticsRow> rows)
    {
        var tableRows = rows.Select(row =>
            $"<tr><td>{Html(row.Label)}</td><td>{Html(FormatScore(row.Value))}</td><td>{row.Count}</td><td>{Html(row.BestMaterial)}</td><td>{Html(row.BestScoreText)}</td></tr>");

        return $"<h3>{Html(title)}</h3>\n<table><thead><tr><th>Group</th><th>Average score</th><th>Materials</th><th>Best material</th><th>Best score</th></tr></thead><tbody>\n" +
               string.Join("\n", tableRows) +
               "\n</tbody></table>\n";
    }

    private string BuildMetricLeaderSummaryHtml(IReadOnlyList<RankingRow> rankedRows)
    {
        var rows = new[]
        {
            BuildMetricLeaderRow("Overall", rankedRows, row => row.RankScore),
            BuildMetricLeaderRow("Tensile", rankedRows, row => row.Tensile),
            BuildMetricLeaderRow("Impact", rankedRows, row => row.Impact),
            BuildMetricLeaderRow("Stiffness", rankedRows, row => row.Stiffness),
            BuildMetricLeaderRow("Consistency", rankedRows, row => row.Consistency),
            BuildMetricLeaderRow("Layer Adhesion", rankedRows, row => row.LayerAdhesion)
        }
        .Where(row => row is not null)
        .Select(row => row!)
        .ToList();

        var tableRows = rows.Select(row =>
            $"<tr><td>{Html(row.Metric)}</td><td>{Html(row.Material)}</td><td>{Html(row.Manufacturer)}</td><td>{Html(row.Type)}</td><td>{Html(row.ScoreText)}</td></tr>");

        return "<h3>Metric leaders</h3>\n<table><thead><tr><th>Metric</th><th>Leader</th><th>Manufacturer</th><th>Type</th><th>Score</th></tr></thead><tbody>\n" +
               string.Join("\n", tableRows) +
               "\n</tbody></table>\n";
    }

    private sealed class MetricLeaderRow
    {
        public string Metric { get; init; } = string.Empty;
        public string Material { get; init; } = string.Empty;
        public string Manufacturer { get; init; } = string.Empty;
        public string Type { get; init; } = string.Empty;
        public string ScoreText { get; init; } = string.Empty;
    }

    private MetricLeaderRow? BuildMetricLeaderRow(string metric, IReadOnlyList<RankingRow> rows, Func<RankingRow, double?> scoreSelector)
    {
        var best = rows
            .Select(row => (Row: row, Score: scoreSelector(row)))
            .Where(item => item.Score.HasValue)
            .OrderByDescending(item => item.Score ?? double.MinValue)
            .ThenBy(item => item.Row.Label, StringComparer.CurrentCultureIgnoreCase)
            .FirstOrDefault();

        if (best.Row is null || !best.Score.HasValue) return null;

        return new MetricLeaderRow
        {
            Metric = metric,
            Material = best.Row.Label,
            Manufacturer = best.Row.Manufacturer,
            Type = best.Row.BaseMaterial,
            ScoreText = FormatScore(best.Score)
        };
    }

    private string BuildRankingsReportHtml(string title, string key, DateTime generatedAt, IReadOnlyList<DataRow> rows, int totalRows)
    {
        var rankedRows = rows
            .Select(row => BuildRankingRow(BuildVideoPlannerRow(row), "Overall"))
            .Where(row => row.RankScore.HasValue)
            .OrderByDescending(row => row.RankScore ?? double.MinValue)
            .ThenBy(row => row.Label, StringComparer.CurrentCultureIgnoreCase)
            .Take(50)
            .ToList();

        var tableRows = rankedRows.Select((row, index) =>
            $"<tr><td>{index + 1}</td><td>{Html(row.Label)}</td><td>{Html(row.Manufacturer)}</td><td>{Html(row.BaseMaterial)}</td><td>{Html(row.Reinforcement)}</td><td>{Html(row.RankScoreText)}</td><td>{Html(row.TensileText)}</td><td>{Html(row.ImpactText)}</td><td>{Html(row.StiffnessText)}</td></tr>");

        var body = "<div class=\"note\"><strong>Rankings analytics report:</strong> top materials and group leaderboards from the current visible dataset, sorted by overall engineering score.</div>" +
                   BuildScoreBarChartHtml("Top 10 overall score", rankedRows, row => row.RankScore) +
                   BuildScoreBarChartHtml("Top 10 tensile score", rankedRows, row => row.Tensile) +
                   BuildScoreBarChartHtml("Top 10 impact score", rankedRows, row => row.Impact) +
                   BuildRankingAnalyticsHtml(rankedRows) +
                   "<h2>Top ranked materials</h2>\n<table><thead><tr><th>#</th><th>Material</th><th>Manufacturer</th><th>Type</th><th>Reinforcement</th><th>Score</th><th>Tensile</th><th>Impact</th><th>Stiffness</th></tr></thead><tbody>\n" +
                   string.Join("\n", tableRows) +
                   "\n</tbody></table>\n";
        return BuildReportHtmlShell(title, key, generatedAt, rows, totalRows, body);
    }

    private string BuildAwardsReportHtml(string title, string key, DateTime generatedAt, IReadOnlyList<DataRow> rows, int totalRows)
    {
        var rankingRows = rows.Select(row => BuildRankingRow(BuildVideoPlannerRow(row), "Overall")).ToList();
        var awardRows = new List<AwardRow>();

        foreach (var definition in AwardDefinitions())
        {
            var candidates = rankingRows
                .Where(definition.AppliesTo)
                .Select(row => (Row: row, Score: definition.ScoreSelector(row)))
                .Where(item => item.Score.HasValue)
                .OrderByDescending(item => item.Score ?? double.MinValue)
                .ThenByDescending(item => item.Row.Overall ?? double.MinValue)
                .ThenBy(item => item.Row.Label, StringComparer.CurrentCultureIgnoreCase)
                .ToList();

            if (candidates.Count == 0) continue;

            var winner = candidates[0];
            var runnerUpItem = candidates.Count > 1 ? candidates[1] : candidates[0];
            var hasRunnerUp = candidates.Count > 1;
            awardRows.Add(new AwardRow
            {
                Award = definition.Name,
                Winner = winner.Row.Label,
                Manufacturer = winner.Row.Manufacturer,
                BaseMaterial = winner.Row.BaseMaterial,
                Reinforcement = winner.Row.Reinforcement,
                Score = winner.Score,
                RunnerUp = hasRunnerUp ? runnerUpItem.Row.Label : "—",
                RunnerUpManufacturer = hasRunnerUp ? runnerUpItem.Row.Manufacturer : string.Empty,
                RunnerUpBaseMaterial = hasRunnerUp ? runnerUpItem.Row.BaseMaterial : string.Empty,
                RunnerUpReinforcement = hasRunnerUp ? runnerUpItem.Row.Reinforcement : string.Empty,
                RunnerUpScore = hasRunnerUp ? runnerUpItem.Score : null,
                UseCase = definition.UseCase,
                Why = BuildAwardReason(definition, winner.Row, winner.Score),
                Status = winner.Row.Status
            });
        }

        var tableRows = awardRows.Take(50).Select(row =>
            $"<tr><td>{Html(row.Award)}</td><td>{Html(row.Winner)}</td><td>{Html(row.Manufacturer)}</td><td>{Html(row.BaseMaterial)}</td><td>{Html(row.Reinforcement)}</td><td>{Html(row.ScoreText)}</td><td>{Html(row.RunnerUp)}</td><td>{Html(row.UseCase)}</td></tr>");

        var awardChartItems = awardRows
            .Where(row => row.Score.HasValue)
            .Select(row => (Label: row.Award, Value: row.Score!.Value))
            .Take(10)
            .ToList();

        
        var manufacturerWinCounts = awardRows
            .GroupBy(a => string.IsNullOrWhiteSpace(a.Manufacturer) ? "Unknown" : a.Manufacturer)
            .ToDictionary(g => g.Key, g => g.Count(), StringComparer.CurrentCultureIgnoreCase);
        var manufacturerRunnerUpCounts = awardRows
            .Where(a => !string.IsNullOrWhiteSpace(a.RunnerUpManufacturer) && a.RunnerUp != "—")
            .GroupBy(a => a.RunnerUpManufacturer)
            .ToDictionary(g => g.Key, g => g.Count(), StringComparer.CurrentCultureIgnoreCase);
        var manufacturerAwardRows = manufacturerWinCounts.Keys
            .Concat(manufacturerRunnerUpCounts.Keys)
            .Distinct(StringComparer.CurrentCultureIgnoreCase)
            .Select(name => new
            {
                Name = name,
                Wins = manufacturerWinCounts.TryGetValue(name, out var wins) ? wins : 0,
                RunnerUps = manufacturerRunnerUpCounts.TryGetValue(name, out var runnerUps) ? runnerUps : 0
            })
            .OrderByDescending(x => x.Wins)
            .ThenByDescending(x => x.RunnerUps)
            .ThenBy(x => x.Name)
            .Select(x => $"<tr><td>{Html(x.Name)}</td><td>{x.Wins}</td><td>{x.RunnerUps}</td></tr>")
            .ToList();

        var typeWinCounts = awardRows
            .GroupBy(a => string.IsNullOrWhiteSpace(a.BaseMaterial) ? "Unknown" : a.BaseMaterial)
            .ToDictionary(g => g.Key, g => g.Count(), StringComparer.CurrentCultureIgnoreCase);
        var typeRunnerUpCounts = awardRows
            .Where(a => !string.IsNullOrWhiteSpace(a.RunnerUpBaseMaterial) && a.RunnerUp != "—")
            .GroupBy(a => a.RunnerUpBaseMaterial)
            .ToDictionary(g => g.Key, g => g.Count(), StringComparer.CurrentCultureIgnoreCase);
        var typeAwardRows = typeWinCounts.Keys
            .Concat(typeRunnerUpCounts.Keys)
            .Distinct(StringComparer.CurrentCultureIgnoreCase)
            .Select(name => new
            {
                Name = name,
                Wins = typeWinCounts.TryGetValue(name, out var wins) ? wins : 0,
                RunnerUps = typeRunnerUpCounts.TryGetValue(name, out var runnerUps) ? runnerUps : 0
            })
            .OrderByDescending(x => x.Wins)
            .ThenByDescending(x => x.RunnerUps)
            .ThenBy(x => x.Name)
            .Select(x => $"<tr><td>{Html(x.Name)}</td><td>{x.Wins}</td><td>{x.RunnerUps}</td></tr>")
            .ToList();

        string ReinforcementClass(string? value) => string.IsNullOrWhiteSpace(value) || value == "—" ? "Unreinforced" : value;
        var reinforcementWinCounts = awardRows
            .GroupBy(a => ReinforcementClass(a.Reinforcement))
            .ToDictionary(g => g.Key, g => g.Count(), StringComparer.CurrentCultureIgnoreCase);
        var reinforcementRunnerUpCounts = awardRows
            .Where(a => a.RunnerUp != "—")
            .GroupBy(a => ReinforcementClass(a.RunnerUpReinforcement))
            .ToDictionary(g => g.Key, g => g.Count(), StringComparer.CurrentCultureIgnoreCase);
        var reinforcementAwardRows = reinforcementWinCounts.Keys
            .Concat(reinforcementRunnerUpCounts.Keys)
            .Distinct(StringComparer.CurrentCultureIgnoreCase)
            .Select(name => new
            {
                Name = name,
                Wins = reinforcementWinCounts.TryGetValue(name, out var wins) ? wins : 0,
                RunnerUps = reinforcementRunnerUpCounts.TryGetValue(name, out var runnerUps) ? runnerUps : 0
            })
            .OrderByDescending(x => x.Wins)
            .ThenByDescending(x => x.RunnerUps)
            .ThenBy(x => x.Name)
            .Select(x => $"<tr><td>{Html(x.Name)}</td><td>{x.Wins}</td><td>{x.RunnerUps}</td></tr>")
            .ToList();

        var body = "<div class=\"note\"><strong>Awards report:</strong> winner and runner-up candidates calculated from the current visible dataset.</div>" +
                   BuildBarChartHtml("Award winner scores", awardChartItems, "/100") +
                   "<h2>Award winners</h2>\n<table><thead><tr><th>Award</th><th>Winner</th><th>Manufacturer</th><th>Type</th><th>Reinforcement</th><th>Score</th><th>Runner-up</th><th>Use case</th></tr></thead><tbody>\n" +
                   string.Join("\n", tableRows) +
                   "\n</tbody></table>\n" +
                   "<h2>Awards Analytics</h2>" +
                   "<div class=\"note\"><strong>Awards analytics:</strong> aggregated award wins from the current dataset.</div>" +
                   "<h2>Manufacturer Award Strength</h2>" + BuildBarChartHtml("Manufacturer Award Wins", manufacturerWinCounts.Select(x => (x.Key, (double)x.Value)).OrderByDescending(x => x.Item2).Take(10).Select(x => (Label:x.Key, Value:x.Item2)).ToList(), "") + "<table><thead><tr><th>Manufacturer</th><th>Award Wins</th><th>Runner-ups</th></tr></thead><tbody>" + string.Join("", manufacturerAwardRows) + "</tbody></table>" +
                   "<h2>Material Family Award Strength</h2>" + BuildBarChartHtml("Material Family Award Wins", typeWinCounts.Select(x => (x.Key, (double)x.Value)).OrderByDescending(x => x.Item2).Take(10).Select(x => (Label:x.Key, Value:x.Item2)).ToList(), "") + "<table><thead><tr><th>Family</th><th>Award Wins</th><th>Runner-ups</th></tr></thead><tbody>" + string.Join("", typeAwardRows) + "</tbody></table>" +
                   "<h2>Reinforcement Award Strength</h2>" + BuildBarChartHtml("Reinforcement Award Wins", reinforcementWinCounts.Select(x => (x.Key, (double)x.Value)).OrderByDescending(x => x.Item2).Take(10).Select(x => (Label:x.Key, Value:x.Item2)).ToList(), "") + "<table><thead><tr><th>Class</th><th>Award Wins</th><th>Runner-ups</th></tr></thead><tbody>" + string.Join("", reinforcementAwardRows) + "</tbody></table>";
        return BuildReportHtmlShell(title, key, generatedAt, rows, totalRows, body);
    }

    private string BuildYouTubeReportHtml(string title, string key, DateTime generatedAt, IReadOnlyList<DataRow> rows, int totalRows)
    {
        var candidates = rows
            .Select(row => BuildVideoPlannerRow(row))
            .OrderByDescending(row => row.Priority)
            .ThenByDescending(row => row.OverallScore ?? double.MinValue)
            .Take(50)
            .ToList();

        var tableRows = candidates.Select(row =>
            $"<tr><td>{Html(row.Label)}</td><td>{Html(row.Manufacturer)}</td><td>{Html(row.BaseMaterial)}</td><td>{Html(row.Reinforcement)}</td><td>{Html(row.Priority.ToString(CultureInfo.CurrentCulture))}</td><td>{Html(row.Status)}</td><td>{Html(row.SuggestedAngle)}</td></tr>");

        var priorityChartItems = candidates
            .Select(row => (Label: row.Label, Value: (double)row.Priority))
            .Take(10)
            .ToList();

        var body = "<div class=\"note\"><strong>YouTube research report:</strong> candidate materials and data-driven video angles from the current visible dataset.</div>" +
                   BuildBarChartHtml("Top 10 video priority", priorityChartItems, string.Empty) +
                   "<h2>Research candidates</h2>\n<table><thead><tr><th>Material</th><th>Manufacturer</th><th>Type</th><th>Reinforcement</th><th>Priority</th><th>Status</th><th>Suggested angle</th></tr></thead><tbody>\n" +
                   string.Join("\n", tableRows) +
                   "\n</tbody></table>\n";
        return BuildReportHtmlShell(title, key, generatedAt, rows, totalRows, body);
    }



    private static string DisplayText(string? value, string? fallback = null)
    {
        if (!string.IsNullOrWhiteSpace(value) && value != "—") return value;
        if (!string.IsNullOrWhiteSpace(fallback) && fallback != "—") return fallback;
        return "-";
    }

    private string FormatMetricCell(DataRow row, string primaryColumn, string alternateColumn, string secondAlternateColumn, string suffix)
    {
        var raw = GetCell(row, primaryColumn, alternateColumn, secondAlternateColumn);
        if (string.IsNullOrWhiteSpace(raw)) return string.Empty;

        if (double.TryParse(raw, NumberStyles.Any, CultureInfo.CurrentCulture, out var currentValue) ||
            double.TryParse(raw, NumberStyles.Any, CultureInfo.InvariantCulture, out currentValue))
        {
            var formatted = currentValue >= 100 ? currentValue.ToString("0", CultureInfo.CurrentCulture) : currentValue.ToString("0.##", CultureInfo.CurrentCulture);
            return string.IsNullOrWhiteSpace(suffix) ? formatted : $"{formatted} {suffix}";
        }

        return raw;
    }

    private string CreateReportPackageFolder(string outputFolder, ReportFoundationResult report, DateTime generatedAt)
    {
        var folderName = BuildReportPackageFolderName(report, generatedAt);
        var fullPath = System.IO.Path.Combine(outputFolder, folderName);
        Directory.CreateDirectory(fullPath);
        return fullPath;
    }

    private string BuildReportPackageFolderName(ReportFoundationResult report, DateTime generatedAt)
    {
        var reportName = MakeSafeFileName(report.Title);
        if (string.IsNullOrWhiteSpace(reportName) || reportName == "report")
        {
            reportName = MakeSafeFileName(report.Key);
        }

        return $"{reportName}-{generatedAt:yyyyMMdd-HHmmss}";
    }

    private string MakeSafeFileName(string value)
    {
        if (string.IsNullOrWhiteSpace(value)) return "report";
        var invalid = System.IO.Path.GetInvalidFileNameChars();
        var cleaned = new string(value.Trim().Select(ch => invalid.Contains(ch) ? '-' : ch).ToArray());
        cleaned = cleaned.Replace(' ', '-').Replace('_', '-').ToLowerInvariant();
        while (cleaned.Contains("--", StringComparison.Ordinal)) cleaned = cleaned.Replace("--", "-", StringComparison.Ordinal);
        return cleaned.Trim('-');
    }

    private void CopyReportPackageAssets(string assetsFolder)
    {
        var assetNames = new[]
        {
            "3dp-iceland-labs-logo-pdf.jpg",
            "3dp-iceland-labs-icon.ico"
        };

        foreach (var assetName in assetNames)
        {
            var sourcePath = FindReportAssetPath(assetName);
            if (string.IsNullOrWhiteSpace(sourcePath)) continue;
            var targetPath = System.IO.Path.Combine(assetsFolder, assetName);
            File.Copy(sourcePath, targetPath, overwrite: true);
        }
    }

    private static string FindReportAssetPath(string assetName)
    {
        var candidatePaths = new[]
        {
            System.IO.Path.Combine(AppContext.BaseDirectory, "Assets", assetName),
            System.IO.Path.Combine(AppContext.BaseDirectory, assetName),
            System.IO.Path.Combine(Directory.GetCurrentDirectory(), "Assets", assetName)
        };

        return candidatePaths.FirstOrDefault(File.Exists) ?? string.Empty;
    }

    private string BuildReportManifest(ReportFoundationResult report, string primaryArtifactPath, string htmlPath, DateTime generatedAt, string packageFolder, string assetsFolder, string metadataPath)
    {
        var sb = new StringBuilder();
        sb.AppendLine("3DP Iceland Labs - Report Package Manifest");
        sb.AppendLine("Version: " + BuildInfo.ShortLabel + " - " + BuildInfo.ReleaseTitle);
        sb.AppendLine("Release identity: " + BuildInfo.ShortLabel + " - " + BuildInfo.ReleaseTitle);
        sb.AppendLine($"Generated: {generatedAt:yyyy-MM-dd HH:mm:ss}");
        sb.AppendLine($"Package folder: {packageFolder}");
        sb.AppendLine($"Report type: {report.Title}");
        sb.AppendLine($"Report key: {report.Key}");
        sb.AppendLine($"Materials in report scope: {report.VisibleMaterialCount} of {report.TotalMaterialCount} active materials");
        sb.AppendLine($"Primary artifact: {primaryArtifactPath}");
        sb.AppendLine($"Canonical HTML report: {htmlPath}");
        sb.AppendLine($"Metadata JSON: {metadataPath}");
        sb.AppendLine($"Assets folder: {assetsFolder}");
        sb.AppendLine("Canonical renderer: HTML report package");
        sb.AppendLine("PDF renderer: WebView2 PrintToPdf from the same canonical HTML file");
        sb.AppendLine("Shared assets: copied into package assets/ and embedded in canonical HTML for standalone review");
        sb.AppendLine("Package standard: report.html, report.txt, optional report.pdf, manifest.txt, report-metadata.json, assets/");
        return sb.ToString();
    }

    private string BuildReportMetadataJson(ReportFoundationResult report, DateTime generatedAt, string packageFolder, string htmlPath, string txtPath, string? pdfPath)
    {
        var sb = new StringBuilder();
        sb.AppendLine("{");
        sb.AppendLine("  \"application\": \"3DPIceland FilamentDB\",");
        sb.AppendLine("  \"version\": \"" + BuildInfo.ShortLabel + "\",");
        sb.AppendLine("  \"build\": \"Strategic Master Roadmap\",");
        sb.AppendLine($"  \"generatedAt\": \"{generatedAt:yyyy-MM-ddTHH:mm:ss}\",");
        sb.AppendLine($"  \"reportKey\": \"{EscapeJson(report.Key)}\",");
        sb.AppendLine($"  \"reportTitle\": \"{EscapeJson(report.Title)}\",");
        sb.AppendLine($"  \"visibleMaterials\": {report.VisibleMaterialCount},");
        sb.AppendLine($"  \"totalMaterials\": {report.TotalMaterialCount},");
        sb.AppendLine($"  \"packageFolder\": \"{EscapeJson(packageFolder)}\",");
        sb.AppendLine($"  \"canonicalHtml\": \"{EscapeJson(htmlPath)}\",");
        sb.AppendLine($"  \"textSummary\": \"{EscapeJson(txtPath)}\",");
        var pdfJson = string.IsNullOrWhiteSpace(pdfPath) ? "null" : "\"" + EscapeJson(pdfPath) + "\"";
        sb.AppendLine($"  \"pdf\": {pdfJson},");
        sb.AppendLine("  \"canonicalFormat\": \"HTML report package\",");
        sb.AppendLine("  \"pdfStrategy\": \"WebView2 PrintToPdf from canonical HTML\"");
        sb.AppendLine("}");
        return sb.ToString();
    }

    private static string EscapeJson(string value)
    {
        return value
            .Replace("\\", "\\\\", StringComparison.Ordinal)
            .Replace("\"", "\\\"", StringComparison.Ordinal)
            .Replace("\r", "\\r", StringComparison.Ordinal)
            .Replace("\n", "\\n", StringComparison.Ordinal);
    }

    private string GetDefaultReportOutputFolder()
    {
        if (AutomationRuntimeProfile.Current is { } profile) return profile.OutputFolder;
        var currentReportFolder = ReportOutputFolderBox?.Text?.Trim();
        if (!string.IsNullOrWhiteSpace(currentReportFolder)) return currentReportFolder;

        var websiteFolder = WebsiteExportFolderBox?.Text?.Trim();
        if (!string.IsNullOrWhiteSpace(websiteFolder)) return System.IO.Path.Combine(websiteFolder, "Reports");

        return System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments), "3DPIcelandFilamentDB", "Reports");
    }


    private void ExportNativeExcel_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            PersistCanonicalStateForExcelRecovery();
            RefreshNativeInputModulesFromMaterialManager(markDirty: false);
            ApplyNativeTensileComputedFields(_nativeTensileRows);
            ApplyNativeImpactComputedFields(_nativeImpactRows);
            ApplyNativeStiffnessComputedFields(_nativeStiffnessRows);

            var timestamp = DateTime.Now.ToString("yyyy-MM-dd_HHmm", CultureInfo.InvariantCulture);
            var dialog = new SaveFileDialog
            {
                Title = "Export Governed Excel Disaster-Recovery Package",
                Filter = "Excel Workbook (*.xlsx)|*.xlsx",
                FileName = $"3DPIceland_FilamentDB_DisasterRecovery_{timestamp}.xlsx"
            };

            if (dialog.ShowDialog(this) != true) return;
            var verifiedSnapshot = ExportExcelRecoveryPackageToPath(dialog.FileName);

            StatusText.Text = $"Excel disaster-recovery package exported — {verifiedSnapshot.Tables.Count} governed tables, {verifiedSnapshot.Tables.Sum(table => table.Rows.Count):N0} rows";
            ShowTransientStatus($"Excel disaster-recovery package verified — {System.IO.Path.GetFileName(dialog.FileName)}");
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, $"Could not export the Excel disaster-recovery package:\n\n{ex.Message}", "Excel Disaster Recovery Export", MessageBoxButton.OK, MessageBoxImage.Error);
        }
    }

    private ExcelRecoverySnapshot ExportExcelRecoveryPackageToPath(string outputPath)
    {
        var fullPath = IOPath.GetFullPath(outputPath);
        var folder = IOPath.GetDirectoryName(fullPath)
                     ?? throw new InvalidOperationException("Excel recovery output folder is unavailable.");
        IODirectory.CreateDirectory(folder);
        using var workbook = new XLWorkbook();
        AddNativeExportInfoSheet(workbook);
        AddNativeMaterialsSheet(workbook);
        AddNativeTensileSheet(workbook);
        AddNativeImpactSheet(workbook);
        AddNativeStiffnessSheet(workbook);
        AddNativeSettingsSheet(workbook);
        AddBaseMaterialProfilesSheet(workbook);
        var recoverySnapshot = _database.CreateExcelRecoverySnapshot();
        new ExcelDisasterRecoveryService().AddRecoveryPackage(workbook, recoverySnapshot);
        workbook.SaveAs(fullPath);
        var verifiedSnapshot = new ExcelDisasterRecoveryService().LoadAndVerify(fullPath);
        if (verifiedSnapshot.Tables.Count != recoverySnapshot.Tables.Count ||
            verifiedSnapshot.Tables.Sum(table => table.Rows.Count) !=
            recoverySnapshot.Tables.Sum(table => table.Rows.Count))
            throw new InvalidOperationException(
                "The saved Excel disaster-recovery package did not pass table/row round-trip verification.");
        return verifiedSnapshot;
    }

    private void PersistCanonicalStateForExcelRecovery()
    {
        ApplyNativeMaterialComputedFieldsToAllRows();
        if (!NativeMaterialIdsAreSqliteSafe() || NativeMaterialHasBlockingValidationIssues())
            throw new InvalidOperationException("Excel disaster recovery is blocked until Materials validation issues are resolved.");
        _database.ReplaceNativeMaterialManagerRows(_nativeMaterialRows.Select(NativeMaterialRecordFromRow));
        SaveNativeMeasurementsToSqlite();
        SaveCanonicalNativeSettings();
        SaveDeploymentSettingsFromManager();
        SaveBaseMaterialCatalogToDatabase();
        SetNativeMaterialsDirty(false);
        SetNativeTensileDirty(false);
        SetNativeImpactDirty(false);
        SetNativeStiffnessDirty(false);
    }

