    private static void WriteHeader(IXLWorksheet ws, int row, params string[] headers)
    {
        for (var i = 0; i < headers.Length; i++) ws.Cell(row, i + 1).Value = headers[i];
        var range = ws.Range(row, 1, row, headers.Length);
        range.Style.Font.Bold = true;
        range.Style.Fill.BackgroundColor = XLColor.FromHtml("D9EAF7");
        range.Style.Border.BottomBorder = XLBorderStyleValues.Thin;
    }

    private static void FinishExportSheet(IXLWorksheet ws, int headerColumns)
    {
        ws.SheetView.FreezeRows(1);
        if (ws.LastRowUsed() is not null && ws.LastRowUsed()!.RowNumber() > 1)
        {
            var range = ws.Range(1, 1, ws.LastRowUsed()!.RowNumber(), headerColumns);
            range.SetAutoFilter();
        }
        ws.Columns().AdjustToContents();
    }

