        try
        {
            var dialog = new OpenFolderDialog
            {
                Title = "Choose folder for 3DP Iceland Labs database",
                InitialDirectory = _database.DatabaseFolder
            };

            if (dialog.ShowDialog(this) != true) return;

            _database.MoveDatabaseToFolder(dialog.FolderName);
            _database = new LocalDatabase();

            LoadSavedVideoIdeas();

            MessageBox.Show(this,
                $"Storage folder updated.\n\nDatabase path:\n{_database.DatabasePath}",
                "Storage Folder Updated",
                MessageBoxButton.OK,
                MessageBoxImage.Information);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Could not change storage folder", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

