    private void UpdateReadiness_Click(object sender, RoutedEventArgs e)
    {
        var dialog = new OpenFileDialog
        {
            Title = "Select Signed 3DPIceland Update Package",
            Filter = "3DPIceland update package (*.zip)|*.zip|All files (*.*)|*.*",
            CheckFileExists = true,
            Multiselect = false
        };
        if (dialog.ShowDialog(this) != true) return;

        var result = new ApplicationUpdatePackageService().Inspect(dialog.FileName, Version.Parse(BuildInfo.Version), _database.CurrentSchemaVersion);
        var manifest = result.Manifest;
        var summary = new StringBuilder()
            .AppendLine(result.Ready ? "This update package passed readiness verification." : "This update package is blocked.")
            .AppendLine()
            .AppendLine("Status: " + result.Status)
            .AppendLine("Detail: " + result.Detail)
            .AppendLine()
            .AppendLine("Package readable: " + PassFail(result.PackageReadable))
            .AppendLine("Manifest valid: " + PassFail(result.ManifestValid))
            .AppendLine("File inventory valid: " + PassFail(result.FileInventoryValid))
            .AppendLine("SHA-256 hashes valid: " + PassFail(result.HashesValid))
            .AppendLine("Trusted signature valid: " + PassFail(result.SignatureValid))
            .AppendLine("Version policy valid: " + PassFail(result.VersionValid))
            .AppendLine("SQLite schema policy valid: " + PassFail(result.DatabaseSchemaValid));
        if (manifest is not null)
        {
            summary.AppendLine()
                .AppendLine("Release: v" + manifest.ReleaseVersion + " " + manifest.ReleaseCode)
                .AppendLine($"Supported SQLite schema: v{manifest.MinimumDatabaseSchema}-v{manifest.MaximumDatabaseSchema}")
                .AppendLine("Governed files: " + manifest.Files.Count.ToString("N0", CultureInfo.CurrentCulture));
        }
        summary.AppendLine().AppendLine("Readiness inspection never changes application files or SQLite data.");
        MessageBox.Show(this, summary.ToString(), "Application Update Readiness", MessageBoxButton.OK,
            result.Ready ? MessageBoxImage.Information : MessageBoxImage.Warning);

        if (result.Ready && manifest is not null)
        {
            var apply = MessageBox.Show(this,
                $"Apply signed application update v{manifest.ReleaseVersion}?\n\n" +
                "A verified SQLite backup and last-known-good application snapshot will be created first. " +
                "The application will close, update, restart and require a startup health acknowledgement. " +
                "Application files will roll back automatically if launch or health verification fails. SQLite is never restored silently.",
                "Confirm Guarded Application Update", MessageBoxButton.YesNo, MessageBoxImage.Warning, MessageBoxResult.No);
            if (apply == MessageBoxResult.Yes) StartGuardedApplicationUpdate(dialog.FileName, manifest);
        }

        static string PassFail(bool value) => value ? "PASS" : "BLOCKED";
    }

    private async void CheckForUpdates_Click(object sender, RoutedEventArgs e) => await CheckForRemoteUpdateAsync(showUpToDate: true);

    public async void BeginAutomaticUpdateCheck()
    {
        await Task.Delay(TimeSpan.FromMinutes(1));
        if (!IsLoaded) return;
        await CheckForRemoteUpdateAsync(showUpToDate: false);
    }

    private async Task CheckForRemoteUpdateAsync(bool showUpToDate)
    {
        if (IsAutomationActionBlocked("Application update check")) return;
        try
        {
            Mouse.OverrideCursor = Cursors.Wait;
            var service = new RemoteApplicationUpdateService();
            var discovery = await service.CheckAsync(Version.Parse(BuildInfo.Version), _database.CurrentSchemaVersion);
            if (!discovery.Available || discovery.Feed is null)
            {
                if (showUpToDate) MessageBox.Show(this, discovery.Detail, discovery.Status, MessageBoxButton.OK,
                    discovery.Status == "Up to date" ? MessageBoxImage.Information : MessageBoxImage.Warning);
                return;
            }
            Mouse.OverrideCursor = null;
            var download = MessageBox.Show(this,
                discovery.Detail + $"\n\nDownload and fully verify {discovery.Feed.PackageBytes:N0} bytes over HTTPS?\n\nNo application files or SQLite data are changed by this step.",
                "Signed Application Update Available", MessageBoxButton.YesNo, MessageBoxImage.Information, MessageBoxResult.No);
            if (download != MessageBoxResult.Yes) return;
            Mouse.OverrideCursor = Cursors.Wait;
            var result = await service.DownloadAsync(discovery.Feed, Version.Parse(BuildInfo.Version), _database.CurrentSchemaVersion);
            Mouse.OverrideCursor = null;
            var manifest = result.Readiness.Manifest!;
            var apply = MessageBox.Show(this,
                $"Downloaded update v{manifest.ReleaseVersion} passed exact inventory, bytes, SHA-256, trusted signature, version and SQLite schema verification.\n\n" +
                "Apply it now? A verified SQLite backup and last-known-good application snapshot are created first. SQLite is never restored automatically.",
                "Confirm Guarded Application Update", MessageBoxButton.YesNo, MessageBoxImage.Warning, MessageBoxResult.No);
            if (apply == MessageBoxResult.Yes) StartGuardedApplicationUpdate(result.PackagePath, manifest);
        }
        catch (Exception ex) { if (showUpToDate) MessageBox.Show(this, ex.Message, "Remote Update Check Failed", MessageBoxButton.OK, MessageBoxImage.Warning); }
        finally { Mouse.OverrideCursor = null; }
    }

    private async void PublishApplicationRelease_Click(object sender, RoutedEventArgs e)
    {
        if (IsAutomationActionBlocked("Application release publishing")) return;
        var dialog = new OpenFileDialog
        {
            Title = "Select Governed Application Deployment Plan",
            Filter = "Application deployment plan (application-deployment-plan.json)|application-deployment-plan.json",
            CheckFileExists = true,
            Multiselect = false
        };
        if (dialog.ShowDialog(this) != true) return;
        try
        {
            var deployment = _database.LoadDeploymentSettings();
            var service = new ApplicationDeploymentService(deployment);
            var plan = service.LoadAndVerify(dialog.FileName);
            var summary = string.Join("\n", plan.Files.Select(file => $"- {file.Kind}: {file.Bytes:N0} bytes -> {file.StableRemotePath}"));
            var answer = MessageBox.Show(this,
                $"Publish application release v{plan.ReleaseVersion} {plan.ReleaseCode} over explicit FTPS?\n\n{summary}\n\n" +
                "Versioned artifacts are activated first. Stable browser download routes are activated last. Existing remote files are retained in a separate application-release backup. " +
                "This does not read or change website deployment manifests, SQLite data or update transaction evidence.\n\nContinue?",
                "Confirm Application Release Publish", MessageBoxButton.YesNo, MessageBoxImage.Warning, MessageBoxResult.No);
            if (answer != MessageBoxResult.Yes) return;
            var password = WindowsCredentialService.ReadPassword(deployment.FtpsHost, deployment.FtpsUserName);
            if (string.IsNullOrWhiteSpace(password)) throw new InvalidOperationException("No FTPS password is stored for the governed host/user identity. Run the existing FTPS connection test first.");
            Mouse.OverrideCursor = Cursors.Wait;
            var result = await Task.Run(() => service.Publish(password, dialog.FileName));
            MessageBox.Show(this,
                $"Application release published.\n\nVersion: v{plan.ReleaseVersion}\nFiles: {result.PublishedPaths.Count:N0}\nBackup: {result.BackupFolder}\n\n" +
                "Installer: https://www.iskort.is/3dp/downloads/3DPIceland-Setup-x64.exe\n" +
                "Portable: https://www.iskort.is/3dp/downloads/3DPIceland-Portable-x64.zip",
                "Application Release Published", MessageBoxButton.OK, MessageBoxImage.Information);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Application Release Publish Failed", MessageBoxButton.OK, MessageBoxImage.Error);
        }
        finally { Mouse.OverrideCursor = null; }
    }

