    private void StartGuardedApplicationUpdate(string packagePath, ApplicationUpdateManifest manifest)
    {
        if (IsAutomationActionBlocked("Guarded application update")) return;
        try
        {
            var executable = Environment.ProcessPath ?? throw new InvalidOperationException("Current application executable path is unavailable.");
            var liveDirectory = IOPath.GetFullPath(AppContext.BaseDirectory).TrimEnd(IOPath.DirectorySeparatorChar);
            var applicationRelativePath = IOPath.GetFileName(executable);
            if (!manifest.Files.Any(file => string.Equals(file.Path, applicationRelativePath, StringComparison.Ordinal)))
                throw new InvalidOperationException("The signed package does not govern the running application executable.");
            const string helperName = "3DPIcelandUpdater.exe";
            var installedHelper = IOPath.Combine(liveDirectory, helperName);
            if (!File.Exists(installedHelper)) throw new FileNotFoundException("The external updater helper is not installed beside the application.", installedHelper);

            var updateRoot = IOPath.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "3DPIcelandLabs", "Updates", "transactions");
            if (!string.Equals(IOPath.GetPathRoot(updateRoot), IOPath.GetPathRoot(liveDirectory), StringComparison.OrdinalIgnoreCase))
                throw new InvalidOperationException("Update transaction and application directories must be on the same volume.");
            var transactionId = DateTime.UtcNow.ToString("yyyyMMddHHmmssfff", CultureInfo.InvariantCulture) + "-" + Guid.NewGuid().ToString("N");
            var transactionDirectory = IOPath.Combine(updateRoot, transactionId);
            var stagingDirectory = IOPath.Combine(transactionDirectory, "staging");
            var rollbackDirectory = IOPath.Combine(transactionDirectory, "rollback");
            var statePath = IOPath.Combine(transactionDirectory, "transaction-state.json");
            var acknowledgementPath = IOPath.Combine(transactionDirectory, "health-ack.json");
            Directory.CreateDirectory(transactionDirectory);

            var packageService = new ApplicationUpdatePackageService();
            var extractedManifest = packageService.ExtractVerifiedPackage(packagePath, Version.Parse(BuildInfo.Version), _database.CurrentSchemaVersion, stagingDirectory);
            if (!string.Equals(extractedManifest.ReleaseVersion, manifest.ReleaseVersion, StringComparison.Ordinal))
                throw new InvalidOperationException("Package identity changed between readiness and staging verification.");
            ApplyNativeMaterialComputedFieldsToAllRows();
            SaveNativeMaterialsSilent();
            if (_nativeMaterialDirty) throw new InvalidOperationException("Current Materials edits could not be saved; update was blocked before shutdown.");
            var databaseBackup = _database.CreateManualBackupNow();

            var runnerPath = IOPath.Combine(transactionDirectory, "3DPIcelandUpdater.runner.exe");
            var verifiedStagedHelper = IOPath.Combine(stagingDirectory, helperName);
            if (!File.Exists(verifiedStagedHelper)) throw new FileNotFoundException("The verified update package does not contain the governed updater helper.", verifiedStagedHelper);
            File.Copy(verifiedStagedHelper, runnerPath, overwrite: false);
            var request = new ApplicationUpdateTransactionRequest
            {
                TransactionId = transactionId, LiveDirectory = liveDirectory, StagingDirectory = stagingDirectory, RollbackDirectory = rollbackDirectory,
                StatePath = statePath, PreviousVersion = BuildInfo.Version, NewVersion = manifest.ReleaseVersion, DatabaseBackupPath = databaseBackup.FullName,
                ReleaseCode = manifest.ReleaseCode, SignatureAlgorithm = manifest.SignatureAlgorithm,
                SigningKeyFingerprint = ApplicationUpdatePackageService.ProductionTrustedPublicKeyFingerprint,
                ApplicationRelativePath = applicationRelativePath, WaitForProcessId = Environment.ProcessId, HealthAcknowledgementPath = acknowledgementPath,
                HealthTimeoutSeconds = 90, MinimumDatabaseSchema = manifest.MinimumDatabaseSchema, MaximumDatabaseSchema = manifest.MaximumDatabaseSchema,
                GovernedFiles = manifest.Files.Select(file => file.Path).ToList()
            };
            var requestPath = IOPath.Combine(transactionDirectory, "update-request.json");
            File.WriteAllText(requestPath, JsonSerializer.Serialize(request, new JsonSerializerOptions { WriteIndented = true }));

            var start = new ProcessStartInfo(runnerPath) { UseShellExecute = false, WorkingDirectory = transactionDirectory };
            start.ArgumentList.Add("--apply"); start.ArgumentList.Add(requestPath);
            _ = Process.Start(start) ?? throw new InvalidOperationException("External updater helper could not be started.");
            _databaseRestoreShutdown = true;
            Application.Current.Shutdown();
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Guarded Application Update Failed Before Shutdown", MessageBoxButton.OK, MessageBoxImage.Error);
        }
    }

    internal void DetectInterruptedApplicationUpdateAtStartup()
    {
        try
        {
            var diagnostic = GetApplicationUpdateDiagnostics().FirstOrDefault(item => item.IsIncomplete);
            if (diagnostic is null) return;
            var message = $"An interrupted application update was detected.\n\n" +
                          $"Transaction: {diagnostic.TransactionId}\nPhase: {diagnostic.Phase}\n" +
                          $"Versions: v{diagnostic.PreviousVersion} -> v{diagnostic.NewVersion}\n" +
                          $"Safe action: {diagnostic.RecoveryAction}\n\n" +
                          "Recovery may change governed application files and restart the application. " +
                          "SQLite will not be restored and all transaction evidence and backups will be retained.\n\n" +
                          "Run guarded recovery now?";
            var answer = MessageBox.Show(this, message, "Interrupted Application Update", MessageBoxButton.YesNo,
                MessageBoxImage.Warning, MessageBoxResult.No);
            if (answer != MessageBoxResult.Yes) return;
            StartInterruptedApplicationUpdateRecovery(diagnostic);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Application Update Recovery Detection", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

    private void StartInterruptedApplicationUpdateRecovery(ApplicationUpdateTransactionDiagnostic diagnostic)
    {
        if (!diagnostic.StateReadable || !diagnostic.RequestReadable)
            throw new InvalidOperationException("Recovery is blocked because durable state and request identity do not match.");
        var request = JsonSerializer.Deserialize<ApplicationUpdateTransactionRequest>(File.ReadAllText(diagnostic.RequestPath))
            ?? throw new InvalidOperationException("Recovery request could not be read.");
        var liveDirectory = IOPath.GetFullPath(AppContext.BaseDirectory).TrimEnd(IOPath.DirectorySeparatorChar);
        if (!string.Equals(IOPath.GetFullPath(request.LiveDirectory).TrimEnd(IOPath.DirectorySeparatorChar), liveDirectory, StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException("Recovery request does not target the running application directory.");
        var installedHelper = IOPath.Combine(liveDirectory, "3DPIcelandUpdater.exe");
        if (!File.Exists(installedHelper)) throw new FileNotFoundException("The installed recovery-capable updater helper is missing.", installedHelper);
        var runnerPath = IOPath.Combine(diagnostic.TransactionDirectory, "3DPIcelandUpdater.recovery.exe");
        if (!File.Exists(runnerPath)) File.Copy(installedHelper, runnerPath, overwrite: false);
        request.WaitForProcessId = Environment.ProcessId;
        var tempRequestPath = diagnostic.RequestPath + ".tmp";
        File.WriteAllText(tempRequestPath, JsonSerializer.Serialize(request, new JsonSerializerOptions { WriteIndented = true }));
        File.Move(tempRequestPath, diagnostic.RequestPath, true);
        var start = new ProcessStartInfo(runnerPath) { UseShellExecute = false, WorkingDirectory = diagnostic.TransactionDirectory };
        start.ArgumentList.Add("--recover"); start.ArgumentList.Add(diagnostic.RequestPath);
        _ = Process.Start(start) ?? throw new InvalidOperationException("External recovery helper could not be started.");
        _databaseRestoreShutdown = true;
        Application.Current.Shutdown();
    }

    private static IReadOnlyList<ApplicationUpdateTransactionDiagnostic> GetApplicationUpdateDiagnostics()
    {
        if (AutomationRuntimeProfile.IsActive)
            return Array.Empty<ApplicationUpdateTransactionDiagnostic>();
        var root = IOPath.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "3DPIcelandLabs", "Updates", "transactions");
        return ApplicationUpdateTransactionDiagnostics.InspectRoot(root);
    }


