        };
        AutomationProperties.SetAutomationId(reportBox, "SystemDiagnosticsReportText");

        Button MakeButton(string text, string automationId, RoutedEventHandler handler)
        {
            var button = new Button
            {
                Content = text,
                Padding = new Thickness(10, 4, 10, 4),
                Margin = new Thickness(0, 0, 8, 0)
            };
            AutomationProperties.SetAutomationId(button, automationId);
            button.Click += handler;
            return button;
        }

        toolbar.Children.Add(MakeButton("Refresh", "RefreshSystemDiagnostics",
            (_, _) => reportBox.Text = BuildSystemDiagnosticsReport()));
        toolbar.Children.Add(MakeButton("Run Integrity Check", "RunSystemIntegrityCheck", (_, _) =>
        {
            try
            {
                var result = _database.RunIntegrityCheck();
                reportBox.Text = BuildSystemDiagnosticsReport() + "\n\nLast integrity check result: " + result;
                MessageBox.Show(window, result, "SQLite Integrity Check", MessageBoxButton.OK,
                    string.Equals(result, "ok", StringComparison.OrdinalIgnoreCase) ? MessageBoxImage.Information : MessageBoxImage.Warning);
            }
            catch (Exception ex)
            {
                MessageBox.Show(window, ex.Message, "Integrity check failed", MessageBoxButton.OK, MessageBoxImage.Warning);
            }
        }));
        toolbar.Children.Add(MakeButton("Recalculate All Materials", "RecalculateAllMaterials", (_, _) =>
        {
            ApplyNativeTensileComputedFields(_nativeTensileRows);
            ApplyNativeImpactComputedFields(_nativeImpactRows);
            ApplyNativeStiffnessComputedFields(_nativeStiffnessRows);
            UpdateNativeWorkflowStatus("Recalculated native measurement results", saved: true);
            reportBox.Text = BuildSystemDiagnosticsReport();
        }));
        toolbar.Children.Add(MakeButton("Export Report", "ExportSystemDiagnostics",
            (_, _) => ExportDiagnosticsReport(reportBox.Text, isVerificationReport: false)));

        DockPanel.SetDock(toolbar, Dock.Top);
        root.Children.Add(toolbar);
        root.Children.Add(reportBox);
        window.Content = root;
        window.ShowDialog();
    }

    private void AppendRuntimeProfileDiagnostics(StringBuilder sb)
    {
        var profile = RuntimeProfileContext.Current;
        sb.AppendLine("Runtime Profile");
        sb.AppendLine("---------------");
        sb.AppendLine("Identity: " + profile.VisibleIdentity);
        sb.AppendLine("Kind: " + profile.Kind);
        sb.AppendLine("Profile ID: " + profile.ProfileId);
        sb.AppendLine("Disposable: " + profile.IsDisposable);
        sb.AppendLine("Database ownership: " + profile.DatabaseOwnership);
        sb.AppendLine("Database path: " + _database.DatabasePath);
        sb.AppendLine("Preferences ownership: " + profile.PreferencesOwnership);
        sb.AppendLine("Output ownership: " + profile.OutputOwnership);
        sb.AppendLine("Credential ownership: " + profile.CredentialOwnership);
        sb.AppendLine("Update transaction ownership: " + profile.UpdateTransactionOwnership);
        sb.AppendLine("Evidence ownership: " + profile.EvidenceOwnership);
        sb.AppendLine("Cleanup ownership: " + profile.CleanupOwnership);
        sb.AppendLine("Capabilities: " + profile.CapabilitySummary);
        sb.AppendLine("Profile identity does not weaken crash, recovery, security, updater transaction or support evidence.");
    }

    private string BuildSystemDiagnosticsReport()
    {
        var sb = new StringBuilder();
        sb.AppendLine("3DPIceland Engineering Platform - System Diagnostics");
        sb.AppendLine("Generated: " + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture));
        sb.AppendLine();

        sb.AppendLine("Application");
        sb.AppendLine("-----------");
        sb.AppendLine("Version: " + BuildInfo.ShortLabel + " - " + BuildInfo.ReleaseTitle);
        sb.AppendLine("Build date: " + GetApplicationBuildDateText());
        sb.AppendLine(".NET runtime: " + Environment.Version);
        sb.AppendLine("Windows/OS: " + Environment.OSVersion);
        sb.AppendLine("Process working set: " + FormatByteSize(Environment.WorkingSet));
        sb.AppendLine("64-bit process: " + Environment.Is64BitProcess);
        sb.AppendLine();

        AppendRuntimeProfileDiagnostics(sb);
        sb.AppendLine();

        var aiProviderConfiguration = _workflowPreferencesService.GetAiAssistantProviderConfiguration();
        var aiProvider = AiAssistantProviderRegistry.Resolve(
            aiProviderConfiguration.ProviderId,
            AutomationRuntimeProfile.IsActive);
        var aiCredentialConfigured = !AutomationRuntimeProfile.IsActive &&
                                     !string.IsNullOrWhiteSpace(
                                         WindowsCredentialService.ReadSecret(
                                             OpenAiAssistantProviderFoundation.CredentialTarget));
        var aiProviderDiagnostic = aiProvider.Inspect(aiProviderConfiguration, aiCredentialConfigured);
        sb.AppendLine("Optional AI Assistant Provider");
        sb.AppendLine("------------------------------");
        sb.AppendLine("Provider: " + aiProviderDiagnostic.ProviderId);
        sb.AppendLine("Model preference: " +
                      (string.IsNullOrWhiteSpace(aiProviderDiagnostic.Model)
                          ? "N/A"
                          : aiProviderDiagnostic.Model));
        sb.AppendLine("Credential configured: " +
                      (AutomationRuntimeProfile.IsActive
                          ? "Owner credential inaccessible"
                          : aiCredentialConfigured ? "Yes (Windows Credential Manager)" : "No"));
        sb.AppendLine("Foundation ready: " + aiProviderDiagnostic.IsReady);
        sb.AppendLine("Network used by diagnostic: " + aiProviderDiagnostic.UsedNetwork);
        sb.AppendLine("Credential value, Authorization header and outbound payload are never included in Diagnostics.");
        sb.AppendLine();

        sb.AppendLine("ECB Exchange-rate Reference (read-only)");
        sb.AppendLine("---------------------------------------");
        sb.AppendLine("Provider: " + EcbExchangeRateReferenceService.ProviderName);
        sb.AppendLine("Endpoint: " + EcbExchangeRateReferenceService.ApiUrl);
        sb.AppendLine("Cache: " + EcbExchangeRateCachePath());
        sb.AppendLine("Cached fetch UTC: " +
                      (_ecbExchangeRateCatalog?.FetchedAtUtc ?? "Not available"));
        sb.AppendLine("Latest observation: " +
                      (_ecbExchangeRateCatalog?.Rates
                           .Select(rate => rate.ObservationDate)
                           .OrderByDescending(value => value, StringComparer.Ordinal)
                           .FirstOrDefault() ?? "Not available"));
        var configuredLandedCostCurrency = _nativeSettingsRows.FirstOrDefault(row =>
            string.Equals(row.Section, "Currency", StringComparison.OrdinalIgnoreCase) &&
            string.Equals(row.Parameter, "Default Landed Cost Currency", StringComparison.OrdinalIgnoreCase) &&
            string.Equals(row.UsedBy, "Purchasing", StringComparison.OrdinalIgnoreCase))?.Value;
        sb.AppendLine("Configured landed-cost default: " +
                      (string.IsNullOrWhiteSpace(configuredLandedCostCurrency)
                          ? "Not configured"
                          : configuredLandedCostCurrency));
        sb.AppendLine("Effective landed-cost default: " + GetDefaultLandedCostCurrency());
        var diagnosticPurchaseOrders = _database.LoadPurchaseOrders();
        var diagnosticInventory = _database.LoadInventorySpoolItems();
        var currentPurchaseSnapshots = diagnosticPurchaseOrders.Count(order =>
            string.Equals(
                order.LandedCostCalculationVersion,
                LandedCostCalculationVersion,
                StringComparison.Ordinal));
        var legacyPurchaseSnapshots = diagnosticPurchaseOrders.Count(order =>
            string.Equals(
                order.LandedCostCalculationVersion,
                "legacy-v1",
                StringComparison.Ordinal));
        var otherPurchaseSnapshots = diagnosticPurchaseOrders.Count(order =>
            !string.IsNullOrWhiteSpace(order.LandedCostCalculationVersion) &&
            !string.Equals(
                order.LandedCostCalculationVersion,
                LandedCostCalculationVersion,
                StringComparison.Ordinal) &&
            !string.Equals(
                order.LandedCostCalculationVersion,
                "legacy-v1",
                StringComparison.Ordinal));
        var uncalculatedPurchaseSnapshots = diagnosticPurchaseOrders.Count(order =>
            string.IsNullOrWhiteSpace(order.LandedCostCalculationVersion));
        var currentInventorySnapshots = diagnosticInventory.Count(item =>
            string.Equals(
                item.LandedCostCalculationVersion,
                LandedCostCalculationVersion,
                StringComparison.Ordinal));
        var legacyInventorySnapshots = diagnosticInventory.Count(item =>
            string.Equals(
                item.LandedCostCalculationVersion,
                "legacy-v1",
                StringComparison.Ordinal));
        var otherInventorySnapshots = diagnosticInventory.Count(item =>
            !string.IsNullOrWhiteSpace(item.LandedCostCalculationVersion) &&
            !string.Equals(
                item.LandedCostCalculationVersion,
                LandedCostCalculationVersion,
                StringComparison.Ordinal) &&
            !string.Equals(
                item.LandedCostCalculationVersion,
                "legacy-v1",
                StringComparison.Ordinal));
        var unversionedInventorySnapshots = diagnosticInventory.Count(item =>
            string.IsNullOrWhiteSpace(item.LandedCostCalculationVersion));
        sb.AppendLine(
            $"Purchase Order landed-cost snapshots: current {currentPurchaseSnapshots}; " +
            $"legacy {legacyPurchaseSnapshots}; other versioned {otherPurchaseSnapshots}; " +
            $"uncalculated {uncalculatedPurchaseSnapshots}.");
        sb.AppendLine(
            $"Inventory landed-cost snapshots: current {currentInventorySnapshots}; " +
            $"legacy {legacyInventorySnapshots}; other versioned {otherInventorySnapshots}; " +
            $"unversioned {unversionedInventorySnapshots}.");
        sb.AppendLine("Calculation contract: invoice inputs/allocations stay in invoice currency; " +
                      "only landed line/unit/kg results use the snapshotted landed currency.");
        sb.AppendLine("Ownership: reference data may prefill only a newly created uncalculated Draft. " +
                      "Saved purchases, inventory, Materials and quotes are never refreshed or recalculated.");
        sb.AppendLine("Migration/recovery contract: schema-v37 startup migration and governed Excel restore " +
                      "are verified separately; opening or refreshing Diagnostics never executes either workflow.");
        sb.AppendLine("Disposable landed-cost workflow authorization: " +
                      (AutomationRuntimeProfile.Current?.LandedCostWorkflowAuthorized == true
                          ? "Exact disposable PO/Material/Inventory identities only"
                          : "Not authorized"));
        sb.AppendLine("Automation evidence boundary: currencies, rate provenance, calculation version, " +
                      "restart checkpoints and state hashes only; supplier, notes, credentials and owner paths excluded.");
        sb.AppendLine();

        var updateDiagnostics = GetApplicationUpdateDiagnostics();
        sb.AppendLine("Application Update Transactions (read-only)");
        sb.AppendLine("-------------------------------------------");
        sb.AppendLine("Transactions found: " + updateDiagnostics.Count.ToString("N0", CultureInfo.CurrentCulture));
        sb.AppendLine("Incomplete: " + updateDiagnostics.Count(item => item.IsIncomplete).ToString("N0", CultureInfo.CurrentCulture));
        foreach (var item in updateDiagnostics)
        {
            sb.AppendLine($"{item.UpdatedAtUtc} | {item.TransactionId} | v{item.PreviousVersion} -> v{item.NewVersion} | {item.Phase}");
            sb.AppendLine("  Package identity: " + (string.IsNullOrWhiteSpace(item.ReleaseCode) ? "Legacy transaction; release code not recorded" : item.ReleaseCode));
            sb.AppendLine("  Signature identity: " + (string.IsNullOrWhiteSpace(item.SignatureAlgorithm) ? "Legacy transaction; signature metadata not recorded" : item.SignatureAlgorithm + " / key " + item.SigningKeyFingerprint));
            sb.AppendLine("  Recovery: " + item.RecoveryAction);
            sb.AppendLine("  SQLite backup evidence: " + (string.IsNullOrWhiteSpace(item.DatabaseBackupPath) ? "None recorded" : item.DatabaseBackupPath));
            sb.AppendLine("  " + item.Detail);
        }
        sb.AppendLine("Diagnostics do not modify application files, transaction evidence, backups or SQLite data.");
        sb.AppendLine();

        sb.AppendLine(App.StartupPerformance.BuildDiagnosticsReport());

        sb.AppendLine("Database");
        sb.AppendLine("--------");
        sb.AppendLine("Database path: " + _database.DatabasePath);
        sb.AppendLine("Database folder: " + _database.DatabaseFolder);
        sb.AppendLine("Executable path: " + GetExecutablePathForDiagnostics());
        sb.AppendLine("Executable folder: " + AppContext.BaseDirectory);
        sb.AppendLine("Database modified: " + GetFileModifiedText(_database.DatabasePath));
        sb.AppendLine("Legacy snapshot folder governance: " + (NativeWorkingCopiesUseStorageFolder() ? "PASS" : "FAIL"));
        sb.AppendLine("Legacy materials snapshot: " + NativeMaterialsFilePath());
        sb.AppendLine("Legacy tensile migration snapshot: " + NativeTensileFilePath());
        sb.AppendLine("Legacy impact migration snapshot: " + NativeImpactFilePath());
        sb.AppendLine("Legacy stiffness migration snapshot: " + NativeStiffnessFilePath());
        sb.AppendLine("SQLite file size: " + GetFileSizeText(_database.DatabasePath));
        sb.AppendLine("Schema version: " + _database.CurrentSchemaVersion);
        sb.AppendLine("Last auto-save text: " + (FindName("LastSavedText") is TextBlock lastSaved ? lastSaved.Text : "—"));
        sb.AppendLine("Auto-save status: " + (FindName("AutoSaveStatusText") is TextBlock autoSave ? autoSave.Text : "—"));
        sb.AppendLine();

        var backups = _database.GetAutomaticBackups();
        var latestBackup = backups.FirstOrDefault();
        var retainedLegacyAutomaticBackups = _database.GetRetainedLegacyAutomaticBackupCount();
        sb.AppendLine("Backups");
        sb.AppendLine("-------");
        sb.AppendLine("Backup folder: " + _database.BackupFolder);
        sb.AppendLine("Rotating automatic backups: " + backups.Count + " / 20");
        sb.AppendLine("Retained legacy automatic backups: " + retainedLegacyAutomaticBackups + " (not rotated by v44.7.8)");
        sb.AppendLine("Latest backup: " + (latestBackup is null ? "None" : latestBackup.Name + " (" + latestBackup.CreationTime.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture) + ")"));
        var recoveryCatalog = _database.GetLocalBackupCatalog();
        sb.AppendLine("Recovery Center catalog: " + recoveryCatalog.Count + " SQLite backup(s)");
        foreach (var group in recoveryCatalog.GroupBy(item => item.CompatibilityStatus).OrderBy(group => group.Key, StringComparer.OrdinalIgnoreCase))
            sb.AppendLine("- " + group.Key + ": " + group.Count());
        sb.AppendLine("Compatibility policy: schema 27-32 require isolated migration dry-run; schema 33 ready; older/newer/corrupt blocked");
        sb.AppendLine();

        sb.AppendLine("Website Export Routing");
        sb.AppendLine("----------------------");
        var websiteRoot = WebsiteExportFolderBox.Text?.Trim();
        if (string.IsNullOrWhiteSpace(websiteRoot)) websiteRoot = GetDefaultWebsiteExportFolder();
        var mainTemplate = System.IO.Path.Combine(websiteRoot, "index.html");
        var manufacturerRedirect = System.IO.Path.Combine(websiteRoot, "manufacturers", "index.html");
        sb.AppendLine("Website root: " + websiteRoot);
        sb.AppendLine("Main template: " + mainTemplate + " [" + (File.Exists(mainTemplate) ? "FOUND" : "MISSING / bundled fallback") + "]");
        sb.AppendLine("Main preview: " + System.IO.Path.Combine(websiteRoot, "index-test.html"));
        sb.AppendLine("Manufacturers redirect: " + manufacturerRedirect + " [" + (File.Exists(manufacturerRedirect) ? "FOUND" : "MISSING / generated with production export") + "]");
        sb.AppendLine("Manufacturers production redirect target: ../index.html#manufacturers");
        sb.AppendLine("Manufacturers preview redirect target: ../index-test.html#manufacturers");
        sb.AppendLine("Manufacturers canonical URL: https://iskort.is/3dp/index.html#manufacturers");
        sb.AppendLine("Manufacturers redirect preview: " + System.IO.Path.Combine(websiteRoot, "manufacturers", "index-test.html"));
        sb.AppendLine();

        sb.AppendLine("Project Statistics");
        sb.AppendLine("------------------");
        sb.AppendLine("Native materials: " + _nativeMaterialRows.Count);
        sb.AppendLine("Native tensile rows: " + _nativeTensileRows.Count);
        sb.AppendLine("Native impact rows: " + _nativeImpactRows.Count);
        sb.AppendLine("Native stiffness rows: " + _nativeStiffnessRows.Count);
        sb.AppendLine("Native settings rows: " + _nativeSettingsRows.Count);
        var diagnosticExperimentalRuns = _database.GetExperimentalRunStats();
        var diagnosticExperimentalMeasurements = _database.GetExperimentalMeasurementStats();
        sb.AppendLine("Experimental series: " + _materialExperimentRows.Count);
        sb.AppendLine("Experimental runs: " + diagnosticExperimentalRuns.Runs);
        sb.AppendLine("Experimental baseline runs: " + diagnosticExperimentalRuns.BaselineRuns);
        sb.AppendLine("Experimental orphaned runs: " + diagnosticExperimentalRuns.OrphanedSeries);
        sb.AppendLine("Experimental measurements: " + diagnosticExperimentalMeasurements.Measurements);
        sb.AppendLine("Experimental orphaned measurements: " + diagnosticExperimentalMeasurements.OrphanedRuns);
        sb.AppendLine();

        sb.AppendLine("Calculation Engine");
        sb.AppendLine("------------------");
        sb.AppendLine("Statistics Engine: Loaded");
        sb.AppendLine("Rating Engine: Loaded");
        sb.AppendLine("Results Engine: Loaded");
        sb.AppendLine("Tensile calculation migration: Active");
        sb.AppendLine("Impact calculation migration: Active");
        sb.AppendLine("Results service: " + _resultsService.GetType().Name);
        sb.AppendLine("Canonical MaterialID count: " + _nativeMaterialRows.Count);
        sb.AppendLine();

        sb.AppendLine(BuildNativeTensileVerificationReport());
        sb.AppendLine();
        sb.AppendLine(BuildNativeImpactVerificationReport());
        sb.AppendLine();

        sb.AppendLine("Project Information");
        sb.AppendLine("-------------------");
        sb.AppendLine("GitHub repository: https://github.com/marteinnsig/3DP-Iceland-FilamentDB");
        sb.AppendLine("Documentation: Docs/USER_GUIDE.md");
        sb.AppendLine("Changelog: Docs/CHANGELOG.md");

        return sb.ToString();
    }

    private static string FormatByteSize(long bytes)
    {
        const double scale = 1024d;
        if (bytes >= scale * scale * scale) return (bytes / (scale * scale * scale)).ToString("0.00", CultureInfo.InvariantCulture) + " GB";
        if (bytes >= scale * scale) return (bytes / (scale * scale)).ToString("0.00", CultureInfo.InvariantCulture) + " MB";
        if (bytes >= scale) return (bytes / scale).ToString("0.00", CultureInfo.InvariantCulture) + " KB";
        return bytes.ToString(CultureInfo.InvariantCulture) + " bytes";
    }

    private sealed class VerificationCheck
    {
        public VerificationCheck(string name, bool passed, string detail)
        {
            Name = name;
            Passed = passed;
            Detail = detail;
        }

        public string Name { get; }
        public bool Passed { get; }
        public string Detail { get; }
    }

    private enum VerificationCheckStatus
    {
        Pass,
        Fail,
        NotApplicable
    }

    private enum VerificationApplicability
    {
        Mandatory,
        CanonicalDataDependent
    }

    private sealed class VerificationProfileResult
    {
        public required RuntimeProfileDescriptor RuntimeProfile { get; init; }
        public required string ProfileName { get; init; }
        public required string ProfileReason { get; init; }
        public required IReadOnlyList<VerificationProfileCheck> Checks { get; init; }
        public int PassedCount => Checks.Count(check => check.Status == VerificationCheckStatus.Pass);
        public int FailedCount => Checks.Count(check => check.Status == VerificationCheckStatus.Fail);
        public int NotApplicableCount => Checks.Count(check => check.Status == VerificationCheckStatus.NotApplicable);
        public int MandatoryCount => Checks.Count(check => check.Applicability == VerificationApplicability.Mandatory);
        public int MandatoryEvidenceCount => Checks.Count(check => check.MandatoryEvidence);
        public int MandatoryEvidenceFailedCount => Checks.Count(check =>
            check.MandatoryEvidence && check.Status == VerificationCheckStatus.Fail);
        public int MandatoryNotApplicableCount => Checks.Count(check =>
            check.Applicability == VerificationApplicability.Mandatory &&
            check.Status == VerificationCheckStatus.NotApplicable);
        public int CanonicalDataNotApplicableCount => Checks.Count(check =>
            check.Applicability == VerificationApplicability.CanonicalDataDependent &&
            check.Status == VerificationCheckStatus.NotApplicable);
        public int ApplicableCount => PassedCount + FailedCount;
        public bool Passed => FailedCount == 0 && MandatoryNotApplicableCount == 0;
    }

    private sealed record VerificationProfileCheck(
        string Name,
        VerificationCheckStatus Status,
        string Detail,
        VerificationApplicability Applicability,
        bool MandatoryEvidence);

