    private static bool IsKnownZeroDataDependency(VerificationCheck check) =>
        CanonicalDataDependentCheckNames.Contains(check.Name) ||
        check.Name.StartsWith("v41.1 ", StringComparison.Ordinal) ||
        check.Name.StartsWith("v41.2 ", StringComparison.Ordinal) ||
        check.Name.StartsWith("v41.3 ", StringComparison.Ordinal) ||
        check.Name.StartsWith("v41.4 ", StringComparison.Ordinal) ||
        check.Name.StartsWith("v41.5 ", StringComparison.Ordinal) ||
        check.Name.StartsWith("v41.6 ", StringComparison.Ordinal) ||
        check.Name.StartsWith("v41.7.", StringComparison.Ordinal);

    private static bool IsMandatoryEvidenceCheck(string checkName) =>
        MandatoryEvidenceCheckNames.Contains(checkName);

    private string GetExecutablePathForDiagnostics()
    {
        return Environment.ProcessPath ?? AppContext.BaseDirectory;
    }

    private string GetFileModifiedText(string path)
    {
        try
        {
            return File.Exists(path)
                ? File.GetLastWriteTime(path).ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture)
                : "missing";
        }
        catch
        {
            return "unavailable";
        }
    }

    private bool IsPathInsideFolder(string path, string folder)
    {
        try
        {
            var fullPath = System.IO.Path.GetFullPath(path).TrimEnd(System.IO.Path.DirectorySeparatorChar, System.IO.Path.AltDirectorySeparatorChar);
            var fullFolder = System.IO.Path.GetFullPath(folder).TrimEnd(System.IO.Path.DirectorySeparatorChar, System.IO.Path.AltDirectorySeparatorChar);
            return fullPath.StartsWith(fullFolder + System.IO.Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(fullPath, fullFolder, StringComparison.OrdinalIgnoreCase);
        }
        catch
        {
            return false;
        }
    }

    private bool NativeWorkingCopiesUseStorageFolder()
    {
        var folder = _database.DatabaseFolder;
        return !string.IsNullOrWhiteSpace(folder) &&
               IsPathInsideFolder(NativeMaterialsFilePath(), folder) &&
               IsPathInsideFolder(NativeTensileFilePath(), folder) &&
               IsPathInsideFolder(NativeImpactFilePath(), folder) &&
               IsPathInsideFolder(NativeStiffnessFilePath(), folder) &&
               IsPathInsideFolder(NativeSettingsFilePath(), folder);
    }


    private sealed class PricingVerificationResult
    {
        public int ActiveMaterials { get; set; }
        public int CompletePricingRows { get; set; }
        public int MissingWeight { get; set; }
        public int MissingCheckedDate { get; set; }
        public int InvalidCurrency { get; set; }
        public int InvalidPriceValues { get; set; }
        public int InvalidNormalizedValues { get; set; }
        public List<string> MissingPricingMaterials { get; } = new();
        public int MissingPricingRows => MissingPricingMaterials.Count;
        public bool IntegrityPassed => ActiveMaterials > 0 && InvalidCurrency == 0 && InvalidPriceValues == 0 && InvalidNormalizedValues == 0 && MissingWeight == 0;
    }

    private PricingVerificationResult EvaluatePricingVerification()
    {
        var result = new PricingVerificationResult();
        foreach (var row in _nativeMaterialRows.Where(item => !item.IsArchived))
        {
            result.ActiveMaterials++;
            var msrp = NumberValue(row.MsrpUsd);
            var landed = NumberValue(row.LandedCostUsd);
            var weight = NumberValue(row.SpoolWeightG);
            var msrpPerKg = NumberValue(row.MsrpUsdPerKg);
            var landedPerKg = NumberValue(row.LandedCostUsdPerKg);
            var hasAnyPricing = !string.IsNullOrWhiteSpace(row.MsrpAmount) || !string.IsNullOrWhiteSpace(row.LandedCostAmount) || msrp.HasValue || landed.HasValue;

            if (hasAnyPricing && (!weight.HasValue || weight <= 0)) result.MissingWeight++;
            if (string.IsNullOrWhiteSpace(row.PriceCheckedDate)) result.MissingCheckedDate++;
            if (!PricingProvenanceService.IsSupportedCurrency(row.MsrpCurrency) ||
                !PricingProvenanceService.IsSupportedCurrency(row.LandedCostCurrency)) result.InvalidCurrency++;
            if ((msrp.HasValue && msrp <= 0) || (landed.HasValue && landed <= 0) ||
                (msrpPerKg.HasValue && msrpPerKg <= 0) || (landedPerKg.HasValue && landedPerKg <= 0)) result.InvalidPriceValues++;
            if ((msrp.HasValue && weight is > 0 && !msrpPerKg.HasValue) ||
                (landed.HasValue && weight is > 0 && !landedPerKg.HasValue)) result.InvalidNormalizedValues++;

            if (msrp is > 0 && landed is > 0 && weight is > 0 && msrpPerKg is > 0 && landedPerKg is > 0)
            {
                result.CompletePricingRows++;
            }
            else
            {
                var displayName = !string.IsNullOrWhiteSpace(row.WebsiteDisplayName)
                    ? row.WebsiteDisplayName
                    : string.Join(" ", new[] { row.Manufacturer, row.MarketingName }.Where(value => !string.IsNullOrWhiteSpace(value)));
                result.MissingPricingMaterials.Add(string.IsNullOrWhiteSpace(displayName) ? row.MaterialID : displayName + " [" + row.MaterialID + "]");
            }
        }
        return result;
    }

    private static string BuildPricingCompletenessDetail(PricingVerificationResult pricing)
    {
        var coverage = pricing.ActiveMaterials > 0
            ? (100.0 * pricing.CompletePricingRows / pricing.ActiveMaterials).ToString("0.0", CultureInfo.InvariantCulture) + "%"
            : "0.0%";
        if (pricing.MissingPricingRows == 0)
            return pricing.CompletePricingRows + " / " + pricing.ActiveMaterials + " active materials complete (" + coverage + ")";

        const int maxNames = 10;
        var missing = string.Join("; ", pricing.MissingPricingMaterials.Take(maxNames));
        if (pricing.MissingPricingRows > maxNames)
            missing += "; +" + (pricing.MissingPricingRows - maxNames) + " more";
        return pricing.CompletePricingRows + " / " + pricing.ActiveMaterials + " active materials complete (" + coverage + "). Optional pricing missing: " + missing;
    }

    private static MeasurementSetResult CreateConsistencyProbeSet(double? coefficientOfVariation, int sampleCount) => new(
        Average: sampleCount > 0 ? 100 : null,
        StandardDeviation: coefficientOfVariation.HasValue ? coefficientOfVariation.Value * 100 : null,
        CoefficientOfVariation: coefficientOfVariation,
        SampleCount: sampleCount,
        Confidence: sampleCount > 0 ? Math.Min(sampleCount, 10) : null,
        CompletenessRating: new RatingResult(sampleCount >= 5 ? 5 : sampleCount > 0 ? 1 : 0, "Probe", "Verification probe"));

    private List<VerificationCheck> BuildVerificationChecks()
    {
        var checks = new List<VerificationCheck>();
        var runtimeProfile = RuntimeProfileContext.Current;
        var ownerProfileContract = RuntimeProfileContext.DescribeOwnerProduction();
        var runtimeProfileFoundationReady =
            ownerProfileContract.Kind == RuntimeProfileKind.OwnerProduction &&
            ownerProfileContract.ProfileId == "owner-production" &&
            !ownerProfileContract.IsDisposable &&
            ownerProfileContract.OwnerDatabaseAllowed &&
            ownerProfileContract.ProductionAndFtpsAllowed &&
            ownerProfileContract.UpdatesAllowed &&
            FindName("RuntimeProfileIdentityText") is TextBlock runtimeIdentity &&
            AutomationProperties.GetAutomationId(runtimeIdentity) == "RuntimeProfileIdentity" &&
            string.Equals(runtimeIdentity.Text, runtimeProfile.VisibleIdentity, StringComparison.Ordinal) &&
            HelpContentCatalog.Sections.Single(
                section => section.Id == "menu-runtime.controls-fields").Body.Contains(
                "OWNER / PRODUCTION uses",
                StringComparison.Ordinal) &&
            (!AutomationRuntimeProfile.IsActive ||
             ((runtimeProfile.Kind == RuntimeProfileKind.DisposableVerification ||
               runtimeProfile.Kind == RuntimeProfileKind.CleanReadiness) &&
              runtimeProfile.IsDisposable &&
              !runtimeProfile.OwnerDatabaseAllowed &&
              !runtimeProfile.ProductionAndFtpsAllowed &&
              !runtimeProfile.UpdatesAllowed));
        checks.Add(new VerificationCheck("v51.1 governed runtime profile identity and capability contract",
            runtimeProfileFoundationReady,
            runtimeProfileFoundationReady
                ? $"{runtimeProfile.VisibleIdentity}; {runtimeProfile.CapabilitySummary}; database ownership: {runtimeProfile.DatabaseOwnership}"
                : "Owner/Disposable runtime identity, visible AutomationId or effective capability contract is incomplete."));
        var cleanProfileProbe = RuntimeProfileContext.DescribeCleanReadiness(new AutomationRuntimeProfile
        {
            ProfileId = "verification-probe",
            Purpose = AutomationRuntimeProfile.CleanReadinessPurpose
        });
        var cleanReadinessContractReady =
            AutomationRuntimeProfile.VerificationPurpose == "verification" &&
            AutomationRuntimeProfile.CleanReadinessPurpose == "clean-readiness" &&
            cleanProfileProbe.Kind == RuntimeProfileKind.CleanReadiness &&
            cleanProfileProbe.IsDisposable &&
            !cleanProfileProbe.OwnerDatabaseAllowed &&
            !cleanProfileProbe.ProductionAndFtpsAllowed &&
            !cleanProfileProbe.UpdatesAllowed &&
            cleanProfileProbe.VisibleIdentity.StartsWith("CLEAN / READINESS", StringComparison.Ordinal) &&
            cleanProfileProbe.DatabaseOwnership.Contains("Seedless", StringComparison.Ordinal) &&
            HelpContentCatalog.Sections.Single(
                section => section.Id == "menu-runtime.controls-fields").Body.Contains(
                "seedless disposable first-run contract",
                StringComparison.Ordinal);
        checks.Add(new VerificationCheck("v51.2 seedless Clean Readiness profile contract",
            cleanReadinessContractReady,
            cleanReadinessContractReady
                ? "Clean Readiness is manifest-contained, seedless and blocks owner database, Production/FTPS and updates"
                : "Clean Readiness purpose, identity, isolation, capability or Help contract is incomplete."));
        var verificationClassificationReady =
            IsKnownZeroDataDependency(new VerificationCheck(
                "Native material source loaded",
                false,
                "Deliberately unrelated detail")) &&
            !IsKnownZeroDataDependency(new VerificationCheck(
                "Release identity alignment",
                false,
                "Material Summary Engine verification has not passed")) &&
            IsMandatoryEvidenceCheck("Database path diagnostics") &&
            IsMandatoryEvidenceCheck("Guarded updater acceptance safety foundation") &&
            IsMandatoryEvidenceCheck("Disposable backup and recovery acceptance safety foundation") &&
            !IsMandatoryEvidenceCheck("Website pipeline source");
        checks.Add(new VerificationCheck("v51.3 Verification classification and mandatory evidence contract",
            verificationClassificationReady,
            verificationClassificationReady
                ? "Runtime/data profiles are distinct; exact-name applicability prevents detail text from granting N/A; path, recovery and updater evidence remain mandatory"
                : "Verification applicability, mandatory evidence ownership or detail-text isolation is incomplete."));
        var profileReconciliationReady =
            typeof(AutomationRuntimeProfile).GetProperty("VisibleIdentity") is null &&
            typeof(AutomationRuntimeProfile).GetMethod("DemandNetworkAndProductionBlocked") is null &&
            !string.IsNullOrWhiteSpace(runtimeProfile.CredentialOwnership) &&
            !string.IsNullOrWhiteSpace(runtimeProfile.UpdateTransactionOwnership) &&
            !string.IsNullOrWhiteSpace(runtimeProfile.EvidenceOwnership) &&
            !string.IsNullOrWhiteSpace(runtimeProfile.CleanupOwnership) &&
            (!AutomationRuntimeProfile.IsActive || GetApplicationUpdateDiagnostics().Count == 0) &&
            HelpContentCatalog.Sections.Single(
                section => section.Id == "menu-runtime.controls-fields").Body.Contains(
                "never read owner credentials or owner update-transaction history",
                StringComparison.Ordinal);
        checks.Add(new VerificationCheck("v51.4 profile ownership and retirement reconciliation contract",
            profileReconciliationReady,
            profileReconciliationReady
                ? "Startup, diagnostics, credentials, update history, evidence and cleanup ownership are explicit; caller-free identity/network adapters are retired"
                : "Profile ownership, disposable owner-history isolation, Help contract or retired adapter cleanup is incomplete."));
        var automationFoundationReady =
            AutomationRuntimeProfile.MarkerFileName == ".3dpiceland-disposable-profile.json" &&
            typeof(AutomationRuntimeProfile).GetMethod(nameof(AutomationRuntimeProfile.Configure)) is not null &&
            typeof(MainWindow).GetMethod(
                nameof(ExportAutomationVerificationEvidence),
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic) is not null &&
            FindName("WorkspaceTabs") is TabControl automationWorkspaceTabs &&
            AutomationProperties.GetAutomationId(automationWorkspaceTabs) == "WorkspaceTabs" &&
            FindName("FastMaterialsViewHost") is ContentControl automationMaterialsHost &&
            AutomationProperties.GetAutomationId(automationMaterialsHost) == "FastMaterialsViewHost";
        checks.Add(new VerificationCheck("Automated runtime acceptance safety foundation", automationFoundationReady,
            automationFoundationReady
                ? "Disposable-path validation, hard Production/FTPS/update locks, stable UI Automation IDs and TXT/JSON evidence are present"
                : "Disposable profile, safety-lock, AutomationId or machine-readable evidence contract is incomplete"));
        var automatedReportAcceptanceReady =
            typeof(AutomationRuntimeProfile).GetProperty(nameof(AutomationRuntimeProfile.ReportGenerationAuthorized)) is not null &&
            typeof(AutomationRuntimeProfile).GetMethod(nameof(AutomationRuntimeProfile.DemandReportGenerationAuthorized)) is not null &&
            FindName("BuildPublicEngineeringReportPackageButton") is Button automationReportButton &&
            AutomationProperties.GetAutomationId(automationReportButton) == "BuildPublicReportPackage" &&
            FindName("ReportOutputFolderBox") is TextBox automationReportOutput &&
            AutomationProperties.GetAutomationId(automationReportOutput) == "ReportOutputFolder" &&
            FindName("ReportPreviewLog") is TextBox automationReportLog &&
            AutomationProperties.GetAutomationId(automationReportLog) == "ReportPreviewLog";
        checks.Add(new VerificationCheck("Automated report acceptance safety foundation", automatedReportAcceptanceReady,
            automatedReportAcceptanceReady
                ? "Scenario authorization, disposable output binding, stable report completion IDs and artifact evidence contracts are present"
                : "Automated report authorization, output containment, completion or evidence contract is incomplete"));
        var disposableCrudAcceptanceReady =
            typeof(AutomationRuntimeProfile).GetProperty(nameof(AutomationRuntimeProfile.MaterialCrudAuthorized)) is not null &&
            typeof(AutomationRuntimeProfile).GetProperty(nameof(AutomationRuntimeProfile.MaterialCrudId)) is not null &&
            typeof(AutomationRuntimeProfile).GetMethod(nameof(AutomationRuntimeProfile.DemandMaterialCrudAuthorized)) is not null &&
            FindName("AutomationCrudPanel") is StackPanel &&
            FindName("AutomationCrudStatusText") is TextBlock automationCrudStatus &&
            AutomationProperties.GetAutomationId(automationCrudStatus) == "AutomationCrudStatus";
        checks.Add(new VerificationCheck("Disposable CRUD acceptance safety foundation", disposableCrudAcceptanceReady,
            disposableCrudAcceptanceReady
                ? "Exact-ID scenario authorization, profile-only commands and stable CRUD persistence evidence IDs are present"
                : "Disposable CRUD authorization, exact-ID guard or stable evidence contract is incomplete"));
        var disposableRecoveryAcceptanceReady =
            typeof(AutomationRuntimeProfile).GetProperty(nameof(AutomationRuntimeProfile.RecoveryAuthorized)) is not null &&
            typeof(AutomationRuntimeProfile).GetMethod(nameof(AutomationRuntimeProfile.DemandRecoveryAuthorized)) is not null &&
            typeof(ExcelRecoveryRestoreResult).GetProperty(nameof(ExcelRecoveryRestoreResult.PostRestoreBackupPath)) is not null &&
            FindName("AutomationRecoveryPanel") is StackPanel &&
            FindName("AutomationRecoveryStatusText") is TextBlock automationRecoveryStatus &&
            AutomationProperties.GetAutomationId(automationRecoveryStatus) == "AutomationRecoveryStatus" &&
            LocalDatabase.BackupFilenameCompatibilityContractIsReady();
        checks.Add(new VerificationCheck("Disposable backup and recovery acceptance safety foundation",
            disposableRecoveryAcceptanceReady,
            disposableRecoveryAcceptanceReady
                ? "Scenario authorization, legacy/new backup discovery, governed Excel restore and pre/post evidence contracts are present"
                : "Disposable recovery authorization, backup compatibility or pre/post evidence contract is incomplete"));
        var guardedUpdaterAcceptanceReady =
            typeof(AutomationRuntimeProfile).GetProperty(nameof(AutomationRuntimeProfile.UpdaterAuthorized)) is not null &&
            typeof(ApplicationUpdateTransactionRequest).GetProperty(
                nameof(ApplicationUpdateTransactionRequest.AutomationProfilePath)) is not null &&
            ApplicationUpdateTransactionEngine.RunContractVerification().Passed;
        checks.Add(new VerificationCheck("Guarded updater acceptance safety foundation",
            guardedUpdaterAcceptanceReady,
            guardedUpdaterAcceptanceReady
                ? "Explicit disposable updater authorization, profile forwarding, transaction rollback and health contracts are present"
                : "Disposable updater authorization, profile forwarding, rollback or health contract is incomplete"));
        var workspaceTabHeaders = WorkspaceTabs.Items.OfType<TabItem>()
            .Select(item => item.Header?.ToString() ?? string.Empty)
            .ToList();
        var websiteExportTabIndex = workspaceTabHeaders.IndexOf("Website Export");
        var workspaceTabOrderReady =
            workspaceTabHeaders.IndexOf("Materials") == 0 &&
            workspaceTabHeaders.IndexOf("Material Detail") == 1 &&
            websiteExportTabIndex >= 0 &&
            workspaceTabHeaders.IndexOf("Manufacturers") == websiteExportTabIndex + 1 &&
            workspaceTabHeaders.IndexOf("Purchase Orders") == websiteExportTabIndex + 2 &&
            workspaceTabHeaders.IndexOf("Inventory") == websiteExportTabIndex + 3 &&
            workspaceTabHeaders.IndexOf("Experimental Testing") == websiteExportTabIndex + 4;
        checks.Add(new VerificationCheck("Workspace tab priority order", workspaceTabOrderReady,
            "Materials and Material Detail stay together; secondary workflow tabs follow Website Export"));
        var canonicalActiveRows = GetCanonicalActiveMaterialRows();
        var canonicalVisibleRows = GetCanonicalVisibleMaterialRows();
        var canonicalActiveIds = canonicalActiveRows
            .Select(row => GetCell(row, "Material ID"))
            .Where(id => !string.IsNullOrWhiteSpace(id))
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        var canonicalVisibleIds = canonicalVisibleRows
            .Select(row => GetCell(row, "Material ID"))
            .Where(id => !string.IsNullOrWhiteSpace(id))
            .ToList();
        var legacyMaterialTabAbsent = !workspaceTabHeaders.Any(header => header.Contains("legacy import cache", StringComparison.OrdinalIgnoreCase));
        var canonicalMaterialProjectionReady = canonicalActiveRows.Count == _nativeMaterialRows.Count(row => !row.IsArchived) &&
                                               canonicalActiveIds.Count == canonicalActiveRows.Count &&
                                               canonicalVisibleIds.Count == canonicalVisibleRows.Count &&
                                               canonicalVisibleIds.Distinct(StringComparer.OrdinalIgnoreCase).Count() == canonicalVisibleIds.Count &&
                                               canonicalVisibleIds.All(canonicalActiveIds.Contains) &&
                                               legacyMaterialTabAbsent;
        checks.Add(new VerificationCheck("Canonical material projection", canonicalMaterialProjectionReady,
            canonicalMaterialProjectionReady
                ? $"{canonicalVisibleRows.Count} visible and {canonicalActiveRows.Count} active unique MaterialIDs come from the native SQLite-backed Materials view; legacy tab absent"
                : "Native active/visible MaterialID parity or legacy-tab removal failed"));
        var materialFilterContract =
            MaterialFilterProjectionService.RunContractVerification();
        checks.Add(new VerificationCheck(
            "v54 Materials OR-within AND-between filter contract",
            materialFilterContract.Passed,
            materialFilterContract.Details));
        var materialFilterPersistenceContract =
            WorkflowPreferencesService.RunMaterialFilterPersistenceContractVerification();
        checks.Add(new VerificationCheck(
            "v54 Materials filter persistence compatibility",
            materialFilterPersistenceContract.Passed,
            materialFilterPersistenceContract.Details));
        var visibleScopeSnapshot = CaptureCanonicalVisibleMaterialScope();
        var repeatedVisibleScopeSnapshot = CaptureCanonicalVisibleMaterialScope();
        var visibleScopeSnapshotReady =
            visibleScopeSnapshot.Count == canonicalVisibleIds.Count &&
            visibleScopeSnapshot.MaterialIds
                .SequenceEqual(canonicalVisibleIds, StringComparer.OrdinalIgnoreCase) &&
            visibleScopeSnapshot.ScopeHash.Length == 64 &&
            string.Equals(
                visibleScopeSnapshot.ScopeHash,
                repeatedVisibleScopeSnapshot.ScopeHash,
                StringComparison.Ordinal);
        checks.Add(new VerificationCheck(
            "v54 canonical visible MaterialID snapshot parity",
            visibleScopeSnapshotReady,
            visibleScopeSnapshotReady
                ? $"{visibleScopeSnapshot.Count} exact visible MaterialID(s), stable SHA-256 {visibleScopeSnapshot.ScopeHash[..12]}"
                : "Visible rows, ordered unique IDs or deterministic scope hash diverged"));
        var materialMultiSelectUiReady =
            AutomationProperties.GetAutomationId(
                NativeMaterialManufacturerMultiFilter) ==
            "NativeMaterialManufacturerMultiFilter" &&
            AutomationProperties.GetAutomationId(
                NativeMaterialBaseMaterialMultiFilter) ==
            "NativeMaterialBaseMaterialMultiFilter" &&
            AutomationProperties.GetAutomationId(
                NativeMaterialVariantFinishMultiFilter) ==
            "NativeMaterialVariantFinishMultiFilter" &&
            AutomationProperties.GetAutomationId(
                NativeMaterialReinforcementMultiFilter) ==
            "NativeMaterialReinforcementMultiFilter" &&
            AutomationProperties.GetAutomationId(
                NativeMaterialColorMultiFilter) ==
            "NativeMaterialColorMultiFilter" &&
            AutomationProperties.GetAutomationId(
                NativeMaterialProductLineMultiFilter) ==
            "NativeMaterialProductLineMultiFilter" &&
            AutomationProperties.GetAutomationId(
                NativeMaterialSearchBox) == "NativeMaterialSearch";
        checks.Add(new VerificationCheck(
            "v54 Materials multi-select stable control contract",
            materialMultiSelectUiReady,
            materialMultiSelectUiReady
                ? "Six no-modifier facet surfaces and Materials search expose stable AutomationIds"
                : "A v54 facet surface or Materials search lacks its stable AutomationId"));
        var websiteCandidateIds = GetNativeWebsiteExportCandidateRows()
            .Select(row => row.MaterialID?.Trim() ?? string.Empty)
            .Where(materialId => !string.IsNullOrWhiteSpace(materialId))
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        var filteredWebsiteProbeRows = canonicalVisibleRows.Take(1).ToList();
        var resolvedWebsiteIds = GetNativeWebsitePipelineRows(filteredWebsiteProbeRows)
            .Select(row => row.MaterialID?.Trim() ?? string.Empty)
            .Where(materialId => !string.IsNullOrWhiteSpace(materialId))
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        var publicPublicationIds = _nativeMaterialRows
            .Where(row =>
                !row.IsArchived &&
                row.PublishPublicReports &&
                !string.IsNullOrWhiteSpace(row.MaterialID))
            .Select(row => row.MaterialID.Trim())
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        var materialScopeIsolationReady =
            resolvedWebsiteIds.SetEquals(websiteCandidateIds) &&
            publicPublicationIds.IsSubsetOf(canonicalActiveIds);
        checks.Add(new VerificationCheck(
            "v54 website and public publication scope isolation",
