    private WebsiteReleaseReadinessResult EvaluateWebsiteReleaseReadiness()
    {
        try
        {
            var generatedAt = new DateTime(2026, 7, 20, 12, 0, 0, DateTimeKind.Local);
            var rows = BuildNativeMaterialDataRows(includeArchived: false);
            var previewHtml = BuildWebsitePreviewHtml(rows, rows, generatedAt, null, isProduction: false);
            var productionHtml = BuildWebsitePreviewHtml(rows, rows, generatedAt, null, isProduction: true);
            var previewRedirect = BuildManufacturerRedirectHtml(isProduction: false);
            var productionRedirect = BuildManufacturerRedirectHtml(isProduction: true);
            var exportRows = GetNativeWebsiteExportCandidateRows();
            var auditRoot = System.IO.Path.Combine("C:\\", "v40-release-audit");
            var previewReportStage = new PublicReportWebsiteStageResult(System.IO.Path.Combine(auditRoot, PublicReportWebsiteIntegrationService.PreviewPortalRoute), 1, 6, 24);
            var productionReportStage = new PublicReportWebsiteStageResult(System.IO.Path.Combine(auditRoot, PublicReportWebsiteIntegrationService.ProductionPortalRoute), 1, 6, 24);
            var previewManifest = BuildWebsiteExportManifest(
                exportRows,
                rows.Count,
                System.IO.Path.Combine(auditRoot, "index-test.html"),
                System.IO.Path.Combine(auditRoot, "manufacturers", "index-test.html"),
                generatedAt,
                "Active SQLite template",
                isProduction: false,
                string.Empty,
                string.Empty,
                previewReportStage);
            var productionManifest = BuildWebsiteExportManifest(
                exportRows,
                rows.Count,
                System.IO.Path.Combine(auditRoot, "index.html"),
                System.IO.Path.Combine(auditRoot, "manufacturers", "index.html"),
                generatedAt,
                "Active SQLite template",
                isProduction: true,
                System.IO.Path.Combine(auditRoot, "backups", "index.html"),
                System.IO.Path.Combine(auditRoot, "backups", "manufacturers-index.html"),
                productionReportStage);

            return _websiteVerificationService.VerifyReleaseContract(
                previewHtml,
                productionHtml,
                previewRedirect,
                productionRedirect,
                previewManifest,
                productionManifest,
                DocumentationEngineService.WhitepaperFileName,
                BuildInfo.ShortLabel + " - " + BuildInfo.ReleaseTitle);
        }
        catch (Exception ex)
        {
            return new WebsiteReleaseReadinessResult { ErrorMessage = ex.Message };
        }
    }

    private string GetVerificationOverallText()
    {
        var profile = BuildVerificationProfile();
        return $"{profile.ProfileName}: {(profile.Passed ? "PASS" : "FAIL")} " +
               $"({profile.PassedCount}/{profile.ApplicableCount} applicable; {profile.NotApplicableCount} N/A)";
    }

    private Brush GetVerificationOverallBrush()
    {
        return BuildVerificationProfile().Passed ? Brushes.ForestGreen : Brushes.DarkRed;
    }

    private string GetWebsiteVerificationVisibilityText()
    {
        var websitePipeline = EvaluateNativeWebsitePipelineVerification();
        if (!websitePipeline.Available)
        {
            return "Website gates: unavailable";
        }

        var payloadPassed = websitePipeline.TensileRows == websitePipeline.CandidateMaterials &&
                            websitePipeline.ImpactRows == websitePipeline.CandidateMaterials &&
                            websitePipeline.StiffnessRows == websitePipeline.CandidateMaterials;

        var radarPassed = websitePipeline.Radar.Passed;

        var rendererPassed = websitePipeline.HtmlRenderer.Passed;

        var verificationPassed = websitePipeline.Website.Passed && websitePipeline.Website.PublishReady;

        return websitePipeline.Passed && payloadPassed && radarPassed && rendererPassed && verificationPassed
            ? "Website gates: Pipeline PASS | Chart PASS | Radar PASS | Renderer PASS | Verification PASS | Publish READY"
            : "Website gates: FAIL - see Website Platform Verification";
    }

    private Brush GetWebsiteVerificationVisibilityBrush()
    {
        var websitePipeline = EvaluateNativeWebsitePipelineVerification();
        var payloadPassed = websitePipeline.Available &&
                            websitePipeline.TensileRows == websitePipeline.CandidateMaterials &&
                            websitePipeline.ImpactRows == websitePipeline.CandidateMaterials &&
                            websitePipeline.StiffnessRows == websitePipeline.CandidateMaterials;

        return websitePipeline.Available && websitePipeline.Passed && payloadPassed && websitePipeline.Radar.Passed && websitePipeline.HtmlRenderer.Passed && websitePipeline.Website.PublishReady ? Brushes.ForestGreen : Brushes.DarkRed;
    }

    private NativeWebsitePipelineVerificationResult EvaluateNativeWebsitePipelineVerification()
    {
        var verification = new NativeWebsitePipelineVerificationResult();

        try
        {
            var materialSummary = EvaluateNativeMaterialSummaryVerification();
            if (!materialSummary.Available || !materialSummary.Passed)
            {
                verification.Available = false;
                verification.Passed = false;
                verification.ErrorMessage = "Material Summary Engine verification has not passed";
                return verification;
            }

            var candidates = GetNativeWebsiteExportCandidateRows();
            var summaries = BuildVerifiedMaterialSummaryMap(candidates);
            var chartInputs = candidates
                .Select(material => new
                {
                    Material = material,
                    MaterialId = material.MaterialID?.Trim() ?? string.Empty
                })
                .Where(item => !string.IsNullOrWhiteSpace(item.MaterialId) && summaries.ContainsKey(item.MaterialId))
                .Select(item => new WebsiteChartMaterialInput(BuildWebsiteTemplateCommonFields(item.Material), summaries[item.MaterialId]))
                .ToList();

            var payload = _websiteChartGeneratorService.BuildPayload(chartInputs);
            var dataJson = _websiteChartGeneratorService.BuildDataJson(chartInputs);
            string? templateHtml = null;
            try
            {
                templateHtml = LoadWebsiteExportTemplate(null);
            }
            catch
            {
                templateHtml = null;
            }

            verification.CandidateMaterials = candidates.Count;
            verification.SummariesBuilt = summaries.Count;
            verification.TensileRows = payload.Tensile.Count;
            verification.ImpactRows = payload.Impact.Count;
            verification.StiffnessRows = payload.Stiffness.Count;
            verification.Radar = _websiteRadarGeneratorService.VerifyRadarPayload(payload);
            verification.HtmlRenderer = _websiteHtmlRendererService.VerifyMainWebsitePayload(payload);
            verification.Website = _websiteVerificationService.Verify(payload, verification.Radar, verification.HtmlRenderer, templateHtml, dataJson);
            verification.Available = true;
            verification.Passed = candidates.Count > 0 && summaries.Count == candidates.Count && payload.Tensile.Count == candidates.Count && payload.Impact.Count == candidates.Count && payload.Stiffness.Count == candidates.Count && verification.Radar.Passed && verification.HtmlRenderer.Passed && verification.Website.Passed;
        }
        catch (Exception ex)
        {
            verification.Available = false;
            verification.Passed = false;
            verification.ErrorMessage = ex.Message;
        }

        return verification;
    }

    private NativeReportingPipelineVerificationResult EvaluateNativeReportingDataPipelineVerification()
    {
        var verification = new NativeReportingPipelineVerificationResult();

        try
        {
            var materialSummary = EvaluateNativeMaterialSummaryVerification();
            if (!materialSummary.Available || !materialSummary.Passed)
            {
                verification.Available = false;
                verification.Passed = false;
                verification.ErrorMessage = "Material Summary Engine verification has not passed";
                return verification;
            }

            var candidates = GetNativeWebsiteExportCandidateRows();
            var summaries = BuildVerifiedMaterialSummaryMap(candidates);
            var reportInputs = candidates
                .Select(material => new
                {
                    Material = material,
                    MaterialId = material.MaterialID?.Trim() ?? string.Empty
                })
                .Where(item => !string.IsNullOrWhiteSpace(item.MaterialId) && summaries.ContainsKey(item.MaterialId))
                .Select(item => new ReportingMaterialInput(
                    item.MaterialId,
                    BuildWebsiteTemplateCommonFields(item.Material),
                    summaries[item.MaterialId]))
                .ToList();

            var payload = _reportingDataPipelineService.BuildPayload(reportInputs);
            var pipeline = _reportingDataPipelineService.Verify(reportInputs);
            var generator = _reportGeneratorService.Verify(payload);
            var reportModel = _reportGeneratorService.BuildReport(payload);
            var pdfRenderer = _reportPdfRendererService.Verify(reportModel);
            var pdfDocument = _reportPdfRendererService.Render(reportModel);
            var certificateGenerator = _reportCertificateGeneratorService.Verify(reportModel, pdfDocument);
            var templates = _reportTemplateService.Verify(reportModel);
            var exportUi = _reportExportUiService.Verify(templates);
            var materialEngineeringReport = _materialEngineeringReportService.Verify(reportModel);
            var unifiedRendering = _unifiedReportRenderingService.Verify(templates, exportUi, pdfRenderer, templates.TemplateOutputs > 0, pdfRenderer.HasLogoAsset);
            var assetPipeline = _reportAssetPipelineService.Verify(unifiedRendering.UsesCanonicalHtmlLayout, unifiedRendering.PdfExportPreserved);

            verification.CandidateMaterials = candidates.Count;
            verification.SummariesConsumed = summaries.Count;
            verification.ReportRows = pipeline.ReportRows;
            verification.CompleteRows = pipeline.CompleteRows;
            verification.PartialRows = pipeline.PartialRows;
            verification.MaterialIdCoverage = pipeline.MaterialIdCoverage;
            verification.UsesVerifiedMaterialSummary = pipeline.UsesVerifiedMaterialSummary;
            verification.Pipeline = pipeline;
            verification.Generator = generator;
            verification.PdfRenderer = pdfRenderer;
            verification.CertificateGenerator = certificateGenerator;
            verification.Templates = templates;
            verification.ExportUi = exportUi;
            verification.MaterialEngineeringReport = materialEngineeringReport;
            verification.UnifiedRendering = unifiedRendering;
            verification.AssetPipeline = assetPipeline;
            verification.PdfPages = pdfRenderer.PageCount;
            verification.PdfBytes = pdfRenderer.ByteCount;
            verification.PdfPayloadValidationPassed = pdfRenderer.PayloadValidationPassed;
            verification.PdfRenderReady = pdfRenderer.RenderReady;
            verification.CertificatesGenerated = certificateGenerator.GeneratedCertificates;
            verification.CertificatePayloadValidationPassed = certificateGenerator.PayloadValidationPassed;
            verification.CertificateReady = certificateGenerator.CertificateReady;
            verification.ReportTemplatesAvailable = templates.TemplateDefinitions;
            verification.ReportTemplateOutputs = templates.TemplateOutputs;
            verification.ReportTemplatePayloadValidationPassed = templates.PayloadValidationPassed;
            verification.ReportTemplateRenderReady = templates.TemplateRenderReady;
            verification.ReportExportUiPayloadValidationPassed = exportUi.PayloadValidationPassed;
            verification.ReportExportUiPreviewReady = exportUi.PreviewWorkflowReady;
            verification.ReportExportUiPdfReady = exportUi.PdfExportWorkflowReady;
            verification.MaterialEngineeringReportsGenerated = materialEngineeringReport.GeneratedEngineeringReports;
            verification.MaterialEngineeringReportPayloadValidationPassed = materialEngineeringReport.PayloadValidationPassed;
            verification.MaterialEngineeringReportRenderReady = materialEngineeringReport.RenderReady;
            verification.BrandedPdfLayoutPassed = pdfRenderer.HasBrandedLayout;
            verification.PdfLogoAssetAvailable = pdfRenderer.HasLogoAsset;
            verification.AppIconAssetAvailable = IsApplicationIconAssetAvailable();
            verification.UnifiedReportRendererPassed = unifiedRendering.Passed &&
                                  assetPipeline.Passed;
            verification.CanonicalHtmlLayoutPassed = unifiedRendering.UsesCanonicalHtmlLayout;
            verification.SharedReportAssetsPassed = unifiedRendering.UsesSharedAssets;
            verification.HtmlToPdfPackageReady = unifiedRendering.PdfExportPreserved && unifiedRendering.HtmlPreviewGenerated;
            verification.ReportAssetPipelinePassed = assetPipeline.Passed;
            verification.ReportAssetsAvailable = assetPipeline.AssetsAvailable;
            verification.SharedReportAssets = assetPipeline.SharedReportAssets;
            verification.ReportAssetManifestReady = assetPipeline.PackageManifestReady;
            verification.ReportChartRendererPassed = templates.TemplateOutputs > 0 && materialEngineeringReport.MetricSections > 0;
            verification.ReportChartPayloads = materialEngineeringReport.MetricSections;
            verification.ReportChartAssetsValidated = assetPipeline.Passed && unifiedRendering.UsesCanonicalHtmlLayout;
            verification.InteractiveReportReady = verification.ReportChartRendererPassed && verification.ReportChartAssetsValidated && IsHtmlPrintEngineAvailable();
            verification.Available = true;
            verification.Passed = candidates.Count > 0 &&
                                  summaries.Count == candidates.Count &&
                                  pipeline.Passed &&
                                  pipeline.ReportRows == candidates.Count &&
                                  generator.Passed &&
                                  generator.GeneratedReports == candidates.Count &&
                                  pdfRenderer.Passed &&
                                  pdfRenderer.RenderedReports == candidates.Count &&
                                  certificateGenerator.Passed &&
                                  certificateGenerator.GeneratedCertificates == candidates.Count &&
                                  templates.Passed &&
                                  exportUi.Passed &&
                                  materialEngineeringReport.Passed &&
                                  verification.BrandedPdfLayoutPassed &&
                                  verification.PdfLogoAssetAvailable &&
                                  verification.AppIconAssetAvailable &&
                                  unifiedRendering.Passed &&
                                  assetPipeline.Passed &&
                                  verification.InteractiveReportReady;
        }
        catch (Exception ex)
        {
            verification.Available = false;
            verification.Passed = false;
            verification.ErrorMessage = ex.Message;
        }

        return verification;
    }

    private NativeTensileVerificationResult EvaluateNativeTensileVerification()
    {
        var verification = new NativeTensileVerificationResult();

        try
        {
            var area = GetNativeTensileCrossSectionArea();
            verification.CrossSectionArea = area;
            verification.Available = true;

            foreach (var row in _nativeTensileRows)
            {
                var hasSamples = row.SampleValues(true).Concat(row.SampleValues(false)).Any(value => !string.IsNullOrWhiteSpace(value));
                if (!hasSamples) continue;

                verification.RowsWithSamples++;
                var results = _resultsService.CalculateTensile(row.SampleValues(true), row.SampleValues(false), area);

                var expectedUprightAverage = FormatNativeResult(results.Upright.Average);
                var expectedFlatAverage = FormatNativeResult(results.Flat.Average);
                var expectedUprightStdDev = FormatNativeResult(results.Upright.StandardDeviation);
                var expectedFlatStdDev = FormatNativeResult(results.Flat.StandardDeviation);
                var expectedUprightCv = FormatNativeResult(results.Upright.CoefficientOfVariation);
                var expectedFlatCv = FormatNativeResult(results.Flat.CoefficientOfVariation);
                var expectedUprightSamples = results.Upright.SampleCount == 0 ? "" : results.Upright.SampleCount.ToString(CultureInfo.CurrentCulture);
                var expectedFlatSamples = results.Flat.SampleCount == 0 ? "" : results.Flat.SampleCount.ToString(CultureInfo.CurrentCulture);
                var expectedUprightConfidence = results.Upright.Confidence.HasValue ? results.Upright.Confidence.Value.ToString(CultureInfo.CurrentCulture) : "";
                var expectedFlatConfidence = results.Flat.Confidence.HasValue ? results.Flat.Confidence.Value.ToString(CultureInfo.CurrentCulture) : "";

                var matches =
                    SameText(row.MpaUpright, expectedUprightAverage) &&
                    SameText(row.MpaFlat, expectedFlatAverage) &&
                    SameText(row.StdDevUpright, expectedUprightStdDev) &&
                    SameText(row.StdDevFlat, expectedFlatStdDev) &&
                    SameText(row.CvUpright, expectedUprightCv) &&
                    SameText(row.CvFlat, expectedFlatCv) &&
                    SameText(row.SamplesUpright, expectedUprightSamples) &&
                    SameText(row.SamplesFlat, expectedFlatSamples) &&
                    SameText(row.ConfidenceUpright, expectedUprightConfidence) &&
                    SameText(row.ConfidenceFlat, expectedFlatConfidence);

                if (!matches && verification.MismatchedMaterialIds.Count < 10)
                {
                    verification.MismatchedMaterialIds.Add(string.IsNullOrWhiteSpace(row.MaterialID) ? "(missing MaterialID)" : row.MaterialID);
                }
            }

            verification.Passed = verification.MismatchedMaterialIds.Count == 0;
        }
        catch (Exception ex)
        {
            verification.Available = false;
            verification.Passed = false;
            verification.ErrorMessage = ex.Message;
        }

        return verification;
    }

