    private static bool IsHtmlPrintEngineAvailable()
    {
        return typeof(Microsoft.Web.WebView2.Wpf.WebView2) is not null;
    }

    private static bool IsApplicationIconAssetAvailable()
    {
        var candidatePaths = new[]
        {
            System.IO.Path.Combine(AppContext.BaseDirectory, "Assets", "3dp-iceland-labs-icon.ico"),
            System.IO.Path.Combine(AppContext.BaseDirectory, "3dp-iceland-labs-icon.ico"),
            System.IO.Path.Combine(Directory.GetCurrentDirectory(), "Assets", "3dp-iceland-labs-icon.ico")
        };

        return candidatePaths.Any(path => File.Exists(path) && new FileInfo(path).Length > 20000);
    }

