    private static string GetApplicationBuildDateText()
    {
        try
        {
            var location = Environment.ProcessPath;
            if (!string.IsNullOrWhiteSpace(location) && File.Exists(location))
            {
                return File.GetLastWriteTime(location).ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture);
            }
        }
        catch
        {
            // Best effort only.
        }

        return "Unknown";
    }

    private static string GetFileSizeText(string path)
    {
        try
        {
            if (!File.Exists(path)) return "Not found";
            var length = new FileInfo(path).Length;
            if (length >= 1024 * 1024) return (length / 1024d / 1024d).ToString("0.00 MB", CultureInfo.InvariantCulture);
            if (length >= 1024) return (length / 1024d).ToString("0.0 KB", CultureInfo.InvariantCulture);
            return length.ToString(CultureInfo.InvariantCulture) + " bytes";
        }
        catch
        {
            return "Unavailable";
        }
    }

    private void OpenBackupFolderFromDiagnostics()
    {
        try
        {
            Directory.CreateDirectory(_database.BackupFolder);
            UrlLauncher.Open(_database.BackupFolder);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Could not open backup folder", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

    private void ExportDiagnosticsReport(string reportText, bool isVerificationReport)
    {
        try
        {
            var reportName = isVerificationReport ? "Verification" : "System_Diagnostics";
            var reportTitle = isVerificationReport ? "Verification Center" : "System Diagnostics";
            var dialog = new SaveFileDialog
            {
                Title = $"Export {reportTitle} Report",
                Filter = "Text file (*.txt)|*.txt",
                FileName = $"3DPIceland_FilamentDB_{reportName}_{DateTime.Now.ToString("yyyyMMdd_HHmmss", CultureInfo.InvariantCulture)}.txt"
            };

            if (dialog.ShowDialog(this) != true) return;
            SafeFileOperations.WriteAllTextAtomic(dialog.FileName, reportText, Encoding.UTF8);
            MessageBox.Show(this, $"{reportTitle} report exported.", reportTitle, MessageBoxButton.OK, MessageBoxImage.Information);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Could not export diagnostics report", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

    private void ExportEngineeringWhitepaper_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            var dialog = new SaveFileDialog
            {
                Title = "Export Engineering Methodology Whitepaper",
                FileName = DocumentationEngineService.WhitepaperFileName,
                Filter = "PDF files (*.pdf)|*.pdf"
            };
            if (dialog.ShowDialog(this) != true) return;
            var engine = new DocumentationEngineService();
            SafeFileOperations.WriteAllBytesAtomic(dialog.FileName, engine.RenderPdf(engine.BuildDocument(DateTime.Now)));
            StatusText.Text = "Engineering whitepaper exported";
            MessageBox.Show(this, $"Whitepaper exported successfully.\n\n{dialog.FileName}", "Documentation Engine", MessageBoxButton.OK, MessageBoxImage.Information);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Whitepaper Export Failed", MessageBoxButton.OK, MessageBoxImage.Error);
        }
    }

