    private void ShowHelpDocument(string fileName, string title)
    {
        try
        {
            var text = LoadHelpDocumentText(fileName);
            var window = new Window
            {
                Title = title,
                Owner = this,
                Width = 1040,
                Height = 760,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Background = Brushes.White
            };

            var root = new DockPanel();

            var toolbar = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Margin = new Thickness(10),
                VerticalAlignment = VerticalAlignment.Center
            };

            var searchBox = new TextBox
            {
                Width = 260,
                Margin = new Thickness(0, 0, 8, 0),
                ToolTip = "Search inside this document"
            };

            var findNextButton = new Button
            {
                Content = "Find Next",
                Padding = new Thickness(10, 4, 10, 4),
                Margin = new Thickness(0, 0, 12, 0),
                ToolTip = "Find the next matching text in the open help document"
            };

            var versionBox = new TextBox
            {
                Width = 120,
                Margin = new Thickness(0, 0, 8, 0),
                ToolTip = "Jump to a version, for example v27.5 or v20"
            };

            var jumpButton = new Button
            {
                Content = "Jump to Version",
                Padding = new Thickness(10, 4, 10, 4),
                ToolTip = "Jump to the first matching version heading"
            };

            toolbar.Children.Add(new TextBlock
            {
                Text = "Search:",
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 0, 6, 0)
            });
            toolbar.Children.Add(searchBox);
            toolbar.Children.Add(findNextButton);
            toolbar.Children.Add(new TextBlock
            {
                Text = "Version:",
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 0, 6, 0)
            });
            toolbar.Children.Add(versionBox);
            toolbar.Children.Add(jumpButton);

            DockPanel.SetDock(toolbar, Dock.Top);
            root.Children.Add(toolbar);

            var textBox = new TextBox
            {
                Text = text,
                IsReadOnly = true,
                TextWrapping = TextWrapping.Wrap,
                VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                HorizontalScrollBarVisibility = ScrollBarVisibility.Auto,
                FontFamily = new FontFamily("Consolas"),
                FontSize = 13,
                Padding = new Thickness(16),
                BorderThickness = new Thickness(0),
                Background = Brushes.White
            };

            void FindText(string query)
            {
                if (string.IsNullOrWhiteSpace(query))
                {
                    return;
                }

                var start = textBox.SelectionStart + Math.Max(1, textBox.SelectionLength);
                var index = textBox.Text.IndexOf(query, start, StringComparison.OrdinalIgnoreCase);
                if (index < 0)
                {
                    index = textBox.Text.IndexOf(query, 0, StringComparison.OrdinalIgnoreCase);
                }

                if (index >= 0)
                {
                    textBox.Focus();
                    textBox.Select(index, query.Length);
                    textBox.ScrollToLine(textBox.Text[..index].Count(c => c == '\n'));
                }
            }

            findNextButton.Click += (_, _) => FindText(searchBox.Text);
            searchBox.KeyDown += (_, args) =>
            {
                if (args.Key == Key.Enter)
                {
                    FindText(searchBox.Text);
                    args.Handled = true;
                }
            };

            jumpButton.Click += (_, _) => FindText(versionBox.Text);
            versionBox.KeyDown += (_, args) =>
            {
                if (args.Key == Key.Enter)
                {
                    FindText(versionBox.Text);
                    args.Handled = true;
                }
            };

            root.Children.Add(textBox);
            window.Content = root;
            window.ShowDialog();
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Could not open help document", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

    private static string LoadHelpDocumentText(string fileName)
    {
        foreach (var path in GetHelpDocumentSearchPaths(fileName))
        {
            if (File.Exists(path))
            {
                return File.ReadAllText(path);
            }
        }

        return $"The help document '{fileName}' could not be found.\n\n" +
               "Expected location: docs folder next to the application or project root.";
    }

    private static IEnumerable<string> GetHelpDocumentSearchPaths(string fileName)
    {
        var baseDir = AppContext.BaseDirectory;
        yield return System.IO.Path.Combine(baseDir, "docs", fileName);

        var current = new DirectoryInfo(baseDir);
        for (var i = 0; i < 6 && current != null; i++, current = current.Parent)
        {
            yield return System.IO.Path.Combine(current.FullName, "docs", fileName);
            yield return System.IO.Path.Combine(current.FullName, fileName);
        }

        yield return System.IO.Path.Combine(Environment.CurrentDirectory, "docs", fileName);
    }

