    private void UpdateCountText()
    {
        var total = _nativeMaterialRows.Count;
        var active = _nativeMaterialRows.Count(row => !row.IsArchived);
        var archived = Math.Max(0, total - active);

        var visible = GetVisibleNativeMaterialIdsFromCurrentFilters().Count;
        var filtersActive = visible != total;

        if (FindName("NativeMaterialCountText") is TextBlock nativeCountText)
        {
            nativeCountText.Text = filtersActive
                ? $"{visible} visible | {total} total materials"
                : archived > 0
                    ? $"{active} active | {archived} archived | {total} total"
                    : $"{total} materials";
        }

        HeaderSummaryText.Text = total == 0
            ? "No data loaded"
            : archived > 0
                ? $"{active} active | {archived} archived"
                : $"{total} materials";
    }

    private void RefreshApplicationStatistics()
    {
        UpdateCountText();
        FooterText.Text = $"SQLite database: {_database.DatabasePath}";

        if (_nativeMaterialRows.Count > 0)
        {
            var active = _nativeMaterialRows.Count(row => !row.IsArchived);
            var archived = _nativeMaterialRows.Count - active;
            StatusText.Text = $"SQLite live data: {_nativeMaterialRows.Count} materials ({active} active, {archived} archived).";
        }

        UpdateNativeWorkflowStatus(_nativeMaterialDirty ? "Unsaved material edit pending" : "Auto-save ready");
        UpdateDashboardInsights();
    }

