    private void UpdateYouTubeResearch()
    {
        try
        {
            if (YouTubeResearchTitleList is null) return;

            var rows = BuildCanonicalVisiblePlannerRows();
            if (rows.Count == 0)
            {
                YouTubeResearchTitleList.ItemsSource = null;
                if (ComparisonDiscoveryList != null) ComparisonDiscoveryList.ItemsSource = null;
                if (ContentCalendarList != null) ContentCalendarList.ItemsSource = null;
                if (ChannelGapList != null) ChannelGapList.ItemsSource = null;
                if (PlaylistDiscoveryList != null) PlaylistDiscoveryList.ItemsSource = null;
                UpdateTopThumbnailRecommendation(null);
                UpdateTopComparisonDiscovery(null);
                UpdateTopContentCalendar(null);
                UpdateTopChannelGap(null);
                UpdateTopPlaylistDiscovery(null);
                if (YouTubeResearchStatusText != null) YouTubeResearchStatusText.Text = "Import data to generate title ideas.";
                return;
            }

            ApplyDataAwareVideoSuggestions(rows);
            ApplyVideoTitleSuggestions(rows);
            ApplyAdvancedTitleEngine(rows);
            ApplyThumbnailResearchEngine(rows);

            var candidates = rows
                .Where(row => row.HasMechanical)
                .OrderByDescending(row => row.ThumbnailScore)
                .ThenByDescending(row => row.Priority)
                .ThenBy(row => row.Label, StringComparer.CurrentCultureIgnoreCase)
                .Take(50)
                .ToList();

            var comparisonCandidates = BuildComparisonDiscoveryRows(rows);
            var contentPlan = BuildContentCalendarRows(candidates, 30);
            var channelGaps = BuildChannelGapRows(rows);
            var playlists = BuildPlaylistDiscoveryRows(rows, candidates, contentPlan, channelGaps);

            YouTubeResearchTitleList.ItemsSource = candidates;
            if (ComparisonDiscoveryList != null) ComparisonDiscoveryList.ItemsSource = comparisonCandidates;
            if (ContentCalendarList != null) ContentCalendarList.ItemsSource = contentPlan;
            if (ChannelGapList != null) ChannelGapList.ItemsSource = channelGaps;
            if (PlaylistDiscoveryList != null) PlaylistDiscoveryList.ItemsSource = playlists;
            UpdateTopThumbnailRecommendation(candidates.FirstOrDefault());
            UpdateTopComparisonDiscovery(comparisonCandidates.FirstOrDefault());
            UpdateTopContentCalendar(contentPlan.FirstOrDefault());
            UpdateTopChannelGap(channelGaps.FirstOrDefault());
            UpdateTopPlaylistDiscovery(playlists.FirstOrDefault());
            if (YouTubeResearchStatusText != null)
            {
                var noVideo = candidates.Count(row => !row.HasVideo);
                YouTubeResearchStatusText.Text = $"Generated {candidates.Count} title + thumbnail candidates, {comparisonCandidates.Count} comparison discoveries, {channelGaps.Count} channel gaps, {contentPlan.Count} calendar slots, and {playlists.Count} playlist discoveries ({noVideo} without video).";
            }
        }
        catch (Exception ex)
        {
            if (YouTubeResearchStatusText != null) YouTubeResearchStatusText.Text = $"YouTube Research failed: {ex.Message}";
        }
    }




