    }

    private static string FormatPlaylistPreview(string label, string value)
    {
        if (string.IsNullOrWhiteSpace(value)) return $"{label}: -";

        var items = value
            .Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries)
            .Select(item => item.Trim())
            .Where(item => item.Length > 0)
            .Take(6)
            .ToList();

        if (items.Count == 0) return $"{label}: {value.Trim()}";
        return $"{label}:\n- " + string.Join("\n- ", items);
    }

    private static List<PlaylistDiscoveryRow> BuildPlaylistDiscoveryRows(
        List<VideoPlannerRow> rows,
        List<VideoPlannerRow> candidates,
        List<ContentCalendarRow> calendarRows,
        List<ChannelGapRow> channelGaps)
    {
        var playlists = new List<PlaylistDiscoveryRow>();
        var usableRows = rows.Where(row => row.HasMechanical).ToList();

        foreach (var group in usableRows.GroupBy(row => CleanPlaylistName(row.Manufacturer)))
        {
            var members = group.OrderByDescending(row => row.ThumbnailScore).ThenByDescending(row => row.Priority).Take(8).ToList();
            if (members.Count >= 3)
            {
                playlists.Add(BuildPlaylistRow(
                    $"{group.Key} Material Tests",
                    "Manufacturer playlist",
                    members,
                    $"Groups {group.Key} videos into one easy playlist for viewers who want that brand."));
            }
        }

        foreach (var group in usableRows.GroupBy(row => NormalizeMaterialFamily(row.BaseMaterial, row.Reinforcement, row.Variant)))
        {
            var members = group.OrderByDescending(row => row.ThumbnailScore).ThenByDescending(row => row.Priority).Take(8).ToList();
            if (members.Count >= 3)
            {
                playlists.Add(BuildPlaylistRow(
                    $"{group.Key} Filament Guide",
                    "Material family playlist",
                    members,
                    $"Groups {group.Key} videos into a focused buyer/research playlist."));
            }
        }

        var reinforced = usableRows
            .Where(row => !string.IsNullOrWhiteSpace(row.Reinforcement) || IsReinforced(row))
            .OrderByDescending(row => row.ThumbnailScore)
            .ThenByDescending(row => row.Priority)
            .Take(8)
            .ToList();
        if (reinforced.Count >= 3)
        {
            playlists.Add(BuildPlaylistRow(
                "Carbon Fiber & Reinforced Filaments",
                "Reinforced materials playlist",
                reinforced,
                "Collects CF/GF/reinforced material videos where viewers compare stiffness, strength, and real print usefulness."));
        }

        var engineering = usableRows
            .Where(row => IsEngineeringFamily(NormalizeMaterialFamily(row.BaseMaterial, row.Reinforcement, row.Variant)))
            .OrderByDescending(row => row.ThumbnailScore)
            .ThenByDescending(row => row.Priority)
            .Take(8)
            .ToList();
        if (engineering.Count >= 3)
        {
            playlists.Add(BuildPlaylistRow(
                "Engineering Filament Tests",
                "Engineering playlist",
                engineering,
                "Collects Nylon, PC, ASA/ABS, and other engineering videos for viewers looking beyond normal PLA/PETG."));
        }

        var gaps = channelGaps
            .Take(8)
            .Select(gap => rows.FirstOrDefault(row => SameText(row.Label, gap.Material)))
            .Where(row => row != null)
            .Cast<VideoPlannerRow>()
            .ToList();
        if (gaps.Count >= 3)
        {
            playlists.Add(BuildPlaylistRow(
                "Untapped High Potential Videos",
                "Channel gap playlist",
                gaps,
                "Builds a playlist from strong no-coverage opportunities discovered in Channel Gap Analysis."));
        }

        return playlists
            .GroupBy(row => row.PlaylistName, StringComparer.CurrentCultureIgnoreCase)
            .Select(group => group.OrderByDescending(row => row.Score).First())
            .OrderByDescending(row => row.Score)
            .ThenBy(row => row.PlaylistName, StringComparer.CurrentCultureIgnoreCase)
            .Take(30)
            .ToList();
    }

    private static PlaylistDiscoveryRow BuildPlaylistRow(string name, string type, List<VideoPlannerRow> members, string baseReason)
    {
        var videos = members.Take(5).Select(row => ShortVideoName(row)).ToList();
        var noVideoCount = members.Count(row => !row.HasVideo);
        var coverageCount = members.Count - noVideoCount;
        var averageScore = members.Count == 0 ? 0 : members.Average(row => Math.Max(row.ThumbnailScore, row.Priority));
        var diversity = members.Select(row => NormalizeMaterialFamily(row.BaseMaterial, row.Reinforcement, row.Variant)).Distinct(StringComparer.CurrentCultureIgnoreCase).Count();
        var score = Math.Clamp((int)Math.Round(averageScore + Math.Min(12, members.Count * 2) + Math.Min(10, noVideoCount * 2) + Math.Min(6, diversity * 2)), 60, 100);
        var missing = members.Where(row => !row.HasVideo).Take(5).Select(row => ShortVideoName(row)).ToList();
        var missingText = missing.Count == 0 ? "No obvious missing videos in this group" : string.Join("; ", missing);
        var completionPercent = members.Count == 0 ? 0 : (int)Math.Round((coverageCount * 100.0) / members.Count);
        var coverage = $"Playlist completion: {completionPercent}% ({coverageCount} of {members.Count} completed, {noVideoCount} gaps)";
        var reason = $"{baseReason} {members.Count} related candidates, {coverageCount} already covered, {noVideoCount} missing or not yet covered, playlist score {score}/100.";

        return new PlaylistDiscoveryRow
        {
            Score = score,
            PlaylistName = name,
            PlaylistType = type,
            Coverage = coverage,
            Videos = string.Join("; ", videos),
            MissingVideos = missingText,
            Reason = reason,
            CopyBlock = $"Playlist: {name}\n" +
                        $"Score: {score}/100\n" +
                        $"Type: {type}\n" +
                        $"Coverage: {coverage}\n" +
                        $"Videos: {string.Join("; ", videos)}\n" +
                        $"Missing / next: {missingText}\n" +
                        $"Why: {reason}"
        };
    }

    private static string CleanPlaylistName(string value)
    {
        if (string.IsNullOrWhiteSpace(value)) return "Unknown Brand";
        return TitleCase(value.Trim());
    }

    private static string ShortVideoName(VideoPlannerRow row)
    {
        if (!string.IsNullOrWhiteSpace(row.SuggestedTitle)) return row.SuggestedTitle.Trim();
        if (!string.IsNullOrWhiteSpace(row.Label)) return row.Label.Trim();
        return "Untitled video";
    }

    private static bool IsReinforced(VideoPlannerRow row)
    {
        var combined = $"{row.Label} {row.Reinforcement} {row.Variant} {row.ProductLine}".ToUpperInvariant();
        return combined.Contains(" CF") || combined.Contains("GF") || combined.Contains("CARBON") || combined.Contains("GLASS") || combined.Contains("FIBER") || combined.Contains("FIBRE");
    }

    private static bool IsEngineeringFamily(string family)
    {
        var value = family.ToUpperInvariant();
        return value.Contains("NYLON") || value.Contains("PA") || value.Contains("PC") || value.Contains("ASA") || value.Contains("ABS") || value.Contains("FLEXIBLE") || value.Contains("SPECIALTY");
    }

    private static List<ChannelGapRow> BuildChannelGapRows(List<VideoPlannerRow> rows)
    {
        return rows
            .Where(row => row.HasMechanical)
            .Select(row =>
            {
                var family = NormalizeMaterialFamily(row.BaseMaterial, row.Reinforcement, row.Variant);
                var score = CalculateChannelGapScore(row, family);
                var gapType = BuildChannelGapType(row);
                var coverage = row.HasVideo ? "Has existing video coverage" : "No dedicated video coverage found";
                var title = string.IsNullOrWhiteSpace(row.SuggestedTitle) ? row.Label : row.SuggestedTitle;
                var reason = BuildChannelGapReason(row, score, family);

                return new ChannelGapRow
                {
                    GapScore = score,
                    GapType = gapType,
                    Material = row.Label,
                    Manufacturer = ShortBrand(row.Manufacturer),
                    MaterialFamily = family,
                    VideoIdea = title,
                    ThumbnailText = row.ThumbnailMainText,
                    Coverage = coverage,
                    Reason = reason,
                    CopyBlock = $"Gap {score}/100 - {row.Label}\n  Type: {gapType}\n  Manufacturer: {ShortBrand(row.Manufacturer)} | Family: {family}\n  Video: {title}\n  Thumbnail: {row.ThumbnailMainText}\n  Coverage: {coverage}\n  Why: {reason}\n"
                };
            })
            .Where(row => row.GapScore >= 45)
            .GroupBy(row => NormalizeComparisonKey(row.Manufacturer, row.Material))
            .Select(group => group.First())
            .OrderByDescending(row => row.GapScore)
            .ThenBy(row => row.Manufacturer, StringComparer.CurrentCultureIgnoreCase)
            .ThenBy(row => row.Material, StringComparer.CurrentCultureIgnoreCase)
            .Take(40)
            .ToList();
    }

    private static int CalculateChannelGapScore(VideoPlannerRow row, string family)
    {
        var score = 40;

        if (!row.HasVideo) score += 28;
        else score -= 20;

        if (row.ThumbnailScore >= 90) score += 14;
        else if (row.ThumbnailScore >= 82) score += 10;
        else if (row.ThumbnailScore >= 74) score += 6;

        if (row.OverallScore.GetValueOrDefault() >= 70) score += 10;
        else if (row.OverallScore.GetValueOrDefault() >= 55) score += 6;

        if (HasReinforcementText(row.Reinforcement)) score += 7;
        if (row.SuggestedTitle.Contains("vs", StringComparison.OrdinalIgnoreCase) ||
            row.SuggestedTitle.Contains("worth", StringComparison.OrdinalIgnoreCase) ||
            row.SuggestedTitle.Contains("best", StringComparison.OrdinalIgnoreCase)) score += 5;

        if (SameText(family, "Flexible") || SameText(family, "Specialty") || SameText(family, "Nylon") || SameText(family, "PC")) score += 6;
        if (row.ImpactScore.GetValueOrDefault() >= 70 || row.StiffnessScore.GetValueOrDefault() >= 70 || row.TensileScore.GetValueOrDefault() >= 70) score += 5;
        if (row.ConsistencyScore.GetValueOrDefault() >= 80) score += 3;

        return Math.Clamp(score, 0, 100);
    }

    private static string BuildChannelGapType(VideoPlannerRow row)
    {
        if (!row.HasVideo && HasReinforcementText(row.Reinforcement)) return "No coverage + reinforced hook";
        if (!row.HasVideo && (row.SuggestedTitle.Contains("vs", StringComparison.OrdinalIgnoreCase) || row.SuggestedTitle.Contains("worth", StringComparison.OrdinalIgnoreCase))) return "No coverage + comparison hook";
        if (!row.HasVideo) return "No video coverage";
        if (row.OverallScore.GetValueOrDefault() >= 70) return "High performer underused";
        return "Weak coverage opportunity";
    }

    private static string BuildChannelGapReason(VideoPlannerRow row, int score, string family)
    {
        var parts = new List<string>();
        if (!row.HasVideo) parts.Add("no dedicated video coverage");
        if (row.ThumbnailScore >= 84) parts.Add($"strong thumbnail grade {row.ThumbnailGrade}");
        if (HasReinforcementText(row.Reinforcement)) parts.Add("reinforced-material curiosity angle");
        if (row.OverallScore.GetValueOrDefault() >= 55) parts.Add($"solid overall score {row.OverallScore.GetValueOrDefault():0.#}");
        if (row.ImpactScore.GetValueOrDefault() >= 70) parts.Add("high impact result");
        if (row.StiffnessScore.GetValueOrDefault() >= 70) parts.Add("high stiffness result");
        if (row.TensileScore.GetValueOrDefault() >= 70) parts.Add("high tensile result");
        if (SameText(family, "Flexible") || SameText(family, "Specialty")) parts.Add("distinct material-family story");

        if (parts.Count == 0) parts.Add("potential content gap");
        return $"{string.Join(", ", parts)}. Gap score {score}/100.";
    }


    private static List<ContentCalendarRow> BuildContentCalendarRows(List<VideoPlannerRow> candidates, int maxWeeks)
    {
        var remaining = candidates
            .Where(row => row.HasMechanical)
            .GroupBy(row => NormalizeComparisonKey(row.Manufacturer, row.SuggestedTitle))
            .Select(group => group.First())
            .ToList();

        var plan = new List<ContentCalendarRow>();
        var recentManufacturers = new Queue<string>();
        var recentFamilies = new Queue<string>();

        for (var week = 1; week <= maxWeeks && remaining.Count > 0; week++)
        {
            var best = remaining
                .Select(row => new { Row = row, Score = CalculateCalendarPriority(row, recentManufacturers, recentFamilies) })
                .OrderByDescending(item => item.Score)
                .ThenByDescending(item => item.Row.ThumbnailScore)
                .ThenBy(item => item.Row.Manufacturer, StringComparer.CurrentCultureIgnoreCase)
                .ThenBy(item => item.Row.Label, StringComparer.CurrentCultureIgnoreCase)
                .First();

            var family = NormalizeMaterialFamily(best.Row.BaseMaterial, best.Row.Reinforcement, best.Row.Variant);
            var reason = BuildCalendarReason(best.Row, recentManufacturers, recentFamilies, best.Score, family);
            var title = string.IsNullOrWhiteSpace(best.Row.SuggestedTitle) ? best.Row.Label : best.Row.SuggestedTitle;

            plan.Add(new ContentCalendarRow
            {
                Week = week,
                PublishPriority = best.Score,
                VideoTitle = title,
                Manufacturer = ShortBrand(best.Row.Manufacturer),
                MaterialFamily = family,
                ThumbnailText = best.Row.ThumbnailMainText,
                Reason = reason,
                CopyBlock = $"Week {week} - {title}\n  Priority: {best.Score}/100\n  Manufacturer: {ShortBrand(best.Row.Manufacturer)} | Family: {family}\n  Thumbnail: {best.Row.ThumbnailMainText}\n  Why: {reason}\n"
            });

            remaining.Remove(best.Row);
            EnqueueRecent(recentManufacturers, ShortBrand(best.Row.Manufacturer), 3);
            EnqueueRecent(recentFamilies, family, 3);
        }

        return plan;
    }

    private static int CalculateCalendarPriority(VideoPlannerRow row, IEnumerable<string> recentManufacturers, IEnumerable<string> recentFamilies)
    {
        var manufacturer = ShortBrand(row.Manufacturer);
        var family = NormalizeMaterialFamily(row.BaseMaterial, row.Reinforcement, row.Variant);
        var recentBrandMatches = recentManufacturers.Count(value => SameText(value, manufacturer));
        var recentFamilyMatches = recentFamilies.Count(value => SameText(value, family));

        var score = row.ThumbnailScore;
        if (!row.HasVideo) score += 8;
        if (HasReinforcementText(row.Reinforcement)) score += 4;
        if (row.SuggestedTitle.Contains("vs", StringComparison.OrdinalIgnoreCase) || row.SuggestedTitle.Contains("worth", StringComparison.OrdinalIgnoreCase)) score += 4;
        if (row.OverallScore.GetValueOrDefault() >= 55) score += 3;

        score -= recentBrandMatches * 18;
        score -= recentFamilyMatches * 12;

        if (recentBrandMatches >= 3) score -= 60;
        if (recentFamilyMatches >= 3) score -= 45;

        return Math.Clamp(score, 0, 100);
    }

    private static string BuildCalendarReason(VideoPlannerRow row, IEnumerable<string> recentManufacturers, IEnumerable<string> recentFamilies, int score, string family)
    {
        var parts = new List<string>();
        if (!row.HasVideo) parts.Add("no current video coverage");
        if (HasReinforcementText(row.Reinforcement)) parts.Add("clear reinforced-material angle");
        if (row.ThumbnailScore >= 84) parts.Add($"strong thumbnail grade {row.ThumbnailGrade}");
        if (row.SuggestedTitle.Contains("vs", StringComparison.OrdinalIgnoreCase) || row.SuggestedTitle.Contains("worth", StringComparison.OrdinalIgnoreCase)) parts.Add("comparison-friendly title");

        var manufacturer = ShortBrand(row.Manufacturer);
        if (!recentManufacturers.Any(value => SameText(value, manufacturer))) parts.Add("keeps manufacturer variety");
        if (!recentFamilies.Any(value => SameText(value, family))) parts.Add("keeps material-family variety");

        if (parts.Count == 0) parts.Add("balanced publishing slot");
        return $"{string.Join(", ", parts)}. Calendar priority {score}/100.";
    }

    private static string NormalizeMaterialFamily(string baseMaterial, string reinforcement, string variant)
    {
        var combined = $"{baseMaterial} {reinforcement} {variant}".ToUpperInvariant();
        if (combined.Contains("PLA")) return "PLA";
        if (combined.Contains("PETG")) return "PETG";
        if (combined.Contains("ASA")) return "ASA";
        if (combined.Contains("ABS")) return "ABS";
        if (combined.Contains("PA") || combined.Contains("NYLON")) return "Nylon";
        if (combined.Contains("PC") || combined.Contains("POLYCARBONATE")) return "PC";
        if (combined.Contains("PEBA") || combined.Contains("TPU") || combined.Contains("TPE")) return "Flexible";
        if (combined.Contains("WOOD") || combined.Contains("SILK") || combined.Contains("HIPS") || combined.Contains("PMMA")) return "Specialty";
        return string.IsNullOrWhiteSpace(baseMaterial) ? "Other" : TitleCase(baseMaterial.Trim());
    }

    private static void EnqueueRecent(Queue<string> queue, string value, int limit)
    {
        if (string.IsNullOrWhiteSpace(value)) value = "Unknown";
        queue.Enqueue(value);
        while (queue.Count > limit) queue.Dequeue();
    }

    private void UpdateTopComparisonDiscovery(ComparisonDiscoveryRow? row)
    {
        if (TopComparisonTitleText is null ||
            TopComparisonScoreText is null ||
            TopComparisonPatternText is null ||
            TopComparisonThumbnailText is null ||
            TopComparisonVideoText is null ||
            TopComparisonMaterialsText is null ||
            TopComparisonReasonText is null) return;

        if (row is null)
        {
            TopComparisonTitleText.Text = "GENERATE RESEARCH TO DISCOVER COMPARISONS";
            TopComparisonScoreText.Text = "Score: -";
            TopComparisonPatternText.Text = "Pattern: -";
            TopComparisonThumbnailText.Text = "Thumbnail: -";
            TopComparisonVideoText.Text = "Video: -";
            TopComparisonMaterialsText.Text = "Materials: -";
            TopComparisonReasonText.Text = "Why: The best comparison will update from the generated candidates.";
            return;
        }

        TopComparisonTitleText.Text = BlankDash(row.VideoAngle).ToUpperInvariant();
        TopComparisonScoreText.Text = $"Score: {row.Score}/100";
        TopComparisonPatternText.Text = $"Pattern: {BlankDash(row.ComparisonType)}";
        TopComparisonThumbnailText.Text = $"Thumbnail: {BlankDash(row.ThumbnailText)}";
        TopComparisonVideoText.Text = $"Video: {BlankDash(row.VideoAngle)}";
        TopComparisonMaterialsText.Text = $"Materials: {BlankDash(row.MaterialA)}  vs  {BlankDash(row.MaterialB)}";
        TopComparisonReasonText.Text = $"Why: {BlankDash(row.Reason)}";
    }

    private static List<ComparisonDiscoveryRow> BuildComparisonDiscoveryRows(List<VideoPlannerRow> rows)
    {
        var mechanical = rows
            .Where(row => row.HasMechanical)
            .Where(row => !string.IsNullOrWhiteSpace(row.BaseMaterial))
            .ToList();

        var discoveries = new List<ComparisonDiscoveryRow>();

        foreach (var reinforced in mechanical.Where(row => HasReinforcementText(row.Reinforcement)))
        {
            var plain = mechanical
                .Where(row => !ReferenceEquals(row, reinforced))
                .Where(row => SameText(row.BaseMaterial, reinforced.BaseMaterial))
                .Where(row => !HasReinforcementText(row.Reinforcement))
                .OrderByDescending(row => SameText(row.Manufacturer, reinforced.Manufacturer) ? 1 : 0)
                .ThenBy(row => Math.Abs(row.OverallScore.GetValueOrDefault() - reinforced.OverallScore.GetValueOrDefault()))
                .FirstOrDefault();

            if (plain is null) continue;

            var scoreGap = BiggestMetricGap(reinforced, plain, out var metricName, out var direction);
            var score = 62 + (SameText(plain.Manufacturer, reinforced.Manufacturer) ? 10 : 0) + (int)Math.Min(18, Math.Abs(scoreGap) / 2.0);
            if (!reinforced.HasVideo || !plain.HasVideo) score += 6;
            if (reinforced.ThumbnailScore >= 84 || plain.ThumbnailScore >= 84) score += 4;
            score = Math.Clamp(score, 0, 100);

            var baseMaterial = reinforced.BaseMaterial.ToUpperInvariant();
            var reinforcement = reinforced.Reinforcement.ToUpperInvariant();
            var angle = $"Is {reinforcement} worth it for {baseMaterial}?";
            var thumb = $"{reinforcement} WORTH IT?";
            var reason = Math.Abs(scoreGap) >= 10
                ? $"Clear {metricName} gap ({direction}) makes this an easy side-by-side story."
                : $"Same base material with and without reinforcement makes a simple comparison video.";

            discoveries.Add(new ComparisonDiscoveryRow
            {
                Score = score,
                ComparisonType = "Reinforced vs plain",
                VideoAngle = angle,
                MaterialA = plain.Label,
                MaterialB = reinforced.Label,
                ThumbnailText = thumb,
                Reason = reason,
                CopyBlock = BuildComparisonCopyBlock(score, "Reinforced vs plain", angle, plain.Label, reinforced.Label, thumb, reason)
            });
        }

        foreach (var group in mechanical.GroupBy(row => NormalizeComparisonKey(row.Manufacturer, row.BaseMaterial)))
        {
            var list = group
                .Where(row => row.OverallScore.HasValue)
                .OrderByDescending(row => row.OverallScore.GetValueOrDefault())
                .ToList();
            if (list.Count < 2) continue;

            var best = list.First();
            var alternate = list.Skip(1).FirstOrDefault(row => !SameText(row.Label, best.Label));
            if (alternate is null) continue;

            var gap = best.OverallScore.GetValueOrDefault() - alternate.OverallScore.GetValueOrDefault();
            if (gap < 6) continue;

            var score = Math.Clamp(60 + (int)Math.Min(22, gap * 2) + (!best.HasVideo || !alternate.HasVideo ? 6 : 0), 0, 100);
            var material = best.BaseMaterial.ToUpperInvariant();
            var brand = ShortBrand(best.Manufacturer);
            var angle = $"Which {brand} {material} is actually best?";
            var thumb = "WHICH WINS?";
            var reason = $"Same brand and base material, but overall score gap is {gap:0.#} points.";

            discoveries.Add(new ComparisonDiscoveryRow
            {
                Score = score,
                ComparisonType = "Same brand showdown",
                VideoAngle = angle,
                MaterialA = alternate.Label,
                MaterialB = best.Label,
                ThumbnailText = thumb,
                Reason = reason,
                CopyBlock = BuildComparisonCopyBlock(score, "Same brand showdown", angle, alternate.Label, best.Label, thumb, reason)
            });
        }

        foreach (var group in mechanical.GroupBy(row => NormalizeComparisonKey(row.BaseMaterial, string.Empty)))
        {
            var list = group
                .Where(row => row.OverallScore.HasValue)
                .OrderByDescending(row => row.OverallScore.GetValueOrDefault())
                .ToList();
            if (list.Count < 3) continue;

            var best = list.First();
            var baseline = list.Skip(Math.Min(2, list.Count - 1)).FirstOrDefault(row => !SameText(row.Manufacturer, best.Manufacturer));
            if (baseline is null) continue;

            var gap = best.OverallScore.GetValueOrDefault() - baseline.OverallScore.GetValueOrDefault();
            if (gap < 8) continue;

            var score = Math.Clamp(58 + (int)Math.Min(24, gap * 1.8) + (!best.HasVideo ? 6 : 0), 0, 100);
            var material = best.BaseMaterial.ToUpperInvariant();
            var angle = $"Best {material} in the database so far?";
            var thumb = $"BEST {material}?";
            var reason = $"Category leaderboard gap of {gap:0.#} points creates a clear best-vs-average video.";

            discoveries.Add(new ComparisonDiscoveryRow
            {
                Score = score,
                ComparisonType = "Category leader",
                VideoAngle = angle,
                MaterialA = baseline.Label,
                MaterialB = best.Label,
                ThumbnailText = thumb,
                Reason = reason,
                CopyBlock = BuildComparisonCopyBlock(score, "Category leader", angle, baseline.Label, best.Label, thumb, reason)
            });
        }

        return discoveries
            .GroupBy(row => $"{row.ComparisonType}|{row.MaterialA}|{row.MaterialB}", StringComparer.CurrentCultureIgnoreCase)
            .Select(group => group.First())
            .OrderByDescending(row => row.Score)
            .ThenBy(row => row.VideoAngle, StringComparer.CurrentCultureIgnoreCase)
            .Take(30)
            .ToList();
    }

    private static string BuildComparisonCopyBlock(int score, string type, string angle, string materialA, string materialB, string thumbnailText, string reason)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"Comparison score: {score}/100");
        sb.AppendLine($"Type: {type}");
        sb.AppendLine($"Video angle: {angle}");
        sb.AppendLine($"Material A: {materialA}");
        sb.AppendLine($"Material B: {materialB}");
        sb.AppendLine($"Thumbnail text: {thumbnailText}");
        sb.AppendLine($"Why: {reason}");
        return sb.ToString().TrimEnd();
    }

    private static double BiggestMetricGap(VideoPlannerRow a, VideoPlannerRow b, out string metricName, out string direction)
    {
        var metrics = new[]
        {
            (Name: "stiffness", A: a.StiffnessScore.GetValueOrDefault(), B: b.StiffnessScore.GetValueOrDefault()),
            (Name: "impact", A: a.ImpactScore.GetValueOrDefault(), B: b.ImpactScore.GetValueOrDefault()),
            (Name: "tensile", A: a.TensileScore.GetValueOrDefault(), B: b.TensileScore.GetValueOrDefault()),
            (Name: "overall", A: a.OverallScore.GetValueOrDefault(), B: b.OverallScore.GetValueOrDefault()),
            (Name: "consistency", A: a.ConsistencyScore.GetValueOrDefault(), B: b.ConsistencyScore.GetValueOrDefault())
        };

        var best = metrics.OrderByDescending(metric => Math.Abs(metric.A - metric.B)).First();
        metricName = best.Name;
        direction = best.A >= best.B ? $"reinforced +{best.A - best.B:0.#}" : $"plain +{best.B - best.A:0.#}";
        return best.A - best.B;
    }

    private static bool HasReinforcementText(string value)
    {
        return !string.IsNullOrWhiteSpace(value) && value.Trim() != "—" && value.Trim() != "-" && value.Trim() != "__none__";
    }

    private static string NormalizeComparisonKey(string a, string b)
    {
        return $"{(a ?? string.Empty).Trim().ToUpperInvariant()}|{(b ?? string.Empty).Trim().ToUpperInvariant()}";
    }

    private void UpdateTopThumbnailRecommendation(VideoPlannerRow? row)
    {
        if (TopThumbnailMainText is null || TopThumbnailPatternText is null || TopThumbnailGradeText is null || TopThumbnailReasonText is null) return;

        if (row is null)
        {
            TopThumbnailMainText.Text = "Generate research to pick a thumbnail";
            TopThumbnailPatternText.Text = "Pattern: -";
            TopThumbnailGradeText.Text = "Grade: -";
            TopThumbnailReasonText.Text = "Why: The best thumbnail recommendation will update from the generated candidates.";
            if (TopThumbnailLayoutText != null) TopThumbnailLayoutText.Text = "Layout: -";
            if (TopThumbnailFaceText != null) TopThumbnailFaceText.Text = "Face / reaction: -";
            return;
        }

        TopThumbnailMainText.Text = BlankDash(row.ThumbnailMainText);
        TopThumbnailPatternText.Text = $"Pattern: {BlankDash(row.ThumbnailPattern)}";
        TopThumbnailGradeText.Text = $"Grade: {BlankDash(row.ThumbnailGrade)} | Score: {row.ThumbnailScore}/100";
        TopThumbnailReasonText.Text = $"Why: {BlankDash(row.ThumbnailRecommendationReason)}";
        if (TopThumbnailLayoutText != null) TopThumbnailLayoutText.Text = $"Layout: {BlankDash(row.ThumbnailVisualLayout)}";
        if (TopThumbnailFaceText != null) TopThumbnailFaceText.Text = $"Face / reaction: {BlankDash(row.ThumbnailFaceDirection)}";
    }

    private static string FormatTitleScore(double? score)
    {
        return score.HasValue ? $"{score.Value:0.#}/100" : "N/A";
    }

    private static void ApplyAdvancedTitleEngine(List<VideoPlannerRow> rows)
    {
        foreach (var row in rows.Where(row => row.HasMechanical))
        {
            var material = string.IsNullOrWhiteSpace(row.BaseMaterial) ? "Filament" : row.BaseMaterial.Trim();
            var brand = ShortBrand(row.Manufacturer);
            var reinforcement = string.IsNullOrWhiteSpace(row.Reinforcement) || row.Reinforcement == "—" || row.Reinforcement == "-"
                ? string.Empty
                : row.Reinforcement.Trim();
            var variant = string.IsNullOrWhiteSpace(row.Variant) ? string.Empty : row.Variant.Trim();

            var titleOptions = new List<string>();

            if (!string.IsNullOrWhiteSpace(reinforcement))
            {
                titleOptions.Add($"Is {reinforcement} Worth It? | {brand} {material}");
                titleOptions.Add($"{material} {reinforcement} Tested: Strength or Stiffness? | {brand}");
            }

            if (row.ImpactScore >= 55) titleOptions.Add($"This {material} Took More Abuse Than Expected | {brand}");
            if (row.StiffnessScore >= 85) titleOptions.Add($"This {material}{(string.IsNullOrWhiteSpace(reinforcement) ? "" : " " + reinforcement)} Is Seriously Stiff | {brand}");
            if (row.TensileScore >= 45) titleOptions.Add($"This {material} Is Stronger Than It Looks | {brand}");
            if (row.ConsistencyScore >= 82) titleOptions.Add($"The Most Repeatable {material} Results So Far | {brand}");
            if (row.LayerAdhesionScore >= 60) titleOptions.Add($"Layer Adhesion Test: This {material} Surprised Me | {brand}");
            if (!string.IsNullOrWhiteSpace(variant)) titleOptions.Add($"Is {variant} {material} Actually Better? | {brand}");
            if (row.OverallScore >= 55) titleOptions.Add($"This {material} Deserves More Attention | {brand}");

            titleOptions.Add($"What Is {ShortenPlannerText(row.Label, 46)} Actually Good For?");

            row.SuggestedTitle = titleOptions
                .Where(title => !string.IsNullOrWhiteSpace(title))
                .Distinct(StringComparer.CurrentCultureIgnoreCase)
                .First();

            var hookParts = new List<string>();
            if (!row.HasVideo) hookParts.Add("No current video");
            if (row.ImpactScore >= 55) hookParts.Add("impact story");
            if (row.StiffnessScore >= 85) hookParts.Add("stiffness hook");
            if (row.ConsistencyScore >= 82) hookParts.Add("repeatability angle");
            if (!string.IsNullOrWhiteSpace(reinforcement)) hookParts.Add($"{reinforcement} comparison");

            row.SuggestedAngle = hookParts.Count == 0
                ? row.SuggestedAngle
                : $"Thumbnail hook: {string.Join(" + ", hookParts)}";

            row.DataReason = string.IsNullOrWhiteSpace(row.DataReason)
                ? $"Opportunity based on {FormatTitleScore(row.OverallScore)} overall, {FormatTitleScore(row.ImpactScore)} impact, {FormatTitleScore(row.StiffnessScore)} stiffness, and {FormatTitleScore(row.ConsistencyScore)} consistency."
                : row.DataReason;

            row.TalkingPoints = string.IsNullOrWhiteSpace(row.TalkingPoints)
                ? $"Overall {FormatTitleScore(row.OverallScore)}; impact {FormatTitleScore(row.ImpactScore)}; stiffness {FormatTitleScore(row.StiffnessScore)}; consistency {FormatTitleScore(row.ConsistencyScore)}."
                : row.TalkingPoints;
        }
    }


    private static void ApplyThumbnailResearchEngine(List<VideoPlannerRow> rows)
    {
        foreach (var row in rows.Where(row => row.HasMechanical))
        {
            var material = string.IsNullOrWhiteSpace(row.BaseMaterial) ? "FILAMENT" : row.BaseMaterial.Trim().ToUpperInvariant();
            var reinforcement = string.IsNullOrWhiteSpace(row.Reinforcement) || row.Reinforcement == "—" || row.Reinforcement == "-"
                ? string.Empty
                : row.Reinforcement.Trim().ToUpperInvariant();

            var tensile = row.TensileScore.GetValueOrDefault();
            var impact = row.ImpactScore.GetValueOrDefault();
            var stiffness = row.StiffnessScore.GetValueOrDefault();
            var consistency = row.ConsistencyScore.GetValueOrDefault();
            var overall = row.OverallScore.GetValueOrDefault();

            var strongestStory = "DATA TESTED";
            var visualMetric = "balanced test results";
            row.ThumbnailPattern = "Data Proof";

            if (impact >= stiffness && impact >= tensile && impact >= 45)
            {
                strongestStory = "TOUGH OR HYPE?";
                visualMetric = $"impact score {FormatTitleScore(row.ImpactScore)}";
                row.ThumbnailPattern = "Myth Busting";
            }
            else if (stiffness >= tensile && stiffness >= 65)
            {
                strongestStory = "SERIOUSLY STIFF?";
                visualMetric = $"stiffness score {FormatTitleScore(row.StiffnessScore)}";
                row.ThumbnailPattern = "Shock Result";
            }
            else if (tensile >= 40)
            {
                strongestStory = "STRONGER?";
                visualMetric = $"tensile score {FormatTitleScore(row.TensileScore)}";
                row.ThumbnailPattern = "Strength Claim";
            }
            else if (consistency >= 80)
            {
                strongestStory = "REPEATABLE?";
                visualMetric = $"consistency score {FormatTitleScore(row.ConsistencyScore)}";
                row.ThumbnailPattern = "Lab Proof";
            }

            if (!string.IsNullOrWhiteSpace(reinforcement))
            {
                row.ThumbnailMainText = $"{reinforcement} WORTH IT?";
                row.ThumbnailPattern = "Comparison";
                row.ThumbnailVisualLayout = $"Split layout: plain {material} on the left, {reinforcement} sample on the right, with one arrow toward the stronger data story ({visualMetric}).";
            }
            else
            {
                row.ThumbnailMainText = strongestStory;
                row.ThumbnailVisualLayout = $"Large tested part in foreground, one small data badge for {visualMetric}, and the full material name kept secondary.";
            }

            if (!row.HasVideo)
            {
                row.ThumbnailFaceDirection = "Curious/surprised creator reaction; this is a new video opportunity with no current channel coverage.";
            }
            else if (overall >= 55)
            {
                row.ThumbnailFaceDirection = "Confident approval reaction with visible data badge so it does not look like pure hype.";
            }
            else
            {
                row.ThumbnailFaceDirection = "Skeptical testing reaction; frame it as measured results, not a product endorsement.";
            }

            var score = 58;
            if (!row.HasVideo) score += 10;
            if (!string.IsNullOrWhiteSpace(reinforcement)) score += 8;
            if (impact >= 55) score += 8;
            if (stiffness >= 85) score += 8;
            if (tensile >= 45) score += 6;
            if (consistency >= 82) score += 5;
            if (overall >= 55) score += 5;
            if (row.ThumbnailMainText.Length <= 16) score += 4;
            row.ThumbnailScore = Math.Clamp(score, 0, 100);
            row.ThumbnailGrade = row.ThumbnailScore >= 92 ? "A+" : row.ThumbnailScore >= 84 ? "A" : row.ThumbnailScore >= 76 ? "B+" : row.ThumbnailScore >= 68 ? "B" : "C";

            row.ThumbnailRiskNote = "Avoid tiny chart text, long material names, and more than one main claim.";

            if (!string.IsNullOrWhiteSpace(reinforcement))
            {
                row.ThumbnailRecommendationReason = !row.HasVideo
                    ? $"Highest ranked {material} {reinforcement} candidate without current video coverage; comparison angle is clear and easy to understand."
                    : $"Strong comparison potential between standard {material} and {reinforcement}-reinforced {material}, backed by {visualMetric}.";
            }
            else if (stiffness >= 65 && stiffness >= impact && stiffness >= tensile)
            {
                row.ThumbnailRecommendationReason = $"Strong stiffness story backed by {visualMetric}, making the result easy to turn into a clear thumbnail claim.";
            }
            else if (impact >= 45 && impact >= stiffness && impact >= tensile)
            {
                row.ThumbnailRecommendationReason = $"Impact result creates a simple tough-or-hype story, backed by {visualMetric}.";
            }
            else if (consistency >= 80)
            {
                row.ThumbnailRecommendationReason = $"Repeatable lab result with {visualMetric}, which supports a trust-focused thumbnail.";
            }
            else
            {
                row.ThumbnailRecommendationReason = $"Clear data-tested thumbnail angle using {visualMetric}, with short readable text and a low-risk visual layout.";
            }

            row.ThumbnailPrompt = $"Thumbnail for {row.SuggestedTitle}. Main text: {row.ThumbnailMainText}. Pattern: {row.ThumbnailPattern}. Layout: {row.ThumbnailVisualLayout} Face: {row.ThumbnailFaceDirection}";
        }
    }


// Dashboard Insights intentionally uses local helper functions to keep this analytics layer
// self-contained while the WPF app is still kept as a single-window project.
private void UpdateDashboardInsights()
{
    try
    {
        // Dashboard inventory, coverage and scoring all use the same native
        // SQLite-backed material projection as the Materials tab.
        var nativeAllRows = _nativeMaterialRows.Where(row => !row.IsArchived).ToList();
        var nativeVisibleIds = GetVisibleNativeMaterialIdsFromCurrentFilters();
        var nativeVisibleRows = nativeAllRows
            .Where(row => string.IsNullOrWhiteSpace(row.MaterialID) || nativeVisibleIds.Contains(row.MaterialID.Trim()))
            .ToList();

        int totalMaterials = nativeAllRows.Count;
        int visibleMaterials = nativeVisibleRows.Count;

        string GetCell(System.Data.DataRow row, params string[] names)
        {
            if (row.Table == null) return string.Empty;
            foreach (var name in names)
            {
                if (row.Table.Columns.Contains(name))
                    return row[name]?.ToString()?.Trim() ?? string.Empty;
            }
            return string.Empty;
        }

        string DisplayScore(double? score)
        {
            return score.HasValue ? $"{score.Value:0.#}/100" : "N/A";
        }

        string DisplayLeader(string label, double? score)
        {
            return string.IsNullOrWhiteSpace(label) || label == "N/A" || !score.HasValue
                ? "N/A"
                : $"{label} ({score.Value:0.#}/100)";
        }

        bool HasVideo(VideoPlannerRow video)
        {
            if (!string.IsNullOrWhiteSpace(video.Status) &&
                video.Status.IndexOf("Has video", StringComparison.CurrentCultureIgnoreCase) >= 0)
                return true;

            return false;
        }

        var visibleRows = GetCanonicalVisibleMaterialRows();
        var allRows = GetCanonicalActiveMaterialRows();

        var manufacturers = new HashSet<string>(StringComparer.CurrentCultureIgnoreCase);
        var types = new HashSet<string>(StringComparer.CurrentCultureIgnoreCase);
        var reinforcements = new HashSet<string>(StringComparer.CurrentCultureIgnoreCase);

        if (nativeAllRows.Count > 0)
        {
            foreach (var row in nativeAllRows)
            {
                if (!string.IsNullOrWhiteSpace(row.Manufacturer)) manufacturers.Add(row.Manufacturer.Trim());
                if (!string.IsNullOrWhiteSpace(row.BaseMaterial)) types.Add(row.BaseMaterial.Trim());
                if (!string.IsNullOrWhiteSpace(row.Reinforcement) && row.Reinforcement != "—" && row.Reinforcement != "-")
                    reinforcements.Add(row.Reinforcement.Trim());
            }
        }
        else
        {
            foreach (var row in allRows)
            {
                var manufacturer = GetCell(row, "Manufacturer", "Brand", "Vendor", "Maker");
                if (!string.IsNullOrWhiteSpace(manufacturer)) manufacturers.Add(manufacturer);

                var type = GetCell(row, "Material Type", "Base Material", "Type", "Material Family");
                if (!string.IsNullOrWhiteSpace(type)) types.Add(type);

                var reinforcement = GetCell(row, "Reinforcement", "Reinforced", "Filler");
                if (!string.IsNullOrWhiteSpace(reinforcement) && reinforcement != "—" && reinforcement != "-")
                    reinforcements.Add(reinforcement);
            }
        }

        var dashboardRows = visibleRows
            .Select(row =>
            {
                var video = BuildVideoPlannerRow(row);
                var ranking = BuildRankingRow(video, "Overall");
                var hasVideo = HasVideo(video);
                var hiddenGemScore =
                    (ranking.Overall ?? 0) +
                    ((ranking.Impact ?? 0) * 0.20) +
                    ((ranking.Consistency ?? 0) * 0.15) +
                    ((ranking.LayerAdhesion ?? 0) * 0.10) +
                    (hasVideo ? 0 : 12);

                return new
                {
                    Video = video,
                    Ranking = ranking,
                    HasVideo = hasVideo,
                    HiddenGemScore = hiddenGemScore
                };
            })
            .ToList();

        var bestOverall = dashboardRows
            .Where(x => x.Ranking.Overall.HasValue)
            .OrderByDescending(x => x.Ranking.Overall!.Value)
            .ThenBy(x => x.Video.Label)
            .FirstOrDefault();

        var bestTensile = dashboardRows
            .Where(x => x.Ranking.Tensile.HasValue)
            .OrderByDescending(x => x.Ranking.Tensile!.Value)
            .ThenBy(x => x.Video.Label)
            .FirstOrDefault();

        var bestImpact = dashboardRows
            .Where(x => x.Ranking.Impact.HasValue)
            .OrderByDescending(x => x.Ranking.Impact!.Value)
            .ThenBy(x => x.Video.Label)
            .FirstOrDefault();

        var bestStiffness = dashboardRows
            .Where(x => x.Ranking.Stiffness.HasValue)
            .OrderByDescending(x => x.Ranking.Stiffness!.Value)
            .ThenBy(x => x.Video.Label)
            .FirstOrDefault();

        DashboardMaterialsText.Text = totalMaterials.ToString();
        DashboardManufacturersText.Text = manufacturers.Count.ToString();
        DashboardTypesText.Text = types.Count.ToString();
        if (DashboardReinforcementText != null) DashboardReinforcementText.Text = reinforcements.Count.ToString();

        if (DashboardHighestOverallText != null) DashboardHighestOverallText.Text = bestOverall == null ? "N/A" : DisplayLeader(bestOverall.Video.Label, bestOverall.Ranking.Overall);
        if (DashboardHighestTensileText != null) DashboardHighestTensileText.Text = bestTensile == null ? "N/A" : DisplayLeader(bestTensile.Video.Label, bestTensile.Ranking.Tensile);
        if (DashboardHighestImpactText != null) DashboardHighestImpactText.Text = bestImpact == null ? "N/A" : DisplayLeader(bestImpact.Video.Label, bestImpact.Ranking.Impact);
        if (DashboardHighestStiffnessText != null) DashboardHighestStiffnessText.Text = bestStiffness == null ? "N/A" : DisplayLeader(bestStiffness.Video.Label, bestStiffness.Ranking.Stiffness);

        var topManufacturers = nativeAllRows.Count > 0
            ? nativeAllRows.GroupBy(row => row.Manufacturer?.Trim() ?? string.Empty, StringComparer.CurrentCultureIgnoreCase)
                .Where(g => !string.IsNullOrWhiteSpace(g.Key)).OrderByDescending(g => g.Count()).ThenBy(g => g.Key)
                .Take(8).Select(g => $"  - {g.Key}: {g.Count()} material(s)").ToList()
            : allRows.GroupBy(row => GetCell(row, "Manufacturer", "Brand", "Vendor", "Maker"))
                .Where(g => !string.IsNullOrWhiteSpace(g.Key)).OrderByDescending(g => g.Count()).ThenBy(g => g.Key)
                .Take(8).Select(g => $"  - {g.Key}: {g.Count()} material(s)").ToList();

        var topTypes = nativeAllRows.Count > 0
            ? nativeAllRows.GroupBy(row => row.BaseMaterial?.Trim() ?? string.Empty, StringComparer.CurrentCultureIgnoreCase)
                .Where(g => !string.IsNullOrWhiteSpace(g.Key)).OrderByDescending(g => g.Count()).ThenBy(g => g.Key)
                .Take(8).Select(g => $"  - {g.Key}: {g.Count()} material(s)").ToList()
            : allRows.GroupBy(row => GetCell(row, "Material Type", "Base Material", "Type", "Material Family"))
                .Where(g => !string.IsNullOrWhiteSpace(g.Key)).OrderByDescending(g => g.Count()).ThenBy(g => g.Key)
                .Take(8).Select(g => $"  - {g.Key}: {g.Count()} material(s)").ToList();

        var hiddenGems = dashboardRows
            .Where(x => !x.HasVideo)
            .Where(x => (x.Ranking.Overall ?? 0) >= 45 || (x.Ranking.Impact ?? 0) >= 50 || (x.Ranking.Stiffness ?? 0) >= 80 || (x.Ranking.Consistency ?? 0) >= 80)
            .OrderByDescending(x => x.HiddenGemScore)
            .ThenByDescending(x => x.Ranking.Overall ?? 0)
            .ThenBy(x => x.Video.Label)
            .Take(10)
            .Select((x, index) =>
            {
                var reasonParts = new List<string>();
                if ((x.Ranking.Overall ?? 0) >= 55) reasonParts.Add($"overall {DisplayScore(x.Ranking.Overall)}");
                if ((x.Ranking.Impact ?? 0) >= 50) reasonParts.Add($"impact {DisplayScore(x.Ranking.Impact)}");
                if ((x.Ranking.Stiffness ?? 0) >= 80) reasonParts.Add($"stiffness {DisplayScore(x.Ranking.Stiffness)}");
                if ((x.Ranking.Consistency ?? 0) >= 80) reasonParts.Add($"consistency {DisplayScore(x.Ranking.Consistency)}");
                if (reasonParts.Count == 0) reasonParts.Add($"overall {DisplayScore(x.Ranking.Overall)}");

                return $"  {index + 1}. {x.Video.Label}\r\n" +
                       $"     {x.Video.Manufacturer} | {x.Video.BaseMaterial} | {DisplayText(x.Video.Reinforcement)}\r\n" +
                       $"     Hidden Gem Score: {x.HiddenGemScore:0.#} | {string.Join(", ", reasonParts)}\r\n" +
                       $"     Suggested angle: {x.Video.SuggestedAngle}";
            })
            .ToList();

        var smallestTypes = nativeAllRows.Count > 0
            ? nativeAllRows.GroupBy(row => row.BaseMaterial?.Trim() ?? string.Empty, StringComparer.CurrentCultureIgnoreCase)
                .Where(g => !string.IsNullOrWhiteSpace(g.Key)).OrderBy(g => g.Count()).ThenBy(g => g.Key)
                .Take(5).Select(g => $"  - {g.Key}: {g.Count()} material(s)").ToList()
            : allRows.GroupBy(row => GetCell(row, "Material Type", "Base Material", "Type", "Material Family"))
                .Where(g => !string.IsNullOrWhiteSpace(g.Key)).OrderBy(g => g.Count()).ThenBy(g => g.Key)
                .Take(5).Select(g => $"  - {g.Key}: {g.Count()} material(s)").ToList();

        var lowCoverageManufacturers = nativeAllRows.Count > 0
            ? nativeAllRows.GroupBy(row => row.Manufacturer?.Trim() ?? string.Empty, StringComparer.CurrentCultureIgnoreCase)
                .Where(g => !string.IsNullOrWhiteSpace(g.Key)).OrderBy(g => g.Count()).ThenBy(g => g.Key)
                .Take(5).Select(g => $"  - {g.Key}: {g.Count()} material(s)").ToList()
            : allRows.GroupBy(row => GetCell(row, "Manufacturer", "Brand", "Vendor", "Maker"))
                .Where(g => !string.IsNullOrWhiteSpace(g.Key)).OrderBy(g => g.Count()).ThenBy(g => g.Key)
                .Take(5).Select(g => $"  - {g.Key}: {g.Count()} material(s)").ToList();

        var topCoverageManufacturers = dashboardRows
            .GroupBy(x => x.Video.Manufacturer)
            .Where(g => !string.IsNullOrWhiteSpace(g.Key))
            .OrderByDescending(g => g.Count())
            .ThenBy(g => g.Key)
            .Take(8)
            .Select(g => $"  - {g.Key}: {g.Count()} material(s)")
            .ToList();

        var strongestManufacturers = dashboardRows
            .Where(x => x.Ranking.Overall.HasValue)
            .GroupBy(x => x.Video.Manufacturer)
            .Where(g => !string.IsNullOrWhiteSpace(g.Key) && g.Count(x => x.Ranking.Overall.HasValue) >= 3)
            .Select(g => new
            {
                Manufacturer = g.Key,
                Count = g.Count(x => x.Ranking.Overall.HasValue),
                Average = g.Where(x => x.Ranking.Overall.HasValue).Average(x => x.Ranking.Overall!.Value),
                Best = g.Where(x => x.Ranking.Overall.HasValue).OrderByDescending(x => x.Ranking.Overall!.Value).First()
            })
            .OrderByDescending(x => x.Average)
            .ThenByDescending(x => x.Count)
            .ThenBy(x => x.Manufacturer)
            .Take(8)
            .Select(x => $"  - {x.Manufacturer}: avg {x.Average:0.#}/100 across {x.Count} material(s), best {x.Best.Video.Label} ({x.Best.Ranking.Overall!.Value:0.#}/100)")
            .ToList();

        var mostConsistentManufacturers = dashboardRows
            .Where(x => x.Ranking.Consistency.HasValue)
            .GroupBy(x => x.Video.Manufacturer)
            .Where(g => !string.IsNullOrWhiteSpace(g.Key) && g.Count(x => x.Ranking.Consistency.HasValue) >= 3)
            .Select(g => new
            {
                Manufacturer = g.Key,
                Count = g.Count(x => x.Ranking.Consistency.HasValue),
                Average = g.Where(x => x.Ranking.Consistency.HasValue).Average(x => x.Ranking.Consistency!.Value),
                Best = g.Where(x => x.Ranking.Consistency.HasValue).OrderByDescending(x => x.Ranking.Consistency!.Value).First()
            })
            .OrderByDescending(x => x.Average)
            .ThenByDescending(x => x.Count)
            .ThenBy(x => x.Manufacturer)
            .Take(8)
            .Select(x => $"  - {x.Manufacturer}: avg consistency {x.Average:0.#}/100 across {x.Count} material(s), best {x.Best.Video.Label} ({x.Best.Ranking.Consistency!.Value:0.#}/100)")
            .ToList();

        var categoryLeaders = dashboardRows
            .Where(x => !string.IsNullOrWhiteSpace(x.Video.BaseMaterial) && x.Ranking.Overall.HasValue)
            .GroupBy(x => x.Video.BaseMaterial)
            .OrderByDescending(g => g.Count())
            .ThenBy(g => g.Key)
            .Take(10)
            .Select(g =>
            {
                var leader = g.OrderByDescending(x => x.Ranking.Overall!.Value).ThenBy(x => x.Video.Label).First();
                return $"  - {g.Key}: {leader.Video.Label} ({leader.Ranking.Overall!.Value:0.#}/100)";
            })
            .ToList();

        var youtubeOpportunityRows = dashboardRows
            .Select(x =>
            {
                var noVideoBonus = x.HasVideo ? 0 : 25;
                var score =
                    noVideoBonus +
                    ((x.Ranking.Overall ?? 0) * 0.35) +
                    ((x.Ranking.Impact ?? 0) * 0.20) +
                    ((x.Ranking.Stiffness ?? 0) * 0.15) +
                    ((x.Ranking.Consistency ?? 0) * 0.15) +
                    ((x.Ranking.LayerAdhesion ?? 0) * 0.10);

                var reasonParts = new List<string>();
                if (!x.HasVideo) reasonParts.Add("no video");
                if ((x.Ranking.Overall ?? 0) >= 55) reasonParts.Add($"overall {DisplayScore(x.Ranking.Overall)}");
                if ((x.Ranking.Impact ?? 0) >= 50) reasonParts.Add($"impact {DisplayScore(x.Ranking.Impact)}");
                if ((x.Ranking.Stiffness ?? 0) >= 80) reasonParts.Add($"stiffness {DisplayScore(x.Ranking.Stiffness)}");
                if ((x.Ranking.Consistency ?? 0) >= 80) reasonParts.Add($"consistency {DisplayScore(x.Ranking.Consistency)}");
                if (reasonParts.Count == 0) reasonParts.Add("balanced score profile");

                return new
                {
                    x.Video,
                    x.Ranking,
                    x.HasVideo,
                    OpportunityScore = score,
                    Reasons = string.Join(", ", reasonParts)
                };
            })
            .Where(x => !x.HasVideo)
            .OrderByDescending(x => x.OpportunityScore)
            .ThenByDescending(x => x.Ranking.Overall ?? 0)
            .ThenBy(x => x.Video.Label)
            .Take(10)
            .Select((x, index) =>
                $"  {index + 1}. {x.Video.Label}\r\n" +
                $"     {x.Video.Manufacturer} | {x.Video.BaseMaterial} | {DisplayText(x.Video.Reinforcement)}\r\n" +
                $"     Opportunity Score: {x.OpportunityScore:0.#}/100 | {x.Reasons}\r\n" +
                $"     Suggested angle: {x.Video.SuggestedAngle}")
            .ToList();

        DashboardInsightsText.Text =
            "DATABASE OVERVIEW\r\n" +
            "=================\r\n" +
            $"Materials tested: {totalMaterials}\r\n" +
            $"Visible / filtered materials: {visibleMaterials}\r\n" +
            $"Manufacturers: {manufacturers.Count}\r\n" +
            $"Material types: {types.Count}\r\n" +
            $"Reinforcement types: {reinforcements.Count}\r\n\r\n" +
            "CURRENT LEADERS\r\n" +
            "===============\r\n" +
            $"Highest overall: {(bestOverall == null ? "N/A" : DisplayLeader(bestOverall.Video.Label, bestOverall.Ranking.Overall))}\r\n" +
            $"Highest tensile: {(bestTensile == null ? "N/A" : DisplayLeader(bestTensile.Video.Label, bestTensile.Ranking.Tensile))}\r\n" +
            $"Highest impact: {(bestImpact == null ? "N/A" : DisplayLeader(bestImpact.Video.Label, bestImpact.Ranking.Impact))}\r\n" +
            $"Highest stiffness: {(bestStiffness == null ? "N/A" : DisplayLeader(bestStiffness.Video.Label, bestStiffness.Ranking.Stiffness))}\r\n\r\n" +
            "OPPORTUNITY DISCOVERY\r\n" +
            "=====================\r\n" +
            $"Hidden gem candidates found: {hiddenGems.Count}\r\n" +
            "Under-tested material types:\r\n" +
            (smallestTypes.Count > 0 ? string.Join("\r\n", smallestTypes) : "  - N/A") +
            "\r\n\r\nManufacturers with low coverage:\r\n" +
            (lowCoverageManufacturers.Count > 0 ? string.Join("\r\n", lowCoverageManufacturers) : "  - N/A") +
            "\r\n\r\nRecommended actions:\r\n" +
            "  - Prioritize hidden gems without videos.\r\n" +
            "  - Expand low-count material categories.\r\n" +
            "  - Look for CF/GF comparison opportunities.\r\n" +
            "  - Use high-impact or high-consistency outliers as video candidates.\r\n\r\n" +
            "YOUTUBE OPPORTUNITY SCORING\r\n" +
            "===========================\r\n" +
            "Ranked video candidates using no-video bonus, overall score, impact, stiffness, consistency and layer adhesion.\r\n" +
            (youtubeOpportunityRows.Count > 0 ? string.Join("\r\n", youtubeOpportunityRows) : "  No YouTube opportunity candidates found.") +
            "\r\n\r\n" +
            "COMPETITIVE INSIGHTS\r\n" +
            "====================\r\n" +
            "Top manufacturers by coverage:\r\n" +
            (topCoverageManufacturers.Count > 0 ? string.Join("\r\n", topCoverageManufacturers) : "  - N/A") +
            "\r\n\r\nStrongest manufacturers by average overall score:\r\n" +
            (strongestManufacturers.Count > 0 ? string.Join("\r\n", strongestManufacturers) : "  - N/A") +
            "\r\n\r\nMost consistent manufacturers:\r\n" +
            (mostConsistentManufacturers.Count > 0 ? string.Join("\r\n", mostConsistentManufacturers) : "  - N/A") +
            "\r\n\r\nCategory leaders:\r\n" +
            (categoryLeaders.Count > 0 ? string.Join("\r\n", categoryLeaders) : "  - N/A") +
            "\r\n\r\n" +
            "CREATOR ROADMAP\r\n" +
            "================\r\n" +
            $"Video candidates available: {hiddenGems.Count}\r\n\r\n" +
            "IMMEDIATE VIDEOS (NEXT 30 DAYS)\r\n" +
            "-------------------------------\r\n" +
            (hiddenGems.Count > 0 ? string.Join("\r\n", hiddenGems.Take(3)) : "No candidates found.") +
            "\r\n\r\nCOMPARISON VIDEO IDEAS\r\n" +
            "----------------------\r\n" +
            "- PA6 CF vs PA6 GF\r\n" +
            "- PLA Tough vs PLA High Speed\r\n" +
            "- ASA vs ASA CF\r\n" +
            "- CF vs GF reinforcement showdown\r\n" +
            "\r\n\r\nCONTENT BACKLOG\r\n" +
            "---------------\r\n" +
            $"Remaining hidden gem opportunities: {Math.Max(0, hiddenGems.Count - 3)}\r\n" +
            "Use remaining candidates for future manufacturer-focused series.\r\n\r\n" +
            "HIDDEN GEMS\r\n" +
            "===========\r\n" +
            "High-potential materials without an existing video, ranked by score profile and YouTube usefulness.\r\n" +
            (hiddenGems.Count > 0 ? string.Join("\r\n", hiddenGems) : "  No hidden gems found in the current visible dataset.") +
            "\r\n\r\nDATABASE HEALTH\r\n" +
            "===============\r\n" +
            "Most tested manufacturers:\r\n" +
            string.Join("\r\n", topManufacturers) +
            "\r\n\r\nMost tested material types:\r\n" +
            string.Join("\r\n", topTypes) +
            "\r\n\r\nNEXT INSIGHT MODULES\r\n" +
            "====================\r\n" +
            "- Creator Insights";
    }
    catch
    {
        // Dashboard insights must never block the main database workflow.
    }
}


    private enum AiAssistantOutputKind
    {
        LocalAdvisory,
        OpenAiPayloadPreview,
        OpenAiAdvisory,
