    private void SaveAiSession_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            var currentOutput = GetTextBoxText("AiAssistantOutputBox");
            if (!CanPersistAiAssistantSession(_aiAssistantOutputKind, currentOutput, out var reason))
            {
                MessageBox.Show(
                    reason,
                    "AI Assistant Session",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            var sessions = LoadAiSavedSessions().ToList();
            var title = GetTextBoxText("AiSessionTitleBox").Trim();
            if (string.IsNullOrWhiteSpace(title))
            {
                title = $"AI session {DateTime.Now:yyyy-MM-dd HH.mm}";
            }

            var existing = sessions.FirstOrDefault(item => string.Equals(item.Title, title, StringComparison.OrdinalIgnoreCase));
            if (existing is null)
            {
                existing = new AiAssistantSavedSession
                {
                    Id = Guid.NewGuid().ToString("N"),
                    Title = title,
                    CreatedAt = DateTime.Now
                };
                sessions.Insert(0, existing);
            }

            existing.Title = title;
            existing.TemplateName = GetSelectedAiTemplateName();
            existing.PromptText = GetTextBoxText("AiPromptEditorBox");
            existing.OutputText = currentOutput;
            existing.VisibleMaterialCount = GetCanonicalVisibleMaterialRows().Count;
            existing.DatabaseContext = BuildAiSessionContext();
            existing.UpdatedAt = DateTime.Now;

            SaveAiSavedSessions(sessions.Take(200).ToList());
            LoadAiSavedSessionsIntoCombo(existing.Id);
            SetAiAssistantOutput(existing.OutputText + "\r\n\r\nSESSION SAVED\r\n-------------\r\n" + existing.Title + "\r\n" + existing.DatabaseContext);
        }
        catch (Exception ex)
        {
            MessageBox.Show($"Could not save AI Assistant session.\n\n{ex.Message}", "AI Assistant", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

    private void LoadAiSession_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            var combo = FindName("AiSavedSessionsCombo") as ComboBox;
            var selectedId = combo?.SelectedValue as string;
            if (string.IsNullOrWhiteSpace(selectedId))
            {
                MessageBox.Show("Select a saved AI Assistant session first.", "AI Assistant", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            var session = LoadAiSavedSessions().FirstOrDefault(item => item.Id == selectedId);
            if (session is null)
            {
                MessageBox.Show("The selected AI Assistant session could not be found.", "AI Assistant", MessageBoxButton.OK, MessageBoxImage.Information);
                LoadAiSavedSessionsIntoCombo();
                return;
            }

            SetTextBoxText("AiSessionTitleBox", session.Title);
            SelectAiTemplate(session.TemplateName);
            SetTextBoxText("AiPromptEditorBox", session.PromptText);

            var output = string.IsNullOrWhiteSpace(session.OutputText)
                ? "This research session does not contain generated output yet."
                : session.OutputText;

            if (!string.IsNullOrWhiteSpace(session.DatabaseContext))
            {
                output += "\r\n\r\nSAVED SESSION CONTEXT\r\n---------------------\r\n" + session.DatabaseContext;
            }

            SetAiAssistantOutput(output);
        }
        catch (Exception ex)
        {
            MessageBox.Show($"Could not load AI Assistant session.\n\n{ex.Message}", "AI Assistant", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

