    private void DeleteAiSession_Click(object sender, RoutedEventArgs e)
    {
        if (IsAutomationActionBlocked("AI session deletion")) return;
        try
        {
            var combo = FindName("AiSavedSessionsCombo") as ComboBox;
            var selectedId = combo?.SelectedValue as string;
            if (string.IsNullOrWhiteSpace(selectedId))
            {
                MessageBox.Show("Select a research session to delete.", "AI Assistant", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            var sessions = LoadAiSavedSessions().ToList();
            var session = sessions.FirstOrDefault(item => item.Id == selectedId);
            if (session is null)
            {
                LoadAiSavedSessionsIntoCombo();
                return;
            }

            var result = MessageBox.Show($"Delete saved research session '{session.Title}'?", "Delete AI Session", MessageBoxButton.YesNo, MessageBoxImage.Question);
            if (result != MessageBoxResult.Yes)
            {
                return;
            }

            sessions.RemoveAll(item => item.Id == selectedId);
            SaveAiSavedSessions(sessions);
            LoadAiSavedSessionsIntoCombo();
            SetAiAssistantOutput("Deleted research session: " + session.Title);
        }
        catch (Exception ex)
        {
            MessageBox.Show($"Could not delete AI Assistant session.\n\n{ex.Message}", "AI Assistant", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }


