    private bool IsAiSelectedCollectionScope()
    {
        if (FindName("AiMaterialCollectionScopeCombo") is ComboBox combo &&
            combo.SelectedItem is ComboBoxItem item &&
            item.Content is not null)
        {
            return item.Content.ToString()?.Contains("Selected collection", StringComparison.OrdinalIgnoreCase) == true;
        }

        return false;
    }

    private List<DataRow> GetAiMaterialIntelligenceRows()
    {
        if (IsAiSelectedCollectionScope())
        {
            var collection = GetSelectedAiMaterialCollection();
            if (collection is not null && collection.MaterialKeys.Count > 0)
            {
                var selectedKeys = new HashSet<string>(collection.MaterialKeys, StringComparer.OrdinalIgnoreCase);
                return GetCanonicalActiveMaterialRows()
                    .Where(row => selectedKeys.Contains(BuildAiMaterialKey(row)))
                    .ToList();
            }
        }

        return GetCanonicalVisibleMaterialRows();
    }

    private string GetAiMaterialIntelligenceScopeLabel()
    {
        if (IsAiSelectedCollectionScope())
        {
            var collection = GetSelectedAiMaterialCollection();
            if (collection is not null)
            {
                return "Selected collection: " + collection.Title;
            }

            return "Selected collection: none selected";
        }

        return "Current visible rows";
    }

    private string BuildAiMaterialKey(DataRow row)
    {
        var materialId = AiCellValue(row, "Material ID", "MaterialID", "ID");
        if (!string.IsNullOrWhiteSpace(materialId))
        {
            return materialId;
        }

        return BuildAiMaterialCollectionLabel(row);
    }

    private string BuildAiMaterialCollectionLabel(DataRow row)
    {
        return JoinNonEmpty(" ",
            AiCellValue(row, "Manufacturer", "Brand"),
            AiCellValue(row, "Product Line", "ProductLine", "Series"),
            AiCellValue(row, "Marketing Name", "Material Name", "Name"),
            AiCellValue(row, "Base Material", "Material Type", "Type"),
            AiCellValue(row, "Reinforcement", "Reinforment", "Filled"));
    }

    private string BuildAiMaterialCollectionBrief(AiMaterialCollection collection)
    {
        var savedKeys = collection.MaterialKeys
            .Where(key => !string.IsNullOrWhiteSpace(key))
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        var activeCount = _nativeMaterialRows.Count(row =>
            !row.IsArchived && savedKeys.Contains(row.MaterialID));
        var archivedCount = _nativeMaterialRows.Count(row =>
            row.IsArchived && savedKeys.Contains(row.MaterialID));
        var knownKeys = _nativeMaterialRows
            .Where(row => savedKeys.Contains(row.MaterialID))
            .Select(row => row.MaterialID)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        var missingCount = savedKeys.Count(key => !knownKeys.Contains(key));
        var lines = new List<string>
        {
            "MATERIAL COLLECTION",
            "===================",
            "Title: " + collection.Title,
            "Materials: " + collection.MaterialKeys.Count,
            $"Resolved active: {activeCount}",
            $"Archived: {archivedCount}",
            $"Missing: {missingCount}",
            "Saved set SHA-256: " +
            (string.IsNullOrWhiteSpace(collection.MaterialIdSetSha256)
                ? "not recorded by this legacy snapshot"
                : collection.MaterialIdSetSha256),
            "Updated: " + collection.UpdatedAt.ToString("yyyy-MM-dd HH:mm"),
            "",
            "DATABASE CONTEXT",
            "----------------",
            string.IsNullOrWhiteSpace(collection.DatabaseContext) ? "No saved context." : collection.DatabaseContext,
            "",
            "MATERIALS",
            "---------"
        };

        if (collection.MaterialLabels.Count == 0)
        {
            lines.Add("No material labels were saved.");
        }
        else
        {
            lines.AddRange(collection.MaterialLabels.Take(80).Select(label => "- " + label));
        }

        lines.Add("");
        lines.Add("NEXT ACTION");
        lines.Add("-----------");
        lines.Add("Set Intelligence scope to Selected collection, then use Recommended Next Video, Recommended Comparisons or Hidden Gems.");

        return string.Join("\r\n", lines);
    }

    private sealed class AiMaterialInsight
    {
        public string Label { get; set; } = "";
        public string Manufacturer { get; set; } = "";
        public string ProductLine { get; set; } = "";
        public string BaseMaterial { get; set; } = "";
        public string Reinforcement { get; set; } = "";
        public string Category { get; set; } = "";
        public double Score { get; set; }
        public string Reason { get; set; } = "";
    }
    private sealed class AiCoverageEntry
    {
        public string CollectionId { get; set; } = "";
        public string MaterialKey { get; set; } = "";
        public string CollectionTitle { get; set; } = "";
        public string MaterialLabel { get; set; } = "";
        public string Status { get; set; } = "";
        public string UpdatedUtc { get; set; } = DateTime.UtcNow.ToString("O");
    }

    private sealed class AiCollectionMaterialIdentity
    {
        public string MaterialKey { get; init; } = "";
        public string MaterialLabel { get; init; } = "";
    }

    private sealed class AiCoverageBindingCandidate
    {
        public AiCoverageEntry Entry { get; init; } = new();
        public AiMaterialCollection Collection { get; init; } = new();
        public AiCollectionMaterialIdentity Material { get; init; } = new();
    }

    private string AiCoverageFilePath()
    {
        return StorageWorkingFilePath("ai-material-coverage.json");
    }

    private List<AiCoverageEntry> LoadAiCoverageEntries()
    {
        try
        {
            var path = AiCoverageFilePath();
            if (!File.Exists(path))
            {
                return new List<AiCoverageEntry>();
            }

            var json = File.ReadAllText(path);
            return JsonSerializer.Deserialize<List<AiCoverageEntry>>(json) ?? new List<AiCoverageEntry>();
        }
        catch
        {
            return new List<AiCoverageEntry>();
        }
    }

    private void SaveAiCoverageEntries(List<AiCoverageEntry> entries)
    {
        var json = JsonSerializer.Serialize(entries, new JsonSerializerOptions { WriteIndented = true });
        File.WriteAllText(AiCoverageFilePath(), json);
    }

    private static bool HasStableAiCoverageIdentity(AiCoverageEntry entry) =>
        !string.IsNullOrWhiteSpace(entry.CollectionId) &&
        !string.IsNullOrWhiteSpace(entry.MaterialKey);

    private static bool AiCoverageEntryMatches(
        AiCoverageEntry entry,
        AiMaterialCollection collection,
        AiCollectionMaterialIdentity material)
    {
        if (HasStableAiCoverageIdentity(entry))
        {
            return string.Equals(entry.CollectionId, collection.Id, StringComparison.OrdinalIgnoreCase) &&
                   string.Equals(entry.MaterialKey, material.MaterialKey, StringComparison.OrdinalIgnoreCase);
        }

        return string.Equals(entry.CollectionTitle, collection.Title, StringComparison.OrdinalIgnoreCase) &&
               string.Equals(entry.MaterialLabel, material.MaterialLabel, StringComparison.OrdinalIgnoreCase);
    }

    private static bool AiCoverageBelongsToCollection(
        AiCoverageEntry entry,
        AiMaterialCollection collection)
    {
        return (HasStableAiCoverageIdentity(entry) &&
                string.Equals(entry.CollectionId, collection.Id, StringComparison.OrdinalIgnoreCase)) ||
               (!HasStableAiCoverageIdentity(entry) &&
                string.Equals(entry.CollectionTitle, collection.Title, StringComparison.OrdinalIgnoreCase));
    }

    private static string AiCoverageStatusFor(
        IEnumerable<AiCoverageEntry> entries,
        AiMaterialCollection collection,
        AiCollectionMaterialIdentity material)
    {
        return entries.FirstOrDefault(entry => AiCoverageEntryMatches(entry, collection, material))?.Status ?? "Open";
    }

    private static List<AiCollectionMaterialIdentity> GetAiCollectionMaterials(AiMaterialCollection collection)
    {
        var keys = collection.MaterialKeys ?? new List<string>();
        var labels = collection.MaterialLabels ?? new List<string>();
        var count = Math.Min(keys.Count, labels.Count);
        var materials = new List<AiCollectionMaterialIdentity>();

        for (var index = 0; index < count; index++)
        {
            var key = keys[index]?.Trim() ?? "";
            var label = labels[index]?.Trim() ?? "";
            if (string.IsNullOrWhiteSpace(key) || string.IsNullOrWhiteSpace(label))
            {
                continue;
            }

            materials.Add(new AiCollectionMaterialIdentity
            {
                MaterialKey = key,
                MaterialLabel = label
            });
        }

        return materials;
    }

    private static List<AiCoverageBindingCandidate> BuildExactAiCoverageBindingCandidates(
        IReadOnlyList<AiCoverageEntry> entries,
        IReadOnlyList<AiMaterialCollection> collections)
    {
        var candidates = new List<AiCoverageBindingCandidate>();

        foreach (var entry in entries.Where(item => !HasStableAiCoverageIdentity(item)))
        {
            var matchingCollections = collections
                .Where(collection =>
                    string.Equals(collection.Title, entry.CollectionTitle, StringComparison.OrdinalIgnoreCase))
                .ToList();
            if (matchingCollections.Count != 1)
            {
                continue;
            }

            var collection = matchingCollections[0];
            var matchingMaterials = GetAiCollectionMaterials(collection)
                .Where(material =>
                    string.Equals(material.MaterialLabel, entry.MaterialLabel, StringComparison.OrdinalIgnoreCase))
                .ToList();
            if (matchingMaterials.Count != 1)
            {
                continue;
            }

            candidates.Add(new AiCoverageBindingCandidate
            {
                Entry = entry,
                Collection = collection,
                Material = matchingMaterials[0]
            });
        }

        return candidates;
    }

    private void RefreshAiCoverageIdentityStatus()
    {
        if (FindName("AiCoverageIdentityStatus") is not TextBlock statusText)
        {
            return;
        }

        var entries = LoadAiCoverageEntries();
        var stable = entries.Count(HasStableAiCoverageIdentity);
        var legacy = entries.Count - stable;
        var candidates = BuildExactAiCoverageBindingCandidates(entries, LoadAiMaterialCollections());
        statusText.Text =
            $"Coverage identity: {stable:N0} stable CollectionID/MaterialID, {legacy:N0} legacy; " +
            $"{candidates.Count:N0} unique exact legacy binding candidate(s).";
    }

    private void BindExactAiCoverageIdentity_Click(object sender, RoutedEventArgs e)
    {
        if (IsAutomationActionBlocked("AI coverage identity binding")) return;

        var entries = LoadAiCoverageEntries();
        var collections = LoadAiMaterialCollections();
        var candidates = BuildExactAiCoverageBindingCandidates(entries, collections);
        var legacyCount = entries.Count(item => !HasStableAiCoverageIdentity(item));
        var unmatched = legacyCount - candidates.Count;

        if (candidates.Count == 0)
        {
            SetAiAssistantOutput(
                "EXACT LEGACY COVERAGE BINDING\r\n" +
                "=============================\r\n" +
                $"Legacy entries: {legacyCount:N0}\r\n" +
                "Unique exact candidates: 0\r\n" +
                $"Unmatched or ambiguous retained unchanged: {unmatched:N0}\r\n\r\n" +
                "No coverage data was changed.");
            RefreshAiCoverageIdentityStatus();
            return;
        }

        var preview = string.Join(
            "\r\n",
            candidates.Take(12).Select(candidate =>
                $"- {candidate.Collection.Title} / {candidate.Material.MaterialKey} / {candidate.Entry.Status}"));
        if (candidates.Count > 12)
        {
            preview += $"\r\n- ... and {candidates.Count - 12:N0} more";
        }

        var confirmation = MessageBox.Show(
            $"Bind {candidates.Count:N0} legacy coverage entry/entries to unique exact Collection ID and MaterialID matches?\n\n" +
            preview +
            $"\n\n{unmatched:N0} unmatched or ambiguous legacy entry/entries will remain unchanged.\n" +
            "No fuzzy matching or status remapping is performed.",
            "Bind Exact Legacy Coverage Identity?",
            MessageBoxButton.YesNo,
            MessageBoxImage.Question,
            MessageBoxResult.No);
        if (confirmation != MessageBoxResult.Yes)
        {
            SetAiAssistantOutput(
                "EXACT LEGACY COVERAGE BINDING CANCELLED\r\n" +
                "=======================================\r\n" +
                $"Unique exact candidates: {candidates.Count:N0}\r\n" +
                $"Unmatched or ambiguous retained unchanged: {unmatched:N0}\r\n\r\n" +
                "No coverage data was changed.");
            return;
        }

        foreach (var candidate in candidates)
        {
            candidate.Entry.CollectionId = candidate.Collection.Id;
            candidate.Entry.MaterialKey = candidate.Material.MaterialKey;
        }

        SaveAiCoverageEntries(entries);
        RefreshAiCoverageIdentityStatus();
        SetAiAssistantOutput(
            "EXACT LEGACY COVERAGE BINDING COMPLETE\r\n" +
            "======================================\r\n" +
            $"Bound exact entries: {candidates.Count:N0}\r\n" +
            $"Unmatched or ambiguous retained unchanged: {unmatched:N0}\r\n\r\n" +
            "Legacy title and label snapshots were preserved for compatibility.");
    }

    private void GenerateCollectionDashboard_Click(object sender, RoutedEventArgs e)
    {
        SetAiAssistantOutput(BuildCollectionDashboardBrief());
    }

    private void MarkCollectionPublished_Click(object sender, RoutedEventArgs e)
    {
        var collection = GetSelectedAiMaterialCollection();
        if (collection is null)
        {
            MessageBox.Show("Select a collection first.", "Coverage Tracking", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }

        ApplyStatusToCollection(collection, "Published");
        SetAiAssistantOutput(BuildCollectionDashboardBrief());
    }

    private void ClearCollectionCoverage_Click(object sender, RoutedEventArgs e)
    {
        var collection = GetSelectedAiMaterialCollection();
        if (collection is null)
        {
            MessageBox.Show("Select a collection first.", "Coverage Tracking", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }

        var result = MessageBox.Show(
            $"Clear all saved workflow/coverage statuses for the selected AI collection '{collection.Title}'?\n\n" +
            "This does not delete the collection, remove materials, or change the Materials tab filter.",
            "Clear Selected Collection Status",
            MessageBoxButton.YesNo,
            MessageBoxImage.Question);
        if (result != MessageBoxResult.Yes)
        {
            return;
        }

        var entries = LoadAiCoverageEntries();
        entries.RemoveAll(item => AiCoverageBelongsToCollection(item, collection));
        SaveAiCoverageEntries(entries);
        RefreshAiCoverageIdentityStatus();
        SetAiAssistantOutput(BuildCollectionDashboardBrief());
    }

private List<string> GetVisibleAiMaterialLabels()
    {
        var labels = new List<string>();

        foreach (var row in GetCanonicalVisibleMaterialRows())
        {
            var materialId = AiCellValue(row, "Material ID", "MaterialID", "ID");
            var manufacturer = AiCellValue(row, "Manufacturer", "Brand");
            var productLine = AiCellValue(row, "Product Line", "ProductLine", "Series");
            var marketingName = AiCellValue(row, "Marketing Name", "Material Name", "Name");
            var baseMaterial = AiCellValue(row, "Base Material", "Material Type", "Type");
            var variant = AiCellValue(row, "Variant / Finish", "Variant", "Finish");
            var reinforcement = AiCellValue(row, "Reinforcement", "Reinforment", "Filled");
            var color = AiCellValue(row, "Color");

            var label = JoinNonEmpty(" ", manufacturer, productLine, marketingName, baseMaterial, variant, reinforcement, color);

            if (string.IsNullOrWhiteSpace(label))
            {
                label = JoinNonEmpty(" ", manufacturer, productLine, baseMaterial, color);
            }

            if (!string.IsNullOrWhiteSpace(materialId))
            {
                label = $"{materialId} — {label}";
            }

            if (!string.IsNullOrWhiteSpace(label))
            {
                labels.Add(label.Trim());
            }
        }

        return labels;
    }


    private string GetSelectedAiMaterialStatus()
    {
        if (FindName("AiMaterialStatusCombo") is ComboBox comboBox)
        {
            if (comboBox.SelectedItem is ComboBoxItem item)
            {
                return item.Content?.ToString()?.Trim() ?? "Published";
            }

            var value = comboBox.SelectedItem?.ToString()?.Trim();
            if (!string.IsNullOrWhiteSpace(value))
            {
                return value;
            }
        }

        return "Published";
    }

    private void ApplyCollectionStatus_Click(object sender, RoutedEventArgs e)
    {
        var collection = GetSelectedAiMaterialCollection();
        if (collection is null)
        {
            MessageBox.Show("Select a collection first.", "Material Status Tracking", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }

        var status = GetSelectedAiMaterialStatus();
        ApplyStatusToCollection(collection, status);
        SetAiAssistantOutput(BuildCollectionDashboardBrief());
    }

    private void ApplyStatusToCollection(AiMaterialCollection collection, string status)
    {
        var materials = GetAiCollectionMaterials(collection);
        if (materials.Count == 0)
        {
            MessageBox.Show("The selected collection has no stored materials.", "Material Status Tracking", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }

        var entries = LoadAiCoverageEntries();

        foreach (var material in materials)
        {
            var entry = entries.FirstOrDefault(item =>
                HasStableAiCoverageIdentity(item) &&
                string.Equals(item.CollectionId, collection.Id, StringComparison.OrdinalIgnoreCase) &&
                string.Equals(item.MaterialKey, material.MaterialKey, StringComparison.OrdinalIgnoreCase));
            if (entry is null &&
                materials.Count(item =>
                    string.Equals(item.MaterialLabel, material.MaterialLabel, StringComparison.OrdinalIgnoreCase)) == 1)
            {
                entry = entries.FirstOrDefault(item =>
                    !HasStableAiCoverageIdentity(item) &&
                    string.Equals(item.CollectionTitle, collection.Title, StringComparison.OrdinalIgnoreCase) &&
                    string.Equals(item.MaterialLabel, material.MaterialLabel, StringComparison.OrdinalIgnoreCase));
            }

            if (entry is null)
            {
                entry = new AiCoverageEntry
                {
                    CollectionId = collection.Id,
                    MaterialKey = material.MaterialKey,
                    CollectionTitle = collection.Title,
                    MaterialLabel = material.MaterialLabel
                };
                entries.Add(entry);
            }
            else
            {
                entry.CollectionId = collection.Id;
                entry.MaterialKey = material.MaterialKey;
                entry.CollectionTitle = collection.Title;
                entry.MaterialLabel = material.MaterialLabel;
            }

            entry.Status = status;
            entry.UpdatedUtc = DateTime.UtcNow.ToString("O");
        }

        SaveAiCoverageEntries(entries);
        RefreshAiCoverageIdentityStatus();
    }



    private void GenerateVideoPipelineDashboard_Click(object sender, RoutedEventArgs e)
    {
        SetAiAssistantOutput(BuildVideoPipelineDashboardBrief());
    }

    private string BuildVideoPipelineDashboardBrief()
    {
        var collections = LoadAiMaterialCollections();
        var coverageEntries = LoadAiCoverageEntries();

        var statusOrder = new[] { "Open", "Untested", "Tested", "Video Planned", "Filmed", "Edited", "Published" };
        var globalStatusCounts = statusOrder.ToDictionary(status => status, _ => 0, StringComparer.OrdinalIgnoreCase);
        var collectionSummaries = new List<string>();
        var nextActions = new List<string>();

        var totalRows = 0;
        var totalPublished = 0;

        foreach (var collection in collections.OrderBy(item => item.Title))
        {
            var materials = GetAiCollectionMaterials(collection);

            if (materials.Count == 0)
            {
                continue;
            }

            totalRows += materials.Count;

            string StatusFor(AiCollectionMaterialIdentity material)
            {
                return AiCoverageStatusFor(coverageEntries, collection, material);
            }

            var statusCounts = materials
                .Select(StatusFor)
                .GroupBy(status => status)
                .ToDictionary(group => group.Key, group => group.Count(), StringComparer.OrdinalIgnoreCase);

            foreach (var status in statusOrder)
            {
                if (statusCounts.TryGetValue(status, out var count))
                {
                    globalStatusCounts[status] += count;
                }
            }

            foreach (var status in statusCounts.Keys)
            {
                if (!globalStatusCounts.ContainsKey(status))
                {
                    globalStatusCounts[status] = statusCounts[status];
                }
            }

            var published = materials.Count(material =>
                string.Equals(StatusFor(material), "Published", StringComparison.OrdinalIgnoreCase));
            totalPublished += published;
            var remaining = materials.Count - published;
            var percent = materials.Count == 0 ? 0 : Math.Round((double)published / materials.Count * 100, 1);

            collectionSummaries.Add($"{collection.Title}: {published}/{materials.Count} published ({percent}%)");

            var recommendedStatus = PickPipelineNextStatus(statusCounts);
            if (!string.IsNullOrWhiteSpace(recommendedStatus))
            {
                nextActions.Add($"{collection.Title}: {BuildPipelineActionText(recommendedStatus, statusCounts[recommendedStatus])}");
            }
            else if (remaining == 0)
            {
                nextActions.Add($"{collection.Title}: complete");
            }
        }

        var totalCoverage = totalRows == 0 ? 0 : Math.Round((double)totalPublished / totalRows * 100, 1);

        var lines = new List<string>
        {
            "VIDEO PIPELINE DASHBOARD",
            "========================",
            $"Collections: {collections.Count}",
            $"Tracked material rows: {totalRows}",
            $"Published / completed: {totalPublished}",
            $"Remaining: {Math.Max(0, totalRows - totalPublished)}",
            $"Overall coverage: {totalCoverage}%",
            "",
            "PIPELINE STATUS SUMMARY",
            "-----------------------"
        };

        foreach (var status in statusOrder)
        {
            if (globalStatusCounts.TryGetValue(status, out var count) && count > 0)
            {
                lines.Add($"{status}: {count}");
            }
        }

        foreach (var status in globalStatusCounts.Keys.OrderBy(item => item))
        {
            if (!statusOrder.Contains(status, StringComparer.OrdinalIgnoreCase) && globalStatusCounts[status] > 0)
            {
                lines.Add($"{status}: {globalStatusCounts[status]}");
            }
        }

        lines.Add("");
        lines.Add("NEXT BEST ACTIONS");
        lines.Add("-----------------");

        if (nextActions.Count == 0)
        {
            lines.Add("No tracked collections found yet. Create collections, apply statuses, then run this dashboard again.");
        }
        else
        {
            foreach (var action in nextActions.Take(20))
            {
                lines.Add("- " + action);
            }
        }

        lines.Add("");
        lines.Add("COLLECTION PROGRESS");
        lines.Add("-------------------");

        if (collectionSummaries.Count == 0)
        {
            lines.Add("No material collections found.");
        }
        else
        {
            foreach (var summary in collectionSummaries)
            {
                lines.Add("- " + summary);
            }
        }

        lines.Add("");
        lines.Add("HOW TO USE THIS");
        lines.Add("---------------");
        lines.Add("Use Material Status Tracking in each collection to move materials through Tested, Video Planned, Filmed, Edited and Published.");
        lines.Add("Run this dashboard to see the full YouTube production pipeline across all saved collections.");

        return string.Join("\r\n", lines);
    }

    private string PickPipelineNextStatus(Dictionary<string, int> statusCounts)
    {
        var priority = new[] { "Edited", "Filmed", "Video Planned", "Tested", "Untested", "Open" };

        foreach (var status in priority)
        {
            if (statusCounts.TryGetValue(status, out var count) && count > 0)
            {
                return status;
            }
        }

        return string.Empty;
    }

    private string BuildPipelineActionText(string status, int count)
    {
        return status switch
        {
            "Edited" => $"{count} edited item(s) ready to publish",
            "Filmed" => $"{count} filmed item(s) ready for editing",
            "Video Planned" => $"{count} planned item(s) ready to film",
            "Tested" => $"{count} tested item(s) ready for video planning",
            "Untested" => $"{count} untested item(s) need testing before content planning",
            "Open" => $"{count} open item(s) need a workflow status",
            _ => $"{count} item(s) at status {status}"
        };
    }


    private string BuildCollectionDashboardBrief()
    {
        var collection = GetSelectedAiMaterialCollection();
        if (collection is null)
        {
            return "COLLECTION DASHBOARD\r\n\r\nSelect a material collection first. The Collections dropdown must contain a saved collection.";
        }

        var materials = GetAiCollectionMaterials(collection);
        var coverage = LoadAiCoverageEntries();

        string StatusFor(AiCollectionMaterialIdentity material)
        {
            return AiCoverageStatusFor(coverage, collection, material);
        }

        var published = materials.Count(material =>
            string.Equals(StatusFor(material), "Published", StringComparison.OrdinalIgnoreCase));
        var remaining = Math.Max(0, materials.Count - published);
        var percent = materials.Count == 0 ? 0 : Math.Round((double)published / materials.Count * 100, 1);

        var statusOrder = new[] { "Open", "Untested", "Tested", "Video Planned", "Filmed", "Edited", "Published" };
        var statusCounts = materials
            .Select(StatusFor)
            .GroupBy(status => status)
            .ToDictionary(group => group.Key, group => group.Count(), StringComparer.OrdinalIgnoreCase);

        var lines = new List<string>
        {
            "COLLECTION DASHBOARD",
            "====================",
            $"Collection: {collection.Title}",
            $"Collection ID: {collection.Id}",
            $"Materials: {materials.Count}",
            $"Published / completed: {published}",
            $"Remaining: {remaining}",
            $"Coverage: {percent}%",
            "",
            "STATUS BREAKDOWN",
            "----------------"
        };

        foreach (var status in statusOrder)
        {
            if (statusCounts.TryGetValue(status, out var count) && count > 0)
            {
                lines.Add($"{status}: {count}");
            }
        }

        foreach (var status in statusCounts.Keys.OrderBy(item => item))
        {
            if (!statusOrder.Contains(status, StringComparer.OrdinalIgnoreCase))
            {
                lines.Add($"{status}: {statusCounts[status]}");
            }
        }

        lines.Add("");
        lines.Add("NEXT ACTION");
        lines.Add("-----------");
        lines.Add(remaining > 0
            ? "Use Material status + Apply Status to update the workflow stage for this collection."
            : "This collection is fully marked as published/completed.");

        lines.Add("");
        lines.Add("MATERIAL STATUS");
        lines.Add("---------------");
        lines.Add($"Showing {materials.Count} of {materials.Count} saved material rows.");
        lines.Add("");

        for (var index = 0; index < materials.Count; index++)
        {
            var material = materials[index];
            lines.Add($"{index + 1:00}. [{StatusFor(material)}] {material.MaterialLabel}");
        }

        lines.Add("");
        lines.Add("BUTTONS");
        lines.Add("-------");
        lines.Add("Apply Status marks every saved material row in the selected collection with the selected status.");
        lines.Add("Mark Collection Published marks every saved material row in the selected collection as Published.");
        lines.Add("Clear Selected Collection Status removes only the saved workflow/coverage statuses for the selected AI collection. It does not delete materials or affect Materials tab filters.");

        return string.Join("\r\n", lines);
    }

    private string BuildMaterialIntelligenceBrief(string mode)
    {
        var sourceRows = GetAiMaterialIntelligenceRows();

        if (sourceRows.Count == 0)
        {
            return "MATERIAL INTELLIGENCE\r\n\r\nNo materials are available for the selected scope. Load materials, clear filters or choose another collection.";
        }

        var rows = sourceRows
            .Take(250)
            .ToList();

        var insights = rows
            .Select(row => BuildAiMaterialInsight(row))
            .Where(item => !string.IsNullOrWhiteSpace(item.Label))
            .OrderByDescending(item => item.Score)
            .ThenBy(item => item.Label)
            .ToList();

        var lines = new List<string>
        {
            "MATERIAL INTELLIGENCE",
            "=====================",
            $"Mode: {mode}",
            $"Visible source materials: {sourceRows.Count}",
            $"Materials processed: {rows.Count}",
            $"Materials omitted by the 250-material analysis limit: {sourceRows.Count - rows.Count}",
            $"Scope: {GetAiMaterialIntelligenceScopeLabel()}",
            "",
            "HOW TO USE THIS",
            "---------------",
            "Apply filters/search first if you want recommendations for one manufacturer, material family or video batch.",
            "Then generate this again and save the result as a research session."
        };

        if (mode == "next-video")
        {
            lines.Add("");
            lines.Add("RECOMMENDED NEXT VIDEO");
            lines.Add("----------------------");

            foreach (var item in insights.Take(8))
            {
                lines.Add("- " + item.Label);
                lines.Add("  Angle: " + item.Reason);
                lines.Add("  Suggested title: " + BuildAiSuggestedVideoTitle(item));
            }
        }
        else if (mode == "comparisons")
        {
            lines.Add("");
            lines.Add("RECOMMENDED COMPARISONS");
            lines.Add("-----------------------");

            var comparisons = BuildAiComparisonIdeas(insights);
            if (comparisons.Count == 0)
            {
                lines.Add("No strong comparison groups were found in the current visible rows.");
                lines.Add("Try filtering by a manufacturer or base material with both reinforced and standard variants.");
            }
            else
            {
                foreach (var comparison in comparisons.Take(12))
                {
                    lines.Add("- " + comparison);
                }
            }
        }
        else if (mode == "hidden-gems")
        {
            lines.Add("");
            lines.Add("HIDDEN GEM CANDIDATES");
            lines.Add("---------------------");

            var hiddenGems = insights
                .Where(item => item.Score >= 40)
                .OrderBy(item => CountAiManufacturerMaterials(insights, item.Manufacturer))
                .ThenByDescending(item => item.Score)
                .Take(10)
                .ToList();

            foreach (var item in hiddenGems)
            {
                lines.Add("- " + item.Label);
                lines.Add("  Why it may be worth a video: " + item.Reason);
            }
        }
        else
        {
            lines.Add("");
            lines.Add("TOP MATERIAL OPPORTUNITIES");
            lines.Add("--------------------------");
            foreach (var item in insights.Take(10))
            {
                lines.Add("- " + item.Label + " — " + item.Reason);
            }
        }

        lines.Add("");
        lines.Add("SAVE THIS");
        lines.Add("---------");
        lines.Add("Use Save Session to store this recommendation set with the current prompt, output and visible database context.");

        return string.Join("\r\n", lines);
    }

    private AiMaterialInsight BuildAiMaterialInsight(DataRow row)
    {
        var manufacturer = AiCellValue(row, "Manufacturer", "Brand");
        var productLine = AiCellValue(row, "Product Line", "ProductLine", "Series");
        var marketingName = AiCellValue(row, "Marketing Name", "Material Name", "Name");
        var baseMaterial = AiCellValue(row, "Base Material", "Material Type", "Type");
        var reinforcement = AiCellValue(row, "Reinforcement", "Reinforment", "Filled");
        var category = AiCellValue(row, "Material Category", "Category");
        var color = AiCellValue(row, "Color");

        var label = JoinNonEmpty(" ", manufacturer, productLine, marketingName, baseMaterial, reinforcement);
        if (string.IsNullOrWhiteSpace(label))
        {
            label = JoinNonEmpty(" ", manufacturer, baseMaterial, color);
        }

        var score = 0.0;
        var reasonParts = new List<string>();

        var numericScore = AiBestNumericValue(row,
            "Overall Score",
            "Total Score",
            "Engineering Score",
            "Performance Score",
            "Ranking Score",
            "Score",
            "Rating");

        if (numericScore > 0)
        {
            score += Math.Min(numericScore, 100);
            reasonParts.Add("has a usable score signal");
        }

        if (!string.IsNullOrWhiteSpace(reinforcement) && reinforcement != "—")
        {
            score += 30;
            reasonParts.Add("reinforced material angle");
        }

        if (string.Equals(category, "Engineering", StringComparison.OrdinalIgnoreCase))
        {
            score += 20;
            reasonParts.Add("engineering material");
        }

        if (!string.IsNullOrWhiteSpace(baseMaterial) && baseMaterial != "—")
        {
            if (baseMaterial.Contains("ASA", StringComparison.OrdinalIgnoreCase) ||
                baseMaterial.Contains("ABS", StringComparison.OrdinalIgnoreCase) ||
                baseMaterial.Contains("PC", StringComparison.OrdinalIgnoreCase) ||
                baseMaterial.Contains("PA", StringComparison.OrdinalIgnoreCase) ||
                baseMaterial.Contains("PETG", StringComparison.OrdinalIgnoreCase))
            {
                score += 15;
                reasonParts.Add("practical buyer interest");
            }
        }

        if (!string.IsNullOrWhiteSpace(marketingName) && marketingName != "—")
        {
            score += 5;
        }

        if (reasonParts.Count == 0)
        {
            reasonParts.Add("visible in the current filtered material set");
        }

        return new AiMaterialInsight
        {
            Label = label,
            Manufacturer = manufacturer,
            ProductLine = productLine,
            BaseMaterial = baseMaterial,
            Reinforcement = reinforcement,
            Category = category,
            Score = score,
            Reason = string.Join(", ", reasonParts)
        };
    }

    private List<string> BuildAiComparisonIdeas(List<AiMaterialInsight> insights)
    {
        var ideas = new List<string>();

        foreach (var group in insights
            .Where(item => !string.IsNullOrWhiteSpace(item.Manufacturer) && !string.IsNullOrWhiteSpace(item.BaseMaterial))
            .GroupBy(item => item.Manufacturer + "|" + item.BaseMaterial)
            .OrderByDescending(group => group.Count()))
        {
            var items = group.ToList();
            if (items.Count < 2)
            {
                continue;
            }

            var standard = items.FirstOrDefault(item => string.IsNullOrWhiteSpace(item.Reinforcement) || item.Reinforcement == "—");
            var reinforced = items.FirstOrDefault(item => !string.IsNullOrWhiteSpace(item.Reinforcement) && item.Reinforcement != "—");

            if (standard is not null && reinforced is not null)
            {
                ideas.Add($"{reinforced.Manufacturer} {reinforced.BaseMaterial}: reinforced vs standard — {reinforced.Label} vs {standard.Label}");
            }

            var cf = items.FirstOrDefault(item => item.Reinforcement.Contains("CF", StringComparison.OrdinalIgnoreCase));
            var gf = items.FirstOrDefault(item => item.Reinforcement.Contains("GF", StringComparison.OrdinalIgnoreCase));
            if (cf is not null && gf is not null)
            {
                ideas.Add($"{cf.Manufacturer} {cf.BaseMaterial}: CF vs GF — {cf.Label} vs {gf.Label}");
            }
        }

        return ideas.Distinct().ToList();
    }

    private string BuildAiSuggestedVideoTitle(AiMaterialInsight item)
    {
        if (!string.IsNullOrWhiteSpace(item.Reinforcement) && item.Reinforcement != "—")
        {
            return $"{item.BaseMaterial} {item.Reinforcement} Tested – Is It Worth the Upgrade? | {item.Manufacturer}";
        }

        if (string.Equals(item.Category, "Engineering", StringComparison.OrdinalIgnoreCase))
        {
            return $"Is This Engineering Filament Actually Practical? | {item.Manufacturer} {item.BaseMaterial}";
        }

        return $"Should You Print With This Filament? | {item.Manufacturer} {item.BaseMaterial}";
    }

    private int CountAiManufacturerMaterials(List<AiMaterialInsight> insights, string manufacturer)
    {
        return insights.Count(item => string.Equals(item.Manufacturer, manufacturer, StringComparison.OrdinalIgnoreCase));
    }

    private string AiCellValue(DataRow row, params string[] names)
    {
        foreach (var name in names)
        {
            if (row.Table.Columns.Contains(name))
            {
                var value = row[name]?.ToString()?.Trim();
                if (!string.IsNullOrWhiteSpace(value))
                {
                    return value;
                }
            }
        }

        return "";
    }

    private double AiBestNumericValue(DataRow row, params string[] names)
    {
        foreach (var name in names)
        {
            if (!row.Table.Columns.Contains(name))
            {
                continue;
            }

            var text = row[name]?.ToString();
            if (string.IsNullOrWhiteSpace(text))
            {
                continue;
            }

            text = text.Replace("%", "").Trim();

            if (double.TryParse(text, NumberStyles.Any, CultureInfo.InvariantCulture, out var invariantValue))
            {
                return invariantValue;
            }

            if (double.TryParse(text, NumberStyles.Any, CultureInfo.CurrentCulture, out var currentValue))
            {
                return currentValue;
            }
        }

        return 0;
    }

    private string BuildAiAssistantBrief(string mode)
    {
        var visibleRows = GetCanonicalVisibleMaterialRows();
        if (visibleRows.Count == 0)
        {
            return "AI Assistant\n\nNo visible materials are loaded. Load Materials data or clear filters and try again.";
        }

        var rows = visibleRows
            .Take(60)
            .ToList();

        string Value(DataRow row, params string[] names) => DisplayOrDash(DataTableHelpers.FirstValue(row, names));

        var manufacturers = rows
            .Select(row => Value(row, "Manufacturer", "Brand"))
            .Where(value => value != "—")
            .GroupBy(value => value)
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key)
            .Take(6)
            .Select(group => $"{group.Key} ({group.Count()})")
            .ToList();

        var materialTypes = rows
            .Select(row => Value(row, "Base Material", "Type", "Material Type"))
            .Where(value => value != "—")
            .GroupBy(value => value)
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key)
            .Take(8)
            .Select(group => $"{group.Key} ({group.Count()})")
            .ToList();

        var reinforced = rows
            .Where(row => Value(row, "Reinforcement", "Reinforment") != "—")
            .Take(8)
            .Select(row => "- " + JoinNonEmpty(" ", Value(row, "Manufacturer", "Brand"), Value(row, "Product Line"), Value(row, "Base Material", "Type", "Material Type"), Value(row, "Reinforcement", "Reinforment")))
            .ToList();

        var sampleMaterials = rows
            .Take(8)
            .Select(row => "- " + JoinNonEmpty(" ", Value(row, "Manufacturer", "Brand"), Value(row, "Product Line"), Value(row, "Marketing Name"), Value(row, "Base Material", "Type", "Material Type"), Value(row, "Reinforcement", "Reinforment")))
            .ToList();

        var promptText = GetTextBoxText("AiPromptEditorBox").Trim();
        var videoIdeas = new List<string>
        {
            "- Best engineering filaments in the current filtered database",
            "- CF vs GF: which reinforcement actually makes sense?",
            "- Standard vs reinforced: when is the upgrade worth it?",
            "- Hidden gems from the current material list",
            "- Manufacturer showdown based on tested materials"
        };

        var comparisonIdeas = new List<string>
        {
            "- Compare reinforced and non-reinforced variants inside the same base material",
            "- Compare CF and GF materials from the same manufacturer where possible",
            "- Compare ASA vs ABS for practical outdoor and engineering use",
            "- Compare PLA specialty materials by use case rather than only raw score",
            "- Build a shortlist from the current filters and compare them in one video"
        };

        var lines = new List<string>
        {
            "LOCAL RULE-BASED AI ASSISTANT",
            "=============================",
            $"Mode: {mode}",
            $"Template: {GetSelectedAiTemplateName()}",
            $"Visible source materials: {visibleRows.Count}",
            $"Materials processed: {rows.Count}",
            $"Materials omitted by the 60-material local brief limit: {visibleRows.Count - rows.Count}",
            "",
            "PLANNING NOTE (REFERENCE ONLY)",
            "------------------------------",
            string.IsNullOrWhiteSpace(promptText) ? "No planning note entered." : promptText,
            "",
            "DATABASE CONTEXT",
            "----------------",
            "Top manufacturers: " + (manufacturers.Count > 0 ? string.Join(", ", manufacturers) : "N/A"),
            "Top material types: " + (materialTypes.Count > 0 ? string.Join(", ", materialTypes) : "N/A"),
            "",
            "SAMPLE MATERIALS",
            "----------------",
            sampleMaterials.Count > 0 ? string.Join("\r\n", sampleMaterials) : "No sample materials found."
        };

        if (mode is "video" or "full")
        {
            lines.Add("");
            lines.Add("VIDEO IDEAS");
            lines.Add("-----------");
            lines.AddRange(videoIdeas);
            lines.Add("");
            lines.Add("THUMBNAIL HOOKS");
            lines.Add("---------------");
            lines.Add("- BEAST OR BUST?");
            lines.Add("- CF VS GF");
            lines.Add("- WORTH THE UPGRADE?");
            lines.Add("- BEST ENGINEERING FILAMENT?");
            lines.Add("- HIDDEN GEM?");
        }

        if (mode is "comparison" or "full")
        {
            lines.Add("");
            lines.Add("COMPARISON IDEAS");
            lines.Add("----------------");
            lines.AddRange(comparisonIdeas);
            lines.Add("");
            lines.Add("REINFORCED CANDIDATES");
            lines.Add("---------------------");
            lines.Add(reinforced.Count > 0 ? string.Join("\r\n", reinforced) : "No reinforced materials are visible with the current filters.");
        }

        if (mode is "thumbnail" or "playlist" or "full")
        {
            lines.Add("");
            lines.Add(mode == "playlist" ? "PLAYLIST SUGGESTIONS" : "ADDITIONAL TEMPLATE OUTPUT");
            lines.Add("--------------------------");
            lines.Add("- Group by manufacturer when planning a review series.");
            lines.Add("- Group by base material when viewers need buying guidance.");
            lines.Add("- Group reinforced materials into engineering-focused episodes.");
            lines.Add("- Use short thumbnail text that highlights the decision or conflict.");
        }

        lines.Add("");
        lines.Add("NEXT ACTION");
        lines.Add("-----------");
        lines.Add("Use filters/search first, then regenerate this brief to focus the assistant on a manufacturer, material family or video batch. Save the session when the prompt and output are useful.");

        return string.Join("\r\n", lines);
    }

    

    

    

    


