    {
        public long BaseMaterialId { get; set; }
        public string BaseMaterial { get; set; } = "";
        public string Category { get; set; } = "";
        public string SortOrder { get; set; } = "";
        public string NozzleTemperatureMinC { get; set; } = "";
        public string NozzleTemperatureRecommendedC { get; set; } = "";
        public string NozzleTemperatureMaxC { get; set; } = "";
        public string BedTemperatureMinC { get; set; } = "";
        public string BedTemperatureRecommendedC { get; set; } = "";
        public string BedTemperatureMaxC { get; set; } = "";
        public string PrintSpeedMinMmPerS { get; set; } = "";
        public string PrintSpeedRecommendedMmPerS { get; set; } = "";
        public string PrintSpeedMaxMmPerS { get; set; } = "";
        public string CoolingMinPercent { get; set; } = "";
        public string CoolingRecommendedPercent { get; set; } = "";
        public string CoolingMaxPercent { get; set; } = "";
