    private sealed class NativeSettingsState
    {
        public List<NativeSettingRow> Settings { get; set; } = new();
        public List<NativeBaseMaterialRow> BaseMaterials { get; set; } = new();
    }

    private readonly ObservableCollection<NativeSettingRow> _nativeSettingsRows = new();
    private readonly ObservableCollection<NativeBaseMaterialRow> _nativeBaseMaterialRows = new();

    private void InitializeNativeSettingsManager()
    {
        LoadBuiltInNativeSettingsDefaults();
        LoadCanonicalNativeSettings();
        EnsurePricingSettings();
        LoadDeploymentSettingsIntoManager();
        var canonicalBaseMaterials = _database.LoadBaseMaterialCatalog();
        if (canonicalBaseMaterials.Count == 0)
        {
            // One-time backwards-compatible migration. Printing values formerly entered
            // per MaterialID are intentionally not migrated: they were test data only.
            var legacyPath = NativeSettingsFilePath();
            if (System.IO.File.Exists(legacyPath))
            {
                try
                {
                    var legacy = JsonSerializer.Deserialize<NativeSettingsState>(System.IO.File.ReadAllText(legacyPath));
                    if (legacy?.BaseMaterials.Count > 0)
                    {
                        _nativeBaseMaterialRows.Clear();
                        foreach (var row in legacy.BaseMaterials) _nativeBaseMaterialRows.Add(row);
                    }
                }
                catch { /* Invalid legacy JSON must not prevent safe default seeding. */ }
            }
            SaveBaseMaterialCatalogToDatabase();
        }
        else
        {
            _nativeBaseMaterialRows.Clear();
            foreach (var row in canonicalBaseMaterials) _nativeBaseMaterialRows.Add(FromBaseMaterialRecord(row));
        }
        EnsurePurchasingCurrencySettings();
        RefreshFtpsEndpointSummary();
    }

    private void LoadCanonicalNativeSettings()
    {
        var canonical = _database.LoadNativeSettingsRows();
        if (canonical.Count == 0)
        {
            var legacyPath = NativeSettingsFilePath();
            if (System.IO.File.Exists(legacyPath))
            {
                try
                {
                    var legacy = JsonSerializer.Deserialize<NativeSettingsState>(System.IO.File.ReadAllText(legacyPath));
                    if (legacy?.Settings.Count > 0)
                    {
                        _nativeSettingsRows.Clear();
                        foreach (var row in legacy.Settings.Where(row => !string.Equals(row.Section, "Deployment", StringComparison.OrdinalIgnoreCase))) _nativeSettingsRows.Add(row);
                    }
                }
                catch { /* Invalid legacy snapshot falls back to governed defaults. */ }
            }
            SaveCanonicalNativeSettings();
            return;
        }
        _nativeSettingsRows.Clear();
        foreach (var row in canonical) _nativeSettingsRows.Add(new NativeSettingRow { Section=row.Section, Parameter=row.Parameter, Value=row.Value, Unit=row.Unit, UsedBy=row.UsedBy, Notes=row.Notes });
    }

    private void SaveCanonicalNativeSettings() => _database.ReplaceNativeSettingsRows(
        _nativeSettingsRows.Where(row => !string.Equals(row.Section, "Deployment", StringComparison.OrdinalIgnoreCase)).Select(row => new NativeSettingRecord
        { Section=row.Section, Parameter=row.Parameter, Value=row.Value, Unit=row.Unit, UsedBy=row.UsedBy, Notes=row.Notes }));

    private void LoadDeploymentSettingsIntoManager()
    {
        foreach (var old in _nativeSettingsRows.Where(row => string.Equals(row.Section, "Deployment", StringComparison.OrdinalIgnoreCase)).ToList())
            _nativeSettingsRows.Remove(old);
        var settings = _database.LoadDeploymentSettings();
        _nativeSettingsRows.Add(new NativeSettingRow { Section = "Deployment", Parameter = "FTPS host", Value = settings.FtpsHost, Unit = "host", UsedBy = "FTPS Publishing", Notes = "SQLite-canonical endpoint; password stays in Windows Credential Manager" });
        _nativeSettingsRows.Add(new NativeSettingRow { Section = "Deployment", Parameter = "FTPS port", Value = settings.FtpsPort.ToString(CultureInfo.InvariantCulture), Unit = "port", UsedBy = "FTPS Publishing", Notes = "Explicit TLS control port" });
        _nativeSettingsRows.Add(new NativeSettingRow { Section = "Deployment", Parameter = "FTPS username", Value = settings.FtpsUserName, Unit = "user", UsedBy = "FTPS Publishing", Notes = "Credential key is scoped to host and username" });
    }

    private DeploymentSettingsRecord GetDeploymentSettingsFromManager()
    {
        string Value(string parameter) => _nativeSettingsRows.FirstOrDefault(row =>
            string.Equals(row.Section, "Deployment", StringComparison.OrdinalIgnoreCase) &&
            string.Equals(row.Parameter, parameter, StringComparison.OrdinalIgnoreCase))?.Value?.Trim() ?? string.Empty;
        var host = Value("FTPS host");
        var user = Value("FTPS username");
        if (string.IsNullOrWhiteSpace(host)) throw new InvalidOperationException("FTPS host is required in Settings Manager.");
        if (Uri.CheckHostName(host) == UriHostNameType.Unknown) throw new InvalidOperationException("FTPS host is not a valid DNS name or IP address.");
        if (!int.TryParse(Value("FTPS port"), NumberStyles.None, CultureInfo.InvariantCulture, out var port) || port is < 1 or > 65535)
            throw new InvalidOperationException("FTPS port must be a whole number between 1 and 65535.");
        if (string.IsNullOrWhiteSpace(user)) throw new InvalidOperationException("FTPS username is required in Settings Manager.");
        return new DeploymentSettingsRecord { FtpsHost = host, FtpsPort = port, FtpsUserName = user };
    }

    private void SaveDeploymentSettingsFromManager()
    {
        var settings = GetDeploymentSettingsFromManager();
        _database.SaveDeploymentSettings(settings);
        RefreshFtpsEndpointSummary(settings);
    }

    private void RefreshFtpsEndpointSummary(DeploymentSettingsRecord? settings = null)
    {
        settings ??= _database.LoadDeploymentSettings();
        if (FindName("FtpsEndpointSummaryText") is TextBlock text)
            text.Text = $"{settings.FtpsUserName}@{settings.FtpsHost}:{settings.FtpsPort} · Explicit TLS · Passive";
    }

    private static NativeBaseMaterialRow FromBaseMaterialRecord(BaseMaterialCatalogRecord row) => new()
    {
        BaseMaterialId = row.BaseMaterialId, BaseMaterial = row.BaseMaterial, Category = row.Category, SortOrder = row.SortOrder,
        NozzleTemperatureMinC = row.NozzleTemperatureMinC, NozzleTemperatureRecommendedC = row.NozzleTemperatureRecommendedC, NozzleTemperatureMaxC = row.NozzleTemperatureMaxC,
        BedTemperatureMinC = row.BedTemperatureMinC, BedTemperatureRecommendedC = row.BedTemperatureRecommendedC, BedTemperatureMaxC = row.BedTemperatureMaxC,
        PrintSpeedMinMmPerS = row.PrintSpeedMinMmPerS, PrintSpeedRecommendedMmPerS = row.PrintSpeedRecommendedMmPerS, PrintSpeedMaxMmPerS = row.PrintSpeedMaxMmPerS,
        CoolingMinPercent = row.CoolingMinPercent, CoolingRecommendedPercent = row.CoolingRecommendedPercent, CoolingMaxPercent = row.CoolingMaxPercent,
        CoolingGuidance = row.CoolingGuidance, DryingTemperatureC = row.DryingTemperatureC, DryingTimeHours = row.DryingTimeHours,
        EnclosureRequirement = row.EnclosureRequirement, PrinterProfileReference = row.PrinterProfileReference, SlicerProfileReference = row.SlicerProfileReference,
        ProfileId = row.ProfileId, ProfileKind = row.ProfileKind
    };

    private void SaveBaseMaterialCatalogToDatabase()
    {
        var nextId = Math.Max(
            1,
            _nativeBaseMaterialRows.Select(row => row.BaseMaterialId).DefaultIfEmpty().Max() + 1);
        foreach (var row in _nativeBaseMaterialRows.Where(row => row.BaseMaterialId <= 0))
            row.BaseMaterialId = nextId++;
        _database.ReplaceBaseMaterialCatalog(_nativeBaseMaterialRows.Select(row => new BaseMaterialCatalogRecord
    {
        BaseMaterialId = row.BaseMaterialId, BaseMaterial = row.BaseMaterial, Category = row.Category, SortOrder = row.SortOrder,
        NozzleTemperatureMinC = row.NozzleTemperatureMinC, NozzleTemperatureRecommendedC = row.NozzleTemperatureRecommendedC, NozzleTemperatureMaxC = row.NozzleTemperatureMaxC,
        BedTemperatureMinC = row.BedTemperatureMinC, BedTemperatureRecommendedC = row.BedTemperatureRecommendedC, BedTemperatureMaxC = row.BedTemperatureMaxC,
        PrintSpeedMinMmPerS = row.PrintSpeedMinMmPerS, PrintSpeedRecommendedMmPerS = row.PrintSpeedRecommendedMmPerS, PrintSpeedMaxMmPerS = row.PrintSpeedMaxMmPerS,
        CoolingMinPercent = row.CoolingMinPercent, CoolingRecommendedPercent = row.CoolingRecommendedPercent, CoolingMaxPercent = row.CoolingMaxPercent,
        CoolingGuidance = row.CoolingGuidance, DryingTemperatureC = row.DryingTemperatureC, DryingTimeHours = row.DryingTimeHours,
        EnclosureRequirement = row.EnclosureRequirement, PrinterProfileReference = row.PrinterProfileReference, SlicerProfileReference = row.SlicerProfileReference,
        ProfileId = row.ProfileId, ProfileKind = row.ProfileKind
    }));
    }

    private void EnsurePurchasingCurrencySettings()
    {
        var added = false;
        var defaults = GetDefaultNativeSettingsRows()
            .Where(r => string.Equals(r.Section, "Currency", StringComparison.OrdinalIgnoreCase) &&
                        (r.Parameter.StartsWith("ISK per 1 ", StringComparison.OrdinalIgnoreCase) ||
                         string.Equals(
                             r.Parameter,
                             "Default Landed Cost Currency",
                             StringComparison.OrdinalIgnoreCase)) &&
                        string.Equals(r.UsedBy, "Purchasing", StringComparison.OrdinalIgnoreCase));

        foreach (var defaultRow in defaults)
        {
            if (_nativeSettingsRows.Any(r => string.Equals(r.Section, defaultRow.Section, StringComparison.OrdinalIgnoreCase) &&
                                             string.Equals(r.Parameter, defaultRow.Parameter, StringComparison.OrdinalIgnoreCase) &&
                                             string.Equals(r.UsedBy, "Purchasing", StringComparison.OrdinalIgnoreCase)))
                continue;
            _nativeSettingsRows.Add(new NativeSettingRow
            {
                Section = defaultRow.Section,
                Parameter = defaultRow.Parameter,
                Value = defaultRow.Value,
                Unit = defaultRow.Unit,
                UsedBy = defaultRow.UsedBy,
                Notes = defaultRow.Notes
            });
            added = true;
        }
        if (added) SaveCanonicalNativeSettings();
    }

    private string NativeSettingsFilePath()
    {
        return StorageWorkingFilePath("native-settings-manager.json");
    }

    private void LoadBuiltInNativeSettingsDefaults()
    {
        _nativeSettingsRows.Clear();
        foreach (var row in GetDefaultNativeSettingsRows())
        {
            _nativeSettingsRows.Add(row);
        }

        _nativeBaseMaterialRows.Clear();
        foreach (var row in GetDefaultNativeBaseMaterialRows())
        {
            _nativeBaseMaterialRows.Add(row);
        }
    }

