    private void SaveNativeSettings_Click(object sender, RoutedEventArgs e)
    {
        SaveCanonicalNativeSettings();
        SaveDeploymentSettingsFromManager();
        SaveBaseMaterialCatalogToDatabase();
        MessageBox.Show("Settings saved. Base Material Catalog is canonical in SQLite.", "Settings Manager", MessageBoxButton.OK, MessageBoxImage.Information);
    }

    private void LoadNativeSettings_Click(object sender, RoutedEventArgs e)
    {
        var result = MessageBox.Show(
            this,
            "Reload saved General and Deployment settings from SQLite?\n\n" +
            "Current unsaved Settings edits will be discarded. The Base Material Catalog is unchanged.",
            "Reload Saved Settings?",
            MessageBoxButton.YesNo,
            MessageBoxImage.Question,
            MessageBoxResult.No);
        if (result != MessageBoxResult.Yes)
        {
            return;
        }

        LoadCanonicalNativeSettings();
        LoadDeploymentSettingsIntoManager();
        EnsurePurchasingCurrencySettings();
        RefreshPurchaseCurrencyChoices();

        // Base Material Catalog is intentionally not replaced from JSON. SQLite owns it.

        RefreshNativeInputModulesFromMaterialManager(markDirty: false);
        ApplyNativeMaterialComputedFieldsToAllRows();
        RefreshNativeMaterialGridValidation();
        RefreshFastSettingsViews();
        ShowTransientStatus("Saved General and Deployment settings reloaded; Base Material Catalog was unchanged.");
    }

    private void ResetNativeSettings_Click(object sender, RoutedEventArgs e)
    {
        var result = MessageBox.Show(this, "Restore general Settings Manager rows from the built-in defaults?\n\nCurrent unsaved general settings will be replaced. Deployment settings and the canonical Base Material Catalog remain separately owned.", "Restore Built-in Defaults?", MessageBoxButton.YesNo, MessageBoxImage.Warning, MessageBoxResult.No);
        if (result != MessageBoxResult.Yes)
        {
            return;
        }

        ReplaceNativeGeneralSettingsWithBuiltInDefaults();
        SaveCanonicalNativeSettings();
        RefreshNativeInputModulesFromMaterialManager(markDirty: false);
        RefreshPurchaseCurrencyChoices();
        ApplyNativeMaterialComputedFieldsToAllRows();
        RefreshNativeMaterialGridValidation();
        RefreshFastSettingsViews();
        ShowTransientStatus("Built-in General Settings restored and saved; Deployment Settings and Base Material Catalog were unchanged.");
    }

    private void ReplaceNativeGeneralSettingsWithBuiltInDefaults()
    {
        foreach (var row in _nativeSettingsRows
                     .Where(row => !string.Equals(row.Section, "Deployment", StringComparison.OrdinalIgnoreCase))
                     .ToList())
        {
            _nativeSettingsRows.Remove(row);
        }

        foreach (var row in GetDefaultNativeSettingsRows())
        {
            _nativeSettingsRows.Add(row);
        }
    }

    private void AddBaseMaterialRow_Click(object sender, RoutedEventArgs e)
    {
        var row = new NativeBaseMaterialRow
        {
            BaseMaterial = NextUniqueBaseMaterialName("New material"),
            Category = "Standard",
            SortOrder = ""
        };
        _nativeBaseMaterialRows.Add(row);
        SaveBaseMaterialCatalogToDatabase();
        RefreshFastSettingsViews();
        ShowTransientStatus($"{row.BaseMaterial} added to the canonical Base Material Catalog.");
    }

    private void DuplicateBaseMaterialRow_Click(object sender, RoutedEventArgs e)
    {
        var source = _selectedFastBaseMaterialRow;
        if (source is null)
        {
            ShowTransientStatus("Select a Base Material row before duplicating.");
            return;
        }

        var copy = new NativeBaseMaterialRow
        {
            BaseMaterial = NextUniqueBaseMaterialName(source.BaseMaterial + " Copy"),
            Category = source.Category,
            SortOrder = source.SortOrder,
            NozzleTemperatureMinC = source.NozzleTemperatureMinC,
            NozzleTemperatureRecommendedC = source.NozzleTemperatureRecommendedC,
            NozzleTemperatureMaxC = source.NozzleTemperatureMaxC,
            BedTemperatureMinC = source.BedTemperatureMinC,
            BedTemperatureRecommendedC = source.BedTemperatureRecommendedC,
            BedTemperatureMaxC = source.BedTemperatureMaxC,
            PrintSpeedMinMmPerS = source.PrintSpeedMinMmPerS,
            PrintSpeedRecommendedMmPerS = source.PrintSpeedRecommendedMmPerS,
            PrintSpeedMaxMmPerS = source.PrintSpeedMaxMmPerS,
            CoolingMinPercent = source.CoolingMinPercent,
            CoolingRecommendedPercent = source.CoolingRecommendedPercent,
            CoolingMaxPercent = source.CoolingMaxPercent,
            CoolingGuidance = source.CoolingGuidance,
            DryingTemperatureC = source.DryingTemperatureC,
            DryingTimeHours = source.DryingTimeHours,
            EnclosureRequirement = source.EnclosureRequirement,
            PrinterProfileReference = source.PrinterProfileReference,
            SlicerProfileReference = source.SlicerProfileReference,
            ProfileId = source.ProfileId,
            ProfileKind = source.ProfileKind
        };
        _nativeBaseMaterialRows.Add(copy);
        SaveBaseMaterialCatalogToDatabase();
        RefreshFastSettingsViews();
        ShowTransientStatus($"{copy.BaseMaterial} duplicated from {source.BaseMaterial}.");
    }

    private void DeleteBaseMaterialRow_Click(object sender, RoutedEventArgs e)
    {
        if (IsAutomationActionBlocked("Base Material deletion")) return;
        var row = _selectedFastBaseMaterialRow;
        if (row is null) return;

        if (_nativeMaterialRows.Any(material =>
                material.BaseMaterialId == row.BaseMaterialId))
        {
            MessageBox.Show(
                this,
                $"{row.BaseMaterial} is referenced by Materials and cannot be deleted.",
                "Base Material In Use",
                MessageBoxButton.OK,
                MessageBoxImage.Warning);
            return;
        }

        var prompt = BuildBaseMaterialDeletePrompt(row.BaseMaterial);
        if (!ShowSafeDeleteConfirmation(prompt.Caption, prompt.Message)) return;

        try
        {
            if (!_database.DeleteUnreferencedBaseMaterial(row.BaseMaterialId))
            {
                MessageBox.Show(
                    this,
                    $"{row.BaseMaterial} was not deleted. It may have become referenced or no longer exists.",
                    "Base Material Not Deleted",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return;
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(
                this,
                $"Could not delete {row.BaseMaterial}. No in-memory catalog or selection change was made.\n\n{ex.Message}",
                "Base Material Delete Failed",
                MessageBoxButton.OK,
                MessageBoxImage.Error);
            return;
        }

        try
        {
        try
        {
            _nativeBaseMaterialRows.Remove(row);
            _selectedFastBaseMaterialRow = null;
            ApplyNativeMaterialComputedFieldsToAllRows();
            RefreshNativeMaterialGridValidation();
            RefreshNativeInputModulesFromMaterialManager(markDirty: false);
            RefreshFastSettingsViews();
            ShowTransientStatus($"{row.BaseMaterial} deleted from the canonical Base Material Catalog.");
        }
        catch (Exception ex)
        {
            _nativeBaseMaterialRows.Clear();
            foreach (var persisted in _database.LoadBaseMaterialCatalog())
                _nativeBaseMaterialRows.Add(FromBaseMaterialRecord(persisted));
            _selectedFastBaseMaterialRow = null;
            RefreshFastSettingsViews();
            MessageBox.Show(
                this,
                $"{row.BaseMaterial} was deleted from SQLite, but the view refresh failed and was reloaded from the canonical catalog.\n\n{ex.Message}",
                "Base Material Deleted — View Reloaded",
                MessageBoxButton.OK,
                MessageBoxImage.Warning);
        }
        }
        catch (Exception ex)
        {
            _nativeBaseMaterialRows.Clear();
            foreach (var persisted in _database.LoadBaseMaterialCatalog())
                _nativeBaseMaterialRows.Add(FromBaseMaterialRecord(persisted));
            _selectedFastBaseMaterialRow = null;
            RefreshFastSettingsViews();
            MessageBox.Show(
                this,
                $"{row.BaseMaterial} was deleted from SQLite, but the view refresh failed and was reloaded from the canonical catalog.\n\n{ex.Message}",
                "Base Material Deleted — View Reloaded",
                MessageBoxButton.OK,
                MessageBoxImage.Warning);
        }
    }

    private static BaseMaterialDeletePrompt BuildBaseMaterialDeletePrompt(string baseMaterialName) =>
        new(
            $"Delete Base Material \"{baseMaterialName}\"?\n\n" +
            "This permanently removes only this unreferenced canonical catalog entry. " +
            "Materials, measurements and calculated results are not changed.\n\n" +
            "Choose No, press Escape or close this warning to keep the catalog and current selection unchanged.",
            "Delete Base Material?",
            false);

    private static BaseMaterialDeletePrompt BuildMaterialDeletePrompt(
        string materialId,
        string displayName) =>
        new(
            $"Delete material {materialId} – {displayName}?\n\n" +
            "This permanently removes the material from the native database. " +
            "A backup will be created first.\n\n" +
            "Choose No, press Escape or close this warning to keep the material and current selection unchanged.",
            "Delete Material?",
            false);

    private static bool BaseMaterialDeleteConfirmed(bool? result) =>
        result == true;

    private bool ShowSafeDeleteConfirmation(string caption, string message)
    {
        var confirmation = new SafeDeleteConfirmationWindow(caption, message)
        {
            Owner = this
        };
        return BaseMaterialDeleteConfirmed(confirmation.ShowDialog());
    }

    private sealed record BaseMaterialDeletePrompt(
        string Message,
        string Caption,
        bool DefaultResult);

    private string NextUniqueBaseMaterialName(string preferred)
    {
        var candidate = preferred.Trim();
        var suffix = 2;
        while (_nativeBaseMaterialRows.Any(row =>
                   string.Equals(row.BaseMaterial.Trim(), candidate, StringComparison.OrdinalIgnoreCase)) ||
               _nativeMaterialRows.Any(row =>
                   string.Equals(row.BaseMaterial?.Trim(), candidate, StringComparison.OrdinalIgnoreCase)))
        {
            candidate = $"{preferred.Trim()} {suffix++}";
        }
        return candidate;
    }

