    private sealed record ManufacturerEngineeringIntelligence(
        int CompleteCount,
        int PartialCount,
        double? AverageOverall,
        ManufacturerMetricLeader? StrongestTensile,
        ManufacturerMetricLeader? BestImpact,
        ManufacturerMetricLeader? HighestStiffness,
        ManufacturerMetricLeader? BestLayerAdhesion,
        ManufacturerMetricLeader? BestOverall,
        ManufacturerMetricLeader? BestValue,
        IReadOnlyList<ManufacturerMaterialInsight> TopMaterials,
        IReadOnlyList<string> FamilySummary)
    {
        public bool HasData => CompleteCount > 0 || PartialCount > 0 || AverageOverall.HasValue ||
                               StrongestTensile is not null || BestImpact is not null || HighestStiffness is not null ||
                               BestLayerAdhesion is not null || BestOverall is not null || BestValue is not null;
    }

