        [JsonIgnore]
        public bool IsRowValid => !string.IsNullOrWhiteSpace(MaterialID)
            && !string.IsNullOrWhiteSpace(Manufacturer)
            && !string.IsNullOrWhiteSpace(ProductLine)
            && !string.IsNullOrWhiteSpace(BaseMaterial)
            && !string.IsNullOrWhiteSpace(WebsiteDisplayName);

        [JsonIgnore]
        public string ValidationSummary
        {
            get
            {
                var issues = new List<string>();
                if (string.IsNullOrWhiteSpace(MaterialID)) issues.Add("Material ID");
                if (string.IsNullOrWhiteSpace(Manufacturer)) issues.Add("Manufacturer");
                if (string.IsNullOrWhiteSpace(ProductLine)) issues.Add("Product Line");
                if (string.IsNullOrWhiteSpace(BaseMaterial)) issues.Add("Base Material");
                if (string.IsNullOrWhiteSpace(WebsiteDisplayName)) issues.Add("Display Name");

                return issues.Count == 0 ? "OK" : "Missing: " + string.Join(", ", issues);
            }
        }
    }

