        row["Tested Status"] = material.TestedStatus;
        row["In Tensile"] = material.InTensile;
        row["In Impact"] = material.InImpact;
        row["In Stiffness"] = material.InStiffness;
        row["Sort Order"] = material.SortOrder;
        row["Source Priority"] = material.SourcePriority;
        row["Website Display Name"] = material.WebsiteDisplayName;
        row["Material Key"] = material.MaterialKey;
        row["Publish Public Reports"] = material.PublishPublicReports ? "Yes" : "No";
        row["Publish Public Test Details"] = material.PublishPublicTestDetails ? "Yes" : "No";
        row["Archived"] = material.IsArchived ? "Yes" : "No";
        table.Rows.Add(row);
        return row;
    }

    private List<DataRow> BuildNativeMaterialDataRows(bool includeArchived)
    {
        return _nativeMaterialRows
            .Where(material => includeArchived || !material.IsArchived)
            .Select(BuildNativeMaterialDataRow)
            .ToList();
    }

    private string StorageWorkingFilePath(string fileName)
    {
        var folder = _database.DatabaseFolder;
        if (string.IsNullOrWhiteSpace(folder))
        {
            folder = LocalDatabase.GetConfiguredStorageFolder();
        }

        Directory.CreateDirectory(folder);
        return System.IO.Path.Combine(folder, fileName);
    }

    private string NativeMaterialsFilePath()
    {
        return StorageWorkingFilePath("native-materials-manager.json");
    }

    private List<NativeMaterialRow> LoadNativeMaterialsFromCanonicalOrMigrationSnapshot()
    {
        var canonicalRows = _database.LoadNativeMaterialManagerRows().Select(NativeMaterialRowFromRecord).ToList();
        if (canonicalRows.Count > 0) return canonicalRows;

        var path = NativeMaterialsFilePath();
        if (System.IO.File.Exists(path))
        {
            try
            {
                var json = System.IO.File.ReadAllText(path);
                var state = JsonSerializer.Deserialize<NativeMaterialsState>(json) ?? new NativeMaterialsState();
                if (state.Materials.Count > 0)
                {
                    // SQLite owns governed publication and printing-setting fields even
                    // while a legacy JSON snapshot remains available only for empty-database seeding.
                    var sqliteCanonicalRows = _database.LoadNativeMaterialManagerRows()
                        .ToDictionary(row => row.MaterialID.Trim(), StringComparer.OrdinalIgnoreCase);
                    foreach (var material in state.Materials)
                    {
                        if (!sqliteCanonicalRows.TryGetValue(material.MaterialID.Trim(), out var canonical)) continue;
                        material.PublishPublicReports = canonical.PublishPublicReports;
                        material.PublishPublicTestDetails = canonical.PublishPublicTestDetails;
                        material.NozzleTemperatureMinC = canonical.NozzleTemperatureMinC;
                        material.NozzleTemperatureRecommendedC = canonical.NozzleTemperatureRecommendedC;
                        material.NozzleTemperatureMaxC = canonical.NozzleTemperatureMaxC;
                        material.BedTemperatureMinC = canonical.BedTemperatureMinC;
                        material.BedTemperatureRecommendedC = canonical.BedTemperatureRecommendedC;
                        material.BedTemperatureMaxC = canonical.BedTemperatureMaxC;
                        material.PrintSpeedMinMmPerS = canonical.PrintSpeedMinMmPerS;
                        material.PrintSpeedRecommendedMmPerS = canonical.PrintSpeedRecommendedMmPerS;
                        material.PrintSpeedMaxMmPerS = canonical.PrintSpeedMaxMmPerS;
                        material.CoolingRequirement = canonical.CoolingRequirement;
                        material.DryingTimeHours = canonical.DryingTimeHours;
                        material.EnclosureRequirement = canonical.EnclosureRequirement;
                        material.PrinterProfileReference = canonical.PrinterProfileReference;
                        material.SlicerProfileReference = canonical.SlicerProfileReference;
                        material.PrintingProfileId = canonical.PrintingProfileId;
                        material.PrintingProfileKind = canonical.PrintingProfileKind;
                        material.CoolingMinPercent = canonical.CoolingMinPercent;
                        material.CoolingRecommendedPercent = canonical.CoolingRecommendedPercent;
                        material.CoolingMaxPercent = canonical.CoolingMaxPercent;
                        material.DryingTemperatureC = canonical.DryingTemperatureC;
                        material.SlicerIdentity = canonical.SlicerIdentity;
                        material.SlicerVersion = canonical.SlicerVersion;
                        material.PrintingSettingsProvenance = canonical.PrintingSettingsProvenance;
                        material.PrintingSettingsSourceUrl = canonical.PrintingSettingsSourceUrl;
                        material.PrintingSettingsCheckedDate = canonical.PrintingSettingsCheckedDate;
                        material.PrintingSettingsValidationNote = canonical.PrintingSettingsValidationNote;
                    }
                    _database.ReplaceNativeMaterialManagerRows(state.Materials.Select(NativeMaterialRecordFromRow));
                    return state.Materials;
                }
            }
            catch
            {
                // Fall through to native defaults if the legacy JSON snapshot cannot be read.
            }
        }

        return GetDefaultNativeMaterialRows();
    }

