    private static List<NativeMaterialRow> GetDefaultNativeMaterialRows()
    {
        return new List<NativeMaterialRow>();
    }


    private void ReplaceNativeMaterialRows(IEnumerable<NativeMaterialRow> rows)
    {
        var previousSuppress = _suppressNativeMaterialDirty;
        _suppressNativeMaterialDirty = true;
        _nativeMaterialRows.Clear();
        foreach (var row in rows)
        {
            _nativeMaterialRows.Add(row);
        }
        ApplyNativeMaterialComputedFieldsToAllRows();
        _suppressNativeMaterialDirty = previousSuppress;
        QueueNativeMaterialCollectionRefresh();
    }

    private void MarkNativeMaterialsDirty()
    {
        SetNativeMaterialsDirty(true);
    }

    private void SetNativeMaterialsDirty(bool isDirty)
    {
        _nativeMaterialDirty = isDirty;
        if (FindName("SaveNativeMaterialsButton") is Button saveButton)
        {
            saveButton.IsEnabled = true;
            saveButton.ToolTip = "Manual backup only. Normal editing auto-saves.";
        }
        RefreshNativeMaterialSummary();
    }

    private void RefreshNativeMaterialGridValidation()
    {
        _embeddedMaterialsPrototypeView?.SynchronizeFromCanonical(
            "canonical Materials validation",
            _lastSelectedNativeMaterial);
    }

    private void QueueNativeMaterialEditRefresh()
    {
        // Arrow/Tab navigation must be allowed to activate the next editor before the
        // comparatively expensive all-material recompute, filter rebuild, module sync and
        // SQLite save. Repeated edits restart this short timer and collapse into one save.
        _nativeMaterialEditDebounceTimer.Stop();
        _nativeMaterialEditDebounceTimer.Start();
    }

    private void NativeMaterialEditDebounceTimer_Tick(object? sender, EventArgs e)
    {
        _nativeMaterialEditDebounceTimer.Stop();
        ApplyNativeMaterialComputedFieldsToAllRows();
        PopulateNativeMaterialFilters();
        ApplyNativeMaterialFilters();
        RefreshNativeMaterialGridValidation();
        RefreshNativeMaterialSummary();
        RefreshInventorySummary();
        if (SaveNativeMaterialsSilent())
        {
            RefreshNativeInputModulesFromMaterialManager(markDirty: false);
        }
        QueueNativeMaterialDependentIntelligenceRefresh();
    }


    private void RefreshNativeInputModulesFromMaterialManager(bool markDirty)
    {
        // Measurement/input modules reference MaterialID and display current identity
        // from Material Manager. Identity fields should never be owned by measurement rows.
        SyncNativeTensileRowsWithMaterialManager(markDirty);
        SyncNativeImpactRowsWithMaterialManager(markDirty);
        SyncNativeStiffnessRowsWithMaterialManager(markDirty);
        ApplyNativeMeasurementFilters();
    }

    private void MainWindow_Closing(object? sender, CancelEventArgs e)
    {
        if (_databaseRestoreShutdown) return;

        _embeddedMaterialsPrototypeView?.CommitActiveEditor();
        _embeddedFastTensileView?.CommitActiveEditor();
        _embeddedFastImpactView?.CommitActiveEditor();
        _embeddedFastStiffnessView?.CommitActiveEditor();
        _nativeMaterialEditDebounceTimer.Stop();

        _workflowPreferencesService.CaptureWindow(this);
        _workflowPreferencesService.SetLastSelectedMaterialId(_lastSelectedNativeMaterial?.MaterialID);
        _workflowPreferencesService.SetMaterialFilterState(_materialFilterState);
        SaveWebsiteExportFolderPreference(WebsiteExportFolderBox.Text?.Trim() ?? string.Empty);
        foreach (var gridName in WorkflowGridNames)
        {
            if (FindName(gridName) is DataGrid grid)
            {
                _workflowPreferencesService.CaptureGrid(grid);
            }
        }
        _workflowPreferencesService.Save();

        // Measurement rows are FK children of canonical Materials. Persist a new
        // or duplicated parent MaterialID before attempting measurement auto-save.
        if (_nativeMaterialDirty)
        {
            ApplyNativeMaterialComputedFieldsToAllRows();
            if (!SaveNativeMaterialsSilent())
            {
                var closeAnyway = MessageBox.Show(
                    this,
                    "Material Manager changes could not be auto-saved before closing.\n\n" +
                    "Measurement auto-save was not attempted because measurement rows require their parent MaterialID in SQLite.\n\n" +
                    "Close the application anyway?",
                    "Auto-Save Blocked",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Warning,
                    MessageBoxResult.No);
                if (closeAnyway != MessageBoxResult.Yes)
                {
                    e.Cancel = true;
                }
                return;
            }
        }

        if (_nativeTensileDirty || _nativeImpactDirty || _nativeStiffnessDirty)
        {
            try
            {
                ApplyNativeTensileComputedFields(_nativeTensileRows);
                ApplyNativeImpactComputedFields(_nativeImpactRows);
                ApplyNativeStiffnessComputedFields(_nativeStiffnessRows);
                RefreshNativeMaterialTestStatusFromNativeInputTabs(markDirty: true);
                SaveNativeMeasurementsToSqlite();
                SetNativeTensileDirty(false);
                SetNativeImpactDirty(false);
                SetNativeStiffnessDirty(false);
            }
            catch (Exception ex)
            {
                var closeAnyway = MessageBox.Show(
                    this,
                    $"Measurement changes could not be auto-saved before closing:\n\n{ex.Message}\n\nClose the application anyway?",
                    "Measurement Auto-Save Blocked",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Warning,
                    MessageBoxResult.No);
                if (closeAnyway != MessageBoxResult.Yes)
                {
                    e.Cancel = true;
                    return;
                }
            }
        }

        // Measurement save can update the derived Material test-status fields.
        // Persist that parent metadata after the child transaction completes.
        if (!_nativeMaterialDirty)
        {
            return;
        }

        ApplyNativeMaterialComputedFieldsToAllRows();
        SaveNativeMaterialsSilent();

        if (!_nativeMaterialDirty)
        {
            return;
        }

        var result = MessageBox.Show("Material Manager changes could not be auto-saved before closing. Close the application anyway?", "Auto-Save Blocked", MessageBoxButton.YesNo, MessageBoxImage.Warning);
        if (result != MessageBoxResult.Yes)
        {
            e.Cancel = true;
        }
    }

    private string BuildNativeMaterialValidationSummary()
    {
        ApplyNativeMaterialComputedFieldsToAllRows();

        var duplicateIds = _nativeMaterialRows
            .Where(row => !string.IsNullOrWhiteSpace(row.MaterialID))
            .GroupBy(row => row.MaterialID.Trim(), StringComparer.OrdinalIgnoreCase)
            .Where(group => group.Count() > 1)
            .Select(group => group.Key)
            .ToList();

        var missingIds = _nativeMaterialRows.Count(row => string.IsNullOrWhiteSpace(row.MaterialID));
        var missingManufacturers = _nativeMaterialRows.Count(row => string.IsNullOrWhiteSpace(row.Manufacturer));
        var missingProductLines = _nativeMaterialRows.Count(row => string.IsNullOrWhiteSpace(row.ProductLine));
        var missingBaseMaterials = _nativeMaterialRows.Count(row => string.IsNullOrWhiteSpace(row.BaseMaterial));
        var missingDisplayNames = _nativeMaterialRows.Count(row => string.IsNullOrWhiteSpace(row.WebsiteDisplayName));
        var invalidRows = _nativeMaterialRows.Count(row => !row.IsRowValid);
        var duplicateDisplayNames = _nativeMaterialRows
            .Where(row => !string.IsNullOrWhiteSpace(row.WebsiteDisplayName))
            .GroupBy(row => row.WebsiteDisplayName.Trim(), StringComparer.OrdinalIgnoreCase)
            .Where(group => group.Count() > 1)
            .Select(group => group.Key)
            .ToList();
        var linkedYouTubeReviews = _nativeMaterialRows.Count(row => !string.IsNullOrWhiteSpace(row.YouTubeReviewUrl));

        var issues = new List<string>();
        if (missingIds > 0) issues.Add($"Missing Material ID: {missingIds}");
        if (duplicateIds.Count > 0) issues.Add($"Duplicate Material ID: {string.Join(", ", duplicateIds.Take(10))}{(duplicateIds.Count > 10 ? " ..." : string.Empty)}");
        if (missingManufacturers > 0) issues.Add($"Missing Manufacturer: {missingManufacturers}");
        if (missingProductLines > 0) issues.Add($"Missing Product Line: {missingProductLines}");
        if (missingBaseMaterials > 0) issues.Add($"Missing Base Material: {missingBaseMaterials}");
        if (missingDisplayNames > 0) issues.Add($"Missing Website Display Name: {missingDisplayNames}");
        if (duplicateDisplayNames.Count > 0) issues.Add($"Duplicate Website Display Name: {string.Join(", ", duplicateDisplayNames.Take(10))}{(duplicateDisplayNames.Count > 10 ? " ..." : string.Empty)}");

        var active = _nativeMaterialRows.Count(row => !row.IsArchived);
        var archived = _nativeMaterialRows.Count(row => row.IsArchived);
        var exportCandidates = GetNativeWebsiteExportCandidateRows().Count;
        var header = $"Validated {_nativeMaterialRows.Count} native material rows ({active} active, {archived} archived, {invalidRows} invalid, {exportCandidates} future website export candidates, {linkedYouTubeReviews} YouTube links).";
        var archiveNote = "Archived rows remain visible in Material Manager, but future native website export should use only active/export-candidate rows.";

        return issues.Count == 0
            ? header + Environment.NewLine + Environment.NewLine + archiveNote + Environment.NewLine + Environment.NewLine + "No blocking material manager issues found."
            : header + Environment.NewLine + Environment.NewLine + archiveNote + Environment.NewLine + Environment.NewLine + string.Join(Environment.NewLine, issues.Select(issue => "- " + issue));
    }

    private string GenerateNextNativeMaterialId()
    {
        var max = 0;
        foreach (var row in _nativeMaterialRows)
        {
            var text = row.MaterialID?.Replace("MAT", "", StringComparison.OrdinalIgnoreCase) ?? "";
            if (int.TryParse(text, out var number) && number > max)
            {
                max = number;
            }
        }

        return $"MAT{max + 1:0000}";
    }

    private string BuildNativeMaterialDisplayName(NativeMaterialRow row)
    {
        var parts = new[]
        {
            row.Manufacturer,
            row.ProductLine,
            row.MarketingName,
            row.BaseMaterial,
            row.VariantFinish,
            row.Reinforcement,
            row.Color
        };

        return string.Join(" ", parts.Where(part => !string.IsNullOrWhiteSpace(part))).Trim();
    }

    private string BuildNativeMaterialCategory(NativeMaterialRow row)
    {
        if (string.IsNullOrWhiteSpace(row.BaseMaterial))
        {
            return string.Empty;
        }

        var settingsRow = ResolveBaseMaterialCatalogRow(row);

        return settingsRow?.Category?.Trim() ?? string.Empty;
    }

    private string BuildNativeMaterialKey(NativeMaterialRow row)
    {
        var parts = new[]
        {
            row.BaseMaterial,
            row.VariantFinish,
            row.Reinforcement,
            row.Color,
            row.Manufacturer,
            row.ProductLine,
            row.MarketingName
        };

        return string.Join("|", parts.Select(part => (part ?? string.Empty).Trim()));
    }

    private static string NormalizeNativeYesNo(string value)
    {
        return string.Equals((value ?? string.Empty).Trim(), "Yes", StringComparison.OrdinalIgnoreCase) ? "Yes" : "No";
    }

    private string BuildNativeMaterialTestedStatus(NativeMaterialRow row)
    {
        var testedCount = new[] { row.InTensile, row.InImpact, row.InStiffness }
            .Count(value => string.Equals((value ?? string.Empty).Trim(), "Yes", StringComparison.OrdinalIgnoreCase));

        return testedCount switch
        {
            0 => "Not tested",
            3 => "Fully tested",
            _ => "Partially tested"
        };
    }

    private static bool NativeTensileRowHasMeasurementData(NativeTensileMeasurementRow row)
    {
        return ToNumbers(row.SampleValues(true)).Any() || ToNumbers(row.SampleValues(false)).Any();
    }

    private void RefreshNativeMaterialTestStatusFromNativeInputTabs(bool markDirty)
    {
        if (_nativeMaterialRows.Count == 0) return;

        var tensileMaterialIds = _nativeTensileRows
            .Where(row => !string.IsNullOrWhiteSpace(row.MaterialID))
            .Where(NativeTensileRowHasMeasurementData)
            .Select(row => row.MaterialID.Trim())
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

        var impactMaterialIds = _nativeImpactRows
            .Where(row => !string.IsNullOrWhiteSpace(row.MaterialID))
            .Where(NativeImpactRowHasMeasurementData)
            .Select(row => row.MaterialID.Trim())
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

        var stiffnessMaterialIds = _nativeStiffnessRows
            .Where(row => !string.IsNullOrWhiteSpace(row.MaterialID))
            .Where(NativeStiffnessRowHasMeasurementData)
            .Select(row => row.MaterialID.Trim())
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

        var changed = false;
        foreach (var material in _nativeMaterialRows.Where(row => !string.IsNullOrWhiteSpace(row.MaterialID)))
        {
            var materialId = material.MaterialID.Trim();
            var newInTensile = tensileMaterialIds.Contains(materialId) ? "Yes" : "No";
            var newInImpact = impactMaterialIds.Contains(materialId) ? "Yes" : "No";
            var newInStiffness = stiffnessMaterialIds.Contains(materialId) ? "Yes" : "No";

            if (!string.Equals(material.InTensile, newInTensile, StringComparison.OrdinalIgnoreCase))
            {
                material.InTensile = newInTensile;
                changed = true;
            }

            if (!string.Equals(material.InImpact, newInImpact, StringComparison.OrdinalIgnoreCase))
            {
                material.InImpact = newInImpact;
                changed = true;
            }

            if (!string.Equals(material.InStiffness, newInStiffness, StringComparison.OrdinalIgnoreCase))
            {
                material.InStiffness = newInStiffness;
                changed = true;
            }

            var previousStatus = material.TestedStatus;
            material.TestedStatus = BuildNativeMaterialTestedStatus(material);
            if (!string.Equals(previousStatus, material.TestedStatus, StringComparison.Ordinal))
            {
                changed = true;
            }
        }

        if (changed)
        {
            ApplyNativeMaterialComputedFieldsToAllRows();
            RefreshNativeMaterialSummary();
            RefreshNativeMaterialGridValidation();
            if (markDirty) MarkNativeMaterialsDirty();
        }

        // Material Detail and Dashboard Insights must follow native measurement edits,
        // even when the Yes/No coverage flags themselves did not change.
        RefreshSelectedNativeMaterialDetails();
        UpdateDashboardInsights();
    }

    private void RefreshSelectedNativeMaterialDetails()
    {
        var selected = _lastSelectedNativeMaterial;
        if (selected is null) return;
        var current = _nativeMaterialRows.FirstOrDefault(row =>
            string.Equals(row.MaterialID?.Trim(), selected.MaterialID?.Trim(), StringComparison.OrdinalIgnoreCase));
        if (current is not null)
        {
            ShowNativeMaterialDetails(current);
        }
    }

    private string BuildNativeMaterialSortOrder(NativeMaterialRow row, int rowIndex)
    {
        var baseSortText = ResolveBaseMaterialCatalogRow(row)?.SortOrder;

        var baseSort = 9990d;
        if (!string.IsNullOrWhiteSpace(baseSortText))
        {
            _ = double.TryParse(baseSortText, NumberStyles.Any, CultureInfo.InvariantCulture, out baseSort);
        }

        var computed = baseSort + ((rowIndex + 3) / 1000d);
        return computed.ToString("0.###", CultureInfo.InvariantCulture);
    }

    private void ApplyNativeMaterialComputedFields(NativeMaterialRow row, int rowIndex)
    {
        if (string.IsNullOrWhiteSpace(row.MaterialID))
        {
            row.Video = "No";
            row.TestedStatus = string.Empty;
            row.SortOrder = string.Empty;
            row.SourcePriority = string.Empty;
            row.WebsiteDisplayName = string.Empty;
            row.MaterialKey = string.Empty;
            return;
        }

        row.Video = string.IsNullOrWhiteSpace(row.YouTubeReviewUrl) ? "No" : "Yes";
        row.InTensile = NormalizeNativeYesNo(row.InTensile);
        row.InImpact = NormalizeNativeYesNo(row.InImpact);
        row.InStiffness = NormalizeNativeYesNo(row.InStiffness);
        row.TestedStatus = BuildNativeMaterialTestedStatus(row);
        row.MaterialCategory = BuildNativeMaterialCategory(row);
        row.SortOrder = BuildNativeMaterialSortOrder(row, rowIndex);
        row.SourcePriority = "Materials master";
        row.WebsiteDisplayName = BuildNativeMaterialDisplayName(row);
        row.MaterialKey = BuildNativeMaterialKey(row);
        ApplyMaterialPricingCalculations(row);
    }

    private IReadOnlyDictionary<string, decimal> GetMaterialPricingCurrencyUnitsPerUsd()
    {
        var rates = new Dictionary<string, decimal>(StringComparer.OrdinalIgnoreCase)
        {
            ["USD"] = 1m
        };
        foreach (var (currency, parameter) in new[]
                 {
                     ("ISK", "ISK per 1 USD"),
                     ("EUR", "EUR per 1 USD"),
                     ("GBP", "GBP per 1 USD")
                 })
        {
            var value = _nativeSettingsRows.FirstOrDefault(r =>
                string.Equals(r.Section, "Currency", StringComparison.OrdinalIgnoreCase) &&
                string.Equals(r.Parameter, parameter, StringComparison.OrdinalIgnoreCase) &&
                r.UsedBy.Contains("Material Pricing", StringComparison.OrdinalIgnoreCase))?.Value;
            if (decimal.TryParse(value?.Replace(',', '.'), NumberStyles.Number, CultureInfo.InvariantCulture, out var rate) &&
                rate > 0m)
                rates[currency] = rate;
        }
        return rates;
    }

    private string ConvertPriceToUsd(string? amountText, string? currency)
        => _pricingProvenanceService
            .ConvertToUsd(amountText, currency, GetMaterialPricingCurrencyUnitsPerUsd())
            .UsdAmount;

    private void ApplyMaterialPricingCalculations(NativeMaterialRow row)
    {
        row.MsrpCurrency = PricingProvenanceService.NormalizeCurrencyForStorage(row.MsrpCurrency);
        row.LandedCostCurrency = PricingProvenanceService.NormalizeCurrencyForStorage(row.LandedCostCurrency);
        row.MsrpUsd = ConvertPriceToUsd(row.MsrpAmount, row.MsrpCurrency);
        row.LandedCostUsd = ConvertPriceToUsd(row.LandedCostAmount, row.LandedCostCurrency);
        row.MsrpUsdPerKg = CalculateUsdPerKg(row.MsrpUsd, row.SpoolWeightG);
        row.LandedCostUsdPerKg = CalculateUsdPerKg(row.LandedCostUsd, row.SpoolWeightG);
    }

    private static string CalculateUsdPerKg(string? usdText, string? spoolWeightText)
    {
        if (!TryParseDecimalAware(usdText ?? string.Empty, out var usd) || usd < 0 ||
            !TryParseDecimalAware(spoolWeightText ?? string.Empty, out var grams) || grams <= 0)
            return string.Empty;
        return (usd * 1000.0 / grams).ToString("0.00", CultureInfo.InvariantCulture);
    }

    private void ApplyNativeMaterialComputedFieldsToAllRows()
    {
        for (var i = 0; i < _nativeMaterialRows.Count; i++)
        {
            ApplyNativeMaterialComputedFields(_nativeMaterialRows[i], i);
        }
    }

    private void InitializePurchaseOrderManager()
    {
        _ecbExchangeRateCatalog =
            EcbExchangeRateReferenceService.LoadCache(EcbExchangeRateCachePath());
        foreach (var order in _database.LoadPurchaseOrders())
        {
            if (string.IsNullOrWhiteSpace(order.LifecycleStatus)) order.LifecycleStatus = "Draft";
            if (string.IsNullOrWhiteSpace(order.ShippingAllocationMethod)) order.ShippingAllocationMethod = "Automatic";
            if (string.IsNullOrWhiteSpace(order.TaxAllocationMethod)) order.TaxAllocationMethod = "By line value";
            if (string.IsNullOrWhiteSpace(order.CustomsAllocationMethod)) order.CustomsAllocationMethod = "By line value";
            if (string.IsNullOrWhiteSpace(order.FeeAllocationMethod)) order.FeeAllocationMethod = "By line value";
            _purchaseOrders.Add(order);
        }
        foreach (var line in _database.LoadPurchaseOrderLines())
        {
            if (string.IsNullOrWhiteSpace(line.ReceivedQuantity)) line.ReceivedQuantity = "0";
            if (string.IsNullOrWhiteSpace(line.ReceivingStatus)) line.ReceivingStatus = "Not checked";
            if (string.IsNullOrWhiteSpace(line.InventoryCategory)) line.InventoryCategory = "Filament";
            _purchaseOrderLines.Add(line);
        }
        if (FindName("PurchaseOrdersGrid") is DataGrid ordersGrid) ordersGrid.ItemsSource = _purchaseOrders;
        RefreshPurchaseCurrencyChoices();
        _purchaseOrderLineView = CollectionViewSource.GetDefaultView(_purchaseOrderLines);
        _purchaseOrderLineView.Filter = item => item is PurchaseOrderLineRecord line &&
            (FindName("PurchaseOrdersGrid") is not DataGrid g || g.SelectedItem is not PurchaseOrderRecord order || line.PurchaseOrderId == order.PurchaseOrderId);
        if (FindName("PurchaseOrderLinesGrid") is DataGrid linesGrid)
        {
            linesGrid.ItemsSource = _purchaseOrderLineView;
            RefreshPurchaseMaterialChoices();
        }
        _purchaseOrders.CollectionChanged += (_, _) => SavePurchaseOrders();
        _purchaseOrderLines.CollectionChanged += (_, _) => SavePurchaseOrders();
        if (_purchaseOrders.Count > 0 && FindName("PurchaseOrdersGrid") is DataGrid grid) grid.SelectedIndex = 0;
        RefreshPurchaseOrderSummary();
        RefreshEcbExchangeRateStatus();
    }

    private void SavePurchaseOrders() => _database.ReplacePurchaseOrders(_purchaseOrders, _purchaseOrderLines);

    private void CalculateSelectedPurchaseOrderCosts()
    {
        CommitPurchaseOrderEdits(false);
        if (FindName("PurchaseOrdersGrid") is not DataGrid grid || grid.SelectedItem is not PurchaseOrderRecord order) return;
        if (!string.IsNullOrWhiteSpace(order.LandedCostCalculationVersion))
        {
            MessageBox.Show(
                this,
                "This Purchase Order already has a saved landed-cost calculation snapshot. " +
                "Saved calculations are never recalculated.",
                "Landed Cost Snapshot Locked",
                MessageBoxButton.OK,
                MessageBoxImage.Information);
            RefreshLandedCostCurrencyReview();
            return;
        }
        if (!TryParseDecimalAware(order.LandedCostConversionRate, out var parsedConversionRate) ||
            parsedConversionRate <= 0)
        {
            MessageBox.Show(
                this,
                "Review and apply a valid landed-cost currency conversion rate before calculating.",
                "Landed Cost Currency",
                MessageBoxButton.OK,
                MessageBoxImage.Warning);
            return;
        }
        var lines = _purchaseOrderLines.Where(x => x.PurchaseOrderId == order.PurchaseOrderId).ToList();
        var result = _purchasingCostAllocationService.Calculate(
            order,
            lines,
            Convert.ToDecimal(parsedConversionRate, CultureInfo.InvariantCulture));
        order.CostStatus = result.IsValid ? result.Status : "Draft";
        if (FindName("PurchaseCostValidationText") is TextBlock validationText)
        {
            validationText.Text = result.ValidationDetails;
            validationText.Foreground = result.IsValid
                ? new SolidColorBrush(Color.FromRgb(22, 101, 52))
                : new SolidColorBrush(Color.FromRgb(185, 28, 28));
        }
        if (result.IsValid)
        {
            StampLandedCostCalculation(order, DateTimeOffset.UtcNow);
        }
        SavePurchaseOrders();
        var syncedMaterials = result.IsValid
            ? SyncLinkedMaterialsFromPurchaseOrder(order, lines)
            : 0;
        if (syncedMaterials > 0)
        {
            SaveNativeMaterialsSilent();
            RefreshNativeMaterialGridValidation();
        }
        grid.Items.Refresh();
        if (FindName("PurchaseOrderLinesGrid") is DataGrid lg) lg.Items.Refresh();
        RefreshPurchaseOrderSummary();
        RefreshLandedCostCurrencyReview();
        if (!result.IsValid)
        {
            MessageBox.Show(this, result.ValidationDetails, "Cost Allocation Validation", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

    private void CalculatePurchaseCosts_Click(object sender, RoutedEventArgs e) => CalculateSelectedPurchaseOrderCosts();

    private static void StampLandedCostCalculation(
        PurchaseOrderRecord order,
        DateTimeOffset calculatedAtUtc)
    {
        order.LandedCostCalculatedAtUtc =
            calculatedAtUtc.ToUniversalTime().ToString("O", CultureInfo.InvariantCulture);
        order.LandedCostCalculationVersion = LandedCostCalculationVersion;
    }

    private IReadOnlyList<string> GetPurchasingCurrencyCodes()
    {
        var codes = _nativeSettingsRows
            .Where(r => string.Equals(r.Section, "Currency", StringComparison.OrdinalIgnoreCase) &&
                        r.Parameter.StartsWith("ISK per 1 ", StringComparison.OrdinalIgnoreCase) &&
                        string.Equals(r.UsedBy, "Purchasing", StringComparison.OrdinalIgnoreCase))
            .Select(r => r.Parameter["ISK per 1 ".Length..].Trim().ToUpperInvariant())
            .Where(code => code.Length == 3)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(code => code == "ISK" ? 0 : 1)
            .ThenBy(code => code, StringComparer.OrdinalIgnoreCase)
            .ToList();
        if (!codes.Contains("ISK", StringComparer.OrdinalIgnoreCase))
            codes.Insert(0, "ISK");
        return codes.Count > 0 ? codes : new[] { "ISK", "USD", "EUR", "GBP" };
    }

    private string? GetIskRateForPurchaseCurrency(string? currency)
    {
        var code = (currency ?? string.Empty).Trim().ToUpperInvariant();
        if (code == "ISK") return "1";
        var parameter = "ISK per 1 " + code;
        var value = _nativeSettingsRows.FirstOrDefault(r =>
            string.Equals(r.Section, "Currency", StringComparison.OrdinalIgnoreCase) &&
            string.Equals(r.Parameter, parameter, StringComparison.OrdinalIgnoreCase) &&
            string.Equals(r.UsedBy, "Purchasing", StringComparison.OrdinalIgnoreCase))?.Value;
        return TryParseDecimalAware(value ?? string.Empty, out var rate) && rate > 0
            ? rate.ToString("0.####", CultureInfo.InvariantCulture)
            : null;
    }

    private sealed record LandedCostCurrencySnapshot(
        string Currency,
        string ConversionRate,
        string Source,
        string ObservationDate,
        string FetchedAtUtc);

    private static LandedCostCurrencySnapshot BuildDerivedLandedCostCurrencySnapshot(
        string landedCurrency,
        decimal invoiceIskPerUnit,
        decimal landedIskPerUnit,
        string source,
        string observationDate,
        string fetchedAtUtc) =>
        new(
            landedCurrency,
            (invoiceIskPerUnit / landedIskPerUnit).ToString(
                "0.######",
                CultureInfo.InvariantCulture),
            source,
            observationDate,
            fetchedAtUtc);

    private string GetDefaultLandedCostCurrency()
    {
        var configured = _nativeSettingsRows.FirstOrDefault(row =>
            string.Equals(row.Section, "Currency", StringComparison.OrdinalIgnoreCase) &&
            string.Equals(row.Parameter, "Default Landed Cost Currency", StringComparison.OrdinalIgnoreCase) &&
            string.Equals(row.UsedBy, "Purchasing", StringComparison.OrdinalIgnoreCase))?.Value;
        var normalized = (configured ?? string.Empty).Trim().ToUpperInvariant();
        return GetPurchasingCurrencyCodes().Contains(normalized, StringComparer.OrdinalIgnoreCase)
            ? normalized
            : "ISK";
    }

    private bool TryBuildLandedCostCurrencySnapshot(
        string? invoiceCurrency,
        string? landedCurrency,
        out LandedCostCurrencySnapshot snapshot)
    {
        var invoice = (invoiceCurrency ?? string.Empty).Trim().ToUpperInvariant();
        var landed = (landedCurrency ?? string.Empty).Trim().ToUpperInvariant();
        snapshot = new LandedCostCurrencySnapshot(landed, string.Empty, string.Empty, string.Empty, string.Empty);
        if (!GetPurchasingCurrencyCodes().Contains(invoice, StringComparer.OrdinalIgnoreCase) ||
            !GetPurchasingCurrencyCodes().Contains(landed, StringComparer.OrdinalIgnoreCase))
            return false;
        if (string.Equals(invoice, landed, StringComparison.OrdinalIgnoreCase))
        {
            snapshot = new LandedCostCurrencySnapshot(
                landed, "1", "Same-currency identity", string.Empty, string.Empty);
            return true;
        }

        var invoiceReference = _ecbExchangeRateCatalog?.Rates.FirstOrDefault(rate =>
            string.Equals(rate.Currency, invoice, StringComparison.OrdinalIgnoreCase));
        var landedReference = _ecbExchangeRateCatalog?.Rates.FirstOrDefault(rate =>
            string.Equals(rate.Currency, landed, StringComparison.OrdinalIgnoreCase));
        if (invoiceReference is not null && landedReference is not null &&
            invoiceReference.IskPerCurrencyUnit > 0 && landedReference.IskPerCurrencyUnit > 0)
        {
            snapshot = BuildDerivedLandedCostCurrencySnapshot(
                landed,
                invoiceReference.IskPerCurrencyUnit,
                landedReference.IskPerCurrencyUnit,
                EcbExchangeRateReferenceService.ProviderName + " derived ISK cross-rate",
                string.CompareOrdinal(
                    invoiceReference.ObservationDate,
                    landedReference.ObservationDate) <= 0
                    ? invoiceReference.ObservationDate
                    : landedReference.ObservationDate,
                invoiceReference.FetchedAtUtc);
            return true;
        }

        if (!TryParseDecimalAware(GetIskRateForPurchaseCurrency(invoice) ?? string.Empty, out var invoiceIsk) ||
            !TryParseDecimalAware(GetIskRateForPurchaseCurrency(landed) ?? string.Empty, out var landedIsk) ||
            invoiceIsk <= 0 || landedIsk <= 0)
            return false;
        snapshot = BuildDerivedLandedCostCurrencySnapshot(
            landed,
            Convert.ToDecimal(invoiceIsk, CultureInfo.InvariantCulture),
            Convert.ToDecimal(landedIsk, CultureInfo.InvariantCulture),
            "Manual governed Settings",
            string.Empty,
            string.Empty);
        return true;
    }

    private static bool CanOverrideLandedCostCurrency(PurchaseOrderRecord order) =>
        string.Equals(order.LifecycleStatus, "Draft", StringComparison.OrdinalIgnoreCase) &&
        string.Equals(order.CostStatus, "Draft", StringComparison.OrdinalIgnoreCase) &&
        string.IsNullOrWhiteSpace(order.LandedCostCalculatedAtUtc) &&
        string.IsNullOrWhiteSpace(order.LandedCostCalculationVersion);

    private static void ApplyLandedCostCurrencySnapshot(
        PurchaseOrderRecord order,
        LandedCostCurrencySnapshot snapshot)
    {
        order.LandedCostCurrency = snapshot.Currency;
        order.LandedCostConversionRate = snapshot.ConversionRate;
        order.LandedCostRateSource = snapshot.Source;
        order.LandedCostRateObservationDate = snapshot.ObservationDate;
        order.LandedCostRateFetchedAtUtc = snapshot.FetchedAtUtc;
    }

    private void RefreshLandedCostCurrencyReview()
    {
        if (FindName("LandedCostCurrencySelector") is not ComboBox selector ||
            FindName("LandedCostConversionRateText") is not TextBlock rateText ||
            FindName("LandedCostRateStatusText") is not TextBlock statusText ||
            FindName("ApplyLandedCostCurrencyOverride") is not Button applyButton)
            return;
        selector.ItemsSource = GetPurchasingCurrencyCodes();
        if (FindName("PurchaseOrdersGrid") is not DataGrid grid ||
            grid.SelectedItem is not PurchaseOrderRecord order)
        {
            selector.SelectedItem = null;
            selector.IsEnabled = false;
            applyButton.IsEnabled = false;
            rateText.Text = string.Empty;
            statusText.Text = "Select a Purchase Order to review its landed-cost currency snapshot.";
            return;
        }

        selector.SelectedItem = order.LandedCostCurrency;
        var canOverride = CanOverrideLandedCostCurrency(order);
        selector.IsEnabled = canOverride;
        applyButton.IsEnabled = canOverride;
        rateText.Text = string.IsNullOrWhiteSpace(order.LandedCostConversionRate)
            ? "Conversion rate requires review."
            : $"1 {order.Currency} = {order.LandedCostConversionRate} {order.LandedCostCurrency}";
        var provenance = string.IsNullOrWhiteSpace(order.LandedCostRateSource)
            ? "No valid conversion provenance is available."
            : order.LandedCostRateSource +
              (string.IsNullOrWhiteSpace(order.LandedCostRateObservationDate)
                  ? string.Empty
                  : $"; observation {order.LandedCostRateObservationDate}");
        statusText.Text = canOverride
            ? provenance + $" Allocation fields use {order.Currency}; Landed result fields use " +
              $"{order.LandedCostCurrency}. Draft override is available; applying it requires confirmation."
            : provenance + $" Allocation fields use {order.Currency}; Landed result fields use " +
              $"{order.LandedCostCurrency}. Snapshot is locked because this is not an uncalculated v53 Draft.";
    }

    private void ApplyLandedCostCurrencyOverride_Click(object sender, RoutedEventArgs e)
    {
        if (FindName("PurchaseOrdersGrid") is not DataGrid grid ||
            grid.SelectedItem is not PurchaseOrderRecord order ||
            FindName("LandedCostCurrencySelector") is not ComboBox selector)
            return;
        if (!CanOverrideLandedCostCurrency(order))
        {
            MessageBox.Show(
                this,
                "Landed-cost currency can be changed only for an uncalculated v53 Draft Purchase Order.",
                "Landed Cost Currency",
                MessageBoxButton.OK,
                MessageBoxImage.Information);
            RefreshLandedCostCurrencyReview();
            return;
        }
        var selected = selector.SelectedItem?.ToString() ?? string.Empty;
        if (!TryBuildLandedCostCurrencySnapshot(order.Currency, selected, out var snapshot))
        {
            MessageBox.Show(
                this,
                $"No governed conversion from {order.Currency} to {selected} is available. Review the purchasing currency rates in Settings Manager.",
                "Landed Cost Currency",
                MessageBoxButton.OK,
                MessageBoxImage.Warning);
            RefreshLandedCostCurrencyReview();
            return;
        }
        var confirmation = MessageBox.Show(
            this,
            $"Apply {selected} as the landed-cost currency for {order.PurchaseOrderId}?\n\n" +
            $"1 {order.Currency} = {snapshot.ConversionRate} {selected}\n" +
            $"Source: {snapshot.Source}\n\n" +
            "This stores Draft metadata only. It does not calculate or rewrite any monetary amount.",
            "Apply Draft Landed-cost Currency Override?",
            MessageBoxButton.YesNo,
            MessageBoxImage.Question,
            MessageBoxResult.No);
        if (confirmation != MessageBoxResult.Yes)
        {
            RefreshLandedCostCurrencyReview();
            return;
        }
        ApplyLandedCostCurrencySnapshot(order, snapshot);
        SavePurchaseOrders();
        RefreshLandedCostCurrencyReview();
        RefreshPurchaseOrderSummary();
    }

    private void RefreshPurchaseCurrencyChoices()
    {
        if (FindName("PurchaseOrdersGrid") is not DataGrid grid) return;
        var column = grid.Columns.OfType<DataGridComboBoxColumn>()
            .FirstOrDefault(c => string.Equals(c.Header?.ToString(), "Currency", StringComparison.OrdinalIgnoreCase));
        if (column is not null) column.ItemsSource = GetPurchasingCurrencyCodes();
        RefreshLandedCostCurrencyReview();
    }

    private void ApplyPurchaseCurrencyRate(PurchaseOrderRecord order, bool showMissingRate)
    {
        order.Currency = (order.Currency ?? "ISK").Trim().ToUpperInvariant();
        if (!_sessionNewPurchaseOrderIds.Contains(order.PurchaseOrderId))
        {
            RefreshEcbExchangeRateStatus(
                "Saved order retained its original exchange rate.");
            return;
        }

        var reference = _ecbExchangeRateCatalog?.Rates.FirstOrDefault(rate =>
            string.Equals(rate.Currency, order.Currency, StringComparison.OrdinalIgnoreCase));
        if (reference is not null)
        {
            order.ExchangeRate = reference.IskPerCurrencyUnit.ToString(
                "0.######",
                CultureInfo.InvariantCulture);
            order.ExchangeRateSource = reference.Source;
            order.ExchangeRateObservationDate = reference.ObservationDate;
            order.ExchangeRateFetchedAtUtc = reference.FetchedAtUtc;
            SchedulePurchaseOrderGridRefresh();
            RefreshEcbExchangeRateStatus(
                $"{order.Currency} reference {order.ExchangeRate} ISK; " +
                $"ECB observation {order.ExchangeRateObservationDate}. " +
                "Prefilled only for this new order.");
            return;
        }

        var rate = GetIskRateForPurchaseCurrency(order.Currency);
        if (rate is not null)
        {
            order.ExchangeRate = rate;
            order.ExchangeRateSource = "Manual governed Settings";
            order.ExchangeRateObservationDate = string.Empty;
            order.ExchangeRateFetchedAtUtc = string.Empty;
            SchedulePurchaseOrderGridRefresh();
            RefreshEcbExchangeRateStatus(
                $"{order.Currency} used the manual governed Settings fallback.");
            return;
        }
        order.ExchangeRate = string.Empty;
        order.ExchangeRateSource = string.Empty;
        order.ExchangeRateObservationDate = string.Empty;
        order.ExchangeRateFetchedAtUtc = string.Empty;
        SchedulePurchaseOrderGridRefresh();
        if (showMissingRate)
            MessageBox.Show(this, $"No valid ISK exchange rate is configured for {order.Currency}. Update 'ISK per 1 {order.Currency}' in Settings Manager.", "Purchase Currency", MessageBoxButton.OK, MessageBoxImage.Information);
    }

    private string EcbExchangeRateCachePath()
        => StorageWorkingFilePath("ecb-exchange-rate-reference-cache.json");

    private static bool EcbExchangeRateCatalogNeedsRefresh(
        ExchangeRateReferenceCatalog? catalog,
        DateTime utcNow)
    {
        if (catalog is null ||
            !DateTime.TryParse(
                catalog.FetchedAtUtc,
                CultureInfo.InvariantCulture,
                DateTimeStyles.RoundtripKind,
                out var fetchedAt))
            return true;
        return utcNow.ToUniversalTime() - fetchedAt.ToUniversalTime() > TimeSpan.FromDays(1);
    }

    private async Task RefreshEcbExchangeRateCatalogAsync(bool showFailure)
    {
        if (AutomationRuntimeProfile.Current is not null)
        {
            RefreshEcbExchangeRateStatus(
                "Automation is offline; deterministic ECB parser checks are used.");
            return;
        }

        RefreshEcbExchangeRateStatus("Downloading ECB reference observations...");
        try
        {
            _ecbExchangeRateCatalog =
                await _ecbExchangeRateReferenceService.FetchAsync(
                    EcbExchangeRateCachePath());
            RefreshEcbExchangeRateStatus();
        }
        catch (Exception ex)
        {
            _ecbExchangeRateCatalog =
                EcbExchangeRateReferenceService.LoadCache(EcbExchangeRateCachePath());
            RefreshEcbExchangeRateStatus(
                _ecbExchangeRateCatalog is null
                    ? "ECB unavailable; new orders retain the manual governed Settings workflow."
                    : "ECB unavailable; cached reference retained. " + ex.Message);
            if (showFailure && _ecbExchangeRateCatalog is null)
                MessageBox.Show(
                    this,
                    "ECB reference rates could not be downloaded. " +
                    "The new order will use manual governed Settings values.\n\n" +
                    ex.Message,
                    "ECB Exchange-rate Reference",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
        }
    }

    private void RefreshEcbExchangeRateStatus(string? explicitStatus = null)
    {
        if (FindName("EcbExchangeRateStatusText") is not TextBlock text) return;
        if (!string.IsNullOrWhiteSpace(explicitStatus))
        {
            text.Text = explicitStatus;
            return;
        }

        var latest = _ecbExchangeRateCatalog?.Rates
            .Select(rate => rate.ObservationDate)
            .OrderByDescending(value => value, StringComparer.Ordinal)
            .FirstOrDefault();
        var hasFetchedAt = DateTime.TryParse(
                        _ecbExchangeRateCatalog?.FetchedAtUtc,
                        CultureInfo.InvariantCulture,
                        DateTimeStyles.RoundtripKind,
                        out var fetched);
        var stale = hasFetchedAt &&
                    DateTime.UtcNow - fetched.ToUniversalTime() > TimeSpan.FromDays(1);
        var fetchedLabel = hasFetchedAt
            ? $"; fetched {fetched.ToUniversalTime():yyyy-MM-dd HH:mm} UTC"
            : string.Empty;
        text.Text = latest is null
            ? "ECB reference not cached. Manual governed Settings remain available."
            : $"ECB-derived reference cache{(stale ? " (stale)" : "")}: observation {latest}; " +
              $"applies only to new orders created in this session{fetchedLabel}.";
    }

    private async void RefreshEcbExchangeRates_Click(object sender, RoutedEventArgs e)
        => await RefreshEcbExchangeRateCatalogAsync(showFailure: true);

    private void SchedulePurchaseOrderGridRefresh()
    {
        if (FindName("PurchaseOrdersGrid") is not DataGrid grid) return;
        grid.Dispatcher.BeginInvoke(new Action(() =>
        {
            if (grid.Items is IEditableCollectionView editableView &&
                (editableView.IsAddingNew || editableView.IsEditingItem))
            {
                SchedulePurchaseOrderGridRefresh();
                return;
            }

            grid.Items.Refresh();
        }), DispatcherPriority.ApplicationIdle);
    }

    private void RefreshPurchaseMaterialChoices()
    {
        if (FindName("PurchaseOrderLinesGrid") is not DataGrid grid) return;
        if (grid.Columns.OfType<DataGridComboBoxColumn>().FirstOrDefault(c => (c.Header?.ToString() ?? "").Contains("material", StringComparison.OrdinalIgnoreCase)) is not { } column) return;
        var choices = _nativeMaterialRows.Where(m => !m.IsArchived && !string.IsNullOrWhiteSpace(m.MaterialID))
            .Select(m => new KeyValuePair<string,string>(m.MaterialID, $"{m.Manufacturer} {m.WebsiteDisplayName}".Trim()))
            .OrderBy(x => x.Value, StringComparer.CurrentCultureIgnoreCase).ToList();
        column.ItemsSource = choices;
        var labels = choices.ToDictionary(x=>x.Key,x=>x.Value,StringComparer.OrdinalIgnoreCase);
        foreach(var line in _purchaseOrderLines) line.MaterialDisplayName = labels.TryGetValue(line.MaterialId,out var label)?label:line.MaterialId;
    }

    private async void AddPurchaseOrder_Click(object sender, RoutedEventArgs e)
    {
        if (EcbExchangeRateCatalogNeedsRefresh(_ecbExchangeRateCatalog, DateTime.UtcNow))
            await RefreshEcbExchangeRateCatalogAsync(showFailure: false);
        var order = new PurchaseOrderRecord
        {
            PurchaseOrderId = "PO-" + DateTime.Now.ToString(
                "yyyyMMdd-HHmmss",
                CultureInfo.InvariantCulture),
            PurchaseDate = DateTime.Today.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture),
            Currency = "ISK",
            ExchangeRate = "1",
            ExchangeRateSource = _ecbExchangeRateCatalog is null
                ? "Manual governed Settings"
                : EcbExchangeRateReferenceService.ProviderName,
            ExchangeRateObservationDate = _ecbExchangeRateCatalog?.Rates
                .FirstOrDefault(rate => rate.Currency == "ISK")?.ObservationDate ?? string.Empty,
            ExchangeRateFetchedAtUtc = _ecbExchangeRateCatalog?.FetchedAtUtc ?? string.Empty,
            TaxTreatment = "VAT included in invoice",
            CostStatus = "Draft",
            LifecycleStatus = "Draft",
            ShippingAllocationMethod = "Automatic",
            TaxAllocationMethod = "By line value",
            CustomsAllocationMethod = "By line value",
            FeeAllocationMethod = "By line value"
        };
        var defaultLandedCurrency = GetDefaultLandedCostCurrency();
        if (!TryBuildLandedCostCurrencySnapshot(
                order.Currency,
                defaultLandedCurrency,
                out var landedSnapshot))
        {
            _ = TryBuildLandedCostCurrencySnapshot(
                order.Currency,
                "ISK",
                out landedSnapshot);
        }
        ApplyLandedCostCurrencySnapshot(order, landedSnapshot);
        _sessionNewPurchaseOrderIds.Add(order.PurchaseOrderId);
        _purchaseOrders.Add(order); SavePurchaseOrders();
        if (FindName("PurchaseOrdersGrid") is DataGrid grid) { grid.SelectedItem=order; grid.ScrollIntoView(order); }
        RefreshPurchaseOrderSummary();
        RefreshEcbExchangeRateStatus(
            $"New order created. Landed-cost currency default {order.LandedCostCurrency} was snapshotted for this Draft only.");
        RefreshLandedCostCurrencyReview();
    }

    private void DeletePurchaseOrder_Click(object sender, RoutedEventArgs e)
    {
        if (IsAutomationActionBlocked("Purchase Order deletion")) return;
        if (FindName("PurchaseOrdersGrid") is not DataGrid grid || grid.SelectedItem is not PurchaseOrderRecord order) return;
        if (MessageBox.Show(this, "Delete selected purchase order and its lines? Existing inventory spools are not deleted.", "Purchase Orders", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
        foreach(var line in _purchaseOrderLines.Where(x=>x.PurchaseOrderId==order.PurchaseOrderId).ToList()) _purchaseOrderLines.Remove(line);
        _purchaseOrders.Remove(order); SavePurchaseOrders(); _purchaseOrderLineView?.Refresh(); RefreshPurchaseOrderSummary();
    }

    private void PurchaseOrdersGrid_SelectionChanged(object sender, SelectionChangedEventArgs e)
    {
        _purchaseOrderLineView?.Refresh();
        RefreshPurchaseOrderSummary();
        RefreshLandedCostCurrencyReview();
    }

    private void AddPurchaseOrderLine_Click(object sender, RoutedEventArgs e)
    {
        if (FindName("PurchaseOrdersGrid") is not DataGrid grid || grid.SelectedItem is not PurchaseOrderRecord order) { MessageBox.Show(this,"Create or select a purchase order first.","Purchase Orders",MessageBoxButton.OK,MessageBoxImage.Information); return; }
        if (!string.IsNullOrWhiteSpace(order.LandedCostCalculationVersion))
