    private void PurchaseOrderGrid_BeginningEdit(object sender, DataGridBeginningEditEventArgs e)
    {
        if (!IsPurchaseOrderFinancialEditLocked(sender as DataGrid, e.Row.Item, e.Column.Header?.ToString()))
        {
            return;
        }

        e.Cancel = true;
        ShowTransientStatus("Calculated landed-cost inputs are locked; saved results were not changed.");
    }

    private void PurchaseOrderGrid_CellEditEnding(object sender, DataGridCellEditEndingEventArgs e)
    {
        if (IsPurchaseOrderFinancialEditLocked(sender as DataGrid, e.Row.Item, e.Column.Header?.ToString()))
        {
            e.Cancel = true;
            ShowTransientStatus("Calculated landed-cost inputs are locked; saved results were not changed.");
            return;
        }
        var editedCurrency = sender is DataGrid grid && ReferenceEquals(grid, FindName("PurchaseOrdersGrid")) &&
                             string.Equals(e.Column.Header?.ToString(), "Currency", StringComparison.OrdinalIgnoreCase);
        var order = e.Row.Item as PurchaseOrderRecord;
        Dispatcher.BeginInvoke(new Action(() =>
        {
            if (editedCurrency && order is not null)
            {
                ApplyPurchaseCurrencyRate(order, showMissingRate: true);
                if (_sessionNewPurchaseOrderIds.Contains(order.PurchaseOrderId) &&
                    CanOverrideLandedCostCurrency(order) &&
                    TryBuildLandedCostCurrencySnapshot(
                        order.Currency,
                        order.LandedCostCurrency,
                        out var landedSnapshot))
                {
                    ApplyLandedCostCurrencySnapshot(order, landedSnapshot);
                }
            }
            SavePurchaseOrders();
            RefreshPurchaseMaterialChoices();
            RefreshPurchaseOrderSummary();
            RefreshLandedCostCurrencyReview();
        }), DispatcherPriority.Background);
    }

    private bool IsPurchaseOrderFinancialEditLocked(DataGrid? grid, object? rowItem, string? header)
    {
        var protectedOrder = rowItem switch
        {
            PurchaseOrderRecord order => order,
            PurchaseOrderLineRecord line => _purchaseOrders.FirstOrDefault(candidate =>
                string.Equals(candidate.PurchaseOrderId, line.PurchaseOrderId, StringComparison.OrdinalIgnoreCase)),
            _ => null
        };
        return IsPurchaseOrderFinancialEditLocked(grid, protectedOrder, header);
    }

    private bool IsPurchaseOrderFinancialEditLocked(
        DataGrid? grid,
        PurchaseOrderRecord? protectedOrder,
        string? header) =>
        !string.IsNullOrWhiteSpace(protectedOrder?.LandedCostCalculationVersion) &&
               IsLandedCostInputColumn(grid, header);

    private bool IsLandedCostInputColumn(DataGrid? grid, string? header)
    {
        if (grid is null || string.IsNullOrWhiteSpace(header)) return false;
        if (ReferenceEquals(grid, FindName("PurchaseOrdersGrid")))
        {
            return header is
                "Currency" or "1 currency unit = ISK" or "Tax treatment" or
                "Items total" or "Shipping" or "Shipping allocation" or
                "Supplier VAT" or "Invoice total" or "Import VAT" or
                "Customs" or "Clearance" or "Other fees";
        }
        if (ReferenceEquals(grid, FindName("PurchaseOrderLinesGrid")))
        {
            return header is
                "Expected" or "Unit price" or "Discount" or "Unit weight g" or
                "Allocate" or "Manual shipping";
        }
        return false;
    }

    private int SyncLinkedMaterialsFromPurchaseOrder(PurchaseOrderRecord order, IReadOnlyList<PurchaseOrderLineRecord> lines)
    {
        var synced = 0;
        foreach (var line in lines.Where(x => !string.IsNullOrWhiteSpace(x.MaterialId)))
        {
            var material = _nativeMaterialRows.FirstOrDefault(x =>
                string.Equals(x.MaterialID, line.MaterialId, StringComparison.OrdinalIgnoreCase));
            if (material is null) continue;

            SyncMaterialPricingFromPurchaseLine(material, line, order);
            synced++;
        }
        return synced;
    }

    private void SyncMaterialPricingFromPurchaseLine(NativeMaterialRow material, PurchaseOrderLineRecord line, PurchaseOrderRecord? order)
    {
        var currency = string.IsNullOrWhiteSpace(order?.Currency) ? "ISK" : order.Currency.Trim().ToUpperInvariant();
        var landedCurrency = string.IsNullOrWhiteSpace(order?.LandedCostCurrency)
            ? currency
            : order.LandedCostCurrency.Trim().ToUpperInvariant();
        var spoolWeight = string.IsNullOrWhiteSpace(line.UnitWeightG) ? material.SpoolWeightG : line.UnitWeightG;

        material.PurchaseId = order?.PurchaseOrderId ?? material.PurchaseId;
        material.PurchasedFrom = order?.Supplier ?? material.PurchasedFrom;
        material.PurchaseDate = order?.PurchaseDate ?? material.PurchaseDate;
        material.OrderNumber = order?.OrderNumber ?? material.OrderNumber;
        material.ManufacturerSku = string.IsNullOrWhiteSpace(line.Sku) ? material.ManufacturerSku : line.Sku;
        material.StorageLocation = string.IsNullOrWhiteSpace(line.StorageLocation) ? material.StorageLocation : line.StorageLocation.Trim();
        material.SpoolWeightG = spoolWeight;

        // In this database MSRP is intentionally the original purchase/unit price.
        // This preserves the user's established pricing workflow while keeping the
        // landed cost as the true all-in cost after shipping, tax and fees.
        material.PurchasePriceAmount = line.UnitPrice;
        material.PurchaseCurrency = currency;
        material.MsrpAmount = line.UnitPrice;
        material.MsrpCurrency = currency;

        material.ShippingAmount = PerUnit(line.AllocatedShipping, line.Quantity);
        material.VatAmount = PerUnit(line.AllocatedTax, line.Quantity);
        material.LandedCostAmount = line.LandedUnitCost;
        material.LandedCostCurrency = landedCurrency;
        material.PriceCheckedDate = string.IsNullOrWhiteSpace(order?.PurchaseDate)
            ? material.PriceCheckedDate
            : order.PurchaseDate;

        ApplyNativeMaterialComputedFields(material, _nativeMaterialRows.IndexOf(material));
    }

    private NativeMaterialRow? CreateMaterialFromPurchaseLine(PurchaseOrderLineRecord line, PurchaseOrderRecord? order, bool showValidationMessages)
    {
        if (!string.Equals(line.InventoryCategory, "Filament", StringComparison.OrdinalIgnoreCase))
            return null;
        if (!string.IsNullOrWhiteSpace(line.MaterialId))
            return _nativeMaterialRows.FirstOrDefault(x => string.Equals(x.MaterialID, line.MaterialId, StringComparison.OrdinalIgnoreCase));

        if (string.IsNullOrWhiteSpace(line.Description))
        {
            if (showValidationMessages)
                MessageBox.Show(this, "Enter the ordered item / invoice description first.", "Purchase Orders", MessageBoxButton.OK, MessageBoxImage.Information);
            return null;
        }

        var material = new NativeMaterialRow
        {
            MaterialID = GenerateNextNativeMaterialId(),
            Manufacturer = string.IsNullOrWhiteSpace(order?.Supplier) ? "New manufacturer" : order.Supplier,
            ProductLine = "Purchase import",
            MarketingName = line.Description.Trim(),
            BaseMaterial = "PLA",
            MaterialCategory = "Standard",
            DiameterMm = "1.75",
            SpoolWeightG = string.IsNullOrWhiteSpace(line.UnitWeightG) ? "1000" : line.UnitWeightG,
            ManufacturerSku = line.Sku,
            StorageLocation = line.StorageLocation?.Trim() ?? "",
            PurchasedFrom = order?.Supplier ?? "",
            PurchaseDate = order?.PurchaseDate ?? "",
            OrderNumber = order?.OrderNumber ?? "",
            PurchasePriceAmount = line.UnitPrice,
            PurchaseCurrency = order?.Currency ?? "ISK",
            MsrpAmount = line.UnitPrice,
            MsrpCurrency = order?.Currency ?? "ISK",
            ShippingAmount = PerUnit(line.AllocatedShipping, line.Quantity),
            VatAmount = PerUnit(line.AllocatedTax, line.Quantity),
            LandedCostAmount = line.LandedUnitCost,
            LandedCostCurrency = string.IsNullOrWhiteSpace(order?.LandedCostCurrency)
                ? order?.Currency ?? "ISK"
                : order.LandedCostCurrency,
            PriceCheckedDate = order?.PurchaseDate ?? "",
            PurchaseId = order?.PurchaseOrderId ?? "",
            InventoryStatus = "Unopened",
            Quantity = "0",
            RemainingWeightG = string.IsNullOrWhiteSpace(line.UnitWeightG) ? "1000" : line.UnitWeightG,
            Video = "No", TestedStatus = "Not tested", InTensile = "No", InImpact = "No", InStiffness = "No",
            SourcePriority = "Purchase order", IsArchived = false
        };

        ApplyNativeMaterialComputedFields(material, _nativeMaterialRows.Count);
        _nativeMaterialRows.Add(material);
        SyncMaterialPricingFromPurchaseLine(material, line, order);
        line.MaterialId = material.MaterialID;
        return material;
    }

    private void CreateMaterialFromPurchaseLine_Click(object sender, RoutedEventArgs e)
    {
        CommitPurchaseOrderEdits();
        if (FindName("PurchaseOrderLinesGrid") is not DataGrid grid || grid.SelectedItem is not PurchaseOrderLineRecord line)
        {
            MessageBox.Show(this, "Select an ordered item first.", "Purchase Orders", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }
        if (!string.Equals(line.InventoryCategory, "Filament", StringComparison.OrdinalIgnoreCase))
        {
            MessageBox.Show(this, $"'{line.InventoryCategory}' lines stay on the Purchase Order but do not create Material or Inventory Spool records. Only Filament lines use the material receiving workflow.", "Purchase Orders", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }
        if (!string.IsNullOrWhiteSpace(line.MaterialId))
        {
            var label = _nativeMaterialRows.FirstOrDefault(x => string.Equals(x.MaterialID, line.MaterialId, StringComparison.OrdinalIgnoreCase))?.WebsiteDisplayName;
            MessageBox.Show(this, string.IsNullOrWhiteSpace(label)
                ? "This ordered item is already linked to a material."
                : $"This ordered item is already linked to '{label}'.", "Purchase Orders", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }

        var order = _purchaseOrders.FirstOrDefault(x => x.PurchaseOrderId == line.PurchaseOrderId);
        var material = CreateMaterialFromPurchaseLine(line, order, showValidationMessages: true);
        if (material is null) return;

        SaveNativeMaterialsSilent();
        SavePurchaseOrders();
        RefreshPurchaseMaterialChoices();
        grid.Items.Refresh();
        RefreshPurchaseOrderSummary();
        MessageBox.Show(this, $"Created {material.MaterialID}: {material.WebsiteDisplayName}\n\nThe purchase line is now linked. Review and complete the material fields before testing.", "Purchase Orders", MessageBoxButton.OK, MessageBoxImage.Information);
    }

    private void CommitPurchaseOrderEdits(bool save = true)
    {
        if (FindName("PurchaseOrdersGrid") is DataGrid ordersGrid)
        {
            ordersGrid.CommitEdit(DataGridEditingUnit.Cell, true);
            ordersGrid.CommitEdit(DataGridEditingUnit.Row, true);
        }
        if (FindName("PurchaseOrderLinesGrid") is DataGrid linesGrid)
        {
            linesGrid.CommitEdit(DataGridEditingUnit.Cell, true);
            linesGrid.CommitEdit(DataGridEditingUnit.Row, true);
        }
        if (save) SavePurchaseOrders();
    }

    private void ReceivePurchaseOrder_Click(object sender, RoutedEventArgs e)
    {
        if (FindName("PurchaseOrdersGrid") is not DataGrid grid || grid.SelectedItem is not PurchaseOrderRecord order) return;
        var lines = _purchaseOrderLines.Where(x => x.PurchaseOrderId == order.PurchaseOrderId).ToList();
        if (lines.Count == 0) { MessageBox.Show(this, "Add the ordered items first.", "Receiving", MessageBoxButton.OK, MessageBoxImage.Information); return; }
        foreach (var line in lines)
        {
            if (string.IsNullOrWhiteSpace(line.ReceivedQuantity) || line.ReceivedQuantity == "0") line.ReceivedQuantity = line.Quantity;
            if (line.ReceivingStatus == "Not checked") line.ReceivingStatus = line.ReceivedQuantity == line.Quantity ? "Correct" : "Missing";
        }
        order.LifecycleStatus = "Receiving";
        order.ReceivedDate = string.IsNullOrWhiteSpace(order.ReceivedDate) ? DateTime.Today.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture) : order.ReceivedDate;
        SavePurchaseOrders(); grid.Items.Refresh();
        if (FindName("PurchaseOrderLinesGrid") is DataGrid lineGrid) lineGrid.Items.Refresh();
        RefreshPurchaseOrderSummary();
        MessageBox.Show(this, "Expected quantities were copied into Received. Count the box, correct any differences, set each Check status, then link or create materials.", "Receiving started", MessageBoxButton.OK, MessageBoxImage.Information);
    }

    private void CreateInventoryFromPurchaseOrder_Click(object sender, RoutedEventArgs e)
    {
        CommitPurchaseOrderEdits();
        if (FindName("PurchaseOrdersGrid") is not DataGrid grid || grid.SelectedItem is not PurchaseOrderRecord order) return;
        if (!string.Equals(
                order.LandedCostCalculationVersion,
                LandedCostCalculationVersion,
                StringComparison.Ordinal) ||
            string.IsNullOrWhiteSpace(order.LandedCostCalculatedAtUtc))
        {
            MessageBox.Show(
                this,
                "Calculate and save the landed-cost snapshot before creating Inventory spools.",
                "Landed Cost Required",
                MessageBoxButton.OK,
                MessageBoxImage.Information);
            return;
        }

        var lines = _purchaseOrderLines.Where(x => x.PurchaseOrderId == order.PurchaseOrderId).ToList();
        var receivedLines = lines.Where(x => ParsePositiveInt(x.ReceivedQuantity) > 0).ToList();
        var filamentLines = receivedLines.Where(x => string.Equals(x.InventoryCategory, "Filament", StringComparison.OrdinalIgnoreCase)).ToList();
        var deferredLines = receivedLines.Count - filamentLines.Count;
        if (receivedLines.Count == 0)
        {
            MessageBox.Show(this, "No received quantities have been entered. Use Receive / Reconcile and confirm the box contents first.", "Purchase Orders", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }

        var missingDescriptions = filamentLines.Where(x => string.IsNullOrWhiteSpace(x.MaterialId) && string.IsNullOrWhiteSpace(x.Description)).ToList();
        if (missingDescriptions.Count > 0)
        {
            MessageBox.Show(this, $"{missingDescriptions.Count} received line(s) have neither a linked material nor an ordered-item description. Enter a description before creating inventory.", "Purchase Orders", MessageBoxButton.OK, MessageBoxImage.Warning);
            return;
        }

        var autoCreateLines = filamentLines.Where(x => string.IsNullOrWhiteSpace(x.MaterialId)).ToList();
        if (autoCreateLines.Count > 0)
        {
            var result = MessageBox.Show(this,
                $"{autoCreateLines.Count} received line(s) are not linked to an existing material.\n\nCreate a new draft material for each of these lines and continue creating the received inventory spools?",
                "Create materials and inventory", MessageBoxButton.YesNo, MessageBoxImage.Question);
            if (result != MessageBoxResult.Yes) return;
        }

        var createdMaterials = 0;
        foreach (var line in autoCreateLines)
        {
            if (CreateMaterialFromPurchaseLine(line, order, showValidationMessages: false) is not null)
                createdMaterials++;
        }

        // Persist and refresh material links before generating inventory records.
        if (createdMaterials > 0)
        {
            SaveNativeMaterialsSilent();
            SavePurchaseOrders();
            RefreshPurchaseMaterialChoices();
        }

        var createdSpools = 0;
        foreach (var line in filamentLines)
        {
            if (string.IsNullOrWhiteSpace(line.MaterialId)) continue;
            var target = ParsePositiveInt(line.ReceivedQuantity);
            var existing = _inventorySpoolRows.Count(x => x.PurchaseOrderLineId == line.PurchaseOrderLineId);
            for (var i = existing; i < target; i++)
            {
                _inventorySpoolRows.Add(BuildInventorySpoolFromPurchaseLine(order, line));
                createdSpools++;
            }
        }

        SaveInventorySpools();
        SyncMaterialInventoryQuantityFromSpools(true);
        RefreshInventoryMaterialChoices();
        RefreshInventorySummary();
        if (createdSpools > 0 || createdMaterials > 0) order.LifecycleStatus = "Inventory created";
        SavePurchaseOrders();
        grid.Items.Refresh();
        if (FindName("PurchaseOrderLinesGrid") is DataGrid lineGrid) lineGrid.Items.Refresh();
        RefreshPurchaseOrderSummary();

        var deferredNote = deferredLines > 0
            ? $"\n\n{deferredLines} received non-filament line(s) remain recorded on the Purchase Order and were not converted into Material/Spool records."
            : string.Empty;
        var message = createdSpools > 0 || createdMaterials > 0
            ? $"Created {createdMaterials} new material record(s) and {createdSpools} received inventory spool record(s).\n\nStorage locations were copied to the individual Inventory Spools.{deferredNote}"
            : "No new filament materials or spools were needed." + deferredNote;
        MessageBox.Show(this, message, "Purchase Orders", MessageBoxButton.OK, MessageBoxImage.Information);
    }

    private static InventorySpoolRecord BuildInventorySpoolFromPurchaseLine(
        PurchaseOrderRecord order,
        PurchaseOrderLineRecord line) =>
        new()
        {
            InventoryItemId = "INV-" + Guid.NewGuid().ToString("N")[..8].ToUpperInvariant(),
            MaterialId = line.MaterialId,
            PurchaseOrderLineId = line.PurchaseOrderLineId,
            PurchaseId = order.PurchaseOrderId,
            PurchasedFrom = order.Supplier,
            PurchaseDate = order.PurchaseDate,
            OrderNumber = order.OrderNumber,
            PurchasePriceAmount = line.UnitPrice,
            PurchaseCurrency = order.Currency,
            ShippingAmount = PerUnit(line.AllocatedShipping, line.Quantity),
            VatAmount = PerUnit(line.AllocatedTax, line.Quantity),
            CustomsAmount = PerUnit(line.AllocatedCustoms, line.Quantity),
            OtherFeesAmount = PerUnit(line.AllocatedFees, line.Quantity),
            LandedCostAmount = line.LandedUnitCost,
            LandedCostCurrency = order.LandedCostCurrency,
            LandedCostConversionRate = order.LandedCostConversionRate,
            LandedCostRateSource = order.LandedCostRateSource,
            LandedCostRateObservationDate = order.LandedCostRateObservationDate,
            LandedCostRateFetchedAtUtc = order.LandedCostRateFetchedAtUtc,
            LandedCostCalculatedAtUtc = order.LandedCostCalculatedAtUtc,
            LandedCostCalculationVersion = order.LandedCostCalculationVersion,
            SpoolWeightG = line.UnitWeightG,
            RemainingWeightG = line.UnitWeightG,
            StorageLocation = line.StorageLocation,
            Quantity = "1",
            Status = "Unopened"
        };

    private static string PerUnit(string? total, string? quantity)
    {
        if (!decimal.TryParse(total, NumberStyles.Any, CultureInfo.CurrentCulture, out var t) && !decimal.TryParse(total?.Replace(',','.'), NumberStyles.Any, CultureInfo.InvariantCulture, out t)) return string.Empty;
        var q = ParsePositiveInt(quantity); return q > 0 ? (t / q).ToString("0.00", CultureInfo.CurrentCulture) : string.Empty;
    }

    private static int ParsePositiveInt(string? value) => int.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed) && parsed > 0 ? parsed : 0;

    private void BrowsePurchaseInvoice_Click(object sender, RoutedEventArgs e)
    {
        if (FindName("PurchaseOrdersGrid") is not DataGrid grid || grid.SelectedItem is not PurchaseOrderRecord order) return;
        var dialog=new OpenFileDialog { Filter="Order documents|*.pdf;*.png;*.jpg;*.jpeg|All files|*.*" };
        if(dialog.ShowDialog(this)==true)
        {
            var year = DateTime.TryParse(order.PurchaseDate, CultureInfo.InvariantCulture, DateTimeStyles.None, out var date) ? date.Year.ToString(CultureInfo.InvariantCulture) : DateTime.Today.Year.ToString(CultureInfo.InvariantCulture);
            var folder = System.IO.Path.Combine(_database.DatabaseFolder, "Invoices", year);
            Directory.CreateDirectory(folder);
            var supplier = string.Concat((order.Supplier ?? "Supplier").Select(ch => System.IO.Path.GetInvalidFileNameChars().Contains(ch) ? '_' : ch));
            var number = string.Concat((order.OrderNumber ?? order.PurchaseOrderId).Select(ch => System.IO.Path.GetInvalidFileNameChars().Contains(ch) ? '_' : ch));
            var target = System.IO.Path.Combine(folder, $"{supplier}_{number}{System.IO.Path.GetExtension(dialog.FileName)}");
            System.IO.File.Copy(dialog.FileName, target, true);
            order.InvoiceFile = System.IO.Path.GetRelativePath(_database.DatabaseFolder, target);
            SavePurchaseOrders(); grid.Items.Refresh(); RefreshPurchaseOrderSummary();
        }
    }

    private void RefreshPurchaseOrderSummary()
    {
        if (FindName("PurchaseOrderSummaryText") is not TextBlock text) return;
        if (FindName("PurchaseOrdersGrid") is not DataGrid grid || grid.SelectedItem is not PurchaseOrderRecord order)
        {
            text.Text="Select a purchase order.";
            if (FindName("PurchaseCostValidationText") is TextBlock emptyValidation) emptyValidation.Text = "Cost allocation validation will appear here after calculation.";
            return;
        }
        var lines=_purchaseOrderLines.Where(x=>x.PurchaseOrderId==order.PurchaseOrderId).ToList();
        var qty=lines.Sum(x=>int.TryParse(x.Quantity,NumberStyles.Integer,CultureInfo.InvariantCulture,out var q)?Math.Max(0,q):0);
        var received=lines.Sum(x=>ParsePositiveInt(x.ReceivedQuantity));
        var linked=lines.Count(x=>!string.IsNullOrWhiteSpace(x.MaterialId));
        var issues=lines.Count(x=>x.ReceivingStatus is "Missing" or "Damaged" or "Extra");
        text.Text=$"Stage: {order.LifecycleStatus} • {lines.Count} item line(s) • Expected {qty} • Received {received} • Materials linked {linked}/{lines.Count} • Receiving issues {issues} • Tax: {order.TaxTreatment}";
    }

    private void InitializeExperimentalMaterialManager()
    {
        _experimentDefinitions.Clear();
        _experimentDefinitions.AddRange(_database.LoadExperimentDefinitions(activeOnly: true));
        foreach (var row in _database.LoadMaterialExperiments()) _materialExperimentRows.Add(row);
        foreach (var run in _database.LoadExperimentalRuns()) _experimentalRunRows.Add(run);
        foreach (var measurement in _database.LoadExperimentalMeasurements()) _experimentalMeasurementRows.Add(measurement);
        RefreshExperimentalChoices();
        if (FindName("MaterialExperimentsGrid") is DataGrid grid)
        {
            _materialExperimentView = new ListCollectionView(_materialExperimentRows);
            _materialExperimentView.Filter = MaterialExperimentFilter;
            grid.ItemsSource = _materialExperimentView;
        }
        if (FindName("ExperimentalRunsGrid") is DataGrid runsGrid)
        {
            _experimentalRunView = new ListCollectionView(_experimentalRunRows);
            _experimentalRunView.Filter = item => item is ExperimentalRunRecord run && _selectedExperimentalSeries is not null && run.MaterialExperimentId == _selectedExperimentalSeries.MaterialExperimentId;
            runsGrid.ItemsSource = _experimentalRunView;
        }
        ClearExperimentalMeasurementEditors();
        if (FindName("ExperimentalResultsGrid") is DataGrid resultsGrid) resultsGrid.ItemsSource = _experimentalSeriesResultRows;
        RefreshExperimentalSeriesResults();
        // Experimental records are persisted explicitly by the CRUD/edit workflows.
        // Do not save from CollectionChanged: ObservableCollection raises that event while
        // ListCollectionView is still processing Add/Remove, and re-entering persistence/UI
        // refresh from that event can throw InvalidOperationException in WPF.
        RefreshExperimentalStatus();
        RefreshExperimentalPublicationReadiness();
    }


    private void ClearExperimentalMeasurementEditors()
    {
        foreach (var gridName in new[] { "ExperimentalTensileGrid", "ExperimentalImpactGrid", "ExperimentalStiffnessGrid" })
            if (FindName(gridName) is DataGrid grid) grid.ItemsSource = null;
    }

    private void BindExperimentalMeasurementEditors(ExperimentalRunRecord? run)
    {
        if (run is null)
        {
            ClearExperimentalMeasurementEditors();
            return;
        }

        // Use fixed per-run row lists instead of CollectionView filters over the shared collection.
        // The editor rows must never disappear while a cell is being edited or when another editor tab is selected.
        var runRows = _experimentalMeasurementRows
            .Where(x => string.Equals(x.ExperimentalRunId, run.ExperimentalRunId, StringComparison.Ordinal))
            .ToList();

        SetExperimentalEditorRows("ExperimentalTensileGrid", runRows
            .Where(x => x.MeasurementType == "Tensile")
            .OrderBy(x => x.Orientation == "Upright" ? 0 : 1)
            .ToList());
        SetExperimentalEditorRows("ExperimentalImpactGrid", runRows
            .Where(x => x.MeasurementType == "Impact")
            .OrderBy(x => x.Orientation == "Upright" ? 0 : 1)
            .ToList());
        SetExperimentalEditorRows("ExperimentalStiffnessGrid", runRows
            .Where(x => x.MeasurementType == "Stiffness")
            .ToList());
    }

    private void SetExperimentalEditorRows(string gridName, IReadOnlyList<ExperimentalMeasurementRecord> rows)
    {
        if (FindName(gridName) is not DataGrid grid) return;
        grid.ItemsSource = null;
        grid.ItemsSource = rows;
        grid.Visibility = Visibility.Visible;
        grid.UpdateLayout();
    }

    private void RefreshExperimentalChoices()
    {
        if (FindName("MaterialExperimentsGrid") is not DataGrid grid) return;
        var materialChoices = _nativeMaterialRows
            .Where(m => !m.IsArchived && !string.IsNullOrWhiteSpace(m.MaterialID))
            .Select(m => new KeyValuePair<string, string>(m.MaterialID, $"{m.Manufacturer} {m.WebsiteDisplayName}".Trim()))
            .OrderBy(x => x.Value, StringComparer.CurrentCultureIgnoreCase).ThenBy(x => x.Key, StringComparer.OrdinalIgnoreCase).ToList();
        var definitionChoices = _experimentDefinitions
            .Select(d => new KeyValuePair<string, string>(d.ExperimentDefinitionId, d.Name)).ToList();
        foreach (var column in grid.Columns.OfType<DataGridComboBoxColumn>())
        {
            var header = column.Header?.ToString() ?? string.Empty;
            if (header == "Material" || header == "Baseline") column.ItemsSource = materialChoices;
            else if (header == "Experiment") column.ItemsSource = definitionChoices;
        }
        var materialLabels = materialChoices.ToDictionary(x => x.Key, x => x.Value, StringComparer.OrdinalIgnoreCase);
        var definitionLabels = definitionChoices.ToDictionary(x => x.Key, x => x.Value, StringComparer.OrdinalIgnoreCase);
        foreach (var row in _materialExperimentRows)
        {
            row.MaterialDisplayName = materialLabels.TryGetValue(row.MaterialID, out var material) ? material : row.MaterialID;
            row.BaselineMaterialDisplayName = materialLabels.TryGetValue(row.BaselineMaterialID, out var baseline) ? baseline : row.BaselineMaterialID;
            row.ExperimentName = definitionLabels.TryGetValue(row.ExperimentDefinitionId, out var definition) ? definition : row.ExperimentDefinitionId;
        }
        _materialExperimentView?.Refresh();
    }

    private bool MaterialExperimentFilter(object item)
    {
        if (item is not MaterialExperimentRecord row) return false;
        if (FindName("ExperimentalActiveOnlyCheckBox") is CheckBox activeOnly && activeOnly.IsChecked == true && !row.IsActive) return false;
        var search = FindName("ExperimentalSearchTextBox") is TextBox box ? box.Text.Trim() : string.Empty;
        if (string.IsNullOrWhiteSpace(search)) return true;
        return new[] { row.MaterialExperimentId, row.MaterialDisplayName, row.MaterialID, row.ExperimentName, row.ParameterValue, row.ParameterUnit, row.BaselineMaterialDisplayName, row.Notes }
            .Any(value => (value ?? string.Empty).Contains(search, StringComparison.CurrentCultureIgnoreCase));
    }

    private void SaveMaterialExperiments()
    {
        _database.SynchronizeExperimentalGraph(
            _materialExperimentRows,
            _experimentalRunRows,
            _experimentalMeasurementRows);
    }

    private void SaveExperimentalRuns() => SaveMaterialExperiments();

    private void SaveExperimentalMeasurements() => SaveMaterialExperiments();

    private void MaterialExperimentsGrid_SelectionChanged(object sender, SelectionChangedEventArgs e)
    {
        if (sender is not DataGrid grid) return;
        var series = grid.SelectedItem as MaterialExperimentRecord ?? grid.CurrentCell.Item as MaterialExperimentRecord;
        if (series is null) return;
        _lastSelectedMaterialExperiment = series;
        ActivateExperimentalSeries(series);
    }

    private void ActivateExperimentalSeries(MaterialExperimentRecord? series)
    {
        _selectedExperimentalSeries = series;
        var contextVersion = ++_experimentalSeriesContextVersion;

        // Series changes are atomic: remove every child context from the previous series first.
        // This prevents stale Run measurements/results from remaining visible when the new series
        // has no Runs, and prevents an older deferred callback from restoring the wrong series.
        _lastSelectedExperimentalRun = null;
        if (FindName("ExperimentalRunsGrid") is DataGrid runsGrid)
        {
            runsGrid.SelectedItem = null;
            runsGrid.UnselectAll();
        }
        ClearExperimentalMeasurementEditors();
        _experimentalSeriesResultRows.Clear();
        _experimentalRunView?.Refresh();
        RefreshExperimentalSeriesResults();
        RefreshExperimentalStatus();

        Dispatcher.BeginInvoke(new Action(() =>
        {
            if (contextVersion != _experimentalSeriesContextVersion ||
                !ReferenceEquals(_selectedExperimentalSeries, series)) return;
            if (FindName("ExperimentalRunsGrid") is not DataGrid currentRunsGrid) return;

            var candidate = _experimentalRunView?.Cast<object>()
                .OfType<ExperimentalRunRecord>()
                .FirstOrDefault();
            if (candidate is null)
            {
                currentRunsGrid.SelectedItem = null;
                ClearExperimentalMeasurementEditors();
                RefreshExperimentalSeriesResults();
                RefreshExperimentalStatus();
                return;
            }

            currentRunsGrid.SelectedItem = candidate;
            currentRunsGrid.ScrollIntoView(candidate);
            ActivateExperimentalRun(candidate);
        }), DispatcherPriority.ContextIdle);
    }

    private void AddExperimentalRun_Click(object sender, RoutedEventArgs e)
    {
        var series = _selectedExperimentalSeries ?? _lastSelectedMaterialExperiment;
        if (series is null)
        {
            MessageBox.Show(this, "Select a test series first.", "Experimental Testing", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }
        var row = new ExperimentalRunRecord
        {
            ExperimentalRunId = "RUN-" + Guid.NewGuid().ToString("N")[..8].ToUpperInvariant(),
            MaterialExperimentId = series.MaterialExperimentId,
            ParameterUnit = series.ParameterUnit,
            Status = "Planned",
            IsActive = true,
            CreatedAtUtc = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture)
        };
        _experimentalRunRows.Add(row);
        SaveExperimentalRuns();
        _experimentalRunView?.Refresh();
        RefreshExperimentalSeriesResults();
        RefreshExperimentalStatus();
    }

    private ExperimentalRunRecord? ResolveExperimentalRun()
    {
        if (FindName("ExperimentalRunsGrid") is not DataGrid grid) return _lastSelectedExperimentalRun;
        return grid.CurrentCell.Item as ExperimentalRunRecord ?? grid.SelectedItem as ExperimentalRunRecord ?? _lastSelectedExperimentalRun;
    }

    private void DuplicateExperimentalRun_Click(object sender, RoutedEventArgs e)
    {
        var source = ResolveExperimentalRun();
        if (source is null) return;
        var row = CreateExperimentalRunDuplicate(source);
        _experimentalRunRows.Add(row); SaveExperimentalRuns(); _experimentalRunView?.Refresh(); RefreshExperimentalSeriesResults(); RefreshExperimentalStatus();
    }

    private static ExperimentalRunRecord CreateExperimentalRunDuplicate(
        ExperimentalRunRecord source,
        string? duplicateId = null) =>
        new()
        {
            ExperimentalRunId = duplicateId ?? "RUN-" + Guid.NewGuid().ToString("N")[..8].ToUpperInvariant(),
            MaterialExperimentId = source.MaterialExperimentId, ParameterValue = source.ParameterValue, ParameterUnit = source.ParameterUnit,
            Status = "Planned", IsBaseline = false, IsActive = source.IsActive, Notes = source.Notes,
            CreatedAtUtc = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture)
        };

    private void DeleteExperimentalRun_Click(object sender, RoutedEventArgs e)
    {
        if (IsAutomationActionBlocked("Experimental run deletion")) return;
        var row = ResolveExperimentalRun();
        if (row is null) { MessageBox.Show(this, "Select a run first.", "Experimental Testing"); return; }
        if (MessageBox.Show(this, $"Delete experimental run {row.ExperimentalRunId}?", "Experimental Testing", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
        _experimentalRunRows.Remove(row); foreach (var measurement in _experimentalMeasurementRows.Where(x => x.ExperimentalRunId == row.ExperimentalRunId).ToList()) _experimentalMeasurementRows.Remove(measurement); if (ReferenceEquals(_lastSelectedExperimentalRun,row)) _lastSelectedExperimentalRun=null; SaveExperimentalRuns(); _experimentalRunView?.Refresh(); RefreshExperimentalSeriesResults(); RefreshExperimentalStatus();
    }

    private void ExperimentalRunsGrid_SelectionChanged(object sender, SelectionChangedEventArgs e)
    {
        if (sender is not DataGrid grid) return;
        var selectedRun = grid.SelectedItem as ExperimentalRunRecord ?? grid.CurrentCell.Item as ExperimentalRunRecord;
        if (selectedRun is null)
        {
            if (_experimentalRunView?.Cast<object>().Any() != true)
            {
                _lastSelectedExperimentalRun = null;
                ClearExperimentalMeasurementEditors();
            }
            RefreshExperimentalStatus();
            return;
        }

        ActivateExperimentalRun(selectedRun);
    }

    private void ActivateExperimentalRun(ExperimentalRunRecord run)
    {
        _lastSelectedExperimentalRun = run;
        EnsureExperimentalMeasurementRows(run);
        BindExperimentalMeasurementEditors(run);
        RefreshExperimentalSeriesResults();
        RefreshExperimentalStatus();
    }


    private void ExperimentalMeasurementEditors_SelectionChanged(object sender, SelectionChangedEventArgs e)
    {
        // Tab changes must never leave an editor with a stale/null ItemsSource.
        if (!ReferenceEquals(e.Source, sender)) return;
        var run = ResolveExperimentalRun();
        if (run is null)
        {
            ClearExperimentalMeasurementEditors();
            return;
        }
        _lastSelectedExperimentalRun = run;
        EnsureExperimentalMeasurementRows(run);
        BindExperimentalMeasurementEditors(run);
    }

    private void EnsureExperimentalMeasurementRows(ExperimentalRunRecord? run)
    {
        if (run is null) return;
        // Remove generic v40.4.0 placeholders and the obsolete dedicated Layer Adhesion row.
        // Tensile Upright is the canonical layer-adhesion measurement.
        foreach (var legacy in _experimentalMeasurementRows.Where(x => x.ExperimentalRunId == run.ExperimentalRunId &&
                     ((string.IsNullOrWhiteSpace(x.Orientation) && x.MeasurementType != "Stiffness") || x.MeasurementType == "Layer Adhesion")).ToList())
            _experimentalMeasurementRows.Remove(legacy);
        var definitions = new[]
        {
            (Type:"Tensile", Orientation:"Upright", RawUnit:"N", ResultUnit:"MPa"),
            (Type:"Tensile", Orientation:"Flat", RawUnit:"N", ResultUnit:"MPa"),
            (Type:"Impact", Orientation:"Upright", RawUnit:"%", ResultUnit:"kJ/m²"),
            (Type:"Impact", Orientation:"Flat", RawUnit:"%", ResultUnit:"kJ/m²"),
            (Type:"Stiffness", Orientation:"", RawUnit:"rev / °", ResultUnit:"MPa")
        };
        var added = false;
        foreach (var definition in definitions)
        {
            var existing = _experimentalMeasurementRows.FirstOrDefault(x => x.ExperimentalRunId == run.ExperimentalRunId && x.MeasurementType == definition.Type && x.Orientation == definition.Orientation);
            if (existing is not null)
            {
                existing.RawUnit = definition.RawUnit; existing.ResultUnit = definition.ResultUnit;
                continue;
            }
            _experimentalMeasurementRows.Add(new ExperimentalMeasurementRecord
            {
                ExperimentalMeasurementId = "XMS-" + Guid.NewGuid().ToString("N")[..8].ToUpperInvariant(),
                ExperimentalRunId = run.ExperimentalRunId, MeasurementType = definition.Type, Orientation = definition.Orientation,
                RawUnit = definition.RawUnit, ResultUnit = definition.ResultUnit
            });
            added = true;
        }
        RecalculateExperimentalMeasurements(run.ExperimentalRunId);
        if (added) SaveExperimentalMeasurements();
        BindExperimentalMeasurementEditors(run);
    }


    private void RecalculateExperimentalMeasurements(string runId)
    {
        var rows = _experimentalMeasurementRows.Where(x => x.ExperimentalRunId == runId).ToList();
        var tensileArea = GetNativeTensileCrossSectionArea();
        var impactAngle = GetNativeImpactNoSampleAngle();
        var impactArea = GetNativeImpactCrossSectionAreaM2();
        var maxImpact = GetNativeImpactMaxPossibleImpact();
        var mmPerRevolution = GetNativeStiffnessMmPerRevolution();
        var spanLength = GetNativeStiffnessSpanLength();
        var load = GetNativeStiffnessLoad();
        var secondMoment = GetNativeStiffnessSecondMomentOfArea();
        foreach (var row in rows)
        {
            MeasurementSetResult? set = null;
            if (row.MeasurementType == "Tensile")
            {
                var result = string.Equals(row.Orientation,"Flat",StringComparison.OrdinalIgnoreCase)
                    ? _resultsService.CalculateTensile(Array.Empty<string>(), row.SampleValues(), tensileArea).Flat
                    : _resultsService.CalculateTensile(row.SampleValues(), Array.Empty<string>(), tensileArea).Upright;
                set = result;
            }
            else if (row.MeasurementType == "Impact")
            {
                var result = string.Equals(row.Orientation,"Flat",StringComparison.OrdinalIgnoreCase)
                    ? _resultsService.CalculateImpact(Array.Empty<string>(), row.SampleValues(), impactAngle, impactArea, maxImpact).Flat
                    : _resultsService.CalculateImpact(row.SampleValues(), Array.Empty<string>(), impactAngle, impactArea, maxImpact).Upright;
                set = result;
            }
            else if (row.MeasurementType == "Stiffness")
            {
                var result = _resultsService.CalculateStiffness(row.Sample1,row.Sample2,mmPerRevolution,spanLength,load,secondMoment);
                row.ResultAverage = FormatNativeResult(result.ModulusMpa);
                row.ResultStdDev = ""; row.ResultCv = "";
                row.ResultCount = string.IsNullOrWhiteSpace(row.Sample1) && string.IsNullOrWhiteSpace(row.Sample2) ? "" : "1";
                row.ResultConfidence = result.CompletenessRating.Stars.ToString(CultureInfo.CurrentCulture);
                row.NotifyCalculated(); continue;
            }
            if (set is not null)
            {
                row.ResultAverage=FormatNativeResult(set.Average); row.ResultStdDev=FormatNativeResult(set.StandardDeviation);
                // ResultsService returns CV as a ratio (1.0 = 100%). Experimental editors and downstream result rows use percentage points.
                row.ResultCv=FormatNativeResult(set.CoefficientOfVariation * 100d); row.ResultCount=set.SampleCount==0?"":set.SampleCount.ToString(CultureInfo.CurrentCulture);
                row.ResultConfidence=set.Confidence?.ToString(CultureInfo.CurrentCulture)??""; row.NotifyCalculated();
            }
        }
    }

    private void RefreshExperimentalSeriesResults()
    {
        _experimentalSeriesResultRows.Clear();
        var series = _selectedExperimentalSeries ?? _lastSelectedMaterialExperiment;
        if (series is null)
        {
            SetExperimentalAnalyticsSummary(null);
            RefreshExperimentalDashboard(null, new List<ExperimentalRunRecord>(), null);
            if (FindName("ExperimentalResultsSummaryText") is TextBlock emptyText)
                emptyText.Text = "Select a test series to compare its runs.";
            return;
        }

        var runs = GetExperimentalComparisonRuns(series)
            .OrderBy(x => ParseExperimentalSortValue(x.ParameterValue))
            .ThenBy(x => x.ParameterValue, StringComparer.CurrentCultureIgnoreCase)
            .ToList();
        var baseline = runs.FirstOrDefault(x => x.IsBaseline);
        var baselineMetrics = baseline is null ? null : GetExperimentalRunMetrics(baseline.ExperimentalRunId);
        var analyticsInputs = runs.Select(run =>
        {
            var metrics = GetExperimentalRunMetrics(run.ExperimentalRunId);
            return new ExperimentalAnalyticsInput(run.ExperimentalRunId, ExperimentalRunLabel(run), run.IsBaseline,
                metrics.TensileUpright, metrics.TensileFlat, metrics.ImpactUpright, metrics.ImpactFlat, metrics.Stiffness);
        }).ToList();
        var analytics = _experimentalAnalyticsService.Analyze(analyticsInputs);
        var rankings = analytics.RankedRuns.ToDictionary(x => x.ExperimentalRunId, StringComparer.OrdinalIgnoreCase);

        foreach (var run in runs)
        {
            var metrics = GetExperimentalRunMetrics(run.ExperimentalRunId);
            rankings.TryGetValue(run.ExperimentalRunId, out var ranking);
            _experimentalSeriesResultRows.Add(new ExperimentalSeriesResultRow
            {
                ExperimentalRunId = run.ExperimentalRunId, RunLabel = ExperimentalRunLabel(run), Status = run.Status, IsBaseline = run.IsBaseline,
                Rank = ranking?.Rank ?? 0, OverallScore = ranking is null ? string.Empty : ranking.OverallScore.ToString("0.0", CultureInfo.CurrentCulture),
                TensileUprightAverage = FormatExperimentalMetric(metrics.TensileUpright),
                TensileUprightDelta = FormatExperimentalDelta(metrics.TensileUpright, baselineMetrics?.TensileUpright, run.IsBaseline), TensileUprightCv = FormatExperimentalPercent(metrics.TensileUprightCv),
                TensileFlatAverage = FormatExperimentalMetric(metrics.TensileFlat),
                TensileFlatDelta = FormatExperimentalDelta(metrics.TensileFlat, baselineMetrics?.TensileFlat, run.IsBaseline), TensileFlatCv = FormatExperimentalPercent(metrics.TensileFlatCv),
                ImpactUprightAverage = FormatExperimentalMetric(metrics.ImpactUpright),
                ImpactUprightDelta = FormatExperimentalDelta(metrics.ImpactUpright, baselineMetrics?.ImpactUpright, run.IsBaseline), ImpactUprightCv = FormatExperimentalPercent(metrics.ImpactUprightCv),
                ImpactFlatAverage = FormatExperimentalMetric(metrics.ImpactFlat),
                ImpactFlatDeltaDisplay = FormatExperimentalDelta(metrics.ImpactFlat, baselineMetrics?.ImpactFlat, run.IsBaseline), ImpactFlatCv = FormatExperimentalPercent(metrics.ImpactFlatCv),
                StiffnessAverage = FormatExperimentalMetric(metrics.Stiffness),
                StiffnessDelta = FormatExperimentalDelta(metrics.Stiffness, baselineMetrics?.Stiffness, run.IsBaseline)
            });
        }

        SetExperimentalAnalyticsSummary(analytics);
        RefreshExperimentalDashboard(series, runs, analytics);
        RefreshExperimentalCharts();
        RefreshExperimentalPublicationReadiness(series);
        if (FindName("ExperimentalResultsSummaryText") is TextBlock summary)
        {
            if (runs.Count == 0) summary.Text = "No runs exist in the selected series.";
            else if (baseline is null) summary.Text = $"{runs.Count} run(s). Mark one run as Baseline to calculate Δ%. Analytics ranking is available from completed results.";
            else summary.Text = $"{runs.Count} run(s) compared with {ExperimentalRunLabel(baseline)} baseline. Overall score: Tensile 40%, Impact 40%, Stiffness 20%; available metrics are reweighted automatically.";
        }
    }

    private List<ExperimentalRunRecord> GetExperimentalComparisonRuns(MaterialExperimentRecord series)
    {
        var includeInactive = FindName("ExperimentalIncludeInactiveHistoryCheckBox") is CheckBox { IsChecked: true };
        return _experimentalRunRows
            .Where(run => string.Equals(run.MaterialExperimentId, series.MaterialExperimentId, StringComparison.OrdinalIgnoreCase) &&
                          (includeInactive || run.IsActive))
            .ToList();
    }

    private string ExperimentalComparisonScopeLabel() =>
        FindName("ExperimentalIncludeInactiveHistoryCheckBox") is CheckBox { IsChecked: true }
            ? "Active and inactive history included."
            : "Active runs only; website parity is active.";

    private void ExperimentalComparisonScope_Changed(object sender, RoutedEventArgs e)
    {
        RefreshExperimentalSeriesResults();
    }


    private void ExperimentalResultsViewTabs_SelectionChanged(object sender, SelectionChangedEventArgs e)
    {
        if (e.Source == sender) Dispatcher.BeginInvoke(new Action(RefreshExperimentalCharts), DispatcherPriority.Background);
    }

    private void ExperimentalChart_SizeChanged(object sender, SizeChangedEventArgs e)
    {
        if (sender is Canvas && e.NewSize.Width > 0 && e.NewSize.Height > 0)
            Dispatcher.BeginInvoke(new Action(RefreshExperimentalCharts), DispatcherPriority.Background);
    }

    private void RefreshExperimentalCharts()
    {
        if (FindName("ExperimentalTensileChart") is not Canvas tensile) return;
        var series = _selectedExperimentalSeries ?? _lastSelectedMaterialExperiment;
        var runs = series is null ? new List<ExperimentalRunRecord>() : GetExperimentalComparisonRuns(series)
            .OrderBy(x => ParseExperimentalSortValue(x.ParameterValue)).ThenBy(x => x.ParameterValue, StringComparer.CurrentCultureIgnoreCase).ToList();
        var points = runs.Select(run =>
        {
            var m = GetExperimentalRunMetrics(run.ExperimentalRunId);
            var ranked = _experimentalSeriesResultRows.FirstOrDefault(x => x.ExperimentalRunId == run.ExperimentalRunId);
            return new ExperimentalChartPoint(ExperimentalRunLabel(run), ParseExperimentalResult(run.ParameterValue), run.IsBaseline,
                m.TensileUpright, m.TensileFlat, m.ImpactUpright, m.ImpactFlat, m.Stiffness,
                ParseExperimentalResult(ranked?.OverallScore));
        }).ToList();

        DrawExperimentalLineChart(tensile, "Parameter vs Tensile", points, new[]
        {
            new ExperimentalChartSeries("Upright", p => p.TensileUpright, Brushes.SteelBlue),
            new ExperimentalChartSeries("Flat", p => p.TensileFlat, Brushes.DarkOrange)
        }, "MPa");
        DrawExperimentalLineChart(FindName("ExperimentalImpactChart") as Canvas, "Parameter vs Impact", points, new[]
        {
            new ExperimentalChartSeries("Upright", p => p.ImpactUpright, Brushes.SeaGreen),
            new ExperimentalChartSeries("Flat", p => p.ImpactFlat, Brushes.MediumVioletRed)
        }, "kJ/m²");
        DrawExperimentalLineChart(FindName("ExperimentalStiffnessChart") as Canvas, "Parameter vs Stiffness", points,
            new[] { new ExperimentalChartSeries("Stiffness", p => p.Stiffness, Brushes.SlateBlue) }, "MPa");
        DrawExperimentalBarChart(FindName("ExperimentalScoreChart") as Canvas, "Combined Performance Score", points, p => p.Score, "%");
        DrawExperimentalBaselineChart(FindName("ExperimentalBaselineChart") as Canvas, points);
        if (FindName("ExperimentalChartsStatusText") is TextBlock status)
            status.Text = points.Count == 0
                ? "Select a test series with active runs to display charts."
                : $"{points.Count} run(s) visualized. {ExperimentalComparisonScopeLabel()} Blue halo = baseline; gold marker = best value. Charts use the same native results and analytics score as the Results table.";
    }

    private static void DrawExperimentalLineChart(Canvas? canvas, string title, IReadOnlyList<ExperimentalChartPoint> points, IReadOnlyList<ExperimentalChartSeries> series, string unit)
    {
        if (canvas is null) return; canvas.Children.Clear();
        var w = Math.Max(480, canvas.ActualWidth); var h = Math.Max(280, canvas.ActualHeight); const double l=58,r=18,t=72,b=48;
        AddChartText(canvas,title,12,8,16,FontWeights.SemiBold,Brushes.Black);
        var values = series.SelectMany(s => points.Select(p => s.Selector(p))).Where(v=>v.HasValue).Select(v=>v!.Value).ToList();
        if (values.Count==0) { AddChartText(canvas,"No calculated results",l,t+30,13,FontWeights.Normal,Brushes.Gray); return; }
        var minY=Math.Min(0,values.Min()); var maxY=values.Max(); if(Math.Abs(maxY-minY)<0.0001) maxY=minY+1;
        var numericX=points.Count>1 && points.All(p=>p.X.HasValue); var minX=numericX?points.Min(p=>p.X!.Value):0; var maxX=numericX?points.Max(p=>p.X!.Value):Math.Max(1,points.Count-1); if(Math.Abs(maxX-minX)<0.0001) maxX=minX+1;
        DrawAxes(canvas,w,h,l,r,t,b,minY,maxY,unit);
        foreach(var s in series) {
            var valid=points.Select((p,i)=>(p,i,v:s.Selector(p))).Where(x=>x.v.HasValue).ToList();
            var poly=new Polyline{Stroke=s.Brush,StrokeThickness=2};
            foreach(var x in valid) { var xv=numericX?x.p.X!.Value:x.i; var px=l+(xv-minX)/(maxX-minX)*(w-l-r); var py=t+(maxY-x.v!.Value)/(maxY-minY)*(h-t-b); poly.Points.Add(new Point(px,py)); AddDot(canvas,px,py,s.Brush,x.p.IsBaseline,x.v.Value==values.Max()); }
            canvas.Children.Add(poly);
        }
        for(int i=0;i<points.Count;i++){var xv=numericX?points[i].X!.Value:i; var px=l+(xv-minX)/(maxX-minX)*(w-l-r); AddChartText(canvas,points[i].Label,px-30,h-b+8,10,FontWeights.Normal,Brushes.DimGray,60,TextAlignment.Center);}
        var lx=l; foreach(var s in series){canvas.Children.Add(new Line{X1=lx,Y1=46,X2=lx+18,Y2=46,Stroke=s.Brush,StrokeThickness=3}); AddChartText(canvas,s.Name,lx+23,37,11,FontWeights.Normal,Brushes.DimGray); lx+=95;}
    }

    private static void DrawExperimentalBarChart(Canvas? canvas,string title,IReadOnlyList<ExperimentalChartPoint> points,Func<ExperimentalChartPoint,double?> selector,string unit)
    {
        if(canvas is null)return; canvas.Children.Clear(); var w=Math.Max(480,canvas.ActualWidth);var h=Math.Max(280,canvas.ActualHeight);const double l=52,r=18,t=62,b=55;
        AddChartText(canvas,title,12,8,16,FontWeights.SemiBold,Brushes.Black);var vals=points.Select(selector).Where(v=>v.HasValue).Select(v=>v!.Value).ToList();if(vals.Count==0){AddChartText(canvas,"No analytics scores",l,t+30,13,FontWeights.Normal,Brushes.Gray);return;}var max=Math.Max(100,vals.Max());DrawAxes(canvas,w,h,l,r,t,b,0,max,unit);var bw=(w-l-r)/Math.Max(1,points.Count)*0.62;var best=vals.Max();
        for(int i=0;i<points.Count;i++){var v=selector(points[i]);if(!v.HasValue)continue;var x=l+(i+.5)*(w-l-r)/points.Count-bw/2;var y=t+(max-v.Value)/max*(h-t-b);var rect=new Rectangle{Width=bw,Height=h-b-y,Fill=v.Value==best?Brushes.Goldenrod:Brushes.SteelBlue,Stroke=points[i].IsBaseline?Brushes.DodgerBlue:Brushes.Transparent,StrokeThickness=points[i].IsBaseline?3:0};Canvas.SetLeft(rect,x);Canvas.SetTop(rect,y);canvas.Children.Add(rect);AddChartText(canvas,v.Value.ToString("0.0",CultureInfo.CurrentCulture),x,y-18,10,FontWeights.SemiBold,Brushes.DimGray,bw,TextAlignment.Center);AddChartText(canvas,points[i].Label,x-8,h-b+8,10,FontWeights.Normal,Brushes.DimGray,bw+16,TextAlignment.Center);}
    }

    private static void DrawExperimentalBaselineChart(Canvas? canvas,IReadOnlyList<ExperimentalChartPoint> points)
    {
        if(canvas is null)return;canvas.Children.Clear();var baseline=points.FirstOrDefault(p=>p.IsBaseline);AddChartText(canvas,"Baseline vs Run Comparison (normalized to baseline = 100)",12,8,16,FontWeights.SemiBold,Brushes.Black);if(baseline is null){AddChartText(canvas,"Mark one run as Baseline to display this chart.",58,72,13,FontWeights.Normal,Brushes.Gray);return;}
        double? Ratio(double? v,double? b)=>v.HasValue&&b.HasValue&&Math.Abs(b.Value)>0.000001?v.Value/b.Value*100:null;
        var normalized=points.Select(p=>new ExperimentalChartPoint(p.Label,p.X,p.IsBaseline,Ratio(p.TensileUpright,baseline.TensileUpright),Ratio(p.TensileFlat,baseline.TensileFlat),Ratio(p.ImpactUpright,baseline.ImpactUpright),Ratio(p.ImpactFlat,baseline.ImpactFlat),Ratio(p.Stiffness,baseline.Stiffness),p.Score)).ToList();
        DrawExperimentalLineChart(canvas,"Baseline vs Run Comparison (normalized to baseline = 100)",normalized,new[]{new ExperimentalChartSeries("Tensile U",p=>p.TensileUpright,Brushes.SteelBlue),new ExperimentalChartSeries("Tensile F",p=>p.TensileFlat,Brushes.DarkOrange),new ExperimentalChartSeries("Impact U",p=>p.ImpactUpright,Brushes.SeaGreen),new ExperimentalChartSeries("Impact F",p=>p.ImpactFlat,Brushes.MediumVioletRed),new ExperimentalChartSeries("Stiffness",p=>p.Stiffness,Brushes.SlateBlue)},"Index");
    }

    private static void DrawAxes(Canvas canvas,double w,double h,double l,double r,double t,double b,double min,double max,string unit)
    { canvas.Children.Add(new Line{X1=l,Y1=t,X2=l,Y2=h-b,Stroke=Brushes.SlateGray,StrokeThickness=1});canvas.Children.Add(new Line{X1=l,Y1=h-b,X2=w-r,Y2=h-b,Stroke=Brushes.SlateGray,StrokeThickness=1});for(int i=0;i<=4;i++){var y=t+i*(h-t-b)/4;var v=max-i*(max-min)/4;canvas.Children.Add(new Line{X1=l,Y1=y,X2=w-r,Y2=y,Stroke=Brushes.Gainsboro,StrokeThickness=1});AddChartText(canvas,v.ToString("0.##",CultureInfo.CurrentCulture),2,y-8,10,FontWeights.Normal,Brushes.DimGray,l-7,TextAlignment.Right);}AddChartText(canvas,unit,4,t-18,10,FontWeights.SemiBold,Brushes.DimGray);}
    private static void AddDot(Canvas c,double x,double y,Brush brush,bool baseline,bool best){if(baseline){var halo=new Ellipse{Width=15,Height=15,Stroke=Brushes.DodgerBlue,StrokeThickness=2,Fill=Brushes.Transparent};Canvas.SetLeft(halo,x-7.5);Canvas.SetTop(halo,y-7.5);c.Children.Add(halo);}var dot=new Ellipse{Width=best?9:7,Height=best?9:7,Fill=best?Brushes.Gold:brush,Stroke=brush,StrokeThickness=1};Canvas.SetLeft(dot,x-dot.Width/2);Canvas.SetTop(dot,y-dot.Height/2);c.Children.Add(dot);}
    private static void AddChartText(Canvas c,string text,double x,double y,double size,FontWeight weight,Brush brush,double width=double.NaN,TextAlignment alignment=TextAlignment.Left){var tb=new TextBlock{Text=text,FontSize=size,FontWeight=weight,Foreground=brush,TextAlignment=alignment,TextTrimming=TextTrimming.CharacterEllipsis};if(!double.IsNaN(width))tb.Width=Math.Max(1,width);Canvas.SetLeft(tb,x);Canvas.SetTop(tb,y);c.Children.Add(tb);}
    private sealed record ExperimentalChartPoint(string Label,double? X,bool IsBaseline,double? TensileUpright,double? TensileFlat,double? ImpactUpright,double? ImpactFlat,double? Stiffness,double? Score);
    private sealed record ExperimentalChartSeries(string Name,Func<ExperimentalChartPoint,double?> Selector,Brush Brush);

    private static string ExperimentalRunLabel(ExperimentalRunRecord run) =>
        string.IsNullOrWhiteSpace(run.ParameterValue) ? run.ExperimentalRunId : $"{run.ParameterValue} {run.ParameterUnit}".Trim();

    private ExperimentalPublicationReadiness GetExperimentalPublicationReadiness(MaterialExperimentRecord series)
    {
        var runs = _experimentalRunRows
            .Where(run => run.IsActive &&
                          string.Equals(run.MaterialExperimentId, series.MaterialExperimentId, StringComparison.OrdinalIgnoreCase))
            .ToList();
        var completed = 0;
        var missing = 0;
        var highCvRuns = 0;
        foreach (var run in runs)
        {
            var metrics = GetExperimentalRunMetrics(run.ExperimentalRunId);
            var values = new[]
            {
                metrics.TensileUpright, metrics.TensileFlat,
                metrics.ImpactUpright, metrics.ImpactFlat, metrics.Stiffness
            };
            var runMissing = values.Count(value => !value.HasValue);
            missing += runMissing;
            if (runMissing == 0) completed++;
            if (new[]
                {
                    metrics.TensileUprightCv, metrics.TensileFlatCv,
                    metrics.ImpactUprightCv, metrics.ImpactFlatCv
                }.Any(value => value > 15d))
                highCvRuns++;
        }

        var baselineCount = runs.Count(run => run.IsBaseline);
        var statusConflicts = runs.Count(run =>
        {
            var metrics = GetExperimentalRunMetrics(run.ExperimentalRunId);
            var complete = metrics.TensileUpright.HasValue && metrics.TensileFlat.HasValue &&
                           metrics.ImpactUpright.HasValue && metrics.ImpactFlat.HasValue &&
                           metrics.Stiffness.HasValue;
            return string.Equals(run.Status, "Completed", StringComparison.OrdinalIgnoreCase) && !complete;
        });
        var ready = runs.Count >= 2 && baselineCount == 1 && missing == 0 && highCvRuns == 0 && statusConflicts == 0;
        var detail =
            $"Publication readiness: active runs {runs.Count}, complete {completed}, missing results {missing}, " +
            $"baseline {(baselineCount == 1 ? "ready" : baselineCount == 0 ? "missing" : "invalid")}, " +
            $"high-CV runs {highCvRuns}, completed-status conflicts {statusConflicts}.";
        return new ExperimentalPublicationReadiness(ready, detail);
    }

    private void RefreshExperimentalPublicationReadiness(MaterialExperimentRecord? series = null)
    {
        if (FindName("ExperimentalPublicationReadinessText") is not TextBlock text) return;
        series ??= _selectedExperimentalSeries ?? _lastSelectedMaterialExperiment;
        if (series is null)
        {
            text.Text = "Publication readiness: select a Series.";
            return;
        }

        var readiness = GetExperimentalPublicationReadiness(series);
        text.Text = readiness.Ready
            ? readiness.Detail + " Ready for governed Website inclusion."
            : readiness.Detail + " Review before Website inclusion; partial research requires explicit confirmation.";
    }

    private sealed record ExperimentalPublicationReadiness(bool Ready, string Detail);

    private void RefreshExperimentalDashboard(MaterialExperimentRecord? series, IReadOnlyList<ExperimentalRunRecord> runs, ExperimentalAnalyticsResult? analytics)
    {
        void Set(string name, string value) { if (FindName(name) is TextBlock text) text.Text = string.IsNullOrWhiteSpace(value) ? "—" : value; }
        if (series is null)
        {
            foreach (var name in new[] { "ExperimentalDashboardSeriesText", "ExperimentalDashboardRecommendedText", "ExperimentalDashboardRunsText", "ExperimentalDashboardCompletedText", "ExperimentalDashboardMissingText", "ExperimentalDashboardBaselineText", "ExperimentalDashboardQualityText", "ExperimentalDashboardHighestCvText", "ExperimentalDashboardCvSourceText", "ExperimentalDashboardBestTensileText", "ExperimentalDashboardBestImpactText", "ExperimentalDashboardBestStiffnessText", "ExperimentalDashboardBestOverallText" }) Set(name, "—");
            Set("ExperimentalDashboardStatusText", "Select a test series to view experiment completeness and quality indicators.");
            return;
        }
        static string Best(ExperimentalBestResult? result) => result is null ? "—" : $"{result.RunLabel} ({result.Value:0.00})";
        var completed = runs.Count(run =>
        {
            var m = GetExperimentalRunMetrics(run.ExperimentalRunId);
            return m.TensileUpright.HasValue && m.TensileFlat.HasValue && m.ImpactUpright.HasValue && m.ImpactFlat.HasValue && m.Stiffness.HasValue;
        });
        var missing = runs.Sum(run =>
        {
            var m = GetExperimentalRunMetrics(run.ExperimentalRunId);
            return new[] { m.TensileUpright, m.TensileFlat, m.ImpactUpright, m.ImpactFlat, m.Stiffness }.Count(v => !v.HasValue);
        });
        // CV values in the Results table are canonical percentage-point values.
        // Example: "0.35%" parses to 0.35, while the high-variation limit is 15.00.
        // The Dashboard must read these exact result rows rather than reinterpreting raw ResultCv values.
        const double highVariationThresholdPercent = 15d;
        var resultRowsByRunId = _experimentalSeriesResultRows
            .ToDictionary(x => x.ExperimentalRunId, StringComparer.OrdinalIgnoreCase);
        var cvReadings = runs.SelectMany(run =>
        {
            if (!resultRowsByRunId.TryGetValue(run.ExperimentalRunId, out var resultRow))
                return Array.Empty<ExperimentalDashboardCvReading>();

            var runLabel = resultRow.RunLabel;
            return new[]
            {
                new ExperimentalDashboardCvReading(run.ExperimentalRunId, runLabel, "Tensile Upright", ParseExperimentalResult(resultRow.TensileUprightCv)),
                new ExperimentalDashboardCvReading(run.ExperimentalRunId, runLabel, "Tensile Flat", ParseExperimentalResult(resultRow.TensileFlatCv)),
                new ExperimentalDashboardCvReading(run.ExperimentalRunId, runLabel, "Impact Upright", ParseExperimentalResult(resultRow.ImpactUprightCv)),
                new ExperimentalDashboardCvReading(run.ExperimentalRunId, runLabel, "Impact Flat", ParseExperimentalResult(resultRow.ImpactFlatCv))
            };
        }).Where(x => x.ValuePercent.HasValue).ToList();
        var highestCv = cvReadings.OrderByDescending(x => x.ValuePercent).FirstOrDefault();
        var highCvRuns = cvReadings
            .Where(x => x.ValuePercent > highVariationThresholdPercent)
            .Select(x => x.ExperimentalRunId)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();
        var highCv = highCvRuns.Count;
        var quality = runs.Count == 0 ? "No runs" : missing == 0 && highCv == 0 ? "Complete" : missing > 0 ? "Needs measurements" : "High variation";
        var recommended = analytics?.RecommendedRun;
        Set("ExperimentalDashboardSeriesText", $"{series.MaterialDisplayName} — {series.ExperimentName} ({series.ParameterUnit})");
        Set("ExperimentalDashboardRecommendedText", recommended is null ? "—" : $"{recommended.RunLabel} · {recommended.OverallScore:0.0}");
        Set("ExperimentalDashboardRunsText", runs.Count.ToString(CultureInfo.CurrentCulture));
        Set("ExperimentalDashboardCompletedText", completed.ToString(CultureInfo.CurrentCulture));
        Set("ExperimentalDashboardMissingText", missing.ToString(CultureInfo.CurrentCulture));
        Set("ExperimentalDashboardBaselineText", analytics?.BaselineLabel ?? "Not selected");
        Set("ExperimentalDashboardQualityText", quality);
        Set("ExperimentalDashboardHighestCvText", highestCv is null ? "No CV available" : $"Highest CV: {highestCv.ValuePercent!.Value.ToString("0.00", CultureInfo.CurrentCulture) + "%"}");
        Set("ExperimentalDashboardCvSourceText", highestCv is null ? $"Threshold: {highVariationThresholdPercent:0}%" : $"{highestCv.RunLabel} · {highestCv.Metric} · Threshold {highVariationThresholdPercent:0}%");
        Set("ExperimentalDashboardBestTensileText", Best(analytics?.BestTensileFlat ?? analytics?.BestTensileUpright));
        Set("ExperimentalDashboardBestImpactText", Best(analytics?.BestImpactFlat ?? analytics?.BestImpactUpright));
        Set("ExperimentalDashboardBestStiffnessText", Best(analytics?.BestStiffness));
        Set("ExperimentalDashboardBestOverallText", recommended is null ? "—" : $"#{recommended.Rank} {recommended.RunLabel} · {recommended.OverallScore:0.0}");
        var warnings = new List<string>();
        if (runs.Count < 2) warnings.Add("Add at least two runs for a meaningful comparison.");
        if (!runs.Any(x => x.IsBaseline)) warnings.Add("Select a baseline run to enable delta comparisons.");
        if (missing > 0) warnings.Add($"{missing} calculated result(s) are still missing.");
        if (highCv > 0 && highestCv is not null) warnings.Add($"{highCv} run(s) contain CV above 15%. Highest is {highestCv.ValuePercent!.Value.ToString("0.00", CultureInfo.CurrentCulture) + "%"} in {highestCv.RunLabel} · {highestCv.Metric}.");
        Set("ExperimentalDashboardStatusText", warnings.Count == 0 ? "All runs are complete, baseline comparison is active, and no high-variation warning was detected." : string.Join(" ", warnings));
    }

    private void SetExperimentalAnalyticsSummary(ExperimentalAnalyticsResult? analytics)
    {
        void Set(string name, string value) { if (FindName(name) is TextBlock text) text.Text = string.IsNullOrWhiteSpace(value) ? "—" : value; }
        static string Best(ExperimentalBestResult? result) => result is null ? "—" : $"{result.RunLabel}  ({result.Value:0.00})";
        Set("ExperimentalAnalyticsBaselineText", analytics?.BaselineLabel ?? string.Empty);
        Set("ExperimentalAnalyticsBestTensileText", Best(analytics?.BestTensileFlat ?? analytics?.BestTensileUpright));
        Set("ExperimentalAnalyticsBestImpactText", Best(analytics?.BestImpactFlat ?? analytics?.BestImpactUpright));
        Set("ExperimentalAnalyticsBestStiffnessText", Best(analytics?.BestStiffness));
        Set("ExperimentalAnalyticsRecommendedText", analytics?.RecommendedRun is null ? string.Empty : $"{analytics.RecommendedRun.RunLabel}  ({analytics.RecommendedRun.OverallScore:0.0})");
    }

    private ExperimentalRunMetrics GetExperimentalRunMetrics(string runId)
    {
        double? Read(string type, string orientation, bool cv = false)
        {
            var row = _experimentalMeasurementRows.FirstOrDefault(x =>
                string.Equals(x.ExperimentalRunId, runId, StringComparison.OrdinalIgnoreCase) &&
                string.Equals(x.MeasurementType, type, StringComparison.OrdinalIgnoreCase) &&
                string.Equals(x.Orientation ?? string.Empty, orientation, StringComparison.OrdinalIgnoreCase));
            return ParseExperimentalResult(cv ? row?.ResultCv : row?.ResultAverage);
        }
        return new ExperimentalRunMetrics(
            Read("Tensile", "Upright"), Read("Tensile", "Upright", true),
            Read("Tensile", "Flat"), Read("Tensile", "Flat", true),
            Read("Impact", "Upright"), Read("Impact", "Upright", true),
            Read("Impact", "Flat"), Read("Impact", "Flat", true),
            Read("Stiffness", string.Empty));
    }

    private static double ParseExperimentalSortValue(string? text) => ParseExperimentalResult(text) ?? double.MaxValue;
    private static double? ParseExperimentalResult(string? text)
    {
        if (string.IsNullOrWhiteSpace(text)) return null;
        var normalized = text.Trim().Replace("%", string.Empty).Replace(',', '.');
        return double.TryParse(normalized, NumberStyles.Float, CultureInfo.InvariantCulture, out var value) ? value : null;
    }
    private static string FormatExperimentalMetric(double? value) => value.HasValue ? value.Value.ToString("0.00", CultureInfo.CurrentCulture) : string.Empty;
    private static string FormatExperimentalPercent(double? value) => value.HasValue ? value.Value.ToString("0.00", CultureInfo.CurrentCulture) + "%" : string.Empty;
    private static string FormatExperimentalDelta(double? value, double? baseline, bool isBaseline)
    {
        if (isBaseline && value.HasValue) return "0.00%";
        if (!value.HasValue || !baseline.HasValue || Math.Abs(baseline.Value) < 0.0000001d) return string.Empty;
        var delta = (value.Value - baseline.Value) / baseline.Value * 100d;
        return delta.ToString("+0.00;-0.00;0.00", CultureInfo.CurrentCulture) + "%";
    }

    private sealed record ExperimentalDashboardCvReading(
        string ExperimentalRunId, string RunLabel, string Metric, double? ValuePercent);

    private sealed record ExperimentalRunMetrics(
        double? TensileUpright, double? TensileUprightCv,
        double? TensileFlat, double? TensileFlatCv,
        double? ImpactUpright, double? ImpactUprightCv,
        double? ImpactFlat, double? ImpactFlatCv,
        double? Stiffness);

    private void ExperimentalMeasurementEditor_CellEditEnding(object sender, DataGridCellEditEndingEventArgs e)
    {
        // Capture the edited row before WPF completes the edit transaction. The calculation is deferred,
        // but it must remain tied to that row's RunID even if the user changes selection immediately after.
        var editedRow = e.Row.Item as ExperimentalMeasurementRecord;
        var runId = editedRow?.ExperimentalRunId;
        if (string.IsNullOrWhiteSpace(runId)) return;

        // CellEditEnding is raised while WPF is closing the cell that was just edited.
        // Do not call CommitEdit from the deferred callback: by the time it runs the user may
        // already have activated the next sample cell, and committing the grid again closes that
        // new editor. That produced the alternating single-click / double-click behaviour.
        Dispatcher.BeginInvoke(new Action(() =>
        {
            RecalculateExperimentalMeasurements(runId);
            var run = _experimentalRunRows.FirstOrDefault(item =>
                string.Equals(item.ExperimentalRunId, runId, StringComparison.OrdinalIgnoreCase));
            var hasMeasurementInput = _experimentalMeasurementRows
                .Where(item => string.Equals(item.ExperimentalRunId, runId, StringComparison.OrdinalIgnoreCase))
                .SelectMany(item => item.SampleValues())
                .Any(value => !string.IsNullOrWhiteSpace(value));
            if (run is not null && ShouldAssignMeasuredDate(run.MeasuredDate, hasMeasurementInput ? new[] { "measured" } : Array.Empty<string>()))
            {
                run.MeasuredDate = DateTime.Today;
                SaveExperimentalRuns();
            }
            else
            {
                SaveExperimentalMeasurements();
            }
            RefreshExperimentalSeriesResults();
            RefreshExperimentalStatus();
        }), DispatcherPriority.ContextIdle);
    }

    private void ExperimentalRunsGrid_PreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
    {
        var cell = FindVisualParent<DataGridCell>(e.OriginalSource as DependencyObject);
        if (cell?.DataContext is not ExperimentalRunRecord row) return;
        _lastSelectedExperimentalRun = row;
        if (sender is DataGrid grid)
        {
            grid.SelectedItem = row;
            grid.CurrentCell = new DataGridCellInfo(row, cell.Column);

            // SelectionUnit=CellOrRowHeader does not reliably raise SelectionChanged when the
            // user clicks another cell-row. Rebind the currently visible measurement editor
            // after WPF finishes changing the current cell so the new RunID is active at once.
            Dispatcher.BeginInvoke(new Action(() => ActivateExperimentalRun(row)), DispatcherPriority.ContextIdle);
        }
        var header = cell.Column.Header?.ToString();
        if (header == "Baseline")
        {
            foreach (var other in _experimentalRunRows.Where(x => x.MaterialExperimentId == row.MaterialExperimentId && !ReferenceEquals(x,row))) other.IsBaseline = false;
            row.IsBaseline = !row.IsBaseline; SaveExperimentalRuns(); RefreshExperimentalSeriesResults(); e.Handled = true;
        }
        else if (header == "Active")
        {
            row.IsActive = !row.IsActive;
            SaveExperimentalRuns();
            RefreshExperimentalSeriesResults();
            e.Handled = true;
        }
    }

    private void ExperimentalRunsGrid_CellEditEnding(object sender, DataGridCellEditEndingEventArgs e)
    {
        Dispatcher.BeginInvoke(new Action(() => { SaveExperimentalRuns(); RefreshExperimentalStatus(); }), DispatcherPriority.ContextIdle);
    }

    private void AddMaterialExperiment_Click(object sender, RoutedEventArgs e)
    {
        var material = _lastSelectedNativeMaterial;
        if (material is null || !_nativeMaterialRows.Contains(material) || material.IsArchived)
            material = _nativeMaterialRows.FirstOrDefault(m => !m.IsArchived && !string.IsNullOrWhiteSpace(m.MaterialID));

        var definition = _experimentDefinitions.FirstOrDefault();
        var row = new MaterialExperimentRecord
        {
            MaterialExperimentId = "XPT-" + Guid.NewGuid().ToString("N")[..8].ToUpperInvariant(),
            MaterialID = material?.MaterialID ?? string.Empty,
            MaterialDisplayName = material is null ? string.Empty : $"{material.Manufacturer} {material.WebsiteDisplayName}".Trim(),
            ExperimentDefinitionId = definition?.ExperimentDefinitionId ?? string.Empty,
            ExperimentName = definition?.Name ?? string.Empty,
            ParameterUnit = definition?.DefaultUnit ?? string.Empty,
            BaselineMaterialID = material?.MaterialID ?? string.Empty,
            BaselineMaterialDisplayName = material is null ? string.Empty : $"{material.Manufacturer} {material.WebsiteDisplayName}".Trim(),
            IsActive = true,
            CreatedAtUtc = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture)
        };

        // Keep collection mutation, SQLite persistence, and DataGrid focus as separate phases.
        // This avoids re-entering ListCollectionView while it is handling CollectionChanged.
        _materialExperimentRows.Add(row);
        SaveMaterialExperiments();
        RefreshExperimentalStatus();

        // Do not force DataGrid selection, scrolling or edit focus here.
        // WPF can still be finalizing the collection-view change after Add(), and
        // changing SelectedItem/ScrollIntoView from a dispatcher callback may throw
        // InvalidOperationException even though the row was already created and saved.
    }

    private void DuplicateMaterialExperiment_Click(object sender, RoutedEventArgs e)
    {
        if (FindName("MaterialExperimentsGrid") is not DataGrid grid) return;
        var source = grid.CurrentCell.Item as MaterialExperimentRecord ?? grid.SelectedItem as MaterialExperimentRecord ?? _lastSelectedMaterialExperiment;
        if (source is null) return;
        var row = new MaterialExperimentRecord
        {
            MaterialExperimentId = "XPT-" + Guid.NewGuid().ToString("N")[..8].ToUpperInvariant(),
            MaterialID = source.MaterialID,
            MaterialDisplayName = source.MaterialDisplayName,
            ExperimentDefinitionId = source.ExperimentDefinitionId,
            ExperimentName = source.ExperimentName,
            ParameterValue = source.ParameterValue,
            ParameterUnit = source.ParameterUnit,
            BaselineMaterialID = source.BaselineMaterialID,
            BaselineMaterialDisplayName = source.BaselineMaterialDisplayName,
            Notes = source.Notes,
            IsActive = source.IsActive,
            CreatedAtUtc = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture)
        };
        _materialExperimentRows.Add(row);
        SaveMaterialExperiments();
        RefreshExperimentalStatus();
        // Keep duplicate creation independent from DataGrid focus/selection state.
        // The new row appears through ObservableCollection notification and remains persisted.
    }

    private void DeleteMaterialExperiment_Click(object sender, RoutedEventArgs e)
    {
        if (IsAutomationActionBlocked("Experimental series deletion")) return;
        if (FindName("MaterialExperimentsGrid") is not DataGrid grid) return;
        var row = grid.CurrentCell.Item as MaterialExperimentRecord ?? grid.SelectedItem as MaterialExperimentRecord ?? _lastSelectedMaterialExperiment;
        if (row is null)
        {
            MessageBox.Show(this, "Select an experimental record first.", "Experimental Testing", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }
        if (MessageBox.Show(this, $"Delete experimental record {row.MaterialExperimentId}?", "Experimental Testing", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
        grid.CommitEdit(DataGridEditingUnit.Cell, true);
        grid.CommitEdit(DataGridEditingUnit.Row, true);
        _materialExperimentRows.Remove(row);
        var deletedRunIds = _experimentalRunRows.Where(x => x.MaterialExperimentId == row.MaterialExperimentId).Select(x => x.ExperimentalRunId).ToHashSet(StringComparer.OrdinalIgnoreCase);
        foreach (var run in _experimentalRunRows.Where(x => deletedRunIds.Contains(x.ExperimentalRunId)).ToList()) _experimentalRunRows.Remove(run);
        foreach (var measurement in _experimentalMeasurementRows.Where(x => deletedRunIds.Contains(x.ExperimentalRunId)).ToList()) _experimentalMeasurementRows.Remove(measurement);
        SaveExperimentalRuns();
        if (ReferenceEquals(_lastSelectedMaterialExperiment, row)) _lastSelectedMaterialExperiment = null;
        SaveMaterialExperiments();
        RefreshExperimentalStatus();
    }

    private void MaterialExperimentsGrid_PreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
    {
        if (sender is not DataGrid grid) return;
        var cell = FindVisualParent<DataGridCell>(e.OriginalSource as DependencyObject);
        if (cell?.DataContext is not MaterialExperimentRecord row) return;

        // Cell-based editing does not create a row SelectedItem. Keep an explicit,
        // stable current record for Duplicate/Delete without forcing row selection.
        _lastSelectedMaterialExperiment = row;
        var seriesChanged = !ReferenceEquals(_selectedExperimentalSeries, row);
        void QueueSeriesActivation()
        {
            if (!seriesChanged) return;
            Dispatcher.BeginInvoke(new Action(() => ActivateExperimentalSeries(row)),
                System.Windows.Threading.DispatcherPriority.ContextIdle);
        }

        grid.CurrentCell = new DataGridCellInfo(row, cell.Column);

        // DataGridCheckBoxColumn normally defers binding until the edit ends. Handle
        // governed checkboxes directly so confirmation and persistence occur on the click.
        var header = cell.Column.Header?.ToString();
        if (string.Equals(header, "Website", StringComparison.Ordinal))
        {
            var requestedPublishing = !row.PublishOnWebsite;
            var readiness = GetExperimentalPublicationReadiness(row);
            var confirmedIncomplete = false;
            if (requestedPublishing && !readiness.Ready)
            {
                confirmedIncomplete = MessageBox.Show(
                    this,
                    readiness.Detail + "\n\nInclude this incomplete Series in Website output anyway?",
                    "Experimental publication readiness",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Warning,
                    MessageBoxResult.No) == MessageBoxResult.Yes;
            }

            var resolvedPublishing = ResolveExperimentalPublicationRequest(
                requestedPublishing,
                readiness.Ready,
                confirmedIncomplete);
            if (row.PublishOnWebsite != resolvedPublishing)
            {
                row.PublishOnWebsite = resolvedPublishing;
                SaveMaterialExperiments();
            }
            RefreshExperimentalStatus();
            RefreshExperimentalPublicationReadiness(row);
            e.Handled = true;
        }
        else if (string.Equals(header, "Active", StringComparison.Ordinal))
        {
            row.IsActive = !row.IsActive;
            row.UpdatedAtUtc = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture);
            SaveMaterialExperiments();
            RefreshExperimentalStatus();
            e.Handled = true;
        }

        // Defer the complete Series context transition until the governed checkbox
        // decision and mouse/edit transaction have finished. This prevents a modal
        // readiness prompt from pumping a queued context change while it is open.
        QueueSeriesActivation();
    }

    private static bool ResolveExperimentalPublicationRequest(
        bool requestedPublishing,
        bool readinessReady,
        bool confirmedIncomplete) =>
        requestedPublishing && (readinessReady || confirmedIncomplete);

    private void MaterialExperimentsGrid_CellEditEnding(object sender, DataGridCellEditEndingEventArgs e)
    {
        // Never rebuild DataGridComboBoxColumn.ItemsSource or refresh the ListCollectionView
        // while a ComboBox edit transaction is closing. WPF throws InvalidOperationException
        // when the active dropdown's collection/view is mutated from this callback.
        Dispatcher.BeginInvoke(new Action(() =>
        {
            if (e.Row.Item is MaterialExperimentRecord row)
            {
                var definition = _experimentDefinitions.FirstOrDefault(x => x.ExperimentDefinitionId == row.ExperimentDefinitionId);
                if (definition is not null && string.IsNullOrWhiteSpace(row.ParameterUnit))
                    row.ParameterUnit = definition.DefaultUnit;

                UpdateExperimentalDisplayLabels(row);
            }

            SaveMaterialExperiments();
            RefreshExperimentalStatus();
            RefreshExperimentalPublicationReadiness(e.Row.Item as MaterialExperimentRecord);
        }), DispatcherPriority.ContextIdle);
    }

    private void UpdateExperimentalDisplayLabels(MaterialExperimentRecord row)
    {
        var material = _nativeMaterialRows.FirstOrDefault(x => string.Equals(x.MaterialID, row.MaterialID, StringComparison.OrdinalIgnoreCase));
        row.MaterialDisplayName = material is null ? row.MaterialID : $"{material.Manufacturer} {material.WebsiteDisplayName}".Trim();

        var baseline = _nativeMaterialRows.FirstOrDefault(x => string.Equals(x.MaterialID, row.BaselineMaterialID, StringComparison.OrdinalIgnoreCase));
        row.BaselineMaterialDisplayName = baseline is null ? row.BaselineMaterialID : $"{baseline.Manufacturer} {baseline.WebsiteDisplayName}".Trim();

        var definition = _experimentDefinitions.FirstOrDefault(x => string.Equals(x.ExperimentDefinitionId, row.ExperimentDefinitionId, StringComparison.OrdinalIgnoreCase));
        row.ExperimentName = definition?.Name ?? row.ExperimentDefinitionId;
    }

    private void ExperimentalFilter_Changed(object sender, RoutedEventArgs e)
    {
        if (_suppressExperimentalFilterRefresh) return;
        QueueExperimentalFilterRefresh();
    }

    private void ClearExperimentalFilters_Click(object sender, RoutedEventArgs e)
    {
        _suppressExperimentalFilterRefresh = true;
        try
        {
            if (FindName("ExperimentalSearchTextBox") is TextBox search) search.Text = string.Empty;
            if (FindName("ExperimentalActiveOnlyCheckBox") is CheckBox active) active.IsChecked = false;
        }
        finally
        {
            _suppressExperimentalFilterRefresh = false;
        }
        QueueExperimentalFilterRefresh();
    }

    private void QueueExperimentalFilterRefresh()
    {
        Dispatcher.BeginInvoke(new Action(() =>
        {
            if (FindName("MaterialExperimentsGrid") is DataGrid grid)
            {
                grid.CommitEdit(DataGridEditingUnit.Cell, true);
                grid.CommitEdit(DataGridEditingUnit.Row, true);
            }
            _materialExperimentView?.Refresh();
            RefreshExperimentalStatus();
        }), DispatcherPriority.ContextIdle);
    }

    private void RefreshExperimentalStatus()
    {
        if (FindName("ExperimentalStatusText") is not TextBlock text) return;
        var visible = _materialExperimentView?.OfType<MaterialExperimentRecord>().Count() ?? _materialExperimentRows.Count;
        var active = _materialExperimentRows.Count(x => x.IsActive);
        var linked = _materialExperimentRows.Count(x => _nativeMaterialRows.Any(m => string.Equals(m.MaterialID, x.MaterialID, StringComparison.OrdinalIgnoreCase)));
        var selectedRuns = _selectedExperimentalSeries is null ? 0 : _experimentalRunRows.Count(x => x.MaterialExperimentId == _selectedExperimentalSeries.MaterialExperimentId);
        text.Text = $"{visible} series visible • {_materialExperimentRows.Count} total • {active} active • {linked}/{_materialExperimentRows.Count} MaterialID links valid • {selectedRuns} run(s) in selected series";
        if (_selectedExperimentalSeries is not null)
        {
            var selectedActiveRuns = _experimentalRunRows.Count(run =>
                run.MaterialExperimentId == _selectedExperimentalSeries.MaterialExperimentId && run.IsActive);
            var selectedInactiveRuns = _experimentalRunRows.Count(run =>
                run.MaterialExperimentId == _selectedExperimentalSeries.MaterialExperimentId && !run.IsActive);
            text.Text += $" ({selectedActiveRuns} active, {selectedInactiveRuns} inactive)";
        }
    }

    private InventorySummary BuildInventorySummary()
    {
        var materials = _nativeMaterialRows.ToDictionary(x => x.MaterialID, StringComparer.OrdinalIgnoreCase);
        return _inventoryEngineService.Calculate(_inventorySpoolRows.Select(x =>
        {
            materials.TryGetValue(x.MaterialId, out var material);
            return new InventoryItemInput
            {
                InventoryItemId = x.InventoryItemId, MaterialID = x.MaterialId, DisplayName = material?.WebsiteDisplayName ?? x.MaterialId, Manufacturer = material?.Manufacturer ?? "", BaseMaterial = material?.BaseMaterial ?? "",
                StorageLocation = x.StorageLocation, Status = x.Status, Quantity = x.Quantity, SpoolWeightG = x.SpoolWeightG, RemainingWeightG = x.RemainingWeightG, PurchasePriceAmount = x.PurchasePriceAmount, Currency = x.PurchaseCurrency, IsArchived = material?.IsArchived ?? false
            };
        }));
    }

    private NativeBaseMaterialRow? ResolveBaseMaterialCatalogRow(
        NativeMaterialRow? material,
        string? legacyBaseMaterial = null)
    {
        if (material?.BaseMaterialId is long baseMaterialId)
        {
            return _nativeBaseMaterialRows.FirstOrDefault(row =>
                row.BaseMaterialId == baseMaterialId);
        }

        var legacyName = material?.BaseMaterial ?? legacyBaseMaterial ?? string.Empty;
        if (string.IsNullOrWhiteSpace(legacyName)) return null;
        var matches = _nativeBaseMaterialRows.Where(row =>
                string.Equals(
                    row.BaseMaterial?.Trim(),
                    legacyName.Trim(),
                    StringComparison.OrdinalIgnoreCase))
            .Take(2)
            .ToList();
        return matches.Count == 1 ? matches[0] : null;
    }

    private void ResolveLinkedBaseMaterialNames()
    {
        var changed = false;
        foreach (var material in _nativeMaterialRows.Where(row => row.BaseMaterialId.HasValue))
        {
            var catalogRow = ResolveBaseMaterialCatalogRow(material);
            if (catalogRow is null) continue;
            if (string.Equals(material.BaseMaterial, catalogRow.BaseMaterial, StringComparison.Ordinal)) continue;
            material.BaseMaterial = catalogRow.BaseMaterial;
            changed = true;
        }

        if (changed)
        {
            _database.ReplaceNativeMaterialManagerRows(
                _nativeMaterialRows.Select(NativeMaterialRecordFromRow));
        }
    }

    private void InitializeUsageWorkspace()
    {
        UsageEventTypeSelector.ItemsSource = Enum.GetValues<UsageEventType>();
        UsageEventTypeSelector.SelectedItem = UsageEventType.TestPrint;
        UsageProvenanceSelector.ItemsSource = Enum.GetValues<UsageQuantityProvenance>();
        UsageProvenanceSelector.SelectedItem = UsageQuantityProvenance.NotRecorded;
        UsageOccurredAtUtcTextBox.Text =
            DateTimeOffset.UtcNow.ToString("yyyy-MM-dd HH:mm:ss 'UTC'", CultureInfo.InvariantCulture);
        UsageSourceTextBox.Text = "Manual entry";
        RefreshUsageWorkspace();
    }

    private void RefreshUsageWorkspace()
    {
        var selectedMaterialId =
            _usageSelectedMaterialId ??
            UsageMaterialSelector.SelectedValue?.ToString() ??
            _lastSelectedNativeMaterial?.MaterialID;
        var materials = _nativeMaterialRows
            .Where(row => !row.IsArchived)
            .OrderBy(row => row.WebsiteDisplayName)
            .ThenBy(row => row.MaterialID)
            .ToList();
        UsageMaterialSelector.ItemsSource = materials;
        var selected = materials.FirstOrDefault(row =>
                           row.MaterialID.Equals(
                               selectedMaterialId,
                               StringComparison.OrdinalIgnoreCase))
                       ?? materials.FirstOrDefault();
        UsageMaterialSelector.SelectedItem = selected;
        RefreshUsageMaterialContext(selected?.MaterialID);
    }

    private void UsageMaterialSelector_SelectionChanged(
        object sender,
        SelectionChangedEventArgs e)
    {
        RefreshUsageMaterialContext(UsageMaterialSelector.SelectedValue?.ToString());
    }

    private void RefreshUsageMaterialContext(string? materialId)
    {
        _usageSelectedMaterialId = string.IsNullOrWhiteSpace(materialId)
            ? null
            : materialId;
        var selectedInventoryId = UsageInventorySelector.SelectedValue?.ToString();
        var inventory = string.IsNullOrWhiteSpace(materialId)
            ? new List<InventorySpoolRecord>()
            : _database.LoadInventorySpoolItems()
                .Where(item => item.MaterialId.Equals(
                    materialId,
                    StringComparison.OrdinalIgnoreCase))
                .OrderBy(item => item.InventoryItemId)
                .ToList();
        UsageInventorySelector.ItemsSource = inventory;
        UsageInventorySelector.SelectedItem = inventory.FirstOrDefault(item =>
            item.InventoryItemId.Equals(
                selectedInventoryId,
                StringComparison.OrdinalIgnoreCase));

        var events = string.IsNullOrWhiteSpace(materialId)
            ? new List<UsageEventRecord>()
            : _database.LoadUsageEvents()
                .Where(item => item.MaterialId.Equals(
                    materialId,
                    StringComparison.OrdinalIgnoreCase))
                .OrderByDescending(item => item.OccurredAtUtc)
                .ThenByDescending(item => item.CreatedAtUtc)
                .ToList();
        var projection = string.IsNullOrWhiteSpace(materialId)
            ? null
            : _usageEventDomainService.ProjectMaterial(materialId, events);
        UsageLedgerGrid.ItemsSource = events;
        UsageEffectiveEventsText.Text =
            projection?.EffectiveEventCount.ToString("N0", CultureInfo.CurrentCulture) ?? "0";
        UsageLedgerRowsText.Text =
            projection?.LedgerRowCount.ToString("N0", CultureInfo.CurrentCulture) ?? "0";
        UsageFilamentTotalText.Text = projection is null ||
                                      projection.FilamentEvidenceEventCount == 0
            ? "Not recorded"
            : $"{projection.FilamentUsedGrams:N2} g";
        UsagePrintTimeTotalText.Text = projection is null ||
                                      projection.PrintDurationEvidenceEventCount == 0
            ? "Not recorded"
            : FormatUsageDuration(projection.PrintDurationSeconds);
        UsageHandsOnTimeTotalText.Text = projection is null ||
                                        projection.HandsOnDurationEvidenceEventCount == 0
            ? "Not recorded"
            : FormatUsageDuration(projection.HandsOnDurationSeconds);
        UsagePartsTotalText.Text = projection is null
            ? "Not recorded"
            : $"Produced {FormatUsageCount(projection.ProducedCount)}\n" +
              $"Accepted {FormatUsageCount(projection.AcceptedCount)}\n" +
              $"Rejected {FormatUsageCount(projection.RejectedCount)}";
        UsageCoverageText.Text = projection is null
            ? "No MaterialID selected"
            : $"Grams {projection.FilamentEvidenceEventCount}/{projection.EffectiveEventCount}\n" +
              $"Print {projection.PrintDurationEvidenceEventCount}/{projection.EffectiveEventCount}\n" +
              $"Hands-on {projection.HandsOnDurationEvidenceEventCount}/{projection.EffectiveEventCount}";
        UsageMaterialIdentityText.Text = string.IsNullOrWhiteSpace(materialId)
            ? "No canonical MaterialID selected"
            : $"Canonical MaterialID: {materialId}";
        UsageStatusText.Text =
            $"{events.Count:N0} immutable event row(s); {inventory.Count:N0} exact linked inventory spool choice(s). " +
            "Usage remains private and is not included in public reports or website output.";
    }

    private void SaveUsageEvent_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            var materialId = UsageMaterialSelector.SelectedValue?.ToString()?.Trim();
            if (string.IsNullOrWhiteSpace(materialId))
                throw new InvalidOperationException("Select one canonical MaterialID.");

            var now = DateTimeOffset.UtcNow;
            var occurred = ParseUsageUtc(UsageOccurredAtUtcTextBox.Text);
            var usageEvent = new UsageEventRecord
            {
                UsageEventId = "USE-" + now.ToString(
                    "yyyyMMddHHmmssfff",
                    CultureInfo.InvariantCulture) + "-" +
                    Guid.NewGuid().ToString("N")[..8].ToUpperInvariant(),
                MaterialId = materialId,
                EventType = UsageEventTypeSelector.SelectedItem is UsageEventType eventType
                    ? eventType
                    : UsageEventType.TestPrint,
                OccurredAtUtc = occurred,
                CreatedAtUtc = now,
                InventoryItemId =
                    UsageInventorySelector.SelectedValue?.ToString(),
                FilamentUsedGrams = ParseNullableUsageDecimal(
                    UsageFilamentGramsTextBox.Text,
                    "Filament grams"),
                FilamentProvenance =
                    UsageProvenanceSelector.SelectedItem is UsageQuantityProvenance provenance
                        ? provenance
                        : UsageQuantityProvenance.NotRecorded,
                PrintDurationSeconds = ParseNullableUsageSeconds(
                    UsagePrintMinutesTextBox.Text,
                    "Print minutes"),
                HandsOnDurationSeconds = ParseNullableUsageSeconds(
                    UsageHandsOnMinutesTextBox.Text,
                    "Hands-on minutes"),
                ProducedCount = ParseNullableUsageCount(
                    UsageProducedCountTextBox.Text,
                    "Produced"),
                AcceptedCount = ParseNullableUsageCount(
                    UsageAcceptedCountTextBox.Text,
                    "Accepted"),
                RejectedCount = ParseNullableUsageCount(
                    UsageRejectedCountTextBox.Text,
                    "Rejected"),
                Source = UsageSourceTextBox.Text.Trim(),
                Note = UsageNoteTextBox.Text.Trim(),
                Origin = "Bounded Usage UI"
            };

            if (string.IsNullOrWhiteSpace(_usageCorrectionOriginalId))
            {
                _database.AppendUsageEventAtomic(usageEvent);
                UsageStatusText.Text =
                    $"Recorded immutable UsageEvent {usageEvent.UsageEventId}.";
            }
            else
            {
                _database.AppendUsageCorrectionAtomic(
                    _usageCorrectionOriginalId,
                    usageEvent,
                    "USE-REV-" + now.ToString(
                        "yyyyMMddHHmmssfff",
                        CultureInfo.InvariantCulture) + "-" +
                    Guid.NewGuid().ToString("N")[..8].ToUpperInvariant(),
                    now,
                    "Bounded Usage UI correction",
                    UsageNoteTextBox.Text.Trim());
                UsageStatusText.Text =
                    $"Appended reversal and replacement for {_usageCorrectionOriginalId}.";
            }

            ReloadInventorySpoolsFromCanonicalDatabase();
            EndUsageCorrection(clearInputs: true);
            RefreshUsageMaterialContext(materialId);
        }
        catch (Exception ex)
        {
            UsageStatusText.Text = "Usage save blocked: " + ex.Message;
            MessageBox.Show(
                this,
                ex.Message,
                "Usage Save Blocked",
                MessageBoxButton.OK,
                MessageBoxImage.Warning);
        }
    }

    private void BeginUsageCorrection_Click(object sender, RoutedEventArgs e)
    {
        if (UsageLedgerGrid.SelectedItem is not UsageEventRecord selected)
        {
            UsageStatusText.Text = "Select one ledger row to correct.";
            return;
        }

        var accepted = _database.LoadUsageEvents();
        if (selected.EntryKind == UsageEventEntryKind.Reversal ||
            accepted.Any(item => string.Equals(
                item.ReversesUsageEventId,
                selected.UsageEventId,
                StringComparison.OrdinalIgnoreCase)))
        {
            UsageStatusText.Text =
                "Selected event cannot be corrected because it is a reversal or already has a reversal.";
            return;
        }

        _usageCorrectionOriginalId = selected.UsageEventId;
        UsageMaterialSelector.SelectedValue = selected.MaterialId;
        RefreshUsageMaterialContext(selected.MaterialId);
        UsageInventorySelector.SelectedValue = selected.InventoryItemId;
        UsageEventTypeSelector.SelectedItem = selected.EventType;
        UsageOccurredAtUtcTextBox.Text =
            selected.OccurredAtUtc.ToString(
                "yyyy-MM-dd HH:mm:ss 'UTC'",
                CultureInfo.InvariantCulture);
        UsageFilamentGramsTextBox.Text =
            selected.FilamentUsedGrams?.ToString(CultureInfo.CurrentCulture) ?? string.Empty;
        UsageProvenanceSelector.SelectedItem = selected.FilamentProvenance;
        UsagePrintMinutesTextBox.Text = FormatUsageMinutes(selected.PrintDurationSeconds);
        UsageHandsOnMinutesTextBox.Text = FormatUsageMinutes(selected.HandsOnDurationSeconds);
        UsageProducedCountTextBox.Text =
            selected.ProducedCount?.ToString(CultureInfo.CurrentCulture) ?? string.Empty;
        UsageAcceptedCountTextBox.Text =
            selected.AcceptedCount?.ToString(CultureInfo.CurrentCulture) ?? string.Empty;
        UsageRejectedCountTextBox.Text =
            selected.RejectedCount?.ToString(CultureInfo.CurrentCulture) ?? string.Empty;
        UsageSourceTextBox.Text = selected.Source;
        UsageNoteTextBox.Text = selected.Note;
        SaveUsageEventButton.Content = "Save Correction";
        CancelUsageCorrectionButton.Visibility = Visibility.Visible;
        UsageStatusText.Text =
            $"Correction draft for {selected.UsageEventId}. Saving appends reversal + replacement.";
    }

    private void CancelUsageCorrection_Click(object sender, RoutedEventArgs e) =>
        EndUsageCorrection(clearInputs: false);

    private void EndUsageCorrection(bool clearInputs)
    {
        _usageCorrectionOriginalId = null;
        SaveUsageEventButton.Content = "Record Usage";
        CancelUsageCorrectionButton.Visibility = Visibility.Collapsed;
        if (!clearInputs) return;
        UsageOccurredAtUtcTextBox.Text =
            DateTimeOffset.UtcNow.ToString("yyyy-MM-dd HH:mm:ss 'UTC'", CultureInfo.InvariantCulture);
        UsageFilamentGramsTextBox.Clear();
        UsageProvenanceSelector.SelectedItem = UsageQuantityProvenance.NotRecorded;
        UsagePrintMinutesTextBox.Clear();
        UsageHandsOnMinutesTextBox.Clear();
        UsageProducedCountTextBox.Clear();
        UsageAcceptedCountTextBox.Clear();
        UsageRejectedCountTextBox.Clear();
        UsageNoteTextBox.Clear();
    }

    private static DateTimeOffset ParseUsageUtc(string text)
    {
        if (!DateTimeOffset.TryParse(
                text.Replace("UTC", "+00:00", StringComparison.OrdinalIgnoreCase),
                CultureInfo.InvariantCulture,
                DateTimeStyles.AllowWhiteSpaces,
                out var parsed))
            throw new InvalidOperationException(
                "Occurred UTC must be a valid timestamp, for example 2026-07-26 17:30:00 UTC.");
        return parsed.ToUniversalTime();
    }

    private static decimal? ParseNullableUsageDecimal(string text, string label)
    {
        if (string.IsNullOrWhiteSpace(text)) return null;
        if (decimal.TryParse(text, NumberStyles.Number, CultureInfo.CurrentCulture, out var value) ||
            decimal.TryParse(
                text.Replace(',', '.'),
                NumberStyles.Number,
                CultureInfo.InvariantCulture,
                out value))
            return value;
        throw new InvalidOperationException(label + " must be numeric or blank.");
    }

    private static long? ParseNullableUsageSeconds(string text, string label)
    {
        var minutes = ParseNullableUsageDecimal(text, label);
        if (!minutes.HasValue) return null;
        return checked((long)Math.Round(
            minutes.Value * 60m,
            MidpointRounding.AwayFromZero));
    }

    private static int? ParseNullableUsageCount(string text, string label)
    {
        if (string.IsNullOrWhiteSpace(text)) return null;
        if (int.TryParse(text, NumberStyles.Integer, CultureInfo.CurrentCulture, out var value))
            return value;
        throw new InvalidOperationException(label + " must be a whole number or blank.");
    }

    private static string FormatUsageMinutes(long? seconds) =>
        seconds.HasValue
            ? (seconds.Value / 60m).ToString("0.##", CultureInfo.CurrentCulture)
            : string.Empty;

    private static string FormatUsageDuration(long? seconds)
    {
        if (!seconds.HasValue) return "Not recorded";
        var duration = TimeSpan.FromSeconds(seconds.Value);
        return Math.Abs(duration.TotalHours) >= 1
            ? $"{duration.TotalHours:0.##} h"
            : $"{duration.TotalMinutes:0.##} min";
    }

    private static string FormatUsageCount(int? value) =>
        value?.ToString("N0", CultureInfo.CurrentCulture) ?? "Not recorded";

    private void InitializeInventorySpoolManager()
    {
        foreach (var row in _database.LoadInventorySpoolItems()) _inventorySpoolRows.Add(row);
        if (_inventorySpoolRows.Count == 0)
        {
            foreach (var m in _nativeMaterialRows.Where(x => !string.IsNullOrWhiteSpace(x.InventoryId) || !string.IsNullOrWhiteSpace(x.RemainingWeightG) || !string.IsNullOrWhiteSpace(x.PurchasePriceAmount)))
                _inventorySpoolRows.Add(new InventorySpoolRecord { InventoryItemId = string.IsNullOrWhiteSpace(m.InventoryId) ? Guid.NewGuid().ToString("N")[..12].ToUpperInvariant() : m.InventoryId, MaterialId = m.MaterialID, Status = m.InventoryStatus, Quantity = m.Quantity, SpoolWeightG = m.SpoolWeightG, RemainingWeightG = m.RemainingWeightG, StorageLocation = m.StorageLocation, BatchNumber = m.BatchNumber, PurchaseId = m.PurchaseId, PurchasedFrom = m.PurchasedFrom, PurchaseDate = m.PurchaseDate, OrderNumber = m.OrderNumber, PurchasePriceAmount = m.PurchasePriceAmount, PurchaseCurrency = m.PurchaseCurrency, ShippingAmount = m.ShippingAmount, VatAmount = m.VatAmount });
            SaveInventorySpools();
        }
        if (FindName("InventorySpoolGrid") is DataGrid grid)
        {
            // Use a dedicated ListCollectionView for the editable spool grid. This avoids
            // sharing the default collection view with other consumers and ensures that
            // Inventory search/filter changes always affect the editable records directly.
            _inventorySpoolView = new ListCollectionView(_inventorySpoolRows);
            _inventorySpoolView.Filter = InventorySpoolFilter;
            ApplyInventoryDefaultSort(_inventorySpoolView, editableRows: true);
            grid.ItemsSource = _inventorySpoolView;
            RefreshInventoryMaterialChoices();
        }
        _inventorySpoolRows.CollectionChanged += (_, _) =>
        {
            if (_isReloadingInventorySpools) return;
            SaveInventorySpools();
            SyncMaterialInventoryQuantityFromSpools(persist: true);
            RefreshInventorySummary();
        };
        SyncMaterialInventoryQuantityFromSpools(persist: false);
        RefreshInventorySummary();
    }

    private void RefreshInventoryMaterialChoices()
    {
        if (FindName("InventorySpoolGrid") is not DataGrid grid) return;
        if (grid.Columns.OfType<DataGridComboBoxColumn>().FirstOrDefault(c => (c.Header?.ToString() ?? "").Contains("material", StringComparison.OrdinalIgnoreCase)) is not { } materialColumn) return;

        var choices = _nativeMaterialRows
            .Where(m => !m.IsArchived && !string.IsNullOrWhiteSpace(m.MaterialID))
            .Select(m => new KeyValuePair<string, string>(
                m.MaterialID,
                $"{m.Manufacturer} {m.WebsiteDisplayName}".Trim()))
            .OrderBy(x => x.Value, StringComparer.CurrentCultureIgnoreCase)
            .ThenBy(x => x.Key, StringComparer.OrdinalIgnoreCase)
            .ToList();
        materialColumn.ItemsSource = choices;
        var labels = choices.ToDictionary(x => x.Key, x => x.Value, StringComparer.OrdinalIgnoreCase);
        foreach (var spool in _inventorySpoolRows)
            spool.MaterialDisplayName = labels.TryGetValue(spool.MaterialId, out var label) ? label : spool.MaterialId;
        _inventorySpoolView?.Refresh();
    }

    private void SaveInventorySpools() => _database.ReplaceInventorySpoolItems(_inventorySpoolRows);

    private void ReloadInventorySpoolsFromCanonicalDatabase()
    {
        _isReloadingInventorySpools = true;
        try
        {
            _inventorySpoolRows.Clear();
            foreach (var row in _database.LoadInventorySpoolItems()) _inventorySpoolRows.Add(row);
        }
        finally
        {
            _isReloadingInventorySpools = false;
        }

        RefreshInventoryMaterialChoices();
        SyncMaterialInventoryQuantityFromSpools(persist: false);
        RefreshInventorySummary();
    }

    /// <summary>
    /// Quantity in Materials is an aggregate display owned by the spool table.
    /// Individual spool/group quantities are edited only in Inventory.
    /// </summary>
    private void SyncMaterialInventoryQuantityFromSpools(bool persist)
    {
        var quantities = _inventorySpoolRows
            .Where(x => !string.IsNullOrWhiteSpace(x.MaterialId))
            .GroupBy(x => x.MaterialId, StringComparer.OrdinalIgnoreCase)
            .ToDictionary(
                g => g.Key,
                g => g.Sum(x => int.TryParse(x.Quantity, NumberStyles.Integer, CultureInfo.InvariantCulture, out var q) && q > 0 ? q : 0),
                StringComparer.OrdinalIgnoreCase);

        var changed = false;
        foreach (var material in _nativeMaterialRows)
        {
            var quantity = quantities.TryGetValue(material.MaterialID, out var total) && total > 0
                ? total.ToString(CultureInfo.InvariantCulture)
                : "0";
            if (!string.Equals(material.Quantity, quantity, StringComparison.Ordinal))
            {
                material.Quantity = quantity;
                changed = true;
            }
        }

        if (changed)
            RefreshNativeMaterialGridValidation();

        if (changed && persist)
            SaveNativeMaterialsSilent();
    }

    private void AddInventorySpool_Click(object sender, RoutedEventArgs e)
    {
        RefreshInventoryMaterialChoices();

        var material = _lastSelectedNativeMaterial;
        if (material is null || !_nativeMaterialRows.Contains(material))
            material = _nativeMaterialRows.FirstOrDefault(m => !m.IsArchived);
        var isFirstSpoolForMaterial = material is not null && !_inventorySpoolRows.Any(x =>
            string.Equals(x.MaterialId, material.MaterialID, StringComparison.OrdinalIgnoreCase));

        // The first spool created for a newly entered material inherits the purchasing
        // and spool defaults entered in Materials. Later Add Spool actions stay blank;
        // Duplicate is the explicit action for copying an existing spool record.
        var newSpool = new InventorySpoolRecord
        {
            InventoryItemId = "INV-" + Guid.NewGuid().ToString("N")[..8].ToUpperInvariant(),
            MaterialId = material?.MaterialID ?? "",
            Status = isFirstSpoolForMaterial && !string.IsNullOrWhiteSpace(material?.InventoryStatus)
                ? material.InventoryStatus
                : "Unopened",
            Quantity = "1",
            SpoolWeightG = isFirstSpoolForMaterial ? material?.SpoolWeightG ?? "" : "",
            RemainingWeightG = isFirstSpoolForMaterial ? material?.RemainingWeightG ?? "" : "",
            StorageLocation = isFirstSpoolForMaterial ? material?.StorageLocation ?? "" : "",
            BatchNumber = isFirstSpoolForMaterial ? material?.BatchNumber ?? "" : "",
            PurchaseId = isFirstSpoolForMaterial ? material?.PurchaseId ?? "" : "",
            PurchasedFrom = isFirstSpoolForMaterial ? material?.PurchasedFrom ?? "" : "",
            PurchaseDate = isFirstSpoolForMaterial ? material?.PurchaseDate ?? "" : "",
            OrderNumber = isFirstSpoolForMaterial ? material?.OrderNumber ?? "" : "",
            PurchasePriceAmount = isFirstSpoolForMaterial ? material?.PurchasePriceAmount ?? "" : "",
            PurchaseCurrency = isFirstSpoolForMaterial && !string.IsNullOrWhiteSpace(material?.PurchaseCurrency)
                ? material.PurchaseCurrency
                : "ISK",
            ShippingAmount = isFirstSpoolForMaterial ? material?.ShippingAmount ?? "" : "",
            VatAmount = isFirstSpoolForMaterial ? material?.VatAmount ?? "" : ""
        };
        _inventorySpoolRows.Add(newSpool);

        SelectInventoryRowForEditing(newSpool, "Material");
    }
    private void DuplicateInventorySpool_Click(object sender, RoutedEventArgs e)
    {
        if (FindName("InventorySpoolGrid") is not DataGrid grid || grid.SelectedItem is not InventorySpoolRecord x) return;
        var copy = new InventorySpoolRecord { InventoryItemId = "INV-" + Guid.NewGuid().ToString("N")[..8].ToUpperInvariant(), MaterialId=x.MaterialId, Status=x.Status, Quantity=x.Quantity, SpoolWeightG=x.SpoolWeightG, RemainingWeightG=x.RemainingWeightG, StorageLocation=x.StorageLocation, BatchNumber=x.BatchNumber, PurchaseId=x.PurchaseId, PurchaseOrderLineId=x.PurchaseOrderLineId, PurchasedFrom=x.PurchasedFrom, PurchaseDate=x.PurchaseDate, OrderNumber=x.OrderNumber, PurchasePriceAmount=x.PurchasePriceAmount, PurchaseCurrency=x.PurchaseCurrency, ShippingAmount=x.ShippingAmount, VatAmount=x.VatAmount, CustomsAmount=x.CustomsAmount, OtherFeesAmount=x.OtherFeesAmount, LandedCostAmount=x.LandedCostAmount, LandedCostCurrency=x.LandedCostCurrency, LandedCostConversionRate=x.LandedCostConversionRate, LandedCostRateSource=x.LandedCostRateSource, LandedCostRateObservationDate=x.LandedCostRateObservationDate, LandedCostRateFetchedAtUtc=x.LandedCostRateFetchedAtUtc, LandedCostCalculatedAtUtc=x.LandedCostCalculatedAtUtc, LandedCostCalculationVersion=x.LandedCostCalculationVersion, Notes=x.Notes };
        _inventorySpoolRows.Add(copy);
        SelectInventoryRowForEditing(copy, "Status");
    }
    private void DeleteInventorySpool_Click(object sender, RoutedEventArgs e)
    {
        if (IsAutomationActionBlocked("Inventory deletion")) return;
        if (FindName("InventorySpoolGrid") is not DataGrid grid || grid.SelectedItem is not InventorySpoolRecord x) return;
        if (MessageBox.Show(this, "Delete selected spool record?", "Inventory", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
        // ICollectionView may contain WPF's NewItemPlaceholder. Filter the view to
        // real inventory records instead of casting every view item directly.
        var visibleRows = _inventorySpoolView?.OfType<InventorySpoolRecord>().ToList()
            ?? _inventorySpoolRows.ToList();
        var index = visibleRows.IndexOf(x);

        _inventorySpoolRows.Remove(x);
        SaveInventorySpools();
        SyncMaterialInventoryQuantityFromSpools(persist: true);
        RefreshInventorySummary();

        var remainingVisibleRows = _inventorySpoolView?.OfType<InventorySpoolRecord>().ToList()
            ?? _inventorySpoolRows.ToList();
        var nextIndex = Math.Max(0, Math.Min(index, remainingVisibleRows.Count - 1));
        var next = remainingVisibleRows.ElementAtOrDefault(nextIndex);
        if (next is not null)
        {
            grid.SelectedItem = next;
            grid.ScrollIntoView(next);
        }
    }
    private void InventorySpoolGrid_CellEditEnding(object sender, DataGridCellEditEndingEventArgs e)
    {
        // CellEditEnding fires before WPF has fully closed its edit transaction.
        // Refreshing/sorting the collection view at Background priority can therefore
        // throw InvalidOperationException ("Refresh is not allowed during an edit transaction").
        Dispatcher.BeginInvoke(new Action(() =>
        {
            SaveInventorySpools();
            SyncMaterialInventoryQuantityFromSpools(persist: true);
            RefreshInventorySummary();
        }), DispatcherPriority.ContextIdle);
    }

    private void RefreshInventorySummary()
    {
        var summary = BuildInventorySummary();
        if (FindName("InventorySummaryGrid") is DataGrid grid)
        {
            _inventorySummaryView = CollectionViewSource.GetDefaultView(summary.Items);
            _inventorySummaryView.Filter = InventorySummaryFilter;
            ApplyInventoryDefaultSort(_inventorySummaryView, editableRows: false);
            grid.ItemsSource = _inventorySummaryView;
        }
        RefreshInventorySpoolViewSafely();
        UpdateInventoryVisibleCount();
        if (FindName("InventoryTotalSpoolsText") is TextBlock total) total.Text = summary.TotalSpools.ToString(CultureInfo.InvariantCulture);
        if (FindName("InventoryUnopenedText") is TextBlock unopened) unopened.Text = summary.UnopenedSpools.ToString(CultureInfo.InvariantCulture);
        if (FindName("InventoryOpenedText") is TextBlock opened) opened.Text = summary.OpenedSpools.ToString(CultureInfo.InvariantCulture);
        if (FindName("InventoryEmptyText") is TextBlock empty) empty.Text = summary.EmptySpools.ToString(CultureInfo.InvariantCulture);
        if (FindName("InventoryRemainingText") is TextBlock remaining) remaining.Text = $"{summary.TotalRemainingWeightG:N0} g\n{summary.RemainingPercent:N1}%";
        if (FindName("InventoryIssuesText") is TextBlock issues) issues.Text = summary.IssueCount.ToString(CultureInfo.InvariantCulture);
        if (FindName("InventoryValidationText") is TextBlock validation)
            validation.Text = summary.IssueCount == 0
                ? $"{summary.CompleteRows}/{summary.MaterialRows} inventory rows complete • No review warnings"
                : $"{summary.CompleteRows}/{summary.MaterialRows} inventory rows complete • {summary.IssueCount} row(s) need review";
        if (FindName("InventoryValueText") is TextBlock value)
        {
            value.Text = summary.EstimatedValueByCurrency.Count == 0
                ? "—"
                : string.Join("\n", summary.EstimatedValueByCurrency.OrderBy(x => x.Key).Select(x => $"{x.Value:N2} {x.Key}"));
        }
        if (FindName("InventoryAverageCostText") is TextBlock averageCost)
        {
            averageCost.Text = summary.AverageCostPerKgByCurrency.Count == 0
                ? "—"
                : string.Join("\n", summary.AverageCostPerKgByCurrency.OrderBy(x => x.Key).Select(x => $"{x.Value:N2} {x.Key}/kg"));
        }
    }

    private void ApplyInventoryDefaultSort(ICollectionView view, bool editableRows)
    {
        view.SortDescriptions.Clear();
        if (editableRows)
        {
            view.SortDescriptions.Add(new SortDescription(nameof(InventorySpoolRecord.MaterialDisplayName), ListSortDirection.Ascending));
            view.SortDescriptions.Add(new SortDescription(nameof(InventorySpoolRecord.Status), ListSortDirection.Ascending));
            view.SortDescriptions.Add(new SortDescription(nameof(InventorySpoolRecord.InventoryItemId), ListSortDirection.Ascending));
        }
        else
        {
            view.SortDescriptions.Add(new SortDescription(nameof(InventoryItemResult.DisplayName), ListSortDirection.Ascending));
            view.SortDescriptions.Add(new SortDescription(nameof(InventoryItemResult.Status), ListSortDirection.Ascending));
            view.SortDescriptions.Add(new SortDescription(nameof(InventoryItemResult.InventoryItemId), ListSortDirection.Ascending));
        }
    }

    private bool InventorySpoolFilter(object item)
    {
        if (item is not InventorySpoolRecord row) return false;
        var material = _nativeMaterialRows.FirstOrDefault(m => string.Equals(m.MaterialID, row.MaterialId, StringComparison.OrdinalIgnoreCase));
        return InventoryFilterMatches(row.Status, row.SpoolWeightG, row.RemainingWeightG, material?.IsArchived ?? false,
            row.InventoryItemId, row.MaterialDisplayName, material?.WebsiteDisplayName, material?.Manufacturer,
            row.PurchasedFrom, row.StorageLocation, row.BatchNumber, row.OrderNumber, row.Notes);
    }

    private bool InventorySummaryFilter(object item)
    {
        if (item is not InventoryItemResult row) return false;
        var material = _nativeMaterialRows.FirstOrDefault(m => string.Equals(m.MaterialID, row.MaterialID, StringComparison.OrdinalIgnoreCase));
        return InventoryFilterMatches(row.Status, row.SpoolWeightG?.ToString(CultureInfo.InvariantCulture), row.EffectiveRemainingWeightG.ToString(CultureInfo.InvariantCulture), material?.IsArchived ?? false,
            row.InventoryItemId, row.DisplayName, row.Manufacturer, row.StorageLocation, row.BaseMaterial, row.Validation);
    }

    private bool InventoryFilterMatches(string status, string? spoolWeightText, string? remainingWeightText, bool isArchived, params string?[] searchable)
    {
        var showEmpty = (FindName("InventoryShowEmptyCheckBox") as CheckBox)?.IsChecked != false;
        var onlyOpened = (FindName("InventoryOnlyOpenedCheckBox") as CheckBox)?.IsChecked == true;
        var lowStock = (FindName("InventoryLowStockCheckBox") as CheckBox)?.IsChecked == true;
        var showArchived = (FindName("InventoryShowArchivedCheckBox") as CheckBox)?.IsChecked == true;
        if (!showArchived && isArchived) return false;
        if (!showEmpty && string.Equals(status, "Empty", StringComparison.OrdinalIgnoreCase)) return false;
        if (onlyOpened && !string.Equals(status, "Opened", StringComparison.OrdinalIgnoreCase)) return false;
        if (lowStock)
        {
            if (!string.Equals(status, "Opened", StringComparison.OrdinalIgnoreCase)) return false;
            if (!TryInventoryDecimal(spoolWeightText, out var spoolWeight) || spoolWeight <= 0 || !TryInventoryDecimal(remainingWeightText, out var remaining) || remaining / spoolWeight >= 0.20m) return false;
        }
        var query = (FindName("InventorySearchTextBox") as TextBox)?.Text?.Trim();
        if (string.IsNullOrWhiteSpace(query)) return true;
        return searchable.Any(value => !string.IsNullOrWhiteSpace(value) && value.Contains(query, StringComparison.OrdinalIgnoreCase));
    }

    private static bool TryInventoryDecimal(string? value, out decimal result) =>
        decimal.TryParse((value ?? "").Replace(',', '.'), NumberStyles.Number, CultureInfo.InvariantCulture, out result);

    private void InventoryFilter_Changed(object sender, RoutedEventArgs e)
    {
        // Commit any active spool edit before refreshing the filtered view. The editable
        // grid is the primary Inventory list, so search/filter changes must be applied to
        // it first; the calculated view then mirrors the same filter state.
        if (FindName("InventorySpoolGrid") is DataGrid spoolGrid)
        {
            spoolGrid.CommitEdit(DataGridEditingUnit.Cell, true);
            spoolGrid.CommitEdit(DataGridEditingUnit.Row, true);
        }

        if (_inventorySpoolView is not null)
            _inventorySpoolView.Filter = InventorySpoolFilter;
        RefreshInventorySpoolViewSafely();

        if (_inventorySummaryView is not null)
        {
            _inventorySummaryView.Filter = InventorySummaryFilter;
            _inventorySummaryView.Refresh();
        }
        UpdateInventoryVisibleCount();
    }

    private void ClearInventoryFilters_Click(object sender, RoutedEventArgs e)
    {
        if (FindName("InventorySearchTextBox") is TextBox search) search.Clear();
        if (FindName("InventoryShowEmptyCheckBox") is CheckBox empty) empty.IsChecked = true;
        if (FindName("InventoryOnlyOpenedCheckBox") is CheckBox opened) opened.IsChecked = false;
        if (FindName("InventoryLowStockCheckBox") is CheckBox low) low.IsChecked = false;
        if (FindName("InventoryShowArchivedCheckBox") is CheckBox archived) archived.IsChecked = false;
        RefreshInventorySpoolViewSafely();
        _inventorySummaryView?.Refresh();
        UpdateInventoryVisibleCount();
    }

    private void RefreshInventorySpoolViewSafely()
    {
        if (_inventorySpoolView is null) return;

        // WPF does not permit Refresh/Sort/Filter while a DataGrid collection view
        // is still inside AddNew/EditItem. Defer until the binding transaction is closed.
        if (_inventorySpoolView is IEditableCollectionView editableView &&
            (editableView.IsAddingNew || editableView.IsEditingItem))
        {
            Dispatcher.BeginInvoke(new Action(RefreshInventorySpoolViewSafely), DispatcherPriority.ContextIdle);
            return;
        }

        _inventorySpoolView.Refresh();
    }

    private void UpdateInventoryVisibleCount()
    {
        if (FindName("InventoryVisibleRowsText") is TextBlock text)
            text.Text = $"Visible: {_inventorySpoolView?.OfType<InventorySpoolRecord>().Count() ?? _inventorySpoolRows.Count} / {_inventorySpoolRows.Count} spool rows";
    }

    private void SelectInventoryRowForEditing(InventorySpoolRecord row, string preferredColumnHeader)
    {
        RefreshInventorySpoolViewSafely();
        if (FindName("InventorySpoolGrid") is not DataGrid grid) return;
        grid.SelectedItem = row;
        grid.ScrollIntoView(row);
        var column = grid.Columns.FirstOrDefault(c => Equals(c.Header, preferredColumnHeader)) ?? grid.Columns.FirstOrDefault(c => !c.IsReadOnly) ?? grid.Columns[0];
        grid.CurrentCell = new DataGridCellInfo(row, column);
        Dispatcher.BeginInvoke(new Action(() =>
        {
            grid.Focus();
            grid.BeginEdit();
        }), DispatcherPriority.Background);
    }

    private void RefreshInventorySummary_Click(object sender, RoutedEventArgs e)
    {
        // Run after the DataGrid binding transaction has fully completed. This
        // prevents the manual refresh action from reading the previous status or
        // remaining-weight value from a just-committed ComboBox/TextBox edit.
        Dispatcher.BeginInvoke(new Action(() =>
        {
            ApplyNativeMaterialComputedFieldsToAllRows();
            RefreshInventorySummary();
            SaveNativeMaterialsSilent();
            UpdateNativeWorkflowStatus("Inventory summary recalculated", saved: !_nativeMaterialDirty);
        }), System.Windows.Threading.DispatcherPriority.ContextIdle);
    }

    private string BuildInventoryVerificationReport()
    {
        var summary = BuildInventorySummary();
        var sb = new StringBuilder();
        sb.AppendLine("Inventory Engine Verification");
        sb.AppendLine("-----------------------------");
        sb.AppendLine("Inventory engine owner: InventoryEngineService");
        sb.AppendLine("Active inventory material rows: " + summary.MaterialRows);
        sb.AppendLine("Total spools: " + summary.TotalSpools);
        sb.AppendLine("Unopened / Opened / Empty: " + summary.UnopenedSpools + " / " + summary.OpenedSpools + " / " + summary.EmptySpools);
        sb.AppendLine("Total remaining weight: " + summary.TotalRemainingWeightG.ToString("N0", CultureInfo.InvariantCulture) + " g");
        sb.AppendLine("Complete inventory rows: " + summary.CompleteRows + " / " + summary.MaterialRows);
        sb.AppendLine("Validation issues: " + summary.IssueCount);
        sb.AppendLine("Estimated value currencies: " + (summary.EstimatedValueByCurrency.Count == 0 ? "none" : string.Join(", ", summary.EstimatedValueByCurrency.Keys.OrderBy(x => x))));
        sb.AppendLine("Status: " + (summary.IssueCount == 0 ? "MATCH" : "REVIEW REQUIRED"));
        sb.AppendLine();
        sb.AppendLine("Purchase Order Foundation Verification");
        sb.AppendLine("--------------------------------------");
        sb.AppendLine("Purchase orders: " + _purchaseOrders.Count);
        sb.AppendLine("Purchase order lines: " + _purchaseOrderLines.Count);
        sb.AppendLine("Filament lines: " + _purchaseOrderLines.Count(x => string.Equals(x.InventoryCategory, "Filament", StringComparison.OrdinalIgnoreCase)));
        sb.AppendLine("Non-filament lines: " + _purchaseOrderLines.Count(x => !string.Equals(x.InventoryCategory, "Filament", StringComparison.OrdinalIgnoreCase)));
        sb.AppendLine("Supported categories: Filament / Printer / Equipment / Spare Parts / Consumables / Other");
        sb.AppendLine("Inventory spools linked to purchase lines: " + _inventorySpoolRows.Count(x => !string.IsNullOrWhiteSpace(x.PurchaseOrderLineId)));
        sb.AppendLine("Tax treatments: VAT included / import VAT separately / tax exempt");
        sb.AppendLine("Landed cost allocation: Deferred to Cost Intelligence milestone");
        return sb.ToString();
    }

    private void RefreshNativeMaterialSummary()
    {
        if (FindName("NativeMaterialSummaryText") is TextBlock textBlock)
        {
            var total = _nativeMaterialRows.Count;
            var archived = _nativeMaterialRows.Count(row => row.IsArchived);
            var active = total - archived;
            var invalid = _nativeMaterialRows.Count(row => !row.IsRowValid);
            var publicReports = _nativeMaterialRows.Count(row => !row.IsArchived && row.PublishPublicReports);
            var dirtyText = _nativeMaterialDirty ? " | Unsaved changes" : " | Saved";
            textBlock.Text = $"Native materials: {total} total, {active} active/export-eligible, {publicReports} selected for public reports, {archived} archived/excluded, {invalid} invalid{dirtyText} | Publication selection: SQLite.";
        }

        RefreshApplicationStatistics();
    }

    private List<NativeMaterialRow> GetNativeWebsiteExportCandidateRows()
    {
        return _nativeMaterialRows
            .Where(row => !row.IsArchived)
            .Where(row => !string.IsNullOrWhiteSpace(row.MaterialID))
            .ToList();
    }

    private bool NativeMaterialHasBlockingValidationIssues()
    {
        var hasInvalidRows = _nativeMaterialRows.Any(row => !row.IsRowValid);
        var hasDuplicateIds = _nativeMaterialRows
            .Where(row => !string.IsNullOrWhiteSpace(row.MaterialID))
            .GroupBy(row => row.MaterialID.Trim(), StringComparer.OrdinalIgnoreCase)
            .Any(group => group.Count() > 1);
        var hasDuplicateDisplayNames = _nativeMaterialRows
            .Where(row => !string.IsNullOrWhiteSpace(row.WebsiteDisplayName))
            .GroupBy(row => row.WebsiteDisplayName.Trim(), StringComparer.OrdinalIgnoreCase)
            .Any(group => group.Count() > 1);

        return hasInvalidRows || hasDuplicateIds || hasDuplicateDisplayNames;
    }

    private bool NativeMaterialIdsAreSqliteSafe()
    {
        var hasMissingIds = _nativeMaterialRows.Any(row => string.IsNullOrWhiteSpace(row.MaterialID));
        var hasDuplicateIds = _nativeMaterialRows
            .Where(row => !string.IsNullOrWhiteSpace(row.MaterialID))
            .GroupBy(row => row.MaterialID.Trim(), StringComparer.OrdinalIgnoreCase)
            .Any(group => group.Count() > 1);

        return !hasMissingIds && !hasDuplicateIds;
    }


    private void CreateDatabaseBackupBeforeMajorMaterialChange(string actionName)
    {
        try
        {
            _database.CreateAutomaticBackupBeforeMajorChange();
            UpdateNativeWorkflowStatus($"Backup created before {actionName}");
        }
        catch
        {
            // Backup is best effort; the database layer also protects normal write flow.
        }
    }

    private void SaveNativeMaterials_Click(object sender, RoutedEventArgs e)
    {
        ApplyNativeMaterialComputedFieldsToAllRows();
        RefreshNativeMaterialGridValidation();

        if (!NativeMaterialIdsAreSqliteSafe())
        {
            MessageBox.Show("Save blocked: canonical SQLite storage requires every row to have a unique Material ID. Fix missing or duplicate Material IDs before saving.", "Material Manager Validation", MessageBoxButton.OK, MessageBoxImage.Warning);
            return;
        }

        if (NativeMaterialHasBlockingValidationIssues())
        {
            var result = MessageBox.Show("Material Manager validation found missing required fields, duplicate Material IDs, or duplicate display names. Save anyway?", "Material Manager Validation", MessageBoxButton.YesNo, MessageBoxImage.Warning);
            if (result != MessageBoxResult.Yes)
            {
                return;
            }
        }

        CreateDatabaseBackupBeforeMajorMaterialChange("manual Material Manager backup");
        _database.ReplaceNativeMaterialManagerRows(_nativeMaterialRows.Select(NativeMaterialRecordFromRow));
        SyncNativeTensileRowsWithMaterialManager(markDirty: true);
        SetNativeMaterialsDirty(false);
        RefreshNativeMaterialGridValidation();
        RefreshInventorySummary();
        UpdateNativeWorkflowStatus("Manual backup complete ✓", saved: true);
        ShowTransientStatus("Materials saved successfully.");
    }

    private bool SaveNativeMaterialsSilent()
    {
        try
        {
            ShowNativeSavingStatus("Materials");
            var sqliteUpdated = false;
            var sqliteBlockedReason = string.Empty;
            if (NativeMaterialIdsAreSqliteSafe() && !NativeMaterialHasBlockingValidationIssues())
            {
                _database.ReplaceNativeMaterialManagerRows(_nativeMaterialRows.Select(NativeMaterialRecordFromRow));
                sqliteUpdated = true;
            }
            else
            {
                sqliteBlockedReason = !NativeMaterialIdsAreSqliteSafe()
                    ? "SQLite save blocked: missing or duplicate Material IDs"
                    : "SQLite save blocked: validation issues";
            }

            if (sqliteUpdated)
            {
                SetNativeMaterialsDirty(false);
                ShowNativeSavedStatus("Materials");
            }
            else
            {
                ShowNativeSaveBlockedStatus("Materials", sqliteBlockedReason);
            }
            return sqliteUpdated;
        }
        catch (Exception ex)
        {
            ShowNativeSaveBlockedStatus("Materials", ex.Message);
            return false;
        }
    }

