    private void AddNativeMaterial_Click(object sender, RoutedEventArgs e)
    {
        CreateDatabaseBackupBeforeMajorMaterialChange("adding material");

        var materialId = GenerateNextNativeMaterialId();
        var defaultManufacturer = _database.LoadManufacturers()
            .Where(item => item.IsActive && !string.IsNullOrWhiteSpace(item.Name))
            .OrderBy(item => item.SortOrder)
            .ThenBy(item => item.Name)
            .FirstOrDefault();
        var defaultBaseMaterial = _nativeBaseMaterialRows.FirstOrDefault(item =>
                                      string.Equals(
                                          item.BaseMaterial?.Trim(),
                                          "PLA",
                                          StringComparison.OrdinalIgnoreCase))
                                  ?? _nativeBaseMaterialRows
                                      .OrderBy(item => item.SortOrder, StringComparer.OrdinalIgnoreCase)
                                      .ThenBy(item => item.BaseMaterial)
                                      .FirstOrDefault();
        var row = new NativeMaterialRow
        {
            MaterialID = materialId,
            ManufacturerId = defaultManufacturer?.ManufacturerId,
            Manufacturer = defaultManufacturer?.Name ?? "New manufacturer",
            ProductLine = $"New product line {materialId}",
            BaseMaterialId = defaultBaseMaterial?.BaseMaterialId,
            BaseMaterial = defaultBaseMaterial?.BaseMaterial ?? "PLA",
            MaterialCategory = defaultBaseMaterial?.Category ?? "Standard",
            DiameterMm = "1.75",
            SpoolWeightG = "1000",
            MsrpCurrency = "ISK",
            LandedCostCurrency = "ISK",
            Video = "No",
            TestedStatus = "Not tested",
            InTensile = "No",
            InImpact = "No",
            InStiffness = "No",
            SortOrder = "",
            SourcePriority = "Materials master",
            IsArchived = false
        };

        ApplyNativeMaterialComputedFields(row, _nativeMaterialRows.Count);
        _nativeMaterialRows.Add(row);
        RefreshFastManufacturerChoices();
        MarkNativeMaterialsDirty();
        RefreshNativeMaterialGridValidation();
        FocusNewNativeMaterial(row);
        QueueNativeMaterialEditRefresh();
    }

