    private void DeleteNativeMaterial_Click(object sender, RoutedEventArgs e)
    {
        if (IsAutomationActionBlocked("Material deletion")) return;
        if (GetSelectedNativeMaterial() is not NativeMaterialRow selected)
        {
            MessageBox.Show("Select a material to delete.", "Material Manager", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }

        var prompt = BuildMaterialDeletePrompt(selected.MaterialID, selected.WebsiteDisplayName);
        if (!ShowSafeDeleteConfirmation(prompt.Caption, prompt.Message))
            return;

        CreateDatabaseBackupBeforeMajorMaterialChange("deleting material");

        _nativeMaterialRows.Remove(selected);
        RefreshFastManufacturerChoices();
        if (ReferenceEquals(_lastSelectedNativeMaterial, selected)) _lastSelectedNativeMaterial = null;
        SyncNativeTensileRowsWithMaterialManager(markDirty: true);
        MarkNativeMaterialsDirty();
        RefreshNativeMaterialGridValidation();
        _embeddedMaterialsPrototypeView?.SynchronizeFromCanonical(
            "the deleted canonical MaterialID");
        try
        {
            SaveNativeMeasurementsToSqlite();
            SetNativeTensileDirty(false);
            SetNativeImpactDirty(false);
            SetNativeStiffnessDirty(false);
            if (!SaveNativeMaterialsSilent())
            {
                ShowNativeSaveBlockedStatus(
                    "Materials",
                    "Deleted measurement references were saved, but the MaterialID removal remains unsaved");
            }
            else
            {
                ReloadInventorySpoolsFromCanonicalDatabase();
            }
        }
        catch (Exception ex)
        {
            ShowNativeSaveBlockedStatus("Materials", ex.Message);
        }
    }

