        public DateTime? MeasuredDate { get => _measuredDate; set { var date = value?.Date; if (_measuredDate == date && _measuredDateText == FormatDisplayedMeasuredDate(date)) return; _measuredDate = date; _measuredDateText = FormatDisplayedMeasuredDate(date); OnPropertyChanged(nameof(MeasuredDate)); OnPropertyChanged(nameof(MeasuredDateText)); } }
        [JsonIgnore]
        public string MeasuredDateText
        {
            get => _measuredDateText;
            set
            {
                var candidate = value ?? "";
                if (_measuredDateText == candidate) return;
                _measuredDateText = candidate;
                if (string.IsNullOrWhiteSpace(candidate)) { _measuredDate = null; OnPropertyChanged(nameof(MeasuredDate)); }
                else if (TryParseDisplayedMeasuredDate(candidate, out var parsed)) { _measuredDate = parsed.Date; _measuredDateText = FormatDisplayedMeasuredDate(_measuredDate); OnPropertyChanged(nameof(MeasuredDate)); }
                OnPropertyChanged(nameof(MeasuredDateText));
            }
        }

        [JsonIgnore]
        public string ValidationSummary
        {
            get
            {
                if (string.IsNullOrWhiteSpace(MaterialID)) return "Missing Material ID";
                if (SampleValues(true).Concat(SampleValues(false)).Any(v => !string.IsNullOrWhiteSpace(v) && !MainWindow.TryParseMeasurement(v, out _))) return "Invalid sample value";
                return "OK";
            }
        }

        public IEnumerable<string> SampleValues(bool upright)
        {
            return upright
                ? new[] { Upright1, Upright2, Upright3, Upright4, Upright5, Upright6, Upright7, Upright8, Upright9, Upright10 }
                : new[] { Flat1, Flat2, Flat3, Flat4, Flat5, Flat6, Flat7, Flat8, Flat9, Flat10 };
        }

        public void SetSample(bool upright, int sampleNumber, string value)
        {
            if (upright)
            {
                if (sampleNumber == 1) _upright1 = value; else if (sampleNumber == 2) _upright2 = value; else if (sampleNumber == 3) _upright3 = value; else if (sampleNumber == 4) _upright4 = value; else if (sampleNumber == 5) _upright5 = value; else if (sampleNumber == 6) _upright6 = value; else if (sampleNumber == 7) _upright7 = value; else if (sampleNumber == 8) _upright8 = value; else if (sampleNumber == 9) _upright9 = value; else if (sampleNumber == 10) _upright10 = value;
            }
            else
            {
                if (sampleNumber == 1) _flat1 = value; else if (sampleNumber == 2) _flat2 = value; else if (sampleNumber == 3) _flat3 = value; else if (sampleNumber == 4) _flat4 = value; else if (sampleNumber == 5) _flat5 = value; else if (sampleNumber == 6) _flat6 = value; else if (sampleNumber == 7) _flat7 = value; else if (sampleNumber == 8) _flat8 = value; else if (sampleNumber == 9) _flat9 = value; else if (sampleNumber == 10) _flat10 = value;
            }
        }
    }

    private sealed class NativeTensileMeasurementsState
    {
        public string SavedAtUtc { get; set; } = "";
        public string StorageMode { get; set; } = CanonicalStorageStatusText;
        public List<NativeTensileMeasurementRow> Rows { get; set; } = new();
    }

    private readonly ObservableCollection<NativeTensileMeasurementRow> _nativeTensileRows = new();
    private bool _nativeTensileDirty;
    private bool _suppressNativeTensileDirty;
    private bool _nativeMeasurementMigrationChecked;

    private void EnsureNativeMeasurementsMigratedToSqlite()
    {
        if (_nativeMeasurementMigrationChecked) return;
        _nativeMeasurementMigrationChecked = true;
        if (_database.NativeMeasurementsAreCanonical()) return;
        var tensile = LoadNativeTensileRowsForCanonicalMigration();
        var impact = LoadNativeImpactRowsForCanonicalMigration();
        var stiffness = LoadNativeStiffnessRowsForCanonicalMigration();
        ApplyNativeTensileComputedFields(tensile);
        ApplyNativeImpactComputedFields(impact);
        ApplyNativeStiffnessComputedFields(stiffness);
        _database.MigrateNativeMeasurementsToSqlite(
            tensile.Select(ToTensilePersistence).ToList(),
            impact.Select(ToImpactPersistence).ToList(),
            stiffness.Select(ToStiffnessPersistence).ToList());
    }

    private static NativeTensilePersistenceRecord ToTensilePersistence(NativeTensileMeasurementRow row) => new()
    {
        MaterialId = row.MaterialID, UprightSamples = row.SampleValues(true).ToList(), FlatSamples = row.SampleValues(false).ToList(),
        UprightMpa = row.MpaUpright, FlatMpa = row.MpaFlat, StdDevUpright = row.StdDevUpright, StdDevFlat = row.StdDevFlat,
        CvUpright = row.CvUpright, CvFlat = row.CvFlat, SamplesUpright = row.SamplesUpright, SamplesFlat = row.SamplesFlat,
        ConfidenceUpright = row.ConfidenceUpright, ConfidenceFlat = row.ConfidenceFlat, TestNotes = row.TestNotes,
        MeasuredDate = ToIsoMeasuredDate(row.MeasuredDate)
    };
    private static NativeImpactPersistenceRecord ToImpactPersistence(NativeImpactMeasurementRow row) => new()
    { MaterialId = row.MaterialID, UprightSamples = row.SampleValues(true).ToList(), FlatSamples = row.SampleValues(false).ToList(), TestNotes = row.TestNotes, MeasuredDate = ToIsoMeasuredDate(row.MeasuredDate) };
    private static NativeStiffnessPersistenceRecord ToStiffnessPersistence(NativeStiffnessMeasurementRow row) => new()
    { MaterialId = row.MaterialID, Revolutions = row.Revolutions, Degrees = row.Degrees, TestNotes = row.TestNotes, MeasuredDate = ToIsoMeasuredDate(row.MeasuredDate) };

    private static string ToIsoMeasuredDate(DateTime? value) =>
        value?.Date.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture) ?? "";

    private static DateTime? ParseIsoMeasuredDate(string value) =>
        DateTime.TryParseExact(value, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var parsed)
            ? parsed.Date
            : null;

    private static string FormatDisplayedMeasuredDate(DateTime? value) =>
        value?.Date.ToString("dd.MM.yyyy", CultureInfo.InvariantCulture) ?? "";

    private static bool TryParseDisplayedMeasuredDate(string value, out DateTime date) =>
        DateTime.TryParseExact(value.Trim(), new[] { "d.M.yyyy", "dd.MM.yyyy" }, CultureInfo.InvariantCulture, DateTimeStyles.None, out date);

    private static bool ShouldAssignMeasuredDate(DateTime? currentDate, IEnumerable<string> inputs) =>
        currentDate is null && inputs.Any(value => !string.IsNullOrWhiteSpace(value));

    private void SaveNativeMeasurementsToSqlite() => _database.MigrateNativeMeasurementsToSqlite(
        _nativeTensileRows.Select(ToTensilePersistence).ToList(),
        _nativeImpactRows.Select(ToImpactPersistence).ToList(),
        _nativeStiffnessRows.Select(ToStiffnessPersistence).ToList(), replaceCanonical: true);

    private void InitializeNativeTensileMeasurements()
    {
        EnsureNativeMeasurementsMigratedToSqlite();
        _nativeTensileRows.CollectionChanged += (_, _) => { if (!_suppressNativeTensileDirty) MarkNativeTensileDirty(); };
        _suppressNativeTensileDirty = true;
        ReplaceNativeTensileRows(BuildNativeTensileRowsFromCanonicalStorage());
        _suppressNativeTensileDirty = false;
        ApplyNativeMeasurementFilters();
        SetNativeTensileDirty(false);
        RefreshNativeTensileSummary();
    }

    private string NativeTensileFilePath() => StorageWorkingFilePath("native-tensile-measurements.json");

    private List<NativeTensileMeasurementRow> LoadNativeTensileRowsForCanonicalMigration()
    {
        var path = NativeTensileFilePath();
        if (System.IO.File.Exists(path))
        {
            try
            {
                var state = JsonSerializer.Deserialize<NativeTensileMeasurementsState>(System.IO.File.ReadAllText(path));
                if (state?.Rows?.Count > 0) return state.Rows;
            }
            catch { }
        }
        return BuildNativeTensileRowsFromCanonicalStorage();
    }

    private static NativeTensileMeasurementRow NativeTensileRowFromMaterial(NativeMaterialRow material)
    {
        return new NativeTensileMeasurementRow
        {
            MaterialID = material.MaterialID,
            Manufacturer = material.Manufacturer,
            ProductLine = material.ProductLine,
            MarketingName = material.MarketingName,
            BaseMaterial = material.BaseMaterial,
            MaterialCategory = material.MaterialCategory,
            VariantFinish = material.VariantFinish,
            Reinforcement = material.Reinforcement,
            Color = material.Color
        };
    }

    private static void CopyNativeMaterialIdentityToTensileRow(NativeMaterialRow material, NativeTensileMeasurementRow tensileRow)
    {
        tensileRow.MaterialID = material.MaterialID;
        tensileRow.Manufacturer = material.Manufacturer;
        tensileRow.ProductLine = material.ProductLine;
        tensileRow.MarketingName = material.MarketingName;
        tensileRow.BaseMaterial = material.BaseMaterial;
        tensileRow.MaterialCategory = material.MaterialCategory;
        tensileRow.VariantFinish = material.VariantFinish;
        tensileRow.Reinforcement = material.Reinforcement;
        tensileRow.Color = material.Color;
    }

    private void SyncNativeTensileRowsWithMaterialManager(bool markDirty)
    {
        if (_nativeMaterialRows.Count == 0) return;

        ApplyNativeMaterialComputedFieldsToAllRows();

        var materialRows = _nativeMaterialRows
            .Where(m => !string.IsNullOrWhiteSpace(m.MaterialID))
            .GroupBy(m => m.MaterialID.Trim(), StringComparer.OrdinalIgnoreCase)
            .Select(g => g.First())
            .ToList();

        var validMaterialIds = materialRows
            .Select(m => m.MaterialID.Trim())
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

        var changed = false;
        for (var i = _nativeTensileRows.Count - 1; i >= 0; i--)
        {
            if (string.IsNullOrWhiteSpace(_nativeTensileRows[i].MaterialID) || !validMaterialIds.Contains(_nativeTensileRows[i].MaterialID.Trim()))
            {
                _nativeTensileRows.RemoveAt(i);
                changed = true;
            }
        }

        var tensileById = _nativeTensileRows
            .Where(r => !string.IsNullOrWhiteSpace(r.MaterialID))
            .GroupBy(r => r.MaterialID.Trim(), StringComparer.OrdinalIgnoreCase)
            .ToDictionary(g => g.Key, g => g.First(), StringComparer.OrdinalIgnoreCase);

        foreach (var material in materialRows)
        {
            var key = material.MaterialID.Trim();
            if (tensileById.TryGetValue(key, out var existing))
            {
                var before = string.Join("|", existing.Manufacturer, existing.ProductLine, existing.MarketingName, existing.BaseMaterial, existing.MaterialCategory, existing.VariantFinish, existing.Reinforcement, existing.Color);
                CopyNativeMaterialIdentityToTensileRow(material, existing);
                var after = string.Join("|", existing.Manufacturer, existing.ProductLine, existing.MarketingName, existing.BaseMaterial, existing.MaterialCategory, existing.VariantFinish, existing.Reinforcement, existing.Color);
                if (!string.Equals(before, after, StringComparison.Ordinal)) changed = true;
            }
            else
            {
                _nativeTensileRows.Add(NativeTensileRowFromMaterial(material));
                changed = true;
            }
        }

        if (!changed) return;

        ApplyNativeTensileComputedFields(_nativeTensileRows);
        RefreshNativeTensileSummary();
        ApplyNativeMeasurementFilters();
        if (markDirty) MarkNativeTensileDirty();
        SyncNativeImpactRowsWithMaterialManager(markDirty);
    }

    private List<NativeTensileMeasurementRow> BuildNativeTensileRowsFromCanonicalStorage()
    {
        var materials = _nativeMaterialRows.ToList();
        var rows = materials
            .Where(m => !string.IsNullOrWhiteSpace(m.MaterialID))
            .Select(NativeTensileRowFromMaterial)
            .ToList();

        var rowById = rows.ToDictionary(r => r.MaterialID, StringComparer.OrdinalIgnoreCase);
        foreach (var sample in _database.GetTensileSamples())
        {
            if (!rowById.TryGetValue(sample.MaterialId, out var row)) continue;
            row.SetSample(string.Equals(sample.Orientation, "Upright", StringComparison.OrdinalIgnoreCase), sample.SampleNumber, sample.RawValue);
        }

        foreach (var row in rows)
        {
            var imported = _database.GetTensileTestResult(row.MaterialID);
            if (imported is not null)
            {
                row.TestNotes = imported.TestNotes ?? "";
            }
            row.MeasuredDate = ParseIsoMeasuredDate(_database.GetNativeMeasurementDate(row.MaterialID, "Tensile"));
        }

        ApplyNativeTensileComputedFields(rows);
        return rows;
    }

    private void ReplaceNativeTensileRows(IEnumerable<NativeTensileMeasurementRow> rows)
    {
        _nativeTensileRows.Clear();
        foreach (var row in rows) _nativeTensileRows.Add(row);
        ApplyNativeTensileComputedFields(_nativeTensileRows);
    }

    private void SaveNativeTensileSilent()
    {
        try
        {
            ShowNativeSavingStatus("Tensile");
            SaveNativeMeasurementsToSqlite();
            SetNativeTensileDirty(false);
            ShowNativeSavedStatus("Tensile");
        }
        catch (Exception ex)
        {
            ShowNativeSaveBlockedStatus("Tensile", ex.Message);
        }
    }

    private void MarkNativeTensileDirty() => SetNativeTensileDirty(true);

    private void SetNativeTensileDirty(bool dirty)
    {
        _nativeTensileDirty = dirty;
        if (FindName("SaveNativeTensileButton") is Button saveButton) saveButton.IsEnabled = dirty;
        RefreshNativeTensileSummary();
    }

    private void RefreshNativeTensileSummary()
    {
        if (FindName("NativeTensileSummaryText") is not TextBlock text) return;
        var tested = _nativeTensileRows.Count(r => ToNumbers(r.SampleValues(true)).Any() || ToNumbers(r.SampleValues(false)).Any());
        var invalid = _nativeTensileRows.Count(r => r.ValidationSummary != "OK");
        text.Text = $"Rows: {_nativeTensileRows.Count} | With samples: {tested} | Invalid: {invalid} | Storage: {CanonicalStorageStatusText} | {(_nativeTensileDirty ? "Unsaved changes" : "Saved")}";
    }

    private void ApplyNativeTensileComputedFields(IEnumerable<NativeTensileMeasurementRow> rows)
    {
        var area = GetNativeTensileCrossSectionArea();
        foreach (var row in rows)
        {
            ApplyNativeTensileComputedFields(row, area);
        }
    }

    private void ApplyNativeTensileComputedFields(NativeTensileMeasurementRow row, double crossSectionArea)
    {
        var results = _resultsService.CalculateTensile(row.SampleValues(true), row.SampleValues(false), crossSectionArea);
        ApplyMeasurementSetToTextFields(
            results.Upright,
            value => row.MpaUpright = value,
            value => row.StdDevUpright = value,
            value => row.CvUpright = value,
            value => row.SamplesUpright = value,
            value => row.ConfidenceUpright = value);
        ApplyMeasurementSetToTextFields(
            results.Flat,
            value => row.MpaFlat = value,
            value => row.StdDevFlat = value,
            value => row.CvFlat = value,
            value => row.SamplesFlat = value,
            value => row.ConfidenceFlat = value);
        row.NotifyComputedFieldsChanged();
    }


    private static void ApplyMeasurementSetToTextFields(
        MeasurementSetResult result,
        Action<string> setAverage,
        Action<string> setStandardDeviation,
        Action<string> setCoefficientOfVariation,
        Action<string> setSampleCount,
        Action<string> setConfidence)
    {
        setAverage(FormatNativeResult(result.Average));
        setStandardDeviation(FormatNativeResult(result.StandardDeviation));
        setCoefficientOfVariation(FormatNativeResult(result.CoefficientOfVariation));
        setSampleCount(result.SampleCount == 0 ? "" : result.SampleCount.ToString(CultureInfo.CurrentCulture));
        setConfidence(result.Confidence.HasValue ? result.Confidence.Value.ToString(CultureInfo.CurrentCulture) : "");
    }

    private static string FormatNativeResult(double? value) => value.HasValue ? value.Value.ToString("0.###", CultureInfo.CurrentCulture) : "";

    private double GetNativeTensileCrossSectionArea()
    {
        var settings = _nativeSettingsRows.FirstOrDefault(r => string.Equals(r.Section, "Tensile", StringComparison.OrdinalIgnoreCase) && r.Parameter.Contains("cross", StringComparison.OrdinalIgnoreCase));
        if (settings is not null && TryParseMeasurement(settings.Value, out var value) && value > 0) return value;
        return 6.5016; // Excel 04 Settings C31 fallback from the audited workbook.
    }

    private static IEnumerable<double> ToNumbers(IEnumerable<string> values)
    {
        foreach (var value in values)
        {
            if (TryParseMeasurement(value, out var number)) yield return number;
        }
    }

    private static double? Average(IReadOnlyList<double> values) => values.Count == 0 ? null : values.Average();

    private static double? StandardDeviation(IReadOnlyList<double> values)
    {
        if (values.Count < 2) return null;
        var avg = values.Average();
        var sum = values.Sum(v => Math.Pow(v - avg, 2));
        return Math.Sqrt(sum / (values.Count - 1));
    }

