        [JsonIgnore]
        public string ValidationSummary
        {
            get
            {
                if (string.IsNullOrWhiteSpace(MaterialID)) return "Missing Material ID";
                if (SampleValues(true).Concat(SampleValues(false)).Any(v => !string.IsNullOrWhiteSpace(v) && !MainWindow.TryParseMeasurement(v, out _))) return "Invalid needle %";
                if (ToNumbers(SampleValues(true).Concat(SampleValues(false))).Any(v => v < 0 || v > 100)) return "Needle % outside 0-100";
                return "OK";
            }
        }

        public IEnumerable<string> SampleValues(bool upright) => upright
            ? new[] { Upright1, Upright2, Upright3, Upright4, Upright5, Upright6, Upright7, Upright8, Upright9, Upright10 }
            : new[] { Flat1, Flat2, Flat3, Flat4, Flat5, Flat6, Flat7, Flat8, Flat9, Flat10 };

        public void SetSample(bool upright, int sampleNumber, string value)
        {
            if (upright)
            {
                if (sampleNumber == 1) _upright1 = value; else if (sampleNumber == 2) _upright2 = value; else if (sampleNumber == 3) _upright3 = value; else if (sampleNumber == 4) _upright4 = value; else if (sampleNumber == 5) _upright5 = value; else if (sampleNumber == 6) _upright6 = value; else if (sampleNumber == 7) _upright7 = value; else if (sampleNumber == 8) _upright8 = value; else if (sampleNumber == 9) _upright9 = value; else if (sampleNumber == 10) _upright10 = value;
            }
            else
            {
                if (sampleNumber == 1) _flat1 = value; else if (sampleNumber == 2) _flat2 = value; else if (sampleNumber == 3) _flat3 = value; else if (sampleNumber == 4) _flat4 = value; else if (sampleNumber == 5) _flat5 = value; else if (sampleNumber == 6) _flat6 = value; else if (sampleNumber == 7) _flat7 = value; else if (sampleNumber == 8) _flat8 = value; else if (sampleNumber == 9) _flat9 = value; else if (sampleNumber == 10) _flat10 = value;
            }
        }
    }

    private sealed class NativeImpactMeasurementsState
    {
        public string SavedAtUtc { get; set; } = "";
        public string StorageMode { get; set; } = CanonicalStorageStatusText;
        public List<NativeImpactMeasurementRow> Rows { get; set; } = new();
    }

    private readonly ObservableCollection<NativeImpactMeasurementRow> _nativeImpactRows = new();
    private bool _nativeImpactDirty;
    private bool _suppressNativeImpactDirty;

    private void InitializeNativeImpactMeasurements()
    {
        _nativeImpactRows.CollectionChanged += (_, _) => { if (!_suppressNativeImpactDirty) MarkNativeImpactDirty(); };
        _suppressNativeImpactDirty = true;
        ReplaceNativeImpactRows(BuildNativeImpactRowsFromCanonicalStorage());
        _suppressNativeImpactDirty = false;
        ApplyNativeMeasurementFilters();
        SetNativeImpactDirty(false);
        RefreshNativeImpactSummary();
    }

    private string NativeImpactFilePath() => StorageWorkingFilePath("native-impact-measurements.json");

    private List<NativeImpactMeasurementRow> LoadNativeImpactRowsForCanonicalMigration()
    {
        var path = NativeImpactFilePath();
        if (System.IO.File.Exists(path))
        {
            try
            {
                var state = JsonSerializer.Deserialize<NativeImpactMeasurementsState>(System.IO.File.ReadAllText(path));
                if (state?.Rows?.Count > 0) return state.Rows;
            }
            catch { }
        }
        return BuildNativeImpactRowsFromCanonicalStorage();
    }

    private List<NativeImpactMeasurementRow> BuildNativeImpactRowsFromCanonicalStorage()
    {
        var materials = _nativeMaterialRows.ToList();

        var rows = materials
            .Where(m => !string.IsNullOrWhiteSpace(m.MaterialID))
            .Select(NativeImpactRowFromMaterial)
            .ToList();

        var rowById = rows
            .Where(r => !string.IsNullOrWhiteSpace(r.MaterialID))
            .GroupBy(r => r.MaterialID.Trim(), StringComparer.OrdinalIgnoreCase)
            .ToDictionary(g => g.Key, g => g.First(), StringComparer.OrdinalIgnoreCase);

        foreach (var sample in _database.GetImpactSamples())
        {
            if (!rowById.TryGetValue(sample.MaterialId.Trim(), out var row)) continue;
            row.SetSample(string.Equals(sample.Orientation, "Upright", StringComparison.OrdinalIgnoreCase), sample.SampleNumber, sample.RawValue);
        }

        foreach (var row in rows)
        {
            row.TestNotes = _database.GetNativeMeasurementNote(row.MaterialID, "Impact");
            row.MeasuredDate = ParseIsoMeasuredDate(_database.GetNativeMeasurementDate(row.MaterialID, "Impact"));
        }

        ApplyNativeImpactComputedFields(rows);
        return rows;
    }

    private static NativeImpactMeasurementRow NativeImpactRowFromMaterial(NativeMaterialRow material) => new()
    {
        MaterialID = material.MaterialID,
        Manufacturer = material.Manufacturer,
        ProductLine = material.ProductLine,
        MarketingName = material.MarketingName,
        BaseMaterial = material.BaseMaterial,
        MaterialCategory = material.MaterialCategory,
        VariantFinish = material.VariantFinish,
        Reinforcement = material.Reinforcement,
        Color = material.Color
    };

    private static void CopyNativeMaterialIdentityToImpactRow(NativeMaterialRow material, NativeImpactMeasurementRow impactRow)
    {
        impactRow.MaterialID = material.MaterialID;
        impactRow.Manufacturer = material.Manufacturer;
        impactRow.ProductLine = material.ProductLine;
        impactRow.MarketingName = material.MarketingName;
        impactRow.BaseMaterial = material.BaseMaterial;
        impactRow.MaterialCategory = material.MaterialCategory;
        impactRow.VariantFinish = material.VariantFinish;
        impactRow.Reinforcement = material.Reinforcement;
        impactRow.Color = material.Color;
    }

    private void SyncNativeImpactRowsWithMaterialManager(bool markDirty)
    {
        if (_nativeMaterialRows.Count == 0) return;

        var materialRows = _nativeMaterialRows
            .Where(m => !string.IsNullOrWhiteSpace(m.MaterialID))
            .GroupBy(m => m.MaterialID.Trim(), StringComparer.OrdinalIgnoreCase)
            .Select(g => g.First())
            .ToList();

        var validMaterialIds = materialRows.Select(m => m.MaterialID.Trim()).ToHashSet(StringComparer.OrdinalIgnoreCase);
        for (var i = _nativeImpactRows.Count - 1; i >= 0; i--)
        {
            if (string.IsNullOrWhiteSpace(_nativeImpactRows[i].MaterialID) || !validMaterialIds.Contains(_nativeImpactRows[i].MaterialID.Trim()))
            {
                _nativeImpactRows.RemoveAt(i);
            }
        }

        var impactById = _nativeImpactRows
            .Where(r => !string.IsNullOrWhiteSpace(r.MaterialID))
            .GroupBy(r => r.MaterialID.Trim(), StringComparer.OrdinalIgnoreCase)
            .ToDictionary(g => g.Key, g => g.First(), StringComparer.OrdinalIgnoreCase);

        foreach (var material in materialRows)
        {
            var key = material.MaterialID.Trim();
            if (impactById.TryGetValue(key, out var existing)) CopyNativeMaterialIdentityToImpactRow(material, existing);
            else _nativeImpactRows.Add(NativeImpactRowFromMaterial(material));
        }

        ApplyNativeImpactComputedFields(_nativeImpactRows);
        RefreshNativeImpactSummary();
        ApplyNativeMeasurementFilters();
        if (markDirty) MarkNativeImpactDirty();
    }

    private void ReplaceNativeImpactRows(IEnumerable<NativeImpactMeasurementRow> rows)
    {
        _nativeImpactRows.Clear();
        foreach (var row in rows) _nativeImpactRows.Add(row);
        ApplyNativeImpactComputedFields(_nativeImpactRows);
    }

    private void SaveNativeImpactSilent()
    {
        try
        {
            ShowNativeSavingStatus("Impact");
            SaveNativeMeasurementsToSqlite();
            SetNativeImpactDirty(false);
            ShowNativeSavedStatus("Impact");
        }
        catch (Exception ex)
        {
            ShowNativeSaveBlockedStatus("Impact", ex.Message);
        }
    }

    private void MarkNativeImpactDirty() => SetNativeImpactDirty(true);

    private void SetNativeImpactDirty(bool dirty)
    {
        _nativeImpactDirty = dirty;
        if (FindName("SaveNativeImpactButton") is Button saveButton) saveButton.IsEnabled = dirty;
        RefreshNativeImpactSummary();
    }

    private void RefreshNativeImpactSummary()
    {
        if (FindName("NativeImpactSummaryText") is not TextBlock text) return;
        var tested = _nativeImpactRows.Count(NativeImpactRowHasMeasurementData);
        var invalid = _nativeImpactRows.Count(r => r.ValidationSummary != "OK");
        text.Text = $"Rows: {_nativeImpactRows.Count} | With samples: {tested} | Invalid: {invalid} | Storage: {CanonicalStorageStatusText} | {(_nativeImpactDirty ? "Unsaved changes" : "Saved")}";
    }

    private static bool NativeImpactRowHasMeasurementData(NativeImpactMeasurementRow row)
    {
        return ToNumbers(row.SampleValues(true)).Any() || ToNumbers(row.SampleValues(false)).Any();
    }

    private void ApplyNativeImpactComputedFields(IEnumerable<NativeImpactMeasurementRow> rows)
    {
        var angle = GetNativeImpactNoSampleAngle();
        var area = GetNativeImpactCrossSectionAreaM2();
        var maxImpact = GetNativeImpactMaxPossibleImpact();
        foreach (var row in rows) ApplyNativeImpactComputedFields(row, angle, area, maxImpact);
    }

    private void ApplyNativeImpactComputedFields(NativeImpactMeasurementRow row, double angle, double area, double maxImpact)
    {
        var results = _resultsService.CalculateImpact(row.SampleValues(true), row.SampleValues(false), angle, area, maxImpact);
        ApplyMeasurementSetToTextFields(
            results.Upright,
            value => row.KjUpright = value,
            value => row.StdDevUpright = value,
            value => row.CvUpright = value,
            value => row.SamplesUpright = value,
            value => row.ConfidenceUpright = value);
        ApplyMeasurementSetToTextFields(
            results.Flat,
            value => row.KjFlat = value,
            value => row.StdDevFlat = value,
            value => row.CvFlat = value,
            value => row.SamplesFlat = value,
            value => row.ConfidenceFlat = value);
        row.NotifyComputedFieldsChanged();
    }



    private sealed class NativeStiffnessMeasurementRow : INotifyPropertyChanged
    {
        public string MaterialID { get; set; } = "";
        public string Manufacturer { get; set; } = "";
        public string ProductLine { get; set; } = "";
        public string MarketingName { get; set; } = "";
        public string BaseMaterial { get; set; } = "";
        public string MaterialCategory { get; set; } = "";
        public string VariantFinish { get; set; } = "";
        public string Reinforcement { get; set; } = "";
        public string Color { get; set; } = "";

        private string _revolutions = "";
        private string _degrees = "";
        private DateTime? _measuredDate;
        private string _measuredDateText = "";

        public string Revolutions { get => _revolutions; set => SetInput(ref _revolutions, value, nameof(Revolutions)); }
        public string Degrees { get => _degrees; set => SetInput(ref _degrees, value, nameof(Degrees)); }
        public string DeflectionMm { get; set; } = "";
        public string ModulusMpa { get; set; } = "";
        public string TestNotes { get; set; } = "";
        public DateTime? MeasuredDate { get => _measuredDate; set { var date = value?.Date; if (_measuredDate == date && _measuredDateText == FormatDisplayedMeasuredDate(date)) return; _measuredDate = date; _measuredDateText = FormatDisplayedMeasuredDate(date); OnPropertyChanged(nameof(MeasuredDate)); OnPropertyChanged(nameof(MeasuredDateText)); } }
        [JsonIgnore]
        public string MeasuredDateText
        {
            get => _measuredDateText;
            set
            {
                var candidate = value ?? "";
                if (_measuredDateText == candidate) return;
                _measuredDateText = candidate;
                if (string.IsNullOrWhiteSpace(candidate)) { _measuredDate = null; OnPropertyChanged(nameof(MeasuredDate)); }
                else if (TryParseDisplayedMeasuredDate(candidate, out var parsed)) { _measuredDate = parsed.Date; _measuredDateText = FormatDisplayedMeasuredDate(_measuredDate); OnPropertyChanged(nameof(MeasuredDate)); }
                OnPropertyChanged(nameof(MeasuredDateText));
            }
        }

        [JsonIgnore]
        public string ValidationSummary
        {
            get
            {
                if (string.IsNullOrWhiteSpace(MaterialID)) return "Missing Material ID";
                if (!string.IsNullOrWhiteSpace(Revolutions))
                {
                    if (!MainWindow.TryParseMeasurement(Revolutions, out var revolutions)) return "Invalid revolutions";
                    if (revolutions > 10) return "Revolutions over limit";
                }
                if (!string.IsNullOrWhiteSpace(Degrees))
                {
                    if (!MainWindow.TryParseMeasurement(Degrees, out var degrees)) return "Invalid degrees";
                    if (degrees > 359) return "Degrees over limit";
                }
                return "OK";
            }
        }

        private void SetInput(ref string field, string? value, string propertyName)
        {
            var candidate = value ?? "";
            if (MainWindow.TryParseMeasurement(candidate, out var number))
            {
                if (propertyName == nameof(Revolutions) && (number < 0 || number > 10))
                {
                    OnPropertyChanged(propertyName);
                    return;
                }
                if (propertyName == nameof(Degrees) && (number < 0 || number > 359))
                {
                    OnPropertyChanged(propertyName);
                    return;
                }
            }
            if (field == candidate) return;
            field = candidate;
            OnPropertyChanged(propertyName);
            OnPropertyChanged(nameof(ValidationSummary));
        }

        public bool HasMeasurementData()
        {
            return MainWindow.TryParseMeasurement(Revolutions, out _) || MainWindow.TryParseMeasurement(Degrees, out _);
        }

        public void NotifyComputedFieldsChanged()
        {
            OnPropertyChanged(nameof(ValidationSummary));
            OnPropertyChanged(nameof(DeflectionMm));
            OnPropertyChanged(nameof(ModulusMpa));
        }

        public event PropertyChangedEventHandler? PropertyChanged;
        private void OnPropertyChanged(string propertyName) => PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
    }

