    private void ApplyNativeStiffnessComputedFields(IEnumerable<NativeStiffnessMeasurementRow> rows)
    {
        var mmPerRevolution = GetNativeStiffnessMmPerRevolution();
        var spanLength = GetNativeStiffnessSpanLength();
        var load = GetNativeStiffnessLoad();
        var secondMoment = GetNativeStiffnessSecondMomentOfArea();
        foreach (var row in rows) ApplyNativeStiffnessComputedFields(row, mmPerRevolution, spanLength, load, secondMoment);
    }

    private void ApplyNativeStiffnessComputedFields(NativeStiffnessMeasurementRow row, double mmPerRevolution, double spanLength, double load, double secondMoment)
    {
        var results = _resultsService.CalculateStiffness(row.Revolutions, row.Degrees, mmPerRevolution, spanLength, load, secondMoment);
