    private double GetNativeStiffnessMmPerRevolution() => GetNativeStiffnessSetting("mm per revolution", 1.058774489370571);
    private double GetNativeStiffnessSpanLength() => GetNativeStiffnessSetting("Span length", 118.2);
    private double GetNativeStiffnessLoad() => GetNativeStiffnessSetting("Load", 5.47);
    private double GetNativeStiffnessSecondMomentOfArea() => GetNativeStiffnessSetting("Second moment of area", 34.67946666666668);

    private double GetNativeStiffnessSetting(string parameterText, double fallback)
    {
        var settings = _nativeSettingsRows.FirstOrDefault(r => string.Equals(r.Section, "Stiffness", StringComparison.OrdinalIgnoreCase) && r.Parameter.Contains(parameterText, StringComparison.OrdinalIgnoreCase));
        if (settings is not null && TryParseMeasurement(settings.Value, out var value) && value > 0) return value;
        return fallback;
    }

    private double GetNativeImpactNoSampleAngle()
    {
        var settings = _nativeSettingsRows.FirstOrDefault(r => string.Equals(r.Section, "Impact", StringComparison.OrdinalIgnoreCase) && r.Parameter.Contains("No-sample rebound angle", StringComparison.OrdinalIgnoreCase));
        if (settings is not null && TryParseMeasurement(settings.Value, out var value) && value > 0) return value;
        return 105.411;
    }

    private double GetNativeImpactCrossSectionAreaM2()
    {
        var settings = _nativeSettingsRows.FirstOrDefault(r => string.Equals(r.Section, "Impact", StringComparison.OrdinalIgnoreCase) && r.Parameter.Contains("Net cross-section area", StringComparison.OrdinalIgnoreCase) && TryParseMeasurement(r.Value, out var parsed) && parsed < 0.001);
        if (settings is not null && TryParseMeasurement(settings.Value, out var value) && value > 0) return value;
        return 4.81603E-05;
    }

    private double GetNativeImpactMaxPossibleImpact()
    {
        var settings = _nativeSettingsRows.FirstOrDefault(r => string.Equals(r.Section, "Impact", StringComparison.OrdinalIgnoreCase) && r.Parameter.Contains("Max possible impact", StringComparison.OrdinalIgnoreCase));
        if (settings is not null && TryParseMeasurement(settings.Value, out var value) && value > 0) return value;
        return 56.97350149396911;
    }

    private static double? ConvertImpactNeedlePercentToKjM2(double needlePercent, double noSampleAngle, double netCrossSectionAreaM2, double maxPossibleImpact)
    {
        if (needlePercent < 0 || needlePercent > 100 || noSampleAngle <= 0 || netCrossSectionAreaM2 <= 0 || maxPossibleImpact <= 0) return null;
        var fraction = 1 - ((1 - Math.Cos(DegreesToRadians(noSampleAngle * (1 - needlePercent / 100d)))) / (1 - Math.Cos(DegreesToRadians(noSampleAngle))));
        return maxPossibleImpact * fraction / netCrossSectionAreaM2 / 1000d;
    }

    private static double DegreesToRadians(double degrees) => Math.PI * degrees / 180d;

    private static bool TryParseMeasurement(string? text, out double value)
    {
        value = 0;
        if (string.IsNullOrWhiteSpace(text)) return false;
        var cleaned = text.Replace("MPa", "", StringComparison.OrdinalIgnoreCase).Replace("%", "", StringComparison.OrdinalIgnoreCase).Trim();
        var cultures = new[] { CultureInfo.CurrentCulture, CultureInfo.GetCultureInfo("is-IS"), CultureInfo.GetCultureInfo("en-US"), CultureInfo.InvariantCulture };
        foreach (var culture in cultures)
        {
            if (double.TryParse(cleaned, NumberStyles.Float, culture, out value)) return true;
        }
        if (cleaned.Contains(',') && !cleaned.Contains('.') && double.TryParse(cleaned.Replace(',', '.'), NumberStyles.Float, CultureInfo.InvariantCulture, out value)) return true;
        return false;
    }

}
public sealed class TensileSampleValueBrushConverter : IValueConverter
{
    private static readonly Brush TransparentBrush = Brushes.Transparent;
    private static readonly Brush YellowBrush = new SolidColorBrush(Color.FromRgb(255, 255, 0));
    private static readonly Brush Green10Brush = new SolidColorBrush(Color.FromRgb(226, 239, 218));
    private static readonly Brush Green20Brush = new SolidColorBrush(Color.FromRgb(198, 239, 206));
    private static readonly Brush Green50Brush = new SolidColorBrush(Color.FromRgb(169, 208, 142));
    private static readonly Brush Green100Brush = new SolidColorBrush(Color.FromRgb(146, 208, 80));
    private static readonly Brush Green200Brush = new SolidColorBrush(Color.FromRgb(112, 173, 71));
    private static readonly Brush Green505Brush = new SolidColorBrush(Color.FromRgb(84, 130, 53));
    private static readonly Brush RedBrush = new SolidColorBrush(Color.FromRgb(255, 0, 0));

    static TensileSampleValueBrushConverter()
    {
        foreach (var brush in new[] { TransparentBrush, YellowBrush, Green10Brush, Green20Brush, Green50Brush, Green100Brush, Green200Brush, Green505Brush, RedBrush })
        {
            if (brush.CanFreeze) brush.Freeze();
        }
    }

    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
    {
        var text = value?.ToString();
        if (string.IsNullOrWhiteSpace(text)) return TransparentBrush;
        if (!TryParseSampleValue(text, culture, out var number))
        {
            return TransparentBrush;
        }

        if (number >= 505) return RedBrush;
        if (number >= 200) return Green505Brush;
        if (number >= 100) return Green200Brush;
        if (number >= 50) return Green100Brush;
        if (number >= 20) return Green50Brush;
        if (number >= 10) return Green10Brush;
        if (number >= 1) return YellowBrush;
        return TransparentBrush;
    }

    private static bool TryParseSampleValue(string text, CultureInfo culture, out double number)
    {
        number = 0;
        var cleaned = text.Replace("%", "", StringComparison.OrdinalIgnoreCase).Replace("MPa", "", StringComparison.OrdinalIgnoreCase).Trim();
        if (string.IsNullOrWhiteSpace(cleaned)) return false;

        cleaned = cleaned.Replace(" ", "").Replace("\u00A0", "");

        // Measurement entry values use commas as decimal separators in Icelandic/Excel exports.
        // Do not parse with NumberStyles.Any first, because InvariantCulture treats comma as a thousands separator
        // and turns values like "5,5" into 55 or "1,00" into 100, which breaks the color bands.
        if (cleaned.Contains(',') && !cleaned.Contains('.'))
        {
            return double.TryParse(cleaned.Replace(',', '.'), NumberStyles.Float, CultureInfo.InvariantCulture, out number);
        }

        if (cleaned.Contains(',') && cleaned.Contains('.'))
        {
            var lastComma = cleaned.LastIndexOf(',');
            var lastDot = cleaned.LastIndexOf('.');
            if (lastComma > lastDot)
            {
                cleaned = cleaned.Replace(".", "").Replace(',', '.');
            }
            else
            {
                cleaned = cleaned.Replace(",", "");
            }
            return double.TryParse(cleaned, NumberStyles.Float, CultureInfo.InvariantCulture, out number);
        }

        return double.TryParse(cleaned, NumberStyles.Float, CultureInfo.InvariantCulture, out number) ||
               double.TryParse(cleaned, NumberStyles.Float, culture, out number);
    }

    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture) => Binding.DoNothing;
}

public sealed class ImpactSampleValueBrushConverter : IValueConverter
{
    private static readonly Brush TransparentBrush = Brushes.Transparent;
    private static readonly Brush YellowBrush = new SolidColorBrush(Color.FromRgb(255, 255, 0));
    private static readonly Brush Green10Brush = new SolidColorBrush(Color.FromRgb(226, 239, 218));
    private static readonly Brush Green20Brush = new SolidColorBrush(Color.FromRgb(198, 239, 206));
    private static readonly Brush Green30Brush = new SolidColorBrush(Color.FromRgb(169, 208, 142));
    private static readonly Brush Green40Brush = new SolidColorBrush(Color.FromRgb(146, 208, 80));
    private static readonly Brush Green50Brush = new SolidColorBrush(Color.FromRgb(112, 173, 71));
    private static readonly Brush Green60Brush = new SolidColorBrush(Color.FromRgb(84, 130, 53));
    private static readonly Brush RedBrush = new SolidColorBrush(Color.FromRgb(255, 0, 0));

    static ImpactSampleValueBrushConverter()
    {
        foreach (var brush in new[] { TransparentBrush, YellowBrush, Green10Brush, Green20Brush, Green30Brush, Green40Brush, Green50Brush, Green60Brush, RedBrush })
        {
            if (brush.CanFreeze) brush.Freeze();
        }
    }

    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
    {
        var text = value?.ToString();
        if (string.IsNullOrWhiteSpace(text)) return TransparentBrush;
        if (!TryParseSampleValue(text, culture, out var number))
        {
            return TransparentBrush;
        }

        if (number >= 101) return RedBrush;
        if (number >= 60) return Green60Brush;
        if (number >= 50) return Green50Brush;
        if (number >= 40) return Green40Brush;
        if (number >= 30) return Green30Brush;
        if (number >= 20) return Green20Brush;
        if (number >= 10) return Green10Brush;
        if (number >= 1) return YellowBrush;
        return TransparentBrush;
    }

    private static bool TryParseSampleValue(string text, CultureInfo culture, out double number)
    {
        number = 0;
        var cleaned = text.Replace("%", "", StringComparison.OrdinalIgnoreCase).Trim();
        if (string.IsNullOrWhiteSpace(cleaned)) return false;

        cleaned = cleaned.Replace(" ", "").Replace("\u00A0", "");

        // Impact values are percentages and may come from Excel with decimal comma formatting.
        // Parse comma as a decimal separator before trying invariant parsing so "5,5" stays 5.5, not 55.
        if (cleaned.Contains(',') && !cleaned.Contains('.'))
        {
            return double.TryParse(cleaned.Replace(',', '.'), NumberStyles.Float, CultureInfo.InvariantCulture, out number);
        }

        if (cleaned.Contains(',') && cleaned.Contains('.'))
        {
            var lastComma = cleaned.LastIndexOf(',');
            var lastDot = cleaned.LastIndexOf('.');
            if (lastComma > lastDot)
            {
                cleaned = cleaned.Replace(".", "").Replace(',', '.');
            }
            else
            {
                cleaned = cleaned.Replace(",", "");
            }
            return double.TryParse(cleaned, NumberStyles.Float, CultureInfo.InvariantCulture, out number);
        }

        return double.TryParse(cleaned, NumberStyles.Float, CultureInfo.InvariantCulture, out number) ||
               double.TryParse(cleaned, NumberStyles.Float, culture, out number);
    }

    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture) => Binding.DoNothing;
}
